//! Interactive native window host for the existing Vello renderer.
//! No WebView, DOM, pixel readback or perpetual animation loop. JSON-line
//! commands and input receipts are a host contract, not a full workspace UI.
use std::{fs, io::{self, BufRead, Read}, path::PathBuf, sync::{Arc, Mutex}};
use art_equation_p0_app_surface::native_gpu::NativeGpuRenderer;
use serde_json::{json, Value};
use art_equation_workspace_core::session::WorkspaceSession;
use winit::{application::ApplicationHandler, dpi::PhysicalSize, event::{ElementState, MouseButton, MouseScrollDelta, WindowEvent}, event_loop::{ActiveEventLoop, EventLoop}, window::{Window,WindowId}};

const MAX_MESSAGE:u64=16*1024*1024;
const MAX_PIXELS:u64=16_777_216;
fn emit(value:Value){println!("{value}")}
fn bounded_file(path:PathBuf)->Result<String,String>{let file=fs::File::open(path).map_err(|e|e.to_string())?;if file.metadata().map_err(|e|e.to_string())?.len()>MAX_MESSAGE{return Err("Host input exceeds 16 MiB".into())}let mut text=String::new();file.take(MAX_MESSAGE+1).read_to_string(&mut text).map_err(|e|e.to_string())?;if text.len() as u64>MAX_MESSAGE{return Err("Host input exceeds 16 MiB".into())}Ok(text)}
#[derive(Clone,Copy)]struct Camera{x:f64,y:f64,scale:f64}
impl Camera{fn value(&self)->Value{json!({"x":self.x,"y":self.y,"scale":self.scale})}fn from(v:&Value)->Result<Self,String>{let c=Self{x:v["x"].as_f64().ok_or("Missing camera x")?,y:v["y"].as_f64().ok_or("Missing camera y")?,scale:v["scale"].as_f64().ok_or("Missing camera scale")?};if ![c.x,c.y,c.scale].iter().all(|v|v.is_finite())||c.scale<0.02||c.scale>64.0{return Err("Invalid native camera".into())}Ok(c)}}
#[derive(Clone,Copy)]enum Wake{Updates,Close}
#[derive(Default)]struct Updates{frame:Option<Value>,camera:Option<Value>,queued:bool}
struct Surface{
 window:Arc<Window>,surface:wgpu::Surface<'static>,device:wgpu::Device,queue:wgpu::Queue,
 texture:wgpu::Texture,view:wgpu::TextureView,blitter:wgpu::util::TextureBlitter,
 renderer:NativeGpuRenderer,config:wgpu::SurfaceConfiguration,paused:bool,
}
fn target(device:&wgpu::Device,width:u32,height:u32)->(wgpu::Texture,wgpu::TextureView){let texture=device.create_texture(&wgpu::TextureDescriptor{label:Some("Native Vello retained output"),size:wgpu::Extent3d{width,height,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba8Unorm,usage:wgpu::TextureUsages::STORAGE_BINDING|wgpu::TextureUsages::TEXTURE_BINDING,view_formats:&[]});let view=texture.create_view(&Default::default());(texture,view)}
impl Surface{
 async fn new(loop_:&ActiveEventLoop,images:&[Value])->Result<Self,String>{
  let window=Arc::new(loop_.create_window(Window::default_attributes().with_title("Art Equation — native Vello canvas host (workspace migration)").with_visible(false).with_inner_size(PhysicalSize::new(640,390))).map_err(|e|e.to_string())?);window.set_ime_allowed(true);
  let mut descriptor=wgpu::InstanceDescriptor::new_without_display_handle();descriptor.backends=wgpu::Backends::VULKAN;
  let instance=wgpu::Instance::new(descriptor);let surface=instance.create_surface(window.clone()).map_err(|e|e.to_string())?;
  let adapter=instance.request_adapter(&wgpu::RequestAdapterOptions{compatible_surface:Some(&surface),power_preference:wgpu::PowerPreference::HighPerformance,..Default::default()}).await.map_err(|e|e.to_string())?;
  let (device,queue)=adapter.request_device(&wgpu::DeviceDescriptor::default()).await.map_err(|e|e.to_string())?;
  let size=window.inner_size();let config=surface.get_default_config(&adapter,size.width,size.height).ok_or("No native surface configuration")?;surface.configure(&device,&config);
  let (texture,view)=target(&device,config.width,config.height);let blitter=wgpu::util::TextureBlitter::new(&device,config.format);let mut renderer=NativeGpuRenderer::new(&device)?;register(&mut renderer,images)?;
  let info=adapter.get_info();emit(json!({"kind":"native.adapter","name":info.name,"backend":format!("{:?}",info.backend),"webview":false,"dom":false}));
  Ok(Self{window,surface,device,queue,texture,view,blitter,renderer,config,paused:false})
 }
 fn resize(&mut self,size:PhysicalSize<u32>)->Result<(),String>{
  self.paused=size.width==0||size.height==0;if self.paused{return Ok(())}
  if size.width>4096||size.height>4096||u64::from(size.width)*u64::from(size.height)>MAX_PIXELS{self.paused=true;return Err("Native surface exceeds bounded dimensions".into())}
  if size.width!=self.config.width||size.height!=self.config.height{self.config.width=size.width;self.config.height=size.height;self.surface.configure(&self.device,&self.config);(self.texture,self.view)=target(&self.device,size.width,size.height)}
  Ok(())
 }
 fn present(&mut self,scene:&str,camera:Camera)->Result<Value,String>{
  if self.paused{return Ok(json!({"paused":true}))}
  let dpr=self.window.scale_factor();let receipt=self.renderer.render_to_texture(&self.device,&self.queue,&self.view,self.config.width,self.config.height,scene,camera.scale*dpr,camera.x*dpr,camera.y*dpr)?;
  if receipt.gpu_allocation_failure_flags!=0||receipt.gpu_allocation_status!="checked"{return Err("Unchecked Vello GPU allocation".into())}
  let mut frame=None;
  for _ in 0..2{match self.surface.get_current_texture(){wgpu::CurrentSurfaceTexture::Success(value)|wgpu::CurrentSurfaceTexture::Suboptimal(value)=>{frame=Some(value);break},wgpu::CurrentSurfaceTexture::Outdated|wgpu::CurrentSurfaceTexture::Lost=>self.surface.configure(&self.device,&self.config),other=>return Err(format!("Native surface acquisition: {other:?}"))}}
  let frame=frame.ok_or("Native surface recovery exhausted")?;let view=frame.texture.create_view(&Default::default());let mut encoder=self.device.create_command_encoder(&Default::default());self.blitter.copy(&self.device,&mut encoder,&self.view,&view);self.queue.submit([encoder.finish()]);self.window.pre_present_notify();frame.present();self.window.set_visible(true);
  Ok(json!({"renderer":receipt,"camera":camera.value(),"width":self.config.width,"height":self.config.height,"dpr":dpr,"pixelReadbacks":0}))
 }
}
fn register(renderer:&mut NativeGpuRenderer,images:&[Value])->Result<(),String>{
 if images.len()>128{return Err("Native image count limit".into())}
 for image in images{let data=image["pixels"].as_array().ok_or("Invalid native image pixels")?;if data.len()>MAX_PIXELS as usize*4{return Err("Native image byte limit".into())}let pixels=data.iter().map(|v|v.as_u64().filter(|n|*n<=255).map(|n|n as u8).ok_or("Invalid image byte")).collect::<Result<Vec<_>,_>>()?;renderer.register_image(&image["reference"].to_string(),pixels)?}Ok(())
}
struct Host{scene:String,board:String,images:Vec<Value>,surface:Option<Surface>,mailbox:Arc<Mutex<Updates>>,camera:Camera,generation:u64,sequence:u64,command_sequence:u64,cursor:(f64,f64),pan:Option<(f64,f64)>}
impl Host{
 fn input(&mut self,event:Value){self.sequence+=1;emit(json!({"kind":"native.input","sequence":self.sequence,"boardId":self.board,"generation":self.generation,"event":event,"camera":self.camera.value()}))}
 fn redraw(&self){if let Some(s)=&self.surface{if !s.paused{s.window.request_redraw()}}}
 fn frame(&mut self,value:Value)->Result<(),String>{
  let generation=value["generation"].as_u64().ok_or("Missing frame generation")?;if generation<=self.generation{return Err("Obsolete native generation".into())}
  let board=value["boardId"].as_str().filter(|s|!s.is_empty()&&s.len()<=128).ok_or("Missing native board identity")?;
  let scene=value["scene"].as_str().ok_or("Missing native scene")?;if scene.len() as u64>MAX_MESSAGE{return Err("Native scene exceeds limit".into())}
  // Register only validated bounded sources before publishing this revision.
  if let Some(images)=value["images"].as_array(){register(&mut self.surface.as_mut().ok_or("Native host not initialized")?.renderer,images)?}
  let camera=if value.get("camera").is_some(){Camera::from(&value["camera"])?}else{self.camera};self.scene=scene.into();self.board=board.into();self.generation=generation;self.camera=camera;self.redraw();Ok(())
 }
}
impl ApplicationHandler<Wake> for Host{
 fn resumed(&mut self,loop_:&ActiveEventLoop){if self.surface.is_some(){return}match pollster::block_on(Surface::new(loop_,&self.images)){Ok(mut surface)=>{
  // A hidden Windows window does not reliably deliver RedrawRequested. Paint
  // once before revealing it, then use demand-driven native redraw events.
  match surface.present(&self.scene,self.camera){Ok(receipt)=>emit(json!({"kind":"native.present","boardId":self.board,"generation":self.generation,"receipt":receipt})),Err(error)=>{emit(json!({"kind":"native.error","error":error}));loop_.exit();return}}
  self.surface=Some(surface);self.images.clear()
 },Err(error)=>{emit(json!({"kind":"native.error","error":error}));loop_.exit()}}}
 fn user_event(&mut self,loop_:&ActiveEventLoop,event:Wake){if matches!(event,Wake::Close){loop_.exit();return}let updates={let mut value=self.mailbox.lock().unwrap();value.queued=false;std::mem::take(&mut *value)};
  if let Some(frame)=updates.frame{if let Err(error)=self.frame(frame){emit(json!({"kind":"native.error","error":error}))}}
  if let Some(value)=updates.camera{if value["generation"].as_u64()!=Some(self.generation)||value["sequence"].as_u64().is_none_or(|s|s<=self.command_sequence){emit(json!({"kind":"native.error","error":"Obsolete native camera command"}));return}match Camera::from(&value["camera"]){Ok(camera)=>{self.command_sequence=value["sequence"].as_u64().unwrap();self.camera=camera;self.redraw()},Err(error)=>emit(json!({"kind":"native.error","error":error}))}}
 }
 fn window_event(&mut self,loop_:&ActiveEventLoop,_:WindowId,event:WindowEvent){match event{
  WindowEvent::CloseRequested=>{self.input(json!({"type":"close"}));loop_.exit()},
  WindowEvent::RedrawRequested=>{if let Some(surface)=&mut self.surface{match surface.present(&self.scene,self.camera){Ok(receipt)=>emit(json!({"kind":"native.present","boardId":self.board,"generation":self.generation,"receipt":receipt})),Err(error)=>emit(json!({"kind":"native.error","generation":self.generation,"error":error}))}}},
  WindowEvent::Resized(size)=>{if let Some(surface)=&mut self.surface{if let Err(error)=surface.resize(size){emit(json!({"kind":"native.error","error":error}))}}self.input(json!({"type":"resize","width":size.width,"height":size.height}));self.redraw()},
  WindowEvent::ScaleFactorChanged{scale_factor,..}=>{self.input(json!({"type":"dpi","dpr":scale_factor}));self.redraw()},
  WindowEvent::CursorMoved{position,..}=>{let dpr=self.surface.as_ref().map(|s|s.window.scale_factor()).unwrap_or(1.);self.cursor=(position.x/dpr,position.y/dpr);if let Some(previous)=self.pan{self.camera.x+=self.cursor.0-previous.0;self.camera.y+=self.cursor.1-previous.1;self.pan=Some(self.cursor);self.redraw()}self.input(json!({"type":"pointer-move","x":(self.cursor.0-self.camera.x)/self.camera.scale,"y":(self.cursor.1-self.camera.y)/self.camera.scale}))},
  WindowEvent::MouseInput{state,button,..}=>{if button==MouseButton::Middle{self.pan=if state==ElementState::Pressed{Some(self.cursor)}else{None}}self.input(json!({"type":"pointer-button","button":format!("{button:?}"),"pressed":state==ElementState::Pressed,"x":(self.cursor.0-self.camera.x)/self.camera.scale,"y":(self.cursor.1-self.camera.y)/self.camera.scale}))},
  WindowEvent::MouseWheel{delta,..}=>{let amount=match delta{MouseScrollDelta::LineDelta(_,y)=>f64::from(y)*0.12,MouseScrollDelta::PixelDelta(p)=>p.y*0.001};let next=(self.camera.scale*amount.clamp(-2.,2.).exp()).clamp(0.02,64.);let ratio=next/self.camera.scale;self.camera.x=self.cursor.0-(self.cursor.0-self.camera.x)*ratio;self.camera.y=self.cursor.1-(self.cursor.1-self.camera.y)*ratio;self.camera.scale=next;self.input(json!({"type":"wheel"}));self.redraw()},
  WindowEvent::KeyboardInput{event,..}=>self.input(json!({"type":"key","key":format!("{:?}",event.logical_key),"pressed":event.state==ElementState::Pressed,"repeat":event.repeat})),
  WindowEvent::Ime(event)=>self.input(json!({"type":"ime","event":format!("{event:?}")})),
  WindowEvent::Focused(false)=>{self.pan=None;self.input(json!({"type":"focus","focused":false}))},_=>{}
 }}
}
fn main()->Result<(),String>{
 let arguments=std::env::args().collect::<Vec<_>>();
 let directory=PathBuf::from(arguments.get(1).ok_or("Initial fixture directory required")?);
 // The native window owns storage directly. No browser sidecar is needed to
 // load, commit, checkpoint, configure recovery or inspect canonical records.
 let workspace=match arguments.len(){
  2=>None,
  6 if arguments[2]=="--workspace"&&arguments[4]=="--project"=>Some(Arc::new(WorkspaceSession::open(&PathBuf::from(&arguments[3]),&arguments[5],true)?)),
  _=>return Err("Usage: live_host fixture [--workspace root --project id]".into()),
 };
 if let Some(session)=&workspace{emit(json!({"kind":"native.workspace","info":session.info()}))}
 let reader_workspace=workspace.as_ref().map(Arc::downgrade);
 let scene=bounded_file(directory.join("scene-paint.json"))?;let images=serde_json::from_str::<Vec<Value>>(&bounded_file(directory.join("image-uploads.json"))?).map_err(|e|e.to_string())?;
 let event_loop=EventLoop::<Wake>::with_user_event().build().map_err(|e|e.to_string())?;let proxy=event_loop.create_proxy();let mailbox=Arc::new(Mutex::new(Updates::default()));let reader_mailbox=mailbox.clone();
 std::thread::spawn(move||{let stdin=io::stdin();let mut reader=stdin.lock();loop{let mut line=Vec::new();match reader.by_ref().take(MAX_MESSAGE+1).read_until(b'\n',&mut line){Ok(0)=>{let _=proxy.send_event(Wake::Close);break},Ok(_)=>{},Err(_)=>break}if line.len() as u64>MAX_MESSAGE{emit(json!({"kind":"native.error","error":"Native message exceeds 16 MiB"}));let _=proxy.send_event(Wake::Close);break}
  let value=match serde_json::from_slice::<Value>(&line){Ok(value)=>value,Err(error)=>{emit(json!({"kind":"native.error","error":error.to_string()}));continue}};let kind=value["type"].as_str().unwrap_or("");if kind=="close"{let _=proxy.send_event(Wake::Close);break}
  if kind=="workspace"{
   let reply=(||{let session=reader_workspace.as_ref().and_then(|w|w.upgrade()).ok_or("No native workspace configured")?;let operation=value["operation"].as_str().ok_or("Missing storage operation")?;session.execute(operation,value.get("value").cloned().unwrap_or(json!({})))})();
   match reply{Ok(data)=>emit(json!({"kind":"native.workspace.reply","requestId":value["requestId"],"ok":true,"data":data})),Err(error)=>emit(json!({"kind":"native.workspace.reply","requestId":value["requestId"],"ok":false,"error":error}))}
   continue
  }
  if kind!="frame"&&kind!="camera"{emit(json!({"kind":"native.error","error":"Unsupported native host command"}));continue}
  let mut updates=reader_mailbox.lock().unwrap();if kind=="frame"{updates.frame=Some(value)}else{updates.camera=Some(value)}if !updates.queued{updates.queued=true;if proxy.send_event(Wake::Updates).is_err(){break}}
 }});
 let mut host=Host{scene,board:"initial-fixture".into(),images,surface:None,mailbox,camera:Camera{x:0.,y:0.,scale:1.},generation:0,sequence:0,command_sequence:0,cursor:(0.,0.),pan:None};event_loop.run_app(&mut host).map_err(|e|e.to_string())
}

//! Small native-window correctness probe. Uses the existing Vello adapter and
//! the identical validated display-list fixture; this is not a new renderer.
use std::{fs, path::PathBuf, sync::Arc, time::Duration};
use art_equation_p0_app_surface::native_gpu::NativeGpuRenderer;
use serde_json::{Value, json};
use winit::{application::ApplicationHandler, event::WindowEvent, event_loop::{ActiveEventLoop, EventLoop}, window::{Window, WindowId}};

struct SurfaceState {
    window: Arc<Window>, surface: wgpu::Surface<'static>, device: wgpu::Device,
    queue: wgpu::Queue, texture: wgpu::Texture, view: wgpu::TextureView,
    blitter: wgpu::util::TextureBlitter, renderer: NativeGpuRenderer,
    config: wgpu::SurfaceConfiguration, adapter: Value,
}
struct Probe { directory: PathBuf, scene: String, state: Option<SurfaceState>, receipts: Vec<Value>, failure: Option<String> }
impl Probe {
    async fn initialize(&self, event_loop: &ActiveEventLoop) -> Result<SurfaceState,String> {
        let window=Arc::new(event_loop.create_window(Window::default_attributes().with_title("Art Equation — native wgpu correctness probe").with_inner_size(winit::dpi::PhysicalSize::new(640,390))).map_err(|e|e.to_string())?);
        let mut descriptor=wgpu::InstanceDescriptor::new_without_display_handle();descriptor.backends=wgpu::Backends::VULKAN;
        let instance=wgpu::Instance::new(descriptor);
        let surface=instance.create_surface(window.clone()).map_err(|e|e.to_string())?;
        let adapter=instance.request_adapter(&wgpu::RequestAdapterOptions{compatible_surface:Some(&surface),power_preference:wgpu::PowerPreference::HighPerformance,..Default::default()}).await.map_err(|e|e.to_string())?;
        let info=adapter.get_info();let identity=json!({"name":info.name,"backend":format!("{:?}",info.backend),"deviceType":format!("{:?}",info.device_type)});
        let (device,queue)=adapter.request_device(&wgpu::DeviceDescriptor::default()).await.map_err(|e|e.to_string())?;
        let config=surface.get_default_config(&adapter,640,390).ok_or("No compatible window surface")?;surface.configure(&device,&config);
        let texture=device.create_texture(&wgpu::TextureDescriptor{label:Some("Same Vello canvas output"),size:wgpu::Extent3d{width:640,height:390,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba8Unorm,usage:wgpu::TextureUsages::STORAGE_BINDING|wgpu::TextureUsages::TEXTURE_BINDING|wgpu::TextureUsages::COPY_SRC,view_formats:&[]});
        let view=texture.create_view(&Default::default());let blitter=wgpu::util::TextureBlitter::new(&device,config.format);let mut renderer=NativeGpuRenderer::new(&device)?;
        let uploads:Vec<Value>=serde_json::from_str(&fs::read_to_string(self.directory.join("image-uploads.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;
        for upload in uploads {let pixels=upload["pixels"].as_array().ok_or("Invalid upload")?.iter().map(|p|p.as_u64().filter(|v|*v<=255).map(|v|v as u8).ok_or("Invalid pixel")).collect::<Result<Vec<_>,_>>()?;renderer.register_image(&upload["reference"].to_string(),pixels)?;}
        Ok(SurfaceState{window,surface,device,queue,texture,view,blitter,renderer,config,adapter:identity})
    }
    fn frame(&mut self)->Result<(),String>{
        let s=self.state.as_mut().ok_or("No surface")?;let step=self.receipts.len();let (scale,x,y)=match step{0=>(1.,0.,0.),1=>(1.,18.,12.),_=>(0.9,0.,0.)};
        let receipt=s.renderer.render_to_texture(&s.device,&s.queue,&s.view,640,390,&self.scene,scale,x,y)?;
        if receipt.gpu_allocation_failure_flags!=0||receipt.gpu_allocation_status!="checked"{return Err("Unchecked GPU allocation".into())}
        let frame=match s.surface.get_current_texture(){wgpu::CurrentSurfaceTexture::Success(frame)|wgpu::CurrentSurfaceTexture::Suboptimal(frame)=>frame,other=>return Err(format!("Native surface acquisition: {other:?}"))};let target=frame.texture.create_view(&Default::default());let mut encoder=s.device.create_command_encoder(&Default::default());s.blitter.copy(&s.device,&mut encoder,&s.view,&target);s.queue.submit([encoder.finish()]);frame.present();
        let mut row=serde_json::to_value(receipt).map_err(|e|e.to_string())?;row["camera"]=json!({"scale":scale,"x":x,"y":y});
        if step==0 {
            // One bounded verification readback. The presentation path above
            // has no readback; this is solely a test pixel oracle.
            let buffer=s.device.create_buffer(&wgpu::BufferDescriptor{label:Some("Probe pixel verification only"),size:640*390*4,usage:wgpu::BufferUsages::COPY_DST|wgpu::BufferUsages::MAP_READ,mapped_at_creation:false});
            let mut encoder=s.device.create_command_encoder(&Default::default());encoder.copy_texture_to_buffer(wgpu::TexelCopyTextureInfo{texture:&s.texture,mip_level:0,origin:wgpu::Origin3d::ZERO,aspect:wgpu::TextureAspect::All},wgpu::TexelCopyBufferInfo{buffer:&buffer,layout:wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(640*4),rows_per_image:Some(390)}},wgpu::Extent3d{width:640,height:390,depth_or_array_layers:1});
            let submitted=s.queue.submit([encoder.finish()]);let (tx,rx)=std::sync::mpsc::channel();buffer.slice(..).map_async(wgpu::MapMode::Read,move|r|{let _=tx.send(r);});s.device.poll(wgpu::PollType::Wait{submission_index:Some(submitted),timeout:Some(Duration::from_secs(15))}).map_err(|e|e.to_string())?;rx.recv_timeout(Duration::from_secs(15)).map_err(|e|e.to_string())?.map_err(|e|e.to_string())?;
            let bytes=buffer.slice(..).get_mapped_range();let left=&bytes[(210*640+60)*4..(210*640+60)*4+4];let right=&bytes[(210*640+240)*4..(210*640+240)*4+4];row["pixels"]=json!({"left":left,"right":right});if left!=[55,213,181,255]||right!=[255,210,105,255]{return Err("Native GPU image pixels differ".into())}fs::write(self.directory.join("native-gpu.rgba"),&bytes).map_err(|e|e.to_string())?;drop(bytes);buffer.unmap();
        }
        self.receipts.push(row);Ok(())
    }
    fn save(&self){let report=json!({"scope":"640x390 native wgpu/Vello window; same authored glyph/image/graph display list, three camera frames. No browser or DOM. Not product integration, app latency or 4K acceptance.","passed":self.failure.is_none()&&self.receipts.len()==3,"failure":self.failure,"adapter":self.state.as_ref().map(|s|&s.adapter),"surfaceFormat":self.state.as_ref().map(|s|format!("{:?}",s.config.format)),"receipts":self.receipts});let _=fs::write(self.directory.join("native-report.json"),serde_json::to_vec_pretty(&report).unwrap());}
}
impl ApplicationHandler for Probe {
    fn resumed(&mut self,event_loop:&ActiveEventLoop){if self.state.is_some(){return}match pollster::block_on(self.initialize(event_loop)){Ok(state)=>{state.window.request_redraw();self.state=Some(state)},Err(e)=>{self.failure=Some(e);self.save();event_loop.exit()}}}
    fn window_event(&mut self,event_loop:&ActiveEventLoop,_:WindowId,event:WindowEvent){match event{WindowEvent::RedrawRequested=>{if let Err(e)=self.frame(){self.failure=Some(e);self.save();event_loop.exit();return}if self.receipts.len()==3{self.save();event_loop.exit()}else{self.state.as_ref().unwrap().window.request_redraw()}},WindowEvent::CloseRequested=>{self.failure=Some("Probe closed before verification".into());self.save();event_loop.exit()},_=>{}}}
}
fn main(){let directory=PathBuf::from(std::env::args().nth(1).expect("Fixture directory required"));let scene=fs::read_to_string(directory.join("scene-paint.json")).expect("Validated fixture required");let mut app=Probe{directory,scene,state:None,receipts:vec![],failure:None};EventLoop::new().unwrap().run_app(&mut app).unwrap();if app.failure.is_some(){std::process::exit(1)}}

//! Actual Vello CPU fallback consuming the shared validated prepared scene.
//! GPU pixels are never requested; output is straight RGBA for ImageData.

#[cfg(test)]
use crate::prepared_scene::MAX_PATH_COMMANDS;
use crate::prepared_scene::{PreparedOp, prepare_snapshot, validate_camera};
use crate::image_resources::{ImageRegistry, ImageReference, parse_reference, parse_references_json};
use std::{collections::HashMap, sync::Arc};
#[cfg(test)]
use serde_json::Value;
use vello_cpu::{
    Level, Pixmap, RasterizerSettings, RenderContext, RenderMode, RenderSettings, Resources, ImageSource,
    kurbo::{Affine, Rect, Shape},
    peniko::{Fill, ImageBrush, ImageSampler},
};

/// Worker-local persistent decoded resources. Raw canonical bytes and CPU
/// pixmaps are both counted; neither is inferred from GPU readback.
#[cfg_attr(target_arch="wasm32", wasm_bindgen::prelude::wasm_bindgen)]
pub struct B4CpuRenderer {
    registry: ImageRegistry,
    images: HashMap<(String,u64), Arc<Pixmap>>,
    surface: Option<CpuSurface>,
    additional_threads: u16,
    surface_allocations: usize,
    surface_resizes: usize,
    disposed: bool,
}

/// The context and its resources have the same lifetime. Reset command/state
/// buffers between frames; retain the raster buffer at the current resolution.
struct CpuSurface {
    context: RenderContext,
    pixmap: Pixmap,
    resources: Resources,
    output_buffer: Vec<u8>,
}

impl Default for B4CpuRenderer {
    fn default()->Self { Self {registry:ImageRegistry::default(),images:HashMap::new(),surface:None,
        additional_threads:0,surface_allocations:0,surface_resizes:0,disposed:false} }
}

impl B4CpuRenderer {
    #[cfg(all(not(target_arch="wasm32"), feature="native-cpu-parallel"))]
    pub fn with_additional_threads(threads: u16) -> Result<Self, String> {
        if threads > 4 { return Err("CPU_THREAD_LIMIT: use 0 to 4 additional threads".into()); }
        Ok(Self {additional_threads:threads,..Self::default()})
    }
    pub fn register(&mut self, reference: ImageReference, pixels: Vec<u8>) -> Result<String,String> {
        if self.disposed {return Err("CPU_RENDERER_DISPOSED".into());}
        self.registry.register(reference, pixels)?;
        Ok(self.stats().to_string())
    }
    fn prune_pixmaps(&mut self) { self.images.retain(|key,_|self.registry.contains(key)); }
    pub fn stats(&self)->serde_json::Value {
        let pixmap_bytes:usize=self.images.values().map(|p|usize::from(p.width())*usize::from(p.height())*4).sum();
        serde_json::json!({"decoded":self.registry.stats(),"cpuPixmapBytes":pixmap_bytes,"cpuPixmapCount":self.images.len(),
            "cpuSurfaceAllocations":self.surface_allocations,"cpuSurfaceResizes":self.surface_resizes,
            "cpuAdditionalThreads":self.additional_threads,
            "cpuSurfaceBytes":self.surface.as_ref().map_or(0,|s|s.pixmap.capacity()*4)})
    }
    pub fn render(&mut self,width:u32,height:u32,snapshot_json:&str,scale:f64,pan_x:f64,pan_y:f64)->Result<Vec<u8>,String> {
        if self.disposed {return Err("CPU_RENDERER_DISPOSED".into());}
        // A completed worker render holds resources until the next requested
        // complete frame. Visible CPU pixels are an independent copied surface.
        let result=self.render_inner(width,height,snapshot_json,scale,pan_x,pan_y);
        if result.is_ok() {self.registry.present();} else {self.registry.discard();}
        self.prune_pixmaps();
        result
    }

    fn render_inner(&mut self,width:u32,height:u32,snapshot_json:&str,scale:f64,pan_x:f64,pan_y:f64)->Result<Vec<u8>,String> {
        if width>4096 || height>4096 {return Err("CPU frame dimensions exceed the 4096-pixel proof limit".into());}
        super::validate_frame(width,height,4096,scale,pan_x,pan_y)?;
        let snapshot=super::parse_snapshot(snapshot_json)?;
        let prepared=prepare_snapshot(&snapshot)?;
        let camera=Affine::translate((pan_x,pan_y))*Affine::scale(scale);
        validate_camera(&prepared,camera)?;
        self.registry.stage(&prepared.resources)?;
        // Resolve every image and allocate persistent pixmaps before output.
        for reference in &prepared.resources {
            let key=(reference.key.clone(),reference.revision);
            if !self.images.contains_key(&key) {
                let image=self.registry.resolve(reference)?;
                let mut pixmap=Pixmap::new(reference.width as u16,reference.height as u16);
                pixmap.data_as_u8_slice_mut().copy_from_slice(&image.pixels);
                self.images.insert(key,Arc::new(pixmap));
            }
        }
        if let Some(surface) = &mut self.surface {
            if u32::from(surface.pixmap.width()) != width || u32::from(surface.pixmap.height()) != height {
                surface.context.reset_and_resize(width as u16, height as u16);
                // Bound retained capacity to the largest admitted frame rather
                // than Vec's geometric growth beyond the requested allocation.
                if width as usize * height as usize > surface.pixmap.capacity() {
                    surface.pixmap = Pixmap::new(width as u16,height as u16);
                } else { surface.pixmap.resize(width as u16, height as u16); }
                self.surface_resizes += 1;
            } else {
                surface.context.reset();
            }
        } else {
            self.surface = Some(CpuSurface {
                context:RenderContext::new_with(width as u16,height as u16,RenderSettings {
                    level:Level::new(), num_threads:self.additional_threads,
                }),
                pixmap:Pixmap::new(width as u16,height as u16),resources:Resources::new(),
                output_buffer:Vec::with_capacity(width as usize * height as usize * 4),
            });
            self.surface_allocations += 1;
        }
        rasterize(width,height,&prepared,camera,&self.images,self.surface.as_mut().unwrap())
    }
}

#[cfg_attr(target_arch="wasm32", wasm_bindgen::prelude::wasm_bindgen)]
impl B4CpuRenderer {
    #[cfg_attr(target_arch="wasm32", wasm_bindgen::prelude::wasm_bindgen(constructor))]
    pub fn new()->Self {Self::default()}
    pub fn register_image(&mut self,reference_json:String,pixels:Vec<u8>)->Result<String,crate::EngineError> {
        let value=serde_json::from_str(&reference_json).map_err(|_|crate::engine_error("RESOURCE_INVALID: image JSON"))?;
        let reference=parse_reference(&value).map_err(crate::engine_error)?;
        self.register(reference,pixels).map_err(crate::engine_error)
    }
    pub fn retain_images(&mut self,references_json:String)->Result<String,crate::EngineError> {
        if self.disposed {return Err(crate::engine_error("CPU_RENDERER_DISPOSED"));}
        let references=parse_references_json(&references_json).map_err(crate::engine_error)?;
        self.registry.retain_candidates(&references);self.prune_pixmaps();
        Ok(self.stats().to_string())
    }
    pub fn resource_stats(&self)->String {self.stats().to_string()}
    pub fn render_snapshot(&mut self,width:u32,height:u32,snapshot_json:String,scale:f64,pan_x:f64,pan_y:f64)->Result<Vec<u8>,crate::EngineError> {
        self.render(width,height,&snapshot_json,scale,pan_x,pan_y).map_err(crate::engine_error)
    }
    /// Zero-copy Wasm rendering entry point: rasterizes into `surface.output_buffer`
    /// and returns byte length so JS can construct a typed view via `surface_buffer_ptr()`.
    pub fn render_into_surface(&mut self,width:u32,height:u32,snapshot_json:String,scale:f64,pan_x:f64,pan_y:f64)->Result<usize,crate::EngineError> {
        if self.disposed {return Err(crate::engine_error("CPU_RENDERER_DISPOSED"));}
        let result = self.render_inner(width,height,&snapshot_json,scale,pan_x,pan_y);
        if result.is_ok() {self.registry.present();} else {self.registry.discard();}
        self.prune_pixmaps();
        result.map(|bytes| bytes.len()).map_err(crate::engine_error)
    }
    pub fn surface_buffer_ptr(&self) -> *const u8 {
        self.surface.as_ref().map_or(std::ptr::null(), |s| s.output_buffer.as_ptr())
    }
    pub fn surface_buffer_len(&self) -> usize {
        self.surface.as_ref().map_or(0, |s| s.output_buffer.len())
    }
    pub fn dispose(&mut self) {self.registry=ImageRegistry::default();self.images.clear();self.surface=None;self.disposed=true;}
}

pub fn render_cpu_snapshot(
    width: u32,
    height: u32,
    snapshot_json: &str,
    scale: f64,
    pan_x: f64,
    pan_y: f64,
) -> Result<Vec<u8>, String> {
    B4CpuRenderer::new().render(width,height,snapshot_json,scale,pan_x,pan_y)
}

fn rasterize(width:u32,height:u32,prepared:&crate::prepared_scene::PreparedScene,camera:Affine,
    images:&HashMap<(String,u64),Arc<Pixmap>>,surface:&mut CpuSurface)->Result<Vec<u8>,String> {
    // Complete validation/preparation precedes all output surface allocation.
    let context = &mut surface.context;
    context.set_paint(prepared.background);
    context.fill_rect(&Rect::new(0.0, 0.0, f64::from(width), f64::from(height)));
    for operation in &prepared.operations {
        let object = match operation {
            PreparedOp::Vector(index) => &prepared.vectors[*index],
            PreparedOp::Image(index) => {
                let image=&prepared.images[*index];
                let pixmap=images.get(&(image.resource.key.clone(),image.resource.revision))
                    .ok_or("RESOURCE_NOT_READY: CPU pixmap missing")?;
                context.set_transform(camera*image.transform);
                context.reset_paint_transform();
                context.set_fill_rule(Fill::NonZero);
                // vello_common 0.2 explicitly panics for ImageSampler.alpha
                // other than one. Apply opacity through the supported layer
                // compositing path shared with vector primitives instead.
                if image.opacity < 1.0 { context.push_opacity_layer(image.opacity); }
                context.set_paint(ImageBrush{image:ImageSource::Pixmap(pixmap.clone()),
                    sampler:ImageSampler::new().with_quality(image.quality)});
                context.fill_rect(&image.source);
                if image.opacity < 1.0 { context.pop_layer(); }
                continue;
            }
            PreparedOp::Gradient(paint) => {
                context.set_transform(camera*paint.transform);
                context.set_paint_transform(paint.brush_transform);
                context.set_fill_rule(paint.fill_rule);
                context.set_paint(paint.gradient.clone());
                context.fill_path(&paint.path);
                context.reset_paint_transform();
                continue;
            }
            PreparedOp::Shadow(paint) => {
                context.set_transform(camera*paint.transform);
                context.reset_paint_transform();
                context.set_fill_rule(Fill::NonZero);
                context.set_paint(paint.color);
                if paint.std_dev==0.0 {
                    context.fill_path(&paint.rect.to_rounded_rect(paint.radius).to_path(0.05));
                } else {
                    context.fill_blurred_rounded_rect(&paint.rect,paint.radius as f32,paint.std_dev as f32,false);
                }
                continue;
            }
            PreparedOp::Scope(scope) => {
                context.set_transform(camera * scope.transform);
                context.set_fill_rule(scope.fill_rule);
                context.push_layer(
                    Some(&scope.path),
                    Some(scope.blend),
                    Some(scope.opacity),
                    None,
                    None,
                );
                continue;
            }
            PreparedOp::Pop => {
                context.pop_layer();
                continue;
            }
        };
        context.set_transform(camera * object.transform);
        context.reset_paint_transform();
        if object.opacity < 1.0 {
            context.push_opacity_layer(object.opacity);
        }
        context.set_fill_rule(object.fill_rule);
        context.set_paint(object.fill);
        context.fill_path(&object.path);
        if let Some(path) = &object.stroke_path {
            context.set_stroke(object.stroke.clone());
            context.set_paint(object.stroke_color);
            context.stroke_path(path);
        }
        if object.opacity < 1.0 {
            context.pop_layer();
        }
    }
    context.flush();
    context.render_with(
        &mut surface.pixmap,
        &mut surface.resources,
        RasterizerSettings {
            render_mode: RenderMode::OptimizeSpeed,
            ..Default::default()
        },
    );
    let byte_len = width as usize * height as usize * 4;
    surface.output_buffer.clear();
    if surface.output_buffer.capacity() < byte_len {
        surface.output_buffer.reserve(byte_len - surface.output_buffer.capacity());
    }
    // Preserve vello_common's rounding into the retained output_buffer so
    // zero-copy callers read `surface_buffer_ptr()` directly without reallocation.
    for pixel in surface.pixmap.data() {
        if pixel.a == 0 { surface.output_buffer.extend_from_slice(&[0;4]); } else {
            let alpha = 255.0 / f32::from(pixel.a);
            let unpremultiply = |component| (f32::from(component) * alpha + 0.5) as u8;
            surface.output_buffer.extend_from_slice(&[unpremultiply(pixel.r),unpremultiply(pixel.g),unpremultiply(pixel.b),pixel.a]);
        }
    }
    Ok(surface.output_buffer.clone())
}
