/// A frame can be presented only after a successful preparation. Starting another
/// preparation or discarding invalidates the old frame, and commit consumes it.
struct PreparedGate<T> {
    ready: Option<T>,
}

impl<T> Default for PreparedGate<T> {
    fn default() -> Self {
        Self { ready: None }
    }
}

impl<T> PreparedGate<T> {
    fn discard(&mut self) {
        self.ready = None;
    }
    fn stage(&mut self, frame: T) {
        self.ready = Some(frame);
    }
    fn take_for_present(&mut self) -> Result<T, &'static str> {
        self.ready
            .take()
            .ok_or("NO_PREPARED_FRAME: prepare a frame before presenting")
    }
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen::prelude::wasm_bindgen]
pub fn render_cpu_snapshot(
    width: u32,
    height: u32,
    snapshot_json: String,
    scale: f64,
    pan_x: f64,
    pan_y: f64,
) -> Result<Vec<u8>, wasm_bindgen::JsValue> {
    cpu::render_cpu_snapshot(width, height, &snapshot_json, scale, pan_x, pan_y)
        .map_err(|error| wasm_bindgen::JsValue::from_str(&error))
}

#[derive(Debug, PartialEq)]
struct FrameInput {
    width: u32,
    height: u32,
    scale: f64,
    pan_x: f64,
    pan_y: f64,
}

fn validate_frame(
    width: u32,
    height: u32,
    device_max_dimension: u32,
    scale: f64,
    pan_x: f64,
    pan_y: f64,
) -> Result<FrameInput, String> {
    if width == 0 || height == 0 || device_max_dimension == 0 {
        return Err("Frame dimensions must be nonzero".into());
    }
    if !scale.is_finite() || scale <= 0.0 || scale > 1_000_000.0 {
        return Err("Viewport scale must be finite, positive and at most 1000000".into());
    }
    if !pan_x.is_finite() || !pan_y.is_finite() || pan_x.abs() > 1e9 || pan_y.abs() > 1e9 {
        return Err("Viewport pan must be finite and within +/-1000000000".into());
    }
    let maximum = device_max_dimension.min(PROOF_MAX_DIMENSION);
    Ok(FrameInput {
        width: width.min(maximum),
        height: height.min(maximum),
        scale,
        pan_x,
        pan_y,
    })
}

fn validate_numbers(value: &Value) -> Result<(), String> {
    match value {
        Value::Number(number) => {
            let value = number
                .as_f64()
                .ok_or("Snapshot number is outside f64 range")?;
            if !value.is_finite() || value.abs() > 1e12 {
                return Err(
                    "Snapshot numeric magnitude exceeds the proof's finite 1e12 limit".into(),
                );
            }
        }
        Value::Array(values) => {
            for value in values {
                validate_numbers(value)?;
            }
        }
        Value::Object(values) => {
            for value in values.values() {
                validate_numbers(value)?;
            }
        }
        _ => {}
    }
    Ok(())
}

/// This slice consumes flat path commands plus one canonical affine matrix.
/// It cannot infer an inherited group transform, clipping or live Boolean from
/// production BoardNode metadata. Reject those meanings rather than painting a
/// successful but geometrically different rectangle/path.
fn validate_flat_vector_metadata(object: &Value) -> Result<(), String> {
    prepared_scene::object_transform(object)?;
    for key in [
        "parentId",
        "clipId",
        "groupId",
        "vectorTransform",
        "vectorBoolean",
        "clip",
        "clipPath",
        "clipStack",
        "mask",
        "filter",
    ] {
        if !object[key].is_null() {
            return Err(format!(
                "SCENE_UNSUPPORTED: object.{key} requires a later full-scene engine slice"
            ));
        }
    }
    let payload = &object["payload"];
    for key in [
        "vectorTransform",
        "vectorBoolean",
        "vectorPath",
        "resolvedPaths",
        "clip",
        "clipPath",
        "clips",
        "clipStack",
        "mask",
        "filter",
        "shadow",
        "diagramCaption",
    ] {
        if !payload[key].is_null() {
            return Err(format!(
                "SCENE_UNSUPPORTED: payload.{key} must be encoded into supported flat commands/matrix before rendering"
            ));
        }
    }
    if !payload["clipChildren"].is_null() && payload["clipChildren"] != false {
        return Err(
            "SCENE_UNSUPPORTED: active clipChildren requires the full-scene clip hierarchy".into(),
        );
    }
    if !payload["fillOpacity"].is_null() && payload["fillOpacity"].as_f64() != Some(1.0) {
        return Err(
            "SCENE_UNSUPPORTED: separate fillOpacity requires a later matched CPU/GPU paint slice"
                .into(),
        );
    }
    if !payload["cornerRadius"].is_null() && payload["cornerRadius"].as_f64() != Some(0.0) {
        return Err(
            "SCENE_UNSUPPORTED: cornerRadius must be encoded into path commands before rendering"
                .into(),
        );
    }
    if payload["commands"].is_null() {
        if let Some(shape) = payload["shapeType"].as_str() {
            if shape != "rect" && shape != "rectangle" {
                return Err(format!(
                    "SCENE_UNSUPPORTED: {shape} requires explicit path commands; bounds fallback only supports rectangles"
                ));
            }
        }
    }
    Ok(())
}

fn parse_snapshot(source: &str) -> Result<Value, String> {
    if source.len() > MAX_SNAPSHOT_BYTES {
        return Err("Snapshot exceeds the 16 MiB proof limit".into());
    }
    let snapshot: Value =
        serde_json::from_str(source).map_err(|error| format!("Invalid snapshot JSON: {error}"))?;
    if snapshot["schema"] == "art-equation.display-list" {
        validate_numbers(&snapshot)?;
        return Ok(snapshot);
    }
    if snapshot["schema"] != "art-equation.scene" || snapshot["schemaVersion"] != 1 {
        return Err("Expected art-equation.scene schemaVersion 1".into());
    }
    let objects = snapshot["objects"]
        .as_array()
        .ok_or("Snapshot objects must be an array")?;
    if objects.len() > MAX_OBJECTS {
        return Err("Snapshot exceeds the 50000-object proof limit".into());
    }
    if snapshot["connections"]
        .as_array()
        .is_some_and(|connections| !connections.is_empty())
    {
        return Err(
            "SCENE_UNSUPPORTED: connection encoding requires a later matched CPU/GPU slice".into(),
        );
    }
    for object in objects {
        if object["visible"] != false && object["hidden"] != true && object["kind"] != "vector" {
            return Err(format!(
                "SCENE_UNSUPPORTED: visible {} object {} requires a later full-scene engine slice",
                object["kind"].as_str().unwrap_or("unknown"),
                object["id"].as_str().unwrap_or("unknown")
            ));
        }
        if object["blendMode"]
            .as_str()
            .is_some_and(|mode| mode != "normal")
        {
            return Err("SCENE_UNSUPPORTED: blendMode must be normal in this proof".into());
        }
        if object["visible"] != false && object["hidden"] != true {
            validate_flat_vector_metadata(object)?;
        }
    }
    validate_numbers(&snapshot)?;
    Ok(snapshot)
}

#[cfg(target_arch = "wasm32")]
mod surface {
    use super::*;
    use sha2::{Digest, Sha256};
    use std::sync::{Arc, Mutex};
    use wasm_bindgen::{JsCast, prelude::*};
    use web_sys::HtmlCanvasElement;

    #[wasm_bindgen]
    extern "C" {
        #[wasm_bindgen(js_namespace = performance, js_name = now)]
        fn probe_now() -> f64;
    }

    fn js_error(message: impl AsRef<str>) -> JsValue {
        JsValue::from_str(message.as_ref())
    }

    struct SurfaceState {
        instance: wgpu::Instance,
        surface: wgpu::Surface<'static>,
        canvas: HtmlCanvasElement,
        device: wgpu::Device,
        queue: wgpu::Queue,
        renderer: vello::Renderer,
        images: image_resources::ImageRegistry,
        image_atlases: Vec<image_atlas::GpuImageAtlas>,
        target: wgpu::Texture,
        target_view: wgpu::TextureView,
        pan_scratch: Option<(wgpu::Texture, wgpu::TextureView)>,
        pan_cache: Option<PanCache>,
        scene_cache: Option<SceneCache>,
        wait_for_completion:bool,
        #[cfg(feature="browser-hybrid")]
        hybrid:Option<crate::native_hybrid::RetainedHybrid>,
        hybrid_static:bool,
        hybrid_revision:u64,
        target_width: u32,
        target_height: u32,
        blitter: wgpu::util::TextureBlitter,
        config: wgpu::SurfaceConfiguration,
        device_lost: Arc<Mutex<Option<String>>>,
        gpu_error: Arc<Mutex<Option<String>>>,
        frame: u64,
        prepared_count: u64,
        prepared: PreparedGate<PreparedFrame>,
        configurations: u64,
        target_allocations: u64,
        reconfigure_next_frame: bool,
    }

    struct PanCache {
        identity: [u8; 32],
        width: u32,
        height: u32,
        scale: f64,
        pan_x: f64,
        pan_y: f64,
        margin_x: u32,
        margin_y: u32,
        allocation: vello::low_level::BumpAllocators,
    }

    #[derive(Clone)]
    struct SceneCache {
        identity: [u8; 32],
        source_scene: Arc<vello::Scene>,
        prepared_scene: Arc<prepared_scene::PreparedScene>,
        atlas_pages: usize,
        atlas_page_resource_counts: Vec<usize>,
    }

    impl SurfaceState {
        fn check_health(&self) -> Result<(), JsValue> {
            if let Some(message) = self.device_lost.lock().unwrap().as_ref() {
                return Err(js_error(format!(
                    "DEVICE_LOST: {message}; initialize the renderer again"
                )));
            }
            if let Some(message) = self.gpu_error.lock().unwrap().take() {
                return Err(js_error(message));
            }
            Ok(())
        }

        fn configure(&mut self) {
            self.surface.configure(&self.device, &self.config);
            self.configurations += 1;
            self.reconfigure_next_frame = false;
        }

        fn resize_target(&mut self, width: u32, height: u32) -> bool {
            if self.target_width == width && self.target_height == height {
                return false;
            }
            self.target.destroy();
            if let Some((texture, _)) = self.pan_scratch.take() { texture.destroy(); }
            self.pan_cache = None;
            let (target, target_view) = create_target(&self.device, width, height);
            self.target = target;
            self.target_view = target_view;
            self.target_width = width;
            self.target_height = height;
            self.target_allocations += 1;
            true
        }

        fn acquire(&mut self) -> Result<wgpu::SurfaceTexture, JsValue> {
            if self.reconfigure_next_frame {
                self.configure();
            }
            for _ in 0..2 {
                match self.surface.get_current_texture() {
                    wgpu::CurrentSurfaceTexture::Success(texture) => return Ok(texture),
                    wgpu::CurrentSurfaceTexture::Suboptimal(texture) => {
                        // Reconfiguration must happen after this texture is presented/dropped.
                        self.reconfigure_next_frame = true;
                        return Ok(texture);
                    }
                    wgpu::CurrentSurfaceTexture::Outdated => self.configure(),
                    wgpu::CurrentSurfaceTexture::Lost => {
                        self.check_health()?;
                        self.surface = self
                            .instance
                            .create_surface(wgpu::SurfaceTarget::Canvas(self.canvas.clone()))
                            .map_err(|error| {
                                js_error(format!("Surface recreation failed: {error}"))
                            })?;
                        self.configure();
                    }
                    wgpu::CurrentSurfaceTexture::Timeout => {
                        return Err(js_error("SURFACE_TIMEOUT: retry on a later frame"));
                    }
                    wgpu::CurrentSurfaceTexture::Occluded => {
                        return Err(js_error("SURFACE_OCCLUDED: retry when visible"));
                    }
                    wgpu::CurrentSurfaceTexture::Validation => {
                        return Err(js_error(
                            "SURFACE_VALIDATION: GPU surface acquisition failed",
                        ));
                    }
                }
            }
            Err(js_error(
                "SURFACE_RECOVERY_FAILED: initialize the renderer again",
            ))
        }
    }

    struct PreparedFrame {
        input: FrameInput,
        revision: Value,
        report: EncodingReport,
        images: usize,
        atlas_pages: usize,
        atlas_page_resource_counts: Vec<usize>,
        dimensions_clamped: bool,
        target_resized: bool,
        prepared_count: u64,
        queue_completed: bool,
        allocation: vello::low_level::BumpAllocators,
        allocation_status: &'static str,
        hybrid_receipt:Option<Value>,
        hybrid_declined:Option<String>,
    }

    fn frame_metadata(
        state: &SurfaceState,
        frame: &PreparedFrame,
        committed: bool,
        resized: bool,
    ) -> Value {
        let mut metadata = serde_json::json!({
            "frame": state.frame, "preparedFrame": frame.prepared_count,
            "revision": frame.revision,
            "width": frame.input.width, "height": frame.input.height,
            "visibleWidth": state.config.width, "visibleHeight": state.config.height,
            "dimensionsClamped": frame.dimensions_clamped,
            "targetResized": frame.target_resized, "resized": resized,
            "surfaceConfigurations": state.configurations,
            "targetAllocations": state.target_allocations,
            "objects": frame.report.objects, "vectors": frame.report.vectors,
            "images":frame.images,"imageResources":state.images.stats(),
            "imageAtlasBytes":state.image_atlases.len()*image_atlas::ATLAS_BYTES,
            "imageAtlasUploads":state.image_atlases.iter().map(|a|a.uploads).sum::<u64>(),
            "imageAtlasUploadBytes":state.image_atlases.iter().map(|a|a.upload_bytes).sum::<u64>(),
            "imageAtlasDeltaUploads":state.image_atlases.iter().map(|a|a.delta_uploads).sum::<u64>(),
            "imageAtlasFullUploads":state.image_atlases.iter().map(|a|a.full_uploads).sum::<u64>(),
            "imageAtlasPages":frame.atlas_pages,
            "imageAtlasAllocatedPages":state.image_atlases.len(),
            "imageAtlasPageResourceCounts":frame.atlas_page_resource_counts,
            "imageAtlasPageUploads":state.image_atlases.iter().map(|a|a.uploads).collect::<Vec<_>>(),
            "imageAtlasPageBytes":state.image_atlases.iter().map(|_|image_atlas::ATLAS_BYTES).collect::<Vec<_>>(),
            "connections": frame.report.connections, "encodedConnections": frame.report.encoded_connections,
            "textPending": frame.report.text, "rasterPending": frame.report.raster,
            "structuralObjects": frame.report.structural,
            "requiresMixedCompositor": frame.report.requires_mixed_compositor,
            "cpuPixelReadbacks": 0,
            "prepared": !committed, "committed": committed,
            "prepareQueueCompleted": frame.queue_completed,
            "queueOrdering":"single-device-ordered-render-then-blit",
            "completionPolicy":if frame.queue_completed{"checked-completed"}else{"checked-ordered"},
            "presentationSubmitted": committed,
        });
        metadata["gpuAllocationStatus"] = serde_json::json!(frame.allocation_status);
        metadata["gpuAllocationFailureFlags"] = serde_json::json!(frame.allocation.failed);
        metadata["gpuAllocationStatusBytes"] = serde_json::json!(32);
        metadata["gpuAllocationCounts"] = serde_json::json!({
            "failed": frame.allocation.failed, "binning": frame.allocation.binning,
            "ptcl": frame.allocation.ptcl, "tile": frame.allocation.tile,
            "segCounts": frame.allocation.seg_counts, "segments": frame.allocation.segments,
            "blend": frame.allocation.blend, "lines": frame.allocation.lines,
        });
        metadata["renderEngine"]=serde_json::json!("classic-0.10");
        if let Some(reason)=&frame.hybrid_declined{metadata["hybridDeclined"]=serde_json::json!(reason);}
        if let Some(receipt)=&frame.hybrid_receipt{
            // Hybrid has no Classic bump allocator. Never relabel Classic
            // counters as proof about a different renderer's output.
            for key in ["gpuAllocationCounts","gpuAllocationFailureFlags","gpuAllocationStatusBytes"] {metadata.as_object_mut().unwrap().remove(key);}
            metadata["gpuAllocationStatus"]=serde_json::json!("not-applicable-hybrid");
            metadata["renderEngine"]=serde_json::json!("hybrid-0.2");
            metadata["hybridValidationStatus"]=serde_json::json!("checked");
            metadata["hybridReceipt"]=receipt.clone();
        }
        metadata
    }

    impl Drop for SurfaceState {
        fn drop(&mut self) {
            self.target.destroy();
            if let Some((texture, _)) = self.pan_scratch.take() { texture.destroy(); }
            self.device.destroy();
            // wgpu's browser Surface::drop is a no-op. Explicitly release its canvas
            // configuration, so a fresh device may initialize this same canvas.
            if let Ok(Some(context)) = self.canvas.get_context("webgpu") {
                if let Ok(method) =
                    js_sys::Reflect::get(&context, &JsValue::from_str("unconfigure"))
                {
                    if let Some(method) = method.dyn_ref::<js_sys::Function>() {
                        let _ = method.call0(&context);
                    }
                }
            }
        }
    }

    fn create_target(
        device: &wgpu::Device,
        width: u32,
        height: u32,
    ) -> (wgpu::Texture, wgpu::TextureView) {
        let target = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("p0-retained-vello-rgba8"),
            size: wgpu::Extent3d {
                width,
                height,
                depth_or_array_layers: 1,
            },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: wgpu::TextureFormat::Rgba8Unorm,
            usage: wgpu::TextureUsages::STORAGE_BINDING | wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::RENDER_ATTACHMENT
                | wgpu::TextureUsages::COPY_SRC | wgpu::TextureUsages::COPY_DST,
            view_formats: &[],
        });
        let view = target.create_view(&wgpu::TextureViewDescriptor::default());
        (target, view)
    }

    #[wasm_bindgen]
    pub struct B4SurfaceRenderer {
        state: Option<SurfaceState>,
        retained: Option<crate::retained_protocol::RetainedScene>,
        rendered_revision: u32,
    }

    #[wasm_bindgen]
    impl B4SurfaceRenderer {
        #[wasm_bindgen(constructor)]
        pub fn new() -> Self {
            Self { state: None,retained:None,rendered_revision:0 }
        }

        /// Warm the optional second rasterizer on this existing browser device.
        /// It never creates another canvas, surface, queue or image atlas.
        pub async fn enable_hybrid(&mut self)->Result<String,JsValue>{
            let state=self.state.as_mut().ok_or_else(||js_error("RENDERER_NOT_INITIALIZED"))?;
            #[cfg(feature="browser-hybrid")]
            {
                if state.hybrid.is_none(){
                    let validation=state.device.push_error_scope(wgpu::ErrorFilter::Validation);
                    let memory=state.device.push_error_scope(wgpu::ErrorFilter::OutOfMemory);
                    let hybrid=crate::native_hybrid::RetainedHybrid::new(&state.device,state.target_width,state.target_height);
                    let memory_error=memory.pop().await;let validation_error=validation.pop().await;
                    if let Some(error)=memory_error.or(validation_error){return Err(js_error(format!("HYBRID_INITIALIZATION_FAILED: {error}")))}
                    state.check_health()?;state.hybrid=Some(hybrid);
                }
                Ok(serde_json::json!({"hybrid":"0.2","sharedDevice":true,"sharedQueue":true,"sharedOutput":true,"sharedImages":true,"gpuWorkingMemory":"not-measured"}).to_string())
            }
            #[cfg(not(feature="browser-hybrid"))]
            {let _=state;Err(js_error("HYBRID_FEATURE_NOT_BUILT"))}
        }

        pub fn set_render_policy(&mut self,policy:String)->Result<(),JsValue>{
            let state=self.state.as_mut().ok_or_else(||js_error("RENDERER_NOT_INITIALIZED"))?;
            match policy.as_str(){
                "classic"=>state.hybrid_static=false,
                "dual-static"=>{
                    #[cfg(feature="browser-hybrid")]
                    {if state.hybrid.is_none(){return Err(js_error("HYBRID_NOT_INITIALIZED"))}state.hybrid_static=true;}
                    #[cfg(not(feature="browser-hybrid"))]
                    {return Err(js_error("HYBRID_FEATURE_NOT_BUILT"))}
                },
                _=>return Err(js_error("INVALID_RENDER_POLICY")),
            }Ok(())
        }

        /// Initialize the main-thread canvas; no document/project state is opened.
        pub async fn initialize(&mut self, canvas: HtmlCanvasElement) -> Result<String, JsValue> {
            self.dispose();
            let input = validate_frame(
                canvas.width(),
                canvas.height(),
                PROOF_MAX_DIMENSION,
                1.0,
                0.0,
                0.0,
            )
            .map_err(js_error)?;
            let mut descriptor = wgpu::InstanceDescriptor::new_without_display_handle();
            descriptor.backends = wgpu::Backends::BROWSER_WEBGPU;
            let instance = wgpu::Instance::new(descriptor);
            let surface = instance
                .create_surface(wgpu::SurfaceTarget::Canvas(canvas.clone()))
                .map_err(|error| js_error(format!("WebGPU surface failed: {error}")))?;
            let adapter = instance
                .request_adapter(&wgpu::RequestAdapterOptions {
                    power_preference: wgpu::PowerPreference::HighPerformance,
                    force_fallback_adapter: false,
                    compatible_surface: Some(&surface),
                })
                .await
                .map_err(|error| js_error(format!("WEBGPU_UNAVAILABLE: {error}")))?;
            let info = adapter.get_info();
            let (device, queue) = adapter
                .request_device(&wgpu::DeviceDescriptor::default())
                .await
                .map_err(|error| js_error(format!("WebGPU device failed: {error}")))?;
            let device_lost = Arc::new(Mutex::new(None));
            let lost_signal = device_lost.clone();
            device.set_device_lost_callback(move |reason, message| {
                *lost_signal.lock().unwrap() = Some(format!("{reason:?}: {message}"));
            });
            let gpu_error = Arc::new(Mutex::new(None));
            let error_signal = gpu_error.clone();
            device.on_uncaptured_error(Arc::new(move |error| {
                let kind = match &error {
                    wgpu::Error::OutOfMemory { .. } => "GPU_OUT_OF_MEMORY",
                    wgpu::Error::Validation { .. } => "GPU_VALIDATION",
                    wgpu::Error::Internal { .. } => "GPU_INTERNAL",
                };
                *error_signal.lock().unwrap() = Some(format!("{kind}: {error}"));
            }));
            let capabilities = surface.get_capabilities(&adapter);
            let format = capabilities
                .formats
                .into_iter()
                .find(|format| {
                    matches!(
                        format,
                        wgpu::TextureFormat::Rgba8Unorm | wgpu::TextureFormat::Bgra8Unorm
                    )
                })
                .ok_or_else(|| js_error("No non-sRGB RGBA8/BGRA8 WebGPU surface format"))?;
            let input = validate_frame(
                input.width,
                input.height,
                device.limits().max_texture_dimension_2d,
                1.0,
                0.0,
                0.0,
            )
            .map_err(js_error)?;
            let config = wgpu::SurfaceConfiguration {
                usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
                format,
                width: input.width,
                height: input.height,
                present_mode: wgpu::PresentMode::Fifo,
                desired_maximum_frame_latency: 2,
                // Cached wgpu 29 web backend supports this mode even though its
                // get_capabilities currently advertises only Opaque.
                alpha_mode: wgpu::CompositeAlphaMode::PreMultiplied,
                view_formats: vec![],
            };
            let renderer = vello::Renderer::new(
                &device,
                vello::RendererOptions {
                    use_cpu: false,
                    antialiasing_support: vello::AaSupport::area_only(),
                    num_init_threads: None,
                    pipeline_cache: None,
                },
            )
            .map_err(|error| js_error(format!("Vello pipeline setup failed: {error}")))?;
            let (target, target_view) = create_target(&device, input.width, input.height);
            // Vello 0.10 fine.wgsl writes straight RGBA (rgba_sep). Alpha blending
            // it exactly once onto a cleared surface produces the premultiplied
            // RGBA required by the configured WebGPU canvas compositor.
            let blitter = wgpu::util::TextureBlitterBuilder::new(&device, format)
                .blend_state(wgpu::BlendState::ALPHA_BLENDING)
                .build();
            let mut state = SurfaceState {
                instance,
                surface,
                canvas,
                device,
                queue,
                renderer,
                images:image_resources::ImageRegistry::default(),
                image_atlases:Vec::new(),
                pan_scratch:None,
                pan_cache:None,
                scene_cache:None,wait_for_completion:false,
                #[cfg(feature="browser-hybrid")]
                hybrid:None,
                hybrid_static:false,
                hybrid_revision:0,
                target,
                target_view,
                blitter,
                target_width: input.width,
                target_height: input.height,
                config,
                device_lost,
                gpu_error,
                frame: 0,
                prepared_count: 0,
                prepared: PreparedGate::default(),
                configurations: 0,
                target_allocations: 1,
                reconfigure_next_frame: false,
            };
            state.configure();
            state.check_health()?;
            let maximum_dimension = state
                .device
                .limits()
                .max_texture_dimension_2d
                .min(PROOF_MAX_DIMENSION);
            self.state = Some(state);
            Ok(serde_json::json!({
                "backend": format!("{:?}", info.backend),
                "deviceType": format!("{:?}", info.device_type),
                "name": info.name, "driver": info.driver,
                "presentation": "main-thread-prepare-then-synchronous-surface-commit",
                "surfaceFormat": format!("{format:?}"),
                "alphaMode": "premultiplied",
                "velloIntermediateAlpha": "straight",
                "width": input.width, "height": input.height,
                "maxDimension": maximum_dimension,
                "cpuPixelReadbacks": 0,
            })
            .to_string())
        }


        pub fn load_retained_scene(&mut self,snapshot_json:String,expected_revision:u32)->Result<u32,JsValue>{
            let revision=self.retained.as_ref().map(|v|v.revision).unwrap_or(0);
            if revision!=expected_revision{return Err(js_error("RETAINED_REVISION_MISMATCH"))}
            let next=crate::retained_protocol::RetainedScene::load(&snapshot_json,revision).map_err(js_error)?;
            let revision=next.revision;self.retained=Some(next);self.rendered_revision=0;Ok(revision)
        }
        pub fn patch_retained_scene(&mut self,patch_json:String,expected_revision:u32)->Result<u32,JsValue>{
            let current=self.retained.as_ref().ok_or_else(||js_error("RETAINED_SCENE_REQUIRED"))?;
            let next=current.patch(&patch_json,expected_revision).map_err(js_error)?;
            let revision=next.revision;self.retained=Some(next);self.rendered_revision=0;Ok(revision)
        }
        pub async fn prepare_retained_frame(&mut self,width:u32,height:u32,revision:u32,scale:f64,pan_x:f64,pan_y:f64)->Result<String,JsValue>{
            let current=self.retained.as_ref().ok_or_else(||js_error("RETAINED_SCENE_REQUIRED"))?;
            if current.revision!=revision{return Err(js_error("RETAINED_REVISION_MISMATCH"))}
            if self.rendered_revision!=revision || self.state.as_ref().is_none_or(|s|s.scene_cache.is_none()){
                let json=current.json.clone();
                let result=self.prepare_snapshot(width,height,json,scale,pan_x,pan_y).await?;
                self.rendered_revision=revision;return Ok(result)
            }
            let trace_start=probe_now();
            let state=self.state.as_mut().ok_or_else(||js_error("RENDERER_NOT_INITIALIZED"))?;
            state.prepared.discard();state.check_health()?;
            let input=validate_frame(width,height,state.device.limits().max_texture_dimension_2d,scale,pan_x,pan_y).map_err(js_error)?;
            let trace_validated=probe_now();
            let cache=state.scene_cache.as_ref().cloned().ok_or_else(||js_error("RETAINED_CACHE_REQUIRED"))?;
                    let camera = vello::kurbo::Affine::translate((input.pan_x, input.pan_y))
                        * vello::kurbo::Affine::scale(input.scale);
                    prepared_scene::validate_camera(&cache.prepared_scene, camera).map_err(js_error)?;
                    state.images.stage(&cache.prepared_scene.resources).map_err(js_error)?;
                    let mut scene = vello::Scene::new();
                    scene.append(&cache.source_scene, Some(camera));
                    let trace_appended=probe_now();
                    let target_resized = state.resize_target(input.width, input.height);
                    let allocation = state.renderer.render_to_texture_checked(
                        &state.device, &state.queue, &scene, &state.target_view,
                        &vello::RenderParams {
                            base_color: cache.prepared_scene.background,
                            width: input.width, height: input.height,
                            antialiasing_method: vello::AaConfig::Area,
                        },
                    ).await.map_err(|error| {
                        state.images.discard();
                        js_error(format!("Vello reused-scene render failed: {error}"))
                    })?;
                    let trace_render_call = probe_now();
                    if state.wait_for_completion {
                        let (sender, receiver) = futures_channel::oneshot::channel();
                        state.queue.on_submitted_work_done(move || { let _ = sender.send(()); });
                        receiver.await.map_err(|_| js_error("GPU_COMPLETION_CHANNEL_CLOSED"))?;
                    }
                    let trace_gpu_done = probe_now();
                    state.check_health()?;
                    state.prepared_count += 1;
                    let dimensions_clamped = input.width != width || input.height != height;
                    let prepared = PreparedFrame {
                        input, revision: serde_json::json!(revision.to_string()),
                        report: cache.prepared_scene.report,
                        images: cache.prepared_scene.images.len(),
                        atlas_pages: cache.atlas_pages,
                        atlas_page_resource_counts: cache.atlas_page_resource_counts,
                        dimensions_clamped,
                        target_resized, prepared_count: state.prepared_count,
                        queue_completed: state.wait_for_completion,
                        allocation, allocation_status: "checked",hybrid_receipt:None,hybrid_declined:None,
                    };
                    let mut metadata = frame_metadata(state, &prepared, false, false);
                    metadata["probeTimingsMs"] = serde_json::json!({
                        "validate": trace_validated - trace_start,
                        "parseScene": 0.0, "pack": 0.0, "atlas": 0.0,
                        "hash": 0.0, "transferBytes": 0,
                        "encode": trace_appended - trace_validated,
                        "renderCall": trace_render_call - trace_appended,
                        "gpuWait": trace_gpu_done - trace_render_call,
                        "total": trace_gpu_done - trace_start
                    });
                    metadata["paintMode"] = serde_json::json!("retained-camera");
                    state.prepared.stage(prepared);
                    return Ok(metadata.to_string());
        }

        pub fn set_completion_policy(&mut self,policy:String)->Result<(),JsValue>{
            let state=self.state.as_mut().ok_or_else(||js_error("RENDERER_NOT_INITIALIZED"))?;
            state.wait_for_completion=match policy.as_str(){"checked-ordered"=>false,"checked-completed"=>true,_=>return Err(js_error("INVALID_COMPLETION_POLICY"))};Ok(())
        }
        /// Representative checked work on the actual viewport device; never presents test pixels.
        pub async fn warm_classic(&mut self)->Result<String,JsValue>{
            let start=probe_now();
            let image=serde_json::json!({"key":"__classic-warm-image__","revision":1,"epoch":4294967295u32,"width":2,"height":2});
            self.register_image(image.to_string(),vec![255u8;16])?;
            let vector=serde_json::json!({"type":"vector","object":{"id":"warm-path","kind":"vector","transform":[1,0,0,1,0,0],"opacity":0.75,"payload":{"commands":[["M",2,2],["L",30,2],["C",48,2,48,40,30,40],["L",2,40],["Z"]],"fill":"#167b8aff","stroke":"#f1c878ff","strokeWidth":2,"vectorFillRule":"nonzero","vectorStrokeJoin":"round","vectorStrokeCap":"round"}}});
            let snapshot=serde_json::json!({"schema":"art-equation.display-list","schemaVersion":2,"sceneId":"__classic-warm__","revision":"1","environment":{"background":"#00000000","colorSpace":"srgb"},"resources":[image.clone()],"operations":[vector,{"type":"image","id":"warm-image","resource":image,"sourceRect":{"x":0,"y":0,"width":2,"height":2},"transform":[8,0,0,8,44,4],"opacity":0.8,"sampling":"bilinear"}]});
            let prepared=self.prepare_snapshot(64,64,snapshot.to_string(),1.0,0.0,0.0).await?;
            let state=self.state.as_mut().ok_or_else(||js_error("RENDERER_NOT_INITIALIZED"))?;
            let format=state.config.format;
            let texture=state.device.create_texture(&wgpu::TextureDescriptor{label:Some("launch-only-blit-warmup"),size:wgpu::Extent3d{width:64,height:64,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format,usage:wgpu::TextureUsages::RENDER_ATTACHMENT,view_formats:&[]});
            let view=texture.create_view(&wgpu::TextureViewDescriptor::default());
            let mut encoder=state.device.create_command_encoder(&wgpu::CommandEncoderDescriptor{label:Some("launch-blit-warmup")});
            state.blitter.copy(&state.device,&mut encoder,&state.target_view,&view);state.queue.submit([encoder.finish()]);
            let(sender,receiver)=futures_channel::oneshot::channel();state.queue.on_submitted_work_done(move||{let _=sender.send(());});receiver.await.map_err(|_|js_error("GPU_COMPLETION_CHANNEL_CLOSED"))?;
            state.check_health()?;state.prepared.discard();state.scene_cache=None;
            self.retain_images("[]".into())?;
            Ok(serde_json::json!({"status":"ready","renderer":"classic-0.10","sameViewportDevice":true,"presentationCount":0,"ms":probe_now()-start,"paths":["fill","stroke","curves","transparency","image-sampling","surface-blit"],"scope":"Representative pipeline warm-up, not all fonts/assets or persistent DX12 pipeline cache","checkedFrame":serde_json::from_str::<Value>(&prepared).map_err(|e|js_error(e.to_string()))?}).to_string())
        }

        /// Render into the retained target only. No visible canvas resize,
        /// surface configuration/acquisition or presentation happens here.
        /// The caller checks its generation before synchronously committing.
        pub async fn prepare_snapshot(
            &mut self,
            width: u32,
            height: u32,
            snapshot_json: String,
            scale: f64,
            pan_x: f64,
            pan_y: f64,
) -> Result<String, JsValue> {
            self.rendered_revision=0;
            let cache_hint = false;
            let warm_cache = false;
            let cache_snapshot_json = String::new();
            let trace_start = probe_now();
            let state = self
                .state
                .as_mut()
                .ok_or_else(|| js_error("RENDERER_NOT_INITIALIZED"))?;
            state.prepared.discard();
            state.check_health()?;
            let input = validate_frame(
                width,
                height,
                state.device.limits().max_texture_dimension_2d,
                scale,
                pan_x,
                pan_y,
            )
            .map_err(js_error)?;
            let trace_validated = probe_now();
            // The isolated viewer serializes its root revision before the
            // environment and operations. Hash the original bytes with only
            // that generation value skipped; a different scene still misses.
            let identity_source = if cache_hint || warm_cache {
                if cache_snapshot_json.is_empty() { return Err(js_error("CACHE_SCENE_REQUIRED")); }
                cache_snapshot_json.as_str()
            } else { snapshot_json.as_str() };
            let mut scene_hash = Sha256::new();
            let revision_prefix = "\"revision\":\"";
            if let Some(start) = identity_source.find(revision_prefix) {
                let value_start = start + revision_prefix.len();
                if let Some(value_end) = identity_source[value_start..].find('"') {
                    scene_hash.update(&identity_source.as_bytes()[..value_start]);
                    scene_hash.update(&identity_source.as_bytes()[value_start + value_end..]);
                } else {
                    scene_hash.update(identity_source.as_bytes());
                }
            } else {
                scene_hash.update(identity_source.as_bytes());
            }
            let identity: [u8; 32] = scene_hash.finalize().into();
            let cached_revision = snapshot_json.find(revision_prefix).and_then(|start| {
                let value_start = start + revision_prefix.len();
                let value_end = snapshot_json[value_start..].find('"')? + value_start;
                let raw = &snapshot_json[value_start..value_end];
                raw.chars().all(|ch| ch.is_ascii_digit()).then(|| raw.to_owned())
            });
            if !cache_hint && !warm_cache {
                if let (Some(cache), Some(revision)) = (
                    state.scene_cache.as_ref().filter(|cache| cache.identity == identity).cloned(),
                    cached_revision,
                ) {
                    let camera = vello::kurbo::Affine::translate((input.pan_x, input.pan_y))
                        * vello::kurbo::Affine::scale(input.scale);
                    prepared_scene::validate_camera(&cache.prepared_scene, camera).map_err(js_error)?;
                    state.images.stage(&cache.prepared_scene.resources).map_err(js_error)?;
                    let mut scene = vello::Scene::new();
                    scene.append(&cache.source_scene, Some(camera));
                    let target_resized = state.resize_target(input.width, input.height);
                    let allocation = state.renderer.render_to_texture_checked(
                        &state.device, &state.queue, &scene, &state.target_view,
                        &vello::RenderParams {
                            base_color: cache.prepared_scene.background,
                            width: input.width, height: input.height,
                            antialiasing_method: vello::AaConfig::Area,
                        },
                    ).await.map_err(|error| {
                        state.images.discard();
                        js_error(format!("Vello reused-scene render failed: {error}"))
                    })?;
                    let trace_render_call = probe_now();
                    if state.wait_for_completion {
                        let (sender, receiver) = futures_channel::oneshot::channel();
                        state.queue.on_submitted_work_done(move || { let _ = sender.send(()); });
                        receiver.await.map_err(|_| js_error("GPU_COMPLETION_CHANNEL_CLOSED"))?;
                    }
                    let trace_gpu_done = probe_now();
                    state.check_health()?;
                    state.prepared_count += 1;
                    let dimensions_clamped = input.width != width || input.height != height;
                    let prepared = PreparedFrame {
                        input, revision: serde_json::json!(revision),
                        report: cache.prepared_scene.report,
                        images: cache.prepared_scene.images.len(),
                        atlas_pages: cache.atlas_pages,
                        atlas_page_resource_counts: cache.atlas_page_resource_counts,
                        dimensions_clamped,
                        target_resized, prepared_count: state.prepared_count,
                        queue_completed: state.wait_for_completion,
                        allocation, allocation_status: "checked",hybrid_receipt:None,hybrid_declined:None,
                    };
                    let mut metadata = frame_metadata(state, &prepared, false, false);
                    metadata["probeTimingsMs"] = serde_json::json!({
                        "validate": trace_validated - trace_start,
                        "parseScene": 0.0, "pack": 0.0, "atlas": 0.0,
                        "encode": trace_render_call - trace_validated,
                        "renderCall": 0.0,
                        "gpuWait": trace_gpu_done - trace_render_call,
                        "total": trace_gpu_done - trace_start
                    });
                    metadata["paintMode"] = serde_json::json!("scene-reuse");
                    state.prepared.stage(prepared);
                    return Ok(metadata.to_string());
                }
            }
            let snapshot = parse_snapshot(&snapshot_json).map_err(js_error)?;
            let prepared_scene = prepared_scene::prepare_snapshot(&snapshot).map_err(js_error)?;
            let camera = vello::kurbo::Affine::translate((input.pan_x, input.pan_y))
                * vello::kurbo::Affine::scale(input.scale);
            prepared_scene::validate_camera(&prepared_scene, camera).map_err(js_error)?;
            let trace_scene_ready = probe_now();
            // Resolve all references and place the entire image batch before
            // rendering. Vello never receives independently packed image IDs.
            let decoded=prepared_scene.resources.iter().map(|r|state.images.resolve(r)).collect::<Result<Vec<_>,_>>().map_err(js_error)?;
            // Preflight the whole bounded set before touching any active GPU
            // page. The previous complete surface frame remains visible until
            // present_prepared commits the fully rendered replacement.
            let plans=image_atlas::pack_native_pages(decoded).map_err(js_error)?;
            let trace_packed = probe_now();
            state.images.stage(&prepared_scene.resources).map_err(js_error)?;
            while state.image_atlases.len()<plans.len() {
                let index=state.image_atlases.len();
                state.image_atlases.push(image_atlas::GpuImageAtlas::new_native_page(
                    &state.device,&mut state.renderer,index).map_err(js_error)?);
            }
            for (atlas,plan) in state.image_atlases.iter_mut().zip(&plans) {
                atlas.update(plan,&state.queue,&mut state.renderer);
            }
            let trace_atlas_ready = probe_now();
            let target_resized = state.resize_target(input.width, input.height);
            let pages=state.image_atlases.iter().zip(&plans)
                .map(|(atlas,plan)|(&atlas.image,plan)).collect::<Vec<_>>();
            let source_scene = gpu_scene::encode_prepared_with_image_pages(&prepared_scene,&pages).map_err(js_error)?;
            let report = prepared_scene.report;
            let mut scene = vello::Scene::new();
            scene.append(&source_scene, Some(camera));
            let background = prepared_scene.background;
            let trace_encoded = probe_now();
            let device_edge = state.device.limits().max_texture_dimension_2d;
            let margin_x = (device_edge.saturating_sub(input.width) / 2).min(320);
            let margin_y = (device_edge.saturating_sub(input.height) / 2).min(320);
            let prior_cache_match = state.pan_cache.as_ref().map(|prior| prior.identity == identity);
            let prior_cache_pan = state.pan_cache.as_ref().map(|prior| (prior.pan_x, prior.pan_y));
            let source = state.pan_cache.as_ref().and_then(|prior| {
                if !(cache_hint || warm_cache) || state.pan_scratch.is_none() || target_resized || prior.identity != identity
                    || prior.width != input.width || prior.height != input.height
                    || prior.scale != input.scale || prior.margin_x != margin_x
                    || prior.margin_y != margin_y { return None; }
                let x = f64::from(prior.margin_x) + prior.pan_x - input.pan_x;
                let y = f64::from(prior.margin_y) + prior.pan_y - input.pan_y;
                if (x - x.round()).abs() > 1e-7 || (y - y.round()).abs() > 1e-7
                    || x < 0.0 || y < 0.0
                    || x + f64::from(input.width) > f64::from(input.width + 2 * margin_x)
                    || y + f64::from(input.height) > f64::from(input.height + 2 * margin_y) {
                    return None;
                }
                Some((x.round() as u32, y.round() as u32))
            });
            let mut paint_mode;
            let allocation;
            let allocation_status;
            let mut hybrid_receipt=None;
            let mut hybrid_declined=None;
            if (cache_hint || warm_cache) && margin_x > 0 && margin_y > 0 {
                let (source_x, source_y) = if let Some(source) = source {
                    paint_mode = "retained-pan-copy";
                    allocation = state.pan_cache.as_ref().expect("matching checked pan cache").allocation;
                    allocation_status = "retained-checked";
                    source
                } else {
                    paint_mode = "overscan-render";
                    if let Some((old, _)) = state.pan_scratch.take() { old.destroy(); }
                    state.pan_cache = None;
                    let overscan_width = input.width + 2 * margin_x;
                    let overscan_height = input.height + 2 * margin_y;
                    let (texture, view) = create_target(&state.device, overscan_width, overscan_height);
                    let overscan_camera = vello::kurbo::Affine::translate((
                        input.pan_x + f64::from(margin_x), input.pan_y + f64::from(margin_y),
                    )) * vello::kurbo::Affine::scale(input.scale);
                    let cache_snapshot = parse_snapshot(&cache_snapshot_json).map_err(js_error)?;
                    if cache_snapshot["resources"] != snapshot["resources"]
                        || cache_snapshot["environment"] != snapshot["environment"] {
                        return Err(js_error("CACHE_SCENE_RESOURCE_OR_ENVIRONMENT_MISMATCH"));
                    }
                    let cache_prepared = prepared_scene::prepare_snapshot(&cache_snapshot).map_err(js_error)?;
                    prepared_scene::validate_camera(&cache_prepared, overscan_camera).map_err(js_error)?;
                    let cache_source_scene = gpu_scene::encode_prepared_with_image_pages(&cache_prepared,&pages).map_err(js_error)?;
                    let mut overscan_scene = vello::Scene::new();
                    overscan_scene.append(&cache_source_scene, Some(overscan_camera));
                    allocation = state.renderer.render_to_texture_checked(
                        &state.device, &state.queue, &overscan_scene, &view,
                        &vello::RenderParams {
                            base_color: background, width: overscan_width, height: overscan_height,
                            antialiasing_method: vello::AaConfig::Area,
                        },
                    ).await.map_err(|error| {
                        state.images.discard();
                        js_error(format!("Vello overscan render failed: {error}"))
                    })?;
                    allocation_status = "checked";
                    state.pan_scratch = Some((texture, view));
                    state.pan_cache = Some(PanCache { identity, width: input.width, height: input.height,
                        scale: input.scale, pan_x: input.pan_x, pan_y: input.pan_y,
                        margin_x, margin_y, allocation });
                    (margin_x, margin_y)
                };
                {
                    if warm_cache { paint_mode = "overscan-warm-copy"; }
                    let overscan = &state.pan_scratch.as_ref().unwrap().0;
                    let mut copy = state.device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
                        label: Some("retina-copy-visible-overscan-region"),
                    });
                    copy.copy_texture_to_texture(
                        wgpu::TexelCopyTextureInfo { texture: overscan, mip_level: 0,
                            origin: wgpu::Origin3d { x: source_x, y: source_y, z: 0 },
                            aspect: wgpu::TextureAspect::All },
                        wgpu::TexelCopyTextureInfo { texture: &state.target, mip_level: 0,
                            origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
                        wgpu::Extent3d { width: input.width, height: input.height,
                            depth_or_array_layers: 1 },
                    );
                    state.queue.submit([copy.finish()]);
                }
            } else {
                paint_mode = "full";
                // An exact frame can race between cache warming and the first
                // pointer-move. Keep a matching overscan texture alive; the
                // next pan still checks scene identity, dimensions and scale.
                if target_resized || state.pan_cache.as_ref().is_some_and(|prior|
                    prior.width != input.width || prior.height != input.height
                    || prior.scale != input.scale) {
                    state.pan_cache = None;
                }
                #[cfg(feature="browser-hybrid")]
                if state.hybrid_static {
                    state.hybrid_revision=state.hybrid_revision.wrapping_add(1);
                    let validation=state.device.push_error_scope(wgpu::ErrorFilter::Validation);
                    let memory=state.device.push_error_scope(wgpu::ErrorFilter::OutOfMemory);
                    let hybrid=state.hybrid.as_mut().ok_or_else(||js_error("HYBRID_NOT_INITIALIZED"))?;
                    let result=hybrid.render(&state.device,&state.queue,&state.target_view,&prepared_scene,None,&state.image_atlases,state.hybrid_revision,input.width,input.height,camera);
                    let memory_error=memory.pop().await;
                    let validation_error=validation.pop().await;
                    if let Some(error)=memory_error.or(validation_error){state.images.discard();return Err(js_error(format!("HYBRID_GPU_ERROR: {error}")))}
                    match result {
                        Ok(receipt)=>{hybrid_receipt=Some(receipt);paint_mode="hybrid-static";},
                        Err(error) if error.starts_with("HYBRID_UNSUPPORTED")=>{hybrid_declined=Some(error)},
                        Err(error)=>{state.images.discard();return Err(js_error(error))},
                    }
                }
                if hybrid_receipt.is_some(){
                    allocation=Default::default();allocation_status="not-applicable-hybrid";
                }else{
                allocation = state.renderer.render_to_texture_checked(
                    &state.device, &state.queue, &scene, &state.target_view,
                    &vello::RenderParams {
                        base_color: background, width: input.width, height: input.height,
                        antialiasing_method: vello::AaConfig::Area,
                    },
                ).await.map_err(|error| {
                    state.images.discard();
                    js_error(format!("Vello render failed: {error}"))
                })?;
                allocation_status = "checked";
                }
            }
            let trace_render_call = probe_now();
            // Vello's render and the subsequent surface blit use the same
            // ordered GPU queue. The blit cannot read the target before the
            // render/copy finishes. Waiting for the entire queue to become idle
            // adds a large startup stall without improving frame ordering.
            // Keep the old wait available as an opt-out diagnostic build.
            if paint_mode != "retained-pan-copy" && (state.wait_for_completion||hybrid_receipt.is_some()) {
                let (sender, receiver) = futures_channel::oneshot::channel();
                state.queue.on_submitted_work_done(move || {
                    let _ = sender.send(());
                });
                receiver
                    .await
                    .map_err(|_| js_error("GPU_COMPLETION_CHANNEL_CLOSED"))?;
            }
            let trace_gpu_done = probe_now();
            state.check_health()?;
            state.prepared_count += 1;
            let dimensions_clamped = input.width != width || input.height != height;
            let prepared = PreparedFrame {
                input,
                revision: snapshot["revision"].clone(),
                report,
                images:prepared_scene.images.len(),
                atlas_pages:plans.len(),
                atlas_page_resource_counts:plans.iter().map(|plan|plan.images.len()).collect(),
                dimensions_clamped,
                target_resized,
                prepared_count: state.prepared_count,
                queue_completed: paint_mode != "retained-pan-copy" && (state.wait_for_completion||hybrid_receipt.is_some()),
                allocation, allocation_status,hybrid_receipt,hybrid_declined,
            };
            let mut metadata = frame_metadata(state, &prepared, false, false);
            metadata["probeTimingsMs"] = serde_json::json!({
                "validate": trace_validated - trace_start,
                "parseScene": trace_scene_ready - trace_validated,
                "pack": trace_packed - trace_scene_ready,
                "atlas": trace_atlas_ready - trace_packed,
                "encode": trace_encoded - trace_atlas_ready,
                "renderCall": trace_render_call - trace_encoded,
                "gpuWait": trace_gpu_done - trace_render_call,
                "total": trace_gpu_done - trace_start
            });
            metadata["paintMode"] = serde_json::json!(paint_mode);
            metadata["priorCacheIdentityMatches"] = serde_json::json!(prior_cache_match);
            metadata["priorCachePan"] = serde_json::json!(prior_cache_pan);
            if !cache_hint && !warm_cache {
                state.scene_cache = Some(SceneCache {
                    identity, source_scene:Arc::new(source_scene),
                    prepared_scene: Arc::new(prepared_scene),
                    atlas_pages: plans.len(),
                    atlas_page_resource_counts: plans.iter().map(|plan| plan.images.len()).collect(),
                });
            } else {
                state.scene_cache = None;
            }
            state.prepared.stage(prepared);
            Ok(metadata.to_string())
        }

        /// One synchronous commit point for surface pixels and caller-owned DOM
        /// ownership/camera updates. A prepared frame is consumed exactly once.
        /// Preparation queue completion does not certify scan-out; this method
        /// submits the final small blit and presents in the current JS turn.
        pub fn present_prepared(&mut self) -> Result<String, JsValue> {
            let state = self
                .state
                .as_mut()
                .ok_or_else(|| js_error("RENDERER_NOT_INITIALIZED"))?;
            let prepared = state.prepared.take_for_present().map_err(js_error)?;
            // An attempted commit consumes the preparation even on a health or
            // surface error; it cannot become an accidental later retry.
            state.check_health()?;
            let resized = state.config.width != prepared.input.width
                || state.config.height != prepared.input.height;
            if resized {
                state.config.width = prepared.input.width;
                state.config.height = prepared.input.height;
                state.configure();
            }
            let surface_texture = state.acquire()?;
            let surface_view = surface_texture
                .texture
                .create_view(&wgpu::TextureViewDescriptor::default());
            let mut encoder =
                state
                    .device
                    .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                        label: Some("p0-main-thread-prepared-surface-commit"),
                    });
            {
                // TextureBlitter loads its destination. Clear every surface frame
                // before alpha conversion so removed/transparent objects cannot
                // blend with an earlier frame or leave motion trails.
                let _clear = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("p0-clear-surface-before-alpha-conversion"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &surface_view,
                        depth_slice: None,
                        resolve_target: None,
                        ops: wgpu::Operations {
                            load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),
                            store: wgpu::StoreOp::Store,
                        },
                    })],
                    depth_stencil_attachment: None,
                    timestamp_writes: None,
                    occlusion_query_set: None,
                    multiview_mask: None,
                });
            }
            state.blitter.copy(
                &state.device,
                &mut encoder,
                &state.target_view,
                &surface_view,
            );
            state.queue.submit([encoder.finish()]);
            surface_texture.present();
            state.frame += 1;
            state.images.present();
            Ok(frame_metadata(state, &prepared, true, resized).to_string())
        }

        pub fn discard_prepared(&mut self) {
            if let Some(state) = self.state.as_mut() {
                state.prepared.discard();
                state.images.discard();
            }
        }

        /// Registration is synchronous and must finish before async preparation
        /// takes the mutable renderer borrow. Revisions are immutable.
        pub fn register_image(&mut self,reference_json:String,pixels:Vec<u8>)->Result<String,JsValue> {
            let state=self.state.as_mut().ok_or_else(||js_error("RENDERER_NOT_INITIALIZED"))?;
            state.check_health()?;
            let value:Value=serde_json::from_str(&reference_json).map_err(|_|js_error("RESOURCE_INVALID: image JSON"))?;
            let reference=image_resources::parse_reference(&value).map_err(js_error)?;
            let used_by_cached_scene = state.scene_cache.as_ref().is_some_and(|cache|
                cache.prepared_scene.resources.contains(&reference));
            let result=state.images.register(reference,pixels).map_err(js_error)?;
            if used_by_cached_scene { state.scene_cache=None; }
            Ok(result.to_string())
        }

        pub fn retain_images(&mut self,references_json:String)->Result<String,JsValue> {
            let state=self.state.as_mut().ok_or_else(||js_error("RENDERER_NOT_INITIALIZED"))?;
            state.prepared.discard();
            let references=image_resources::parse_references_json(&references_json).map_err(js_error)?;
            state.images.retain_candidates(&references);
            if state.scene_cache.as_ref().is_some_and(|cache|
                cache.prepared_scene.resources.iter().any(|r| !references.contains(r))) {
                state.scene_cache=None;
            }
            Ok(state.images.stats().to_string())
        }

        pub fn resource_stats(&self)->Result<String,JsValue> {
            let state=self.state.as_ref().ok_or_else(||js_error("RENDERER_NOT_INITIALIZED"))?;
            let mut stats=state.images.stats();stats["atlasAllocated"]=serde_json::json!(!state.image_atlases.is_empty());
            stats["imageAtlasAllocatedPages"]=serde_json::json!(state.image_atlases.len());
            stats["imageAtlasBytes"]=serde_json::json!(state.image_atlases.len()*image_atlas::ATLAS_BYTES);
            stats["imageAtlasUploads"]=serde_json::json!(state.image_atlases.iter().map(|a|a.uploads).sum::<u64>());
            stats["imageAtlasUploadBytes"]=serde_json::json!(state.image_atlases.iter().map(|a|a.upload_bytes).sum::<u64>());
            stats["imageAtlasDeltaUploads"]=serde_json::json!(state.image_atlases.iter().map(|a|a.delta_uploads).sum::<u64>());
            stats["imageAtlasFullUploads"]=serde_json::json!(state.image_atlases.iter().map(|a|a.full_uploads).sum::<u64>());
            stats["imageAtlasPageUploads"]=serde_json::json!(state.image_atlases.iter().map(|a|a.uploads).collect::<Vec<_>>());
            stats["imageAtlasPageBytes"]=serde_json::json!(state.image_atlases.iter().map(|_|image_atlas::ATLAS_BYTES).collect::<Vec<_>>());
            stats["targetWidth"]=serde_json::json!(state.target_width);stats["targetHeight"]=serde_json::json!(state.target_height);
            stats["visibleWidth"]=serde_json::json!(state.config.width);stats["visibleHeight"]=serde_json::json!(state.config.height);
            Ok(stats.to_string())
        }

        /// Check device health while idle. Calls must not overlap initialization
        /// or preparation, which hold the mutable renderer borrow until resolved.
        pub fn check_health(&self) -> Result<(), JsValue> {
            self.state
                .as_ref()
                .ok_or_else(|| js_error("RENDERER_NOT_INITIALIZED"))?
                .check_health()
        }

        pub fn dispose(&mut self) {
            self.retained=None;self.rendered_revision=0;
            self.state = None;
        }

        /// Destroy the actual device without disposing its observable state.
        /// WebGPU resolves GPUDevice.lost asynchronously; the installed callback
        /// then makes check_health report DEVICE_LOST. Do not synthesize a loss
        /// flag or clear state here, which would bypass that recovery evidence.
        /// Calls must not overlap initialization/preparation's mutable borrow.
        pub fn destroy_device_for_recovery_test(&mut self) {
            if let Some(state) = self.state.as_ref() {
                state.device.destroy();
            }
        }
    }
}

#[cfg(target_arch = "wasm32")]
pub use surface::B4SurfaceRenderer;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn frame_validation_rejects_zero_and_nonfinite_viewports() {
        assert!(validate_frame(0, 20, 4096, 1.0, 0.0, 0.0).is_err());
        assert!(validate_frame(20, 0, 4096, 1.0, 0.0, 0.0).is_err());
        for scale in [f64::NAN, f64::INFINITY, -1.0, 0.0, 1e7] {
            assert!(validate_frame(20, 20, 4096, scale, 0.0, 0.0).is_err());
        }
        for pan in [f64::NAN, f64::INFINITY, -f64::INFINITY, 1e10] {
            assert!(validate_frame(20, 20, 4096, 1.0, pan, 0.0).is_err());
            assert!(validate_frame(20, 20, 4096, 1.0, 0.0, pan).is_err());
        }
    }

    #[test]
    fn frame_dimensions_obey_device_and_proof_caps() {
        let input = validate_frame(u32::MAX, u32::MAX, 2048, 0.25, -900.0, 700.0).unwrap();
        assert_eq!((input.width, input.height), (2048, 2048));
        let input = validate_frame(8000, 6000, 8192, 1.0, 0.0, 0.0).unwrap();
        assert_eq!((input.width, input.height), (4096, 4096));
        assert!(validate_frame(1, 1, 0, 1.0, 0.0, 0.0).is_err());
    }

    #[test]
    fn invalid_snapshot_schema_shape_and_numbers_do_not_reach_gpu() {
        assert!(parse_snapshot("{").is_err());
        assert!(parse_snapshot(r#"{"schema":"wrong","schemaVersion":1,"objects":[]}"#).is_err());
        assert!(
            parse_snapshot(r#"{"schema":"art-equation.scene","schemaVersion":2,"objects":[]}"#)
                .is_err()
        );
        assert!(
            parse_snapshot(r#"{"schema":"art-equation.scene","schemaVersion":1,"objects":{}}"#)
                .is_err()
        );
        assert!(parse_snapshot(r#"{"schema":"art-equation.scene","schemaVersion":1,"objects":[{"bounds":{"x":1e100}}]}"#).is_err());
        assert!(parse_snapshot(&" ".repeat(MAX_SNAPSHOT_BYTES + 1)).is_err());
    }

    #[test]
    fn owned_sanitized_fixture_encodes_without_archived_dependency() {
        let mut fixture = real_board_fixture();
        assert!(parse_snapshot(&fixture.to_string()).is_err());
        fixture["connections"] = serde_json::json!([]);
        let parsed = parse_snapshot(&fixture.to_string()).unwrap();
        let (_, report) = gpu_scene::encode_snapshot(&parsed).unwrap();
        assert_eq!(report.vectors, 7);
        assert_eq!(report.encoded_connections, 0);
    }

    fn flat_guard_fixture() -> Value {
        serde_json::json!({
            "schema":"art-equation.scene", "schemaVersion":1,
            "environment":{"background":"#00000000","colorSpace":"srgb"},
            "connections":[], "objects":[{
                "id":"flat-vector", "kind":"vector", "visible":true,
                "transform":[1,0,0,1,0,0], "bounds":{"x":4,"y":4,"width":8,"height":8},
                "payload":{"fill":"#ff0000"}
            }]
        })
    }

    #[test]
    fn inherited_clips_groups_and_raw_vector_edits_fail_for_both_backends() {
        for (field, value) in [
            ("parentId", serde_json::json!("parent-group")),
            ("clipId", serde_json::json!("clip-mask")),
            ("groupId", serde_json::json!("raw-board-group")),
        ] {
            let mut fixture = flat_guard_fixture();
            fixture["objects"][0][field] = value;
            let source = fixture.to_string();
            assert!(parse_snapshot(&source).unwrap_err().contains(field));
            assert!(
                cpu::render_cpu_snapshot(32, 32, &source, 1.0, 0.0, 0.0)
                    .unwrap_err()
                    .contains(field)
            );
        }
        for (field, value) in [
            (
                "vectorTransform",
                serde_json::json!({"scaleX":-1,"skewX":20}),
            ),
            (
                "vectorBoolean",
                serde_json::json!({"operation":"subtract","operands":[]}),
            ),
            (
                "vectorPath",
                serde_json::json!({"version":1,"closed":true,"points":[]}),
            ),
            ("resolvedPaths", serde_json::json!([])),
            ("clipChildren", serde_json::json!(true)),
            ("fillOpacity", serde_json::json!(0.5)),
            ("cornerRadius", serde_json::json!(8)),
        ] {
            let mut fixture = flat_guard_fixture();
            fixture["objects"][0]["payload"][field] = value;
            let source = fixture.to_string();
            assert!(parse_snapshot(&source).unwrap_err().contains(field));
            assert!(
                cpu::render_cpu_snapshot(32, 32, &source, 1.0, 0.0, 0.0)
                    .unwrap_err()
                    .contains(field)
            );
        }
    }

    #[test]
    fn canonical_matrix_is_validated_and_preserves_actual_transformed_pixels() {
        for matrix in [
            serde_json::json!([1, 0, 0, 1]),
            serde_json::json!("matrix(1,0,0,1,0,0)"),
            serde_json::json!([1, 0, 0, 1, "x", 0]),
        ] {
            let mut fixture = flat_guard_fixture();
            fixture["objects"][0]["transform"] = matrix;
            assert!(parse_snapshot(&fixture.to_string()).is_err());
        }
        let mut fixture = flat_guard_fixture();
        fixture["objects"][0]["transform"] = serde_json::json!([1, 0, 0, 1, 8, 0]);
        let source = fixture.to_string();
        assert!(parse_snapshot(&source).is_ok());
        let pixels = cpu::render_cpu_snapshot(32, 32, &source, 1.0, 0.0, 0.0).unwrap();
        assert_eq!(
            &pixels[(8 * 32 + 6) * 4..(8 * 32 + 6) * 4 + 4],
            &[0, 0, 0, 0]
        );
        assert_eq!(
            &pixels[(8 * 32 + 16) * 4..(8 * 32 + 16) * 4 + 4],
            &[255, 0, 0, 255]
        );
    }

    #[test]
    fn descriptive_group_metadata_and_inactive_clips_do_not_trigger_a_false_positive() {
        let mut fixture = flat_guard_fixture();
        fixture["objects"][0]["payload"]["group"] = serde_json::json!("Reference palette group");
        fixture["objects"][0]["payload"]["clipChildren"] = serde_json::json!(false);
        fixture["objects"][0]["payload"]["fillOpacity"] = serde_json::json!(1.0);
        fixture["objects"][0]["payload"]["cornerRadius"] = serde_json::json!(0.0);
        fixture["objects"][0]["extensions"] =
            serde_json::json!({"group":{"label":"archived design reference"}});
        let source = fixture.to_string();
        assert!(parse_snapshot(&source).is_ok());
        assert!(cpu::render_cpu_snapshot(32, 32, &source, 1.0, 0.0, 0.0).is_ok());
    }

    #[test]
    fn nonrectangular_legacy_shapes_require_commands_and_hidden_ones_do_not_paint() {
        let mut fixture = flat_guard_fixture();
        fixture["objects"][0]["payload"]["shapeType"] = serde_json::json!("ellipse");
        assert!(
            parse_snapshot(&fixture.to_string())
                .unwrap_err()
                .contains("explicit path commands")
        );
        fixture["objects"][0]["visible"] = serde_json::json!(false);
        let pixels = cpu::render_cpu_snapshot(32, 32, &fixture.to_string(), 1.0, 0.0, 0.0).unwrap();
        assert!(pixels.iter().all(|byte| *byte == 0));
    }

    #[test]
    fn presentation_requires_a_successful_preparation_and_consumes_it_once() {
        let mut gate = PreparedGate::default();
        assert!(gate.take_for_present().is_err());
        gate.stage(("revision-1", 320, 240));
        assert_eq!(gate.take_for_present().unwrap(), ("revision-1", 320, 240));
        assert!(gate.take_for_present().is_err());
    }

    #[test]
    fn stale_or_failed_preparations_cannot_commit_the_previous_ready_frame() {
        let mut gate = PreparedGate::default();
        gate.stage(("ready-old", 320, 240));
        // A new preparation invalidates the old commit before it validates or
        // renders. Failure leaves the visible prior frame intact but not ready.
        gate.discard();
        let invalid_snapshot = "{";
        assert!(parse_snapshot(invalid_snapshot).is_err());
        assert!(gate.take_for_present().is_err());
        gate.stage(("stale-completed", 640, 480));
        // The caller's generation check may discard a completed stale render.
        gate.discard();
        assert!(gate.take_for_present().is_err());
        gate.stage(("current-completed", 800, 600));
        assert_eq!(
            gate.take_for_present().unwrap(),
            ("current-completed", 800, 600)
        );
    }
}

//! Native-window adapter for the same validated P0 scene and Vello GPU encoder
//! used by B4SurfaceRenderer. Surface acquisition/presentation remain host-owned.
use std::{collections::HashSet, time::Instant};

use serde::Serialize;
use serde_json::{Map, Value};
use vello::{AaConfig, AaSupport, RenderParams, Renderer, RendererOptions, Scene, kurbo::Affine};

use crate::{gpu_scene, image_atlas, image_resources, prepared_scene};

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct NativePaintReceipt {
    pub parse_prepare_ms: f64,
    pub scene_cache_hit: bool,
    pub encode_cache_hit: bool,
    pub atlas_upload_bytes: u64,
    pub atlas_full_uploads: u64,
    pub atlas_delta_uploads: u64,
    pub atlas_ms: f64,
    pub encode_ms: f64,
    pub vello_submit_ms: f64,
    pub total_ms: f64,
    pub operations: usize,
    pub image_operations: usize,
    pub image_resources: usize,
    pub atlas_uploads: u64,
    pub atlas_pages: usize,
    pub atlas_page_resource_counts: Vec<usize>,
    pub atlas_page_uploads: Vec<u64>,
    pub atlas_page_bytes: Vec<usize>,
    pub atlas_allocated_pages: usize,
    pub atlas_bytes: usize,
    pub atlas_reserved_pages: usize,
    pub atlas_reserved_bytes: usize,
    pub prefetched_resources: usize,
    pub prefetched_bytes: usize,
    pub gpu_allocation_status: &'static str,
    pub gpu_allocation_failure_flags: u32,
    pub gpu_allocation_status_bytes: usize,
    pub gpu_allocation_counts: Value,
}

pub struct NativeGpuRenderer {
    environment: Option<(String,prepared_scene::PreparedScene,Scene)>,
    #[cfg(feature="native-hybrid")]
    hybrid: Option<crate::native_hybrid::RetainedHybrid>,
    #[cfg(feature="native-hybrid")]
    hybrid_revision: u64,
    renderer: Renderer,
    encoded_source: Option<Scene>,
    encoded_atlas_versions: Vec<u64>,
    images: image_resources::ImageRegistry,
    atlases: Vec<image_atlas::GpuImageAtlas>,
    prepared: Option<RetainedPrepared>,
    prefetched: Vec<image_resources::ImageReference>,
    prefetch_generation: Option<(String, String)>,
    prefetched_scene: Option<RetainedPrepared>,
    prefetched_plans: Vec<image_atlas::AtlasPlan>,
    prefetched_atlases: Vec<image_atlas::GpuImageAtlas>,
    prefetched_upload: Option<PartialAtlasUpload>,
}

struct PartialAtlasUpload {
    atlas: image_atlas::GpuImageAtlas,
    pixels: Vec<u8>,
    next_row: u32,
}

struct RetainedPrepared {
    source_json: Option<String>,
    scene: prepared_scene::PreparedScene,
    envelope: Option<Map<String, Value>>,
    operations: Vec<Value>,
    resources: Vec<Value>,
}

enum PreparedChange {
    Vector {
        operation_index: usize,
        slot: usize,
        value: Value,
        paint: prepared_scene::PreparedVector,
    },
    Image {
        operation_index: usize,
        slot: usize,
        value: Value,
        paint: image_resources::PreparedImage,
    },
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct NativeDeltaReceipt {
    pub changed_operations: usize,
    pub prepare_ms: f64,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct NativeProfileStageReceipt {
    pub prepared: bool,
    pub uploaded_pages: usize,
    pub total_pages: usize,
    pub staged_rows: u32,
    pub elapsed_ms: f64,
}

fn operation_identity(operation: &Value) -> Option<&str> {
    if operation["type"] == "vector" {
        operation["object"]["id"].as_str()
    } else {
        operation["id"].as_str()
    }
}

fn checked_camera(
    device: &wgpu::Device,
    width: u32,
    height: u32,
    scale: f64,
    pan_x: f64,
    pan_y: f64,
) -> Result<Affine, String> {
    let input = crate::validate_frame(
        width,
        height,
        device.limits().max_texture_dimension_2d,
        scale,
        pan_x,
        pan_y,
    )?;
    if input.width != width || input.height != height {
        return Err("Native surface exceeds P0 frame dimension limit".into());
    }
    Ok(Affine::translate((pan_x, pan_y)) * Affine::scale(scale))
}

impl RetainedPrepared {
    fn from_source(source: &str, camera: Affine) -> Result<Self, String> {
        let mut snapshot = crate::parse_snapshot(source)?;
        let scene = prepared_scene::prepare_snapshot(&snapshot)?;
        prepared_scene::validate_camera(&scene, camera)?;
        let envelope = snapshot
            .as_object_mut()
            .ok_or("DISPLAY_LIST_INVALID: native snapshot must be an object")?;
        let operations = envelope
            .remove("operations")
            .and_then(|value| value.as_array().cloned())
            .ok_or("DISPLAY_LIST_INVALID: retained scene needs ordered operations")?;
        let resources = envelope
            .remove("resources")
            .and_then(|value| value.as_array().cloned())
            .ok_or("DISPLAY_LIST_INVALID: retained scene needs resource declarations")?;
        if operations.len() != scene.operations.len() {
            return Err("DISPLAY_LIST_INVALID: retained operation count changed".into());
        }
        Ok(Self {
            source_json: Some(source.to_owned()),
            scene,
            envelope: Some(envelope.clone()),
            operations,
            resources,
        })
    }

    fn apply_delta(
        &mut self,
        operations: &[Value],
        resources: &[Value],
        changed_indices: &[usize],
        camera: Affine,
    ) -> Result<NativeDeltaReceipt, String> {
        let started = Instant::now();
        let envelope = self
            .envelope
            .as_ref()
            .ok_or("SCENE_UNSUPPORTED: retained delta requires display-list v2")?;
        if resources != self.resources || operations.len() != self.operations.len() {
            return Err("SCENE_DELTA_REJECTED: resource or operation membership changed".into());
        }
        let supplied: HashSet<usize> = changed_indices.iter().copied().collect();
        if supplied.len() != changed_indices.len()
            || supplied.iter().any(|index| *index >= operations.len())
        {
            return Err("SCENE_DELTA_REJECTED: invalid changed-operation indices".into());
        }
        let actual = self
            .operations
            .iter()
            .zip(operations)
            .enumerate()
            .filter_map(|(index, (old, new))| (old != new).then_some(index))
            .collect::<HashSet<_>>();
        if !actual.is_subset(&supplied) {
            return Err(format!(
                "SCENE_DELTA_REJECTED: changed-operation indices omit paint (actual {}, supplied {}, first missing {:?})",
                actual.len(),
                supplied.len(),
                actual.difference(&supplied).next(),
            ));
        }
        let mut replacements = Vec::with_capacity(actual.len());
        for &index in changed_indices
            .iter()
            .filter(|index| actual.contains(index))
        {
            let old = &self.operations[index];
            let new = &operations[index];
            if old["type"] != new["type"] || operation_identity(old) != operation_identity(new) {
                return Err("SCENE_DELTA_REJECTED: operation identity/type changed".into());
            }
            let resource = match new["type"].as_str() {
                Some("vector") => Vec::new(),
                Some("image") => vec![new["resource"].clone()],
                _ => return Err("SCENE_DELTA_REJECTED: structural paint needs a full scene".into()),
            };
            let mut one = envelope.clone();
            one.insert("operations".into(), Value::Array(vec![new.clone()]));
            one.insert("resources".into(), Value::Array(resource));
            let prepared = prepared_scene::prepare_snapshot(&Value::Object(one))?;
            prepared_scene::validate_camera(&prepared, camera)?;
            match self.scene.operations[index] {
                prepared_scene::PreparedOp::Vector(slot) if prepared.vectors.len() == 1 => {
                    replacements.push(PreparedChange::Vector {
                        operation_index: index,
                        slot,
                        value: new.clone(),
                        paint: prepared.vectors.into_iter().next().unwrap(),
                    });
                }
                prepared_scene::PreparedOp::Image(slot) if prepared.images.len() == 1 => {
                    replacements.push(PreparedChange::Image {
                        operation_index: index,
                        slot,
                        value: new.clone(),
                        paint: prepared.images.into_iter().next().unwrap(),
                    });
                }
                _ => return Err("SCENE_DELTA_REJECTED: prepared paint slot changed".into()),
            }
        }
        // Validation above is atomic: one invalid connector cannot partially
        // replace a card or an earlier edge in the retained ordered scene.
        for replacement in replacements {
            match replacement {
                PreparedChange::Vector {
                    operation_index,
                    slot,
                    value,
                    paint,
                } => {
                    self.scene.vectors[slot] = paint;
                    self.operations[operation_index] = value;
                }
                PreparedChange::Image {
                    operation_index,
                    slot,
                    value,
                    paint,
                } => {
                    self.scene.images[slot] = paint;
                    self.operations[operation_index] = value;
                }
            }
        }
        self.source_json = None;
        Ok(NativeDeltaReceipt {
            changed_operations: actual.len(),
            prepare_ms: started.elapsed().as_secs_f64() * 1000.0,
        })
    }
}

impl NativeGpuRenderer {
    pub fn new(device: &wgpu::Device) -> Result<Self, String> {
        let renderer = Renderer::new(
            device,
            RendererOptions {
                use_cpu: false,
                antialiasing_support: AaSupport::area_only(),
                num_init_threads: None,
                pipeline_cache: None,
            },
        )
        .map_err(|error| format!("Vello pipeline setup failed: {error}"))?;
        Ok(Self {
            renderer,
            environment: None,
            #[cfg(feature="native-hybrid")]
            hybrid: None,
            #[cfg(feature="native-hybrid")]
            hybrid_revision: 0,
            images: image_resources::ImageRegistry::default(),
            encoded_source: None,
            encoded_atlas_versions: Vec::new(),
            atlases: Vec::new(),
            prepared: None,
            prefetched: Vec::new(),
            prefetch_generation: None,
            prefetched_scene: None,
            prefetched_plans: Vec::new(),
            prefetched_atlases: Vec::new(),
            prefetched_upload: None,
        })
    }

    pub fn register_image(&mut self, reference_json: &str, pixels: Vec<u8>) -> Result<(), String> {
        let value: serde_json::Value = serde_json::from_str(reference_json)
            .map_err(|error| format!("RESOURCE_INVALID: image JSON: {error}"))?;
        let reference = image_resources::parse_reference(&value)?;
        self.images.register(reference, pixels)?;
        Ok(())
    }
    /// Small camera-dependent grid/background paint; the retained card scene
    /// stays untouched. Both are presented together to avoid a second surface.
    pub fn set_environment(&mut self,snapshot:&str)->Result<(),String>{
        if self.environment.as_ref().is_some_and(|(source,_,_)|source==snapshot){return Ok(())}
        if snapshot.len()>256*1024{return Err("Environment snapshot exceeds bounded size".into())}
        let value:Value=serde_json::from_str(snapshot).map_err(|e|e.to_string())?;
        let prepared=prepared_scene::prepare_snapshot(&value)?;
        if !prepared.images.is_empty(){return Err("Environment cannot own image resources".into())}
        let encoded=gpu_scene::encode_prepared_with_images(&prepared,None)?;
        self.environment=Some((snapshot.to_owned(),prepared,encoded));
        #[cfg(feature="native-hybrid")]
        {self.hybrid_revision=self.hybrid_revision.wrapping_add(1);}
        Ok(())
    }

    /// The host can stage only the resources needed by the next visible
    /// viewport. Entries may be pruned after a successful frame, so query
    /// immediately before admitting a profile's decoded pixels.
    pub fn has_image(&self, key: &str, revision: u64) -> bool {
        self.images.contains(&(key.to_owned(), revision))
    }

    /// Pin already admitted, verified profile pixels across frames while a
    /// higher-resolution native profile is staged. The normal registry budget
    /// and exact reference validation still apply at registration.
    pub fn set_prefetched_references(&mut self, values: &[Value]) -> Result<(), String> {
        if values.len() > 1024 {
            return Err("RESOURCE_BUDGET_EXCEEDED: too many prefetched references".into());
        }
        let prepared = self
            .prepared
            .as_ref()
            .ok_or("SCENE_NOT_READY: prefetch needs a base scene")?;
        let envelope = prepared
            .envelope
            .as_ref()
            .ok_or("SCENE_UNSUPPORTED: native prefetch needs display-list v2")?;
        let generation = (
            envelope
                .get("sceneId")
                .and_then(Value::as_str)
                .ok_or("DISPLAY_LIST_INVALID: sceneId absent")?
                .to_owned(),
            envelope
                .get("revision")
                .and_then(Value::as_str)
                .ok_or("DISPLAY_LIST_INVALID: revision absent")?
                .to_owned(),
        );
        let mut identities = HashSet::with_capacity(values.len());
        let mut references = Vec::with_capacity(values.len());
        for value in values {
            let reference = image_resources::parse_reference(value)?;
            if !identities.insert((reference.key.clone(), reference.revision)) {
                return Err("RESOURCE_INVALID: duplicate prefetched reference".into());
            }
            self.images.resolve(&reference)?;
            references.push(reference);
        }
        self.prefetched = references;
        self.prefetch_generation = Some(generation);
        Ok(())
    }

    /// Prepare one upcoming profile stage per idle call. The first call
    /// validates/compiles the scene and packs the complete resource set;
    /// later calls upload at most one 2048² page each. Until every page is
    /// ready, normal rendering keeps the previous complete profile.
    #[allow(clippy::too_many_arguments)]
    pub fn stage_next_profile_page(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        snapshot_json: &str,
        width: u32,
        height: u32,
        scale: f64,
        pan_x: f64,
        pan_y: f64,
    ) -> Result<NativeProfileStageReceipt, String> {
        let started = Instant::now();
        let camera = checked_camera(device, width, height, scale, pan_x, pan_y)?;
        if self
            .prefetched_scene
            .as_ref()
            .is_none_or(|scene| scene.source_json.as_deref() != Some(snapshot_json))
        {
            let next = RetainedPrepared::from_source(snapshot_json, camera)?;
            let decoded = next
                .scene
                .resources
                .iter()
                .map(|reference| self.images.resolve(reference))
                .collect::<Result<Vec<_>, _>>()?;
            let plans = image_atlas::pack_native_pages(decoded)?;
            if self.atlases.len() + plans.len() > image_atlas::MAX_NATIVE_ATLAS_PAGES {
                return Err("GPU_IMAGE_ATLAS_FULL: active plus prefetched profile exceeds native page budget".into());
            }
            self.prefetched_atlases.clear();
            self.prefetched_upload = None;
            self.prefetched_scene = Some(next);
            self.prefetched_plans = plans;
            return Ok(NativeProfileStageReceipt {
                prepared: true,
                uploaded_pages: 0,
                total_pages: self.prefetched_plans.len(),
                staged_rows: 0,
                elapsed_ms: started.elapsed().as_secs_f64() * 1000.0,
            });
        }
        let page_index = self.prefetched_atlases.len();
        if self.prefetched_upload.is_none() {
            if let Some(plan) = self.prefetched_plans.get(page_index) {
                let atlas = image_atlas::GpuImageAtlas::new_native_page(
                    device,
                    &mut self.renderer,
                    image_atlas::MAX_NATIVE_ATLAS_PAGES - self.prefetched_plans.len() + page_index,
                )?;
                self.prefetched_upload = Some(PartialAtlasUpload {
                    atlas,
                    pixels: plan.pixels(),
                    next_row: 0,
                });
            }
        } else if let Some(upload) = self.prefetched_upload.as_mut() {
            let rows = (image_atlas::ATLAS_EDGE - upload.next_row).min(256);
            upload
                .atlas
                .upload_rows(queue, &upload.pixels, upload.next_row, rows)?;
            upload.next_row += rows;
            if upload.next_row == image_atlas::ATLAS_EDGE {
                let mut complete = self.prefetched_upload.take().expect("staged upload exists");
                complete
                    .atlas
                    .finish_staged(&self.prefetched_plans[page_index], &mut self.renderer);
                self.prefetched_atlases.push(complete.atlas);
            }
        }
        Ok(NativeProfileStageReceipt {
            prepared: true,
            uploaded_pages: self.prefetched_atlases.len(),
            total_pages: self.prefetched_plans.len(),
            staged_rows: self
                .prefetched_upload
                .as_ref()
                .map_or(0, |upload| upload.next_row),
            elapsed_ms: started.elapsed().as_secs_f64() * 1000.0,
        })
    }

    pub fn render_to_texture(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        target: &wgpu::TextureView,
        width: u32,
        height: u32,
        snapshot_json: &str,
        scale: f64,
        pan_x: f64,
        pan_y: f64,
    ) -> Result<NativePaintReceipt, String> {
        let start = Instant::now();
        let camera = checked_camera(device, width, height, scale, pan_x, pan_y)?;
        let prefetched_complete = !self.prefetched_plans.is_empty()
            && self.prefetched_atlases.len() == self.prefetched_plans.len();
        let prefetched_match = self
            .prefetched_scene
            .as_ref()
            .is_some_and(|scene| scene.source_json.as_deref() == Some(snapshot_json));
        if prefetched_match && (prefetched_complete || self.prefetched_plans.is_empty()) {
            #[cfg(feature="native-hybrid")]
            { self.hybrid_revision = self.hybrid_revision.wrapping_add(1); }
            self.encoded_source = None;
            std::mem::swap(&mut self.prepared, &mut self.prefetched_scene);
            std::mem::swap(&mut self.atlases, &mut self.prefetched_atlases);
            self.prefetched_plans.clear();
        }
        let scene_cache_hit = self
            .prepared
            .as_ref()
            .is_some_and(|prepared| prepared.source_json.as_deref() == Some(snapshot_json));
        if !scene_cache_hit {
            #[cfg(feature="native-hybrid")]
            { self.hybrid_revision = self.hybrid_revision.wrapping_add(1); }
            // Parse and validate the replacement before replacing the last
            // complete scene. A rejected edit must not poison later camera
            // redraws of the previously accepted snapshot.
            let next = RetainedPrepared::from_source(snapshot_json, camera)?;
            if self
                .prefetch_generation
                .as_ref()
                .is_some_and(|(scene_id, revision)| {
                    next.envelope.as_ref().is_none_or(|envelope| {
                        envelope.get("sceneId").and_then(Value::as_str) != Some(scene_id)
                            || envelope.get("revision").and_then(Value::as_str) != Some(revision)
                    })
                })
            {
                self.prefetched.clear();
                self.prefetch_generation = None;
            }
            self.encoded_source = None;
            self.prepared = Some(next);
            self.prefetched_scene = None;
            self.prefetched_plans.clear();
            self.prefetched_atlases.clear();
            self.prefetched_upload = None;
        }
        prepared_scene::validate_camera(
            &self.prepared.as_ref().expect("scene was prepared").scene,
            camera,
        )?;
        self.paint_prepared_to_texture(
            device,
            queue,
            target,
            width,
            height,
            camera,
            start,
            scene_cache_hit,
        )
    }

    /// Apply a bounded edit to the already validated ordered paint list. The
    /// caller retains the authoritative scene model and supplies its exact
    /// changed indices; undeclared changes and structural edits are rejected.
    pub fn apply_operation_delta(
        &mut self,
        device: &wgpu::Device,
        width: u32,
        height: u32,
        operations: &[Value],
        resources: &[Value],
        changed_indices: &[usize],
        scale: f64,
        pan_x: f64,
        pan_y: f64,
    ) -> Result<NativeDeltaReceipt, String> {
        let camera = checked_camera(device, width, height, scale, pan_x, pan_y)?;
        let receipt = self
            .prepared
            .as_mut()
            .ok_or("SCENE_DELTA_REJECTED: no validated base scene")?
            .apply_delta(operations, resources, changed_indices, camera)?;
        if receipt.changed_operations > 0 {
            #[cfg(feature="native-hybrid")]
            { self.hybrid_revision = self.hybrid_revision.wrapping_add(1); }
            self.encoded_source = None;
            // A warmed sibling profile has the prior card/edge geometry.
            // It must be rebuilt from the updated model before any switch.
            self.prefetched_scene = None;
            self.prefetched_plans.clear();
            self.prefetched_atlases.clear();
            self.prefetched_upload = None;
        }
        Ok(receipt)
    }

    /// Draw the last retained scene after an accepted delta or camera update.
    #[cfg(feature="native-hybrid")]
    pub fn warm_hybrid(&mut self,device:&wgpu::Device,width:u32,height:u32) {
        self.hybrid.get_or_insert_with(||crate::native_hybrid::RetainedHybrid::new(device,width,height));
    }

    #[cfg(feature="native-hybrid")]
    pub fn render_retained_hybrid_to_texture(&mut self, device:&wgpu::Device,queue:&wgpu::Queue,
        target:&wgpu::TextureView,width:u32,height:u32,scale:f64,pan_x:f64,pan_y:f64)->Result<Value,String>{
        let camera=checked_camera(device,width,height,scale,pan_x,pan_y)?;
        let prepared=&self.prepared.as_ref().ok_or("SCENE_NOT_READY: no native retained scene")?.scene;
        prepared_scene::validate_camera(prepared,camera)?;
        let hybrid=self.hybrid.get_or_insert_with(||crate::native_hybrid::RetainedHybrid::new(device,width,height));
        hybrid.render(device,queue,target,prepared,self.environment.as_ref().map(|(_,p,_)|p),&self.atlases,self.hybrid_revision,width,height,camera)
    }

    /// Draw the last retained scene after an accepted delta or camera update.
    pub fn render_retained_to_texture(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        target: &wgpu::TextureView,
        width: u32,
        height: u32,
        scale: f64,
        pan_x: f64,
        pan_y: f64,
    ) -> Result<NativePaintReceipt, String> {
        let start = Instant::now();
        let camera = checked_camera(device, width, height, scale, pan_x, pan_y)?;
        prepared_scene::validate_camera(
            &self
                .prepared
                .as_ref()
                .ok_or("SCENE_NOT_READY: retained paint is empty")?
                .scene,
            camera,
        )?;
        self.paint_prepared_to_texture(device, queue, target, width, height, camera, start, true)
    }

    #[allow(clippy::too_many_arguments)]
    fn paint_prepared_to_texture(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        target: &wgpu::TextureView,
        width: u32,
        height: u32,
        camera: Affine,
        start: Instant,
        scene_cache_hit: bool,
    ) -> Result<NativePaintReceipt, String> {
        let prepared = &self.prepared.as_ref().expect("scene was prepared").scene;
        let prepared_at = Instant::now();

        let attempt = (|| {
            let decoded = prepared
                .resources
                .iter()
                .map(|reference| self.images.resolve(reference))
                .collect::<Result<Vec<_>, _>>()?;
            let plans = image_atlas::pack_native_pages(decoded)?;
            let mut staged = prepared.resources.clone();
            staged.extend(
                self.prefetched
                    .iter()
                    .filter(|reference| !prepared.resources.contains(reference))
                    .cloned(),
            );
            self.images.stage(&staged)?;
            while self.atlases.len() < plans.len() {
                let page_index = self.atlases.len();
                self.atlases
                    .push(image_atlas::GpuImageAtlas::new_native_page(
                        device,
                        &mut self.renderer,
                        page_index,
                    )?);
            }
            for (atlas, plan) in self.atlases.iter_mut().zip(&plans) {
                atlas.update(plan, queue, &mut self.renderer);
            }
            let atlas_at = Instant::now();
            let pages = self
                .atlases
                .iter()
                .zip(&plans)
                .map(|(atlas, plan)| (&atlas.image, plan))
                .collect::<Vec<_>>();
            // Camera updates reuse validated local-space encoding. Atlas uploads
            // may alter image placement, so their exact versions revoke it.
            let atlas_versions = self.atlases.iter().take(plans.len()).map(|atlas| atlas.uploads).collect::<Vec<_>>();
            let encode_cache_hit = self.encoded_source.is_some() && atlas_versions == self.encoded_atlas_versions;
            if !encode_cache_hit {
                let source = gpu_scene::encode_prepared_with_image_pages(&prepared, &pages)?;
                self.encoded_source = Some(source);
                self.encoded_atlas_versions = atlas_versions;
            }
            let mut scene = Scene::new();
            if let Some((_,_,environment))=&self.environment{scene.append(environment,Some(camera));}
            scene.append(self.encoded_source.as_ref().expect("source encoded"), Some(camera));
            let encoded_at = Instant::now();
            let allocation = self.renderer
                .render_to_texture_checked_sync(
                    device,
                    queue,
                    &scene,
                    target,
                    &RenderParams {
                        base_color: self.environment.as_ref().map(|(_,environment,_)|environment.background).unwrap_or(prepared.background),
                        width,
                        height,
                        antialiasing_method: AaConfig::Area,
                    },
                )
                .map_err(|error| format!("Vello render failed: {error}"))?;
            let submitted_at = Instant::now();
            Ok(NativePaintReceipt {
                parse_prepare_ms: (prepared_at - start).as_secs_f64() * 1000.0,
                scene_cache_hit,
                encode_cache_hit,
                atlas_upload_bytes: self.atlases.iter().map(|atlas| atlas.upload_bytes).sum(),
                atlas_full_uploads: self.atlases.iter().map(|atlas| atlas.full_uploads).sum(),
                atlas_delta_uploads: self.atlases.iter().map(|atlas| atlas.delta_uploads).sum(),
                atlas_ms: (atlas_at - prepared_at).as_secs_f64() * 1000.0,
                encode_ms: (encoded_at - atlas_at).as_secs_f64() * 1000.0,
                vello_submit_ms: (submitted_at - encoded_at).as_secs_f64() * 1000.0,
                total_ms: (submitted_at - start).as_secs_f64() * 1000.0,
                operations: prepared.operations.len(),
                image_operations: prepared.images.len(),
                image_resources: prepared.resources.len(),
                atlas_uploads: self.atlases.iter().map(|atlas| atlas.uploads).sum(),
                atlas_pages: plans.len(),
                atlas_page_resource_counts: plans.iter().map(|plan| plan.images.len()).collect(),
                atlas_page_uploads: self.atlases.iter().map(|atlas| atlas.uploads).collect(),
                atlas_page_bytes: self
                    .atlases
                    .iter()
                    .map(|_| image_atlas::ATLAS_BYTES)
                    .collect(),
                atlas_allocated_pages: self.atlases.len(),
                atlas_bytes: self.atlases.len() * image_atlas::ATLAS_BYTES,
                atlas_reserved_pages: self.atlases.len()
                    + self.prefetched_atlases.len()
                    + usize::from(self.prefetched_upload.is_some()),
                atlas_reserved_bytes: (self.atlases.len()
                    + self.prefetched_atlases.len()
                    + usize::from(self.prefetched_upload.is_some()))
                    * image_atlas::ATLAS_BYTES,
                prefetched_resources: self.prefetched.len(),
                prefetched_bytes: self
                    .prefetched
                    .iter()
                    .map(|reference| reference.width as usize * reference.height as usize * 4)
                    .sum(),
                gpu_allocation_status: "checked",
                gpu_allocation_failure_flags: allocation.failed,
                gpu_allocation_status_bytes: 32,
                gpu_allocation_counts: serde_json::json!({
                    "failed": allocation.failed, "binning": allocation.binning,
                    "ptcl": allocation.ptcl, "tile": allocation.tile,
                    "segCounts": allocation.seg_counts, "segments": allocation.segments,
                    "blend": allocation.blend, "lines": allocation.lines,
                }),
            })
        })();
        if attempt.is_ok() {
            self.images.present();
        } else {
            self.images.discard();
        }
        attempt
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn retained_vector_delta_updates_only_its_slot_and_rejects_omissions_atomically() {
        let source = json!({
            "schema":"art-equation.display-list", "schemaVersion":2,
            "sceneId":"delta-test", "revision":"1",
            "environment":{"background":"#00000000","colorSpace":"srgb"},
            "resources":[],
            "operations":[
                {"type":"vector","object":{"id":"card","kind":"vector","order":0,
                    "transform":[1,0,0,1,0,0],"payload":{"commands":[["M",0,0],["L",8,0],["L",8,8],["Z"]],"fill":"#ff0000","strokeWidth":0}}},
                {"type":"vector","object":{"id":"edge","kind":"vector","order":1,
                    "transform":[1,0,0,1,0,0],"payload":{"commands":[["M",8,8],["L",16,16]],"fill":"#00000000","stroke":"#ffffff","strokeWidth":1}}}
            ]
        });
        let mut retained =
            RetainedPrepared::from_source(&source.to_string(), Affine::IDENTITY).unwrap();
        let old_edge = retained.operations[1].clone();
        let mut changed = retained.operations.clone();
        changed[0]["object"]["transform"] = json!([1, 0, 0, 1, 3, 4]);
        assert!(
            retained
                .apply_delta(&changed, &[], &[], Affine::IDENTITY)
                .is_err()
        );
        assert_eq!(retained.operations[0], source["operations"][0]);
        let receipt = retained
            .apply_delta(&changed, &[], &[0], Affine::IDENTITY)
            .unwrap();
        assert_eq!(receipt.changed_operations, 1);
        assert_eq!(retained.scene.vectors.len(), 2);
        assert_eq!(
            retained.scene.vectors[0].transform.as_coeffs()[4..],
            [3.0, 4.0]
        );
        assert_eq!(retained.operations[1], old_edge);
        assert!(retained.source_json.is_none());
        let mut malformed = changed.clone();
        malformed[1]["object"]["payload"]["commands"] = json!([["L", 0, 0]]);
        assert!(
            retained
                .apply_delta(&malformed, &[], &[1], Affine::IDENTITY)
                .is_err()
        );
        assert_eq!(retained.operations[1], old_edge);
    }
}

//! Hybrid reuses Classic's validated geometry and premultiplied atlas textures.
//! No second decode, JSON parse, CPU pixel copy, or Hybrid image upload.
use crate::{
    image_atlas::GpuImageAtlas,
    prepared_scene::{PreparedOp, PreparedScene, PreparedScopeKind},
};
#[cfg(not(target_arch="wasm32"))]
fn clock_ms()->f64 {static ORIGIN:std::sync::OnceLock<std::time::Instant>=std::sync::OnceLock::new();ORIGIN.get_or_init(std::time::Instant::now).elapsed().as_secs_f64()*1000.}
#[cfg(target_arch="wasm32")]
#[wasm_bindgen::prelude::wasm_bindgen]
extern "C" {#[wasm_bindgen::prelude::wasm_bindgen(js_namespace=performance,js_name=now)]fn clock_ms()->f64;}
use vello_common::{
    geometry::RectU16,
    kurbo::{Affine, Rect, Shape},
    peniko::{BlendMode, Compose, Fill, Mix},
};
use vello_hybrid::{Renderer, Resources, SampleRect, Scene, TextureBindings, TextureId};

#[derive(PartialEq)]
struct Key {
    revision: u64,
    width: u32,
    height: u32,
    camera: [u64; 6],
    atlases: Vec<u64>,
}
pub(crate) struct RetainedHybrid {
    renderer: Renderer,
    resources: Resources,
    scene: Option<Scene>,
    key: Option<Key>,
    bindings: TextureBindings,
}
impl RetainedHybrid {
    pub fn new(device: &wgpu::Device, width: u32, height: u32) -> Self {
        let (renderer, resources) = Renderer::new(
            device,
            &vello_hybrid::RenderTargetConfig {
                format: wgpu::TextureFormat::Rgba8Unorm,
                width,
                height,
            },
        );
        Self {
            renderer,
            resources,
            scene: None,
            key: None,
            bindings: TextureBindings::new(),
        }
    }
    pub fn render(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        target: &wgpu::TextureView,
        prepared: &PreparedScene,
        environment: Option<&PreparedScene>,
        atlases: &[GpuImageAtlas],
        revision: u64,
        width: u32,
        height: u32,
        camera: Affine,
    ) -> Result<serde_json::Value, String> {
        let start = clock_ms();
        if width == 0 || height == 0 || width > 4096 || height > 4096 {
            return Err("HYBRID_UNSUPPORTED: bounded target required".into());
        }
        // Reject before touching the retained scene. Classic remains authoritative
        // for paint kinds whose parity has not been checked in this adapter.
        for op in environment.into_iter().flat_map(|p|p.operations.iter()).chain(prepared.operations.iter()) {
            match op {
                PreparedOp::Gradient(_) | PreparedOp::Shadow(_) => {
                    return Err("HYBRID_UNSUPPORTED: gradient/shadow parity pending".into())
                }
                PreparedOp::Scope(s)
                    if s.blend.compose != Compose::SrcOver
                        || !matches!(s.blend.mix, Mix::Normal | Mix::Multiply | Mix::Screen) =>
                {
                    return Err("HYBRID_UNSUPPORTED: blend parity pending".into())
                }
                _ => {}
            }
        }
        let key = Key {
            revision,
            width,
            height,
            camera: camera.as_coeffs().map(f64::to_bits),
            atlases: atlases.iter().map(|a| a.uploads).collect(),
        };
        let cached = self.key.as_ref() == Some(&key);
        if !cached {
            let mut scene = Scene::new(width as u16, height as u16);
            scene.set_paint(environment.map(|p|p.background).unwrap_or(prepared.background));
            scene.fill_rect(&Rect::new(0., 0., width as f64, height as f64));
            for prepared in environment.into_iter().chain(std::iter::once(prepared)) {
            for op in &prepared.operations {
                match op {
                    PreparedOp::Vector(index) => {
                        let o = &prepared.vectors[*index];
                        scene.set_transform(camera * o.transform);
                        scene.reset_paint_transform();
                        scene.set_fill_rule(o.fill_rule);
                        if o.opacity < 1. {
                            scene.push_layer(
                                Some(&o.opacity_clip.to_path(0.1)),
                                Some(BlendMode::default()),
                                Some(o.opacity),
                                None,
                                None,
                            )
                        }
                        scene.set_paint(o.fill);
                        scene.fill_path(&o.path);
                        if let Some(path) = &o.stroke_path {
                            scene.set_stroke(o.stroke.clone());
                            scene.set_paint(o.stroke_color);
                            scene.stroke_path(path)
                        }
                        if o.opacity < 1. {
                            scene.pop_layer()
                        }
                    }
                    PreparedOp::Image(index) => {
                        let i = &prepared.images[*index];
                        let (page, (x, y)) = atlases
                            .iter()
                            .enumerate()
                            .find_map(|(page, a)| {
                                a.shared_slot(&i.resource).map(|slot| (page, slot))
                            })
                            .ok_or("HYBRID_RESOURCE_NOT_READY: atlas slot missing")?;
                        scene.set_transform(camera * i.transform);
                        scene.set_fill_rule(Fill::NonZero);
                        // Clip the full resource to the authored fractional crop;
                        // external SampleRect itself uses integer texel regions.
                        scene.push_clip_layer(&i.source.to_path(0.1));
                        if i.opacity < 1. {
                            scene.push_opacity_layer(i.opacity)
                        }
                        let rect = RectU16::new(
                            x as u16,
                            y as u16,
                            (x + i.resource.width) as u16,
                            (y + i.resource.height) as u16,
                        );
                        scene.draw_texture_rects(
                            TextureId(page as u64),
                            i.quality,
                            [SampleRect {
                                source_region: rect,
                                transform: Affine::IDENTITY,
                            }],
                        );
                        if i.opacity < 1. {
                            scene.pop_layer()
                        }
                        scene.pop_layer();
                    }
                    PreparedOp::Scope(s) => {
                        scene.set_transform(camera * s.transform);
                        scene.set_fill_rule(s.fill_rule);
                        if s.kind == PreparedScopeKind::Clip {
                            scene.push_clip_layer(&s.path)
                        } else {
                            scene.push_layer(
                                Some(&s.path),
                                Some(s.blend),
                                Some(s.opacity),
                                None,
                                None,
                            )
                        }
                    }
                    PreparedOp::Pop => scene.pop_layer(),
                    _ => unreachable!("eligibility checked"),
                }
            }
            }
            self.bindings = TextureBindings::new();
            for (index, atlas) in atlases.iter().enumerate() {
                self.bindings
                    .insert(TextureId(index as u64), atlas.shared_view());
            }
            self.scene = Some(scene);
            self.key = Some(key);
        }
        let encode_ms = clock_ms()-start;
        let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
            label: Some("Hybrid shared native target"),
        });
        self.renderer
            .render(
                self.scene.as_ref().expect("encoded scene"),
                &mut self.resources,
                device,
                queue,
                &mut encoder,
                &vello_hybrid::RenderSize { width, height },
                target,
                &self.bindings,
            )
            .map_err(|e| format!("Hybrid render: {e:?}"))?;
        queue.submit([encoder.finish()]);
        Ok(
            serde_json::json!({"backend":"hybrid-0.2","encodeCacheHit":cached,"encodeMs":encode_ms,
            "submitElapsedMs":clock_ms()-start,"sharedImagePages":atlases.len(),
            "hybridImageUploadBytes":0,"sceneParses":0,"pixelReadbacks":0,
            "timingScope":"CPU encode and submission; excludes GPU completion"}),
        )
    }
}

//! Versioned paint derivative: ordered primitives and explicitly isolated scopes.
//! Neither ownership nor transforms are inferred from canonical parent metadata.
use crate::EncodingReport;
use crate::prepared_scene::{
    PreparedOp, PreparedScene, PreparedScope, PreparedScopeKind, object_path, object_transform, optional_number,
    optional_style, paint_color, prepare_snapshot, validate_transformed_path, PreparedGradient, PreparedShadow,
};
use serde_json::{Value, json};
use std::collections::HashSet;
use crate::image_resources::{parse_reference, PreparedImage};
use vello::kurbo::{Rect, Shape, Point};
use vello::peniko::{ImageQuality,Gradient,InterpolationAlphaSpace};
use vello_cpu::peniko::{BlendMode, Compose, Fill, Mix};

const MAX_OPERATIONS: usize = 100_000;
const MAX_SCOPE_DEPTH: usize = 32;
const MAX_COMMANDS: usize = 1_000_000;

fn fields(value: &Value, allowed: &[&str]) -> Result<(), String> {
    let map = value
        .as_object()
        .ok_or("DISPLAY_LIST_INVALID: operation must be an object")?;
    for name in map.keys() {
        if !allowed.contains(&name.as_str()) {
            return Err(format!("SCENE_UNSUPPORTED: display-list field {name}"));
        }
    }
    Ok(())
}

fn identity<'a>(value: &'a Value, key: &str) -> Result<&'a str, String> {
    value[key]
        .as_str()
        .filter(|v| !v.is_empty() && v.len() <= 1024)
        .ok_or_else(|| format!("DISPLAY_LIST_INVALID: {key} must be a bounded nonempty string"))
}

pub(super) fn prepare_display_list(snapshot: &Value) -> Result<PreparedScene, String> {
    if snapshot["schemaVersion"] != 2 {
        return Err("DISPLAY_LIST_INVALID: expected schemaVersion 2".into());
    }
    fields(
        snapshot,
        &[
            "schema",
            "schemaVersion",
            "sceneId",
            "revision",
            "environment",
            "operations",
            "resources",
        ],
    )?;
    identity(snapshot, "sceneId")?;
    identity(snapshot, "revision")?;
    fields(&snapshot["environment"], &["background", "colorSpace"])?;
    if snapshot["environment"]["colorSpace"] != "srgb" {
        return Err("SCENE_UNSUPPORTED: display-list colour space must be srgb".into());
    }
    let source_resources = snapshot["resources"]
        .as_array()
        .ok_or("DISPLAY_LIST_INVALID: resources must be an array")?;
    if source_resources.len()>1024 {
        return Err("RESOURCE_BUDGET_EXCEEDED: display list exceeds 1024 image references".into());
    }
    let resources=source_resources.iter().map(parse_reference).collect::<Result<Vec<_>,_>>()?;
    let mut resource_indices = std::collections::HashMap::with_capacity(resources.len());
    for (idx, resource) in resources.iter().enumerate() {
        if resource_indices.insert((resource.key.clone(), resource.revision), idx).is_some() {
            return Err("RESOURCE_INVALID: duplicate declared image identity".into());
        }
    }
    let source = snapshot["operations"]
        .as_array()
        .ok_or("DISPLAY_LIST_INVALID: operations must be an array")?;
    if source.len() > MAX_OPERATIONS {
        return Err("SCENE_RESOURCE_LIMIT: display-list exceeds 100000 operations".into());
    }
    let background = paint_color(&snapshot["environment"]["background"], "#00000000")?;
    let mut operations = Vec::with_capacity(source.len());
    let mut vectors = Vec::new();
    let mut images = Vec::new();
    let mut stack = Vec::new();
    let mut scopes = HashSet::new();
    let mut objects = HashSet::new();
    let mut command_count = 0_usize;
    for (index, operation) in source.iter().enumerate() {
        let fail = |message: String| format!("operation {index}: {message}");
        match operation["type"].as_str() {
            Some("gradient") => {
                fields(operation,&["type","id","commands","transform","brushTransform","fillRule","gradient"]).map_err(fail)?;
                let id=identity(operation,"id").map_err(fail)?;
                if !objects.insert(id) {return Err(fail("DISPLAY_LIST_INVALID: duplicate primitive identity".into()));}
                if !operation["transform"].is_array() || !operation["brushTransform"].is_array() {return Err(fail("PAINT_INVALID: explicit gradient matrices required".into()));}
                let transform=object_transform(operation).map_err(fail)?;
                let brush_transform=object_transform(&json!({"transform":operation["brushTransform"]})).map_err(fail)?;
                if brush_transform.determinant().abs()<1e-12 {return Err(fail("PAINT_INVALID: singular gradient brush matrix".into()));}
                let path=object_path(&json!({"payload":{"commands":operation["commands"]}}),&mut command_count).map_err(fail)?;
                validate_transformed_path(&path,transform).map_err(fail)?;
                let fill_rule=match operation["fillRule"].as_str(){Some("nonzero")=>Fill::NonZero,Some("evenodd")=>Fill::EvenOdd,_=>return Err(fail("PAINT_INVALID: explicit fill rule required".into()))};
                let g=&operation["gradient"];
                fields(g,&["kind","start","end","center","radius","stops","interpolation","alphaInterpolation"]).map_err(fail)?;
                if g["interpolation"]!="srgb" || g["alphaInterpolation"]!="premultiplied" {return Err(fail("PAINT_UNSUPPORTED: gradient colour convention must be explicit sRGB premultiplied".into()));}
                let point=|name:&str|->Result<Point,String>{let a=g[name].as_array().filter(|a|a.len()==2).ok_or("PAINT_INVALID: gradient point must have2 coordinates")?;
                    let x=a[0].as_f64().filter(|n|n.is_finite()&&n.abs()<=1e9).ok_or("PAINT_INVALID: gradient coordinate")?;
                    let y=a[1].as_f64().filter(|n|n.is_finite()&&n.abs()<=1e9).ok_or("PAINT_INVALID: gradient coordinate")?;Ok(Point::new(x,y))};
                let gradient=match g["kind"].as_str(){
                    Some("linear")=>{if !g["center"].is_null() || !g["radius"].is_null(){return Err(fail("PAINT_INVALID: linear gradient fields".into()));}
                        let start=point("start").map_err(fail)?;let end=point("end").map_err(fail)?;
                        if start.distance(end)<1e-9{return Err(fail("PAINT_INVALID: coincident gradient endpoints".into()));}Gradient::new_linear(start,end)},
                    Some("radial")=>{if !g["start"].is_null() || !g["end"].is_null(){return Err(fail("PAINT_INVALID: radial gradient fields".into()));}
                        let radius=g["radius"].as_f64().filter(|n|n.is_finite()&&*n>0.0&&*n<=1e9).ok_or_else(||fail("PAINT_INVALID: radial radius".into()))?;
                        Gradient::new_radial(point("center").map_err(fail)?,radius as f32)},
                    _=>return Err(fail("PAINT_UNSUPPORTED: gradient kind".into())),
                };
                let stops=g["stops"].as_array().filter(|s|s.len()>=2&&s.len()<=256).ok_or_else(||fail("PAINT_INVALID: gradient needs2..256 stops".into()))?;
                let mut resolved=Vec::new();let mut previous=-1.0;
                for stop in stops {fields(stop,&["offset","color"]).map_err(fail)?;
                    let offset=stop["offset"].as_f64().filter(|n|n.is_finite()&&*n>=previous&&*n>=0.0&&*n<=1.0).ok_or_else(||fail("PAINT_INVALID: gradient stops must be ordered0..1".into()))?;
                    if !stop["color"].is_string(){return Err(fail("PAINT_INVALID: explicit gradient color required".into()));}
                    resolved.push((offset as f32,paint_color(&stop["color"],"#00000000").map_err(fail)?));previous=offset;
                }
                operations.push(PreparedOp::Gradient(PreparedGradient{path,transform,brush_transform,fill_rule,
                    gradient:gradient.with_interpolation_alpha_space(InterpolationAlphaSpace::Premultiplied).with_stops(resolved.as_slice())}));
            }
            Some("blurredRoundedRect") => {
                fields(operation,&["type","id","rect","radius","stdDeviation","color","transform"]).map_err(fail)?;
                let id=identity(operation,"id").map_err(fail)?;
                if !objects.insert(id){return Err(fail("DISPLAY_LIST_INVALID: duplicate primitive identity".into()));}
                fields(&operation["rect"],&["x","y","width","height"]).map_err(fail)?;
                let r=&operation["rect"];
                let number=|key:&str|->Result<f64,String>{r[key].as_f64().filter(|n|n.is_finite()&&n.abs()<=1e9).ok_or_else(||format!("PAINT_INVALID: shadow rect.{key}"))};
                let x=number("x").map_err(fail)?;let y=number("y").map_err(fail)?;let w=number("width").map_err(fail)?;let h=number("height").map_err(fail)?;
                if w<=0.0||h<=0.0{return Err(fail("PAINT_INVALID: positive shadow rectangle required".into()));}
                let rect=Rect::new(x,y,x+w,y+h);
                let radius=operation["radius"].as_f64().filter(|n|n.is_finite()&&*n>=0.0&&*n<=w.min(h)/2.0).ok_or_else(||fail("PAINT_INVALID: shadow circular radius".into()))?;
                let std_dev=operation["stdDeviation"].as_f64().filter(|n|n.is_finite()&&*n>=0.0&&*n<=2048.0).ok_or_else(||fail("PAINT_INVALID: shadow stdDeviation".into()))?;
                if !operation["transform"].is_array() || !operation["color"].is_string(){return Err(fail("PAINT_INVALID: explicit shadow matrix/color required".into()));}
                let transform=object_transform(operation).map_err(fail)?;
                validate_transformed_path(&rect.inflate(2.5*std_dev,2.5*std_dev).to_path(0.05),transform).map_err(fail)?;
                let color=paint_color(&operation["color"],"#00000000").map_err(fail)?;
                operations.push(PreparedOp::Shadow(PreparedShadow{rect,radius,std_dev,color,transform}));
            }
            Some("image") => {
                if objects.len() >= 50_000 {
                    return Err("SCENE_RESOURCE_LIMIT: display-list exceeds 50000 primitives".into());
                }
                fields(operation,&["type","id","resource","sourceRect","transform","opacity","sampling"]).map_err(fail)?;
                let id=identity(operation,"id").map_err(fail)?;
                if !objects.insert(id) { return Err(fail(format!("DISPLAY_LIST_INVALID: duplicate primitive identity {id}"))); }
                let resource=parse_reference(&operation["resource"]).map_err(fail)?;
                let resource_index = *resource_indices
                    .get(&(resource.key.clone(), resource.revision))
                    .filter(|&&idx| resources[idx] == resource)
                    .ok_or_else(|| fail("RESOURCE_NOT_READY: image reference is not declared".into()))?;
                fields(&operation["sourceRect"],&["x","y","width","height"]).map_err(fail)?;
                let rect=&operation["sourceRect"];
                let number=|key:&str|rect[key].as_f64().filter(|n|n.is_finite()).ok_or_else(||format!("IMAGE_INVALID: sourceRect.{key} required"));
                let x=number("x").map_err(fail)?;let y=number("y").map_err(fail)?;
                let width=number("width").map_err(fail)?;let height=number("height").map_err(fail)?;
                if x<0.0 || y<0.0 || width<=0.0 || height<=0.0 || x+width>resource.width as f64 || y+height>resource.height as f64 {
                    return Err(fail("IMAGE_INVALID: source crop exceeds registered pixels".into()));
                }
                let source=Rect::new(x,y,x+width,y+height);
                if !operation["transform"].is_array() {return Err(fail("IMAGE_INVALID: explicit source-to-world matrix required".into()));}
                let transform=object_transform(operation).map_err(fail)?;
                if transform.determinant().abs()<1e-12 {return Err(fail("IMAGE_INVALID: singular source-to-world transform".into()));}
                validate_transformed_path(&source.to_path(0.05),transform).map_err(fail)?;
                let opacity=optional_number(operation,"opacity",1.0).map_err(fail)?;
                if !(0.0..=1.0).contains(&opacity){return Err(fail("IMAGE_INVALID: opacity must be0..1".into()));}
                let quality=match operation["sampling"].as_str(){Some("bilinear")=>ImageQuality::Medium,Some("nearest")=>ImageQuality::Low,_=>return Err(fail("IMAGE_INVALID: explicit nearest/bilinear sampling required".into()))};
                operations.push(PreparedOp::Image(images.len()));
                images.push(PreparedImage{resource,resource_index,source,transform,opacity:opacity as f32,quality});
            }
            Some("vector") => {
                if objects.len() >= 50_000 {
                    return Err(
                        "SCENE_RESOURCE_LIMIT: display-list exceeds 50000 primitives".into(),
                    );
                }
                fields(operation, &["type", "object"]).map_err(fail)?;
                let object = &operation["object"];
                let id = identity(object, "id").map_err(fail)?;
                if !objects.insert(id) {
                    return Err(fail(format!(
                        "DISPLAY_LIST_INVALID: duplicate primitive identity {id}"
                    )));
                }
                // Reuse all existing geometry/paint/dash/affine safeguards.
                // Array sequence, not object.order, controls display-list paint.
                let mut prepared = prepare_snapshot(&json!({"objects":[object], "connections":[],
                    "environment":{"background":"#00000000"}}))
                .map_err(fail)?;
                if prepared.vectors.len() != 1 {
                    return Err(fail(
                        "DISPLAY_LIST_INVALID: vector operation must be visible".into(),
                    ));
                }
                let vector = prepared.vectors.pop().unwrap();
                command_count = command_count
                    .checked_add(vector.path.elements().len())
                    .and_then(|n| {
                        n.checked_add(
                            vector
                                .stroke_path
                                .as_ref()
                                .map_or(0, |p| p.elements().len()),
                        )
                    })
                    .ok_or("SCENE_RESOURCE_LIMIT: display-list command overflow")?;
                operations.push(PreparedOp::Vector(vectors.len()));
                vectors.push(vector);
            }
            Some(kind @ ("pushClip" | "pushComposite")) => {
                let allowed = if kind == "pushClip" {
                    &[
                        "type",
                        "scopeId",
                        "commands",
                        "transform",
                        "fillRule",
                        "isolation",
                    ][..]
                } else {
                    &[
                        "type",
                        "scopeId",
                        "commands",
                        "transform",
                        "fillRule",
                        "isolation",
                        "opacity",
                        "blendMode",
                    ][..]
                };
                fields(operation, allowed).map_err(fail)?;
                let id = identity(operation, "scopeId").map_err(fail)?;
                if !scopes.insert(id) {
                    return Err(fail(format!(
                        "DISPLAY_LIST_INVALID: duplicate scope identity {id}"
                    )));
                }
                if stack.len() >= MAX_SCOPE_DEPTH {
                    return Err(fail("SCENE_RESOURCE_LIMIT: scope depth exceeds 32".into()));
                }
                if operation["isolation"] != "isolated" {
                    return Err(fail(
                        "SCENE_UNSUPPORTED: scope must explicitly be isolated".into(),
                    ));
                }
                if !operation["commands"].is_array() || !operation["transform"].is_array() {
                    return Err(fail(
                        "DISPLAY_LIST_INVALID: scope needs explicit commands and matrix".into(),
                    ));
                }
                let path = object_path(
                    &json!({"payload":{"commands":operation["commands"]}}),
                    &mut command_count,
                )
                .map_err(fail)?;
                let transform = object_transform(operation).map_err(fail)?;
                validate_transformed_path(&path, transform).map_err(fail)?;
                let fill_rule =
                    match optional_style(operation, "fillRule", "nonzero").map_err(fail)? {
                        "nonzero" => Fill::NonZero,
                        "evenodd" => Fill::EvenOdd,
                        value => return Err(fail(format!("SCENE_UNSUPPORTED: fillRule {value}"))),
                    };
                let opacity = optional_number(operation, "opacity", 1.0).map_err(fail)?;
                if !(0.0..=1.0).contains(&opacity) {
                    return Err(fail(
                        "DISPLAY_LIST_INVALID: opacity must be between zero and one".into(),
                    ));
                }
                let blend = match optional_style(operation, "blendMode", "normal").map_err(fail)? {
                    "normal" => BlendMode::new(Mix::Normal,Compose::SrcOver),
                    "multiply" => BlendMode::new(Mix::Multiply,Compose::SrcOver),
                    "screen" => BlendMode::new(Mix::Screen,Compose::SrcOver),
                    "destination-out" => BlendMode::new(Mix::Normal,Compose::DestOut),
                    value => return Err(fail(format!("SCENE_UNSUPPORTED: blendMode {value}"))),
                };
                operations.push(PreparedOp::Scope(PreparedScope {
                    kind: if kind == "pushClip" {
                        PreparedScopeKind::Clip
                    } else {
                        PreparedScopeKind::Composite
                    },
                    path,
                    transform,
                    fill_rule,
                    opacity: opacity as f32,
                    blend,
                }));
                stack.push(id);
            }
            Some("pop") => {
                fields(operation, &["type", "scopeId"]).map_err(fail)?;
                let id = identity(operation, "scopeId").map_err(fail)?;
                if stack.pop() != Some(id) {
                    return Err(fail(format!(
                        "DISPLAY_LIST_INVALID: unmatched scope pop {id}"
                    )));
                }
                operations.push(PreparedOp::Pop);
            }
            kind => return Err(fail(format!("SCENE_UNSUPPORTED: paint operation {kind:?}"))),
        }
        if objects.len()>50_000 {return Err("SCENE_RESOURCE_LIMIT: display-list exceeds 50000 primitives".into());}
        if command_count > MAX_COMMANDS {
            return Err(
                "SCENE_RESOURCE_LIMIT: display-list exceeds 1000000 compiled commands".into(),
            );
        }
    }
    if !stack.is_empty() {
        return Err("DISPLAY_LIST_INVALID: unclosed scope stack".into());
    }
    let report = EncodingReport {
        objects: objects.len(),
        vectors: vectors.len(),
        connections: 0,
        encoded_connections: 0,
        text: 0,
        raster: 0,
        structural: scopes.len(),
        requires_mixed_compositor: false,
    };
    Ok(PreparedScene {
        vectors,
        images,
        resources,
        operations,
        background,
        report,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rect(x: i32, y: i32, w: i32, h: i32) -> Value {
        json!([
            ["M", x, y],
            ["L", x + w, y],
            ["L", x + w, y + h],
            ["L", x, y + h],
            ["Z"]
        ])
    }
    fn draw(id: &str, fill: &str, commands: Value) -> Value {
        json!({"type":"vector","object":{"id":id,"kind":"vector","order":0,
            "transform":[1,0,0,1,0,0],"payload":{"commands":commands,"fill":fill,"strokeWidth":0}}})
    }
    fn scope(id: &str, kind: &str, commands: Value) -> Value {
        let mut value = json!({"type":kind,"scopeId":id,"commands":commands,
            "transform":[1,0,0,1,0,0],"fillRule":"nonzero","isolation":"isolated"});
        if kind == "pushComposite" {
            value["opacity"] = json!(1);
            value["blendMode"] = json!("normal");
        }
        value
    }
    fn pop(id: &str) -> Value {
        json!({"type":"pop","scopeId":id})
    }
    fn list(ops: Vec<Value>) -> Value {
        json!({"schema":"art-equation.display-list","schemaVersion":2,"sceneId":"disposable-scopes","revision":"1",
            "resources":[],"environment":{"background":"#00000000","colorSpace":"srgb"},"operations":ops})
    }
    fn render(value: &Value) -> Vec<u8> {
        crate::cpu::render_cpu_snapshot(64, 64, &value.to_string(), 1.0, 0.0, 0.0).unwrap()
    }
    fn pixel(p: &[u8], x: usize, y: usize) -> [u8; 4] {
        p[(y * 64 + x) * 4..(y * 64 + x) * 4 + 4]
            .try_into()
            .unwrap()
    }
    fn same_error(value: &Value) -> String {
        let source = value.to_string();
        let gpu = crate::parse_snapshot(&source)
            .and_then(|s| prepare_snapshot(&s))
            .err()
            .expect("reject before GPU encoding");
        let cpu = crate::cpu::render_cpu_snapshot(64, 64, &source, 1.0, 0.0, 0.0).unwrap_err();
        assert_eq!(gpu, cpu);
        gpu
    }
    #[test]
    fn display_sequence_wins_over_primitive_order_metadata() {
        let mut first = draw("red", "#ff0000", rect(8, 8, 40, 40));
        first["object"]["order"] = json!(100);
        let second = draw("blue", "#0000ff", rect(8, 8, 40, 40));
        let value = list(vec![first, second]);
        assert_eq!(pixel(&render(&value), 16, 16), [0, 0, 255, 255]);
        assert_eq!(
            crate::gpu_scene::encode_snapshot(&value).unwrap().1.vectors,
            2
        );
    }

    #[test]
    fn authored_clip_and_normal_composite_kinds_survive_shared_preparation() {
        let prepared = prepare_snapshot(&list(vec![
            scope("clip", "pushClip", rect(0,0,64,64)),
            scope("composite", "pushComposite", rect(0,0,64,64)),
            draw("paint", "#ff0000", rect(0,0,64,64)), pop("composite"), pop("clip"),
        ])).unwrap();
        let kinds = prepared.operations.iter().filter_map(|operation| match operation {
            PreparedOp::Scope(scope) => Some(scope.kind),
            _ => None,
        }).collect::<Vec<_>>();
        assert_eq!(kinds, vec![PreparedScopeKind::Clip, PreparedScopeKind::Composite]);
    }
    #[test]
    fn group_opacity_is_applied_once_across_overlapping_primitives() {
        let mut group = scope("g", "pushComposite", rect(0, 0, 64, 64));
        group["opacity"] = json!(0.5);
        let p = render(&list(vec![
            group,
            draw("r", "#ff0000", rect(8, 8, 24, 24)),
            draw("b", "#0000ff", rect(24, 8, 24, 24)),
            pop("g"),
        ]));
        assert_eq!(pixel(&p, 16, 16), [255, 0, 0, 128]);
        assert_eq!(pixel(&p, 28, 16), [0, 0, 255, 128]);
        assert_eq!(pixel(&p, 40, 16), [0, 0, 255, 128]);
    }
    #[test]
    fn nested_clips_keep_each_draw_matrix_independent_and_restore_after_pop() {
        let mut outer = scope("a", "pushClip", rect(0, 0, 32, 32));
        outer["transform"] = json!([1, 0, 0, 1, 8, 8]);
        let p = render(&list(vec![
            outer,
            scope("b", "pushClip", rect(16, 16, 32, 32)),
            draw("r", "#ff0000", rect(0, 0, 64, 64)),
            pop("b"),
            pop("a"),
            draw("b", "#0000ff", rect(48, 0, 8, 8)),
        ]));
        assert_eq!(pixel(&p, 20, 20), [255, 0, 0, 255]);
        assert_eq!(pixel(&p, 10, 10), [0, 0, 0, 0]);
        assert_eq!(pixel(&p, 45, 20), [0, 0, 0, 0]);
        assert_eq!(pixel(&p, 50, 4), [0, 0, 255, 255]);
    }
    #[test]
    fn rotated_and_off_viewport_clip_uses_authored_world_transform() {
        let mut clip = scope("rot", "pushClip", rect(0, 0, 16, 32));
        clip["transform"] = json!([0, 1, -1, 0, 24, -4]);
        let p = render(&list(vec![
            clip,
            draw("r", "#ff0000", rect(0, 0, 64, 64)),
            pop("rot"),
        ]));
        assert_eq!(pixel(&p, 4, 4), [255, 0, 0, 255]);
        assert_eq!(pixel(&p, 26, 4), [0, 0, 0, 0]);
        assert_eq!(pixel(&p, 4, 14), [0, 0, 0, 0]);
    }
    #[test]
    fn evenodd_clip_hole_and_empty_clip_do_not_restore_full_paint() {
        let mut commands = rect(4, 4, 52, 52).as_array().unwrap().clone();
        commands.extend(rect(20, 20, 16, 16).as_array().unwrap().clone());
        let mut clip = scope("hole", "pushClip", json!(commands));
        clip["fillRule"] = json!("evenodd");
        let p = render(&list(vec![
            clip,
            draw("r", "#ff0000", rect(0, 0, 64, 64)),
            pop("hole"),
        ]));
        assert_eq!(pixel(&p, 10, 10), [255, 0, 0, 255]);
        assert_eq!(pixel(&p, 24, 24), [0, 0, 0, 0]);
        let p = render(&list(vec![
            scope("empty", "pushClip", json!([])),
            draw("r", "#ff0000", rect(0, 0, 64, 64)),
            pop("empty"),
        ]));
        assert!(p.iter().all(|b| *b == 0));
    }
    #[test]
    fn multiply_and_screen_composite_use_the_backdrop_and_src_over() {
        for (blend, expected) in [("multiply", [0, 0, 0, 255]), ("screen", [255, 0, 255, 255])] {
            let mut group = scope("mix", "pushComposite", rect(0, 0, 64, 64));
            group["blendMode"] = json!(blend);
            let p = render(&list(vec![
                draw("r", "#ff0000", rect(0, 0, 64, 64)),
                group,
                draw("b", "#0000ff", rect(8, 8, 40, 40)),
                pop("mix"),
            ]));
            assert_eq!(pixel(&p, 16, 16), expected);
            assert_eq!(pixel(&p, 4, 4), [255, 0, 0, 255]);
        }
    }
    #[test]
    fn isolated_clip_has_explicit_blend_backdrop_semantics() {
        let mut group = scope("mix", "pushComposite", rect(0, 0, 64, 64));
        group["blendMode"] = json!("multiply");
        let p = render(&list(vec![
            draw("r", "#ff0000", rect(0, 0, 64, 64)),
            scope("clip", "pushClip", rect(8, 8, 40, 40)),
            group,
            draw("b", "#0000ff", rect(0, 0, 64, 64)),
            pop("mix"),
            pop("clip"),
        ]));
        assert_eq!(pixel(&p, 16, 16), [0, 0, 255, 255]);
        assert_eq!(pixel(&p, 4, 4), [255, 0, 0, 255]);
    }
    #[test]
    fn stack_underflow_mismatch_unclosed_and_duplicate_scopes_fail_identically() {
        for ops in [
            vec![pop("a")],
            vec![scope("a", "pushClip", rect(0, 0, 4, 4)), pop("b")],
            vec![scope("a", "pushClip", rect(0, 0, 4, 4))],
            vec![
                scope("a", "pushClip", rect(0, 0, 4, 4)),
                scope("a", "pushClip", rect(0, 0, 4, 4)),
                pop("a"),
                pop("a"),
            ],
        ] {
            assert!(same_error(&list(ops)).contains("DISPLAY_LIST_INVALID"));
        }
    }
    #[test]
    fn operation_depth_and_aggregate_complexity_limits_are_shared() {
        let ops = (0..33)
            .map(|i| scope(&format!("s{i}"), "pushClip", rect(0, 0, 4, 4)))
            .collect();
        assert!(same_error(&list(ops)).contains("depth"));
        assert!(same_error(&list(vec![pop("a"); MAX_OPERATIONS + 1])).contains("operations"));
        let commands: Vec<Value> = std::iter::once(json!(["M", 0, 0]))
            .chain((0..60_000).map(|_| json!(["L", 1, 1])))
            .collect();
        let ops = (0..17)
            .map(|i| draw(&format!("v{i}"), "#ffffff", json!(commands)))
            .collect();
        assert!(same_error(&list(ops)).contains("1000000"));
    }
    #[test]
    fn unsupported_resources_masks_and_unqualified_blends_cannot_succeed_partially() {
        let mut v = list(vec![]);
        v["resources"] = json!([{"id":"unready-image"}]);
        assert!(same_error(&v).contains("RESOURCE_INVALID"));
        for (key, input) in [
            ("mask", json!({})),
            ("isolation", json!("passthrough")),
            ("blendMode", json!("overlay")),
            ("opacity", json!(1.01)),
        ] {
            let mut op = scope("s", "pushComposite", rect(0, 0, 4, 4));
            op[key] = input;
            same_error(&list(vec![op, pop("s")]));
        }
        let mut op = draw("r", "#ff0000", rect(0, 0, 4, 4));
        op["object"]["payload"]["mask"] = json!({});
        same_error(&list(vec![op]));
    }
    #[test]
    fn malformed_headers_matrices_paths_identities_and_camera_fail_before_paint() {
        for (key, input) in [
            ("schemaVersion", json!(3)),
            ("sceneId", json!("")),
            ("operations", json!({})),
            ("objects", json!([])),
            ("resources", json!(null)),
        ] {
            let mut v = list(vec![]);
            v[key] = input;
            same_error(&v);
        }
        for (key, input) in [
            ("transform", json!([1, 0, 0, 1, 0])),
            ("transform", json!(["bad", 0, 0, 1, 0, 0])),
            ("commands", json!([["L", 0, 0]])),
            ("fillRule", json!("bad")),
        ] {
            let mut op = scope("s", "pushClip", rect(0, 0, 4, 4));
            op[key] = input;
            same_error(&list(vec![op, pop("s")]));
        }
        let mut clip = scope("s", "pushClip", rect(0, 0, 4, 4));
        clip["transform"] = json!([1, 0, 0, 1, 1e9, 0]);
        let prepared = prepare_snapshot(&list(vec![clip, pop("s")])).unwrap();
        assert!(
            crate::prepared_scene::validate_camera(&prepared, vello_cpu::kurbo::Affine::scale(1e6))
                .is_err()
        );
        let op = draw("same", "#ff0000", rect(0, 0, 4, 4));
        assert!(same_error(&list(vec![op.clone(), op])).contains("duplicate"));
    }
}

//! One strict paint/geometry preparation shared by Vello GPU and Vello CPU.
//! The canonical app owns routes, Boolean resolution and affine flattening.
//! Dashes are expanded once here; no renderer invents independent geometry.

use crate::EncodingReport;
use serde_json::Value;
use std::collections::HashSet;
use vello_cpu::{
    color::{AlphaColor, Srgb, parse_color},
    kurbo::{Affine, BezPath, Cap, Join, PathEl, Point, Rect, Shape, Stroke, dash},
    peniko::{BlendMode, Fill, Gradient},
};

pub(super) const MAX_PATH_COMMANDS: usize = 65_536;
const MAX_SCENE_COMMANDS: usize = 1_000_000;
const MAX_DASH_ENTRIES: usize = 64;
const MAX_MITER_LIMIT: f64 = 1_024.0;
const MAX_COMPILED_COORDINATE: f64 = 1e12;

pub(super) struct PreparedScene {
    pub vectors: Vec<PreparedVector>,
    pub images: Vec<crate::image_resources::PreparedImage>,
    pub resources: Vec<crate::image_resources::ImageReference>,
    pub operations: Vec<PreparedOp>,
    pub background: AlphaColor<Srgb>,
    pub report: EncodingReport,
}

pub(super) enum PreparedOp {
    Vector(usize),
    Image(usize),
    Gradient(PreparedGradient),
    Shadow(PreparedShadow),
    Scope(PreparedScope),
    Pop,
}

pub(super) struct PreparedGradient {
    pub path:BezPath,pub transform:Affine,pub brush_transform:Affine,pub fill_rule:Fill,pub gradient:Gradient,
}
pub(super) struct PreparedShadow {
    pub rect:Rect,pub radius:f64,pub std_dev:f64,pub color:AlphaColor<Srgb>,pub transform:Affine,
}

pub(super) struct PreparedScope {
    pub kind: PreparedScopeKind,
    pub path: BezPath,
    pub transform: Affine,
    pub fill_rule: Fill,
    pub opacity: f32,
    pub blend: BlendMode,
}

/// Preserve the authored operation kind even when both currently use the same
/// isolated Normal/SrcOver CPU semantics. GPU clip optimization must never infer
/// an explicit composite from its opacity or blend value alone.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum PreparedScopeKind {
    Clip,
    Composite,
}

pub(super) struct PreparedVector {
    pub path: BezPath,
    pub stroke_path: Option<BezPath>,
    pub transform: Affine,
    pub opacity: f32,
    pub fill: AlphaColor<Srgb>,
    pub fill_rule: Fill,
    pub stroke_color: AlphaColor<Srgb>,
    /// No dash pattern remains: stroke_path already contains its resolved runs.
    pub stroke: Stroke,
    /// Includes requested miter and cap extents, unlike a fixed four-width box.
    pub opacity_clip: Rect,
}

fn optional_bool(value: &Value, key: &str, default: bool) -> Result<bool, String> {
    if value[key].is_null() {
        return Ok(default);
    }
    value[key]
        .as_bool()
        .ok_or_else(|| format!("{key} must be a boolean"))
}

/// Validate all paint before either backend allocates a rendering target.
pub(super) fn prepare_snapshot(snapshot: &Value) -> Result<PreparedScene, String> {
    if snapshot["schema"] == "art-equation.display-list" {
        return crate::prepared_display_list::prepare_display_list(snapshot);
    }
    let objects = snapshot["objects"]
        .as_array()
        .ok_or("Snapshot objects must be an array")?;
    if !snapshot["connections"].is_null() {
        let connections = snapshot["connections"]
            .as_array()
            .ok_or("Snapshot connections must be an array")?;
        if !connections.is_empty() {
            return Err("SCENE_UNSUPPORTED: raw connections need canonical compiled paint and layer ownership".into());
        }
    }
    let background = paint_color(&snapshot["environment"]["background"], "#00000000")?;
    let mut identities = HashSet::with_capacity(objects.len());
    let mut ordered = Vec::with_capacity(objects.len());
    for (index, object) in objects.iter().enumerate() {
        if !object.is_object() {
            return Err("scene object must be an object".into());
        }
        let id = object["id"]
            .as_str()
            .filter(|id| !id.is_empty())
            .ok_or("scene object id must be a nonempty string")?;
        if !identities.insert(id) {
            return Err(format!("scene object id {id} is duplicated"));
        }
        let order = optional_number(object, "order", 0.0)?;
        let visible = optional_bool(object, "visible", true)?;
        let hidden = optional_bool(object, "hidden", false)?;
        if visible && !hidden {
            ordered.push((index, order, object));
        }
    }
    ordered.sort_by(|left, right| left.1.total_cmp(&right.1).then(left.0.cmp(&right.0)));
    let mut vectors = Vec::with_capacity(ordered.len());
    let mut command_count = 0;
    let mut stroke_command_count = 0;
    for (_, _, object) in ordered {
        if object["kind"] != "vector" {
            return Err("SCENE_UNSUPPORTED: expected visible vector".into());
        }
        super::validate_flat_vector_metadata(object)?;
        if optional_style(object, "blendMode", "normal")? != "normal" {
            return Err("SCENE_UNSUPPORTED: blendMode must be normal".into());
        }
        let payload = &object["payload"];
        if !payload.is_object() {
            return Err("vector payload must be an object".into());
        }
        let path = object_path(object, &mut command_count)?;
        let transform = object_transform(object)?;
        validate_transformed_path(&path, transform)?;
        let opacity = optional_number(object, "opacity", 1.0)?;
        if !(0.0..=1.0).contains(&opacity) {
            return Err("object opacity must be between 0 and 1".into());
        }
        let fill_rule = match optional_style(payload, "vectorFillRule", "nonzero")? {
            "nonzero" => Fill::NonZero,
            "evenodd" => Fill::EvenOdd,
            value => return Err(format!("SCENE_UNSUPPORTED: vectorFillRule {value}")),
        };
        let fill = paint_color(&payload["fill"], "#808080")?;
        let stroke_color = paint_color(&payload["stroke"], "#000000")?;
        let (stroke, dashes, offset) = stroke_style(payload)?;
        let stroke_path = if stroke.width > 0.0 && stroke_color.components[3] > 0.0 {
            let resolved = if dashes.is_empty() {
                path.clone()
            } else {
                expand_dashes(&path, &dashes, offset)?
            };
            add_commands(&mut stroke_command_count, resolved.elements().len())?;
            Some(resolved)
        } else {
            None
        };
        let padding = stroke.width * stroke.miter_limit.max(1.0) + 1.0;
        let opacity_clip = path.bounding_box().inflate(padding, padding);
        validate_transformed_path(&opacity_clip.to_path(0.05), transform)?;
        vectors.push(PreparedVector {
            path,
            stroke_path,
            transform,
            opacity: opacity as f32,
            fill,
            fill_rule,
            stroke_color,
            stroke,
            opacity_clip,
        });
    }
    let report = EncodingReport {
        objects: objects.len(),
        vectors: vectors.len(),
        connections: 0,
        encoded_connections: 0,
        text: 0,
        raster: 0,
        structural: 0,
        requires_mixed_compositor: false,
    };
    Ok(PreparedScene {
        operations: (0..vectors.len()).map(PreparedOp::Vector).collect(),
        vectors,
        images: Vec::new(),
        resources: Vec::new(),
        background,
        report,
    })
}

fn add_commands(count: &mut usize, additional: usize) -> Result<(), String> {
    *count = count
        .checked_add(additional)
        .ok_or("SCENE_RESOURCE_LIMIT: command count overflow")?;
    if additional > MAX_PATH_COMMANDS || *count > MAX_SCENE_COMMANDS {
        return Err(
            "SCENE_RESOURCE_LIMIT: path commands exceed the shared complexity bounds".into(),
        );
    }
    Ok(())
}

pub(super) fn stroke_style(payload: &Value) -> Result<(Stroke, Vec<f64>, f64), String> {
    let width = optional_number(payload, "strokeWidth", 0.0)?;
    if !(0.0..=1e6).contains(&width) {
        return Err("stroke width is outside the shared bounds".into());
    }
    let cap = match optional_style(payload, "vectorStrokeCap", "butt")? {
        "butt" => Cap::Butt,
        "round" => Cap::Round,
        "square" => Cap::Square,
        value => return Err(format!("SCENE_UNSUPPORTED: vectorStrokeCap {value}")),
    };
    let join = match optional_style(payload, "vectorStrokeJoin", "miter")? {
        "miter" => Join::Miter,
        "round" => Join::Round,
        "bevel" => Join::Bevel,
        value => return Err(format!("SCENE_UNSUPPORTED: vectorStrokeJoin {value}")),
    };
    let miter = optional_number(payload, "miterLimit", 4.0)?;
    if !(1.0..=MAX_MITER_LIMIT).contains(&miter) {
        return Err("SCENE_RESOURCE_LIMIT: miterLimit must be between 1 and 1024".into());
    }
    let offset = optional_number(payload, "dashOffset", 0.0)?;
    let mut dashes = Vec::new();
    if !payload["dashArray"].is_null() {
        let values = payload["dashArray"]
            .as_array()
            .ok_or("dashArray must be a numeric array")?;
        if values.len() > MAX_DASH_ENTRIES {
            return Err("SCENE_RESOURCE_LIMIT: dashArray exceeds 64 entries".into());
        }
        for value in values {
            let length = finite_number(value, "dashArray entry")?;
            if length < 0.0 || length > 1e6 {
                return Err("dashArray entries must be nonnegative and at most 1000000".into());
            }
            if length == 0.0 {
                return Err("SCENE_UNSUPPORTED: zero-length dash entries require SVG dot parity verification".into());
            }
            dashes.push(length);
        }
    }
    Ok((
        Stroke::new(width)
            .with_caps(cap)
            .with_join(join)
            .with_miter_limit(miter),
        dashes,
        offset,
    ))
}

/// A control polygon upper-bounds curve arc length. Count dash transitions from
/// its shortest positive interval before iterating, then enforce the actual cap.
fn expand_dashes(path: &BezPath, pattern: &[f64], offset: f64) -> Result<BezPath, String> {
    let mut current = Point::ORIGIN;
    let mut start = Point::ORIGIN;
    let mut length = 0.0;
    for element in path.elements() {
        match *element {
            PathEl::MoveTo(point) => {
                current = point;
                start = point;
            }
            PathEl::LineTo(point) => {
                length += current.distance(point);
                current = point;
            }
            PathEl::QuadTo(control, point) => {
                length += current.distance(control) + control.distance(point);
                current = point;
            }
            PathEl::CurveTo(first, second, point) => {
                length += current.distance(first) + first.distance(second) + second.distance(point);
                current = point;
            }
            PathEl::ClosePath => {
                length += current.distance(start);
                current = start;
            }
        }
    }
    let shortest = pattern.iter().copied().fold(f64::INFINITY, f64::min);
    let estimate = 4.0 * (path.elements().len() as f64 + (length / shortest).ceil() + 1.0);
    if !estimate.is_finite() || estimate > MAX_PATH_COMMANDS as f64 {
        return Err(
            "SCENE_RESOURCE_LIMIT: dash expansion exceeds the per-path complexity budget".into(),
        );
    }
    let mut resolved = BezPath::new();
    for element in dash(path.elements().iter().copied(), offset, pattern) {
        if resolved.elements().len() >= MAX_PATH_COMMANDS {
            return Err(
                "SCENE_RESOURCE_LIMIT: resolved dashes exceed the per-path complexity budget"
                    .into(),
            );
        }
        resolved.push(element);
    }
    Ok(resolved)
}

pub(super) fn validate_transformed_path(path: &BezPath, transform: Affine) -> Result<(), String> {
    let check = |point: Point| -> Result<(), String> {
        let point = transform * point;
        if !point.x.is_finite()
            || !point.y.is_finite()
            || point.x.abs() > MAX_COMPILED_COORDINATE
            || point.y.abs() > MAX_COMPILED_COORDINATE
        {
            Err(
                "SCENE_RESOURCE_LIMIT: compiled geometry exceeds finite 1e12 coordinate bounds"
                    .into(),
            )
        } else {
            Ok(())
        }
    };
    for element in path.elements() {
        match *element {
            PathEl::MoveTo(point) | PathEl::LineTo(point) => check(point)?,
            PathEl::QuadTo(control, point) => {
                check(control)?;
                check(point)?;
            }
            PathEl::CurveTo(first, second, point) => {
                check(first)?;
                check(second)?;
                check(point)?;
            }
            PathEl::ClosePath => {}
        }
    }
    Ok(())
}

pub(super) fn validate_camera(scene: &PreparedScene, camera: Affine) -> Result<(), String> {
    for image in &scene.images {
        validate_transformed_path(&image.source.to_path(0.05), camera * image.transform)?;
    }
    for object in &scene.vectors {
        validate_transformed_path(&object.path, camera * object.transform)?;
        validate_transformed_path(
            &object.opacity_clip.to_path(0.05),
            camera * object.transform,
        )?;
    }
    for operation in &scene.operations {
        if let PreparedOp::Gradient(paint)=operation {
            validate_transformed_path(&paint.path,camera*paint.transform)?;
        }
        if let PreparedOp::Shadow(paint)=operation {
            validate_transformed_path(&paint.rect.inflate(2.5*paint.std_dev,2.5*paint.std_dev).to_path(0.05),camera*paint.transform)?;
        }
        if let PreparedOp::Scope(scope) = operation {
            validate_transformed_path(&scope.path, camera * scope.transform)?;
        }
    }
    Ok(())
}

pub(super) fn optional_number(value: &Value, key: &str, default: f64) -> Result<f64, String> {
    if value[key].is_null() {
        return Ok(default);
    }
    finite_number(&value[key], key)
}

fn finite_number(value: &Value, field: &str) -> Result<f64, String> {
    let number = value
        .as_f64()
        .ok_or_else(|| format!("{field} must be a finite number"))?;
    if !number.is_finite() || number.abs() > 1_000_000_000.0 {
        return Err(format!("{field} is outside the shared numeric bounds"));
    }
    Ok(number)
}

pub(super) fn optional_style<'a>(
    value: &'a Value,
    key: &str,
    default: &'a str,
) -> Result<&'a str, String> {
    if value[key].is_null() {
        return Ok(default);
    }
    value[key]
        .as_str()
        .ok_or_else(|| format!("{key} must be a string"))
}

pub(super) fn paint_color(value: &Value, default: &str) -> Result<AlphaColor<Srgb>, String> {
    let source = if value.is_null() {
        default
    } else {
        value.as_str().ok_or("paint color must be a CSS string")?
    };
    if source.len() > 256 {
        return Err("paint color is too long".into());
    }
    if source == "none" {
        return Ok(AlphaColor::from_rgba8(0, 0, 0, 0));
    }
    parse_color(source)
        .map(|color| color.to_alpha_color::<Srgb>())
        .map_err(|error| format!("invalid paint color: {error}"))
}

pub(super) fn object_transform(object: &Value) -> Result<Affine, String> {
    if object["transform"].is_null() {
        return Ok(Affine::IDENTITY);
    }
    let values = object["transform"]
        .as_array()
        .ok_or("object transform must be a six-number array")?;
    if values.len() != 6 {
        return Err("object transform must contain six numbers".into());
    }
    let mut coefficients = [0.0; 6];
    for (target, value) in coefficients.iter_mut().zip(values) {
        *target = finite_number(value, "object transform")?;
    }
    Ok(Affine::new(coefficients))
}

pub(super) fn object_path(object: &Value, scene_commands: &mut usize) -> Result<BezPath, String> {
    let commands = &object["payload"]["commands"];
    let supplied_bounds = if !object["bounds"].is_null() {
        Some(object_bounds(object)?)
    } else {
        None
    };
    if commands.is_null() {
        let path = supplied_bounds
            .ok_or("fallback path needs finite bounds")?
            .to_path(0.05);
        add_commands(scene_commands, path.elements().len())?;
        return Ok(path);
    }
    let commands = commands
        .as_array()
        .ok_or("path commands must be an array")?;
    add_commands(scene_commands, commands.len())?;
    let mut path = BezPath::new();
    let mut moved = false;
    for command in commands {
        let values = command.as_array().ok_or("path command must be an array")?;
        let opcode = values
            .first()
            .and_then(Value::as_str)
            .ok_or("path command needs an opcode")?;
        let expected = match opcode {
            "M" | "L" => 3,
            "Q" => 5,
            "C" => 7,
            "Z" => 1,
            _ => return Err(format!("unsupported path opcode {opcode}")),
        };
        if values.len() != expected {
            return Err(format!("path command {opcode} has the wrong arity"));
        }
        if opcode != "M" && !moved {
            return Err("path must start with MoveTo".into());
        }
        let mut coordinates = [0.0; 6];
        for (target, value) in coordinates.iter_mut().zip(values.iter().skip(1)) {
            *target = finite_number(value, "path coordinate")?;
        }
        match opcode {
            "M" => {
                path.move_to((coordinates[0], coordinates[1]));
                moved = true;
            }
            "L" => path.line_to((coordinates[0], coordinates[1])),
            "Q" => path.quad_to(
                (coordinates[0], coordinates[1]),
                (coordinates[2], coordinates[3]),
            ),
            "C" => path.curve_to(
                (coordinates[0], coordinates[1]),
                (coordinates[2], coordinates[3]),
                (coordinates[4], coordinates[5]),
            ),
            "Z" => path.close_path(),
            _ => unreachable!(),
        }
    }
    Ok(path)
}

fn object_bounds(object: &Value) -> Result<Rect, String> {
    let bounds = &object["bounds"];
    if !bounds.is_object() {
        return Err("bounds must be an object".into());
    }
    let x = finite_number(&bounds["x"], "bounds.x")?;
    let y = finite_number(&bounds["y"], "bounds.y")?;
    let width = finite_number(&bounds["width"], "bounds.width")?;
    let height = finite_number(&bounds["height"], "bounds.height")?;
    if width < 0.0 || height < 0.0 {
        return Err("bounds dimensions cannot be negative".into());
    }
    let right = x + width;
    let bottom = y + height;
    if !right.is_finite() || !bottom.is_finite() || right.abs() > 1e9 || bottom.abs() > 1e9 {
        return Err("SCENE_RESOURCE_LIMIT: bounds edges exceed finite 1e9 bounds".into());
    }
    Ok(Rect::new(x, y, right, bottom))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn fixture() -> Value {
        json!({ "schema":"art-equation.scene", "schemaVersion":1,
            "environment":{"background":"#00000000"}, "connections":[],
            "objects":[{ "id":"primitive", "kind":"vector", "order":0,
                "visible":true, "transform":[1,0,0,1,0,0],
                "bounds":{"x":4,"y":4,"width":36,"height":24},
                "payload":{"commands":[["M",4,8],["C",10,4,32,24,40,8]],
                    "fill":"none","stroke":"#ffffff","strokeWidth":2} }] })
    }

    fn assert_same_error(value: &Value) -> String {
        let source = value.to_string();
        let gpu = crate::parse_snapshot(&source)
            .and_then(|snapshot| prepare_snapshot(&snapshot))
            .err()
            .expect("GPU preparation must reject this input");
        let cpu = crate::cpu::render_cpu_snapshot(48, 40, &source, 1.0, 0.0, 0.0).unwrap_err();
        assert_eq!(
            gpu, cpu,
            "CPU/GPU share the exact failure, rather than partial paint"
        );
        gpu
    }

    #[test]
    fn shared_dash_preparation_keeps_curves_and_removes_second_expansion() {
        let mut value = fixture();
        value["objects"][0]["payload"]["dashArray"] = json!([4, 2, 1]);
        value["objects"][0]["payload"]["dashOffset"] = json!(-9);
        let prepared = prepare_snapshot(&value).unwrap();
        let vector = &prepared.vectors[0];
        assert!(vector.stroke.dash_pattern.is_empty());
        assert_eq!(vector.stroke.dash_offset, 0.0);
        assert_eq!(vector.path.elements().len(), 2);
        let runs = vector.stroke_path.as_ref().unwrap();
        assert!(runs.elements().len() > vector.path.elements().len());
        assert!(
            runs.elements()
                .iter()
                .any(|el| matches!(el, PathEl::CurveTo(..)))
        );
        let (_, report) = crate::gpu_scene::encode_snapshot(&value).unwrap();
        assert_eq!(report, prepared.report);
    }

    #[test]
    fn malformed_styles_bounds_and_visibility_fail_identically_before_paint() {
        for (field, input) in [
            ("dashArray", json!("4 2")),
            ("dashArray", json!([-1, 2])),
            ("dashArray", json!([0, 0])),
            ("dashArray", json!([0, 4])),
            ("dashArray", json!([1_000_001, 2])),
            ("dashArray", json!(["bad", 2])),
            ("dashArray", json!(vec![1; 65])),
            ("dashOffset", json!("bad")),
            ("miterLimit", json!(0.9)),
            ("miterLimit", json!(1025)),
            ("miterLimit", json!("8")),
            ("strokeWidth", json!(-1)),
        ] {
            let mut value = fixture();
            value["objects"][0]["payload"][field] = input;
            assert_same_error(&value);
        }
        for bounds in [
            json!([]),
            json!({"x":0,"y":0,"width":-1,"height":4}),
