const Cmd = await import(await moduleUrl('src/board/columnRowCommands.ts'))
const Col = await import(await moduleUrl('src/board/columns.ts'))
const Arr = await import(await moduleUrl('src/board/arrangement.ts'))
const Struct = await import(await moduleUrl('src/board/diagramStructureCore.ts'))
const Safety = await import(await moduleUrl('src/board/boardMutationSafety.ts'))
const Spatial = await import(await moduleUrl('src/canvas-engine/spatialIndex.ts'))

const inputs = [
  'src/board/columnRowCommands.ts',
  'src/board/arrangement.ts',
  'src/board/columns.ts',
  'src/board/diagramStructureCore.ts',
  'src/board/boardMutationSafety.ts',
  'src/canvas-engine/spatialIndex.ts',
  'src/board/velloEligibility.ts'
]
const hashes = async () => Object.fromEntries(await Promise.all(inputs.map(async (p) => [p, createHash('sha256').update(await readFile(p)).digest('hex')])))

const report = {
  generatedAt: new Date().toISOString(),
  passed: false,
  checks: 0,
  groups: [],
  benchmarks: {},
  sourceHashes: await hashes(),
  limitations: [
    'Stress testing verifies in-memory 50-item mixed-media arrangements, sibling column transfers, ancestor container movement, visual bounds calculations, shelf packing, and sub-millisecond spatial index queries headless.'
  ]
}

const outputDir = resolve('output/partii-dense-media-arrangement')
await mkdir(outputDir, { recursive: true })

const check = (condition, message) => {
  report.checks++
  assert(condition, message)
}
const ok = (result) => {
  check(result.ok, result.ok ? 'success' : JSON.stringify(result.issues))
  return result.value
}
const snapshot = (v) => JSON.stringify(v)

async function group(name, run) {
  const before = report.checks
  await run()
  report.groups.push({ name, checks: report.checks - before, passed: true })
}

// Node builders
const makeNode = (id, kind, extra = {}) => ({
  id,
  kind,
  title: id,
  x: 0,
  y: 0,
  width: 200,
  height: 120,
  ...extra
})

// Build a 50+ item mixed-media fixture
function createStressFixture() {
  const nodes = []
  const connectors = []

  // 1. Column A (Left)
  nodes.push(makeNode('col-left', 'column', { x: 100, y: 100, width: 260, height: 400 }))
  // 6 rows in col-left
  nodes.push(makeNode('row-l1-img', 'image', { parentColumnId: 'col-left', columnOrder: 0, x: 110, y: 140, width: 240, height: 160, assetId: 'asset-img1', imagePresentation: 'artwork' }))
  nodes.push(makeNode('row-l2-note', 'note', { parentColumnId: 'col-left', columnOrder: 1, x: 110, y: 310, width: 240, height: 80, body: 'Note in col left' }))
  nodes.push(makeNode('row-l3-shape', 'shape', { parentColumnId: 'col-left', columnOrder: 2, x: 110, y: 400, width: 240, height: 90, shapeType: 'path', vectorPath: { version: 1, closed: true, points: [{ id: 'p0', x: 0, y: 0 }, { id: 'p1', x: 240, y: 90 }] } }))
  nodes.push(makeNode('row-l4-text', 'text', { parentColumnId: 'col-left', columnOrder: 3, x: 110, y: 500, width: 240, height: 40, body: 'Label header' }))
  nodes.push(makeNode('row-l5-doc', 'document', { parentColumnId: 'col-left', columnOrder: 4, x: 110, y: 550, width: 240, height: 100, assetId: 'asset-doc1' }))
  nodes.push(makeNode('row-l6-note2', 'note', { parentColumnId: 'col-left', columnOrder: 5, x: 110, y: 660, width: 240, height: 70, body: 'Footer note' }))

  // 2. Column B (Middle)
  nodes.push(makeNode('col-middle', 'column', { x: 420, y: 100, width: 260, height: 400 }))
  // 5 rows in col-middle
  nodes.push(makeNode('row-m1-note', 'note', { parentColumnId: 'col-middle', columnOrder: 0, x: 430, y: 140, width: 240, height: 90, body: 'Middle note 1' }))
  nodes.push(makeNode('row-m2-img', 'image', { parentColumnId: 'col-middle', columnOrder: 1, x: 430, y: 240, width: 240, height: 140, assetId: 'asset-img2' }))
  nodes.push(makeNode('row-m3-shape', 'shape', { parentColumnId: 'col-middle', columnOrder: 2, x: 430, y: 390, width: 240, height: 80, shapeType: 'ellipse' }))
  nodes.push(makeNode('row-m4-text', 'text', { parentColumnId: 'col-middle', columnOrder: 3, x: 430, y: 480, width: 240, height: 50, body: 'Paragraph text' }))
  nodes.push(makeNode('row-m5-doc', 'document', { parentColumnId: 'col-middle', columnOrder: 4, x: 430, y: 540, width: 240, height: 90, assetId: 'asset-doc2' }))

  // 3. Column C (Right)
  nodes.push(makeNode('col-right', 'column', { x: 740, y: 100, width: 260, height: 300 }))
  nodes.push(makeNode('row-r1-note', 'note', { parentColumnId: 'col-right', columnOrder: 0, x: 750, y: 140, width: 240, height: 70, body: 'Right note' }))
  nodes.push(makeNode('row-r2-img', 'image', { parentColumnId: 'col-right', columnOrder: 1, x: 750, y: 220, width: 240, height: 120, assetId: 'asset-img3' }))

  // 4. Column D (Locked)
  nodes.push(makeNode('col-locked', 'column', { x: 1060, y: 100, width: 260, height: 200, locked: true }))
  nodes.push(makeNode('row-lock1', 'note', { parentColumnId: 'col-locked', columnOrder: 0, x: 1070, y: 140, width: 240, height: 60, body: 'Locked row' }))

  // 5. Enclosing Frame Container
  nodes.push(makeNode('frame-container', 'group', { containerRole: 'frame', x: 1400, y: 80, width: 500, height: 600 }))
  // Frame-nested Column
  nodes.push(makeNode('col-in-frame', 'column', { groupId: 'frame-container', x: 1420, y: 120, width: 220, height: 350 }))
  nodes.push(makeNode('row-f1-note', 'note', { parentColumnId: 'col-in-frame', columnOrder: 0, x: 1430, y: 150, width: 200, height: 60, body: 'Nested note' }))
  nodes.push(makeNode('row-f2-img', 'image', { parentColumnId: 'col-in-frame', columnOrder: 1, x: 1430, y: 220, width: 200, height: 100, assetId: 'asset-img4' }))
  // Frame-nested direct objects
  nodes.push(makeNode('frame-child-note', 'note', { groupId: 'frame-container', x: 1660, y: 150, width: 200, height: 100, body: 'Direct in frame' }))
  nodes.push(makeNode('frame-child-shape', 'shape', { groupId: 'frame-container', x: 1660, y: 270, width: 200, height: 120, shapeType: 'ellipse' }))

  // 6. Free canvas cards (28 items)
  for (let i = 0; i < 28; i++) {
    const kind = i % 5 === 0 ? 'image' : i % 5 === 1 ? 'note' : i % 5 === 2 ? 'shape' : i % 5 === 3 ? 'text' : 'document'
    const x = 100 + (i % 7) * 220
    const y = 800 + Math.floor(i / 7) * 180
    const extra = {}
    if (kind === 'image') {
      extra.assetId = `free-asset-${i}`
      extra.width = 180 + (i % 3) * 20
      extra.height = 130 + (i % 2) * 20
      if (i === 0) extra.rotation = 30
      if (i === 5) extra.imageTransform = { fit: 'cover', zoom: 1.4 }
    } else if (kind === 'shape') {
      extra.shapeType = i % 2 === 0 ? 'path' : 'ellipse'
      if (extra.shapeType === 'path') {
        extra.vectorPath = { version: 1, closed: true, points: [{ id: `sp0-${i}`, x: 0, y: 0 }, { id: `sp1-${i}`, x: 160, y: 80 }] }
      }
    } else if (kind === 'note') {
      extra.body = `Free note ${i} content with details`
    }
    nodes.push(makeNode(`free-${i}-${kind}`, kind, { x, y, width: 180, height: 120, ...extra }))
  }

  // 7. Connectors linking diverse cards
  connectors.push({ id: 'edge-1', sourceId: 'row-l1-img', targetId: 'row-m1-note', sourcePort: 'right', targetPort: 'left', style: 'elbow', color: '#60a5fa', width: 2, startArrow: false, endArrow: true, dashed: false, animated: false })
  connectors.push({ id: 'edge-2', sourceId: 'free-0-image', targetId: 'free-1-note', sourcePort: 'right', targetPort: 'left', style: 'elbow', color: '#34d399', width: 2, startArrow: false, endArrow: false, dashed: true, animated: false })

  return {
    id: 'dense-media-stress-board',
    title: 'Dense Media Stress Board',
    viewport: { x: 0, y: 0, scale: 1 },
    nodes,
    connectors
  }
}

try {
  await group('50-item mixed-media fixture topology and safety baseline', () => {
    const fixture = createStressFixture()
    check(fixture.nodes.length >= 50, `fixture contains ${fixture.nodes.length} nodes (>= 50 required)`)
    const ownership = Struct.validateContainerOwnership(fixture.nodes)
    check(ownership.ok, 'container ownership is structurally valid')
    const mutation = Safety.validateBoardMutation(fixture, fixture)
    check(mutation.ok, 'mutation safety validates initial fixture')

    // Verify presence of all key media kinds
    const kinds = new Set(fixture.nodes.map((n) => n.kind))
    check(kinds.has('image'), 'has image cards')
    check(kinds.has('note'), 'has note cards')
    check(kinds.has('shape'), 'has shape cards')
    check(kinds.has('text'), 'has text cards')
    check(kinds.has('document'), 'has document cards')
    check(kinds.has('column'), 'has columns')
    check(kinds.has('group'), 'has frames')
  })

  await group('Column row reordering earlier/later preserves row identities and source bytes', () => {
    const fixture = createStressFixture()
    const baseline = snapshot(fixture)

    // Check action states
    const l1State = Cmd.columnRowActionState(fixture, ['row-l1-img'])
    check(l1State.visible, 'row-l1-img action visible')
    check(!l1State.earlier, 'first row cannot move earlier')
    check(l1State.later, 'first row can move later')
    check(!l1State.previousColumn, 'leftmost column row has no previous column')
    check(l1State.nextColumn, 'leftmost column row has next sibling column')

    // Move first row later
    const movedLater = ok(Cmd.moveColumnRowsResult(fixture, ['row-l1-img'], 'later'))
    const childrenAfterLater = Col.columnChildren(movedLater, 'col-left')
    check(childrenAfterLater[0].id === 'row-l2-note', 'row-l2-note became first')
    check(childrenAfterLater[1].id === 'row-l1-img', 'row-l1-img moved to second index')
    check(childrenAfterLater[1].imagePresentation === 'artwork', 'image presentation preserved')
    check(childrenAfterLater[1].assetId === 'asset-img1', 'asset ID preserved')

    // Move it back earlier
    const movedEarlier = ok(Cmd.moveColumnRowsResult(movedLater, ['row-l1-img'], 'earlier'))
    const childrenAfterEarlier = Col.columnChildren(movedEarlier, 'col-left')
    check(childrenAfterEarlier[0].id === 'row-l1-img', 'restored to first position')
    check(childrenAfterEarlier[1].id === 'row-l2-note', 'second restored')

    // Non-adjacent selection refused
    const nonAdjacent = Cmd.moveColumnRowsResult(fixture, ['row-l1-img', 'row-l3-shape'], 'later')
    check(!nonAdjacent.ok, 'non-adjacent selection refused')

    // Cross-column selection refused
    const crossColumn = Cmd.moveColumnRowsResult(fixture, ['row-l1-img', 'row-m1-note'], 'later')
    check(!crossColumn.ok, 'cross-column selection refused')

    // Input unchanged
    check(snapshot(fixture) === baseline, 'input board was never mutated in-place')
  })

  await group('Move to sibling column (previous/next) transfers rows and auto-layouts columns', () => {
    const fixture = createStressFixture()

    // Move row from col-left to col-middle (next)
    const movedToNext = ok(Cmd.moveColumnRowsToSiblingColumnResult(fixture, ['row-l1-img'], 'next'))
    const targetChildren = Col.columnChildren(movedToNext, 'col-middle')
    const sourceChildren = Col.columnChildren(movedToNext, 'col-left')

    check(!sourceChildren.some((n) => n.id === 'row-l1-img'), 'row removed from col-left')
    check(targetChildren.some((n) => n.id === 'row-l1-img'), 'row inserted into col-middle')
    const transferredNode = targetChildren.find((n) => n.id === 'row-l1-img')
    check(transferredNode.parentColumnId === 'col-middle', 'parentColumnId updated to col-middle')
    check(transferredNode.width === 240, 'width preserved/fit to column')
    check(transferredNode.assetId === 'asset-img1', 'assetId preserved')

    // Move row from col-middle to col-left (previous)
    const movedBack = ok(Cmd.moveColumnRowsToSiblingColumnResult(movedToNext, ['row-l1-img'], 'previous'))
    const leftRestored = Col.columnChildren(movedBack, 'col-left')
    check(leftRestored.some((n) => n.id === 'row-l1-img'), 'row restored to col-left')

    // Refuse previous when in col-left (no previous sibling)
    const noPrev = Cmd.moveColumnRowsToSiblingColumnResult(fixture, ['row-l1-img'], 'previous')
    check(!noPrev.ok, 'refuses previous when no earlier sibling column exists')

    // Refuse move into locked sibling
    const rightColChildren = Col.columnChildren(fixture, 'col-right')
    const toLocked = Cmd.moveColumnRowsToSiblingColumnResult(fixture, [rightColChildren[0].id], 'next')
    check(!toLocked.ok, 'refuses move into locked sibling column')

    // Nested frame column sibling boundary:
    // col-in-frame is inside frame-container, so its siblings must also share frame-container
    const inFrameState = Cmd.columnRowActionState(fixture, ['row-f1-note'])
    check(!inFrameState.previousColumn, 'in-frame column has no previous column inside frame')
    check(!inFrameState.nextColumn, 'in-frame column has no next column inside frame')
  })

  await group('Move to ancestor container reparents to parent frame or canvas', () => {
    const fixture = createStressFixture()

    // 1. Move row from col-in-frame out to enclosing frame-container
    const movedOutToFrame = ok(Cmd.moveSelectionToAncestorResult(fixture, ['row-f1-note']))
    const reparentedInFrame = movedOutToFrame.nodes.find((n) => n.id === 'row-f1-note')
    check(reparentedInFrame.parentColumnId === undefined, 'parentColumnId removed')
    check(reparentedInFrame.groupId === 'frame-container', 'groupId set to enclosing frame-container')

    // 2. Move item already directly inside frame-container out to canvas
    const movedOutOfFrame = ok(Cmd.moveSelectionToAncestorResult(fixture, ['frame-child-note']))
    const freeFromFrame = movedOutOfFrame.nodes.find((n) => n.id === 'frame-child-note')
    check(freeFromFrame.groupId === undefined, 'groupId cleared (now on canvas)')
    check(freeFromFrame.parentColumnId === undefined, 'parentColumnId remains undefined')

    // 3. Move row from top-level column out to canvas
    const movedFromTopCol = ok(Cmd.moveSelectionToAncestorResult(fixture, ['row-l2-note']))
    const freeFromCol = movedFromTopCol.nodes.find((n) => n.id === 'row-l2-note')
    check(freeFromCol.parentColumnId === undefined, 'parentColumnId cleared')
    check(freeFromCol.groupId === undefined, 'groupId is undefined (free on canvas)')
    check(freeFromCol.x === 110, 'world x preserved')
    check(freeFromCol.y === 310, 'world y preserved')

    // Mutation safety checks
    check(Safety.validateBoardMutation(fixture, movedOutToFrame).ok, 'frame reparent mutation valid')
    check(Safety.validateBoardMutation(fixture, movedOutOfFrame).ok, 'canvas release mutation valid')
    check(Safety.validateBoardMutation(fixture, movedFromTopCol).ok, 'col release mutation valid')
  })

  await group('Multi-card alignment on 10 free cards calculates visual bounds and skips containers', () => {
    const fixture = createStressFixture()
    const freeCardIds = fixture.nodes.filter((n) => n.id.startsWith('free-')).slice(0, 10).map((n) => n.id)

    // Test Left Alignment
    const alignedLeft = Arr.alignBoardNodes(fixture.nodes, freeCardIds, 'left')
    const leftBoxes = freeCardIds.map((id) => Arr.boardNodeVisualBounds(alignedLeft.find((n) => n.id === id)))
    const minLeft = leftBoxes[0].left
    for (const box of leftBoxes) {
      check(Math.abs(box.left - minLeft) < 1e-4, 'all selected cards aligned to same left')
    }

    // Test Center Alignment
    const alignedCenter = Arr.alignBoardNodes(fixture.nodes, freeCardIds, 'center')
    const centerBoxes = freeCardIds.map((id) => Arr.boardNodeVisualBounds(alignedCenter.find((n) => n.id === id)))
    const avgCenter = (centerBoxes[0].left + centerBoxes[0].right) / 2
    for (const box of centerBoxes) {
      check(Math.abs((box.left + box.right) / 2 - avgCenter) < 1e-4, 'all selected cards aligned to horizontal center')
    }

    // Test Top Alignment
    const alignedTop = Arr.alignBoardNodes(fixture.nodes, freeCardIds, 'top')
    const topBoxes = freeCardIds.map((id) => Arr.boardNodeVisualBounds(alignedTop.find((n) => n.id === id)))
    const minTop = topBoxes[0].top
    for (const box of topBoxes) {
      check(Math.abs(box.top - minTop) < 1e-4, 'all selected cards aligned to top')
    }

    // Container exclusion: Attempting to align a column row with free cards must exclude the column row
    const mixedSelection = [...freeCardIds.slice(0, 2), 'row-l1-img', 'col-left', 'frame-container']
    const eligible = Arr.eligibleArrangementNodes(fixture.nodes, mixedSelection)
    check(eligible.length === 2, 'eligible arrangement nodes filters out column rows and containers')
    check(!eligible.some((n) => n.id === 'row-l1-img'), 'column row excluded')
    check(!eligible.some((n) => n.id === 'col-left'), 'column container excluded')
    check(!eligible.some((n) => n.id === 'frame-container'), 'frame container excluded')
  })

  await group('Shelf packing with gap preserves all media dimensions without collision', () => {
    const fixture = createStressFixture()
    const freeCardIds = fixture.nodes.filter((n) => n.id.startsWith('free-')).slice(0, 16).map((n) => n.id)

    // Pack into 2 rows with gap 24
    const packed2Rows = Arr.packBoardNodes(fixture.nodes, freeCardIds, { gap: 24, rows: 2 })
    const packedBoxes = freeCardIds.map((id) => Arr.boardNodeVisualBounds(packed2Rows.find((n) => n.id === id)))

    // Check no pair overlaps
    for (let i = 0; i < packedBoxes.length; i++) {
      for (let j = i + 1; j < packedBoxes.length; j++) {
        const a = packedBoxes[i], b = packedBoxes[j]
        const overlapX = a.left < b.right && a.right > b.left
        const overlapY = a.top < b.bottom && a.bottom > b.top
        check(!(overlapX && overlapY), `packed cards ${i} and ${j} do not overlap`)
      }
    }

    // Original node dimensions must remain exact
    for (const id of freeCardIds) {
      const orig = fixture.nodes.find((n) => n.id === id)
      const packed = packed2Rows.find((n) => n.id === id)
      check(orig.width === packed.width, `width preserved for ${id}`)
      check(orig.height === packed.height, `height preserved for ${id}`)
    }
  })

  await group('Marquee selection broad-phase and containment vs crossing', () => {
    const fixture = createStressFixture()
    const records = fixture.nodes.map((n) => ({
      id: n.id,
      bounds: { x: n.x, y: n.y, width: n.width, height: n.height }
    }))
    const index = new Spatial.UniformGridSpatialIndex(records, 256)

    // 1. Containing Marquee query
    // Query a box that strictly contains free-0-image and free-1-note
    const n0 = fixture.nodes.find((n) => n.id === 'free-0-image')
    const n1 = fixture.nodes.find((n) => n.id === 'free-1-note')
    const encloseBox = {
      x: Math.min(n0.x, n1.x) - 10,
      y: Math.min(n0.y, n1.y) - 10,
      width: Math.max(n0.x + n0.width, n1.x + n1.width) - Math.min(n0.x, n1.x) + 20,
      height: Math.max(n0.y + n0.height, n1.y + n1.height) - Math.min(n0.y, n1.y) + 20
    }
    const candidates = index.query(encloseBox)
    check(candidates.some((c) => c.id === n0.id), 'contains free-0-image')
    check(candidates.some((c) => c.id === n1.id), 'contains free-1-note')

    // 2. Crossing Marquee simulation:
    // A narrow box that intersects n0's border but does not contain it
    const intersectBox = {
      x: n0.x + 10,
      y: n0.y + 10,
      width: 20,
      height: 20
    }
    const intersectCandidates = index.query(intersectBox)
    check(intersectCandidates.some((c) => c.id === n0.id), 'crossing box intersects candidate')

    // Test containment condition:
    const contains = (box, node) =>
      node.x >= box.x &&
      node.x + node.width <= box.x + box.width &&
      node.y >= box.y &&
      node.y + node.height <= box.y + box.height

    check(!contains(intersectBox, n0), 'intersecting box does not contain node')
    check(contains(encloseBox, n0), 'enclosing box contains node')
  })

  await group('50-item spatial index benchmark and fork isolation (< 1ms query)', () => {
    const fixture = createStressFixture()
    const records = fixture.nodes.map((n) => ({
      id: n.id,
      bounds: { x: n.x, y: n.y, width: n.width, height: n.height }
    }))
    const index = new Spatial.UniformGridSpatialIndex(records, 256)

    // Benchmark 1000 queries
    const t0 = performance.now()
    const iterations = 1000
    let totalFound = 0
    for (let i = 0; i < iterations; i++) {
      const q = { x: 200 + (i % 50) * 10, y: 200 + (i % 50) * 10, width: 400, height: 300 }
      const res = index.query(q)
      totalFound += res.length
    }
    const t1 = performance.now()
    const avgQueryMs = (t1 - t0) / iterations
    report.benchmarks.spatialQueries1000TotalMs = t1 - t0
    report.benchmarks.spatialQueryAvgMs = avgQueryMs
    check(avgQueryMs < 0.1, `average spatial query time ${avgQueryMs.toFixed(4)}ms is well under 0.1ms (< 1ms target)`)

    // Fork isolation test
    const forked = index.fork(records)
    check(forked.size === index.size, 'fork has identical size')
    forked.upsert({ id: 'ephemeral', bounds: { x: 50, y: 50, width: 50, height: 50 } })
    check(forked.size === index.size + 1, 'fork added record')
    check(!index.get('ephemeral'), 'original index unaffected by fork mutation')
  })

  report.sourceHashesAtEnd = await hashes()
  assert.deepEqual(report.sourceHashesAtEnd, report.sourceHashes, 'source files unchanged during test run')
  report.passed = true
} catch (error) {
  report.failure = {
    message: error.message,
    stack: error.stack?.replace(/data:text\/javascript;base64,[A-Za-z0-9+/=]+/g, '[module]')
  }
  process.exitCode = 1
}

await writeFile(resolve(outputDir, 'report.json'), JSON.stringify(report, null, 2))
console.log(JSON.stringify({
  passed: report.passed,
  checks: report.checks,
  groups: report.groups,
  benchmarks: report.benchmarks,
  failure: report.failure,
  report: resolve(outputDir, 'report.json')
}))

import assert from 'node:assert/strict'
import { readFile, mkdir, writeFile } from 'node:fs/promises'
import { resolve, dirname } from 'node:path'
import { createHash } from 'node:crypto'
import ts from 'typescript'
const productionInputs = ['src/board/diagramPaletteCommands.ts', 'src/board/diagramStructureCore.ts', 'src/board/boardMutationSafety.ts', 'src/board/connectors.ts', 'src/board/columns.ts', 'src/model/vector.ts', 'src/board/nativeCommandJournal.ts', 'scripts/partii-diagram-palette.mjs']
const hashes = async () => Object.fromEntries(await Promise.all(productionInputs.map(async path => [path, createHash('sha256').update(await readFile(resolve(path))).digest('hex')])))
const sourceHashes = await hashes()

const modules = new Map()
async function moduleUrl(path) {
  path = resolve(path)
  if (modules.has(path)) return modules.get(path)
  let code = ts.transpileModule(await readFile(path, 'utf8'), { compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022 } }).outputText
  for (const match of [...code.matchAll(/from\s+['"](\.[^'"]+)['"]/g)]) {
    const imported = resolve(dirname(path), `${match[1]}.ts`), url = await moduleUrl(imported)
    code = code.replaceAll(`'${match[1]}'`, `'${url}'`).replaceAll(`"${match[1]}"`, `"${url}"`)
  }
  const url = `data:text/javascript;base64,${Buffer.from(code).toString('base64')}`
  modules.set(path, url); return url
}
const C = await import(await moduleUrl('src/board/diagramPaletteCommands.ts'))
const G = await import(await moduleUrl('src/board/connectors.ts'))
const H = await import(await moduleUrl('src/board/nativeCommandJournal.ts'))
const report = { passed: false, generatedAt: new Date().toISOString(), groups: [], checks: 0, sourceHashes, limitations: ['Pure production command/geometry/journal helpers; no App/native UI or real disk claim. Automatic curves split into two re-routed curve segments under the existing connector contract.'] }
const output = resolve('output/partii-diagram-palette'); await mkdir(output, { recursive: true })
const check = (condition, message) => { report.checks++; assert(condition, message) }
const ok = (result) => { check(result.ok, result.ok ? 'success' : JSON.stringify(result.issues)); return result.value }
const snapshot = (value) => JSON.stringify(value)
const close = (a, b, tolerance = 1e-6) => Math.hypot(a.x - b.x, a.y - b.y) <= tolerance
const leaf = (id, extra = {}) => ({ id, kind: 'shape', shapeType: 'rectangle', title: id, x: 0, y: 0, width: 160, height: 96, ...extra })
const board = (nodes = [], connectors = []) => ({ id: 'test', title: 'Disposable flow', viewport: { x: 0, y: 0, scale: 1 }, nodes, connectors })
const edge = (extra = {}) => ({ id: 'old-edge', sourcePoint: { x: 0, y: 0 }, targetPoint: { x: 600, y: 0 }, sourcePort: 'right', targetPort: 'left', style: 'straight', color: '#60a5fa', width: 3, dashed: false, startArrow: true, endArrow: true, animated: false, label: 'Preserve this label', labelPosition: { t: .72, offsetX: 8, offsetY: -20, extension: { keep: true } }, futureMetadata: { version: 7 }, ...extra })
const inserted = (extra = {}) => ({ connectorId: 'old-edge', downstreamConnectorId: 'new-edge', node: { id: 'inserted', shape: 'process', title: 'Review' }, ...extra })
async function group(name, run) { const before = report.checks; await run(); report.groups.push({ name, checks: report.checks - before, passed: true }) }
try {
  await group('searchable portable common shapes', () => {
    check(C.DIAGRAM_SHAPE_CATALOG.length === 7, 'seven compact entries')
    check(C.filterDiagramShapes('branch diamond').map((entry) => entry.id).join() === 'decision', 'all query terms search common names/keywords')
    check(C.filterDiagramShapes('START').map((entry) => entry.id).join() === 'start-end', 'case insensitive start/end')
    check(C.filterDiagramShapes('not a shape').length === 0, 'empty search state')
    for (const entry of C.DIAGRAM_SHAPE_CATALOG) {
      const node = ok(C.diagramShapeNode({ shape: entry.id, id: entry.id, center: { x: 300, y: 200 }, title: '<Check & review>' }))
      check(node.id === entry.id && node.x + node.width / 2 === 300 && node.y + node.height / 2 === 200, 'factory exact world frame')
      check(snapshot(JSON.parse(snapshot(node))) === snapshot(node), 'portable model')
      if (entry.id === 'text') check(node.body === '<p>&lt;Check &amp; review&gt;</p>', 'text creation cannot inject markup')
      else if (!['line', 'arrow'].includes(entry.id)) {
        check(node.vectorPath.version === 1 && node.vectorPath.closed && node.body === '<Check & review>' && node.diagramShape === entry.id, 'shared editable core geometry + explicit diagram caption tag')
        check(JSON.parse(snapshot(node)).diagramShape === entry.id, 'diagram caption tag survives serialization')
      }
      if (['text', 'line', 'arrow'].includes(entry.id)) check(node.diagramShape === undefined, 'ordinary text/line/arrow do not acquire a vector caption tag')
    }
    const lightText = ok(C.diagramShapeNode({ id: 'light-text', shape: 'text', center: { x: 100, y: 100 }, textColor: '#302820' })), lightLine = ok(C.diagramShapeNode({ id: 'light-line', shape: 'line', center: { x: 100, y: 100 }, strokeColor: '#234f6a' }))
    check(lightText.textColor === '#302820' && lightLine.strokeColor === '#234f6a', 'caller theme-aware text/stroke defaults persist')
    check(!C.diagramShapeNode({ id: 'bad-color', shape: 'process', center: { x: 100, y: 100 }, color: NaN }).ok, 'invalid appearance type refuses before creation')
  })
  await group('atomic free/group/column creation', () => {
    const original = board([leaf('outsider', { x: 900, locked: true }), { ...leaf('group'), kind: 'group', width: 700, height: 600 }, { ...leaf('column', { x: 750 }), kind: 'column', width: 260, height: 300 }]), before = snapshot(original)
    for (const ownerId of [undefined, 'group', 'column']) {
      const command = ok(C.createDiagramNodeResult(original, { shape: 'process', id: `new-${ownerId}`, center: { x: 300, y: 200 } }, { ownerId }))
      check(command.board.nodes.length === original.nodes.length + 1 && command.connectorIds.length === 0, 'one creation transaction')
      const node = command.board.nodes.at(-1)
      check(ownerId === 'column' ? node.parentColumnId === ownerId && !node.groupId && Math.max(...node.vectorPath.points.map((point) => point.x)) === node.width : node.groupId === ownerId, 'exclusive owner and scaled column path frame')
      check(snapshot(command.board.nodes[0]) === snapshot(original.nodes[0]) && snapshot(original) === before, 'locked outsider/input preserved')
    }
  })
  await group('connected successor directional branching and style', () => {
    const original = board([leaf('source', { rotation: 30 })]), before = snapshot(original)
    for (const direction of ['top', 'right', 'bottom', 'left']) {
      const command = ok(C.createConnectedSuccessorResult(original, { sourceId: 'source', node: { id: `next-${direction}`, shape: 'decision' }, connectorId: `edge-${direction}`, direction, connector: { style: 'curve', linePattern: 'dot', label: 'Yes' } }))
      const connection = command.board.connectors[0]
      check(connection.sourceId === 'source' && connection.targetId === command.nodeId && connection.sourcePort === direction && connection.style === 'curve' && connection.linePattern === 'dot' && connection.label === 'Yes', 'attached direction/style exact')
      check(G.connectorGeometry(connection, command.board.nodes) !== null, 'resolved source/new endpoint')
    }
    const first = ok(C.createConnectedSuccessorResult(original, { sourceId: 'source', node: { id: 'branch-a', shape: 'process' }, connectorId: 'branch-edge-a' }))
    const second = ok(C.createConnectedSuccessorResult(first.board, { sourceId: 'source', node: { id: 'branch-b', shape: 'process' }, connectorId: 'branch-edge-b' }))
    const a = first.board.nodes.at(-1), b = second.board.nodes.at(-1)
    check(a.x !== b.x || a.y !== b.y, 'default branching positions avoid overlap')
    check(snapshot(original) === before, 'source input retained')
  })
  await group('straight split outside identity/arrows/label semantics', () => {
    const original = board([], [edge()]), before = snapshot(original), oldGeometry = G.connectorGeometry(original.connectors[0], [])
    const command = ok(C.insertDiagramNodeOnConnectorResult(original, inserted()))
    const [incoming, outgoing] = command.board.connectors, node = command.board.nodes[0]
    check(incoming.id === 'old-edge' && outgoing.id === 'new-edge' && incoming.targetId === node.id && outgoing.sourceId === node.id, 'old ID upstream/new ID downstream')
    check(snapshot(incoming.sourcePoint) === snapshot(original.connectors[0].sourcePoint) && snapshot(outgoing.targetPoint) === snapshot(original.connectors[0].targetPoint) && incoming.targetPoint === undefined && outgoing.sourcePoint === undefined, 'outside free endpoints exact and inside stale coordinates removed')
    check(incoming.startArrow && !incoming.endArrow && !outgoing.startArrow && outgoing.endArrow, 'two outside arrowheads only')
    check(incoming.label === original.connectors[0].label && outgoing.label === undefined && outgoing.labelPosition === undefined && snapshot(incoming.labelPosition.extension) === snapshot(original.connectors[0].labelPosition.extension), 'defined label transfer and extension preservation')
    check(close(G.connectorLabelPoint(incoming, G.connectorGeometry(incoming, command.board.nodes)), G.connectorLabelPoint(original.connectors[0], oldGeometry)), 'world label position exact')
    check(snapshot(incoming.futureMetadata) === snapshot(outgoing.futureMetadata) && snapshot(incoming.futureMetadata) === snapshot(original.connectors[0].futureMetadata), 'unknown relationship data retained')
    check(snapshot(original) === before, 'split input exact')
  })
  await group('manual elbow partition retains outer route and attached endpoints', () => {
    const original = board([leaf('a', { x: -160, y: -48 }), leaf('b', { x: 600, y: 352 })], [edge({ sourceId: 'a', targetId: 'b', sourcePoint: undefined, targetPoint: undefined, style: 'elbow', bendPoints: [{ x: 200, y: 0 }, { x: 200, y: 300 }, { x: 500, y: 300 }] })])
    const command = ok(C.insertDiagramNodeOnConnectorResult(original, inserted({ fraction: .4 }))), [a, b] = command.board.connectors
    check(a.sourceId === 'a' && b.targetId === 'b' && a.sourcePort === original.connectors[0].sourcePort && b.targetPort === original.connectors[0].targetPort, 'outside attached IDs/ports exact')
    check(snapshot([...a.bendPoints, ...b.bendPoints]) === snapshot(original.connectors[0].bendPoints), 'manual waypoints partition without duplication/loss')
    check(a.style === 'elbow' && b.style === 'elbow' && G.connectorGeometry(a, command.board.nodes).manual && G.connectorGeometry(b, command.board.nodes).manual, 'manual routing remains editable')
    check(close(G.connectorGeometry(a, command.board.nodes).source, G.connectorGeometry(original.connectors[0], original.nodes).source) && close(G.connectorGeometry(b, command.board.nodes).target, G.connectorGeometry(original.connectors[0], original.nodes).target), 'outside painted endpoints remain exact')
  })
  await group('automatic curve split and inherited group semantics', () => {
    const original = board([{ ...leaf('owner'), kind: 'group', width: 800, height: 600 }, leaf('a', { x: 10, y: 100, groupId: 'owner' }), leaf('b', { x: 600, y: 300, groupId: 'owner' })], [edge({ style: 'curve', sourceId: 'a', targetId: 'b', sourcePoint: undefined, targetPoint: undefined, sourcePortMode: 'adaptive', targetPortMode: 'adaptive' })])
    const command = ok(C.insertDiagramNodeOnConnectorResult(original, inserted({ node: { id: 'inserted', shape: 'document' } })))
    check(command.board.nodes.at(-1).groupId === 'owner', 'shared group inherited')
    check(command.board.connectors.every((connection) => connection.style === 'curve' && G.connectorGeometry(connection, command.board.nodes)), 'two resolved auto curves retain route style')
    check(command.board.connectors[0].sourcePortMode === 'adaptive' && command.board.connectors[1].targetPortMode === 'adaptive', 'outside adaptive modes survive')
  })
  await group('ten-node branching map one-command journal/JSON/reload', async () => {
    let current = board(), undo = [], redo = []
    for (let index = 0; index < 10; index++) {
      const before = current, result = index === 0 ? C.createDiagramNodeResult(current, { id: 'node-0', shape: 'start-end', center: { x: 100, y: 100 } }) : C.createConnectedSuccessorResult(current, { sourceId: `node-${Math.floor((index - 1) / 2)}`, node: { id: `node-${index}`, shape: index % 3 === 0 ? 'decision' : 'process', title: `Step ${index}` }, connectorId: `edge-${index}` })
      current = ok(result).board; H.recordNativeCommand(undo, redo, before, current)
      check(snapshot(H.undoNativeCommand(undo, redo)) === snapshot(before), 'one command Undo returns exact before snapshot')
      check(snapshot(H.redoNativeCommand(undo, redo)) === snapshot(current), 'one command Redo returns exact after snapshot')
    }
    check(current.nodes.length === 10 && current.connectors.length === 9 && new Set([...current.nodes, ...current.connectors].map((entry) => entry.id)).size === 19, 'branching 10-node identity fixture')
    check(snapshot(JSON.parse(snapshot(current))) === snapshot(current), 'save/reload exact IDs/geometry/routes/labels')
    await writeFile(resolve(output, 'ten-node-flow.json'), JSON.stringify(current, null, 2))
  })
  await group('read-only/inherited lock/visibility/identity refusal is atomic', () => {
    const original = board([{ ...leaf('owner'), kind: 'group', locked: true }, leaf('source', { groupId: 'owner' }), leaf('target', { x: 600 })], [edge({ sourceId: 'source', targetId: 'target', sourcePoint: undefined, targetPoint: undefined })]), before = snapshot(original)
    const commands = [
      () => C.createDiagramNodeResult(original, { id: 'new', shape: 'process', center: { x: 10, y: 10 } }, { readOnly: true }),
      () => C.createDiagramNodeResult(original, { id: 'new', shape: 'process', center: { x: 10, y: 10 } }, { ownerId: 'owner' }),
      () => C.createConnectedSuccessorResult(original, { sourceId: 'source', node: { id: 'new', shape: 'process' }, connectorId: 'fresh' }),
      () => C.insertDiagramNodeOnConnectorResult(original, inserted()),
      () => C.createDiagramNodeResult(original, { id: 'target', shape: 'process', center: { x: 10, y: 10 } }),
      () => C.createDiagramNodeResult(original, { id: 'new', shape: 'process', center: { x: NaN, y: 10 } }),
      () => C.insertDiagramNodeOnConnectorResult(board([], [edge()]), inserted({ fraction: 0 })),
      () => C.insertDiagramNodeOnConnectorResult(board([], [edge({ mindMap: { treeId: 'tree' } })]), inserted()),
    ]
    for (const run of commands) { const result = run(); check(!result.ok && result.issues[0].detail.length > 5, 'actionable refusal'); check(snapshot(original) === before, 'refusal input retained') }
    for (const property of ['collapsed', 'hidden']) {
      const hidden = board([{ ...leaf('owner'), kind: 'group', [property]: true }, leaf('source', { groupId: 'owner' })])
      check(!C.createConnectedSuccessorResult(hidden, { sourceId: 'source', node: { id: 'new', shape: 'text' }, connectorId: 'new-edge' }).ok, 'inherited hidden/collapse refusal')
    }
  })
  report.sourceHashesAtEnd = await hashes(); assert.deepEqual(report.sourceHashesAtEnd, report.sourceHashes)
  report.passed = true
} catch (error) { report.failure = { message: error.message, stack: error.stack?.replace(/data:text\/javascript;base64,[A-Za-z0-9+/=]+/g, '[production module]') }; process.exitCode = 1 }
await writeFile(resolve(output, 'report.json'), JSON.stringify(report, null, 2)); console.log(JSON.stringify({ passed: report.passed, checks: report.checks, groups: report.groups, failure: report.failure, report: resolve(output, 'report.json') }, null, 2))

import assert from 'node:assert/strict'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import { createHash } from 'node:crypto'
import ts from 'typescript'

// In-memory fixtures only. No Tauri calls, user projects, original assets or EXEs.
const sourcePath = process.env.PARTII_STRUCTURE_SOURCE || new URL('../src/board/diagramStructureCore.ts', import.meta.url)
const code = await readFile(sourcePath, 'utf8')
const output = ts.transpileModule(code, { compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022 } }).outputText
const D = await import(`data:text/javascript;base64,${Buffer.from(output).toString('base64')}`)
const checks = [], test = (name, run) => { run(); checks.push(name) }
const node = (id, extra = {}) => ({ id, kind: 'note', title: id, x: 10, y: 20, width: 100, height: 60, ...extra })
const group = (id, extra = {}) => node(id, { kind: 'group', containerRole: 'group', ...extra })
const column = (id, extra = {}) => node(id, { kind: 'column', ...extra })
const edge = (id, sourceId, targetId, extra = {}) => ({ id, sourceId, targetId, sourcePort: 'right', targetPort: 'left', style: 'elbow', color: '#60a5fa', width: 2, dashed: false, startArrow: false, endArrow: true, animated: false, ...extra })
const value = (result) => { assert.equal(result.ok, true, JSON.stringify(result)); return result.value }
const failure = (result, code) => { assert.equal(result.ok, false); assert(result.issues.some((issue) => issue.code === code), JSON.stringify(result)) }
const base = [group('outer'), group('inner', { groupId: 'outer', containerRole: 'frame' }), column('col', { groupId: 'inner' }), node('a', { parentColumnId: 'col', columnOrder: 0 }), node('b', { groupId: 'inner' }), node('external')]
const digest = (input) => JSON.stringify(input)

test('Group, frame and column remain distinct with valid nested ownership', () => {
  value(D.validateContainerOwnership(base))
  assert.equal(base[1].containerRole, 'frame'); assert.equal(base[2].kind, 'column')
  assert.deepEqual(value(D.containerDescendantIds(base, ['outer'])), ['outer', 'inner', 'col', 'a', 'b'])
})
for (const [name, nodes, code] of [
  ['duplicate identities', [node('a'), node('a')], 'duplicate-id'],
  ['empty identities', [node('')], 'invalid-id'],
  ['dual ownership', [group('g'), column('c'), node('a', { groupId: 'g', parentColumnId: 'c' })], 'ambiguous-owner'],
  ['missing owners', [node('a', { groupId: 'missing' })], 'missing-owner'],
  ['wrong group owner', [column('c'), node('a', { groupId: 'c' })], 'wrong-owner-kind'],
  ['wrong column owner', [group('g'), node('a', { parentColumnId: 'g' })], 'wrong-owner-kind'],
  ['self parenting', [group('g', { groupId: 'g' })], 'self-owner'],
  ['mixed ownership cycles', [group('g', { parentColumnId: 'c' }), column('c', { groupId: 'g' })], 'ownership-cycle'],
  ['frame role on a noncontainer', [node('a', { containerRole: 'frame' })], 'invalid-container-role'],
]) test(`Ownership rejects ${name}`, () => failure(D.validateContainerOwnership(nodes), code))

test('Long imported ownership chains validate iteratively without stack overflow', () => {
  const nodes = Array.from({ length: 4000 }, (_, index) => group(`g${index}`, index ? { groupId: `g${index - 1}` } : {}))
  assert.equal(value(D.validateContainerOwnership(nodes)).size, 4000)
  assert.equal(value(D.containerDescendantIds(nodes, ['g0'])).length, 4000)
})
test('Missing selection is an error, not silent partial mutation', () => failure(D.containerDescendantIds(base, ['outer', 'missing']), 'missing-object'))
test('Inherited lock, hidden and collapse states do not leak selection', () => {
  for (const treatment of [{ locked: true }, { hidden: true }, { collapsed: true }]) {
    const nodes = base.map((entry) => entry.id === 'outer' ? { ...entry, ...treatment } : entry)
    const state = value(D.containerState(nodes, 'a'))
    assert.deepEqual(state.ancestors, ['col', 'inner', 'outer'])
    assert.equal(state.locked, Boolean(treatment.locked)); assert.equal(state.hidden, Boolean(treatment.hidden || treatment.collapsed))
    if (!treatment.locked) assert.deepEqual(value(D.visibleDiagramNodeIds(nodes)), treatment.hidden ? ['external'] : ['outer', 'external'])
  }
  assert.equal(value(D.containerState([group('own', { collapsed: true })], 'own')).hidden, false)
})
test('Unknown object state and unrelated corrupt ownership fail closed', () => {
  failure(D.containerState(base, 'missing'), 'missing-object')
  failure(D.moveContainerWithDescendants([...base, node('bad', { groupId: 'gone' })], [], ['b'], { x: 1, y: 1 }), 'missing-owner')
})

test('Reparent removes old column owner/order, preserves geometry and metadata', () => {
  const before = digest(base), moved = value(D.reparentContainerNodes(base, ['a'], { kind: 'group', id: 'outer' })).find((entry) => entry.id === 'a')
  assert.equal(moved.groupId, 'outer'); assert.equal(moved.parentColumnId, undefined); assert.equal(moved.columnOrder, undefined)
  assert.deepEqual([moved.x, moved.y, moved.width, moved.height], [10, 20, 100, 60]); assert.equal(digest(base), before)
})
test('Reparent appends stable column order without automatic layout', () => {
  const moved = value(D.reparentContainerNodes(base, ['b'], { kind: 'column', id: 'col' })).find((entry) => entry.id === 'b')
  assert.equal(moved.groupId, undefined); assert.equal(moved.parentColumnId, 'col'); assert.equal(moved.columnOrder, 1); assert.equal(moved.y, 20)
})
test('Nested selected roots are not flattened or assigned two owners', () => {
  const moved = value(D.reparentContainerNodes(base, ['inner', 'col', 'a']))
  assert.equal(moved.find((entry) => entry.id === 'inner').groupId, undefined)
  assert.equal(moved.find((entry) => entry.id === 'col').groupId, 'inner')
  assert.equal(moved.find((entry) => entry.id === 'a').parentColumnId, 'col')
})
for (const [name, result, code] of [
  ['self-descendant parent', D.reparentContainerNodes(base, ['outer'], { kind: 'group', id: 'inner' }), 'ownership-cycle'],
  ['missing parent', D.reparentContainerNodes(base, ['b'], { kind: 'group', id: 'missing' }), 'missing-owner'],
  ['wrong destination kind', D.reparentContainerNodes(base, ['b'], { kind: 'column', id: 'outer' }), 'wrong-owner-kind'],
  ['locked destination', D.reparentContainerNodes(base.map((entry) => entry.id === 'col' ? { ...entry, locked: true } : entry), ['external'], { kind: 'column', id: 'col' }), 'uneditable-owner'],
  ['hidden destination', D.reparentContainerNodes(base.map((entry) => entry.id === 'col' ? { ...entry, hidden: true } : entry), ['external'], { kind: 'column', id: 'col' }), 'uneditable-owner'],
]) test(`Reparent rejects ${name}`, () => failure(result, code))

test('Atomic descendant move shifts internal waypoints and leaves boundary routing fixed', () => {
  const edges = [edge('internal', 'a', 'b', { bendPoints: [{ x: 20, y: 30 }], vendorData: { retained: true } }), edge('boundary', 'b', 'external', { bendPoints: [{ x: 99, y: 88 }] }), edge('free', undefined, 'b', { sourcePoint: { x: 4, y: 5 }, bendPoints: [{ x: 66, y: 77 }] })]
  const before = digest({ base, edges }), moved = value(D.moveContainerWithDescendants(base, edges, ['outer', 'a'], { x: 23, y: -7 }))
  assert.deepEqual(moved.movedIds, ['outer', 'inner', 'col', 'a', 'b'])
  moved.nodes.forEach((entry) => assert.deepEqual([entry.x, entry.y], entry.id === 'external' ? [10, 20] : [33, 13]))
  assert.deepEqual(moved.connectors[0].bendPoints, [{ x: 43, y: 23 }]); assert.deepEqual(moved.connectors[0].vendorData, { retained: true })
  assert.equal(moved.connectors[1], edges[1]); assert.deepEqual(moved.connectors[2].sourcePoint, { x: 27, y: -2 }); assert.deepEqual(moved.connectors[2].bendPoints, [{ x: 89, y: 70 }]); assert.equal(digest({ base, edges }), before)
})
test('Detached anchors follow their sole moved attachment once; wholly free routes stay fixed', () => {
  const edges = [edge('free-target', 'a', undefined, { targetPoint: { x: 99, y: 77 }, bendPoints: [{ x: 20, y: 30 }] }), edge('free-source', undefined, 'a', { sourcePoint: { x: 66, y: 44 }, bendPoints: [{ x: 50, y: 60 }] }), edge('fully-free', undefined, undefined, { sourcePoint: { x: 1, y: 2 }, targetPoint: { x: 3, y: 4 }, bendPoints: [{ x: 5, y: 6 }] }), edge('outside-attachment', 'external', undefined, { targetPoint: { x: 7, y: 8 } })]
  const moved = value(D.moveContainerWithDescendants(base, edges, ['outer', 'a'], { x: 10, y: 20 }))
  assert.deepEqual(moved.connectors[0].targetPoint, { x: 109, y: 97 }); assert.deepEqual(moved.connectors[0].bendPoints, [{ x: 30, y: 50 }])
  assert.deepEqual(moved.connectors[1].sourcePoint, { x: 76, y: 64 }); assert.deepEqual(moved.connectors[1].bendPoints, [{ x: 60, y: 80 }])
  assert.equal(moved.connectors[2], edges[2]); assert.equal(moved.connectors[3], edges[3])
  failure(D.moveContainerWithDescendants(base, [edge('bad-free', 'a', undefined, { targetPoint: { x: NaN, y: 1 } })], ['a'], { x: 1, y: 2 }), 'invalid-endpoint')
})
for (const [name, treatment, code] of [['own lock', { locked: true }, 'locked-object'], ['explicit hidden descendant', { hidden: true }, 'hidden-object'], ['collapsed owner', { collapsed: true }, 'hidden-object']]) test(`Atomic movement rejects ${name} without mutating its source`, () => {
  const nodes = base.map((entry) => entry.id === (name === 'collapsed owner' ? 'inner' : 'a') ? { ...entry, ...treatment } : entry), before = digest(nodes)
  failure(D.moveContainerWithDescendants(nodes, [], ['outer'], { x: 5, y: 6 }), code); assert.equal(digest(nodes), before)
})
test('Movement rejects nonfinite coordinates, invalid routes and dangling endpoints', () => {
  failure(D.moveContainerWithDescendants(base, [], ['outer'], { x: Infinity, y: 2 }), 'invalid-delta')
  failure(D.moveContainerWithDescendants(base, [edge('bad', 'a', 'b', { bendPoints: [{ x: NaN, y: 2 }] })], ['outer'], { x: 1, y: 2 }), 'invalid-route')
  failure(D.moveContainerWithDescendants(base, [edge('bad', 'gone', 'b')], ['outer'], { x: 1, y: 2 }), 'missing-endpoint')
  failure(D.moveContainerWithDescendants(base, [edge('same', 'a', 'b'), edge('same', 'a', 'b')], ['outer'], { x: 1, y: 2 }), 'duplicate-connector')
})

const template = value(D.createMindMapTemplate('first-instance', { x: 200, y: 300 }))
test('The template has exactly 20 independent nodes and 19 child-identity edges', () => {
  assert.equal(template.nodes.length, 20); assert.equal(template.connectors.length, 19)
  assert.equal(value(D.validateMindMap(template.nodes, template.treeId)).size, 20)
  value(D.validateMindMapConnectors(template.nodes, template.connectors, template.treeId))
  assert(template.nodes.every((entry) => !entry.groupId && !entry.parentColumnId && !entry.targetBoardId))
})
test('Two template instances share no IDs or tree identities', () => {
  const second = value(D.createMindMapTemplate('second-instance', { x: 800, y: 100 }, [...template.nodes, ...template.connectors].map((entry) => entry.id)))
  assert.notEqual(second.treeId, template.treeId)
  assert.equal(new Set([...template.nodes, ...template.connectors, ...second.nodes, ...second.connectors].map((entry) => entry.id)).size, 78)
  value(D.validateMindMap([...template.nodes, ...second.nodes]))
  failure(D.createMindMapTemplate('first-instance', { x: 0, y: 0 }, template.nodes.map((entry) => entry.id)), 'template-id-collision')
})
test('Template rejects invalid namespace and nonfinite placement', () => {
