  }

  rejects('SVG image mime format (prevents SVG script execution)', (b) => {
    b.pages[0].modules[5].media = { id: 'bad-svg', name: 'hack.svg', mime: 'image/svg+xml', mode: 'embedded', dataUrl: 'data:image/svg+xml;base64,PHN2Zz4=' }
