      text: `Process note ${pageIdx + 1}.${modIdx + 1} detailing pipeline validation.`,
      checked: modIdx % 2 === 0
    }))
  }))
  const longJson = Notebook.exportNotebookJson(longBook)
  const parsedLong = Notebook.parseNotebook(longJson)
