        commands: [
          ['M', cx, cy - radius],
          ['C', cx + k, cy - radius, cx + radius, cy - k, cx + radius, cy],
          ['C', cx + radius, cy + k, cx + k, cy + radius, cx, cy + radius],
          ['C', cx - k, cy + radius, cx - radius, cy + k, cx - radius, cy],
          ['C', cx - radius, cy - k, cx - k, cy - radius, cx, cy - radius],
          ['Z']
        ],
        fill: normalizeColor8(fill),
