        assert_eq!(compute_tiled_lod(1.0, 5), 0);
        assert_eq!(compute_tiled_lod(0.5, 5), 0);
        assert_eq!(compute_tiled_lod(2.0, 5), 1);
        assert_eq!(compute_tiled_lod(4.0, 5), 2);
        assert_eq!(compute_tiled_lod(8.0, 5), 3);
