/* Light-theme completion layer.  Component sheets intentionally keep their
   dark defaults so the canvas can remain art-directed; these selectors make
   every application surface, control and overlay follow the active theme. */
.workspace-light,
.workspace-light * {
  scrollbar-color: var(--border-control) transparent;
}
.workspace-light ::-webkit-scrollbar { width: 10px; height: 10px; }
.workspace-light ::-webkit-scrollbar-track { background: transparent; }
.workspace-light ::-webkit-scrollbar-thumb { background: var(--border-control); border: 3px solid transparent; background-clip: padding-box; border-radius: 8px; }
.workspace-light ::-webkit-scrollbar-thumb:hover { background: var(--gold); background-clip: padding-box; }

.workspace-light .pane-loading,
.workspace-light .asset-manager-loading { background: var(--surface-toolbar) !important; color: var(--text-subtle) !important; }
.workspace-light .pane-toolbar,
.workspace-light .document-toolbar,
.workspace-light .canvas-toolbar { background: var(--surface-toolbar) !important; color: var(--text) !important; border-color: var(--border-subtle) !important; }
.workspace-light .format-button,
.workspace-light .overflow-button,
.workspace-light .tool-button,
.workspace-light .quiet-button.compact { color: var(--text-strong) !important; }
.workspace-light .format-button:hover,
.workspace-light .overflow-button:hover,
.workspace-light .tool-button:hover,
.workspace-light .tool-button.active,
.workspace-light .format-button.active { background: var(--surface-hover) !important; border-color: var(--border-control) !important; }
.workspace-light .canvas-toolbar select,
.workspace-light .document-toolbar select,
.workspace-light .connector-label-input,
.workspace-light .connector-color-control,
.workspace-light .document-more-menu select { background: var(--surface-input) !important; color: var(--text) !important; border-color: var(--border-control) !important; }
.workspace-light .document-more-menu,
.workspace-light .document-layout-inspector,
.workspace-light .document-outline,
.workspace-light .board-export-popover,
.workspace-light .canvas-context-menu,
.workspace-light .color-popover,
.workspace-light .unsorted-panel { background: var(--surface-overlay) !important; color: var(--text) !important; border-color: var(--border-control) !important; box-shadow: 0 15px 40px var(--shadow-overlay) !important; }
.workspace-light .document-more-menu button,
.workspace-light .canvas-context-menu button,
.workspace-light .unsorted-panel button,
.workspace-light .document-outline button { color: var(--text) !important; }
.workspace-light .document-more-menu button:hover,
.workspace-light .canvas-context-menu button:hover,
.workspace-light .unsorted-panel button:hover,
.workspace-light .document-outline button:hover { background: var(--surface-hover) !important; }
.workspace-light .document-more-menu>span,
.workspace-light .document-layout-inspector>header,
.workspace-light .document-layout-inspector>section,
.workspace-light .document-outline header { border-color: var(--border-subtle) !important; }
.workspace-light .document-layout-inspector select,
.workspace-light .document-layout-inspector input,
.workspace-light .geometry-fields input,
