.canvas-toolbar .spectrum-workflow-icon,.appearance-control-grid .spectrum-workflow-icon,.appearance-select-control .spectrum-workflow-icon { width:14px; height:14px; }

/* Every native select receives one theme contract. Local layout rules can still
   choose width and height, but cannot leave a platform-coloured dropdown behind. */
.studio-shell { --select-bg:var(--surface-input); --select-text:var(--text); --select-border:var(--border-control); --select-focus:var(--teal); }
