/* The rail is the primary compact-window affordance. Its tooltip is local to
   the rail so it remains readable even when the main toolbar is overflowing. */
.studio-shell .canvas-tool-rail button[title] { position: relative; }
.studio-shell .canvas-tool-rail button[title]::after {
  content: attr(title);
  position: absolute;
  z-index: 200;
  left: calc(100% + 9px);
  top: 50%;
  width: max-content;
  max-width: 220px;
  padding: 6px 8px;
  border: 1px solid var(--border-control);
  border-radius: 5px;
  background: var(--surface-overlay);
  color: var(--text-strong);
  box-shadow: 0 8px 22px var(--shadow-overlay);
  font: 10px/1.25 Inter, sans-serif;
  text-align: left;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-50%) translateX(-3px);
  transition: opacity .12s ease, transform .12s ease;
}
.studio-shell .canvas-tool-rail button[title]:hover::after,
.studio-shell .canvas-tool-rail button[title]:focus-visible::after {
  opacity: 1;
  transform: translateY(-50%) translateX(0);
}

