.node-column.column-presentation-top-strip .column-header { height: 46px; border-top: 8px solid var(--node-accent); background: color-mix(in srgb, var(--node-accent) 10%, #20242a); }
.node-column.column-presentation-header .column-header { border-top: 4px solid var(--node-accent); background: color-mix(in srgb, var(--node-accent) 27%, #20242a); }
.workspace-light .node-column.column-presentation-background { background-color: color-mix(in srgb, var(--node-accent) 30%, #f4ede4) !important; }
.workspace-light .node-column.column-presentation-background .column-header { background: color-mix(in srgb, var(--node-accent) 38%, #fff9f0); }
.workspace-light .node-column.column-presentation-top-strip .column-header { background: color-mix(in srgb, var(--node-accent) 14%, #f3eadf); }
