.node-column .column-header button:hover { color: var(--node-text); }

/* Fast contextual recoloring: keep the project palette directly beside the
   column title so a color change does not require leaving the canvas. */
.column-header-copy { min-width: 0; display: grid; justify-items: center; gap: 4px; }
.column-header-swatches { position: absolute; left: 9px; display: flex !important; align-items: center; gap: 3px; max-width: 92px; }
.column-header-swatches button { position: static; top: auto; right: auto; width: 13px; height: 13px; display: block; flex: none; padding: 0; border: 1px solid #ffffff45; border-radius: 50%; background: var(--column-color); cursor: pointer; box-shadow: inset 0 0 0 1px #0003; transition: transform .12s ease, box-shadow .12s ease; }
.column-header-swatches button.active { outline: 2px solid var(--eclipse-gold); outline-offset: 1px; }
.column-header-swatches button:hover { transform: scale(1.15); box-shadow: 0 0 0 1px var(--eclipse-gold); }
.workspace-light .column-header-swatches button { border-color: #ffffffaa; }

/* Child cards use their own stacking layers. Header actions live cleanly in the column header. */
.node-column .column-header-swatches { visibility:hidden; pointer-events:none; }
.node-column .column-header>.column-collapse-control { position: absolute; right: 8px; top: 8px; width: 22px; height: 22px; display: inline-flex; align-items: center; justify-content: center; border: 1px solid transparent; border-radius: 4px; background: #1c1f2599; color: #d8dbe1; padding: 0; font-size: 13px; line-height: 1; cursor: pointer; pointer-events: auto; z-index: 5; }
.node-column .column-header>.column-collapse-control:hover { border-color: color-mix(in srgb, var(--node-accent) 70%, #fff); background: color-mix(in srgb, var(--node-accent) 24%, #171a1f); color: #fff; }
.workspace-light .node-column .column-header>.column-collapse-control { background: #fffaf3e8; color: #4b4036; border-color: #cdbdab; }
.column-header-controls-overlay { display: none !important; }
.node-shape:has(.node-vector-shape) { pointer-events:none; }
.node-shape .node-vector-shape path,.node-shape .node-vector-shape rect,.node-shape .node-vector-shape line { pointer-events:visiblePainted; cursor:move; }
.node-shape .node-vector-shape .shape-hit-area { pointer-events:all; cursor:move; }
.node-shape .node-vector-shape [pointer-events="none"] { pointer-events:none; }
