.vector-node-editor .vector-anchor.selected { background:#f8d39c; border-color:#fff6d4; box-shadow:0 0 0 3px #f1c38466; }
.vector-node-editor .vector-anchor.endpoint { border-radius:2px; transform:translate(-50%,-50%) rotate(45deg); }
