/* Milanote-style column color treatment: colors are chosen from the shared
   Color panel, never from controls mounted on the column surface. Keep the
   column tint coherent instead of mixing the accent with the old gold/green
   gradient. */
.node-column { background-image: none; background-color: color-mix(in srgb, var(--node-accent) 20%, #20242a); }
