.node-column.column-presentation-top-strip .column-header { background: color-mix(in srgb, var(--node-accent) 16%, #20242a); }
.node-column.column-presentation-header .column-header { background: color-mix(in srgb, var(--node-accent) 28%, #20242a); }
.column-header-swatches { display: none !important; }
