/* Laptop density keeps the canvas primary while retaining a readable project
   navigator, inspector and filmstrip. More aggressive hiding remains below
   the existing compact breakpoints. */
@media (max-width: 1280px) and (min-width: 1081px) {
  .studio-shell .app-body { grid-template-columns: 196px minmax(0, 1fr) 236px; }
  .studio-shell .brand-block { width: 190px; }
