  .studio-shell .project-board-cover { width: 44px; height: 44px; }
  .studio-shell .filmstrip-board { flex-basis: 166px; }
  .studio-shell .filmstrip-open-board { grid-template-columns: 86px minmax(0, 1fr); }
  .studio-shell .filmstrip-cover { height: 78px; }
}

/* Canvas interaction parity: the rail stays fixed in screen space while the
   marquee is intentionally outside the transformed board-world. */
.studio-shell .canvas-tool-rail {
  top: 50%;
  max-height: calc(100% - 18px);
  box-sizing: border-box;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  transform: translateY(-50%);
}
