.studio-shell .canvas-toolbar { overflow-x: auto; overflow-y: hidden; scrollbar-width: none; }
.studio-shell .canvas-toolbar::-webkit-scrollbar { display: none; }
.studio-shell .board-node.selected { border-color: var(--eclipse-gold); box-shadow: 0 0 0 1px var(--canvas-surface),0 0 0 3px var(--eclipse-gold),0 14px 34px var(--shadow-overlay); }

.text-entry-backdrop { position:fixed; z-index:1000; inset:0; display:grid; place-items:center; padding:20px; background:var(--ui-overlay-scrim,#0009); backdrop-filter:blur(5px); }
.studio-shell .text-entry-backdrop { z-index:2000; }
.app-decision-message { white-space:pre-wrap; overflow-wrap:anywhere; max-height:min(48vh,420px); overflow:auto; color:var(--text); font-size:14px; line-height:1.5; margin:0; }
.automatic-board-preview { display:block; width:100%; height:100%; object-fit:contain; }
.text-entry-dialog { box-sizing:border-box; width:min(460px,calc(100vw - 32px)); display:grid; gap:13px; padding:20px; border:1px solid var(--border-control); border-radius:11px; background:var(--surface-overlay); color:var(--text); box-shadow:0 24px 72px var(--shadow-overlay); }
.text-entry-dialog>header { display:flex; align-items:center; justify-content:space-between; margin:-4px 0 2px; color:var(--gold); font-size:10px; font-weight:700; letter-spacing:.13em; }
.text-entry-dialog>header button { width:30px; height:30px; border:1px solid transparent; border-radius:6px; background:transparent; color:var(--text-subtle); font-size:20px; cursor:pointer; }
.text-entry-dialog>header button:hover { border-color:var(--border-control); background:var(--surface-hover); color:var(--text-strong); }
.text-entry-dialog h2 { margin:0; color:var(--text-strong); font:500 23px/1.2 "Iowan Old Style",Georgia,serif; }
.text-entry-dialog>label { color:var(--text-subtle); font-size:12px; }
.text-entry-dialog>input { box-sizing:border-box; width:100%; height:42px; border:1px solid var(--border-control); border-radius:6px; outline:none; background:var(--surface-input); color:var(--text-strong); padding:0 12px; font-family:inherit; font-size:14px; line-height:1.2; }
.text-entry-dialog>input:focus { border-color:var(--focus-ring); box-shadow:0 0 0 2px color-mix(in srgb,var(--focus-ring) 25%,transparent); }
.text-entry-help { max-height:190px; overflow:auto; margin:0; border:1px solid var(--border-subtle); border-radius:6px; background:var(--surface-input); color:var(--text-subtle); padding:10px; white-space:pre-wrap; font-family:inherit; font-size:12px; line-height:1.6; }
.text-entry-dialog>footer { display:flex; justify-content:flex-end; gap:9px; margin-top:6px; }
.text-entry-dialog>footer button { min-width:82px; height:36px; border:1px solid var(--border-control); border-radius:6px; background:var(--surface-toolbar); color:var(--text); padding:0 14px; font-family:inherit; font-size:13px; font-weight:500; line-height:1; cursor:pointer; }
.text-entry-dialog>footer button:hover { border-color:var(--gold); }
.text-entry-dialog>footer .primary-button { border-color:var(--gold); background:var(--gold); color:#1d1a16; }
.text-entry-dialog>footer .primary-button:hover { filter:brightness(1.08); }
.studio-shell .board-node.marquee-preview { border-color: var(--eclipse-gold); box-shadow: 0 0 0 2px color-mix(in srgb,var(--eclipse-gold) 75%,transparent),0 0 22px color-mix(in srgb,var(--eclipse-gold) 28%,transparent); }
.studio-shell.workspace-light .board-node.selected { box-shadow: 0 0 0 1px #fffaf3,0 0 0 3px #8e5b2c,0 12px 30px #75675444; }
.studio-shell .vector-anchor.marquee-preview { background: var(--eclipse-gold); box-shadow: 0 0 0 3px color-mix(in srgb,var(--eclipse-gold) 35%,transparent); }
.studio-shell .vector-segment-selected.preview { opacity: .58; stroke-dasharray: 5 4; }

@media (max-height: 760px) {
  .studio-shell .canvas-tool-rail { width: 70px; }
  .studio-shell .tool-rail-group { grid-template-columns: repeat(2,30px); align-content: start; }
  .studio-shell .tool-rail-group button { width: 30px; height: 30px; }
  .studio-shell .tool-rail-history { grid-template-columns: repeat(2,30px); }
}

/* Eclipse shell hierarchy: project identity, workspace mode, project tools,
   theme, and save each have a distinct role instead of one undifferentiated row. */
.studio-shell .project-tools-cluster { position: relative; flex: none; }
.studio-shell .project-tools-toggle { display: flex; align-items: center; gap: 7px; }
.studio-shell .project-tools-toggle span { color: var(--eclipse-gold); font-size: 9px; }
.studio-shell .project-tools-menu { position: absolute; z-index: 120; top: calc(100% + 9px); right: 0; width: min(258px, calc(100vw - 24px)); display: grid; gap: 2px; padding: 8px; border: 1px solid var(--line-strong); border-radius: 8px; background: color-mix(in srgb,var(--surface-overlay) 96%,transparent); box-shadow: 0 18px 44px var(--shadow-overlay); backdrop-filter: blur(14px); }
.studio-shell .project-tools-menu::before { content:""; position: absolute; right: 34px; top: -5px; width: 8px; height: 8px; border-left: 1px solid var(--line-strong); border-top: 1px solid var(--line-strong); background: var(--surface-overlay); transform: rotate(45deg); }
.studio-shell .project-tools-menu button { min-width: 0; min-height: 43px; display: grid; grid-template-columns: 25px minmax(0,1fr); grid-template-rows: auto auto; align-items: center; column-gap: 8px; border: 0; border-radius: 5px; background: transparent; color: var(--text); padding: 6px 8px; text-align: left; cursor: pointer; }
.studio-shell .project-tools-menu button:hover,.studio-shell .project-tools-menu button:focus-visible { background: var(--surface-hover); outline: 1px solid var(--line-strong); }
.studio-shell .project-tools-menu button:disabled { opacity: .4; cursor: default; }
.studio-shell .project-tools-menu button>span { grid-row: 1/3; color: var(--eclipse-gold); text-align: center; }
.studio-shell .project-tools-menu strong { font-size: 10px; }
.studio-shell .project-tools-menu small { color: var(--muted); font-size: 8px; }
.studio-shell .project-tools-menu>i { height: 1px; margin: 4px 6px; background: linear-gradient(90deg,var(--line-strong),var(--eclipse-gold),var(--line-strong)); }
.studio-shell .inspector-toggle,.studio-shell .inspector-drawer-close { display: none; }

/* Creation belongs to the vertical rail. The horizontal bar now stays
   contextual and no longer repeats Select, Type, Shape, Connector or Import. */
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Select and move cards"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Add rich-text card"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Draw shape"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Add card column"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Import images"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Import videos"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Import 3D model"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Import documents"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Link to another board"],
.studio-shell :is(.canvas-toolbar,.canvas-context-controls)>button[aria-label="Draw connections"] { display: none; }

/* Illustrator-style canvas appearance panel keeps persistent view controls off the main toolbar. */
.studio-shell .canvas-pane { position:relative; }
.appearance-panel { position:absolute; z-index:78; top:52px; right:12px; width:min(292px,calc(100% - 24px)); max-height:calc(100% - 64px); overflow:auto; box-sizing:border-box; border:1px solid var(--border-control); border-radius:8px; background:linear-gradient(180deg,#24282eF8,#171a1fF8); color:var(--text); box-shadow:0 18px 50px #0009; }
.appearance-panel>header { position:sticky; top:0; z-index:1; display:flex; align-items:center; justify-content:space-between; min-height:42px; padding:0 12px; border-bottom:1px solid var(--border-subtle); background:#20242af5; }
.appearance-panel>header strong { font:650 12px/1 Inter,sans-serif; letter-spacing:.02em; }
.appearance-panel>header button { width:28px; height:28px; border:0; background:transparent; color:var(--muted); font-size:18px; cursor:pointer; }
.appearance-panel>section { padding:10px 12px 12px; border-bottom:1px solid var(--border-subtle); }
.appearance-panel>section:last-child { border-bottom:0; }
.appearance-panel h3 { margin:0 0 8px; color:var(--muted); font:650 9px/1 Inter,sans-serif; letter-spacing:.1em; text-transform:uppercase; }
.appearance-control-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; }
.appearance-control-grid .quiet-button { justify-content:flex-start; min-width:0; height:32px; padding:0 9px; }
.appearance-control-grid .toolbar-icon-button svg,.appearance-select-control svg { width:15px; height:15px; flex:none; fill:none; stroke:currentColor; stroke-width:1.8; stroke-linecap:round; stroke-linejoin:round; }
.appearance-color-swatch { width:15px; height:15px; flex:none; border:1px solid #ffffff66; border-radius:50%; box-shadow:inset 0 0 0 1px #0005; }
.appearance-select-control { grid-column:1/-1; display:grid; grid-template-columns:auto minmax(0,1fr); align-items:center; gap:10px; min-height:34px; padding:5px 7px 5px 9px; border:1px solid var(--border-control); border-radius:5px; background:var(--surface-control); color:var(--text); font-size:10px; }
.appearance-select-control>span { display:flex; align-items:center; gap:6px; }
.appearance-select-control select { min-width:0; height:26px; border:1px solid var(--border-control); border-radius:4px; background:var(--surface-raised); color:var(--text); }
.appearance-zoom { display:flex; align-items:center; justify-content:center; min-height:30px; border:1px solid var(--border-subtle); border-radius:5px; color:var(--muted); font:600 10px/1 Inter,sans-serif; }
.workspace-light .appearance-panel { border-color:#baa995; background:linear-gradient(180deg,#fffdf9FA,#f4ede5FA); box-shadow:0 18px 50px #7567543d; }
.workspace-light .appearance-panel>header { background:#f8f1e8f7; }
.workspace-light .appearance-select-control { border-color:#cbbba9; background:#fffaf3; }
.workspace-light .appearance-select-control select { border-color:#cbbba9; background:#fff; color:#3c3630; }

/* Board-owned colour is rendered as one deliberate mode, never as a muddy
   green/gold gradient mixed with application chrome. */
.studio-shell .node-column { background-image: none !important; background-color: #202226 !important; border-color: color-mix(in srgb,var(--node-accent) 62%,var(--line-strong)); }
.studio-shell .node-column .column-header { background: #26282d; color: var(--node-text); }
.studio-shell .node-column.column-presentation-background { background-color: color-mix(in srgb,var(--node-accent) 58%,#202226) !important; }
.studio-shell .node-column.column-presentation-background .column-header { border-top: 0; border-bottom: 1px solid color-mix(in srgb,var(--node-accent) 70%,#fff); background: color-mix(in srgb,var(--node-accent) 72%,#202226); }
.studio-shell .node-column.column-presentation-top-strip .column-header { border-top: 8px solid var(--node-accent); background: #26282d; }
.studio-shell .node-column.column-presentation-header .column-header { border-top: 0; background: var(--node-accent); }
.studio-shell .node-column.column-presentation-black-turquoise { border-color:#44d8cf; background:#050708; box-shadow:0 12px 30px #0009,inset 0 1px #ffffff0a; }
.studio-shell .node-column.column-presentation-black-turquoise .column-header { height:46px; border-top:7px solid #55e3d8; border-bottom:1px solid #55e3d855; background:#090c0e; }
.studio-shell .node-column.column-presentation-black-turquoise .column-header small { color:#8ce9e2; }
.studio-shell.workspace-light .node-column.column-presentation-black-turquoise { border-color:#238d87; background:#121719; }
.studio-shell.workspace-light .node-column.column-presentation-black-turquoise .column-header { border-top-color:#2fc5bb; background:#182022; }

.project-inspector-cover { position:relative; isolation:isolate; }
.project-inspector-cover.cover-drop-active { outline:2px solid #55e3d8; outline-offset:-4px; }
.project-cover-actions { display:flex; flex-wrap:wrap; gap:9px; align-items:center; }
.project-cover-picker { position:absolute; z-index:20; top:calc(100% - 5px); left:9px; right:9px; max-height:235px; overflow:auto; border:1px solid #414752; border-radius:6px; background:#14171c; box-shadow:0 16px 35px #000b; padding:7px; }
.project-cover-picker header { display:flex; align-items:center; justify-content:space-between; margin-bottom:6px; color:#e6e1d9; font:700 8px/1 Inter,sans-serif; text-transform:uppercase; letter-spacing:.08em; }
.project-cover-picker header button { border:0; background:transparent; color:#d5b488; font-size:14px; cursor:pointer; }
.project-cover-picker>div { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:5px; }
.project-cover-picker>div>button { min-width:0; display:grid; gap:3px; border:1px solid #373d47; border-radius:4px; background:#20242b; color:#dce0e4; padding:3px; cursor:pointer; }
.project-cover-picker>div>button:hover { border-color:#55e3d8; background:#282f35; }
.project-cover-picker>div>button>span { display:block; aspect-ratio:1.2; border-radius:2px; background:#2d333b center/cover no-repeat; }
.project-cover-picker>div>button>small { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:7px; }
.project-cover-picker>p { margin:4px; color:#aeb4bd; font-size:8px; }
.workspace-light .project-cover-picker { border-color:#c4b7a5; background:#fffaf3; }.workspace-light .project-cover-picker header { color:#3b342d; }.workspace-light .project-cover-picker>div>button { border-color:#cbbdac; background:#f0e8dc; color:#423a31; }
.studio-shell.workspace-light .node-column { background-color: #f4ede4 !important; }
.studio-shell.workspace-light .node-column.column-presentation-background { background-color: color-mix(in srgb,var(--node-accent) 46%,#f4ede4) !important; }
.studio-shell.workspace-light .node-column.column-presentation-background .column-header { background: color-mix(in srgb,var(--node-accent) 62%,#fff9f0); }
.studio-shell.workspace-light .node-column.column-presentation-top-strip .column-header { background: #f3eadf; }
.studio-shell.workspace-light .node-column.column-presentation-header .column-header { background: var(--node-accent); }

/* The minimap should support orientation without competing with selected art. */
.studio-shell .board-minimap { opacity: .68; transition: opacity 140ms ease-out,border-color 140ms ease-out; }
.studio-shell .board-minimap:hover,.studio-shell .board-minimap:focus-visible { opacity: 1; border-color: var(--eclipse-gold); }

/* Complete light-theme parity for empty project artwork surfaces. */
.studio-shell.workspace-light .project-board-cover { background-color:#eee5d9 !important; color:#8a5828; box-shadow:inset 0 0 0 1px #d1c2b0; }
.studio-shell.workspace-light .project-inspector-cover { background-color:#f0e7dc; border-color:var(--border-subtle); }
.studio-shell.workspace-light .project-inspector-cover h2 { color:var(--text-strong); text-shadow:none; }
.studio-shell.workspace-light .project-inspector-cover>span { color:var(--text-subtle); }
.studio-shell.workspace-light .project-inspector-cover button { color:#8a5828; }
.studio-shell.workspace-light .project-inspector-image-slot:not(.has-image) { border-color:#b9aa98; background:#fffaf3; color:#71695f; }
.studio-shell.workspace-light .project-inspector-image-slot:not(.has-image):hover,.studio-shell.workspace-light .project-inspector-image-slot:not(.has-image).drop-active { border-color:#277b77; background:#f4eee5; color:#315f5b; }
.studio-shell.workspace-light .project-inspector-image-slot:not(.has-image) strong { color:#3d3730; }
.studio-shell.workspace-light .project-inspector-image-slot:not(.has-image) small { color:#81776c; }
.studio-shell.workspace-light .project-inspector-image-placeholder { border-color:#a89783; color:#a66e36; background:#fffdf8; }

@media (max-width: 1080px) {
  .studio-shell .inspector-toggle { display: inline-flex; align-items: center; }
  .studio-shell .project-inspector { display: block; position: fixed; z-index: 110; top: 58px; right: 0; bottom: 25px; width: min(300px,82vw); transform: translateX(102%); transition: transform 150ms ease-out; box-shadow: -18px 0 44px var(--shadow-overlay); }
  .studio-shell .project-inspector.drawer-open { transform: translateX(0); }
  .studio-shell .inspector-drawer-close { display: grid; place-items: center; position: absolute; z-index: 4; top: 8px; right: 8px; width: 28px; height: 28px; border: 1px solid #ffffff55; border-radius: 50%; background: #101116bb; color: #fffaf3; cursor: pointer; }
}

@media (max-width: 900px) {
  .studio-shell .project-tools-toggle { width: 34px; overflow: hidden; padding: 0 9px; color: transparent; }
  .studio-shell .project-tools-toggle span { position: absolute; color: var(--eclipse-gold); font-size: 14px; }
  .studio-shell .inspector-toggle { width: 34px; overflow: hidden; padding: 0; color: transparent; }
  .studio-shell .inspector-toggle::before { content:"I"; display: grid; place-items: center; width: 100%; color: var(--text); font: 600 13px/1 "Iowan Old Style",Georgia,serif; }
}

/* Final tool-rail state contract. Spectrum SVG masks must use the button's
   semantic foreground; legacy span rules otherwise paint them as dividers. */
.studio-shell .canvas-tool-rail button { color: var(--text); }
.studio-shell .canvas-tool-rail button:hover { color: var(--text-strong); }
.studio-shell .canvas-tool-rail button.active { color: var(--eclipse-gold); }
.studio-shell .canvas-tool-rail button:disabled { color: var(--disabled-text); opacity: 1; }
.studio-shell .canvas-tool-rail .tool-rail-subboard { background: #486ed1; border-color: #7093ec; color: #fff; }
.studio-shell .canvas-tool-rail .tool-rail-subboard:hover { background: #5b7fe0; border-color: #a3bcff; color: #fff; }
.studio-shell .canvas-tool-rail .canvas-subtools { display: grid; gap: 3px; padding-top: 5px; border-top: 1px solid var(--line-strong); }
.studio-shell .canvas-tool-rail .canvas-subtools button { background: color-mix(in srgb, var(--panel-raised) 55%, transparent); }
.studio-shell .canvas-tool-rail .canvas-subtools button:hover,
.studio-shell .canvas-tool-rail .canvas-subtools button.active { background: var(--selection-surface); }
.studio-shell .canvas-subtools { position: absolute; z-index: 76; left: 58px; top: 12px; display: grid; gap: 3px; width: 190px; max-height: calc(100% - 24px); overflow: auto; padding: 8px; border: 1px solid var(--border-control); border-radius: 12px; background: var(--surface-overlay); box-shadow: 0 16px 36px var(--shadow-overlay); }
.studio-shell .canvas-subtools button { display: grid; grid-template-columns: 26px minmax(0, 1fr); align-items: center; min-height: 34px; padding: 3px 7px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--text); text-align: left; font: 12px/1.3 Inter, sans-serif; cursor: pointer; }
.studio-shell .canvas-subtools button::after { content: attr(aria-label); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.studio-shell .canvas-subtools button:hover,.studio-shell .canvas-subtools button.active { background: var(--surface-hover); border-color: var(--border-control); }
.studio-shell .canvas-subtools button:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 1px; }
.studio-shell .canvas-subtools button:disabled { opacity: .45; cursor: default; }
.studio-shell .canvas-subtools svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
@media (max-width: 900px) { .studio-shell .canvas-subtools { left: 50px; width: min(190px, calc(100% - 58px)); } }
.studio-shell .canvas-tool-rail .spectrum-workflow-icon,
.workspace-light .studio-shell .canvas-tool-rail .spectrum-workflow-icon {
  margin: 0;
  background: currentColor;
}

/* Direct Select keeps live primitives live: its anchors edit bounds rather
   than converting a labelled rectangle or ellipse into an unrelated path. */
.live-shape-node-editor,
.node-shape:has(.node-shape-ellipse) .vector-node-editor { pointer-events: none; }
.live-shape-direct-overlay { z-index: 60; }
.live-shape-node-editor .live-shape-anchor { cursor: nwse-resize; }
.live-shape-node-editor .anchor-nw { left: 0; top: 0; }
.live-shape-node-editor .anchor-ne { left: 100%; top: 0; cursor: nesw-resize; }
.live-shape-node-editor .anchor-se { left: 100%; top: 100%; }
.live-shape-node-editor .anchor-sw { left: 0; top: 100%; cursor: nesw-resize; }
.live-shape-node-editor.ellipse .anchor-n { left: 50%; top: 0; cursor: ns-resize; }
.live-shape-node-editor.ellipse .anchor-e { left: 100%; top: 50%; cursor: ew-resize; }
.live-shape-node-editor.ellipse .anchor-s { left: 50%; top: 100%; cursor: ns-resize; }
.live-shape-node-editor.ellipse .anchor-w { left: 0; top: 50%; cursor: ew-resize; }

/* Keep project context available while making the active canvas selection visible. */
.studio-shell .project-inspector .inspector-selection {
  gap: 8px;
  background: var(--surface-overlay);
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-strong);
}
.inspector-selection>header small,
.inspector-selection>small,
.inspector-selection p { color: var(--text-subtle); }
.inspector-selection>strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; }
.inspector-selection p { margin: 0; font-size: 10px; text-transform: capitalize; }
.inspector-selection dl { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 6px; margin: 3px 0; }
.inspector-selection dl div { display: flex; justify-content: space-between; gap: 6px; padding: 6px 7px; border: 1px solid var(--border-subtle); border-radius: 4px; background: var(--surface-input); }
.inspector-selection dt { color: var(--text-subtle); }
.inspector-selection dd { margin: 0; font-variant-numeric: tabular-nums; }
.inspector-selection>small { line-height: 1.4; }

/* Trash follows the visual, date-grouped review pattern without changing restore semantics. */
.trash-viewer .trash-day { display: grid; gap: 8px; }
.trash-viewer .trash-day h3 { display: flex; align-items: center; gap: 8px; margin: 10px 4px 2px; color: var(--text-subtle); font-size: 11px; font-weight: 600; }
.trash-viewer .trash-day h3 span { color: var(--muted); font-size: 9px; font-weight: 400; }
.trash-viewer .trash-entry { grid-template-columns: 98px minmax(0,1fr) auto; gap: 12px; min-height: 104px; }
.trash-entry-preview { width: 98px; height: 82px; display: grid; place-content: center; justify-items: center; gap: 4px; overflow: hidden; border: 1px solid var(--border-subtle); border-radius: 4px; background: var(--surface-overlay); color: var(--text-subtle); }
.trash-entry-preview img { width: 100%; height: 100%; object-fit: cover; }
.trash-entry-preview .trash-preview-symbol { font-size: 24px; line-height: 1; }
.trash-entry-preview small { font-size: 9px; }
.trash-entry-preview .trash-preview-excerpt { max-width: 86px; max-height: 30px; overflow: hidden; color: var(--text-subtle); text-align: center; line-height: 1.2; }
.trash-entry-preview .trash-preview-shape { width: 52px; height: 44px; border: 1px solid var(--text-subtle); }
.trash-entry-preview.shape-ellipse .trash-preview-shape { border-radius: 50%; }
.trash-entry-detail { min-width: 0; display: grid; align-content: center; gap: 5px; }
.trash-entry-detail small { display: block; }
.trash-entry-detail .trash-restore-warning { color: var(--error); }
.trash-viewer .trash-entry-actions button:disabled { opacity: .5; cursor: not-allowed; }
@media (max-width: 650px) {
  .trash-viewer .trash-entry { grid-template-columns: 70px minmax(0,1fr); }
  .trash-entry-preview { width: 70px; height: 70px; }
  .trash-viewer .trash-entry-actions { grid-column: 1 / -1; justify-content: flex-end; }
}

.navigator-item-menu { position: fixed; z-index: 120; width: 210px; display: grid; gap: 2px; padding: 6px; border: 1px solid var(--border-control); border-radius: 7px; background: var(--surface-overlay); box-shadow: 0 12px 30px var(--shadow-overlay); color: var(--text-strong); }
.studio-shell > .navigator-item-menu { z-index: 1500; max-height: calc(100dvh - 16px); overflow-y: auto; }
.studio-shell .node-shape:has(> .node-shape-label.rectangle) { background: var(--node-accent); }
.navigator-item-menu strong { overflow: hidden; padding: 7px 8px; border-bottom: 1px solid var(--border-subtle); font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.navigator-item-menu button { min-height: 30px; border: 0; border-radius: 4px; background: transparent; color: var(--text-subtle); padding: 0 8px; text-align: left; font-size: 11px; cursor: pointer; }
