  opacity:1;
}
.studio-shell .questionnaire-toolbar-title { color:var(--text-strong); }
.studio-shell .project-board-cards small { color:var(--text-subtle); }
.studio-shell .project-board-strip>header div { color:var(--text-subtle); }
.studio-shell .project-board-strip>header strong { color:var(--gold); }
.studio-shell.workspace-light .project-board-cards>button.active { box-shadow:inset 2px 0 var(--gold),0 0 0 1px var(--gold); }
@media (max-width:760px) {
  .studio-shell .board-navigation-create,
  .studio-shell .board-cover-trigger,
  .studio-shell .project-board-strip-toggle { max-width:none; min-width:30px; width:30px; padding:0; overflow:hidden; font-size:0; }
  .studio-shell .board-navigation-create::before { content:'＋'; font-size:18px; }
  .studio-shell .board-cover-trigger::before { content:'▧'; font-size:16px; }
  .studio-shell .project-board-strip-toggle::before { content:'▦'; font-size:16px; }
  .studio-shell .board-navigation>button { min-height:30px; }
}
@media (prefers-reduced-motion:reduce) {
  .studio-shell *, .studio-shell *::before, .studio-shell *::after {
    animation-duration:0.01ms !important;
    transition-duration:0.01ms !important;
    scroll-behavior:auto !important;
  }
}

/* The shell's readable text states win over older decorative colour rules. */
.studio-shell .eyebrow,
.studio-shell .tree-section-label,
.studio-shell .project-inspector>section>header .inspector-section-toggle span,
.studio-shell .inspector-status small,
.studio-shell .inspector-empty,
.studio-shell .inspector-link small,
.studio-shell .project-board-cards small { color:var(--ui-label-text); }
.studio-shell .questionnaire-toolbar-title { color:var(--text-strong) !important; }
.studio-shell.workspace-light .brand-mark i,
.studio-shell.workspace-light .asset-summary-heading>button,
.studio-shell.workspace-light .project-inspector>section>header button:not(.inspector-section-toggle) { color:var(--ui-accent-text); }
.studio-shell.workspace-light .mode-switch button:not(.active) { color:var(--ui-label-text); }
.studio-shell.workspace-light .mode-switch button.active { color:var(--text-strong); background:var(--surface-overlay); }
.studio-shell.workspace-light .app-bar>.quiet-button { color:var(--text-strong); background:var(--surface-control); }
.studio-shell.workspace-light .app-bar>.quiet-button:disabled { color:var(--ui-disabled-text); background:var(--surface-control); }
.studio-shell.workspace-light .asset-problem { color:#a3332b; }
.studio-shell.workspace-light .project-inspector-cover>span,
.studio-shell.workspace-light .inspector-status>div>span { color:var(--ui-label-text); }
.studio-shell.workspace-light .inspector-status>div>strong { color:var(--text-strong); }
.studio-shell .navigator .muted,
.studio-shell .project-inspector footer small,
.studio-shell .project-inspector-image-slot small { color:var(--ui-label-text); }
.studio-shell.workspace-light .app-bar .primary-button { color:#fff; background:#8c5f38; }
.studio-shell.workspace-light .app-bar .primary-button:hover { color:#201910; }
.studio-shell .node-column .column-header-copy>small { background:#211d1a; color:#f5f2ed; padding:2px 4px; border-radius:2px; }
.studio-shell.workspace-light .node-column .column-header-copy>small { color:#f5f2ed; }
.studio-shell.workspace-light .board-node>.node-document>span { color:#76502e; }
.studio-shell .status-path { color:var(--ui-label-text); }

/* Tile appearance picker (Milanote-style icon library + image mode). */
.tile-appearance-picker { position: fixed; z-index: 120; width: 320px; max-height: 430px; display: flex; flex-direction: column; border: 1px solid var(--glass-border, #d7e4f021); border-radius: 14px; background: var(--glass-overlay-surface, #13171d); color: var(--text); box-shadow: 0 22px 68px #05070bc2; overflow: hidden; }
.tile-appearance-picker header { display: flex; align-items: center; justify-content: space-between; gap: 6px; padding: 8px 8px 0; }
.tile-appearance-tabs { display: flex; gap: 3px; }
.tile-appearance-tabs button { border: 1px solid var(--line); border-radius: 7px; background: transparent; color: var(--muted); padding: 4px 12px; font: 600 11px Inter, sans-serif; cursor: pointer; }
.tile-appearance-tabs button.active { border-color: var(--gold); color: var(--text-strong); background: color-mix(in srgb, var(--gold) 14%, transparent); }
.tile-appearance-close { width: 24px; height: 24px; border: 0; border-radius: 6px; background: transparent; color: var(--muted); cursor: pointer; font-size: 12px; }
.tile-appearance-close:hover { background: var(--surface-hover); color: var(--text-strong); }
.tile-appearance-search { display: grid; grid-template-columns: minmax(0, 1fr) 118px; gap: 5px; padding: 8px; }
.tile-appearance-search input, .tile-appearance-search select { height: 26px; min-width: 0; border: 1px solid var(--line); border-radius: 6px; background: var(--surface-input); color: var(--text); padding: 0 7px; font-size: 11px; }
.tile-appearance-recents { padding: 0 8px 4px; }
.tile-appearance-recents > span { display: block; color: var(--faint); font: 600 8px Inter, sans-serif; text-transform: uppercase; letter-spacing: .07em; margin-bottom: 3px; }
.tile-appearance-grid { flex: 1; min-height: 120px; overflow-y: auto; display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; padding: 4px 8px 8px; align-content: start; }
.tile-appearance-grid.compact { grid-template-columns: repeat(6, 1fr); min-height: 0; flex: none; overflow: visible; padding-bottom: 4px; }
.tile-appearance-grid button { display: grid; gap: 2px; justify-items: center; padding: 6px 2px 4px; border: 1px solid var(--line); border-radius: 8px; background: var(--surface-input); color: var(--text); cursor: pointer; }
.tile-appearance-grid button > span { font-size: 19px; line-height: 1; }
.tile-appearance-grid button > small { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--faint); font-size: 7.5px; }
.tile-appearance-grid button:hover { border-color: var(--gold); }
.tile-appearance-grid button.selected { border-color: var(--gold); background: color-mix(in srgb, var(--gold) 18%, transparent); box-shadow: inset 0 0 0 1px var(--gold); }
.tile-appearance-grid.compact button { padding: 4px 0; font-size: 15px; }
.tile-appearance-empty { grid-column: 1 / -1; color: var(--faint); font-size: 11px; text-align: center; padding: 18px 6px; }
.tile-appearance-picker footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 7px 8px; border-top: 1px solid var(--line); color: var(--faint); font-size: 9px; }
.tile-appearance-image { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 10px; padding: 10px; }
.tile-appearance-preview { width: 96px; height: 96px; display: grid; place-items: center; border: 1px solid var(--border-control); border-radius: 12px; background-color: var(--node-accent); color: var(--node-icon-foreground, #fff); font-size: 44px; font-weight: 600; background-size: cover; }
.tile-appearance-image strong { display: block; font-size: 12px; color: var(--text-strong); margin-bottom: 3px; }
.tile-appearance-image small { display: block; color: var(--faint); font-size: 10px; line-height: 1.45; margin-bottom: 8px; }
.tile-appearance-actions { display: flex; gap: 6px; flex-wrap: wrap; }

/* Project thumbnail menu + project cover picker anchor. */
.project-thumb-menu { z-index: 120; display: grid; min-width: 190px; border: 1px solid var(--glass-border, #d7e4f021); border-radius: 9px; background: var(--glass-overlay-surface, #13171d); box-shadow: 0 22px 68px #05070bc2; padding: 5px; }
.project-thumb-menu button { border: 0; border-radius: 5px; background: transparent; color: var(--text); text-align: left; padding: 7px 9px; font-size: 11px; cursor: pointer; }
.project-thumb-menu button:hover:not(:disabled) { background: var(--surface-hover); color: var(--text-strong); }
.project-thumb-menu button:disabled { color: var(--faint); cursor: not-allowed; }
.project-cover-picker-anchor { position: relative; z-index: 110; margin: 0 2px 8px; }
.project-cover-picker-anchor .board-cover-picker { position: relative; top: 0; right: 0; width: auto; }
.project-library-item { grid-template-columns: minmax(0, 1fr) 22px 22px 22px; }

/* Milanote-style full column body color. Inline background-color would lose
   to the column-presentation !important rules, so the dedicated class wins. */
.studio-shell .board-node.node-column.has-body-color { background-color: var(--node-body, #24303f) !important; background-image: none; }

/* A document toolbar must stay inside its pane; its body-portaled menu must
   escape pane clipping without inheriting the shell's transformed glass layer. */
.document-toolbar { min-width:0; overflow:hidden; }
.document-formatting-controls { display:flex; flex:1; min-width:0; align-items:center; gap:6px; overflow-x:auto; overflow-y:hidden; overscroll-behavior-x:contain; scrollbar-width:thin; scrollbar-color:var(--border-control) transparent; }
.document-formatting-controls::-webkit-scrollbar { height:6px; }
.document-formatting-controls::-webkit-scrollbar-thumb { background:var(--border-control); border-radius:6px; }
.document-formatting-controls :is(button,select,label) { min-width:32px; min-height:32px; }
.document-formatting-controls select { box-sizing:border-box; font-size:12px; background:var(--surface-input); color:var(--text); border-color:var(--border-control); }
.document-formatting-controls :is(button,select):focus-visible, .document-formatting-controls label:focus-within { outline:2px solid var(--focus-ring); outline-offset:-2px; }
.document-formatting-controls > * { flex:none; }
.document-toolbar > .overflow-button { flex:none; }
.document-more-menu-portaled { position:fixed; z-index:110; right:auto; color:var(--text); background:var(--surface-overlay,#1c1f25); border-color:var(--border-control,#4b505b); }
.document-more-menu-portaled button { min-height:30px; color:var(--text,#d2d3d7); }
.document-more-menu-portaled button:focus-visible { outline:2px solid var(--focus-ring,#d7ae74); outline-offset:-2px; }

/* Part II organization and read-only document repairs. */
.studio-shell .document-editor[aria-readonly="true"] { background: transparent !important; color: inherit !important; }
.sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; border:0; }
.organization-filter-help { margin:8px; color:var(--text-subtle); font-size:11px; line-height:1.4; }
.board-transfer-dialog select { width:100%; margin-top:8px; min-height:36px; background:var(--surface-input); color:var(--text-strong); border:1px solid var(--border-control); }
.board-transfer-dialog p { font-size:12px; line-height:1.5; }

.diagram-caption-svg { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; z-index:1; }
.diagram-structure-panel { position:absolute; z-index:150; top:64px; right:12px; box-sizing:border-box; width:min(360px,calc(100% - 84px)); max-height:calc(100% - 84px); overflow:auto; padding:14px; border:1px solid var(--border-control); border-radius:9px; background:var(--surface-overlay); color:var(--text-strong); box-shadow:0 16px 42px var(--shadow-overlay); font:12px/1.45 Arial,sans-serif; }
.diagram-structure-panel header,.diagram-actions { display:flex; flex-wrap:wrap; align-items:center; gap:6px; }
.diagram-structure-panel header { justify-content:space-between; }
.diagram-structure-panel header button { position:relative; z-index:151; min-width:48px; min-height:28px; cursor:pointer; }
.diagram-structure-panel h2 { margin:0; font-size:16px; }
.diagram-structure-panel h3 { margin:12px 0 8px; font-size:13px; }
.diagram-structure-panel section { padding-block:8px; border-top:1px solid var(--border-subtle); }
.diagram-structure-panel p { color:var(--text-subtle); }
.diagram-structure-panel label { display:grid; gap:5px; margin:6px 0; }
.diagram-structure-panel :is(button,input,select) { min-height:30px; border:1px solid var(--border-control); border-radius:5px; background:var(--surface-input); color:var(--text-strong); padding:5px 8px; font:inherit; box-sizing:border-box; }
.diagram-structure-panel input[type=checkbox] { min-height:20px; width:20px; }
.diagram-structure-panel :is(button,input,select):focus-visible { outline:2px solid var(--focus-ring); outline-offset:2px; }
.diagram-object-list { margin:0; padding:0; list-style:none; }
.diagram-object-list :is(li, .diagram-object-row) { display:flex; flex-wrap:wrap; gap:5px; align-items:center; margin:5px 0; }
.diagram-object-list :is(li, .diagram-object-row)>button { flex:1; min-width:100px; text-align:left; }
.diagram-object-list :is(li, .diagram-object-row)>label { display:flex; align-items:center; margin:0; }
.diagram-object-state { flex-basis:100%; color:var(--text-subtle); }
.diagram-structure-panel button:disabled { opacity:.6; }
@media(forced-colors:active) { .diagram-structure-panel { background:Canvas; color:CanvasText; border-color:CanvasText; } .diagram-structure-panel :is(button,input,select) { background:Canvas; color:CanvasText; border-color:ButtonText; } .diagram-structure-panel :is(p,.diagram-object-state) { color:CanvasText; } }

/* Leave the hidden-inspector restore tab outside document toolbar actions. */
.app-body.inspector-hidden .mode-document .document-toolbar { padding-right:32px; }

/* Existing visual export contract and actionable source warnings. */
.studio-shell .board-export-popover { max-height:calc(100% - 96px); overflow-y:auto; }
.board-export-contract { margin:0; font-size:11px; line-height:1.45; color:var(--text-subtle); }
.board-export-error { margin:0; color:var(--error); font-size:11px; }
.board-export-warnings { padding:7px; border:1px solid var(--border-control); border-radius:5px; font-size:11px; color:var(--text-subtle); }
.board-export-warnings ul { margin:6px 0 0; padding-left:16px; max-height:140px; overflow-y:auto; }
.board-export-warnings li + li { margin-top:5px; }

.studio-shell .project-library-copy small { color: var(--ui-label-text); }
.studio-shell.workspace-light .project-library-cover { color: var(--ui-accent-text); }
.studio-shell .document-theme-paper .paper-header { color: #655f58; }
.studio-shell .document-focus-mode .paper-header { opacity: 1; }
.studio-shell .document-stats span,
.studio-shell .document-layout-inspector > p { color: var(--ui-label-text); }
.studio-shell .document-layout-inspector > header > span { color: var(--ui-accent-text); }
.studio-shell .document-layout-inspector .layout-checkbox { color: var(--ui-label-text) !important; }

/* Approved whole-workspace layout, using the real production commands. */
.studio-shell.approved-layout-port {
  --surface-nav: #1d242e;
  --surface-overlay: #1d242e;
  --surface-toolbar: #1d242e;
  --surface-input: #11161d;
  --surface-control: #252e3a;
  --surface-hover: #2b3848;
  --surface-active: #273c59;
  --text: #e7edf5;
  --text-strong: #f3f5f9;
  --text-subtle: #aab7c7;
  --border-control: #3a4656;
  --border-subtle: #2e3844;
  --gold: #cba36b;
  --gold-hover: #dbb47e;
  --muted: #aab7c7;
  --dim: #768398;
  --blue: #628bd9;
  --blue-fill: #273c59;
  --water: #087cd9;
  --line: #3a4656;
  --line-strong: #4a586d;
  --ui-label-text: #aab7c7;
  --ui-accent-text: #f3d4a0;
  --shell-header-h: 120px;
  --canvas-surface: #13171c;
  --canvas-grid: #242c36;
  grid-template-rows: auto minmax(0, 1fr) 30px;
  background: #12171e;
  font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Arial, sans-serif;
}
.studio-shell.approved-layout-port.workspace-light {
  --surface-nav: #f0f4f8;
  --surface-overlay: #ffffff;
  --surface-toolbar: #eef3f8;
  --surface-input: #ffffff;
  --surface-control: #e2eaf2;
  --surface-hover: #d5e2ef;
  --surface-active: #c5d7ea;
  --text: #1d2734;
  --text-strong: #0d1520;
  --text-subtle: #506173;
  --border-control: #b8c7d6;
  --border-subtle: #d0dbe6;
  --gold: #96672c;
  --gold-hover: #ad7835;
  --muted: #506173;
  --dim: #77899c;
  --blue: #236fbb;
  --blue-fill: #dbe8f5;
  --water: #087cd9;
  --line: #d0dbe6;
  --line-strong: #b8c7d6;
  --ui-label-text: #506173;
  --ui-accent-text: #664112;
  --canvas-surface: #e9eff5;
  --canvas-grid: #c7d4e2;
  background: #e9eff5;
}

/* App Bar & Continuous Aquarium Header Composition */
.studio-shell.approved-layout-port .app-bar.aquarium-app-bar {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) auto;
  align-items: center;
  min-height: 120px;
  height: auto;
  gap: 12px;
  padding: 16px 24px 40px calc(var(--aquarium-window) + 20px);
  border: 0;
  background: linear-gradient(90deg, #063866, #0c1621 28%, #0a131d);
  color: #edf2f9;
  box-shadow: none;
  overflow: visible;
}
.approved-layout-port .app-bar.aquarium-app-bar::after { display: none; }
.approved-layout-port .app-bar .project-heading {
  display: block; min-width: 0; max-width: none; padding: 0; background: transparent; border: 0;
}
.approved-layout-port .app-bar .project-heading strong {
  font: 600 22px/1.25 Georgia, serif; color: #edf2f9; letter-spacing: 0.2px;
}
.approved-layout-port .app-bar .project-heading .eyebrow {
  color: var(--gold, #cba36b); font-size: 11px; font-weight: 600; letter-spacing: 1.6px; margin-bottom: 4px; text-transform: uppercase;
}

/* Header Actions Cluster */
.approved-layout-port .app-header-actions {
  min-width: 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 8px; max-width: 1160px;
}
.approved-layout-port .app-header-actions :is(.quiet-button, .primary-button, .project-tools-toggle) {
  display: inline-flex; align-items: center; justify-content: center;
  height: 38px; min-height: 38px; width: auto; font-size: 13px; font-weight: 500;
  padding: 0 14px; border: 1px solid var(--border-control, #344452); color: #e3eaf4; background: #101b27;
  border-radius: 6px; transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}
.approved-layout-port .app-header-actions :is(.quiet-button, .primary-button, .project-tools-toggle):hover {
  background: #1d2735; border-color: #5982ae; color: #ffffff;
}
.approved-layout-port .app-header-actions .primary-button {
  background: #caa36d; color: #17120b; border-color: #d9b983; font-weight: 600; font-size: 13px;
}
.approved-layout-port .app-header-actions .primary-button:hover {
  background: #dbb47e; border-color: #e4c795; color: #120e08;
}
.approved-layout-port .app-header-actions .quiet-button:disabled {
  color: #8c97a5; background: #181d24; opacity: 0.65; cursor: default;
}
.approved-layout-port .app-header-actions .mode-switch {
  padding: 0; border: 1px solid var(--border-control, #344452); background: #101b27; flex: none; border-radius: 6px; overflow: hidden; display: inline-flex;
}
.approved-layout-port .app-header-actions .mode-switch button {
  min-height: 38px; height: 38px; padding: 0 14px; color: #e3eaf4; font-size: 13px; font-weight: 500; border: 0; border-radius: 0; background: transparent; transition: all 0.15s ease;
}
.approved-layout-port .app-header-actions .mode-switch button:hover {
  background: #1d2735; color: #ffffff;
}
.approved-layout-port .app-header-actions .mode-switch button.active {
  background: #273c59; color: #ffffff; font-weight: 600; box-shadow: inset 0 0 0 1px #5982ae;
}
.approved-layout-port .app-header-actions .project-search {
  display: flex; width: 240px; min-width: 140px; max-width: 260px; flex: none; position: relative;
}
.approved-layout-port .app-header-actions .project-search input {
  min-height: 38px; height: 38px; width: 100%; color: #e3eaf4; background: #101b27; border: 1px solid var(--border-control, #344452); font-size: 13px; border-radius: 6px; padding: 0 34px 0 12px;
}
.approved-layout-port .app-header-actions .project-search input:focus {
  border-color: #5982ae; outline: none; box-shadow: 0 0 0 2px #5982ae44;
}
.approved-layout-port .app-header-actions .project-search-scope { color: #becbd7; }
.approved-layout-port .app-header-actions .theme-toggle { width: 38px; padding: 0; font-size: 15px; }
.approved-layout-port .app-header-actions .inspector-toggle::before { display: none; }
.approved-layout-port .app-header-actions .project-tools-toggle { color: #e3eaf4; overflow: visible; }
.approved-layout-port .app-header-actions .project-tools-toggle span { position: static; color: #becbd7; }

/* Navigator & Workspace Hierarchy */
.approved-layout-port .navigator { padding: 14px 12px; background: var(--surface-nav); }
.approved-layout-port .project-library-row {
  min-height: 72px; border: 1px solid var(--border-control); border-radius: 8px; padding: 10px; background: var(--surface-control);
}
.approved-layout-port .project-library-copy strong {
  display: block; white-space: normal; overflow-wrap: anywhere; font-size: 13px; font-weight: 600; line-height: 1.35; color: var(--text-strong);
}
.approved-layout-port .project-library-copy :is(small, em) { font-size: 11px; color: var(--text-subtle); }
.approved-layout-port .project-row-action { width: 100%; height: 26px; justify-self: center; font-size: 12px; }
.approved-layout-port .tree-row { min-height: 34px; font-size: 13px; padding-block: 7px; border-radius: 5px; }
.approved-layout-port .tree-row:hover { background: var(--surface-hover); }
.approved-layout-port .tree-row.active { background: var(--surface-active); color: var(--text-strong); font-weight: 500; }
.approved-layout-port .tree-section-label {
  font-size: 11px; font-weight: 600; letter-spacing: 1.2px; color: var(--gold); text-transform: uppercase;
}

/* Canvas Toolbar, Rail & Breadcrumbs */
.approved-layout-port .board-navigation {
  min-height: 38px; padding-inline: 14px; background: var(--surface-input); border-bottom: 1px solid var(--border-subtle);
}
.approved-layout-port .project-center.has-board-navigation { grid-template-rows: 38px minmax(0, 1fr) 100px; }
.approved-layout-port .project-center.has-board-navigation.board-strip-hidden { grid-template-rows: 38px minmax(0, 1fr); }
.approved-layout-port .canvas-toolbar { min-height: 46px; background: var(--surface-toolbar); border-bottom: 1px solid var(--border-subtle); }
.approved-layout-port .canvas-board-title {
  max-width: 280px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; font-weight: 600; color: var(--text-strong);
}
.approved-layout-port .canvas-primary-actions {
  position: sticky; right: 0; display: flex; align-items: center; gap: 8px; flex: none; margin-left: auto; padding: 4px 12px; z-index: 3; background: var(--surface-toolbar);
}
