/* SVG artwork owns its fill and stroke in both themes. The general light
   card skin must not add a second body behind paths, lines or arrows. */
.studio-shell .board-node.node-shape:has(> :is(.node-vector-shape, .node-shape-ellipse)) {
  border: 0;
  background: transparent;
}
.studio-shell .board-node.node-shape:has(> :is(.node-vector-shape, .node-shape-ellipse)):not(.selected):not(.marquee-preview):not(.connector-source) {
  box-shadow: none;
}
.studio-shell .board-node.node-shape.connector-source:has(> :is(.node-vector-shape, .node-shape-ellipse)) {
  box-shadow: 0 0 0 3px #58c8c199, 0 12px 32px #0008;
}

/* Node Columns share ordinary column layout, but expose explicit typed graph
   sockets. The interaction proxies stay inside each clipped card frame. */
.board-node.node-graph-column { outline: 2px solid #67cdc3; outline-offset: -2px; }
/* Transparent artwork text preserves its authored frame and typography.
   Compact title chrome reserves the same 14 px used by the imported model. */
.studio-shell .board-node.node-artwork-text > .node-drag-handle { height: 14px; border-bottom: 0; }
.studio-shell .board-node.node-artwork-text > .board-rich-text { height: calc(100% - 14px); border-top: 0; grid-template-rows: minmax(0, 1fr); }
.studio-shell .board-node.node-artwork-text .board-text-editor { min-height: 100%; padding: 0 11px; font-family: var(--artwork-font-family, Inter, sans-serif); font-size: var(--artwork-font-size, 11px); line-height: var(--artwork-line-height, 1.58); font-weight: var(--artwork-font-weight, 400); }
.studio-shell .board-node.node-artwork-text .board-text-editor p { margin: 0; }
/* Tiptap also parses authored bold weights as a strong mark. Preserve the
   explicit weight rather than synthesizing an extra bolder step. */
.studio-shell .board-node.node-artwork-text .board-text-editor span:is([style*="font-weight: 500"], [style*="font-weight: 600"], [style*="font-weight: 700"], [style*="font-weight: 800"], [style*="font-weight: 900"]) > strong { font-weight: inherit; }
.canvas-stage > .board-artwork-text-toolbar { position: absolute; z-index: 92; box-sizing: border-box; min-height: 32px; max-height: 128px; flex-wrap: wrap; overflow: auto; border: 1px solid var(--border-control); border-radius: 5px; background: var(--surface-overlay); color: var(--text); box-shadow: 0 6px 18px var(--shadow-overlay); }
.canvas-stage > .board-artwork-text-toolbar :is(select, button, label) { background: var(--surface-input); color: var(--text); border-color: var(--border-control); }
.board-node.node-graph-column .column-header small { color: #a2e4dc; }
/* The selected container's full-size transform proxy must not swallow its
   sockets. Corner resize handles remain available. */
.canvas-stage:has(.board-node.node-graph-column.selected) .canvas-interaction-overlay .node-transform-box { pointer-events: none !important; }
.canvas-stage:has(.board-node.node-graph-column.selected) .node-transform-box :is(.handle-n, .handle-e, .handle-s, .handle-w) { display: none; }
.node-graph-sockets { position: absolute; inset: 0; z-index: 25; pointer-events: none; }
.node-graph-socket {
  position: absolute; z-index: 2; box-sizing: border-box; width: 18px; height: 18px;
  border: 2px solid #132128; border-radius: 50%; padding: 0; cursor: crosshair;
  pointer-events: auto; background: var(--socket-color, #68b7c9);
  box-shadow: 0 0 0 1px #e7fff3b8, 0 2px 7px #000b;
  touch-action: none;
}
.node-graph-socket:hover, .node-graph-socket.active, .node-graph-socket:focus-visible {
  outline: 3px solid #fff8d9; outline-offset: 1px; filter: brightness(1.2);
}
.node-graph-socket:disabled { cursor: default; opacity: .5; }
.node-graph-draft-layer { position: absolute; z-index: 6; left: 0; top: 0; width: 1px; height: 1px; pointer-events: none; }
.node-graph-role-control { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; color: var(--muted); font-size: 10px; }
.node-graph-role-control select { min-width: 106px; }

.node-drawing-layer{background:transparent!important;border:0!important;box-shadow:none!important;pointer-events:none}.node-drawing-layer>.node-drag-handle{display:none}.node-drawing-layer.selected>.node-transform-box,.node-drawing-layer.selected>.node-resize-handle,.node-drawing-layer.selected>.node-rotate-handle{pointer-events:auto}

/* Paint handles own pointer input while the gradient editor is active. */
.canvas-stage:has([data-gradient-handles]) .canvas-interaction-overlay .node-transform-box { pointer-events:none !important; }

/* Column sizing is an explicit content command in the contextual inspector. */
.inspector-column-layout { display:grid; gap:8px; padding:10px; border:1px solid var(--border-control); border-radius:6px; background:var(--surface-control); }
.inspector-column-layout label { display:grid; gap:8px; font-size:12px; color:var(--text); }
.inspector-column-layout select { width:100%; min-width:0; min-height:32px; padding:0 8px; border:1px solid var(--border-control); border-radius:5px; background:var(--surface-input); color:var(--text-strong); font:inherit; }
.inspector-column-layout select:focus-visible { outline:2px solid var(--focus-ring); outline-offset:2px; }
