.studio-shell .canvas-context-menu [role="menuitemradio"] { display:flex; align-items:center; gap:8px; min-height:32px; }
.studio-shell .canvas-context-menu [role="menuitemradio"][aria-checked="true"] { color:var(--text-strong); background:var(--surface-active); }
.studio-shell .canvas-context-menu [role="menuitemradio"][aria-checked="true"]::after { content:"✓"; margin-left:auto; color:var(--focus-ring); }

.studio-shell .canvas-stage .board-node.node-child-board .child-board-card > strong { color:var(--subboard-label-color,var(--text-strong)) !important; }
.studio-shell .canvas-stage .board-node.node-child-board .child-board-card > small { color:color-mix(in srgb,var(--subboard-label-color,var(--text-strong)) 68%,transparent) !important; }

.studio-shell .board-node.node-child-board .child-board-card { box-shadow:none; }

/* Advance Document Expansion: Authored Breaks, Multimodal Blocks & Derived Page Navigator */
.document-editor [data-blank-page] {
  position: relative;
  height: 54px;
  margin: 38px -68px;
  border-top: 1px dashed #a79f94;
  border-bottom: 1px dashed #a79f94;
  background: repeating-linear-gradient(-45deg, #e8e3da, #e8e3da 8px, #dfd9ce 8px, #dfd9ce 16px);
}
.document-editor [data-blank-page]::after {
  content: "AUTHORED BLANK PAGE";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #6e665e;
  font: 700 7px/1 Inter, sans-serif;
  letter-spacing: 0.15em;
}
.document-editor [data-section-break] {
  position: relative;
  height: 34px;
  margin: 32px -68px;
  border-top: 2px double #9e7448;
  border-bottom: 1px solid #c8c0b4;
  background: #ebe4d8;
}
.document-editor [data-section-break="continuous"]::after {
  content: "SECTION BREAK (CONTINUOUS)";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #84623d;
  font: 700 7px/1 Inter, sans-serif;
  letter-spacing: 0.14em;
}
.document-editor [data-section-break="next-page"]::after {
  content: "SECTION BREAK (NEXT PAGE)";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #84623d;
  font: 700 7px/1 Inter, sans-serif;
  letter-spacing: 0.14em;
}
.document-editor figure.layout-image[data-placement="inline"] {
  display: inline-block;
  vertical-align: middle;
  width: min(180px, 45%);
  margin: 4px 10px;
}
.document-editor figure.layout-image[data-placement="anchored"] {
  border-left: 3px solid #9e7448;
  padding-left: 12px;
  margin: 18px 0;
}
.document-editor figure[data-video-block],
.document-editor figure[data-model3d-block],
.document-editor figure[data-pdf-embed] {
  margin: 22px 0;
  padding: 12px;
  border: 1px solid #c8c0b4;
  border-radius: 6px;
  background: #efeae0;
