}
.document-editor .document-model3d-poster,
.document-editor .document-pdf-embed-card {
  display: grid;
  place-items: center;
  min-height: 160px;
  border: 1px dashed #9e7448;
  border-radius: 4px;
  background: #181c24;
  color: #d8e6f2;
  font: 600 11px/1.4 Inter, sans-serif;
  padding: 18px;
  text-align: center;
}
.document-derived-pages-list {
