/* Always-Visible Document Page & Section Bar in Pages Mode */
.document-page-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  max-width: var(--document-page-width, 816px);
  margin: 0 auto 16px auto;
  padding: 7px 12px;
  border: 1px solid #353944;
  border-radius: 7px;
  background: #14171df2;
  color: #d8dde6;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}
.layout-inspector-open .document-page-bar {
  grid-column: 1;
  width: 100%;
  box-sizing: border-box;
}
.document-page-bar-summary {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 11px;
}
.document-page-bar-summary strong {
  color: #f8fafc;
  font-size: 11.5px;
}
.document-page-bar-summary span {
  color: #cbd5e1;
  font-size: 9.5px;
  letter-spacing: 0.05em;
