.document-page-pills {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
}
.document-page-pills button,
.document-page-bar-actions button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 26px;
  padding: 2px 8px;
  border: 1px solid #383e4c;
  border-radius: 4px;
  background: #1d212a;
  color: #cbd5e1;
  font-size: 10px;
  cursor: pointer;
}
.document-page-pills button:hover:not(:disabled),
.document-page-bar-actions button:hover:not(:disabled) {
  background: #2b313e;
  color: #ffffff;
}
.document-page-pills button:disabled,
.document-page-bar-actions button:disabled {
  opacity: 0.45;
  cursor: default;
}
