import type { BoardNode } from '../model/project'
import { vectorNodeBounds } from '../model/vector'

export type ArrangementAxis = 'horizontal' | 'vertical'
export type Alignment = 'left' | 'right' | 'center' | 'top' | 'middle' | 'bottom'
export type ArrangementBounds = { left: number; top: number; right: number; bottom: number }

/** Arrange free objects only. Moving a container without its members or a
 * member independently would break the existing ownership contract. */
export function eligibleArrangementNodes(nodes: BoardNode[], selectedIds: readonly string[]): BoardNode[] {
  const selected = new Set(selectedIds)
  return nodes.filter((node) => selected.has(node.id) && !node.locked && !node.parentColumnId && !node.groupId && node.kind !== 'column' && node.kind !== 'group')
}

export function boardNodeVisualBounds(node: BoardNode): ArrangementBounds {
  if (node.shapeType === 'path' && node.vectorPath) return vectorNodeBounds(node)
  const angle = (node.rotation || 0) * Math.PI / 180
  const width = Math.abs(node.width * Math.cos(angle)) + Math.abs(node.height * Math.sin(angle))
  const height = Math.abs(node.width * Math.sin(angle)) + Math.abs(node.height * Math.cos(angle))
  const left = node.x + (node.width - width) / 2, top = node.y + (node.height - height) / 2
  return { left, top, right: left + width, bottom: top + height }
}

function translate(nodes: BoardNode[], offsets: Map<string, { x: number; y: number }>): BoardNode[] {
  return nodes.map((node) => {
    const offset = offsets.get(node.id)
    return offset && (offset.x || offset.y) ? { ...node, x: node.x + offset.x, y: node.y + offset.y } : node
  })
}

export function alignBoardNodes(nodes: BoardNode[], selectedIds: readonly string[], alignment: Alignment): BoardNode[] {
  const selected = eligibleArrangementNodes(nodes, selectedIds)
  if (selected.length < 2) return nodes
  const boxes = selected.map(boardNodeVisualBounds)
  const left = Math.min(...boxes.map((box) => box.left)), right = Math.max(...boxes.map((box) => box.right))
  const top = Math.min(...boxes.map((box) => box.top)), bottom = Math.max(...boxes.map((box) => box.bottom))
  return translate(nodes, new Map(selected.map((node, index) => {
    const box = boxes[index]
    const x = alignment === 'left' ? left - box.left : alignment === 'right' ? right - box.right : alignment === 'center' ? (left + right - box.left - box.right) / 2 : 0
    const y = alignment === 'top' ? top - box.top : alignment === 'bottom' ? bottom - box.bottom : alignment === 'middle' ? (top + bottom - box.top - box.bottom) / 2 : 0
    return [node.id, { x, y }]
  })))
}

/** Equal centers remains distinct from equal clear gaps. If the existing span
 * cannot contain the items, gap distribution expands it instead of overlapping. */
export function distributeBoardNodes(nodes: BoardNode[], selectedIds: readonly string[], axis: ArrangementAxis, mode: 'centers' | 'gaps' = 'centers', explicitGap?: number): BoardNode[] {
  const selected = eligibleArrangementNodes(nodes, selectedIds)
  if (selected.length < 3) return nodes
  const low = axis === 'horizontal' ? 'left' : 'top', high = axis === 'horizontal' ? 'right' : 'bottom'
  const ordered = selected.map((node) => ({ node, bounds: boardNodeVisualBounds(node) })).sort((a, b) => a.bounds[low] - b.bounds[low])
  const start = ordered[0].bounds[low], end = Math.max(...ordered.map((entry) => entry.bounds[high]))
  const sizes = ordered.map((entry) => entry.bounds[high] - entry.bounds[low])
  const gap = Number.isFinite(explicitGap) ? Math.max(0, explicitGap!) : Math.max(0, (end - start - sizes.reduce((sum, size) => sum + size, 0)) / (ordered.length - 1))
  const firstCenter = (ordered[0].bounds[low] + ordered[0].bounds[high]) / 2
  const last = ordered.at(-1)!.bounds, lastCenter = (last[low] + last[high]) / 2
  let position = start
  return translate(nodes, new Map(ordered.map(({ node, bounds }, index) => {
    const delta = mode === 'gaps' ? position - bounds[low] : firstCenter + index * (lastCenter - firstCenter) / (ordered.length - 1) - (bounds[low] + bounds[high]) / 2
    position += sizes[index] + gap
    return [node.id, axis === 'horizontal' ? { x: delta, y: 0 } : { x: 0, y: delta }]
  })))
}

/** Shelf packing preserves every source, crop and object size. Variable widths
 * create tight rows; row height is the tallest visual object in that row. */
export function packBoardNodes(nodes: BoardNode[], selectedIds: readonly string[], options: { gap?: number; rows?: number; columns?: number } = {}): BoardNode[] {
  const selected = eligibleArrangementNodes(nodes, selectedIds)
  if (selected.length < 2) return nodes
  const gap = Number.isFinite(options.gap) ? Math.max(0, options.gap!) : 24
  const count = options.rows ? Math.ceil(selected.length / Math.max(1, Math.floor(options.rows))) : options.columns || Math.ceil(Math.sqrt(selected.length))
  const columns = Math.max(1, Math.min(selected.length, Math.floor(count)))
  const boxes = selected.map(boardNodeVisualBounds)
  const left = Math.min(...boxes.map((box) => box.left)), top = Math.min(...boxes.map((box) => box.top))
  const offsets = new Map<string, { x: number; y: number }>()
  let y = top
  for (let start = 0; start < selected.length; start += columns) {
    let x = left, rowHeight = 0
    for (let index = start; index < Math.min(selected.length, start + columns); index++) {
      const box = boxes[index]
      offsets.set(selected[index].id, { x: x - box.left, y: y - box.top })
      x += box.right - box.left + gap
      rowHeight = Math.max(rowHeight, box.bottom - box.top)
    }
    y += rowHeight + gap
  }
  return translate(nodes, offsets)
}

import {nodeGraphPorts} from './nodeColumnCommands'
import {computePortPosition,PORT_SEMANTIC_COLORS} from './cardPorts'
import type { BoardConnector, BoardModel, BoardNode, ProjectAsset } from '../model/project'
import type { CanvasAssetHandle, CanvasObjectKind, CanvasSceneConnection, CanvasSceneObject, CanvasSceneSnapshot } from '../canvas-engine/contracts'
import { DEFAULT_CANVAS_GRID_OPACITY } from '../canvasTheme'
import { prepareVelloVectorGeometry } from './velloVectorGeometry'
import { containerPaintOrder, diagramProjectionStates, type DiagramProjectionState } from './diagramStructureCore'
import { projectGraphColumns, GraphColumnRuntime, graphColumnRows } from './graphColumnV2'
import { connectorGeometry } from './connectors'
import { projectModelArtwork } from './modelArtwork'

const objectCache = new WeakMap<readonly BoardNode[], WeakMap<readonly ProjectAsset[], {sources: ReadonlyMap<string,string>; objects: readonly CanvasSceneObject[]}>>()
const noSources = new Map<string,string>()
const artworkProjections = new WeakMap<BoardNode, {asset?: ProjectAsset; source?: string; value: CanvasSceneObject['modelArtwork']}>()
// Immutable drag replacements must not reparse unchanged saved prose or give
// an unchanged embedded image a fresh upload revision. Weak references retain
// no historical board/media payloads; this index stores bounded identities only.
const latestArtworkNodes = new Map<string, WeakRef<BoardNode>>()
function artworkInputs(node:BoardNode) {
  return JSON.stringify([node.kind,node.textMode,node.title,node.color,node.textColor,node.imagePresentation,node.imageTransform,node.columnPresentation,node.columnBodyColor,Boolean(node.graphColumn),node.coverAssetId,node.containerRole,node.assetId])
}
const assetPaintSources = new WeakMap<ProjectAsset, {source: string; revision: number}>()
const connectionCache = new WeakMap<readonly BoardNode[], WeakMap<readonly BoardConnector[], readonly CanvasSceneConnection[]>>()
const objectRevisions = new WeakMap<BoardNode, Map<string, number>>()
// Immutable node identity plus derived state defines paint identity. Keep only
// the latest projection per node so moving a peer cannot invalidate its paint.
const nodeProjections = new WeakMap<BoardNode, { key: string; object: CanvasSceneObject }>()
const connectorProjections = new WeakMap<BoardConnector, CanvasSceneConnection>()
let lastEnvironment: CanvasSceneSnapshot['environment'] | undefined
const graphRuntimes = new Map<string, GraphColumnRuntime>()

const revisions = new WeakMap<object, number>()
let nextRevision = 1

function revisionFor(value: object) {
  const existing = revisions.get(value)
  if (existing) return existing
  const revision = nextRevision++
  revisions.set(value, revision)
  return revision
}

function objectKind(node: BoardNode): CanvasObjectKind {
  if (node.kind === 'column' || node.kind === 'group') return 'container'
  if (node.kind === 'image') return 'raster'
  if (node.kind === 'shape') return 'vector'
  if (node.kind === 'note' || node.kind === 'text') return 'text'
  if (node.kind === 'clip') return 'capture'
  if (node.kind === 'board-link') return 'link'
  return node.kind
}

function assetHandle(node: BoardNode, assets: ReadonlyMap<string, ProjectAsset>): CanvasAssetHandle | undefined {
  if (!node.assetId) return undefined
  const asset = assets.get(node.assetId)
  if (!asset) return undefined
  const kind = asset.kind === 'image' || asset.kind === 'video' || asset.kind === 'model' || asset.kind === 'document' ? asset.kind : 'other'
  return { id: asset.id, kind, revision: revisionFor(asset) }
}

function rotatedBounds(node: BoardNode) {
  const angle = Math.abs((node.rotation || 0) % 180) * Math.PI / 180
  if (angle === 0) return { x: node.x, y: node.y, width: node.width, height: node.height }
  const width = Math.abs(node.width * Math.cos(angle)) + Math.abs(node.height * Math.sin(angle))
  const height = Math.abs(node.width * Math.sin(angle)) + Math.abs(node.height * Math.cos(angle))
  return { x: node.x + (node.width - width) / 2, y: node.y + (node.height - height) / 2, width, height }
}

function unionBounds(a: CanvasSceneObject['bounds'], b: CanvasSceneObject['bounds'] | null) {
  if (!b) return a
  const x = Math.min(a.x, b.x), y = Math.min(a.y, b.y)
  return Object.freeze({ x, y, width: Math.max(a.x + a.width, b.x + b.width) - x,
    height: Math.max(a.y + a.height, b.y + b.height) - y })
}

function sceneObject(node: BoardNode, order: number, assets: ReadonlyMap<string, ProjectAsset>, state: DiagramProjectionState, structuredCard?: CanvasSceneObject['structuredCard']): CanvasSceneObject {
  const asset = assetHandle(node, assets)
  const key = `${order}:${state.locked}:${state.hidden}:${asset?.revision ?? ''}:${structuredCard ? JSON.stringify(structuredCard) : ''}`
  const cached = nodeProjections.get(node)
  if (cached?.key === key) return cached.object
  const hasDiagramCaption = Boolean(node.diagramShape)
  const hasShapeCaption = node.kind === 'shape' && node.shapeType === 'ellipse' && Boolean(node.body)
  // Prepare the authored path independently of its DOM caption. This derivative
  // serves canonical picking/indexing; hasDiagramCaption still excludes the
  // complete object from Vello paint ownership until text layout is supported.
  const preparedVectorGeometry = node.kind === 'shape'
    ? prepareVelloVectorGeometry(hasDiagramCaption ? { ...node, diagramShape: undefined } : node)
    : undefined
  // Broad-phase visibility follows authored world geometry, independently of
  // the saved editing frame. The current .diagram-caption-svg is clipped to its
  // own saved-frame SVG viewport (SVG UA overflow:hidden), then node-rotated;
  // its inner affine can move glyphs but cannot expand that viewport. Include
  // this frame even for empty Boolean paths without resurrecting path geometry.
  // Ellipse captions have overflow:visible, so this union is only an editing
  // frame/index bound; eligibility refuses their unmeasured mixed paint batch.
  const bounds = preparedVectorGeometry?.status === 'ready'
    ? hasDiagramCaption || hasShapeCaption ? unionBounds(rotatedBounds(node), preparedVectorGeometry.bounds)
      : preparedVectorGeometry.bounds ?? { x: node.x, y: node.y, width: 0, height: 0 }
    : rotatedBounds(node)
  // A parent may change while the child's saved record retains its identity.
  // Scene deltas compare revisions, so derived state and paint order need one too.
  let versions = objectRevisions.get(node)
  if (!versions) { versions = new Map(); objectRevisions.set(node, versions) }
  let revision = versions.get(key)
  if (!revision) { revision = nextRevision++; versions.set(key, revision) }
  const object: CanvasSceneObject = {
    id: node.id,
    revision,
    order,
    kind: objectKind(node),
    ...(node.kind === 'column' ? { role: 'column' as const } : node.kind === 'group' ? { role: node.containerRole === 'frame' || /\bframe\b/i.test(node.title) ? 'frame' as const : 'group' as const } : {}),
    bounds,
    localBounds: { x: node.x, y: node.y, width: node.width, height: node.height },
    zIndex: order,
    ...(node.parentColumnId ? { parentId: node.parentColumnId } : node.groupId ? { parentId: node.groupId } : {}),
    locked: state.locked,
    hidden: state.hidden,
    ...(structuredCard ? { structuredCard } : {}),
    appearance: {
      fill: node.color,
      stroke: node.strokeColor,
      text: node.textColor,
      opacity: node.opacity ?? 1,
      strokeWidth: node.strokeWidth,
      vectorFillRule: node.vectorFillRule,
      vectorStrokeJoin: node.vectorStrokeJoin,
      vectorStrokeCap: node.vectorStrokeCap,
      cornerRadius: node.cornerRadius,
      rotation: node.rotation || 0,
      ...(preparedVectorGeometry?.status === 'ready' ? preparedVectorGeometry.effectivePaint : {}),
    },
    ...(node.vectorPath ? { vectorPath: node.vectorPath } : {}),
    ...(node.kind === 'shape' ? {
      ...(node.shapeType ? { shapeType: node.shapeType } : {}),
      hasDiagramCaption,
      hasShapeCaption,
      preparedVectorGeometry,
    } : {}),
    ...(node.vectorBoolean ? { vectorBoolean: node.vectorBoolean } : {}),
    ...(node.vectorTransform ? { vectorTransform: node.vectorTransform } : {}),
    ...(asset ? { asset } : {}),
  }
  nodeProjections.set(node, { key, object })
  return object
}

function sceneConnection(connection: BoardConnector): CanvasSceneConnection {
  const cached = connectorProjections.get(connection)
  if (cached) return cached
  const object: CanvasSceneConnection = {
    id: connection.id,
    revision: revisionFor(connection),
    sourceId: connection.sourceId,
    targetId: connection.targetId,
    sourcePoint: connection.sourcePoint,
    targetPoint: connection.targetPoint,
    sourcePort: connection.sourcePort,
    targetPort: connection.targetPort,
    sourcePortMode: connection.sourcePortMode,
    targetPortMode: connection.targetPortMode,
    style: connection.style,
    color: connection.color,
    width: connection.width,
    dashed: connection.dashed,
    startArrow: connection.startArrow,
    endArrow: connection.endArrow,
    animated: connection.animated,
    label: connection.label,
    bendPoints: connection.bendPoints,
    labelPosition: connection.labelPosition,
    relationshipStyle: connection.relationshipStyle,
    linePattern: connection.linePattern,
  }
  connectorProjections.set(connection, object)
  return object
}

export function createArtEquationCanvasScene(
  board: Pick<BoardModel, 'id' | 'nodes' | 'connectors' | 'gridVisible' | 'gridOpacity' | 'gridSpacing'>,
  assets: readonly ProjectAsset[],
  colors: { background: string; grid: string },
  sources: ReadonlyMap<string,string> = noSources,
): CanvasSceneSnapshot {
  let byAssets = objectCache.get(board.nodes)
  if (!byAssets) { byAssets = new WeakMap(); objectCache.set(board.nodes, byAssets) }
  const entry = byAssets.get(assets)
  let objects = entry?.sources === sources ? entry.objects : undefined
  if (!objects) {
    const assetsById = new Map(assets.map((asset) => [asset.id, asset]))
    const states = diagramProjectionStates(board.nodes)
    const paint = containerPaintOrder(board.nodes)
    const nodesById = new Map(board.nodes.map((node) => [node.id, node]))
    const ordered = paint.ok ? paint.value.orderedIds.map((id) => nodesById.get(id)!) : board.nodes
    let runtime = graphRuntimes.get(board.id)
    if (!runtime) { if(graphRuntimes.size>=32)graphRuntimes.delete(graphRuntimes.keys().next().value!);runtime=new GraphColumnRuntime();graphRuntimes.set(board.id,runtime) }
    objects = ordered.map((node, index) => {
      let structuredCard: CanvasSceneObject['structuredCard']
      if (node.graphColumn) {
        let result: string
        try { const value = runtime.evaluate(board, node.id, assets); result = value.type === 'records' ? `${value.value.length} records` : value.type === 'number' ? `${value.value} records` : value.value.slice(0, 200) } catch (e) { result = 'Input error: ' + String(e) }
        structuredCard = { title: node.title, rows: graphColumnRows(node, board.nodes), result, fill: node.columnBodyColor || node.color || '#34546c', headerFill: node.color || '#34546c', text: node.textColor || '#ffffff', ports: [{x:node.width,y:node.height/2}, ...node.graphColumn.inputs.map((_,i)=>({x:0,y:node.height*(i+1)/(node.graphColumn!.inputs.length+1)}))] }
      }
      const object = sceneObject(node, index, assetsById, states.ok && paint.ok ? states.value.get(node.id)! : { locked: true, hidden: true }, structuredCard)
      const asset = node.assetId ? assetsById.get(node.assetId) : undefined
      const source = node.assetId ? sources.get(node.assetId) : node.body?.startsWith('data:image/') ? node.body : undefined
      let artwork = artworkProjections.get(node)
      const artworkSlot=JSON.stringify([board.id,node.id]),previousNode=latestArtworkNodes.get(artworkSlot)?.deref(),previousArtwork=previousNode&&artworkProjections.get(previousNode)
      if(!artwork && previousNode && previousArtwork && previousArtwork.asset===asset && previousArtwork.source===source && (previousArtwork.value?.kind!=='image'||previousArtwork.value.tilesSource===(node.assetId?sources.get(node.assetId+':tiles'):undefined)) && previousNode.body===node.body && previousNode.captured?.articleHtml===node.captured?.articleHtml && previousNode.captured?.transcriptHtml===node.captured?.transcriptHtml && artworkInputs(previousNode)===artworkInputs(node)) {
        artwork=previousArtwork;artworkProjections.set(node,artwork)
      }
      if (!artwork || artwork.asset !== asset || artwork.source !== source || (artwork.value?.kind==='image' && artwork.value.tilesSource!==(node.assetId?sources.get(node.assetId+':tiles'):undefined))) {
        let value = projectModelArtwork(node, asset, source, node.assetId?sources.get(node.assetId+":tiles"):undefined)
        if (value?.kind === 'image') {
          let sourceRevision = revisionFor(node)
          if(asset) {
            let accepted=assetPaintSources.get(asset)
            if(!accepted||accepted.source!==value.source){
              // A host may change its resolved URL without replacing metadata.
              // Give that source a fresh immutable resource revision as well.
              accepted={source:value.source,revision:accepted?nextRevision++:revisionFor(asset)}
              assetPaintSources.set(asset,accepted)
            }
            sourceRevision=accepted.revision
          }
          value = {...value, sourceRevision}
        }
        artwork = {asset,source,value}; artworkProjections.set(node,artwork)
      }
      latestArtworkNodes.delete(artworkSlot)
      if(latestArtworkNodes.size>=512)latestArtworkNodes.delete(latestArtworkNodes.keys().next().value!)
      latestArtworkNodes.set(artworkSlot,new WeakRef(node))
      // Keep projection identity stable across camera/peer changes. Source or
      // asset replacements must never reuse a previously accepted image.
      if (artwork.value) {
        const projection = nodeProjections.get(node)!
        if (projection.object.modelArtwork !== artwork.value) projection.object = {...object,modelArtwork:artwork.value}
        return projection.object
      }
      if(object.modelArtwork){const projection=nodeProjections.get(node)!;projection.object={...object,modelArtwork:undefined};return projection.object}
      return object
    })
    const graphProjection = projectGraphColumns(board)
    // Ports are part of the canonical structured card paint, not extra unsupported
    // child objects. Derived edges are independent vectors below ordinary objects.
    for (let index=0;index<graphProjection.connections.length;index++) {
      const edge=graphProjection.connections[index],geometry=connectorGeometry(edge,board.nodes)
      if(!geometry||objects.find(o=>o.id===edge.sourceId)?.hidden||objects.find(o=>o.id===edge.targetId)?.hidden)continue
      const coords=geometry.commands.flatMap(command=>command.slice(1) as number[]),xs=coords.filter((_,i)=>i%2===0),ys=coords.filter((_,i)=>i%2===1)
      const bounds={x:Math.min(...xs),y:Math.min(...ys),width:Math.max(...xs)-Math.min(...xs),height:Math.max(...ys)-Math.min(...ys)}
      objects = [...objects, {id:edge.id,revision:revisionFor(edge),order:-graphProjection.connections.length+index,zIndex:-1,kind:'vector',bounds,localBounds:bounds,locked:true,hidden:false,appearance:{fill:'#00000000',stroke:edge.color,strokeWidth:edge.width,strokeScaling:'scene',opacity:1,rotation:0},preparedVectorGeometry:{status:'ready',commands:geometry.commands,bounds,fillRule:'nonzero',hasFill:false,strokeOutsetCssPx:1}}]
    }

    const ports=new Map<string,{x:number;y:number;color:string}[]>()
    for(const node of board.nodes){
      const items=nodeGraphPorts(board,node,nodesById).map(port=>{const p=computePortPosition(port,node);return {x:p.x-node.x,y:p.y-node.y,color:PORT_SEMANTIC_COLORS[port.semanticType]}})
      if(items.length)ports.set(node.id,items)
    }
    for(const edge of graphProjection.connections){
      const node=nodesById.get(edge.sourceId!),geometry=connectorGeometry(edge,board.nodes)
      if(!node||!geometry)continue
      const a=-(node.rotation||0)*Math.PI/180,c=Math.cos(a),s=Math.sin(a),dx=geometry.source.x-node.x-node.width/2,dy=geometry.source.y-node.y-node.height/2
      const p={x:node.width/2+c*dx-s*dy,y:node.height/2+s*dx+c*dy,color:edge.color}
      const items=ports.get(node.id)||[];if(!items.some(old=>Math.hypot(old.x-p.x,old.y-p.y)<.001))items.push(p);ports.set(node.id,items)
    }
    objects=objects.map(object=>object.modelArtwork&&ports.has(object.id)?{...object,modelPorts:ports.get(object.id)}:object)
    byAssets.set(assets, {sources,objects})
  }
  let byConnectors = connectionCache.get(board.nodes)
  if (!byConnectors) { byConnectors = new WeakMap(); connectionCache.set(board.nodes, byConnectors) }
  let connections = byConnectors.get(board.connectors)
  if (!connections) {
    const visible = new Set(objects.filter((object) => !object.hidden).map((object) => object.id))
    connections = [...board.connectors, ...projectGraphColumns(board).connections].filter((connection) => (!connection.sourceId || visible.has(connection.sourceId)) && (!connection.targetId || visible.has(connection.targetId))).map(sceneConnection)
    byConnectors.set(board.connectors, connections)
  }
  const environment = {
    background: colors.background,
    grid: {
      visible: board.gridVisible !== false,
      color: colors.grid,
      opacity: Math.max(.05, Math.min(1, board.gridOpacity ?? DEFAULT_CANVAS_GRID_OPACITY)),
      spacing: Math.max(12, Math.min(120, board.gridSpacing || 44)),
    },
  }
  if (!lastEnvironment || JSON.stringify(lastEnvironment) !== JSON.stringify(environment)) lastEnvironment = environment
  return {
    id: board.id,
    revision: revisionFor(board),
    objects,
    connections,
    environment: lastEnvironment,
  }
}

import type { BoardModel, BoardNode, ProjectModel } from '../model/project'

// Board-organization logic lives in the app layer (src/board), not in
// canvas-engine: the engine boundary test forbids engine modules from
// importing the application model, and hierarchy rules operate on that model.

export type BoardHierarchyIssue = Readonly<{
  boardId: string
  kind: 'missing-parent' | 'self-parent' | 'cycle'
}>

export type NestedBoardCreation = Readonly<{
  board: BoardModel
}>

export function boardAncestors(boards: readonly BoardModel[], boardId: string): BoardModel[] {
  const byId = new Map(boards.map((board) => [board.id, board]))
  const result: BoardModel[] = []
  const visited = new Set([boardId])
  let current = byId.get(boardId)
  while (current?.parentBoardId) {
    if (visited.has(current.parentBoardId)) break
    const parent = byId.get(current.parentBoardId)
    if (!parent) break
    result.unshift(parent)
    visited.add(parent.id)
    current = parent
  }
  return result
}

export function boardChildren(boards: readonly BoardModel[], parentBoardId: string): BoardModel[] {
  return boards.filter((board) => board.parentBoardId === parentBoardId)
}

export function canReparentBoard(boards: readonly BoardModel[], boardId: string, parentBoardId?: string): boolean {
  if (!parentBoardId) return true
  if (boardId === parentBoardId) return false
  return !boardAncestors(boards, parentBoardId).some((board) => board.id === boardId)
}

/** Recover invalid ownership without discarding a board. Existing board-link
 * shortcuts remain shortcuts; ownership is expressed only by parentBoardId. */
export function normalizeBoardHierarchy(boards: readonly BoardModel[]): { boards: BoardModel[]; issues: BoardHierarchyIssue[] } {
  const byId = new Map(boards.map((board) => [board.id, board]))
  const issues: BoardHierarchyIssue[] = []
  const normalized = boards.map((board) => {
    if (!board.parentBoardId) return board
    if (board.parentBoardId === board.id) {
      issues.push({ boardId: board.id, kind: 'self-parent' })
      return { ...board, parentBoardId: undefined }
    }
    if (!byId.has(board.parentBoardId)) {
      issues.push({ boardId: board.id, kind: 'missing-parent' })
      return { ...board, parentBoardId: undefined }
    }
    const visited = new Set([board.id])
    let cursor = byId.get(board.parentBoardId)
    while (cursor) {
      if (visited.has(cursor.id)) {
        issues.push({ boardId: board.id, kind: 'cycle' })
        return { ...board, parentBoardId: undefined }
      }
      visited.add(cursor.id)
      cursor = cursor.parentBoardId ? byId.get(cursor.parentBoardId) : undefined
    }
    return board
  })
  return { boards: normalized, issues }
}

export function createNestedBoard(parent: BoardModel, title: string): NestedBoardCreation {
  const id = `board-${crypto.randomUUID()}`
  return {
    board: {
      id,
      title,
      parentBoardId: parent.id,
      viewport: { x: 28, y: 28, scale: .82 },
      nodes: [],
      connectors: [],
    },
  }
}

export function insertNestedBoard(project: ProjectModel, parentBoardId: string, title: string, position: { x: number; y: number } = { x: 120, y: 120 }): { project: ProjectModel; boardId: string; portalId: string } | null {
  const parent = project.boards.find((board) => board.id === parentBoardId)
  if (!parent) return null
  const created = createNestedBoard(parent, title)
  const portal: BoardNode = { id: `board-portal-${crypto.randomUUID()}`, kind: 'board-link', boardLinkRole: 'child', boardPortal: true, targetBoardId: created.board.id, x: Math.round(position.x), y: Math.round(position.y), width: 140, height: 128, title, color: '#5778c9' }
  return {
    boardId: created.board.id,
    portalId: portal.id,
    project: {
      ...project,
      boards: [...project.boards.map((board) => board.id === parentBoardId ? { ...board, nodes: [...board.nodes, portal] } : board), created.board],
    },
  }
}

/** Keep subboard portals at their compact tile size. Earlier previews saved
 * oversized card bounds that made selection handles surround empty canvas. */
export function normalizeBoardPortalBounds(boards: readonly BoardModel[]): BoardModel[] {
  return boards.map((board) => {
    let changed = false
    const nodes = board.nodes.map((node) => {
      // Portals laid out inside a column keep their grid cell bounds; the
      // 140x128 fallback only repairs free-floating tiles.
      if (node.kind !== 'board-link' || node.boardLinkRole !== 'child' || !node.boardPortal || node.parentColumnId || node.groupId || (node.width === 140 && node.height === 128)) return node
      changed = true
      return { ...node, width: 140, height: 128 }
    })
    return changed ? { ...board, nodes } : board
  })
}

/** Remove legacy auto-inserted child cards while retaining their real boards.
 * Explicit shortcut cards remain visible. */
export function withoutLegacyChildTiles(boards: readonly BoardModel[]): BoardModel[] {
  return boards.map((board) => {
    const removed = new Set(board.nodes.filter((node) => node.kind === 'board-link' && node.boardLinkRole === 'child' && !node.boardPortal).map((node) => node.id))
    if (!removed.size) return board
    const removedNodes = board.nodes.filter((node) => removed.has(node.id))
    const removedConnectors = board.connectors.filter((connector) => removed.has(connector.sourceId || '') || removed.has(connector.targetId || ''))
    return {
      ...board,
      legacyHiddenChildTiles: {
        nodes: [...(board.legacyHiddenChildTiles?.nodes || []), ...removedNodes],
        connectors: [...(board.legacyHiddenChildTiles?.connectors || []), ...removedConnectors],
      },
      nodes: board.nodes.filter((node) => !removed.has(node.id)),
      connectors: board.connectors.filter((connector) => !removed.has(connector.sourceId || '') && !removed.has(connector.targetId || '')),
    }
  })
}

import { useEffect, useMemo, useRef, useState } from 'react'
import type { CanvasSceneSnapshot, CanvasViewport } from '../canvas-engine/contracts'
import type { BoardNode } from '../model/project'
import { mapToMinimap, minimapBounds, minimapSceneSvg, type MinimapImage } from './minimapGeometry'
import { appUpdateClock } from '../canvas-engine/appFrameClock'

type BoardMinimapProps = {
  camera?: import('../canvas-engine/liveCamera').LiveCamera
  scene: CanvasSceneSnapshot
  nodes?: readonly BoardNode[]
  viewport: CanvasViewport
  stageWidth: number
  stageHeight: number
  onViewportChange: (viewport: CanvasViewport) => void
  assetSources?: ReadonlyMap<string, string>
}

export function BoardMinimap({ scene, nodes, viewport, camera, stageWidth, stageHeight, onViewportChange, assetSources }: BoardMinimapProps) {
  const contentRef = useRef<HTMLCanvasElement>(null)
  const viewportRef = useRef<HTMLCanvasElement>(null)
  const objects = scene.objects
  const bounds = useMemo(() => minimapBounds(objects, stageWidth, stageHeight, nodes), [objects, nodes, stageHeight, stageWidth])
  const [pixelRatio, setPixelRatio] = useState(() => window.devicePixelRatio || 1)
  const thumbnails = useRef(new Map<string, MinimapImage | null>())
  // Small overview rasters only; never cache viewport-sized board frames.
  // Exact scene keys let undo reuse the already accepted pixels. Both the
  // entry count and aggregate SVG key size are bounded for large boards.
  const overviewRasters = useRef(new Map<string, ImageData>())

  useEffect(() => {
    let media: MediaQueryList | undefined
    const refresh = () => {
      media?.removeEventListener('change', refresh)
      media = window.matchMedia(`(resolution: ${window.devicePixelRatio || 1}dppx)`)
      media.addEventListener('change', refresh, { once: true })
      setPixelRatio(window.devicePixelRatio || 1)
    }
    window.addEventListener('resize', refresh)
    refresh()
    return () => { window.removeEventListener('resize', refresh); media?.removeEventListener('change', refresh) }
  }, [])

  // Scene content is retained in its own layer. Camera motion only redraws the
  // small viewport rectangle below, so a 20k-object board is not replayed for
  // every pan or zoom frame.
  useEffect(() => {
    const canvas = contentRef.current
    if (!canvas) return
    const surface = prepareCanvas(canvas, pixelRatio)
    if (!surface) return
    const { context, width, height } = surface
    let cancelled = false, paintFrame: number | undefined
    let paintGeneration = 0
    const images = new Map<string, MinimapImage>()
    const byId = new Map(nodes?.map(node => [node.id, node]))
    const loading = new Map<HTMLImageElement, () => void>()
    const draw = () => {
      const generation = ++paintGeneration
      const svg = minimapSceneSvg(scene, nodes, bounds, width, height, images)
      const imageCount = images.size
      const accepted = overviewRasters.current.get(svg)
      const publish = () => {
        canvas.dataset.imageThumbnails = String(imageCount)
        canvas.dataset.sceneRevision = String(scene.revision)
      }
      if (accepted && accepted.width === canvas.width && accepted.height === canvas.height) {
        context.putImageData(accepted, 0, 0); publish(); return
      }
      const image = new Image()
      image.onload = () => {
        if (cancelled || generation !== paintGeneration) return
        context.clearRect(0, 0, width, height); context.drawImage(image, 0, 0, width, height)
        if (svg.length <= 250_000 && canvas.width && canvas.height) try {
          overviewRasters.current.delete(svg)
          overviewRasters.current.set(svg, context.getImageData(0, 0, canvas.width, canvas.height))
          while (overviewRasters.current.size > 4) overviewRasters.current.delete(overviewRasters.current.keys().next().value!)
        } catch { /* A non-readable vector/media source cannot block the overview. */ }
        publish()
      }
      image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`
    }
    const scheduleDraw = () => {
      if (paintFrame === undefined) paintFrame = appUpdateClock.request(() => { paintFrame = undefined; if (!cancelled) draw() })
    }
    const pending = new Map<string, {ids: string[]; key: string; source: string}>()
    for (const object of scene.objects.filter(object => !object.hidden)) {
      const node = byId.get(object.id), artwork = object.modelArtwork
      const poster = node?.assetId ? assetSources?.get(node.assetId + ':overview') : undefined
      const source = poster || (artwork?.kind === 'image' ? artwork.source : node?.kind === 'image' && node.body?.startsWith('data:image/') ? node.body : undefined)
      if (!source) continue
      // Inline pixels are immutable content. Repeated cards share one decode
      // even when their object revisions differ; managed files retain a revision.
      const key = source.startsWith('data:') ? source : `${object.asset?.revision || (artwork?.kind === 'image' ? artwork.sourceRevision : 0)}:${source}`
      const cached = thumbnails.current.get(key)
      if (cached) images.set(object.id, cached)
      if (!thumbnails.current.has(key)) {
        const job = pending.get(key)
        if (job) job.ids.push(object.id)
        else pending.set(key, {ids:[object.id], key, source})
      }
    }
    const jobs = [...pending.values()]
    draw()
    // Prefer managed posters. At most two source decodes run concurrently;
    // retain only bounded, small thumbnails, never full-size media or videos.
    let next = 0
    const worker = async () => {
      while (!cancelled && next < jobs.length) {
        const job = jobs[next++], image = new Image(); image.crossOrigin = 'anonymous'
        const decoded = await new Promise<boolean>(resolve => {
          loading.set(image, () => resolve(false))
          image.onload = () => resolve(true); image.onerror = () => resolve(false); image.src = job.source
        })
        loading.delete(image)
        if (cancelled) return
        let thumbnail: MinimapImage | null = null
        if (decoded) try {
          const ratio = Math.min(1,192 / Math.max(image.naturalWidth,image.naturalHeight)), small = document.createElement('canvas')
          small.width = Math.max(1,Math.round(image.naturalWidth*ratio)); small.height = Math.max(1,Math.round(image.naturalHeight*ratio))
          small.getContext('2d')!.drawImage(image,0,0,small.width,small.height)
          thumbnail = {source:small.toDataURL('image/png'),width:image.naturalWidth,height:image.naturalHeight}
        } catch { /* Unreadable media retains its accurate object footprint. */ }
        thumbnails.current.set(job.key,thumbnail)
        while(thumbnails.current.size>128)thumbnails.current.delete(thumbnails.current.keys().next().value!)
        if(thumbnail)for(const id of job.ids)images.set(id,thumbnail)
        scheduleDraw()
      }
    }
    void worker(); void worker()
    return () => {
      cancelled = true; if (paintFrame !== undefined) appUpdateClock.cancel(paintFrame)
      for (const [image, cancel] of loading) { image.onload = null; image.onerror = null; image.src = ''; cancel() }
      loading.clear()
    }
  }, [bounds, pixelRatio, scene, nodes, assetSources])

  useEffect(() => {
    const canvas = viewportRef.current
    if (!canvas) return
    const draw = (viewport: CanvasViewport) => {
    const surface = prepareCanvas(canvas, pixelRatio)
    if (!surface) return
    const { context, width, height } = surface
    context.clearRect(0, 0, width, height)
    const map = mapToMinimap(bounds, width, height)
    const viewportLeft = -viewport.x / viewport.scale
    const viewportTop = -viewport.y / viewport.scale
    context.strokeStyle = '#e3b574'
    context.lineWidth = 1.5
    context.strokeRect(map.x(viewportLeft), map.y(viewportTop), stageWidth / viewport.scale * map.scale, stageHeight / viewport.scale * map.scale)
    }
    draw(camera?.current || viewport)
    return camera?.subscribe(draw)
  }, [bounds, pixelRatio, stageHeight, stageWidth, viewport, camera])

  const isDraggingRef = useRef(false)

  function navigate(event: React.PointerEvent<HTMLButtonElement>) {
    const current = camera?.current || viewport
    const rect = contentRef.current!.getBoundingClientRect()
    const map = mapToMinimap(bounds, rect.width, rect.height)
    const worldX = (event.clientX - rect.left - map.offsetX) / map.scale + bounds.minX
    const worldY = (event.clientY - rect.top - map.offsetY) / map.scale + bounds.minY
    onViewportChange({ ...current, x: stageWidth / 2 - worldX * current.scale, y: stageHeight / 2 - worldY * current.scale })
  }

  function handlePointerDown(event: React.PointerEvent<HTMLButtonElement>) {
    if (event.button !== 0) return
    event.preventDefault(); event.stopPropagation()
    isDraggingRef.current = true
    try {
      event.currentTarget.setPointerCapture(event.pointerId)
    } catch {}
    navigate(event)
  }

  function handlePointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    if (!isDraggingRef.current) return
    navigate(event)
  }

  function handlePointerUp(event: React.PointerEvent<HTMLButtonElement>) {
    if (!isDraggingRef.current) return
    isDraggingRef.current = false
    try {
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId)
      }
    } catch {}
  }

  return (
    <button
      className="board-minimap"
      type="button"
      aria-label="Board minimap. Click or drag to navigate."
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      onLostPointerCapture={handlePointerUp}
      onKeyDown={event => {
        const delta = {ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[event.key]
        if(!delta)return
        event.preventDefault();event.stopPropagation()
        const current=camera?.current||viewport,step=event.shiftKey?.5:.1
        onViewportChange({...current,x:current.x-delta[0]*stageWidth*step,y:current.y-delta[1]*stageHeight*step})
      }}
    >
      <canvas ref={contentRef} />
      <canvas className="board-minimap-viewport" ref={viewportRef} />
    </button>
  )
}

function prepareCanvas(canvas: HTMLCanvasElement, pixelRatio: number) {
  const ratio = Math.min(2, Math.max(1, pixelRatio))
  const width = canvas.clientWidth
  const height = canvas.clientHeight
  const targetWidth = Math.round(width * ratio)
  const targetHeight = Math.round(height * ratio)
  if (canvas.width !== targetWidth) canvas.width = targetWidth
  if (canvas.height !== targetHeight) canvas.height = targetHeight
  const context = canvas.getContext('2d')
  if (!context) return undefined
  context.setTransform(ratio, 0, 0, ratio, 0, 0)
  return { context, width, height }
}

import type { BoardModel, BoardNode } from '../model/project'
import { containerDescendantIds, diagramState, diagramProjectionStates, moveContainerWithDescendants, validateContainerOwnership, type StructureResult } from './diagramStructureCore'
import { connectorGeometry } from './connectors'
import { resizeVectorNodeFrame } from '../model/vector'
import { isRectangleErasure, rectangleErasureState, resizeRectangleErasureFrame } from '../model/rectangleErasure'
import { guardColumnRowPosition } from './columnRowPosition'
import { validGradient, validTexture } from './vectorPaint'

const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)
// Imported vectors use fractional coordinates; equivalent translations can differ
// by floating-point roundoff after addition/subtraction. Never accept visible drift.
const sameCoordinate = (a: number, b: number) => Number.isFinite(a) && Number.isFinite(b) && Math.abs(a - b) <= 1e-7
const refuse = (detail: string): StructureResult<BoardModel> => ({ ok: false, issues: [{ code: 'unsafe-board-edit', detail }] })

/** Final boundary for all board content commands, including inspector/native
 * callbacks. Reject atomically before history or project state is changed. */
export function validateBoardMutation(before: BoardModel, after: BoardModel, readOnly = false): StructureResult<BoardModel> {
  const contentChanged = !same(before.nodes, after.nodes) || !same(before.connectors, after.connectors)
  if (readOnly && !same({ ...before, viewport: undefined }, { ...after, viewport: undefined })) return refuse('This workspace is read-only.')
  if (!contentChanged) return { ok: true, value: after }
  const valid = validateContainerOwnership(after.nodes)
  if (!valid.ok) return valid
  const afterStates = diagramProjectionStates(after.nodes)
  if (!afterStates.ok) return afterStates
  const beforeStates = diagramProjectionStates(before.nodes)
  if (!beforeStates.ok) return beforeStates
  const next = new Map(after.nodes.map((node) => [node.id, node]))
  const originalNodes = new Map(before.nodes.map((node) => [node.id, node]))
  for (const node of before.nodes) {
    const changed = next.get(node.id)
    if (same(node, changed)) continue
    const unlocking = changed && node.locked && changed.locked === false && same({ ...node, locked: false }, changed)
    const showing = changed && node.hidden && changed.hidden === false && same({ ...node, hidden: false }, changed)
    const nodes = unlocking || showing ? before.nodes.map((entry) => entry.id === node.id ? { ...entry, ...(unlocking ? { locked: false } : { hidden: false }) } : entry) : before.nodes
    const unlockedState = unlocking || showing ? diagramState(nodes, node.id) : undefined
    if (unlockedState && !unlockedState.ok) return unlockedState
    const state = unlockedState?.ok ? unlockedState.value : beforeStates.value.get(node.id)!
    if (state.locked || state.hidden) return refuse('The object or its owner is locked, hidden or collapsed; the command was cancelled.')
    if (changed && (node.kind === 'group' || node.kind === 'column') && (changed.x !== node.x || changed.y !== node.y) && changed.width === node.width && changed.height === node.height && changed.rotation === node.rotation) {
      const descendants = containerDescendantIds(before.nodes, [node.id])
      if (!descendants.ok) return descendants
      for (const id of descendants.value) {
        const original = originalNodes.get(id)!, moved = next.get(id)
        if (!moved || !sameCoordinate(moved.x, original.x + (changed.x - node.x)) || !sameCoordinate(moved.y, original.y + (changed.y - node.y))) return refuse('Move the container and all its members together; the command was cancelled.')
      }
    }
  }
  for (const node of after.nodes) {
    if ((node.vectorFillGradient && !validGradient(node.vectorFillGradient)) || (node.vectorStrokeGradient && !validGradient(node.vectorStrokeGradient)) || (node.vectorTexture && !validTexture(node.vectorTexture)) || [node.fillOpacity,node.strokeOpacity].some(value=>value!==undefined && (!Number.isFinite(value)||value<0||value>1))) return refuse('Drawing paint must contain valid gradients, textures and transparency values.')
    if (![node.x, node.y, node.width, node.height, node.rotation ?? 0].every(Number.isFinite) || node.width <= 0 || node.height <= 0) return refuse('Object geometry must be finite with positive dimensions.')
    const previous = originalNodes.get(node.id), owner = node.groupId || node.parentColumnId
    if (node.kind === 'shape' && node.shapeType === 'rectangle' && node.vectorBoolean && !same(previous, node) && !rectangleErasureState(node)) return refuse('Rectangle erasure modifiers must remain valid with their frame; the original artwork is preserved.')
    if (owner && (!previous || owner !== (previous.groupId || previous.parentColumnId))) {
      const destination = beforeStates.value.get(owner)
      if (destination?.locked || destination?.hidden) return refuse('The destination container is locked, hidden or collapsed; the command was cancelled.')
    }
  }
  const ids = new Set(after.nodes.map((node) => node.id)), edges = new Set<string>()
  for (const edge of after.connectors) {
    if (edges.has(edge.id) || (edge.sourceId && !ids.has(edge.sourceId)) || (edge.targetId && !ids.has(edge.targetId))) return refuse('The command would leave an invalid connection identity or endpoint.')
    edges.add(edge.id)
    if ([...(edge.bendPoints || []), ...(edge.sourcePoint ? [edge.sourcePoint] : []), ...(edge.targetPoint ? [edge.targetPoint] : [])].some((point) => !Number.isFinite(point.x) || !Number.isFinite(point.y))) return refuse('Connection geometry must be finite.')
  }
  const nextEdges = new Map(after.connectors.map((edge) => [edge.id, edge]))
  for (const edge of before.connectors) {
    if (same(edge, nextEdges.get(edge.id))) continue
    for (const id of [edge.sourceId, edge.targetId]) {
      if (!id) continue
      const state = beforeStates.value.get(id)
      if (!state || state.locked || state.hidden) return refuse('A connection endpoint is locked, hidden or collapsed; the command was cancelled.')
    }
  }
  return { ok: true, value: after }
}

export function patchBoardNode(board: BoardModel, id: string, patch: Partial<BoardNode>, readOnly = false, normalize: (node: BoardNode) => BoardNode = (node) => node): StructureResult<BoardModel> {
  const node = board.nodes.find((entry) => entry.id === id)
  if (!node) return refuse('The selected object is no longer on this board.')
  if (['width', 'height'].some((key) => key in patch && (!Number.isFinite(patch[key as 'width' | 'height']) || patch[key as 'width' | 'height']! <= 0))) return refuse('Object dimensions must be finite and positive.')
  const positionChanged = ('x' in patch && patch.x !== node.x) || ('y' in patch && patch.y !== node.y)
  const frameChanged = ('width' in patch && patch.width !== node.width) || ('height' in patch && patch.height !== node.height)
  if (isRectangleErasure(node) && frameChanged && Object.hasOwn(patch, 'vectorBoolean')) return refuse('Change the rectangle frame and its erasure modifiers in separate validated commands.')
  if (isRectangleErasure(node) && frameChanged && [patch.x ?? node.x, patch.y ?? node.y, patch.width ?? node.width, patch.height ?? node.height].some(value => !Number.isFinite(value) || Math.abs(value) > 1e9)) return refuse('Rectangle dimensions exceed the bounded erasure geometry; artwork is preserved.')
  if (positionChanged && !frameChanged) {
    const position = guardColumnRowPosition(board, [id])
    if (!position.ok) return position
  }
  let next = board
  if ('x' in patch || 'y' in patch) {
    const moved = moveContainerWithDescendants(board.nodes, board.connectors, [id], { x: (patch.x ?? node.x) - node.x, y: (patch.y ?? node.y) - node.y })
    if (!moved.ok) return moved
    next = { ...board, nodes: moved.value.nodes, connectors: moved.value.connectors }
  }
  if (['width', 'height', 'rotation'].some((key) => key in patch && patch[key as keyof BoardNode] !== node[key as keyof BoardNode]) && (node.kind === 'group' || node.kind === 'column')) {
    const descendants = containerDescendantIds(board.nodes, [id])
    if (!descendants.ok) return descendants
    for (const child of descendants.value) {
      const state = diagramState(board.nodes, child)
      if (!state.ok) return state
      if (state.value.locked || state.value.hidden) return refuse('A container member is locked, hidden or collapsed; the transform was cancelled.')
    }
  }
  next = { ...next, nodes: next.nodes.map((entry) => {
    if (entry.id !== id) return entry
    const updated = { ...entry, ...patch }
    const resized = isRectangleErasure(entry) && (updated.width !== entry.width || updated.height !== entry.height)
      ? resizeRectangleErasureFrame({ ...updated, x: entry.x, y: entry.y, width: entry.width, height: entry.height }, updated)
      : entry.vectorPath && (updated.width !== entry.width || updated.height !== entry.height)
      ? resizeVectorNodeFrame({ ...updated, x: entry.x, y: entry.y, width: entry.width, height: entry.height }, updated)
      : updated
    return normalize(resized)
  }) }
  return validateBoardMutation(board, next, readOnly)
}

/** Dissolving a container releases direct members in world space. Connections
 * attached to its boundary become detached at their current visible endpoints. */
export function dissolveBoardContainer(board: BoardModel, id: string, readOnly = false): StructureResult<BoardModel> {
  const node = board.nodes.find((entry) => entry.id === id)
  if (!node || (node.kind !== 'group' && node.kind !== 'column')) return refuse('Choose a group, frame or column to dissolve.')
  const descendants = containerDescendantIds(board.nodes, [id])
  if (!descendants.ok) return descendants
  for (const child of descendants.value) {
    const state = diagramState(board.nodes, child)
    if (!state.ok) return state
    if (state.value.locked || state.value.hidden) return refuse('A container member is locked, hidden or collapsed; dissolving was cancelled.')
  }
  const next = { ...board, nodes: board.nodes.filter((entry) => entry.id !== id).map((entry) => {
    if (entry.groupId !== id && entry.parentColumnId !== id) return entry
    const released = { ...entry }; delete released.groupId; delete released.parentColumnId; delete released.columnOrder; delete released.freeWidth; delete released.freeHeight
    if (node.groupId) released.groupId = node.groupId
    else if (node.parentColumnId) { released.parentColumnId = node.parentColumnId; released.columnOrder = entry.columnOrder ?? node.columnOrder ?? 0 }
    return released
  }), connectors: board.connectors.map((edge) => {
    if (edge.sourceId !== id && edge.targetId !== id) return edge
    const geometry = connectorGeometry(edge, board.nodes)
    if (!geometry) return edge // Validation below refuses any unresolved endpoint.
    return { ...edge, ...(edge.sourceId === id ? { sourceId: undefined, sourcePoint: geometry.source } : {}), ...(edge.targetId === id ? { targetId: undefined, targetPoint: geometry.target } : {}) }
  }) }
  return validateBoardMutation(board, next, readOnly)
}

import { memo, useEffect, useMemo, useRef, useState } from 'react'
import type { BoardModel, ProjectAsset } from '../model/project'
import { createArtEquationCanvasScene } from './artEquationCanvasAdapter'
import { minimapBounds, minimapSceneSvg } from './minimapGeometry'
import { recordMetric } from '../diagnostics/performance'

/** Automatic previews share path/Boolean/transform geometry with the minimap. */
const EMPTY_ASSETS: readonly ProjectAsset[] = []
export const BoardPreview = memo(function BoardPreview({ board, assets = EMPTY_ASSETS, width = 160, height = 110, fallbackBackground = '#1b1f25' }: { board: BoardModel; assets?: readonly ProjectAsset[]; width?: number; height?: number; fallbackBackground?: string }) {
  const image = useRef<HTMLImageElement>(null), retained = useRef<{ identity: unknown[]; source: string } | undefined>(undefined)
  const [visible, setVisible] = useState(false)
  const [foreground, setForeground] = useState(!document.hidden)
  useEffect(() => {
    const node = image.current
    if (!node) return
    const onVisibility = () => setForeground(!document.hidden)
    document.addEventListener('visibilitychange', onVisibility)
    const observer = new IntersectionObserver(entries => setVisible(entries.some(entry => entry.isIntersecting)), { rootMargin: '0px' })
    observer.observe(node)
    return () => { observer.disconnect(); document.removeEventListener('visibilitychange', onVisibility) }
  }, [])
  const source = useMemo(() => {
    if (!visible || !foreground) return retained.current?.source
    const identity = [board.id, board.nodes, board.connectors, board.backgroundColor, board.backgroundFollowsTheme, assets, width, height, fallbackBackground]
    if (retained.current?.identity.every((value, index) => value === identity[index])) return retained.current.source
    const start = performance.now()
    const scene = createArtEquationCanvasScene(board, assets, { background: board.backgroundFollowsTheme ? fallbackBackground : board.backgroundColor || fallbackBackground, grid: '#64748b' })
    const bounds = minimapBounds(scene.objects, width, height, board.nodes)
    const result = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(minimapSceneSvg(scene, board.nodes, bounds, width, height))}`
    retained.current = { identity, source: result }
    recordMetric('board.preview-built', { boardId: board.id, objects: scene.objects.length, durationMs: performance.now() - start })
    return result
  }, [visible, foreground, board.id, board.nodes, board.connectors, board.backgroundColor, board.backgroundFollowsTheme, assets, width, height, fallbackBackground])
  return <img ref={image} className="automatic-board-preview" data-preview-board={board.id} data-preview-demand={visible && foreground ? 'visible' : 'idle'} src={source} alt="" width={width} height={height} loading="lazy" draggable={false} />
})

import { useEffect, useState } from 'react'
import type { RefObject } from 'react'

export type BoardRendererSnapshot = {
  state: 'loading' | 'ready' | 'fallback' | 'unknown'
  renderer: string | null
  rawState: string | null
  detail: string
  error: string | null
}

const unknown = (detail: string): BoardRendererSnapshot => ({ state: 'unknown', renderer: null, rawState: null, detail, error: null })

function reportedAttribute(host: HTMLElement, name: string, limit: number) {
  const value = host.getAttribute(name)?.trim()
  return value ? value.length > limit ? value.slice(0, limit) + '…' : value : null
}

function visible(element: HTMLElement) {
  if (element.hidden || !element.getClientRects().length) return false
  const style = element.ownerDocument.defaultView?.getComputedStyle(element)
  return style?.display !== 'none' && style?.visibility !== 'hidden' && style?.visibility !== 'collapse'
}

/** Observe only the production backdrop directly owned by this visible canvas.
 * A configured edition, nested media renderer or hidden old host cannot prove readiness.
 */
export function readBoardRendererDiagnostics(stage: HTMLElement | null): BoardRendererSnapshot {
  if (!stage?.matches('.canvas-stage')) return unknown('Current canvas is unavailable.')
  const pane = stage.closest<HTMLElement>('.canvas-pane')
  if (!pane || !visible(pane) || !visible(stage)) return unknown('Current canvas is hidden.')
  const hosts = Array.from(stage.children).filter((child) => child.matches('.gpu-board') && visible(child as HTMLElement)) as HTMLElement[]
  if (hosts.length !== 1) return unknown(hosts.length ? 'Multiple visible backdrop hosts; readiness is ambiguous.' : 'No visible reporting backdrop in this canvas.')
  const host = hosts[0]
  const rawState = reportedAttribute(host, 'data-render-state', 48)
  const renderer = reportedAttribute(host, 'data-renderer', 80)
  const error = reportedAttribute(host, 'data-render-error', 600)
  const retainedError = reportedAttribute(host, 'data-retained-fallback', 600)
  const result: BoardRendererSnapshot = { state: 'unknown', renderer, rawState, detail: 'Backdrop has not reported readiness.', error: error || retainedError }
  if (rawState === 'loading' || rawState === 'scheduled') {
    result.state = 'loading'; result.detail = rawState === 'scheduled' ? 'Render scheduled.' : 'Render loading.'
  } else if (rawState === 'fallback' || rawState === 'context-lost' || retainedError || (!rawState && error)) {
    result.state = 'fallback'; result.detail = rawState === 'context-lost' ? 'WebGL context lost.' : retainedError ? 'Retained content reported fallback.' : 'Backdrop reported fallback.'
  } else if (rawState === 'ready' && renderer === 'vello-webgpu') {
    result.state = 'ready'; result.detail = 'Vello host reports ready.'
  } else if (rawState === 'idle') {
    let renders = 0
    try { renders = JSON.parse(host.getAttribute('data-render-metrics') || '{}').renders } catch { /* Unknown metrics cannot establish a completed render. */ }
    if (Number.isFinite(renders) && renders > 0) {
      result.state = 'ready'; result.detail = 'Host idle after a reported render.'
    } else result.detail = 'Host idle; completed render is unreported.'
  } else if (rawState) result.detail = `Host state: ${rawState}. Readiness is unreported.`
  return result
}

/** Track lazy mounting, replacement, removal and host reports without polling or
 * changing renderer state. Cleanup rejects even already queued observer callbacks.
 */
export function observeBoardRendererDiagnostics(stage: HTMLElement | null, publish: (value: BoardRendererSnapshot) => void) {
  let active = true
  let previous = ''
  const refresh = () => {
    if (!active) return
    const snapshot = readBoardRendererDiagnostics(stage)
    const key = JSON.stringify(snapshot)
    if (key !== previous) { previous = key; publish(snapshot) }
  }
  refresh()
  const view = stage?.ownerDocument.defaultView
  if (!stage || !view) return () => { active = false }
  const pane = stage.closest<HTMLElement>('.canvas-pane')
  const observer = new view.MutationObserver((records) => {
    if (records.some((record) => record.type === 'childList' || record.target === stage || record.target === pane || (record.target as Element).matches?.('.gpu-board'))) refresh()
  })
  observer.observe(stage, { subtree: true, childList: true, attributes: true, attributeFilter: ['data-render-state', 'data-renderer', 'data-render-error', 'data-retained-fallback', 'data-render-metrics', 'hidden', 'class', 'style'] })
  if (pane) observer.observe(pane, { attributes: true, attributeFilter: ['hidden', 'class', 'style'] })
  view.addEventListener('resize', refresh)
  return () => { active = false; observer.disconnect(); view.removeEventListener('resize', refresh) }
}

export function BoardRendererDiagnosticRows({ configuredRenderer, snapshot }: { configuredRenderer: string, snapshot: BoardRendererSnapshot }) {
  const state = snapshot.state[0].toUpperCase() + snapshot.state.slice(1)
  return <>
    <div><dt>Renderer configuration</dt><dd>{configuredRenderer}</dd></div>
    <div><dt>Backdrop status</dt><dd data-observed-render-state={snapshot.state}>{state} · {snapshot.renderer === 'vello-webgpu' ? 'Vello WebGPU' : snapshot.renderer || 'Renderer unreported'}</dd></div>
    <div><dt>Renderer observation</dt><dd>{snapshot.detail}</dd></div>
    {snapshot.error && <div><dt>Last reported renderer error</dt><dd style={{ overflowWrap: 'anywhere' }}>{snapshot.error}</dd></div>}
  </>
}

export function BoardRendererDiagnostics({ stageRef, configuredRenderer }: { stageRef: RefObject<HTMLDivElement | null>, configuredRenderer: string }) {
  const [snapshot, setSnapshot] = useState<BoardRendererSnapshot>(() => unknown('Renderer observation is starting.'))
  useEffect(() => observeBoardRendererDiagnostics(stageRef.current, setSnapshot), [stageRef])
  return <BoardRendererDiagnosticRows configuredRenderer={configuredRenderer} snapshot={snapshot} />
}

