import { managedBoardFolderPath, type BoardConnector, type BoardModel, type BoardNode, type ProjectModel } from '../model/project'

export type BoardTransactionIdFactory = (kind: 'board' | 'node' | 'connector') => string

/** Ownership follows parentBoardId, never a shortcut target or disk path. */
export function ownedBoardSubtree(boards: readonly BoardModel[], boardId: string): BoardModel[] {
  const ids = new Set([boardId])
  let changed = true
  while (changed) {
    changed = false
    for (const board of boards) if (board.parentBoardId && ids.has(board.parentBoardId) && !ids.has(board.id)) {
      ids.add(board.id)
      changed = true
    }
  }
  return boards.filter((board) => ids.has(board.id))
}

/** Expand visual containers without confusing them with nested board ownership. */
export function containerNodeIds(board: BoardModel, selectedIds: readonly string[]): Set<string> {
  const ids = new Set(selectedIds)
  let changed = true
  while (changed) {
    changed = false
    for (const node of board.nodes) if (!ids.has(node.id)
      && ((node.parentColumnId && ids.has(node.parentColumnId)) || (node.groupId && ids.has(node.groupId)))) {
      ids.add(node.id)
      changed = true
    }
  }
  return ids
}

function allBoardNodes(board: BoardModel): BoardNode[] {
  return [...board.nodes, ...(board.legacyHiddenChildTiles?.nodes || [])]
}

function allBoardConnectors(board: BoardModel): BoardConnector[] {
  return [...board.connectors, ...(board.legacyHiddenChildTiles?.connectors || [])]
}

function hasUniqueIds(items: readonly { id: string }[]): boolean {
  return items.every((item) => Boolean(item.id)) && new Set(items.map((item) => item.id)).size === items.length
}

/** A bounded source validation: reject ambiguous IDs/references instead of
 * cloning them into apparently independent records. Missing asset files remain
 * a catalog-health concern; immutable catalog/source references are retained. */
function validDuplicationSource(project: ProjectModel, subtree: readonly BoardModel[]): boolean {
  if (!hasUniqueIds(project.boards) || !hasUniqueIds(project.boards.flatMap(allBoardNodes)) || !hasUniqueIds(project.boards.flatMap(allBoardConnectors))) return false
  const boards = new Map(project.boards.map((board) => [board.id, board]))
  for (const board of subtree) {
    if (board.parentBoardId && !boards.has(board.parentBoardId)) return false
    const ancestors = new Set([board.id])
    let parent = board.parentBoardId
    while (parent) {
      if (ancestors.has(parent)) return false
      ancestors.add(parent)
      parent = boards.get(parent)?.parentBoardId
    }
    const nodes = new Map(allBoardNodes(board).map((node) => [node.id, node]))
    const owners = new Set<string>()
    for (const node of nodes.values()) {
      if (node.parentColumnId && nodes.get(node.parentColumnId)?.kind !== 'column') return false
      if (node.groupId && nodes.get(node.groupId)?.kind !== 'group') return false
      if (node.kind === 'board-link' && node.boardLinkRole === 'child' && node.boardPortal) {
        if (!node.targetBoardId || boards.get(node.targetBoardId)?.parentBoardId !== board.id || owners.has(node.targetBoardId)) return false
        owners.add(node.targetBoardId)
      }
    }
    if (allBoardConnectors(board).some((connector) => (connector.sourceId && !nodes.has(connector.sourceId)) || (connector.targetId && !nodes.has(connector.targetId)))) return false
  }
  return true
}

function idAllocator(project: ProjectModel, factory: BoardTransactionIdFactory) {
  const taken = new Set([...project.boards.map((board) => board.id), ...project.boards.flatMap(allBoardNodes).map((node) => node.id), ...project.boards.flatMap(allBoardConnectors).map((connector) => connector.id)])
  return (kind: 'board' | 'node' | 'connector') => {
    for (let attempt = 0; attempt < 32; attempt++) {
      const id = factory(kind)
      if (id && !taken.has(id)) { taken.add(id); return id }
    }
    throw new Error('Could not allocate an independent board object ID')
  }
}

export type BoardDuplicateResult = {
  project: ProjectModel
  boardId: string
  boardIds: Map<string, string>
  nodeIds: Map<string, string>
  connectorIds: Map<string, string>
  /** Folders to prepare before committing the project transaction. No source
   * folder is moved or copied by this pure helper. */
  folderPaths: string[]
  portalId?: string
}

/** Duplicate the canonical owned subtree. Source assets stay shared immutable
 * catalog records; instance styles/crops/vector geometry are deep copies.
 * Child folder links are intentionally cleared rather than making the copy
 * appear to own the original child folder. New root boards use new managed
 * folders. The caller prepares folders and commits this result once. */
export function duplicateBoardSubtree(project: ProjectModel, boardId: string, options: { title?: string; idFactory?: BoardTransactionIdFactory } = {}): BoardDuplicateResult | null {
  const source = project.boards.find((board) => board.id === boardId)
  if (!source) return null
  const subtree = ownedBoardSubtree(project.boards, boardId)
  if (!validDuplicationSource(project, subtree)) return null
  const allocate = idAllocator(project, options.idFactory || ((kind) => `${kind}-${crypto.randomUUID()}`))
  const boardIds = new Map(subtree.map((board) => [board.id, allocate('board')]))
  const nodeIds = new Map(subtree.flatMap(allBoardNodes).map((node) => [node.id, allocate('node')]))
  const connectorIds = new Map(subtree.flatMap(allBoardConnectors).map((connector) => [connector.id, allocate('connector')]))
  const copyNode = (node: BoardNode, ownerId: string): BoardNode => {
    const copy = { ...structuredClone(node), id: nodeIds.get(node.id)!, parentColumnId: node.parentColumnId ? nodeIds.get(node.parentColumnId) : undefined, groupId: node.groupId ? nodeIds.get(node.groupId) : undefined }
    if (node.graphColumn) copy.graphColumn = { ...structuredClone(node.graphColumn), inputs: node.graphColumn.inputs.map(input => ({ ...input, sourceId: nodeIds.get(input.sourceId) || input.sourceId })) }
    if (node.kind === 'board-link' && node.targetBoardId) {
      copy.targetBoardId = boardIds.get(node.targetBoardId) || node.targetBoardId
      const owned = project.boards.find((board) => board.id === node.targetBoardId)?.parentBoardId === ownerId
      if (node.boardLinkRole === 'child' && !owned) { copy.boardLinkRole = 'shortcut'; copy.boardPortal = undefined }
    }
    return copy
  }
  const copyConnector = (connector: BoardConnector): BoardConnector => ({ ...structuredClone(connector), id: connectorIds.get(connector.id)!, sourceId: connector.sourceId ? nodeIds.get(connector.sourceId) : undefined, targetId: connector.targetId ? nodeIds.get(connector.targetId) : undefined })
  const copies = subtree.map((board): BoardModel => {
    const id = boardIds.get(board.id)!
    const parentBoardId = board.parentBoardId ? boardIds.get(board.parentBoardId) || board.parentBoardId : undefined
    return {
      ...structuredClone(board), id, parentBoardId,
      title: board.id === boardId ? options.title?.trim() || `${board.title} copy` : board.title,
      linkedFolderPath: parentBoardId ? undefined : managedBoardFolderPath(project.id, id),
      nodes: board.nodes.map((node) => copyNode(node, board.id)),
      connectors: board.connectors.map(copyConnector),
      ...(board.legacyHiddenChildTiles ? { legacyHiddenChildTiles: { nodes: board.legacyHiddenChildTiles.nodes.map((node) => copyNode(node, board.id)), connectors: board.legacyHiddenChildTiles.connectors.map(copyConnector) } } : {}),
    }
  })
  const newRoot = copies.find((board) => board.id === boardIds.get(boardId))!
  let portalId: string | undefined
  let originals = project.boards
  if (source.parentBoardId) {
    const parent = originals.find((board) => board.id === source.parentBoardId)!
    const sourcePortal = parent.nodes.find((node) => node.kind === 'board-link' && node.boardLinkRole === 'child' && node.targetBoardId === boardId && node.boardPortal)
    portalId = allocate('node')
    const portal: BoardNode = sourcePortal
      ? { ...structuredClone(sourcePortal), id: portalId, targetBoardId: newRoot.id, title: newRoot.title, x: sourcePortal.x + 28, y: sourcePortal.y + 28, columnOrder: sourcePortal.columnOrder === undefined ? undefined : sourcePortal.columnOrder + .5 }
      : { id: portalId, kind: 'board-link', boardLinkRole: 'child', boardPortal: true, targetBoardId: newRoot.id, title: newRoot.title, x: 120, y: 120, width: 140, height: 128, color: newRoot.tileAccentColor || '#5778c9' }
    originals = originals.map((board) => board.id === parent.id ? { ...board, nodes: [...board.nodes, portal] } : board)
  }
  return { project: { ...project, boards: [...originals, ...copies] }, boardId: newRoot.id, boardIds, nodeIds, connectorIds, folderPaths: copies.filter((board) => !board.parentBoardId).map((board) => board.linkedFolderPath!), portalId }
}

export type BoardTransferResult = { project: ProjectModel; movedNodeIds: string[]; detachedConnectorIds: string[] }

/** Move local instances (with container contents) to another board. Internal
 * connectors move with them. External connectors are explicitly reported and
 * detached, since this model cannot attach across boards. A UI must disclose
 * this policy and retain the original project for one-step Undo before commit.
 * Owning portals reparent their target but never move any linked disk folder. */
export function moveNodesBetweenBoards(project: ProjectModel, sourceBoardId: string, destinationBoardId: string, nodeIds: readonly string[], offset: { x: number; y: number } = { x: 0, y: 0 }): BoardTransferResult | null {
  const source = project.boards.find((board) => board.id === sourceBoardId)
  const destination = project.boards.find((board) => board.id === destinationBoardId)
  if (!source || !destination || source === destination || !nodeIds.length || !Number.isFinite(offset.x) || !Number.isFinite(offset.y)) return null
  if (!validDuplicationSource(project, [source, destination])) return null
  if (nodeIds.some((id) => !source.nodes.some((node) => node.id === id))) return null
  const movingIds = containerNodeIds(source, nodeIds)
  const moving = source.nodes.filter((node) => movingIds.has(node.id))
  // Data references are board-local. Refuse a partial graph transfer rather
  // than leaving computations connected to objects in another board.
  if (source.nodes.some(node => node.graphColumn?.inputs.some(input => movingIds.has(node.id) !== movingIds.has(input.sourceId)))) return null
  if (moving.some((node) => node.locked || destination.nodes.some((item) => item.id === node.id))) return null
  const childBoards = new Set<string>()
  for (const portal of moving.filter((node) => node.kind === 'board-link' && node.boardLinkRole === 'child')) {
    const target = project.boards.find((board) => board.id === portal.targetBoardId)
    if (!target || target.parentBoardId !== sourceBoardId || ownedBoardSubtree(project.boards, target.id).some((board) => board.id === destinationBoardId)) return null
    childBoards.add(target.id)
  }
  const internal = source.connectors.filter((connector) => (movingIds.has(connector.sourceId || '') || movingIds.has(connector.targetId || ''))
    && (!connector.sourceId || movingIds.has(connector.sourceId)) && (!connector.targetId || movingIds.has(connector.targetId)))
  if (internal.some((connector) => destination.connectors.some((item) => item.id === connector.id))) return null
  const affected = source.connectors.filter((connector) => movingIds.has(connector.sourceId || '') || movingIds.has(connector.targetId || ''))
  const internalIds = new Set(internal.map((connector) => connector.id))
  const transferred = moving.map((node): BoardNode => ({ ...structuredClone(node), x: node.x + offset.x, y: node.y + offset.y,
    parentColumnId: node.parentColumnId && movingIds.has(node.parentColumnId) ? node.parentColumnId : undefined,
    groupId: node.groupId && movingIds.has(node.groupId) ? node.groupId : undefined,
    columnOrder: node.parentColumnId && movingIds.has(node.parentColumnId) ? node.columnOrder : undefined,
    width: node.parentColumnId && !movingIds.has(node.parentColumnId) ? node.freeWidth || node.width : node.width,
    height: node.parentColumnId && !movingIds.has(node.parentColumnId) ? node.freeHeight || node.height : node.height,
  }))
  return { project: { ...project, boards: project.boards.map((board) => {
    const owned = childBoards.has(board.id) ? { ...board, parentBoardId: destinationBoardId } : board
    if (board.id === sourceBoardId) return { ...owned, nodes: board.nodes.filter((node) => !movingIds.has(node.id)), connectors: board.connectors.filter((connector) => !affected.includes(connector)) }
    if (board.id === destinationBoardId) return { ...owned, nodes: [...board.nodes, ...transferred], connectors: [...board.connectors, ...internal.map((connector) => ({ ...structuredClone(connector),
      ...(connector.sourcePoint ? { sourcePoint: { x: connector.sourcePoint.x + offset.x, y: connector.sourcePoint.y + offset.y } } : {}),
      ...(connector.targetPoint ? { targetPoint: { x: connector.targetPoint.x + offset.x, y: connector.targetPoint.y + offset.y } } : {}),
    }))] }
    return owned
  }) }, movedNodeIds: moving.map((node) => node.id), detachedConnectorIds: affected.filter((connector) => !internalIds.has(connector.id)).map((connector) => connector.id) }
}

import type { BoardConnector, BoardNode, BoardPoint, ProjectModel } from '../model/project'
import { containerDescendantIds, diagramProjectionStates, mindMapBranchIds, type StructureResult } from './diagramStructureCore'
import { validateBoardMutation } from './boardMutationSafety'
import { canReparentBoard } from './boardHierarchy'
import { connectorGeometry } from './connectors'
import { layoutBoardColumnsForNodesResult } from './columns'

type TransferResult = { project: ProjectModel; movedIds: string[]; transportedConnectorIds: string[]; detachedConnectorIds: string[] }
const fail = (detail: string): StructureResult<TransferResult> => ({ ok: false, issues: [{ code: 'unsafe-board-transfer', detail }] })

/** Atomic placement/ownership transaction; no filesystem operations.
 * Internal edges travel; boundary edges retain a visible detached source anchor. */
export function transferBoardSelection(project: ProjectModel, sourceId: string, destinationId: string, requestedIds: readonly string[], options: { readOnly?: boolean; position?: BoardPoint } = {}): StructureResult<TransferResult> {
  if (options.readOnly) return fail('This workspace is read-only.')
  if (sourceId === destinationId) return fail('Choose a different destination board.')
  const source = project.boards.find((board) => board.id === sourceId), destination = project.boards.find((board) => board.id === destinationId)
  if (!source || !destination || !requestedIds.length) return fail('Choose existing objects and a destination board.')
  const initial = containerDescendantIds(source.nodes, requestedIds)
  if (!initial.ok) return initial
  const branches = new Set(initial.value)
  for (const id of initial.value) {
    const node = source.nodes.find((entry) => entry.id === id)!
    if (!node.mindMap) continue
    const root = source.nodes.find((entry) => entry.mindMap?.treeId === node.mindMap!.treeId && !entry.mindMap.parentId)
    if (!root || !branches.has(root.id)) return fail('Move the mind-map root to move its complete tree; individual branches stay on their board.')
    const branch = mindMapBranchIds(source.nodes, root.id)
    if (!branch.ok) return branch
    branch.value.forEach((child) => branches.add(child))
  }
  const expanded = containerDescendantIds(source.nodes, [...branches])
  if (!expanded.ok) return expanded
  const moved = new Set(expanded.value), states = diagramProjectionStates(source.nodes)
  if (source.nodes.some(node => node.graphColumn?.inputs.some(input => moved.has(node.id) !== moved.has(input.sourceId)))) return fail('Move the connected graph and its sources together, or disconnect its inputs first. Graph data references stay on one board.')
  if (!states.ok) return states
  for (const id of moved) {
    const state = states.value.get(id)!
    if (state.locked || state.hidden) return fail('A selected object or owner is locked, hidden or collapsed; nothing was moved.')
  }
  for (const node of source.nodes.filter((entry) => moved.has(entry.id) && entry.mindMap)) if (source.nodes.some((entry) => entry.mindMap?.treeId === node.mindMap!.treeId && !moved.has(entry.id))) return fail('Move a complete mind-map tree; partial trees cannot cross boards.')
  const incoming = source.nodes.filter((entry) => moved.has(entry.id))
  if (incoming.some((node) => destination.nodes.some((entry) => entry.id === node.id))) return fail('The destination has a conflicting object identity; nothing was overwritten.')
  if (incoming.some((node) => node.mindMap && destination.nodes.some((entry) => entry.mindMap?.treeId === node.mindMap!.treeId))) return fail('The destination has a conflicting mind-map identity.')
  const parents = new Map<string, string>()
  for (const node of incoming) if (node.kind === 'board-link' && node.boardLinkRole === 'child') {
    const child = project.boards.find((board) => board.id === node.targetBoardId)
    if (!child || child.parentBoardId !== sourceId) return fail('The owning portal does not match its board parent; repair that identity before moving it.')
    const owners = project.boards.flatMap((board) => board.nodes).filter((entry) => entry.kind === 'board-link' && entry.boardLinkRole === 'child' && entry.targetBoardId === child.id)
    if (owners.length !== 1 || !canReparentBoard(project.boards, child.id, destinationId)) return fail('This destination would duplicate ownership or create a board cycle.')
    parents.set(child.id, destinationId)
  }
  const left = Math.min(...incoming.map((node) => node.x)), top = Math.min(...incoming.map((node) => node.y))
  const delta = options.position ? { x: options.position.x - left, y: options.position.y - top } : { x: 0, y: 0 }
  if (!Number.isFinite(delta.x) || !Number.isFinite(delta.y)) return fail('The destination position must be finite.')
  const translate = (point: BoardPoint) => ({ ...point, x: point.x + delta.x, y: point.y + delta.y })
  const nodes = incoming.map((node) => {
    const next: BoardNode = { ...node, x: node.x + delta.x, y: node.y + delta.y }
    if (node.groupId && !moved.has(node.groupId)) delete next.groupId
    if (node.parentColumnId && !moved.has(node.parentColumnId)) { delete next.parentColumnId; delete next.columnOrder; delete next.freeWidth; delete next.freeHeight }
    return next
  })
  const travelling: BoardConnector[] = [], remaining: BoardConnector[] = [], detached: string[] = []
  for (const edge of source.connectors) {
    const sourceMoved = Boolean(edge.sourceId && moved.has(edge.sourceId)), targetMoved = Boolean(edge.targetId && moved.has(edge.targetId))
    const sourceFree = !edge.sourceId && Boolean(edge.sourcePoint), targetFree = !edge.targetId && Boolean(edge.targetPoint)
    if ((sourceMoved && targetMoved) || (sourceMoved && targetFree) || (targetMoved && sourceFree)) travelling.push({ ...edge, ...(edge.bendPoints ? { bendPoints: edge.bendPoints.map(translate) } : {}), ...(edge.sourcePoint ? { sourcePoint: translate(edge.sourcePoint) } : {}), ...(edge.targetPoint ? { targetPoint: translate(edge.targetPoint) } : {}) })
    else if (sourceMoved || targetMoved) {
      const geometry = connectorGeometry(edge, source.nodes)
      if (!geometry) return fail('A boundary connection could not be resolved; nothing was moved.')
      remaining.push({ ...edge, ...(sourceMoved ? { sourceId: undefined, sourcePoint: { ...geometry.source } } : {}), ...(targetMoved ? { targetId: undefined, targetPoint: { ...geometry.target } } : {}) })
      detached.push(edge.id)
    } else remaining.push(edge)
  }
  if (travelling.some((edge) => destination.connectors.some((entry) => entry.id === edge.id))) return fail('The destination has a conflicting connection identity; nothing was overwritten.')
  const sourceColumns = [...new Set(incoming.flatMap((node) => node.parentColumnId && !moved.has(node.parentColumnId) ? [node.parentColumnId] : []))]
  // Newly detached boundary anchors describe where the removed objects were.
  // They stay in world space while remaining rows tighten their source column.
  const detachedIds = new Set(detached)
  const sourceLayout = layoutBoardColumnsForNodesResult({ ...source, nodes: source.nodes.filter((node) => !moved.has(node.id)), connectors: remaining.filter((edge) => !detachedIds.has(edge.id)) }, sourceColumns)
  if (!sourceLayout.ok) return sourceLayout
  const laidOutEdges = new Map(sourceLayout.value.connectors.map((edge) => [edge.id, edge]))
  const nextSource = { ...sourceLayout.value, connectors: remaining.map((edge) => laidOutEdges.get(edge.id) || edge) }
  const nextDestination = { ...destination, nodes: [...destination.nodes, ...nodes], connectors: [...destination.connectors, ...travelling] }
  for (const [before, after] of [[source, nextSource], [destination, nextDestination]]) { const checked = validateBoardMutation(before, after); if (!checked.ok) return checked }
  const boards = project.boards.map((board) => { const updated = board.id === sourceId ? nextSource : board.id === destinationId ? nextDestination : board; return parents.has(board.id) ? { ...updated, parentBoardId: parents.get(board.id)! } : updated })
  return { ok: true, value: { project: { ...project, boards }, movedIds: incoming.map((node) => node.id), transportedConnectorIds: travelling.map((edge) => edge.id), detachedConnectorIds: detached } }
}

import type { BoardConnector, BoardModel, BoardNode } from '../model/project'
import { vectorNodeMatrix } from '../model/vector'
import { boardNodeVisualBounds, type ArrangementBounds } from './arrangement'
import { connectorGeometry, connectorLabelPoint } from './connectors'
import { projectGraphColumns } from './graphColumnV2'
import { containerDescendantIds, containerPaintOrder, diagramProjectionStates, validateMindMapConnectors, type StructureResult } from './diagramStructureCore'

export type BoardVisualExportTarget = 'full' | 'viewport' | 'selection' | 'frame'
export type BoardVisualExportOptions = {
  target: BoardVisualExportTarget
  selectedIds?: readonly string[]
  viewportSize: { width: number; height: number }
}
export type BoardVisualExport = {
  target: BoardVisualExportTarget
  nodes: BoardNode[]
  connectors: BoardConnector[]
  bounds: { left: number; top: number; width: number; height: number }
  frameId?: string
}
const fail = (code: string, detail: string, nodeId?: string): StructureResult<BoardVisualExport> => ({ ok: false, issues: [{ code, detail, ...(nodeId ? { nodeId } : {}) }] })
const finitePoint = (point: { x: number; y: number }) => point && Number.isFinite(point.x) && Number.isFinite(point.y)
const frameNode = (node: BoardNode) => node.kind === 'group' && (node.containerRole === 'frame' || /\bframe\b/i.test(node.title))
const expand = (bounds: ArrangementBounds, amount: number): ArrangementBounds => ({ left: bounds.left - amount, top: bounds.top - amount, right: bounds.right + amount, bottom: bounds.bottom + amount })
const union = (bounds: readonly ArrangementBounds[]): ArrangementBounds => ({
  left: Math.min(...bounds.map((box) => box.left)), top: Math.min(...bounds.map((box) => box.top)),
  right: Math.max(...bounds.map((box) => box.right)), bottom: Math.max(...bounds.map((box) => box.bottom)),
})

/** Conservative bounds match the existing SVG serializer. Cubic control hulls
 * contain the entire route without sampling error. Default SVG marker units
 * scale the 8x8 arrow by stroke width; radius 9 also covers the refX offset.
 * Labels use 12px Inter/sans-serif at a baseline: 24px per UTF-16 unit, 24px
 * ascent and 12px descent allow generous fallback glyph metrics, plus 2px.
 * These are artifact bounds, not measured text/hit-test bounds. */
export function connectorVisualExportBounds(connector: BoardConnector, nodes: readonly BoardNode[]): ArrangementBounds | null {
  const geometry = connectorGeometry(connector, nodes)
  if (!geometry) return null
  const points = geometry.commands.flatMap((command) => {
    const result: { x: number; y: number }[] = []
    for (let index = 1; index < command.length; index += 2) result.push({ x: command[index] as number, y: command[index + 1] as number })
    return result
  })
  if (!points.length || points.some((point) => !finitePoint(point))) return null
  const width = Number.isFinite(connector.width) ? Math.max(.1, connector.width) : 2
  const margin = Math.max(width * 2, connector.startArrow || connector.endArrow ? width * 9 : 0)
  const route = expand({ left: Math.min(...points.map((point) => point.x)), top: Math.min(...points.map((point) => point.y)), right: Math.max(...points.map((point) => point.x)), bottom: Math.max(...points.map((point) => point.y)) }, margin)
  if (!connector.label?.trim()) return route
  const point = connectorLabelPoint(connector, geometry)
  if (!finitePoint(point)) return null
  const halfWidth = connector.label.length * 12 + 2
  return union([route, { left: point.x - halfWidth, right: point.x + halfWidth, top: point.y - 26, bottom: point.y + 14 }])
}

/** Canonical export projection only: no rasterizer, source embedding, mutation,
 * workspace write or new format. Validate complete ownership/tree/edge graphs
 * before choosing a region, including hidden records. Hidden/collapsed branches
 * never appear in artifacts. Lock state does not hide otherwise visible art.
 *
 * Selection/frame includes transitive container membership and only edges
 * whose attachments are all in the region, including tethered free endpoints.
 * Wholly detached routes are retained for full/viewport only. Frames remain
 * non-clipping world-space regions; bounds union visible members and routes.
 * Viewport is an explicit camera crop, so offscreen artwork is intentionally
 * clipped; full/selection/frame extend to complete supported artwork bounds. */
export function prepareBoardVisualExport(board: BoardModel, options: BoardVisualExportOptions): StructureResult<BoardVisualExport> {
  const { target, viewportSize } = options
  if (!['full', 'viewport', 'selection', 'frame'].includes(target)) return fail('invalid-export-target', 'Choose an existing board export target.')
  if (![viewportSize.width, viewportSize.height].every((value) => Number.isFinite(value) && value > 0) || ![board.viewport.x, board.viewport.y, board.viewport.scale].every(Number.isFinite) || board.viewport.scale <= 0) return fail('invalid-export-viewport', 'The export camera and viewport dimensions must be finite and positive.')
  const states = diagramProjectionStates(board.nodes)
  if (!states.ok) return states
  const paint = containerPaintOrder(board.nodes)
  if (!paint.ok) return paint
  const byId = new Map(board.nodes.map((node) => [node.id, node]))
  for (const node of board.nodes) {
    if (![node.x, node.y, node.width, node.height, node.rotation ?? 0].every(Number.isFinite) || node.width <= 0 || node.height <= 0) return fail('invalid-export-geometry', 'Object geometry must be finite with positive dimensions.', node.id)
    if (node.strokeWidth !== undefined && (!Number.isFinite(node.strokeWidth) || node.strokeWidth < 0)) return fail('invalid-export-stroke', 'Object strokes must be finite and nonnegative.', node.id)
  }
  const edgeIds = new Set<string>()
  for (const edge of board.connectors) {
    if (!edge.id || edgeIds.has(edge.id)) return fail('duplicate-export-connector', 'Connection identities must be nonempty and unique.')
    edgeIds.add(edge.id)
    if ((edge.sourceId && !byId.has(edge.sourceId)) || (edge.targetId && !byId.has(edge.targetId))) return fail('missing-export-endpoint', `Connection ${edge.id} references a missing object.`)
    if ((!edge.sourceId && !edge.sourcePoint) || (!edge.targetId && !edge.targetPoint)) return fail('missing-export-anchor', `Connection ${edge.id} needs both attached or free endpoints.`)
    if ([...(edge.bendPoints || []), ...(edge.sourcePoint ? [edge.sourcePoint] : []), ...(edge.targetPoint ? [edge.targetPoint] : [])].some((point) => !finitePoint(point))) return fail('invalid-export-route', `Connection ${edge.id} has a non-finite route.`)
    if (edge.labelPosition && ![edge.labelPosition.t, edge.labelPosition.offsetX, edge.labelPosition.offsetY].every(Number.isFinite)) return fail('invalid-export-label', `Connection ${edge.id} has a non-finite label position.`)
  }
  const treeIds = new Set([...board.nodes.flatMap((node) => node.mindMap ? [node.mindMap.treeId] : []), ...board.connectors.flatMap((edge) => edge.mindMap ? [edge.mindMap.treeId] : [])])
  for (const id of treeIds) {
    const valid = validateMindMapConnectors(board.nodes, board.connectors, id)
    if (!valid.ok) return valid
  }
  let region: Set<string> | undefined, frameId: string | undefined
  if (target === 'selection' || target === 'frame') {
    const ids = options.selectedIds || []
    let roots = ids
    if (target === 'frame') {
      // Match the existing selected-frame, first-frame, selected-container rule.
      const frame = board.nodes.find((node) => ids.includes(node.id) && frameNode(node))
        || board.nodes.find(frameNode)
        || board.nodes.find((node) => ids.includes(node.id) && (node.kind === 'group' || node.kind === 'column'))
      if (!frame) return fail('missing-export-frame', 'Create or select a frame before exporting a frame.')
      roots = [frame.id]; frameId = frame.id
    }
    if (!roots.length) return fail('empty-export-selection', 'Select at least one card to export.')
    const descendants = containerDescendantIds(board.nodes, roots)
    if (!descendants.ok) return descendants
    region = new Set(descendants.value)
  }
  const nodes = paint.value.orderedIds.map((id) => byId.get(id)!).filter((node) => !states.value.get(node.id)!.hidden && (!region || region.has(node.id)))
  if (region && !nodes.length) return fail('hidden-export-region', 'The chosen region has no visible objects to export.')
  const maskedRectangle = nodes.find(node => node.kind === 'shape' && node.shapeType === 'rectangle' && node.vectorBoolean)
  if (maskedRectangle) return fail('rectangle-appearance-export-pending', 'This rectangle has editable erasure cuts. Visual export and image/SVG copy need its complete inset border, shadow and caption appearance; no incomplete artifact was produced.', maskedRectangle.id)
  const exportedIds = new Set(nodes.map((node) => node.id))
  const connectors = [...board.connectors, ...projectGraphColumns(board).connections].filter((edge) => {
    const attachments = [edge.sourceId, edge.targetId].filter((id): id is string => Boolean(id))
    if (attachments.some((id) => states.value.get(id)!.hidden)) return false
    return !region || (attachments.length > 0 && attachments.every((id) => exportedIds.has(id)))
  })
  const camera = { left: -board.viewport.x / board.viewport.scale, top: -board.viewport.y / board.viewport.scale, width: viewportSize.width / board.viewport.scale, height: viewportSize.height / board.viewport.scale }
  if (target === 'viewport') return { ok: true, value: { target, nodes, connectors, bounds: camera } }
  const boundedFrame = frameId ? byId.get(frameId) : undefined
  if (target === 'frame' && boundedFrame?.boundedCanvas) return { ok: true, value: { target, nodes, connectors, frameId, bounds: { left: boundedFrame.x, top: boundedFrame.y, width: boundedFrame.width, height: boundedFrame.height } } }
  const boxes: ArrangementBounds[] = []
  for (const node of nodes) {
    const box = boardNodeVisualBounds(node), stroke = node.strokeWidth ?? (node.kind === 'shape' ? 2 : 1)
    // Path geometry includes half-stroke already; this extra margin also covers
    // miter joins and a scaled/skewed inner affine in vectorNodeSvgMarkup.
    const matrix = node.shapeType === 'path' && node.vectorPath ? vectorNodeMatrix(node) : undefined
    const factor = matrix ? Math.hypot(matrix.a, matrix.b, matrix.c, matrix.d) : 1
    const margin = node.shapeType === 'arrow' ? stroke * 9 : stroke * 2 * Math.max(1, factor)
    const padded = expand(box, margin)
    if (!Object.values(padded).every(Number.isFinite)) return fail('invalid-export-bounds', 'Artwork bounds must remain finite.', node.id)
    boxes.push(padded)
  }
  for (const edge of connectors) {
    const box = connectorVisualExportBounds(edge, board.nodes)
    if (!box || !Object.values(box).every(Number.isFinite)) return fail('invalid-export-bounds', `Connection ${edge.id} could not be bounded safely.`)
    boxes.push(box)
  }
  const padding = target === 'frame' ? 0 : target === 'selection' ? 24 : 42
  const box = boxes.length ? expand(union(boxes), padding) : { left: 0, top: 0, right: camera.width, bottom: camera.height }
  const bounds = { left: box.left, top: box.top, width: Math.max(1, box.right - box.left), height: Math.max(1, box.bottom - box.top) }
  if (!Object.values(bounds).every(Number.isFinite)) return fail('invalid-export-bounds', 'The export bounds exceed finite board coordinates.')
  return { ok: true, value: { target, nodes, connectors, bounds, ...(frameId ? { frameId } : {}) } }
}

import type { BoardModel, BoardNode } from '../model/project'
import { boardNodeVisualBounds } from './arrangement'

export const isBoundedFrame = (node: BoardNode) => node.kind === 'group' && Boolean(node.boundedCanvas)
export const drawingOnly = (node: BoardNode) => node.kind === 'shape' || node.kind === 'text'

/** Explicit bounded frames only. Historical groups/frames retain authored geometry. */
export function containFrameEdit(previous: BoardModel, next: BoardModel): { ok: true; board: BoardModel } | { ok: false; message: string } {
  const frames = next.nodes.filter(isBoundedFrame)
  if (!frames.length) return { ok: true, board: next }
  const old = new Map(previous.nodes.map(node => [node.id, node]))
  let changed = false
  const nodes = next.nodes.map(node => {
    if (isBoundedFrame(node)) return node
    const before = old.get(node.id)
    let owner = frames.find(frame => frame.id === node.groupId || frame.id === before?.groupId)
    // A new object or a moved free object enters a frame; existing unrelated
    // records never acquire membership just because another control was used.
    if (!owner && !node.groupId && !node.parentColumnId && node.kind !== 'group' && node.kind !== 'column'
      && (!before || before.x !== node.x || before.y !== node.y)) {
      const box = boardNodeVisualBounds(node)
      owner = [...frames].reverse().find(frame => (!before ? box.right >= frame.x && box.bottom >= frame.y && box.left <= frame.x + frame.width && box.top <= frame.y + frame.height : box.left >= frame.x && box.top >= frame.y && box.right <= frame.x + frame.width && box.bottom <= frame.y + frame.height))
    }
    if (!owner) return node
    if (owner.boundedCanvas === 'drawing' && !drawingOnly(node)) throw new Error('Drawing Canvas accepts drawing shapes and text only. Place media on the surrounding board.')
    const box = boardNodeVisualBounds(node)
    const pad = node.shapeType === 'path' ? 0 : Math.max(0, node.strokeWidth ?? (node.kind === 'shape' ? 2 : 0)) / 2
    const width = box.right - box.left + 2 * pad, height = box.bottom - box.top + 2 * pad
    if (width > owner.width || height > owner.height) throw new Error('This object does not fit inside its frame. Enlarge the frame first; the edit was cancelled.')
    const dx = Math.max(owner.x + pad - box.left, Math.min(0, owner.x + owner.width - pad - box.right))
    const dy = Math.max(owner.y + pad - box.top, Math.min(0, owner.y + owner.height - pad - box.bottom))
    if (dx || dy || node.groupId !== owner.id) { changed = true; return { ...node, groupId: owner.id, x: node.x + dx, y: node.y + dy } }
    return node
  })
  // Rotating a container would separate its world-space members. Members may
  // rotate independently; their actual transformed visual envelope is bounded.
  if (frames.some(frame => Boolean(frame.rotation))) return { ok: false, message: 'Frames stay aligned with the board. Rotate the artwork inside the frame instead.' }
  return { ok: true, board: changed ? { ...next, nodes } : next }
}

export function safeFrameEdit(previous: BoardModel, next: BoardModel) {
  try { return containFrameEdit(previous, next) }
  catch (error) { return { ok: false as const, message: String(error instanceof Error ? error.message : error) } }
}

import paper from 'paper'
import type { BoardNode, BoardPoint } from '../model/project'
import type { CanvasPreparedVectorGeometry, CanvasVectorCommand } from '../canvas-engine/contracts'
import { prepareVelloVectorGeometry } from './velloVectorGeometry'
import { isRectangleErasure } from '../model/rectangleErasure'
import { prepareRectangleErasurePick } from './rectangleErasurePaint'

type ReadyGeometry = Extract<CanvasPreparedVectorGeometry, { status: 'ready' }>
export type CanonicalVectorPickOptions = Readonly<{
  zoomScale?: number
  strokeWidth?: number
  /** Closed semantic SVG hit proxies include their interior even with transparent paint. */
  includeFill?: boolean
  /** Optional explicit UI proximity radius; measured in CSS pixels after all transforms. */
  hitRadiusCssPx?: number
}>

const finitePoint = (point: BoardPoint) => Number.isFinite(point.x) && Number.isFinite(point.y)
const coordinatesFinite = (command: CanvasVectorCommand) => command.slice(1).every(Number.isFinite)

/** Geometry-only semantic picking. It consumes the same immutable prepared
 * world commands as Vello, never local sampling, paint bounds as geometry,
 * editable copies or display pixels. Paper's private 1px view has updates
 * disabled; picking only calls geometry methods, with no draw or readback.
 * The default stroke policy
 * is nearest-curve proximity matching the SVG proxy's half width (round tube);
 * this does not promise exact SVG butt/square-cap or miter-join pixel coverage.
 * Own one picker per canvas/document host and dispose it with that host. */
export function createCanonicalVectorPicker() {
  let scope: paper.PaperScope | undefined
  let project: paper.Project | undefined
  let cache = new WeakMap<ReadyGeometry, paper.PathItem | null>()
  let disposed = false
  const releaseScope = () => {
    const ownedScope = scope
    scope = undefined; project = undefined
    if (!ownedScope) return
    // Also cover a Project constructor that registered itself before failing.
    // This scope is private to the picker; no production Paper project is removed.
    try {
      for (const ownedProject of [...ownedScope.projects]) {
        try { ownedProject.remove() }
        catch {
          // A faulty project remover must not prevent its view and scope from
          // being retired. projects is Paper's public per-scope membership list.
          try { ownedProject.view?.remove() } catch { /* continue scope cleanup */ }
          const index = ownedScope.projects.indexOf(ownedProject)
          if (index >= 0) ownedScope.projects.splice(index, 1)
        }
      }
    } finally {
      // Paper0.12.18 implements this public method but omits it from its d.ts.
      ;(ownedScope as paper.PaperScope & { remove(): void }).remove()
    }
  }

  const compile = (geometry: ReadyGeometry): paper.PathItem | null => {
    if (disposed) return null
    if (cache.has(geometry)) return cache.get(geometry) ?? null
    const immutable = Object.isFrozen(geometry) && Object.isFrozen(geometry.commands)
      && Object.isFrozen(geometry.bounds) && geometry.commands.every(Object.isFrozen)
    try {
      if (!scope) {
        scope = new paper.PaperScope()
        project = new scope.Project(undefined!)
        if (project.view) { project.view.autoUpdate = false; project.view.pause() }
      }
      scope.activate()
    } catch {
      // The private Paper1px view can fail to initialize. Picking must fail
      // closed without retaining a partially initialized global scope/project.
      releaseScope()
      return null
    }
    let compound: paper.CompoundPath | undefined
    let current: paper.Path | undefined
    try {
      compound = new scope.CompoundPath({ insert: false, fillRule: geometry.fillRule })
      for (const command of geometry.commands) {
        if (!coordinatesFinite(command)) throw new Error('Nonfinite prepared command')
        if (command[0] === 'M' && command.length === 3) {
          current = new scope.Path({ insert: false })
          compound.addChild(current)
          current.moveTo(new scope.Point(command[1], command[2]))
        } else if (command[0] === 'L' && command.length === 3 && current) {
          current.lineTo(new scope.Point(command[1], command[2]))
        } else if (command[0] === 'C' && command.length === 7 && current) {
          current.cubicCurveTo(new scope.Point(command[1], command[2]),
            new scope.Point(command[3], command[4]), new scope.Point(command[5], command[6]))
        } else if (command[0] === 'Z' && command.length === 1 && current) {
          current.closePath()
          current = undefined
        } else throw new Error('Malformed prepared command sequence')
      }
      if (immutable) cache.set(geometry, compound)
      return compound
    } catch {
      compound?.remove()
      if (immutable) cache.set(geometry, null)
      return null
    }
  }

  const hit = (geometry: CanvasPreparedVectorGeometry, point: BoardPoint, options: CanonicalVectorPickOptions = {}) => {
    if (disposed || geometry.status !== 'ready' || !geometry.bounds || !geometry.commands.length || !finitePoint(point)) return false
    const zoom = options.zoomScale ?? 1, strokeWidth = options.strokeWidth ?? 2
    const cssRadius = options.hitRadiusCssPx ?? geometry.hitOutsetCssPx ?? Math.max(8, strokeWidth * 2)
    if (!Number.isFinite(zoom) || zoom <= 0 || !Number.isFinite(strokeWidth) || strokeWidth < 0
      || !Number.isFinite(cssRadius) || cssRadius < 0) return false
    if (geometry.approximation && (zoom < geometry.approximation.minCssScale || zoom > geometry.approximation.maxCssScale)) return false
    const radius = cssRadius / zoom, { x, y, width, height } = geometry.bounds
    if (![radius, x, y, width, height, x + width, y + height].every(Number.isFinite) || width < 0 || height < 0) return false
    if (geometry.primitive === 'plain-line') {
      // Match the semantic SVG line's butt-capped rectangular stroke, rather
      // than Paper's rounded nearest-curve tube. Coincident endpoints have no
      // proxy area; zero painted width still retains the separate hit stroke.
      const [a, b] = geometry.commands
      if (geometry.commands.length !== 2 || a?.[0] !== 'M' || a.length !== 3 || b?.[0] !== 'L' || b.length !== 3
        || !coordinatesFinite(a) || !coordinatesFinite(b)) return false
      const hitRadius = (options.hitRadiusCssPx ?? geometry.hitOutsetCssPx ?? cssRadius) / zoom
      if (!Number.isFinite(hitRadius) || hitRadius < 0) return false
      const dx = b[1] - a[1], dy = b[2] - a[2], lengthSquared = dx * dx + dy * dy
      if (!Number.isFinite(lengthSquared) || lengthSquared <= 0) return false
      const t = ((point.x - a[1]) * dx + (point.y - a[2]) * dy) / lengthSquared
      if (!Number.isFinite(t) || t < 0 || t > 1) return false
      const distance = Math.abs((point.x - a[1]) * dy - (point.y - a[2]) * dx) / Math.sqrt(lengthSquared)
      return Number.isFinite(distance) && distance <= hitRadius
    }
    if (point.x < x - radius || point.x > x + width + radius || point.y < y - radius || point.y > y + height + radius) return false
    const item = compile(geometry)
    if (!item || !scope) return false
    try {
      const query = new scope.Point(point.x, point.y)
      if ((options.includeFill ?? geometry.hasFill) && geometry.hasFill && item.contains(query)) return true
      const nearest = item.getNearestLocation(query)
      return Boolean(nearest && Number.isFinite(nearest.distance) && nearest.distance <= radius)
    } catch { return false }
    finally {
      // Mutable hand-authored input is never retained. Prepared model geometry
      // is deeply frozen and cached weakly; detached paths do not populate a project.
      if (!cache.has(geometry)) item.remove()
    }
  }

  return {
    hit,
    /** Unsupported paint derivatives retain the caller's prior DOM fallback. */
    nodeStatus(node: BoardNode, geometry?: CanvasPreparedVectorGeometry): CanvasPreparedVectorGeometry['status'] {
      if (disposed || node.hidden || node.kind !== 'shape') return 'invalid'
      if (isRectangleErasure(node)) return prepareRectangleErasurePick(node).status
      return (geometry ?? prepareVelloVectorGeometry(node.diagramShape ? { ...node, diagramShape: undefined } : node)).status
    },
    /** Optional prepared argument lets App's indexed candidate reuse the exact
     * accepted/live scene derivative without recompiling Boolean geometry. */
    hitNode(node: BoardNode, point: BoardPoint, zoomScale = 1, geometry?: CanvasPreparedVectorGeometry) {
      if (!disposed && !node.hidden && node.kind === 'shape' && isRectangleErasure(node)) {
        return hit(prepareRectangleErasurePick(node), point, { zoomScale, includeFill: true, hitRadiusCssPx: 0 })
      }
      if (disposed || node.hidden || node.kind !== 'shape'
        || (node.shapeType !== 'ellipse' && node.shapeType !== 'line' && (node.shapeType !== 'path' || !node.vectorPath))) return false
      // Caption metadata excludes paint takeover, not this authored SVG path's
      // semantic geometry. App renders the same VectorPathShape for this case.
      const prepared = geometry?.status === 'unsupported' && geometry.reason === 'diagram-caption' || !geometry
        ? prepareVelloVectorGeometry(node.diagramShape ? { ...node, diagramShape: undefined } : node) : geometry
      return hit(prepared, point, { zoomScale, strokeWidth: node.strokeWidth ?? 2 })
    },
    dispose() {
      if (disposed) return
      disposed = true
      cache = new WeakMap()
      releaseScope()
    },
  }
}

import { useEffect } from 'react'
import { observeCanvasPerformance } from './canvasPerformance'
import type { CSSProperties, MouseEvent, PointerEvent } from 'react'
import type { BoardModel, BoardNode, ShapeType } from '../model/project'
import { vectorEditorControls } from '../model/vectorEditing'

export type ResizeHandle = 'nw' | 'n' | 'ne' | 'e' | 'se' | 's' | 'sw' | 'w'
export const RESIZE_HANDLES: ResizeHandle[] = ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w']
export type LiveShapeAnchor = 'nw' | 'ne' | 'se' | 'sw' | 'n' | 'e' | 's' | 'w'

export function isLiveShapeDirectSelectable(node: BoardNode) {
  return node.kind === 'shape' && (node.shapeType === 'rectangle' || node.shapeType === 'ellipse') && !node.vectorPath
}

export function liveShapeAnchors(shapeType: ShapeType | undefined): LiveShapeAnchor[] {
  return shapeType === 'ellipse' ? ['n', 'e', 's', 'w'] : ['nw', 'ne', 'se', 'sw']
}

export type CanvasInteractionOverlayProps = {
  board: BoardModel
  selectedIds: readonly string[]
  selectedNode?: BoardNode
  visibleNodes: readonly BoardNode[]
  interactionTool: string
  directPolicy: { nodeId?: string }
  selectedVectorAnchorIndexes: readonly number[]
  marqueePreviewAnchors: readonly number[]
  rotationReadout: number | null
  cornerRadiusReadout: number | null
  viewOnly: boolean
  fisheyeScale: (node: BoardNode) => number
  nodeTitle: (node: BoardNode) => string
  stageRef: React.RefObject<HTMLDivElement | null>
  startNodeDrag: (event: PointerEvent, node: BoardNode) => void
  startNodeResize: (event: PointerEvent<HTMLButtonElement> | MouseEvent<HTMLButtonElement>, node: BoardNode, handle: ResizeHandle) => void
  startNodeRotate: (event: PointerEvent<HTMLButtonElement> | MouseEvent<HTMLButtonElement>, node: BoardNode) => void
  startNodeRadius: (event: PointerEvent<HTMLButtonElement> | MouseEvent<HTMLButtonElement>, node: BoardNode) => void
  startLiveShapeAnchorDrag: (event: PointerEvent<HTMLButtonElement>, node: BoardNode, anchor: LiveShapeAnchor) => void
  startVectorControlDrag: (event: PointerEvent<HTMLButtonElement>, node: BoardNode, index: number, part: 'anchor' | 'in' | 'out') => void
  addCurveHandles: (node: BoardNode, index: number) => void
  setSelectedVectorPoint: (point: { nodeId: string; index: number } | null) => void
  setSelectedVectorAnchorIndexes: (indexes: number[] | ((current: number[]) => number[])) => void
  toggleColumn: (column: BoardNode) => void
}

/**
 * Screen-Space Transient Interaction Overlay
 * Centralizes all selection bounding boxes, Bézier anchor/tangent handles,
 * live shape direct-select controls, and column controls in a dedicated
 * interaction layer positioned above the canvas stage.
 */
export function CanvasInteractionOverlay({
  board,
  selectedIds,
  selectedNode,
  visibleNodes,
  interactionTool,
  directPolicy,
  selectedVectorAnchorIndexes,
  marqueePreviewAnchors,
  rotationReadout,
  cornerRadiusReadout,
  viewOnly,
  fisheyeScale,
  nodeTitle,
  stageRef,
  startNodeDrag,
  startNodeResize,
  startNodeRotate,
  startNodeRadius,
  startLiveShapeAnchorDrag,
  startVectorControlDrag,
  addCurveHandles,
  setSelectedVectorPoint,
  setSelectedVectorAnchorIndexes,
  toggleColumn,
}: CanvasInteractionOverlayProps) {
  useEffect(() => stageRef.current ? observeCanvasPerformance(stageRef.current) : undefined, [stageRef, board.id])
  return (
    <div className="canvas-interaction-overlay" data-canvas-paint-chrome="interaction" style={{ pointerEvents: 'none', position: 'absolute', inset: 0, zIndex: 10 }}>
      {/* 1. Transform Bounding Box & Resize/Rotate/Radius Handles */}
      {!viewOnly && interactionTool !== 'node' && selectedIds.length === 1 && selectedNode && visibleNodes.some((node) => node.id === selectedNode.id) && !selectedNode.parentColumnId && !(selectedNode.kind === 'board-link' && selectedNode.boardPortal) && (() => {
        const node = selectedNode
        return (
          <div
            className="node-transform-box"
            data-transform-controls={node.id}
            onPointerDown={(event) => { if (event.target === event.currentTarget) startNodeDrag(event, node) }}
            style={{
              // The frame must not cover card editors, media, or other live
              // controls. Its handles opt into hit testing individually.
              pointerEvents: 'none',
              left: node.x,
              top: node.y,
              right: 'auto',
              bottom: 'auto',
              width: node.width,
              height: node.height,
              zIndex: 10,
              transform: `rotate(${node.rotation || 0}deg) scale(${fisheyeScale(node)})`,
              transformOrigin: 'center center',
              '--handle-size': `${12 / board.viewport.scale}px`,
              '--handle-offset': `${7 / board.viewport.scale}px`,
              '--rotate-gap': `${29 / board.viewport.scale}px`,
            } as CSSProperties}
          >
            {RESIZE_HANDLES.map((handle) => (
              <button
                className={`node-resize-handle handle-${handle}`}
                type="button"
                key={handle}
                aria-label={`Resize ${nodeTitle(node)} from ${handle}`}
                onPointerDown={(event) => startNodeResize(event, node, handle)}
                onMouseDown={(event) => {
                  if (!stageRef.current?.dataset.activeTransform) startNodeResize(event, node, handle)
                }}
              />
            ))}
            {node.kind === 'shape' && (node.shapeType || 'rectangle') === 'rectangle' && (
              <>
                <button
                  className="node-radius-handle"
                  type="button"
                  aria-label={`Adjust corner radius of ${nodeTitle(node)}`}
                  onPointerDown={(event) => startNodeRadius(event, node)}
                  onMouseDown={(event) => {
                    if (!stageRef.current?.dataset.activeTransform) startNodeRadius(event, node)
                  }}
                />
                {cornerRadiusReadout !== null && (
                  <output className="corner-radius-readout" aria-live="polite">
                    {cornerRadiusReadout}px
                  </output>
                )}
              </>
            )}
            <button
              className="node-rotate-handle"
              type="button"
              aria-label={`Rotate ${nodeTitle(node)}`}
              onPointerDown={(event) => startNodeRotate(event, node)}
              onMouseDown={(event) => {
                if (!stageRef.current?.dataset.activeTransform) startNodeRotate(event, node)
              }}
            />
            {rotationReadout !== null && (
              <output
                className="rotation-readout"
                aria-live="polite"
                style={{
                  fontSize: `${10 / board.viewport.scale}px`,
                  padding: `${4 / board.viewport.scale}px ${7 / board.viewport.scale}px`,
                }}
              >
                {rotationReadout}°
              </output>
            )}
          </div>
        )
      })()}

      {/* 2. Direct Selection Handles for Bézier Vector Curves */}
      {interactionTool === 'node' && directPolicy.nodeId && selectedNode && selectedNode.id === directPolicy.nodeId && selectedNode.vectorPath && (() => {
        const node = selectedNode
        const controls = vectorEditorControls(node)
        return (
          <div
            className="vector-node-editor"
            style={{
              pointerEvents: 'auto',
              position: 'absolute',
              left: node.x,
              top: node.y,
              width: node.width,
              height: node.height,
              transform: `rotate(${node.rotation || 0}deg) scale(${fisheyeScale(node)})`,
              transformOrigin: 'top left',
              zIndex: 11,
            }}
          >
            <svg className="vector-handle-lines" viewBox={`0 0 ${node.width} ${node.height}`} preserveAspectRatio="none" aria-hidden="true">
              {controls.flatMap(({ index, anchor, handleIn, handleOut }) => [
                handleIn && <line key={`in-${index}`} x1={anchor.x} y1={anchor.y} x2={handleIn.x} y2={handleIn.y} />,
                handleOut && <line key={`out-${index}`} x1={anchor.x} y1={anchor.y} x2={handleOut.x} y2={handleOut.y} />,
              ])}
            </svg>
            {controls.map(({ index, anchor, handleIn, handleOut }) => {
              const endpoint = !node.vectorPath!.closed && (index === 0 || index === controls.length - 1)
              return (
                <span key={index}>
                  <button
                    className={`vector-anchor ${selectedVectorAnchorIndexes.includes(index) ? 'selected' : ''} ${marqueePreviewAnchors.includes(index) ? 'marquee-preview' : ''} ${endpoint ? 'endpoint' : ''}`}
                    data-point-index={index}
                    type="button"
                    aria-label={`${endpoint ? 'Edit open endpoint' : 'Move anchor'} ${index + 1}`}
                    title={`${endpoint ? 'Open endpoint' : `Anchor ${index + 1}`}; double-click to ${handleIn || handleOut ? 'remove' : 'add'} Bézier handles`}
                    style={{ left: `${(anchor.x / node.width) * 100}%`, top: `${(anchor.y / node.height) * 100}%` }}
                    onPointerDown={(event) => startVectorControlDrag(event, node, index, 'anchor')}
                    onDoubleClick={(event) => {
                      event.preventDefault()
                      event.stopPropagation()
                      setSelectedVectorPoint({ nodeId: node.id, index })
                      setSelectedVectorAnchorIndexes([index])
                      addCurveHandles(node, index)
                    }}
                  />
                  {handleIn && (
                    <button
                      className="vector-handle in"
                      type="button"
                      aria-label={`Adjust incoming curve handle ${index + 1}`}
                      style={{ left: `${(handleIn.x / node.width) * 100}%`, top: `${(handleIn.y / node.height) * 100}%` }}
                      onPointerDown={(event) => startVectorControlDrag(event, node, index, 'in')}
                    />
                  )}
                  {handleOut && (
                    <button
                      className="vector-handle out"
                      type="button"
                      aria-label={`Adjust outgoing curve handle ${index + 1}`}
                      style={{ left: `${(handleOut.x / node.width) * 100}%`, top: `${(handleOut.y / node.height) * 100}%` }}
                      onPointerDown={(event) => startVectorControlDrag(event, node, index, 'out')}
                    />
                  )}
                </span>
              )
            })}
          </div>
        )
      })()}

      {/* 3. Live Shape Direct Selection Anchors (Rectangle / Ellipse) */}
      {interactionTool === 'node' && selectedIds.length === 1 && selectedNode && isLiveShapeDirectSelectable(selectedNode) && (
        <div
          className={`vector-node-editor live-shape-node-editor live-shape-direct-overlay ${selectedNode.shapeType || 'rectangle'}`}
          style={{
            pointerEvents: 'auto',
            position: 'absolute',
            left: selectedNode.x,
            top: selectedNode.y,
            width: selectedNode.width,
            height: selectedNode.height,
            transform: `rotate(${selectedNode.rotation || 0}deg) scale(${fisheyeScale(selectedNode)})`,
            transformOrigin: 'top left',
            zIndex: 11,
          }}
        >
          {liveShapeAnchors(selectedNode.shapeType).map((anchor) => (
            <button
              key={anchor}
              className={`vector-anchor live-shape-anchor anchor-${anchor}`}
              type="button"
              aria-label={`Resize ${selectedNode.shapeType} from ${anchor}`}
              title={`Drag ${anchor.toUpperCase()} anchor${selectedNode.shapeType === 'ellipse' ? '; Shift constrains to a circle' : ''}`}
              onPointerDown={(event) => startLiveShapeAnchorDrag(event, selectedNode, anchor)}
            />
          ))}
        </div>
      )}

      {/* 4. Column Header Collapse/Expand Overlay */}
      {!viewOnly && visibleNodes.filter((node) => node.kind === 'column').map((column) => (
        <div
          key={`column-controls-${column.id}`}
          data-column-controls={column.id}
          className="column-header-controls-overlay"
          style={{
            pointerEvents: 'auto',
            position: 'absolute',
            left: column.x + 9,
            top: column.y + 9,
            width: Math.max(48, column.width - 18),
            transform: `rotate(${column.rotation || 0}deg) scale(${fisheyeScale(column)})`,
            transformOrigin: 'top left',
            zIndex: 10,
          } as CSSProperties}
        >
          <button
            className="column-collapse-control"
            type="button"
            aria-label={column.collapsed ? `Expand ${column.title}` : `Collapse ${column.title}`}
            title={column.collapsed ? 'Expand column' : 'Collapse column'}
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation()
              toggleColumn(column)
            }}
          >
            {column.collapsed ? '＋' : '−'}
          </button>
        </div>
      ))}
    </div>
  )
}

import { requestAppFrame, cancelAppFrame } from '../canvas-engine/appFrameClock'
/** Local, bounded browser diagnostics. Frame intervals are not GPU execution timings. */
export function observeCanvasPerformance(stage: HTMLElement) {
  const frames: number[] = []
  const gestures: number[] = []
  let previous = 0
  let published = 0
  let request = 0
  let longTasks = 0
  let longestTask = 0
  const summarize = (samples: number[]) => {
    const sorted = [...samples].sort((a, b) => a - b)
    return { samples: sorted.length, medianMs: sorted.length ? +sorted[Math.floor(sorted.length / 2)].toFixed(2) : 0, p95Ms: sorted.length ? +sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * .95))].toFixed(2) : 0, over33Ms: sorted.filter((value) => value > 33.4).length }
  }
  const push = (samples: number[], value: number) => { samples.push(value); if (samples.length > 240) samples.shift() }
  const observer = typeof PerformanceObserver !== 'undefined' && PerformanceObserver.supportedEntryTypes.includes('longtask') ? new PerformanceObserver((entries) => {
    for (const entry of entries.getEntries()) { longTasks++; longestTask = Math.max(longestTask, entry.duration) }
  }) : null
  observer?.observe({ type: 'longtask', buffered: false })
  const tick = (now: number) => {
    if (document.visibilityState === 'visible') {
      if (previous) {
        push(frames, now - previous)
        if (stage.dataset.gesturePreview === 'true' || stage.dataset.activeTransform) push(gestures, now - previous)
      }
      if (now - published >= 1000) {
        stage.dataset.canvasPerformance = JSON.stringify({ boardFrames: summarize(frames), gestureFrames: summarize(gestures), longTasks, longestTaskMs: +longestTask.toFixed(2), nodes: Number(stage.dataset.totalNodes), renderer: stage.dataset.canvasRenderer, viewport: { width: stage.clientWidth, height: stage.clientHeight }, devicePixelRatio: window.devicePixelRatio })
        published = now
      }
      previous = now
    } else previous = 0
    request = requestAppFrame(tick)
  }
  request = requestAppFrame(tick)
  return () => { cancelAppFrame(request); observer?.disconnect(); delete stage.dataset.canvasPerformance }
}

