import { useEffect, useState } from 'react'
import type { CapturedContent } from '../model/project'
import { BoardRichText } from './BoardRichText'
import './CapturedContent.css'

type ClipTab = 'article' | 'comments' | 'transcript'

function plainText(html: string) {
  const container = document.createElement('div')
  container.innerHTML = html
  return container.textContent?.trim() || ''
}

function tabHtml(content: CapturedContent, tab: ClipTab) {
  return tab === 'article' ? content.articleHtml : tab === 'comments' ? content.commentsHtml : content.transcriptHtml
}

function countLabel(html: string) {
  const text = plainText(html)
  return text ? `${text.split(/\s+/).length} words` : 'empty'
}

export function CapturedContentCard({ content, mediaUrl, mediaKind, onChange, onEdit, onMine, onRequestText }: {
  content: CapturedContent
  mediaUrl?: string
  mediaKind?: 'image' | 'video'
  onChange: (content: CapturedContent) => void
  onEdit: () => void
  onMine?: () => void
  onRequestText: (options: { title: string; label: string; initialValue?: string }) => Promise<string | null>
}) {
  const [tab, setTab] = useState<ClipTab>('article')
  const html = tabHtml(content, tab)
  const updateHtml = (next: string) => onChange({ ...content, ...(tab === 'article' ? { articleHtml: next } : tab === 'comments' ? { commentsHtml: next } : { transcriptHtml: next }) })
  return <div className={`capture-card ${mediaUrl ? 'with-media' : ''}`} onPointerDown={(event) => event.stopPropagation()}>
    <div className="capture-source"><span title={content.sourceUrl || 'No source URL saved'}>{content.sourceLabel || 'Saved reference'}</span><strong title={content.author || 'No author saved'}>{content.author || 'Unknown author'}</strong>{onMine && <button type="button" title="Send this capture to the Eclipse DEV Miner as a text job" onClick={onMine}>Mine ⛏</button>}<button type="button" title="Edit source details and captured text" onClick={onEdit}>Edit capture</button></div>
    {mediaUrl && <div className="capture-media">{mediaKind === 'video' ? <video src={mediaUrl} controls preload="metadata" /> : <img src={mediaUrl} alt="Captured reference" draggable={false} />}</div>}
    <div className="capture-reading">
      <div className="capture-tabs" role="tablist" aria-label="Captured content sections">
        {(['article', 'comments', 'transcript'] as ClipTab[]).map((entry) => <button className={tab === entry ? 'active' : ''} type="button" title={`Show saved ${entry}`} role="tab" aria-selected={tab === entry} key={entry} onClick={() => setTab(entry)}><span>{entry}</span><small>{countLabel(tabHtml(content, entry))}</small></button>)}
      </div>
      <BoardRichText html={html || '<p></p>'} selected={false} onChange={updateHtml} onRequestText={onRequestText} />
    </div>
  </div>
}

export function CaptureEditorDialog({ initialValue, mediaLabel, onSave, onClose, onRequestText }: {
  initialValue: CapturedContent
  mediaLabel?: string
  onSave: (content: CapturedContent, title: string) => void
  onClose: () => void
  onRequestText: (options: { title: string; label: string; initialValue?: string }) => Promise<string | null>
}) {
  const [draft, setDraft] = useState(initialValue)
  const [title, setTitle] = useState(() => plainText(initialValue.articleHtml).slice(0, 80) || 'Saved reference')
  const [tab, setTab] = useState<ClipTab>('article')
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => event.key === 'Escape' && onClose()
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [onClose])
  const html = tabHtml(draft, tab)
  const updateHtml = (next: string) => setDraft((current) => ({ ...current, ...(tab === 'article' ? { articleHtml: next } : tab === 'comments' ? { commentsHtml: next } : { transcriptHtml: next }) }))
  return <div className="capture-dialog-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
    <section className="capture-dialog" role="dialog" aria-modal="true" aria-label="Save article or social post">
      <header><div><span>RESEARCH CAPTURE</span><strong>Preserve the reference, not just the screenshot.</strong></div><button type="button" aria-label="Close capture editor" onClick={onClose}>×</button></header>
      <div className="capture-fields">
        <label><span>Card title</span><input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Reference title" /></label>
        <label><span>Content type</span><select value={draft.kind} onChange={(event) => setDraft({ ...draft, kind: event.target.value as CapturedContent['kind'] })}><option value="social-post">Social post</option><option value="article">Article / blog</option><option value="transcript">Transcript</option><option value="script">Script</option><option value="local-document">Local document</option></select></label>
        <label><span>Source / platform</span><input value={draft.sourceLabel} onChange={(event) => setDraft({ ...draft, sourceLabel: event.target.value })} placeholder="Instagram, TikTok, Ars Technica…" /></label>
        <label><span>Author / account</span><input value={draft.author} onChange={(event) => setDraft({ ...draft, author: event.target.value })} placeholder="Author or account" /></label>
        <label className="capture-url"><span>Source URL</span><input value={draft.sourceUrl} onChange={(event) => setDraft({ ...draft, sourceUrl: event.target.value })} placeholder="https://…" /></label>
        <label><span>Published</span><input value={draft.publishedAt} onChange={(event) => setDraft({ ...draft, publishedAt: event.target.value })} placeholder="Date or original label" /></label>
        {mediaLabel && <p className="capture-attached">▧ Attached disk media: <strong>{mediaLabel}</strong></p>}
      </div>
      <div className="capture-composer-tabs" role="tablist">{(['article', 'comments', 'transcript'] as ClipTab[]).map((entry) => <button className={tab === entry ? 'active' : ''} type="button" role="tab" aria-selected={tab === entry} key={entry} onClick={() => setTab(entry)}><strong>{entry === 'article' ? 'Article / caption' : entry}</strong><small>{countLabel(tabHtml(draft, entry))}</small></button>)}</div>
      <div className="capture-composer"><BoardRichText html={html || '<p></p>'} selected onChange={updateHtml} onRequestText={onRequestText} variant="composer" /></div>
      <footer><p>Paste formatted text directly. Long captions, comments, scripts, and transcripts remain searchable and scroll inside the canvas card.</p><button type="button" onClick={onClose}>Cancel</button><button className="primary-button" type="button" onClick={() => onSave({ ...draft, capturedAt: draft.capturedAt || new Date().toISOString() }, title.trim() || 'Saved reference')}>Save capture</button></footer>
    </section>
  </div>
}

/**
 * Art Equation Canvas Engine - Typed Card Ports & Anchors
 *
 * Implements Rete/React-Flow style first-class connection handles:
 * - Typed sockets: reference, identity, evidence, continuity, branch, transform, video-range.
 * - Normalized side placement (left, right, top, bottom).
 * - Dynamic port creation and runtime validation before committing edges.
 * - Normalized coordinate tracking so card resize/drag preserves edge attachment.
 */

export type PortSemanticType =
  | 'reference'
  | 'identity'
  | 'evidence'
  | 'continuity-in'
  | 'continuity-out'
  | 'branch-out'
  | 'branch-in'
  | 'transform'
  | 'media-time-range'
  | 'generic'

export type PortSide = 'left' | 'right' | 'top' | 'bottom' | 'auto'
export type PortDirection = 'source' | 'target' | 'both'

export interface CardPort {
  id: string
  cardId: string
  semanticType: PortSemanticType
  side: PortSide
  normalizedOffset: number // 0.0 to 1.0 along the specified edge
  direction: PortDirection
  label?: string
  colorToken?: string
}

export interface CardBounds {
  x: number
  y: number
  width: number
  height: number
}

export interface AbsolutePoint {
  x: number
  y: number
}

/**
 * Computes exact canvas coordinates for a port based on current card bounds.
 */
export function computePortPosition(port: CardPort, bounds: CardBounds): AbsolutePoint {
  const { x, y, width, height } = bounds
  const offset = Math.max(0, Math.min(1, port.normalizedOffset))

  switch (port.side) {
    case 'top':
      return { x: x + width * offset, y }
    case 'bottom':
      return { x: x + width * offset, y: y + height }
    case 'left':
      return { x, y: y + height * offset }
    case 'right':
    default:
      return { x: x + width, y: y + height * offset }
  }
}

/**
 * Validates whether two ports can legally form a directional semantic connection.
 */
export function validatePortConnection(
  source: CardPort,
  target: CardPort
): { valid: boolean; reason?: string } {
  if (source.cardId === target.cardId) {
    return { valid: false, reason: 'Self-connecting loops are prohibited.' }
  }

  if (!['source', 'target', 'both'].includes(source.direction) || !['source', 'target', 'both'].includes(target.direction)) {
    return { valid: false, reason: 'Both ports must have a valid direction.' }
  }

  if (source.direction === 'target') {
    return { valid: false, reason: `Port ${source.id} is target-only and cannot initiate a connection.` }
  }

  if (target.direction === 'source') {
    return { valid: false, reason: `Port ${target.id} is source-only and cannot receive a connection.` }
  }

  // Type compatibility rules
  if (source.semanticType === 'identity' && target.semanticType !== 'identity' && target.semanticType !== 'generic') {
    return { valid: false, reason: 'Identity ports can only connect to identity or generic sockets.' }
  }

  if (source.semanticType === 'continuity-out' && target.semanticType !== 'continuity-in' && target.semanticType !== 'branch-in' && target.semanticType !== 'generic') {
    return { valid: false, reason: 'Continuity-out must terminate on continuity-in or branch-in.' }
  }

  if (source.semanticType === 'branch-out' && target.semanticType !== 'branch-in' && target.semanticType !== 'continuity-in' && target.semanticType !== 'generic') {
    return { valid: false, reason: 'Branch-out must terminate on branch-in or continuity-in.' }
  }

  return { valid: true }
}

/**
 * Color tokens representing semantic port types on canvas.
 */
export const PORT_SEMANTIC_COLORS: Record<PortSemanticType, string> = {
  reference: '#3b82f6', // blue
  identity: '#a855f7', // purple
  evidence: '#10b981', // green
  'continuity-in': '#f59e0b', // amber
  'continuity-out': '#f59e0b', // amber
  'branch-out': '#ef4444', // red
  'branch-in': '#ef4444', // red
  transform: '#ec4899', // pink
  'media-time-range': '#06b6d4', // cyan
  generic: '#94a3b8' // slate
}

/**
 * Generates standard semantic ports for cards based on their narrative / structural role.
 */
export function createStandardCardPorts(
  cardId: string,
  role: 'continuity' | 'branch' | 'reference' | 'identity' | 'video' | 'general'
): CardPort[] {
  switch (role) {
    case 'continuity':
      return [
        { id: `${cardId}-cin`, cardId, semanticType: 'continuity-in', side: 'left', normalizedOffset: 0.5, direction: 'target', label: 'Continuity In' },
        { id: `${cardId}-cout`, cardId, semanticType: 'continuity-out', side: 'right', normalizedOffset: 0.5, direction: 'source', label: 'Continuity Out' },
        { id: `${cardId}-bout`, cardId, semanticType: 'branch-out', side: 'bottom', normalizedOffset: 0.5, direction: 'source', label: 'Branch Out' },
        { id: `${cardId}-ref`, cardId, semanticType: 'reference', side: 'top', normalizedOffset: 0.5, direction: 'target', label: 'Reference In' }
      ]
    case 'branch':
      return [
        { id: `${cardId}-bin`, cardId, semanticType: 'branch-in', side: 'top', normalizedOffset: 0.5, direction: 'target', label: 'Branch In' },
        { id: `${cardId}-cout`, cardId, semanticType: 'continuity-out', side: 'right', normalizedOffset: 0.5, direction: 'source', label: 'Continuity Out' },
        { id: `${cardId}-ref`, cardId, semanticType: 'reference', side: 'bottom', normalizedOffset: 0.5, direction: 'target', label: 'Reference In' }
      ]
    case 'identity':
      return [
        { id: `${cardId}-idin`, cardId, semanticType: 'identity', side: 'left', normalizedOffset: 0.5, direction: 'target', label: 'Identity In' },
        { id: `${cardId}-idout`, cardId, semanticType: 'identity', side: 'right', normalizedOffset: 0.5, direction: 'source', label: 'Identity Out' },
        { id: `${cardId}-ref`, cardId, semanticType: 'reference', side: 'top', normalizedOffset: 0.5, direction: 'both', label: 'Ref Socket' }
      ]
    case 'video':
      return [
        { id: `${cardId}-refout`, cardId, semanticType: 'reference', side: 'right', normalizedOffset: 0.5, direction: 'source', label: 'Ref Out' },
        { id: `${cardId}-time`, cardId, semanticType: 'media-time-range', side: 'bottom', normalizedOffset: 0.5, direction: 'source', label: 'Time Range' }
      ]
    case 'reference':
    case 'general':
    default:
      return [
        { id: `${cardId}-ref-left`, cardId, semanticType: 'reference', side: 'left', normalizedOffset: 0.5, direction: 'both', label: 'Ref Left' },
        { id: `${cardId}-ref-right`, cardId, semanticType: 'reference', side: 'right', normalizedOffset: 0.5, direction: 'both', label: 'Ref Right' },
        { id: `${cardId}-ref-top`, cardId, semanticType: 'reference', side: 'top', normalizedOffset: 0.5, direction: 'both', label: 'Ref Top' },
        { id: `${cardId}-ref-bottom`, cardId, semanticType: 'reference', side: 'bottom', normalizedOffset: 0.5, direction: 'both', label: 'Ref Bottom' }
      ]
  }
}

/**
 * Art Equation Canvas Engine - Color Utilities
 */

export function normalizeColor8(color: string): string {
  if (!color || color === 'none') return '#00000000'
  if (color.startsWith('#')) {
    if (color.length === 7) return `${color}ff`
    if (color.length === 9) return color
    if (color.length === 4) {
      const r = color[1], g = color[2], b = color[3]
      return `#${r}${r}${g}${g}${b}${b}ff`
    }
  }
  return color
}

/**
 * Art Equation Canvas Engine - Column Object & Square Slot Snapping Architecture
 *
 * Implements column and square container objects with explicit uniform media fit
 * and direct perimeter port attachment. Stretching is opt-in for legacy callers.
 */

import type { Rect } from './snapManager.ts'
import type { MediaFitMode } from './mediaEngine.ts'
import { calculateMediaFit, createMediaRenderOp } from './mediaEngine.ts'
import { computePortPosition, createStandardCardPorts, PORT_SEMANTIC_COLORS, type CardPort } from './cardPorts.ts'

export interface ImageResourceRef {
  key: string
  width: number
  height: number
  revision?: number
  epoch?: number
}
export type SlotMediaFitMode = MediaFitMode | 'stretch'

export interface ColumnItemSpec {
  id: string
  title?: string
  imageKey?: string
  isSquare?: boolean
  width?: number
  height?: number
  aspectRatio?: number
  role?: 'continuity' | 'reference' | 'identity' | 'branch' | 'reservoir'
  fillColor?: string
  borderColor?: string
}

export interface SnappedSlot {
  id: string
  role: string
  bounds: Rect
  title?: string
  imageKey?: string
  ports: CardPort[]
  fillColor?: string
  borderColor?: string
}

export interface ColumnLayoutResult {
  columnBounds: Rect
  slots: SnappedSlot[]
}

/**
 * Creates a column container object and computes snapped vertical slots for each child item.
 * Every item inherits the column width and snaps flush to the column's horizontal track.
 */
export function layoutColumnContainer(
  _columnId: string,
  origin: { x: number; y: number },
  columnWidth: number,
  gap: number,
  items: ColumnItemSpec[]
): ColumnLayoutResult {
  let currentY = origin.y
  const slots: SnappedSlot[] = []

  for (const item of items) {
    let itemHeight = item.height || columnWidth // Default to square if unspecified

    if (item.isSquare) {
      itemHeight = columnWidth
    } else if (item.aspectRatio && item.aspectRatio > 0) {
      itemHeight = Math.round(columnWidth / item.aspectRatio)
    }

    const bounds: Rect = {
      x: origin.x,
      y: currentY,
      width: columnWidth,
      height: itemHeight
    }

    const role = item.role || 'continuity'
    const ports = createStandardCardPorts(item.id, role === 'reservoir' ? 'general' : role)

    slots.push({
      id: item.id,
      role,
      bounds,
      title: item.title,
      imageKey: item.imageKey,
      ports,
      fillColor: item.fillColor,
      borderColor: item.borderColor
    })

    currentY += itemHeight + gap
  }

  const totalHeight = currentY > origin.y ? currentY - origin.y - gap : 0
  const columnBounds: Rect = {
    x: origin.x,
    y: origin.y,
    width: columnWidth,
    height: totalHeight
  }

  return { columnBounds, slots }
}

export interface SquareContainerSpec {
  id: string
  x: number
  y: number
  size: number
  role?: 'continuity' | 'reference' | 'identity' | 'branch' | 'reservoir'
  title?: string
  imageKey?: string
  fillColor?: string
  borderColor?: string
}

export interface SnappedSquare {
  id: string
  bounds: Rect
  role: string
  title?: string
  imageKey?: string
  ports: CardPort[]
  fillColor?: string
  borderColor?: string
}

/**
 * Creates a standalone square container object where cards and images snap flush inside.
 * Treats the square identically to column object slots with single-pixel perimeter bounds.
 */
export function createSquareContainer(spec: SquareContainerSpec): SnappedSquare {
  const bounds: Rect = {
    x: spec.x,
    y: spec.y,
    width: spec.size,
    height: spec.size
  }
  const role = spec.role || 'continuity'
  const ports = createStandardCardPorts(spec.id, role === 'reservoir' ? 'general' : role)
  return {
    id: spec.id,
    bounds,
    role,
    title: spec.title,
    imageKey: spec.imageKey,
    ports,
    fillColor: spec.fillColor,
    borderColor: spec.borderColor
  }
}

/**
 * Uniform cover fills the slot using a source crop; contain preserves the whole
 * source within the slot. Explicit stretch retains the older affine behavior.
 * Layout screenshots must never be used as source media for any fit mode.
 */
export function snapImageToSlot(
  opId: string,
  slotRect: Rect,
  imageRef: ImageResourceRef,
  opacity: number = 1.0,
  fitMode: SlotMediaFitMode = 'cover'
): any {
  if (![slotRect.x, slotRect.y, slotRect.width, slotRect.height, imageRef.width, imageRef.height].every(Number.isFinite)
    || ![slotRect.x + slotRect.width, slotRect.y + slotRect.height].every(Number.isFinite)
    || slotRect.width <= 0 || slotRect.height <= 0 || !Number.isInteger(imageRef.width) || !Number.isInteger(imageRef.height)
    || imageRef.width <= 0 || imageRef.height <= 0) {
    throw new Error('Slot and image dimensions must be finite and positive.')
  }
  if (!Number.isFinite(opacity) || opacity < 0 || opacity > 1) throw new Error('Image opacity must be between zero and one.')
  if (!['contain', 'cover', 'crop', 'native', 'stretch'].includes(fitMode)) throw new Error(`Unsupported slot media fit: ${fitMode}`)
  if (fitMode !== 'stretch') {
    const fit = calculateMediaFit({ intrinsicWidth: imageRef.width, intrinsicHeight: imageRef.height },
      { frameRect: slotRect, fitMode })
    return createMediaRenderOp(opId, { ...imageRef, revision: imageRef.revision ?? 1, epoch: imageRef.epoch ?? 1 }, fit, opacity)
  }

  // Compatibility mode only: independent affine scales intentionally distort.
  const sx = slotRect.width / imageRef.width
  const sy = slotRect.height / imageRef.height
  const tx = slotRect.x
  const ty = slotRect.y

  return {
    type: 'image',
    id: opId,
    resource: {
      key: imageRef.key,
      revision: imageRef.revision || 1,
      epoch: imageRef.epoch || 1,
      width: imageRef.width,
      height: imageRef.height
    },
    sourceRect: {
      x: 0,
      y: 0,
      width: imageRef.width,
      height: imageRef.height
    },
    transform: [sx, 0, 0, sy, tx, ty],
    opacity,
    sampling: 'bilinear'
  }
}

/**
 * Snaps an image flush inside a square slot with zero margin/padding.
 * Uses the same uniform media fit contract as a column slot.
 */
export function snapImageToSquareSlot(
  opId: string,
  slotRect: Rect,
  imageRef: ImageResourceRef,
  opacity: number = 1.0,
  fitMode: SlotMediaFitMode = 'cover'
): any {
  return snapImageToSlot(opId, slotRect, imageRef, opacity, fitMode)
}

/**
 * Snaps an image flush inside a column slot with zero margin/padding.
 */
export function snapImageToColumnSlot(
  opId: string,
  slotRect: Rect,
  imageRef: ImageResourceRef,
  opacity: number = 1.0,
  fitMode: SlotMediaFitMode = 'cover'
): any {
  return snapImageToSlot(opId, slotRect, imageRef, opacity, fitMode)
}

/**
 * Computes socket handle positions attached directly to the flush perimeter of a slot.
 */
export function getSlotPerimeterPorts(slot: SnappedSlot | SnappedSquare): Array<{ port: CardPort; x: number; y: number; color: string }> {
  return slot.ports.map((port) => {
    const pt = computePortPosition(port, slot.bounds)
    const color = PORT_SEMANTIC_COLORS[port.semanticType] || '#3b82f6'
    return { port, x: pt.x, y: pt.y, color }
  })
}

import type { BoardModel, BoardNode } from '../model/project'
import { validateContainerOwnership, moveContainerWithDescendants, reparentContainerNodes, type StructureResult } from './diagramStructureCore'
import { columnChildren, insertNodesIntoColumnResult, releaseNodesFromColumnsResult, flowOwnerId, isFlowColumn } from './columns'
import { validateBoardMutation } from './boardMutationSafety'

type Options = { readOnly?: boolean }
export type ColumnRowActionState = {
  visible: boolean
  earlier: boolean
  later: boolean
  previousColumn: boolean
  nextColumn: boolean
  detach: boolean
  ancestor: boolean
  reason?: string
}
const refuse = <T = BoardModel>(detail: string): StructureResult<T> => ({ ok: false, issues: [{ code: 'column-row-command', detail }] })

function selectedRows(board: BoardModel, ids: readonly string[], options: Options): StructureResult<BoardNode[]> {
  if (options.readOnly) return refuse('This workspace is read-only.')
  const valid = validateContainerOwnership(board.nodes)
  if (!valid.ok) return valid
  const requested = new Set(ids)
  if (!requested.size) return refuse('Select a column row first.')
  for (const id of requested) if (!valid.value.has(id)) return refuse('A selected row is no longer on this board.')
  const roots = [...requested].filter((id) => {
    let node = valid.value.get(id)!
    while (node.groupId || node.parentColumnId) {
      const owner = node.groupId || node.parentColumnId!
      if (requested.has(owner)) return false
      node = valid.value.get(owner)!
    }
    return true
  }).map((id) => valid.value.get(id)!)
  if (!roots.length || roots.some((node) => !flowOwnerId(node, board.nodes))) return refuse('Select rows directly owned by a column.')
  const editable = moveContainerWithDescendants(board.nodes, board.connectors, roots.map((node) => node.id), { x: 0, y: 0 })
  return editable.ok ? { ok: true, value: roots } : editable
}

function orderedBlock(board: BoardModel, rows: BoardNode[]): StructureResult<{ columnId: string; ids: string[]; first: number; count: number; total: number }> {
  const columns = new Set(rows.map((row) => flowOwnerId(row, board.nodes)!))
  if (columns.size !== 1) return refuse('Select rows from one column to change their order.')
  const columnId = flowOwnerId(rows[0], board.nodes)!, children = columnChildren(board, columnId), selected = new Set(rows.map((row) => row.id))
  const indexes = children.flatMap((row, index) => selected.has(row.id) ? [index] : [])
  if (indexes.some((index, order) => index !== indexes[0] + order)) return refuse('Select adjacent rows to move them together.')
  return { ok: true, value: { columnId, ids: children.filter((row) => selected.has(row.id)).map((row) => row.id), first: indexes[0], count: indexes.length, total: children.length } }
}

function siblingColumns(board: BoardModel, currentColumnId: string): { previous?: BoardNode; next?: BoardNode } {
  const current = board.nodes.find((n) => n.id === currentColumnId && isFlowColumn(n))
  if (!current) return {}
  const siblings = board.nodes
    .filter((n) => isFlowColumn(n) && n.groupId === current.groupId)
    .sort((a, b) => a.x - b.x || a.y - b.y || a.id.localeCompare(b.id))
  const index = siblings.findIndex((n) => n.id === currentColumnId)
  if (index < 0) return {}
  return {
    previous: index > 0 ? siblings[index - 1] : undefined,
    next: index < siblings.length - 1 ? siblings[index + 1] : undefined,
  }
}

/** Move one row or an adjacent selected block one row earlier/later. Supplied
 * selection order never changes the saved mixed-content order. */
export function moveColumnRowsResult(board: BoardModel, ids: readonly string[], direction: 'earlier' | 'later', options: Options = {}): StructureResult<BoardModel> {
  const rows = selectedRows(board, ids, options)
  if (!rows.ok) return rows
  const block = orderedBlock(board, rows.value)
  if (!block.ok) return block
  if (direction !== 'earlier' && direction !== 'later') return refuse('Choose whether to move rows earlier or later.')
  const { columnId, first, count, total } = block.value
  if ((direction === 'earlier' && first === 0) || (direction === 'later' && first + count === total)) return { ok: true, value: board }
  const moved = insertNodesIntoColumnResult(board, block.value.ids, { columnId, index: first + (direction === 'earlier' ? -1 : 1) })
  return moved.ok ? validateBoardMutation(board, moved.value, Boolean(options.readOnly)) : moved
}

/** Move one row or an adjacent block to an adjacent sibling column on the board. */
export function moveColumnRowsToSiblingColumnResult(
  board: BoardModel,
  ids: readonly string[],
  direction: 'previous' | 'next',
  options: Options = {}
): StructureResult<BoardModel> {
  const rows = selectedRows(board, ids, options)
  if (!rows.ok) return rows
  const block = orderedBlock(board, rows.value)
  if (!block.ok) return block
  const { previous, next } = siblingColumns(board, block.value.columnId)
  const target = direction === 'previous' ? previous : next
  if (!target) return refuse(`No ${direction} sibling column available.`)
  if (target.locked || target.hidden || target.collapsed) return refuse(`The target column is ${target.locked ? 'locked' : target.hidden ? 'hidden' : 'collapsed'}.`)
  const targetChildren = columnChildren(board, target.id)
  const moved = insertNodesIntoColumnResult(board, block.value.ids, { columnId: target.id, index: targetChildren.length })
  return moved.ok ? validateBoardMutation(board, moved.value, Boolean(options.readOnly)) : moved
}

/** Move selected items out of their immediate column or frame to their ancestor container. */
export function moveSelectionToAncestorResult(
  board: BoardModel,
  ids: readonly string[],
  options: Options = {}
): StructureResult<BoardModel> {
  if (options.readOnly) return refuse('This workspace is read-only.')
  const valid = validateContainerOwnership(board.nodes)
  if (!valid.ok) return valid
  const requested = new Set(ids)
  if (!requested.size) return refuse('Select objects to move to ancestor container.')

  const roots = [...requested].filter((id) => {
    let node = valid.value.get(id)!
    while (node.groupId || node.parentColumnId) {
      const owner = node.groupId || node.parentColumnId!
      if (requested.has(owner)) return false
      node = valid.value.get(owner)!
    }
    return true
  }).map((id) => valid.value.get(id)!)

  if (!roots.length) return refuse('No editable objects selected.')

  const columnRowRoots = roots.filter((node) => flowOwnerId(node, board.nodes))
  if (columnRowRoots.length === roots.length) {
    const column = valid.value.get(flowOwnerId(columnRowRoots[0], board.nodes)!)
    if (column?.groupId) {
      const parentFrame = valid.value.get(column.groupId)
      if (parentFrame && parentFrame.kind === 'group') {
        const released = releaseNodesFromColumnsResult(board, roots.map((r) => r.id))
        if (!released.ok) return released
        const reparented = reparentContainerNodes(released.value.nodes, roots.map((r) => r.id), { kind: 'group', id: parentFrame.id })
        if (!reparented.ok) return reparented
        return validateBoardMutation(board, { ...board, nodes: reparented.value }, Boolean(options.readOnly))
      }
    }
    return detachColumnRowsResult(board, roots.map((r) => r.id), options)
  }

  const groupRoots = roots.filter((node) => node.groupId)
  if (groupRoots.length === roots.length) {
    const parentGroup = valid.value.get(groupRoots[0].groupId!)
    if (parentGroup?.groupId) {
      const grandParent = valid.value.get(parentGroup.groupId)
      if (grandParent && grandParent.kind === 'group') {
        const reparented = reparentContainerNodes(board.nodes, roots.map((r) => r.id), { kind: 'group', id: grandParent.id })
        return reparented.ok ? validateBoardMutation(board, { ...board, nodes: reparented.value }, Boolean(options.readOnly)) : reparented
      }
    }
    const reparented = reparentContainerNodes(board.nodes, roots.map((r) => r.id))
    return reparented.ok ? validateBoardMutation(board, { ...board, nodes: reparented.value }, Boolean(options.readOnly)) : reparented
  }

  const released = releaseNodesFromColumnsResult(board, roots.map((r) => r.id))
  if (!released.ok) return released
  const reparented = reparentContainerNodes(released.value.nodes, roots.map((r) => r.id))
  return reparented.ok ? validateBoardMutation(board, { ...board, nodes: reparented.value }, Boolean(options.readOnly)) : reparented
}

/** Release rows through the same source reflow/free-frame restoration as a
 * pointer detach, retaining their current world position and all source bytes. */
export function detachColumnRowsResult(board: BoardModel, ids: readonly string[], options: Options = {}): StructureResult<BoardModel> {
  const rows = selectedRows(board, ids, options)
  if (!rows.ok) return rows
  const released = releaseNodesFromColumnsResult(board, rows.value.map((row) => row.id))
  return released.ok ? validateBoardMutation(board, released.value, Boolean(options.readOnly)) : released
}

export function columnRowActionState(board: BoardModel, ids: readonly string[], options: Options = {}): ColumnRowActionState {
  const visible = ids.some((id) => board.nodes.some(node => node.id === id && flowOwnerId(node, board.nodes)))
  const rows = selectedRows(board, ids, options)
  if (!rows.ok) return { visible, earlier: false, later: false, previousColumn: false, nextColumn: false, detach: false, ancestor: false, reason: rows.issues[0]?.detail }
  const block = orderedBlock(board, rows.value)
  if (!block.ok) return { visible, earlier: false, later: false, previousColumn: false, nextColumn: false, detach: true, ancestor: true, reason: block.issues[0]?.detail }
  const { previous, next } = siblingColumns(board, block.value.columnId)
  return {
    visible,
    earlier: block.value.first > 0,
    later: block.value.first + block.value.count < block.value.total,
    previousColumn: Boolean(previous && !previous.locked && !previous.hidden && !previous.collapsed),
    nextColumn: Boolean(next && !next.locked && !next.hidden && !next.collapsed),
    detach: true,
    ancestor: true,
  }
}

import type { BoardModel } from '../model/project'
import { containerDescendantIds, type StructureResult } from './diagramStructureCore'

export const COLUMN_ROW_POSITION_REASON = 'Detach from column to position freely.'

/** Explicit row-only position commands must not create geometry that hydration
 * discards. Canonical column layout and resize use their existing internal
 * movement helpers; this guard applies only at user position command boundaries. */
export function guardColumnRowPosition(board: BoardModel, ids: readonly string[]): StructureResult<BoardModel> {
  const closure = containerDescendantIds(board.nodes, ids)
  if (!closure.ok) return closure
  const moving = new Set(closure.value)
  for (const node of board.nodes) if (moving.has(node.id) && (node.parentColumnId || board.nodes.some(owner => owner.id === node.groupId && owner.graphColumn)) && !moving.has(node.parentColumnId || node.groupId!)) {
    return { ok: false, issues: [{ code: 'column-row-position', nodeId: node.id, detail: COLUMN_ROW_POSITION_REASON }] }
  }
  return { ok: true, value: board }
}

import type { BoardConnector, BoardModel, BoardNode } from '../model/project'
import { resizeVectorNodeFrame } from '../model/vector'
import { isRectangleErasure, rectangleErasureState, resizeRectangleErasureFrame } from '../model/rectangleErasure'
import { GraphColumnRuntime } from './graphColumnV2'
import { SUBBOARD_ROW_HEIGHT } from './subboardPresentation'
import {
  containerDescendantIds, containerPaintOrder, diagramState, moveContainerWithDescendants,
  reparentContainerNodes, validateContainerOwnership, type StructureResult,
} from './diagramStructureCore'

export const COLUMN_HEADER_HEIGHT = 58
export const COLUMN_PADDING = 10
export const COLUMN_GAP = 10
export const COLUMN_MIN_WIDTH = 230
export const COLUMN_EMPTY_HEIGHT = 150
/** Frame labels sit above their body, unlike regular group headers. */
export const COLUMN_FRAME_HEADER_HEIGHT = 28

export type ColumnDropTarget = { columnId: string; index: number }
export type ColumnDropResult = StructureResult<ColumnDropTarget | null>
export type ColumnCommandResult = StructureResult<BoardModel>
export type ColumnImageSizing = 'responsive' | 'minimum-height'

/** Explicit image framing remains a deliberate crop/transform choice. These
 * rows, image cards and covers keep their existing card-layout rules. */
const responsiveArtwork = (node: BoardNode) => node.kind === 'image' && node.imagePresentation === 'artwork'
  && (node.imageTransform?.fit === undefined || node.imageTransform.fit === 'contain')
  && (node.imageTransform?.zoom === undefined || node.imageTransform.zoom === 1)
  && (node.imageTransform?.rotation === undefined || node.imageTransform.rotation === 0)
  && !node.imageTransform?.flipX && !node.imageTransform?.flipY
  && (node.imageTransform?.positionX === undefined || node.imageTransform.positionX === 50)
  && (node.imageTransform?.positionY === undefined || node.imageTransform.positionY === 50)
const imageSizing = (node: BoardNode): ColumnImageSizing | undefined => {
  const value = node.columnImageSizing
  return value === 'responsive' || value === 'minimum-height' ? value : undefined
}

const success = (value: BoardModel): ColumnCommandResult => ({ ok: true, value })
const failure = <T = BoardModel>(code: string, detail: string, nodeId?: string): StructureResult<T> => ({ ok: false, issues: [{ code, detail, ...(nodeId ? { nodeId } : {}) }] })
export const isFlowColumn = (node: BoardNode | undefined) => Boolean(node && (node.kind === 'column' || (node.kind === 'group' && node.graphColumn)))
export const flowOwnerId = (node: BoardNode, nodes: readonly BoardNode[]) => node.parentColumnId || (nodes.some(owner => owner.id === node.groupId && owner.graphColumn) ? node.groupId : undefined)
const isContainer = (node: BoardNode) => node.kind === 'group' || isFlowColumn(node)
const positive = (value: number | undefined): value is number => typeof value === 'number' && Number.isFinite(value) && value > 0
// Legacy typed edges remain distinct from the versioned graph dataflow.
const isNodeColumn = (node: BoardNode | undefined) => isFlowColumn(node) && (node as BoardNode & { columnMode?: string }).columnMode === 'node'
const isNodeGraphConnector = (edge: BoardConnector) => (edge as BoardConnector & { nodeGraph?: { version?: number } }).nodeGraph?.version === 1
const nodeGraphOwner = (board: BoardModel, node: BoardNode) => {
  let parentId = node.parentColumnId
  const seen = new Set<string>()
  while (parentId && !seen.has(parentId)) {
    seen.add(parentId)
    const parent = board.nodes.find((entry) => entry.id === parentId)
    if (isNodeColumn(parent)) return parent
    parentId = parent?.parentColumnId
  }
  return undefined
}

/** Milanote-style subboards flow as compact rows, never stretched covers. */
export function isColumnSubboardTile(node: BoardNode) {
  return node.kind === 'board-link' && node.boardLinkRole === 'child' && Boolean(node.boardPortal)
}

export function columnChildren(board: BoardModel, columnId: string, excludedIds: ReadonlySet<string> = new Set()) {
  return board.nodes
    .filter((node) => flowOwnerId(node, board.nodes) === columnId && !excludedIds.has(node.id))
    .sort((a, b) => (a.columnOrder ?? 0) - (b.columnOrder ?? 0) || a.y - b.y || a.id.localeCompare(b.id))
}

function selectedRoots(board: BoardModel, ids: readonly string[]): StructureResult<BoardNode[]> {
  const valid = validateContainerOwnership(board.nodes)
  if (!valid.ok) return valid
  const requested = new Set(ids)
  for (const id of requested) if (!valid.value.has(id)) return { ok: false, issues: [{ code: 'missing-object', nodeId: id, detail: `Object ${id} is not on this board.` }] }
  return { ok: true, value: [...requested].filter((id) => {
    let node = valid.value.get(id)!
    while (node.groupId || node.parentColumnId) {
      const owner = node.groupId || node.parentColumnId!
      if (requested.has(owner)) return false
      node = valid.value.get(owner)!
    }
    return true
  }).map((id) => valid.value.get(id)!) }
}

/** Propagate inner row heights through owning columns; never infer group size. */
function affectedColumnIds(board: BoardModel, ids: readonly string[]): string[] {
  const byId = new Map(board.nodes.map((node) => [node.id, node])), columns = new Set(ids)
  for (const id of ids) {
    let node = byId.get(id)
    while (node?.groupId || node?.parentColumnId) {
      node = byId.get(node.groupId || node.parentColumnId!)
      if (node && isFlowColumn(node)) columns.add(node.id)
    }
  }
  return [...columns]
}

/** Scoped, atomic reflow uses the production subtree/route movement command.
 * Whole-board normalization skips locked/hidden columns; explicit scope refuses
 * them. Every changed row is checked, including its inherited/descendant locks. */
export function layoutBoardColumnsResult(board: BoardModel, columnIds?: readonly string[]): ColumnCommandResult {
  const valid = validateContainerOwnership(board.nodes)
  if (!valid.ok) return valid
  const requested = columnIds ? [...new Set(columnIds)] : board.nodes.filter((node) => isFlowColumn(node)).map((node) => node.id)
  const depths = new Map<string, number>()
  for (const id of requested) {
    const node = valid.value.get(id)
    if (!node) return failure('missing-owner', `Column ${id} is not on this board.`, id)
    if (!isFlowColumn(node)) return failure('wrong-owner-kind', 'Column layout requires a column container.', id)
    const state = diagramState(board.nodes, id)
    if (!state.ok) return state
    if (columnIds && (state.value.locked || state.value.hidden)) return failure('uneditable-owner', 'The column or its ancestor is locked or hidden; layout was cancelled.', id)
    depths.set(id, state.value.containerAncestors.length)
  }
  let next = board
  for (const id of requested.sort((a, b) => depths.get(b)! - depths.get(a)!)) {
    const column = next.nodes.find((node) => node.id === id)!
    if (!columnIds && column.columnFixedLayout) continue
    const state = diagramState(next.nodes, id)
    if (!state.ok) return state
    if (state.value.locked || state.value.hidden) continue
    if (![column.x, column.y].every(Number.isFinite) || !positive(column.width) || !positive(column.height)) return failure('invalid-geometry', 'Column geometry must be finite with positive dimensions.', id)
    const children = columnChildren(next, id)
    if (children.some((child) => !positive(child.width) || !positive(child.height) || ![child.x, child.y].every(Number.isFinite))) return failure('invalid-geometry', 'Every column row must have finite geometry and positive dimensions.', id)
    // Keep nested frame/column dimensions, widening the host if necessary.
    const width = Math.max(COLUMN_MIN_WIDTH, column.width, ...children.filter(isContainer).map((child) => child.width + COLUMN_PADDING * 2))
    if (column.collapsed) {
      if (column.width !== width || column.height !== COLUMN_HEADER_HEIGHT) next = { ...next, nodes: next.nodes.map((node) => node.id === id ? { ...node, width, height: COLUMN_HEADER_HEIGHT } : node) }
      continue
    }
    const innerWidth = width - COLUMN_PADDING * 2
    let y = column.y + COLUMN_HEADER_HEIGHT + COLUMN_PADDING
    for (let index = 0; index < children.length; index++) {
      const child = next.nodes.find((node) => node.id === children[index].id)!
      let x = column.x + COLUMN_PADDING, rowY = y, childWidth = child.width, childHeight = child.height
      if (isColumnSubboardTile(child)) {
        childWidth = innerWidth; childHeight = SUBBOARD_ROW_HEIGHT
        y += childHeight + COLUMN_GAP
      } else {
        if (child.kind === 'group' && (child.containerRole === 'frame' || /\bframe\b/i.test(child.title))) { y += COLUMN_FRAME_HEADER_HEIGHT; rowY = y }
        if (!isContainer(child)) {
          const sourceWidth = positive(child.freeWidth) ? child.freeWidth : child.width
          const sourceHeight = positive(child.freeHeight) ? child.freeHeight : child.height
          const explicitArtworkSizing = responsiveArtwork(child) ? imageSizing(column) : undefined
          childWidth = explicitArtworkSizing ? innerWidth : column.columnPreserveCardSizes ? Math.min(innerWidth, sourceWidth) : innerWidth
          const proportionalHeight = sourceHeight * childWidth / sourceWidth
          childHeight = explicitArtworkSizing === 'responsive' ? proportionalHeight
            : explicitArtworkSizing === 'minimum-height' ? Math.max(78, Math.round(proportionalHeight))
              : column.columnPreserveCardSizes ? proportionalHeight
                : child.kind === 'document' ? Math.max(70, sourceHeight) : Math.max(78, Math.round(sourceHeight * innerWidth / sourceWidth))
        }
        y += childHeight + COLUMN_GAP
      }
      if (![x, rowY, childWidth, childHeight, y].every(Number.isFinite) || !positive(childWidth) || !positive(childHeight)) return failure('invalid-layout', 'Column layout would exceed finite positive geometry.', child.id)
      if (child.x === x && child.y === rowY && child.width === childWidth && child.height === childHeight && child.columnOrder === index) continue
      if (child.kind === 'shape' && child.shapeType === 'rectangle' && child.vectorBoolean && !rectangleErasureState(child)) return failure('invalid-rectangle-erasure', 'This rectangle has invalid erasure modifiers; column layout was cancelled without changing artwork.', child.id)
      const moved = moveContainerWithDescendants(next.nodes, next.connectors, [child.id], { x: x - child.x, y: rowY - child.y })
      if (!moved.ok) return moved
      next = { ...next, nodes: moved.value.nodes.map((node) => {
        if (node.id !== child.id) return node
        const frame = { x: node.x, y: node.y, width: childWidth, height: childHeight }
        const resized = isRectangleErasure(node) ? resizeRectangleErasureFrame(node, frame) : node.vectorPath && (node.width !== childWidth || node.height !== childHeight) ? resizeVectorNodeFrame(node, frame) : { ...node, ...frame }
        return { ...resized, columnOrder: index }
      }), connectors: moved.value.connectors }
    }
    const height = Math.max(COLUMN_EMPTY_HEIGHT, children.length ? y - column.y + (column.graphColumn ? 32 : 0) : COLUMN_EMPTY_HEIGHT)
    if (!Number.isFinite(height)) return failure('invalid-layout', 'Column layout would exceed finite geometry.', id)
    const current = next.nodes.find((node) => node.id === id)!
    if (current.width !== width || current.height !== height) next = { ...next, nodes: next.nodes.map((node) => node.id === id ? { ...node, width, height } : node) }
  }
  return success(next)
}

/** A document command, not a default or load-time migration. Save a paired
 * source frame before a minimum-height floor can overwrite its aspect ratio.
 * Explicit choices also apply to fixed Node Columns; ordinary normalization
 * continues to leave their saved geometry and graph records alone. */
export function setColumnImageSizingResult(
  board: BoardModel, columnId: string, sizing: ColumnImageSizing, readOnly = false,
): ColumnCommandResult {
  if (readOnly) return failure('read-only', 'This workspace is read-only; column image sizing was not changed.', columnId)
  if (sizing !== 'responsive' && sizing !== 'minimum-height') return failure('invalid-image-sizing', 'Choose Responsive or Minimum height.', columnId)
  const valid = validateContainerOwnership(board.nodes)
  if (!valid.ok) return valid
  const column = valid.value.get(columnId)
  if (!column) return failure('missing-owner', `Column ${columnId} is not on this board.`, columnId)
  if (!isFlowColumn(column)) return failure('wrong-owner-kind', 'Image sizing requires a column container.', columnId)
  if (column.collapsed) return failure('uneditable-owner', 'Expand the column before changing its image sizing.', columnId)
  const descendants = containerDescendantIds(board.nodes, [columnId])
  if (!descendants.ok) return descendants
  for (const id of descendants.value) {
    const state = diagramState(board.nodes, id)
    if (!state.ok) return state
    if (state.value.locked || state.value.hidden) return failure('uneditable-owner', 'The column, an ancestor or an affected row is locked or hidden; image sizing was not changed.', id)
  }
  let changed = false
  const nodes = board.nodes.map((node) => {
    if (node.id === columnId) {
      if (imageSizing(node) === sizing) return node
      changed = true
      return { ...node, columnImageSizing: sizing }
    }
    if (flowOwnerId(node, board.nodes) !== columnId || !responsiveArtwork(node)
      || (positive(node.freeWidth) && positive(node.freeHeight))) return node
    changed = true
    // Never combine a valid old width with a newer floored height. Missing or
    // partial free geometry uses the current paired frame once, then persists.
    return { ...node, freeWidth: node.width, freeHeight: node.height }
  })
  const draft = changed ? { ...board, nodes } : board
  return layoutBoardColumnsResult(draft, affectedColumnIds(draft, [columnId]))
}

/** Compatibility entry point preserves the supplied snapshot on refusal. */
export function layoutBoardColumns(board: BoardModel, columnIds?: readonly string[]): BoardModel {
  const result = layoutBoardColumnsResult(board, columnIds)
  return result.ok ? result.value : board
}

/** Layout for an edit to specific objects: their own/owning columns only.
 * Callers supply all fresh clone/paste IDs when those include nested columns. */
export function layoutBoardColumnsForNodesResult(board: BoardModel, ids: readonly string[]): ColumnCommandResult {
  const valid = validateContainerOwnership(board.nodes)
  if (!valid.ok) return valid
  const columns = new Set<string>()
  for (const id of new Set(ids)) {
    let node = valid.value.get(id)
    if (!node) return failure('missing-object', `Object ${id} is not on this board.`, id)
    if (isFlowColumn(node)) columns.add(node.id)
    while (node.groupId || node.parentColumnId) {
      node = valid.value.get(node.groupId || node.parentColumnId!)!
      if (isFlowColumn(node)) columns.add(node.id)
    }
  }
  return layoutBoardColumnsResult(board, affectedColumnIds(board, [...columns]))
}

/** Distinguish a refused visible destination from dropping onto free canvas.
 * Callers can roll a refused gesture back without detaching its source row. */
export function findColumnDropTargetResult(board: BoardModel, worldX: number, worldY: number, movingIds: ReadonlySet<string>): ColumnDropResult {
  if (![worldX, worldY].every(Number.isFinite)) return failure('invalid-drop-position', 'Drop coordinates must be finite board-space positions.')
  const descendants = containerDescendantIds(board.nodes, [...movingIds])
  if (!descendants.ok) return descendants
  const paint = containerPaintOrder(board.nodes)
  if (!paint.ok) return paint
  const excluded = new Set(descendants.value)
  const candidates = board.nodes.filter((node) => isFlowColumn(node) && (!node.graphColumn || !excluded.has(node.id))
    && worldX >= node.x && worldX <= node.x + node.width
    && worldY >= node.y + COLUMN_HEADER_HEIGHT * .45 && worldY <= node.y + (node.collapsed ? COLUMN_HEADER_HEIGHT : Math.max(node.height, COLUMN_EMPTY_HEIGHT) + 36))
  const carriesTypedEdge = candidates.length > 0 && board.connectors.some((edge) => isNodeGraphConnector(edge) && (excluded.has(edge.sourceId || '') || excluded.has(edge.targetId || '')))
  // Match the visible object layer rather than the saved array order. A locked
  // topmost column must refuse the drop instead of falling through behind it.
  for (const column of candidates.sort((a, b) => paint.value.zIndexById.get(b.id)! - paint.value.zIndexById.get(a.id)!)) {
    const state = diagramState(board.nodes, column.id)
    if (!state.ok) return state
    if (state.value.hidden) continue
    if (state.value.locked || column.collapsed) return failure('uneditable-owner', 'The destination column is locked or collapsed; the drop was cancelled.', column.id)
    if (carriesTypedEdge && !isNodeColumn(column)) return failure('typed-edge-outside-node-column', 'Disconnect typed edges before moving their cards into a regular Column.', column.id)
    const reparented = reparentContainerNodes(board.nodes, [...movingIds], { kind: column.kind as 'group' | 'column', id: column.id })
    if (!reparented.ok) return reparented
    const children = columnChildren(board, column.id, excluded)
    const index = children.findIndex((child) => worldY < child.y + child.height / 2)
    return { ok: true, value: { columnId: column.id, index: index < 0 ? children.length : index } }
  }
  return { ok: true, value: null }
}

export function findColumnDropTarget(board: BoardModel, worldX: number, worldY: number, movingIds: ReadonlySet<string>): ColumnDropTarget | null {
  const result = findColumnDropTargetResult(board, worldX, worldY, movingIds)
  return result.ok ? result.value : null
}

export function columnInsertionY(board: BoardModel, target: ColumnDropTarget, movingIds: ReadonlySet<string>) {
  const column = board.nodes.find((node) => node.id === target.columnId)
  if (!column) return 0
  const children = columnChildren(board, target.columnId, movingIds)
  if (!children.length || target.index === 0) return column.y + COLUMN_HEADER_HEIGHT + COLUMN_PADDING
  const previous = children[Math.min(target.index, children.length) - 1]
  return previous.y + previous.height + COLUMN_GAP / 2
}

export function insertNodesIntoColumnResult(board: BoardModel, movingIds: readonly string[], target: ColumnDropTarget): ColumnCommandResult {
  if (!movingIds.length) return success(board)
  if (!Number.isSafeInteger(target.index) || target.index < 0) return failure('invalid-column-index', 'Drop placement must be a nonnegative integer row index.', target.columnId)
  const roots = selectedRoots(board, movingIds)
  if (!roots.ok) return roots
  const column = board.nodes.find((node) => node.id === target.columnId)
  if (!column) return failure('missing-owner', 'The destination column no longer exists.', target.columnId)
  if (!isFlowColumn(column)) return failure('wrong-owner-kind', 'The destination must be a Column or Graph Column.', target.columnId)
  if (column?.collapsed) return failure('uneditable-owner', 'Expand the destination column before adding rows.', column.id)
  if (column && !isNodeColumn(column) && !roots.value.every(isNodeColumn)) {
    const descendants = containerDescendantIds(board.nodes, movingIds)
    if (!descendants.ok) return descendants
    const moving = new Set(descendants.value)
    if (board.connectors.some((edge) => isNodeGraphConnector(edge) && (moving.has(edge.sourceId || '') || moving.has(edge.targetId || '')))) {
      return failure('typed-edge-outside-node-column', 'Disconnect typed edges before moving their cards into a regular Column.', column.id)
    }
  }
  const reparented = reparentContainerNodes(board.nodes, movingIds, { kind: (column?.kind || 'column') as 'group' | 'column', id: target.columnId })
  if (!reparented.ok) return reparented
  const moving = new Set(roots.value.map((node) => node.id)), sourceColumns = roots.value.flatMap((node) => flowOwnerId(node, board.nodes) ? [flowOwnerId(node, board.nodes)!] : [])
  const order = columnChildren(board, target.columnId, moving).map((node) => node.id)
  order.splice(Math.min(target.index, order.length), 0, ...moving)
  const orders = new Map(order.map((id, index) => [id, index]))
  // A locked row cannot be renumbered even if its geometry already matches.
  for (const node of board.nodes) if (!moving.has(node.id) && orders.has(node.id) && node.columnOrder !== orders.get(node.id)) {
    const editable = moveContainerWithDescendants(board.nodes, board.connectors, [node.id], { x: 0, y: 0 })
    if (!editable.ok) return editable
  }
  const nodes = reparented.value.map((node) => {
    if (!orders.has(node.id)) return node
    if (!moving.has(node.id)) return node.columnOrder === orders.get(node.id) ? node : { ...node, columnOrder: orders.get(node.id) }
    return { ...node, columnOrder: orders.get(node.id), ...(isContainer(node) ? {} : { freeWidth: positive(node.freeWidth) ? node.freeWidth : node.width, freeHeight: positive(node.freeHeight) ? node.freeHeight : node.height }) }
  })
  const draft = { ...board, nodes }
  try { const runtime=new GraphColumnRuntime();for(const graph of draft.nodes)if(graph.graphColumn)runtime.evaluate(draft,graph.id) }
  catch(error) { return failure('invalid-graph-containment', String(error), target.columnId) }
  return layoutBoardColumnsResult(draft, affectedColumnIds(draft, [...sourceColumns, target.columnId]))
}

export function insertNodesIntoColumn(board: BoardModel, movingIds: string[], target: ColumnDropTarget): BoardModel {
  const result = insertNodesIntoColumnResult(board, movingIds, target)
  return result.ok ? result.value : board
}

export function releaseNodesFromColumnsResult(board: BoardModel, movingIds: readonly string[]): ColumnCommandResult {
  const roots = selectedRoots(board, movingIds)
  if (!roots.ok) return roots
  // Freeform drags retain existing group/frame membership.
  const released = roots.value.filter((node) => flowOwnerId(node, board.nodes))
  if (!released.length) return success(board)
  const descendants = containerDescendantIds(board.nodes, released.map((node) => node.id))
  if (!descendants.ok) return descendants
  const moving = new Set(descendants.value)
  if (released.some((node) => !isNodeColumn(node) && nodeGraphOwner(board, node))
    && board.connectors.some((edge) => isNodeGraphConnector(edge) && (moving.has(edge.sourceId || '') || moving.has(edge.targetId || '')))) {
    return failure('typed-edge-outside-node-column', 'Disconnect typed edges before removing their cards from a Node Column.')
  }
  for (const node of released) if (node.kind === 'shape' && node.shapeType === 'rectangle' && node.vectorBoolean && !rectangleErasureState(node)) return failure('invalid-rectangle-erasure', 'This rectangle has invalid erasure modifiers; releasing its row was cancelled without changing artwork.', node.id)
  const reparented = reparentContainerNodes(board.nodes, released.map((node) => node.id))
  if (!reparented.ok) return reparented
  const releasedRoots = new Set(released.map((node) => node.id))
  const draft = { ...board, nodes: reparented.value.map((node) => {
    if (!releasedRoots.has(node.id) || isContainer(node)) return node
    const frame = { x: node.x, y: node.y, width: positive(node.freeWidth) ? node.freeWidth : node.width, height: positive(node.freeHeight) ? node.freeHeight : node.height }
    return isRectangleErasure(node) ? resizeRectangleErasureFrame(node, frame) : node.vectorPath && (node.width !== frame.width || node.height !== frame.height) ? resizeVectorNodeFrame(node, frame) : { ...node, ...frame }
  }) }
  return layoutBoardColumnsResult(draft, affectedColumnIds(draft, released.map((node) => flowOwnerId(node, board.nodes)!)))
}

export function releaseNodesFromColumns(board: BoardModel, movingIds: string[]): BoardModel {
  const result = releaseNodesFromColumnsResult(board, movingIds)
  return result.ok ? result.value : board
}

export type FlatColumnItem = {
  id: string
  columnId: string
  index: number
  x: number
  y: number
  width: number
  height: number
}

/** Flat coordinate layout calculation for columns.
 * Produces a linear coordinate list for fast viewport spatial queries without DOM tree thrashing. */
const flatColumnIndexes=new WeakMap<readonly BoardNode[],{owners:Map<string,BoardNode>;children:Map<string,BoardNode[]>;rows:Map<string,FlatColumnItem[]>}>()
export function computeFlatColumnCoordinates(board: BoardModel, columnIds?: readonly string[]): FlatColumnItem[] {
  let index=flatColumnIndexes.get(board.nodes)
  if(!index){
    const owners=new Map(board.nodes.filter(isFlowColumn).map(n=>[n.id,n])),children=new Map<string,BoardNode[]>()
    for(const node of board.nodes){const owner=node.parentColumnId||(node.groupId&&owners.get(node.groupId)?.graphColumn?node.groupId:undefined);if(!owner)continue;const list=children.get(owner)||[];list.push(node);children.set(owner,list)}
    index={owners,children,rows:new Map()};flatColumnIndexes.set(board.nodes,index)
  }
  const items:FlatColumnItem[]=[]
  for(const id of columnIds||index.owners.keys()){
