@media (forced-colors:active) { .diagram-palette { background:Canvas; color:CanvasText; border-color:CanvasText; box-shadow:none; } .diagram-palette :is(button,input) { background:Canvas; color:CanvasText; border-color:ButtonText; } .diagram-palette :is(button,input):focus-visible { outline-color:Highlight; } .diagram-palette small,.diagram-palette-hint,.diagram-palette-empty { color:CanvasText; } }

import { useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent } from 'react'
import { filterDiagramShapes, type DiagramShapeId } from './diagramPaletteCommands'
import './DiagramPalette.css'

export type DiagramPaletteCloseReason = 'escape' | 'outside' | 'cancel' | 'choose'
export type DiagramPaletteProps = {
  mode?: 'create' | 'successor' | 'insert'
  onChoose: (shape: DiagramShapeId) => boolean | void
  onClose: (reason: DiagramPaletteCloseReason) => void
  disabled?: boolean
  disabledReason?: string
  style?: CSSProperties
}
function ShapeIcon({ shape }: { shape: DiagramShapeId }) {
  return <svg viewBox="0 0 40 32" aria-hidden="true" focusable="false">
    {shape === 'process' ? <rect x="3" y="5" width="34" height="22" rx="1" />
      : shape === 'decision' ? <path d="M20 2 38 16 20 30 2 16Z" />
        : shape === 'start-end' ? <rect x="3" y="6" width="34" height="20" rx="10" />
          : shape === 'document' ? <path d="M4 3H36V25C26 31 16 19 4 25Z" />
            : shape === 'text' ? <path d="M8 6H32M20 6V27M14 27H26M8 6V10M32 6V10" />
              : <><path d="M4 16H35" />{shape === 'arrow' && <path d="M27 9 35 16 27 23" />}</>}
  </svg>
}

/** Nonmodal flyout. The caller owns placement and restoring trigger focus;
 * outside dismissal deliberately lets the clicked control keep its focus. */
export function DiagramPalette({ mode = 'create', onChoose, onClose, disabled = false, disabledReason, style }: DiagramPaletteProps) {
  const [query, setQuery] = useState(''), [active, setActive] = useState(0)
  const root = useRef<HTMLDivElement>(null), input = useRef<HTMLInputElement>(null), buttons = useRef<(HTMLButtonElement | null)[]>([])
  const headingId = useId(), hintId = useId(), shapes = filterDiagramShapes(query)
  useEffect(() => { input.current?.focus() }, [])
  useEffect(() => {
    const dismiss = (event: PointerEvent) => { if (event.target instanceof Node && !root.current?.contains(event.target)) onClose('outside') }
    document.addEventListener('pointerdown', dismiss)
    return () => document.removeEventListener('pointerdown', dismiss)
  }, [onClose])
  const choose = (shape: DiagramShapeId) => { if (!disabled && onChoose(shape) !== false) onClose('choose') }
  const focusButton = (index: number) => { if (!shapes.length || disabled) return; const next = (index + shapes.length) % shapes.length; setActive(next); buttons.current[next]?.focus() }
  const onButtonKey = (event: KeyboardEvent, index: number) => {
    const offset = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowDown' ? 2 : event.key === 'ArrowUp' ? -2 : 0
    if (offset || event.key === 'Home' || event.key === 'End') { event.preventDefault(); focusButton(event.key === 'Home' ? 0 : event.key === 'End' ? shapes.length - 1 : index + offset) }
  }
  const title = mode === 'successor' ? 'Add a connected shape' : mode === 'insert' ? 'Insert a shape' : 'Diagram shapes'
  const viewportStyle = { ...style, ...(typeof style?.top === 'number' && style.maxHeight === undefined ? { maxHeight: `calc(100vh - ${Math.max(12, style.top)}px - 12px)` } : {}) }
  return <div ref={root} className="diagram-palette" style={viewportStyle} role="dialog" aria-label="Diagram shapes" aria-labelledby={headingId} aria-describedby={mode === 'insert' || disabledReason ? hintId : undefined} aria-modal="false" onKeyDown={(event) => { if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); onClose('escape') } }}>
    <header><h2 id={headingId}>{title}</h2><button type="button" aria-label="Close diagram shapes" onClick={() => onClose('cancel')}>×</button></header>
    <label className="diagram-palette-search"><span>Find a shape</span><input ref={input} type="search" aria-label="Find a diagram shape" value={query} onChange={(event) => { setQuery(event.target.value); setActive(0) }} onKeyDown={(event) => { if (event.key === 'ArrowDown' || event.key === 'ArrowUp') { event.preventDefault(); focusButton(event.key === 'ArrowDown' ? 0 : shapes.length - 1) } }} /></label>
    {(mode === 'insert' || disabledReason) && <p id={hintId} className="diagram-palette-hint" role={disabledReason ? 'status' : undefined}>{disabledReason || 'The original label stays with the incoming relationship.'}</p>}
    <div className="diagram-palette-options" aria-label="Available diagram shapes">
      {shapes.map((shape, index) => <button ref={(button) => { buttons.current[index] = button }} key={shape.id} type="button" disabled={disabled} tabIndex={index === Math.min(active, shapes.length - 1) ? 0 : -1} aria-label={shape.label} title={shape.description} onFocus={() => setActive(index)} onKeyDown={(event) => onButtonKey(event, index)} onClick={() => choose(shape.id)}><ShapeIcon shape={shape.id} /><span>{shape.label}<small>{shape.description}</small></span></button>)}
    </div>
    {!shapes.length && <p className="diagram-palette-empty" role="status">No matching shapes. Try another name.</p>}
  </div>
}

import type { BoardConnector, BoardModel, BoardNode, BoardPoint, ConnectorPort } from '../model/project'
import { createDiagramShape, diagramProjectionStates, type DiagramShapeKind, type StructureResult } from './diagramStructureCore'
import { validateBoardMutation } from './boardMutationSafety'
import { columnChildren, insertNodesIntoColumnResult } from './columns'
import { connectorGeometry, connectorLabelPoint, nearestPort, pointAlongRoute, portPoint, projectConnectorLabelPosition, type ConnectorGeometry } from './connectors'

export type DiagramShapeId = 'process' | 'decision' | 'start-end' | 'document' | 'text' | 'line' | 'arrow'
export const DIAGRAM_SHAPE_CATALOG: readonly { id: DiagramShapeId; label: string; description: string; keywords: string; width: number; height: number }[] = [
  { id: 'process', label: 'Process', description: 'A step or activity', keywords: 'rectangle task action flow', width: 160, height: 96 },
  { id: 'decision', label: 'Decision', description: 'A question or branch', keywords: 'diamond condition choice flow', width: 160, height: 120 },
  { id: 'start-end', label: 'Start / End', description: 'The beginning or end of a flow', keywords: 'terminator capsule rounded flow', width: 160, height: 72 },
  { id: 'document', label: 'Document', description: 'A document or output', keywords: 'paper report file flow', width: 160, height: 112 },
  { id: 'text', label: 'Text', description: 'A free text label', keywords: 'label caption annotation', width: 180, height: 64 },
  { id: 'line', label: 'Line', description: 'An editable line', keywords: 'stroke straight', width: 160, height: 24 },
  { id: 'arrow', label: 'Arrow', description: 'An editable arrow shape', keywords: 'direction pointer straight', width: 160, height: 24 },
]
export const filterDiagramShapes = (query: string) => {
  const words = query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean)
  return DIAGRAM_SHAPE_CATALOG.filter((shape) => words.every((word) => `${shape.label} ${shape.description} ${shape.keywords}`.toLocaleLowerCase().includes(word)))
}
export type DiagramNodeRequest = { shape: DiagramShapeId; id: string; center: BoardPoint; title?: string; width?: number; height?: number; color?: string; strokeColor?: string; textColor?: string }
export type DiagramCommand = { board: BoardModel; nodeId: string; connectorIds: string[] }
export type DiagramCommandResult = StructureResult<DiagramCommand>
export type DiagramCommandOptions = { readOnly?: boolean; ownerId?: string | null }
export type DiagramConnectorStyle = Partial<Pick<BoardConnector, 'style' | 'color' | 'width' | 'dashed' | 'linePattern' | 'startArrow' | 'endArrow' | 'animated' | 'label' | 'labelPosition' | 'relationshipStyle' | 'sourcePortMode' | 'targetPortMode'>>
export type ConnectedSuccessorRequest = { sourceId: string; node: Omit<DiagramNodeRequest, 'center'> & { center?: BoardPoint }; connectorId: string; direction?: ConnectorPort; gap?: number; connector?: DiagramConnectorStyle }
export type InsertDiagramNodeRequest = { connectorId: string; node: Omit<DiagramNodeRequest, 'center'> & { center?: BoardPoint }; downstreamConnectorId: string; fraction?: number }
const success = <T,>(value: T): StructureResult<T> => ({ ok: true, value })
const refuse = (code: string, detail: string, nodeId?: string): { ok: false; issues: { code: string; detail: string; nodeId?: string }[] } => ({ ok: false, issues: [{ code, detail, ...(nodeId ? { nodeId } : {}) }] })
const pointIsFinite = (point: BoardPoint | undefined): point is BoardPoint => Boolean(point && Number.isFinite(point.x) && Number.isFinite(point.y))
const escaped = (text: string) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

/** Shared core geometry, with no new shape enum or SVG string in saved data. */
export function diagramShapeNode(request: DiagramNodeRequest): StructureResult<BoardNode> {
  const shape = DIAGRAM_SHAPE_CATALOG.find((entry) => entry.id === request.shape)
  if (!shape) return refuse('unsupported-diagram-shape', 'Choose one of the labeled diagram shapes.')
  const width = request.width ?? shape.width, height = request.height ?? shape.height, title = request.title ?? shape.label
  if (typeof request.id !== 'string' || !request.id.trim() || !pointIsFinite(request.center) || ![width, height].every((value) => Number.isFinite(value) && value > 0) || typeof title !== 'string') return refuse('invalid-diagram-node', 'Use a fresh identity, a finite position and positive finite dimensions.')
  if ([request.color, request.strokeColor, request.textColor].some((value) => value !== undefined && (typeof value !== 'string' || !value.trim()))) return refuse('invalid-diagram-appearance', 'Use nonempty color values for the diagram appearance.')
  const appearance = { ...(request.color ? { color: request.color } : {}), ...(request.strokeColor ? { strokeColor: request.strokeColor } : {}), ...(request.textColor ? { textColor: request.textColor } : {}) }
  const frame = { x: request.center.x - width / 2, y: request.center.y - height / 2, width, height }
  if (request.shape === 'text') return success({ id: request.id, kind: 'text', ...frame, title, body: `<p>${escaped(title)}</p>`, textColor: '#e7eef5', opacity: 1, ...appearance })
  if (request.shape === 'line' || request.shape === 'arrow') return success({ id: request.id, kind: 'shape', shapeType: request.shape, ...frame, title, body: '', color: 'transparent', strokeColor: '#afc8dc', strokeWidth: 2, opacity: 1, ...(request.shape === 'arrow' ? { arrowMotion: { enabled: false, speed: 'normal', direction: 'forward', style: 'flow' } as const } : {}), ...appearance })
  const kind: DiagramShapeKind = request.shape === 'start-end' ? 'terminator' : request.shape
  const created = createDiagramShape(kind, request.id, frame, title)
  return created.ok ? success({ ...created.value, body: title, diagramShape: request.shape as 'process' | 'decision' | 'start-end' | 'document', ...appearance }) : created
}

function checkedBoard(board: BoardModel, readOnly = false) {
  if (readOnly) return refuse('readonly-diagram', 'This workspace is read-only; no diagram objects were created.')
  const states = diagramProjectionStates(board.nodes)
  if (!states.ok) return states
  // Check the existing snapshot as new content, including dangling/duplicate edges.
  const valid = validateBoardMutation({ ...board, nodes: [], connectors: [] }, board)
  return valid.ok ? states : valid
}
function freshIdentity(board: BoardModel, ids: readonly string[]) {
  const existing = new Set([...board.nodes, ...board.connectors].map((entry) => entry.id))
  return ids.some((id) => typeof id !== 'string' || !id.trim() || existing.has(id)) || new Set(ids).size !== ids.length
    ? refuse('diagram-id-collision', 'Use a fresh identity for every new object and connection; existing objects were retained.') : success(true)
}
function putNode(board: BoardModel, node: BoardNode, ownerId?: string | null, index?: number): StructureResult<BoardModel> {
  if (!ownerId) return success({ ...board, nodes: [...board.nodes, node] })
  const owner = board.nodes.find((entry) => entry.id === ownerId)
  if (!owner || (owner.kind !== 'column' && owner.kind !== 'group')) return refuse('invalid-diagram-owner', 'Choose an existing group, frame or column as the owner.', ownerId)
  const states = diagramProjectionStates(board.nodes)
  if (!states.ok) return states
  if (states.value.get(ownerId)?.locked || states.value.get(ownerId)?.hidden || owner.collapsed) return refuse('uneditable-diagram-owner', 'The destination or its owner is locked, hidden or collapsed.', ownerId)
  if (owner.kind === 'group') return success({ ...board, nodes: [...board.nodes, { ...node, groupId: owner.id }] })
  return insertNodesIntoColumnResult({ ...board, nodes: [...board.nodes, node] }, [node.id], { columnId: owner.id, index: index ?? columnChildren(board, owner.id).length })
}
function finish(before: BoardModel, after: BoardModel, nodeId: string, connectorIds: string[], readOnly = false): DiagramCommandResult {
  const checked = validateBoardMutation(before, after, readOnly)
  return checked.ok ? success({ board: checked.value, nodeId, connectorIds }) : checked
}
export function createDiagramNodeResult(board: BoardModel, request: DiagramNodeRequest, options: DiagramCommandOptions = {}): DiagramCommandResult {
  const checked = checkedBoard(board, options.readOnly), fresh = freshIdentity(board, [request.id])
  if (!checked.ok) return checked
  if (!fresh.ok) return fresh
  const created = diagramShapeNode(request)
  if (!created.ok) return created
  const placed = putNode(board, created.value, options.ownerId)
  return placed.ok ? finish(board, placed.value, request.id, [], options.readOnly) : placed
}

function clearFrame(board: BoardModel, node: BoardNode, direction: ConnectorPort): BoardPoint | null {
  const horizontal = direction === 'left' || direction === 'right'
  for (let index = 0; index < 100; index++) {
    const offset = index ? Math.ceil(index / 2) * (index % 2 ? 1 : -1) : 0
    const candidate = { ...node, x: node.x + (horizontal ? 0 : offset * (node.width + 24)), y: node.y + (horizontal ? offset * (node.height + 24) : 0) }
    if (!board.nodes.some((entry) => entry.kind !== 'group' && entry.kind !== 'column' && candidate.x < entry.x + entry.width + 12 && candidate.x + candidate.width + 12 > entry.x && candidate.y < entry.y + entry.height + 12 && candidate.y + candidate.height + 12 > entry.y)) return { x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2 }
  }
  return null
}
export function createConnectedSuccessorResult(board: BoardModel, request: ConnectedSuccessorRequest, options: DiagramCommandOptions = {}): DiagramCommandResult {
  const checked = checkedBoard(board, options.readOnly), fresh = freshIdentity(board, [request.node.id, request.connectorId])
  if (!checked.ok) return checked
  if (!fresh.ok) return fresh
  const source = board.nodes.find((entry) => entry.id === request.sourceId), state = checked.value.get(request.sourceId)
  if (!source || !state) return refuse('missing-diagram-source', 'Select an existing object to create its connected successor.')
  if (state.locked || state.hidden) return refuse('uneditable-diagram-source', 'The source or its owner is locked, hidden or collapsed.', source.id)
  const direction = request.direction ?? 'right', gap = request.gap ?? 80
  if (!['top', 'right', 'bottom', 'left'].includes(direction) || !Number.isFinite(gap) || gap < 0) return refuse('invalid-successor-placement', 'Choose a connection side and finite nonnegative spacing.')
  const sample = diagramShapeNode({ ...request.node, center: request.node.center ?? { x: 0, y: 0 } })
  if (!sample.ok) return sample
  const port = portPoint(source, direction), sourceCenter = { x: source.x + source.width / 2, y: source.y + source.height / 2 }, length = Math.hypot(port.x - sourceCenter.x, port.y - sourceCenter.y)
  const nx = (port.x - sourceCenter.x) / length, ny = (port.y - sourceCenter.y) / length, extent = Math.abs(nx) * sample.value.width / 2 + Math.abs(ny) * sample.value.height / 2
  const proposed = request.node.center ?? { x: port.x + nx * (gap + extent), y: port.y + ny * (gap + extent) }
  const candidate = diagramShapeNode({ ...request.node, center: proposed })
  if (!candidate.ok) return candidate
  const center = request.node.center ?? clearFrame(board, candidate.value, direction)
  if (!center) return refuse('no-successor-space', 'There is no clear nearby position; choose a position for the successor.')
  const created = diagramShapeNode({ ...request.node, center })
  if (!created.ok) return created
  const ownerId = options.ownerId !== undefined ? options.ownerId : source.groupId ?? source.parentColumnId
  const placed = putNode(board, created.value, ownerId, source.parentColumnId === ownerId ? (source.columnOrder ?? 0) + 1 : undefined)
  if (!placed.ok) return placed
  const target = placed.value.nodes.find((entry) => entry.id === request.node.id)!, nextSource = placed.value.nodes.find((entry) => entry.id === source.id)!
  const edge: BoardConnector = { style: 'elbow', color: '#60a5fa', width: 2, dashed: false, startArrow: false, endArrow: true, animated: false, ...request.connector, id: request.connectorId, sourceId: source.id, targetId: target.id, sourcePort: direction, targetPort: nearestPort(target, portPoint(nextSource, direction)), sourcePortMode: request.connector?.sourcePortMode ?? 'fixed', targetPortMode: request.connector?.targetPortMode ?? 'fixed' }
  if (!['straight', 'elbow', 'curve'].includes(edge.style) || !Number.isFinite(edge.width) || edge.width <= 0 || !connectorGeometry(edge, placed.value.nodes)) return refuse('invalid-successor-connection', 'Use a supported route and positive finite connection width.')
  return finish(board, { ...placed.value, connectors: [...placed.value.connectors, edge] }, target.id, [edge.id], options.readOnly)
}

function routeFraction(geometry: ConnectorGeometry, point: BoardPoint) { return projectConnectorLabelPosition(geometry, point).t }
function commonOwner(board: BoardModel, edge: BoardConnector) {
  const source = board.nodes.find((node) => node.id === edge.sourceId), target = board.nodes.find((node) => node.id === edge.targetId)
  const a = source?.groupId ?? source?.parentColumnId, b = target?.groupId ?? target?.parentColumnId
  return a && a === b ? a : undefined
}
/** Old ID/label stay on source→inserted; a fresh downstream ID retains the old
 * target and end arrow. Only the two outside arrowheads survive. Labels retain
 * world position, including unknown label metadata. Straight routes remain
 * straight; elbow waypoints are partitioned; automatic curves reroute as two
 * curves (their current model stores no independently editable cubic handles). */
export function insertDiagramNodeOnConnectorResult(board: BoardModel, request: InsertDiagramNodeRequest, options: DiagramCommandOptions = {}): DiagramCommandResult {
  const checked = checkedBoard(board, options.readOnly), fresh = freshIdentity(board, [request.node.id, request.downstreamConnectorId])
  if (!checked.ok) return checked
  if (!fresh.ok) return fresh
  const edge = board.connectors.find((entry) => entry.id === request.connectorId)
  if (!edge) return refuse('missing-insert-connection', 'Select an existing relationship to insert a node.')
  if ((edge as BoardConnector & { mindMap?: unknown }).mindMap) return refuse('mind-map-insert', 'Use the mind-map child command to extend this branch; its tree relationship was retained.')
  for (const id of [edge.sourceId, edge.targetId].filter((id): id is string => Boolean(id))) if (checked.value.get(id)?.locked || checked.value.get(id)?.hidden) return refuse('uneditable-insert-endpoint', 'A relationship endpoint or its owner is locked, hidden or collapsed.', id)
  const original = connectorGeometry(edge, board.nodes)
  if (!original) return refuse('invalid-insert-route', 'The relationship endpoints cannot be resolved; no objects were changed.')
  if (original.points.slice(1).reduce((length, point, index) => length + Math.hypot(point.x - original.points[index].x, point.y - original.points[index].y), 0) < .001) return refuse('zero-insert-route', 'This relationship has no visible route length to insert into.')
  const fraction = request.fraction ?? (request.node.center ? routeFraction(original, request.node.center) : .5)
  if (!Number.isFinite(fraction) || fraction <= 0 || fraction >= 1) return refuse('invalid-insert-position', 'Insert between the relationship endpoints, away from its start and end.')
  const created = diagramShapeNode({ ...request.node, center: request.node.center ?? pointAlongRoute(original.points, fraction) })
  if (!created.ok) return created
  const ownerId = options.ownerId !== undefined ? options.ownerId : commonOwner(board, edge), target = board.nodes.find((node) => node.id === edge.targetId)
  const placed = putNode(board, created.value, ownerId, target && ownerId && target.parentColumnId === ownerId ? target.columnOrder : undefined)
  if (!placed.ok) return placed
  const inserted = placed.value.nodes.find((node) => node.id === request.node.id)!, center = { x: inserted.x + inserted.width / 2, y: inserted.y + inserted.height / 2 }
  const placedEdge = placed.value.connectors.find((entry) => entry.id === edge.id)!, route = connectorGeometry(placedEdge, placed.value.nodes)
  if (!route) return refuse('invalid-insert-route', 'The arranged relationship cannot be resolved; no objects were changed.')
  const split = routeFraction(route, center), before = pointAlongRoute(route.points, Math.max(0, split - .01)), after = pointAlongRoute(route.points, Math.min(1, split + .01))
  const incoming: BoardConnector = { ...placedEdge, targetId: inserted.id, targetPort: nearestPort(inserted, before), targetPortMode: 'fixed', endArrow: false }
  delete incoming.targetPoint
  const outgoing: BoardConnector = { ...placedEdge, id: request.downstreamConnectorId, sourceId: inserted.id, sourcePort: nearestPort(inserted, after), sourcePortMode: 'fixed', startArrow: false }
  delete outgoing.sourcePoint; delete outgoing.label; delete outgoing.labelPosition
  if (edge.style === 'elbow') {
    // Keep exact old manual waypoints outside the inserted frame, on their side.
    const outside = (point: BoardPoint) => point.x < inserted.x || point.x > inserted.x + inserted.width || point.y < inserted.y || point.y > inserted.y + inserted.height
    const points = route.manual ? placedEdge.bendPoints ?? [] : route.points.slice(1, -1)
    incoming.bendPoints = points.filter((point) => outside(point) && routeFraction(route, point) < split).map((point) => ({ ...point }))
    outgoing.bendPoints = points.filter((point) => outside(point) && routeFraction(route, point) >= split).map((point) => ({ ...point }))
  }
  if (edge.label !== undefined || edge.labelPosition !== undefined) {
    const nextGeometry = connectorGeometry(incoming, placed.value.nodes)
    if (!nextGeometry) return refuse('invalid-insert-label', 'The source segment could not preserve the relationship label.')
    incoming.labelPosition = { ...edge.labelPosition, ...projectConnectorLabelPosition(nextGeometry, connectorLabelPoint(edge, original)) }
  }
  const connectors = placed.value.connectors.flatMap((entry) => entry.id === edge.id ? [incoming, outgoing] : [entry])
  return finish(board, { ...placed.value, connectors }, inserted.id, [incoming.id, outgoing.id], options.readOnly)
}

import type { BoardConnector, BoardNode, BoardPoint, VectorPathPoint } from '../model/project'

/** Diagram relationships are deliberately separate from board/folder ownership.
 * This optional extension uses the existing JSON node records, not a schema bump. */
export type MindMapMembership = { version: 1; treeId: string; parentId?: string; order: number; collapsed?: boolean }
export type DiagramNode = BoardNode & { hidden?: boolean; mindMap?: MindMapMembership }
export type DiagramConnector = BoardConnector & { mindMap?: { version: 1; treeId: string; childId: string } }
export type StructureIssue = { code: string; nodeId?: string; detail: string }
export type StructureResult<T> = { ok: true; value: T } | { ok: false; issues: StructureIssue[] }
export type ContainerOwner = { kind: 'group' | 'column'; id: string }
const fail = <T = never>(code: string, detail: string, nodeId?: string): StructureResult<T> => ({ ok: false, issues: [{ code, detail, ...(nodeId ? { nodeId } : {}) }] })
const success = <T>(value: T): StructureResult<T> => ({ ok: true, value })
const ownerId = (node: BoardNode) => node.groupId || node.parentColumnId
const finite = (value: number) => typeof value === 'number' && Number.isFinite(value)
const clone = <T>(value: T): T => structuredClone(value)

/** Do not guess at conflicting legacy ownership. Reject it and leave the source
 * untouched so a caller can offer an explicit repair, not silently lose members. */
export function validateContainerOwnership(nodes: readonly DiagramNode[]): StructureResult<Map<string, DiagramNode>> {
  const byId = new Map<string, DiagramNode>(), issues: StructureIssue[] = []
  for (const node of nodes) {
    if (!node.id || typeof node.id !== 'string') issues.push({ code: 'invalid-id', detail: 'Every object needs a nonempty string identity.' })
    else if (byId.has(node.id)) issues.push({ code: 'duplicate-id', nodeId: node.id, detail: 'Object identities must be unique.' })
    else byId.set(node.id, node)
    if (node.groupId && node.parentColumnId) issues.push({ code: 'ambiguous-owner', nodeId: node.id, detail: 'An object cannot belong to both a freeform group/frame and a column.' })
    if (node.containerRole && node.kind !== 'group') issues.push({ code: 'invalid-container-role', nodeId: node.id, detail: 'Only a group-kind object can declare group/frame treatment.' })
  }
  for (const node of nodes) {
    const id = ownerId(node)
    if (!id) continue
    const parent = byId.get(id)
    if (!parent) issues.push({ code: 'missing-owner', nodeId: node.id, detail: `Owner ${id} is not on this board.` })
    else if (id === node.id) issues.push({ code: 'self-owner', nodeId: node.id, detail: 'An object cannot own itself.' })
    else if ((node.groupId && parent.kind !== 'group') || (node.parentColumnId && parent.kind !== 'column')) issues.push({ code: 'wrong-owner-kind', nodeId: node.id, detail: 'Membership must reference the matching group/frame or column kind.' })
  }
  // Each object has at most one owner. Walking previously completed chains is
  // linear and avoids recursion overflow on deeply nested imported diagrams.
  const complete = new Set<string>()
  for (const node of nodes) {
    if (complete.has(node.id)) continue
    const chain: string[] = [], visiting = new Set<string>()
    let current: DiagramNode | undefined = node
    while (current && !complete.has(current.id)) {
      if (visiting.has(current.id)) { issues.push({ code: 'ownership-cycle', nodeId: current.id, detail: 'Container ownership contains a cycle.' }); break }
      visiting.add(current.id); chain.push(current.id)
      current = byId.get(ownerId(current) || '')
    }
    chain.forEach((id) => complete.add(id))
  }
  return issues.length ? { ok: false, issues } : success(byId)
}

export function containerDescendantIds(nodes: readonly DiagramNode[], roots: readonly string[]): StructureResult<string[]> {
  const valid = validateContainerOwnership(nodes)
  if (!valid.ok) return valid
  const selected = new Set(roots)
  for (const id of selected) if (!valid.value.has(id)) return fail('missing-object', `Object ${id} is not on this board.`, id)
  const children = new Map<string, string[]>()
  for (const node of nodes) if (ownerId(node)) { const siblings = children.get(ownerId(node)!) || []; siblings.push(node.id); children.set(ownerId(node)!, siblings) }
  const queue = [...selected]
  for (let cursor = 0; cursor < queue.length; cursor++) for (const child of children.get(queue[cursor]) || []) if (!selected.has(child)) { selected.add(child); queue.push(child) }
  return success(nodes.filter((node) => selected.has(node.id)).map((node) => node.id))
}

export function containerState(nodes: readonly DiagramNode[], id: string): StructureResult<{ locked: boolean; hidden: boolean; ancestors: string[] }> {
  const valid = validateContainerOwnership(nodes)
  if (!valid.ok) return valid
  return indexedContainerState(valid.value, id)
}

function indexedContainerState(byId: Map<string, DiagramNode>, id: string): StructureResult<{ locked: boolean; hidden: boolean; ancestors: string[] }> {
  const node = byId.get(id)
  if (!node) return fail('missing-object', `Object ${id} is not on this board.`, id)
  const ancestors: string[] = []
  let locked = Boolean(node.locked), hidden = Boolean(node.hidden), current = node
  while (ownerId(current)) {
    current = byId.get(ownerId(current)!)!
    ancestors.push(current.id); locked ||= Boolean(current.locked); hidden ||= Boolean(current.hidden || current.collapsed)
  }
  return success({ locked, hidden, ancestors })
}

export function diagramState(nodes: readonly DiagramNode[], id: string): StructureResult<{ locked: boolean; hidden: boolean; containerAncestors: string[]; mindMapAncestors: string[] }> {
  const containers = validateContainerOwnership(nodes), trees = validateMindMap(nodes)
  if (!containers.ok) return containers
  if (!trees.ok) return trees
  return indexedDiagramState(containers.value, trees.value, id)
}

function indexedDiagramState(containers: Map<string, DiagramNode>, trees: Map<string, DiagramNode>, id: string): StructureResult<{ locked: boolean; hidden: boolean; containerAncestors: string[]; mindMapAncestors: string[] }> {
  const own = indexedContainerState(containers, id)
  if (!own.ok) return own
  let { locked, hidden } = own.value
  const mindMapAncestors: string[] = []
  let current = containers.get(id)!
  while (current.mindMap?.parentId) {
    current = trees.get(current.mindMap.parentId)!
    const state = indexedContainerState(containers, current.id)
    if (!state.ok) return state
    mindMapAncestors.push(current.id); locked ||= state.value.locked; hidden ||= state.value.hidden || Boolean(current.mindMap?.collapsed)
  }
  return success({ locked, hidden, containerAncestors: own.value.ancestors, mindMapAncestors })
}

function editableSet(nodes: readonly DiagramNode[], ids: readonly string[]): StructureResult<string[]> {
  const expanded = containerDescendantIds(nodes, ids)
  if (!expanded.ok) return expanded
  const valid = validateContainerOwnership(nodes)
  if (!valid.ok) return valid
  const trees = validateMindMap(nodes)
  if (!trees.ok) return trees
  // A hidden child must not move accidentally when a visible owner is moved.
  for (const id of expanded.value) {
    const state = indexedDiagramState(valid.value, trees.value, id)
    if (!state.ok) return state
    if (state.value.locked) return fail('locked-object', 'The object or its container is locked; the whole command was cancelled.', id)
    if (state.value.hidden) return fail('hidden-object', 'The object or its container is hidden/collapsed; the whole command was cancelled.', id)
  }
  return expanded
}

/** Only the topmost requested roots are reparented; their descendants keep their
 * internal ownership. World-space geometry is never laid out implicitly here. */
export function reparentContainerNodes<T extends DiagramNode>(nodes: readonly T[], ids: readonly string[], owner?: ContainerOwner): StructureResult<T[]> {
  const editable = editableSet(nodes, ids)
  if (!editable.ok) return editable
  const valid = validateContainerOwnership(nodes)
  if (!valid.ok) return valid
  const requested = new Set(ids), roots = new Set(ids.filter((id) => {
    let node = valid.value.get(id)!
    while (ownerId(node)) { if (requested.has(ownerId(node)!)) return false; node = valid.value.get(ownerId(node)!)! }
    return true
  }))
  if (owner) {
    const target = valid.value.get(owner.id)
    if (!target) return fail('missing-owner', `Owner ${owner.id} is not on this board.`)
    if (target.kind !== owner.kind) return fail('wrong-owner-kind', 'The requested owner does not have the matching container kind.', owner.id)
    if (editable.value.includes(owner.id)) return fail('ownership-cycle', 'An object cannot be reparented inside its own descendants.', owner.id)
    const state = containerState(nodes, owner.id)
    if (!state.ok) return state
    if (state.value.locked || state.value.hidden) return fail('uneditable-owner', 'The destination container is locked or hidden.', owner.id)
  }
  const existingOrders = owner?.kind === 'column' ? nodes.filter((node) => node.parentColumnId === owner.id && !roots.has(node.id)).map((node) => finite(node.columnOrder!) ? node.columnOrder! : 0) : []
  let nextOrder = existingOrders.length ? Math.max(...existingOrders) + 1 : 0
  const next = nodes.map((node) => {
    if (!roots.has(node.id)) return node
    const moved = { ...node }; delete moved.groupId; delete moved.parentColumnId; delete moved.columnOrder
    if (owner?.kind === 'group') moved.groupId = owner.id
    else if (owner?.kind === 'column') { moved.parentColumnId = owner.id; moved.columnOrder = nextOrder++ }
    return moved
  })
  const checked = validateContainerOwnership(next)
  return checked.ok ? success(next) : checked
}

/** One atomic model command. Routes with both attached endpoints moved, or one
 * moved attachment plus one detached anchor, travel with the subtree. Two-object
 * boundary routes and wholly detached edges stay fixed-world. */
export function moveContainerWithDescendants<T extends DiagramNode, E extends BoardConnector>(nodes: readonly T[], connectors: readonly E[], ids: readonly string[], delta: BoardPoint): StructureResult<{ nodes: T[]; connectors: E[]; movedIds: string[] }> {
  if (!finite(delta.x) || !finite(delta.y)) return fail('invalid-delta', 'Movement must use finite board-space coordinates.')
  const editable = editableSet(nodes, ids)
  if (!editable.ok) return editable
  const moved = new Set(editable.value), edgeIds = new Set<string>(), nodeIds = new Set(nodes.map(node => node.id))
  for (const edge of connectors) {
    if (edgeIds.has(edge.id)) return fail('duplicate-connector', 'Connection identities must be unique.')
    edgeIds.add(edge.id)
    if ((edge.sourceId && !nodeIds.has(edge.sourceId)) || (edge.targetId && !nodeIds.has(edge.targetId))) return fail('missing-endpoint', `Connection ${edge.id} references a missing object.`)
    if (edge.bendPoints?.some((point) => !finite(point.x) || !finite(point.y))) return fail('invalid-route', `Connection ${edge.id} has a non-finite manual waypoint.`)
    for (const point of [edge.sourcePoint, edge.targetPoint]) if (point && (!finite(point.x) || !finite(point.y))) return fail('invalid-endpoint', `Connection ${edge.id} has a non-finite detached anchor.`)
  }
  const shifted = nodes.map((node) => moved.has(node.id) ? { ...node, x: node.x + delta.x, y: node.y + delta.y } : node)
  if (shifted.some((node) => !finite(node.x) || !finite(node.y))) return fail('invalid-geometry', 'A movement would produce non-finite object geometry.')
  const translate = (point: BoardPoint) => ({ ...point, x: point.x + delta.x, y: point.y + delta.y })
  const edges = connectors.map((edge) => {
    const sourceMoved = Boolean(edge.sourceId && moved.has(edge.sourceId)), targetMoved = Boolean(edge.targetId && moved.has(edge.targetId))
    const sourceDetached = !edge.sourceId && Boolean(edge.sourcePoint), targetDetached = !edge.targetId && Boolean(edge.targetPoint)
    const internal = (sourceMoved && targetMoved) || (sourceMoved && targetDetached) || (targetMoved && sourceDetached)
    if (!internal) return edge
    return { ...edge, ...(edge.bendPoints ? { bendPoints: edge.bendPoints.map(translate) } : {}), ...(sourceDetached ? { sourcePoint: translate(edge.sourcePoint!) } : {}), ...(targetDetached ? { targetPoint: translate(edge.targetPoint!) } : {}) }
  })
  if (edges.some((edge) => [...(edge.bendPoints || []), ...(edge.sourcePoint ? [edge.sourcePoint] : []), ...(edge.targetPoint ? [edge.targetPoint] : [])].some((point) => !finite(point.x) || !finite(point.y)))) return fail('invalid-route', 'Movement would produce non-finite route geometry.')
  return success({ nodes: shifted, connectors: edges, movedIds: editable.value })
}

export function validateMindMap(nodes: readonly DiagramNode[], treeId?: string): StructureResult<Map<string, DiagramNode>> {
  const ownership = validateContainerOwnership(nodes)
  if (!ownership.ok) return ownership
  const members = nodes.filter((node) => node.mindMap && (!treeId || node.mindMap.treeId === treeId)), byId = new Map(members.map((node) => [node.id, node])), issues: StructureIssue[] = []
  const roots = new Map<string, string[]>(), siblingOrders = new Set<string>()
  if (treeId && !members.length) return fail('missing-tree', `Mind-map tree ${treeId} is not on this board.`)
  for (const node of members) {
    const data = node.mindMap!
    if (node.kind === 'group' || node.kind === 'column' || node.kind === 'board-link') issues.push({ code: 'invalid-mind-map-kind', nodeId: node.id, detail: 'A mind-map branch is a content object, not a container or board portal.' })
    if (data.version !== 1 || !data.treeId || typeof data.treeId !== 'string' || !Number.isSafeInteger(data.order) || data.order < 0) issues.push({ code: 'invalid-mind-map', nodeId: node.id, detail: 'Mind-map membership needs version 1, a tree ID and a nonnegative integer order.' })
    const orderKey = JSON.stringify([data.treeId, data.parentId || '', data.order])
    if (siblingOrders.has(orderKey)) issues.push({ code: 'duplicate-branch-order', nodeId: node.id, detail: 'Sibling branch orders must be unique.' })
    siblingOrders.add(orderKey)
    if (!data.parentId) { const list = roots.get(data.treeId) || []; list.push(node.id); roots.set(data.treeId, list) }
    else {
      const parent = byId.get(data.parentId)
      if (!parent || parent.mindMap?.treeId !== data.treeId) issues.push({ code: 'missing-mind-map-parent', nodeId: node.id, detail: 'A branch must reference a parent within its own tree.' })
      if (data.parentId === node.id) issues.push({ code: 'mind-map-cycle', nodeId: node.id, detail: 'A branch cannot parent itself.' })
    }
  }
  for (const id of new Set(members.map((node) => node.mindMap!.treeId))) if ((roots.get(id)?.length || 0) !== 1) issues.push({ code: 'mind-map-root-count', detail: `Tree ${id} must have exactly one root.` })
  const complete = new Set<string>()
  for (const node of members) {
    const visiting = new Set<string>(), chain: string[] = []
    let current: DiagramNode | undefined = node
    while (current && !complete.has(current.id)) {
      if (visiting.has(current.id)) { issues.push({ code: 'mind-map-cycle', nodeId: current.id, detail: 'Mind-map parenting contains a cycle.' }); break }
      visiting.add(current.id); chain.push(current.id); current = byId.get(current.mindMap?.parentId || '')
    }
    chain.forEach((id) => complete.add(id))
  }
  return issues.length ? { ok: false, issues } : success(byId)
}

function orderedChildren(nodes: readonly DiagramNode[], parentId: string): DiagramNode[] { return nodes.filter((node) => node.mindMap?.parentId === parentId).sort((a, b) => a.mindMap!.order - b.mindMap!.order || a.id.localeCompare(b.id)) }
export function mindMapBranchIds(nodes: readonly DiagramNode[], id: string): StructureResult<string[]> {
  const node = nodes.find((entry) => entry.id === id)
  if (!node?.mindMap) return fail('missing-branch', 'The requested object is not a mind-map branch.', id)
  const valid = validateMindMap(nodes, node.mindMap.treeId)
  if (!valid.ok) return valid
  const queue = [id]
  for (let index = 0; index < queue.length; index++) queue.push(...orderedChildren([...valid.value.values()], queue[index]).map((child) => child.id))
  return success(queue)
}

/** Derived visibility; no content is removed or recovery records modified. */
export function visibleDiagramNodeIds(nodes: readonly DiagramNode[]): StructureResult<string[]> {
  const containers = validateContainerOwnership(nodes), trees = validateMindMap(nodes)
  if (!containers.ok) return containers
  if (!trees.ok) return trees
  const visible = nodes.filter((node) => {
    const state = indexedDiagramState(containers.value, trees.value, node.id)
    return state.ok && !state.value.hidden
  })
  return success(visible.map((node) => node.id))
}

export type DiagramProjectionState = { locked: boolean; hidden: boolean }

/** Renderer-facing state is derived from the same ownership/tree policy as
 * editing. Validate each graph once for the scene, rather than once per object;
 * callers must fail closed if the imported hierarchy is invalid. */
export function diagramProjectionStates(nodes: readonly DiagramNode[]): StructureResult<Map<string, DiagramProjectionState>> {
  const containers = validateContainerOwnership(nodes), trees = validateMindMap(nodes)
  if (!containers.ok) return containers
  if (!trees.ok) return trees
  const states = new Map<string, DiagramProjectionState>()
  for (const node of nodes) {
    const state = indexedDiagramState(containers.value, trees.value, node.id)
    if (!state.ok) return state
    states.set(node.id, { locked: state.value.locked, hidden: state.value.hidden })
  }
  return success(states)
}

/** Mind-map edges are one persistent identity per child, not regenerated from
 * endpoints during render. Unrelated connectors are retained byte-for-byte. */
export function validateMindMapConnectors(nodes: readonly DiagramNode[], connectors: readonly DiagramConnector[], treeId: string): StructureResult<true> {
  const valid = validateMindMap(nodes, treeId)
  if (!valid.ok) return valid
  const seen = new Set<string>(), edgeIds = new Set<string>(), issues: StructureIssue[] = []
  for (const edge of connectors) {
    if (edgeIds.has(edge.id)) issues.push({ code: 'duplicate-connector', detail: `Connection identity ${edge.id} is duplicated.` })
    edgeIds.add(edge.id)
    if (edge.mindMap?.treeId !== treeId) continue
    const child = valid.value.get(edge.mindMap.childId)
    if (edge.mindMap.version !== 1 || !child?.mindMap?.parentId || edge.targetId !== child.id || edge.sourceId !== child.mindMap.parentId || seen.has(child.id)) issues.push({ code: 'invalid-mind-map-edge', detail: `Connection ${edge.id} does not uniquely match its child branch.` })
    else seen.add(child.id)
  }
  for (const node of valid.value.values()) if (node.mindMap!.parentId && !seen.has(node.id)) issues.push({ code: 'missing-mind-map-edge', nodeId: node.id, detail: 'Every non-root branch needs one stable identity connection.' })
  return issues.length ? { ok: false, issues } : success(true)
}

export function reparentMindMapBranch<T extends DiagramNode, E extends DiagramConnector>(nodes: readonly T[], connectors: readonly E[], id: string, parentId: string, order?: number): StructureResult<{ nodes: T[]; connectors: E[] }> {
  const branch = mindMapBranchIds(nodes, id)
  if (!branch.ok) return branch
  const node = nodes.find((entry) => entry.id === id)!, parent = nodes.find((entry) => entry.id === parentId)
  if (!node.mindMap!.parentId) return fail('root-reparent', 'The tree root cannot be reparented.', id)
  if (!parent?.mindMap || parent.mindMap.treeId !== node.mindMap!.treeId) return fail('cross-tree-reparent', 'Branches can only be reparented within their own tree.', id)
  if (branch.value.includes(parentId)) return fail('mind-map-cycle', 'A branch cannot be reparented inside its descendants.', id)
  const safe = editableSet(nodes, [...branch.value, parentId])
  if (!safe.ok) return safe
  const edges = validateMindMapConnectors(nodes, connectors, node.mindMap!.treeId)
  if (!edges.ok) return edges
  if (order !== undefined && (!Number.isSafeInteger(order) || order < 0)) return fail('invalid-branch-order', 'Branch placement must be a nonnegative integer index.', id)
  const newSiblings = orderedChildren(nodes, parentId).filter((entry) => entry.id !== id)
  newSiblings.splice(Math.min(order ?? newSiblings.length, newSiblings.length), 0, node)
  const orders = new Map(newSiblings.map((entry, index) => [entry.id, index]))
  if (node.mindMap!.parentId !== parentId) orderedChildren(nodes, node.mindMap!.parentId!).filter((entry) => entry.id !== id).forEach((entry, index) => orders.set(entry.id, index))
  const next = nodes.map((entry) => orders.has(entry.id) ? { ...entry, mindMap: { ...entry.mindMap!, order: orders.get(entry.id)!, ...(entry.id === id ? { parentId } : {}) } } : entry)
  const nextEdges = connectors.map((edge) => edge.mindMap?.treeId === node.mindMap!.treeId && edge.mindMap.childId === id ? { ...edge, sourceId: parentId, sourcePoint: undefined } : edge)
  const checked = validateMindMapConnectors(next, nextEdges, node.mindMap!.treeId)
  return checked.ok ? success({ nodes: next, connectors: nextEdges }) : checked
}

/** Deterministic right-growing tree layout. Hidden/collapsed descendants keep
 * their previous coordinates; visible locked objects cancel the whole command. */
export function layoutMindMap<T extends DiagramNode>(nodes: readonly T[], treeId: string, options: { origin?: BoardPoint; horizontalGap?: number; verticalGap?: number } = {}): StructureResult<T[]> {
  const valid = validateMindMap(nodes, treeId)
  if (!valid.ok) return valid
  const visibility = visibleDiagramNodeIds(nodes)
  if (!visibility.ok) return visibility
  const visible = new Set(visibility.value), members = [...valid.value.values()].filter((node) => visible.has(node.id)), root = [...valid.value.values()].find((node) => !node.mindMap!.parentId)!
  const allNodes = new Map(nodes.map((node) => [node.id, node]))
  const hGap = options.horizontalGap ?? 80, vGap = options.verticalGap ?? 24, origin = options.origin || { x: root.x, y: root.y }
  if (!finite(hGap) || hGap < 0 || !finite(vGap) || vGap < 0 || !finite(origin.x) || !finite(origin.y)) return fail('invalid-layout', 'Layout origin and nonnegative spacing must be finite.')
  for (const node of members) {
    const state = indexedDiagramState(allNodes, valid.value, node.id)
    if (!state.ok) return state
    if (state.value.locked) return fail('locked-object', 'A visible branch is locked; the whole layout was cancelled.', node.id)
    if (!finite(node.width) || !finite(node.height) || node.width <= 0 || node.height <= 0) return fail('invalid-geometry', 'Visible branches need positive finite dimensions.', node.id)
  }
  if (!visible.has(root.id)) return success([...nodes])
  const children = new Map(members.map((node) => [node.id, orderedChildren(members, node.id)])), traversal = [root]
  for (let index = 0; index < traversal.length; index++) traversal.push(...children.get(traversal[index].id)!)
  const spans = new Map<string, number>()
  for (const node of [...traversal].reverse()) { const list = children.get(node.id)!; spans.set(node.id, Math.max(node.height, list.reduce((sum, child) => sum + spans.get(child.id)!, 0) + Math.max(0, list.length - 1) * vGap)) }
  const placed = new Map<string, BoardPoint>(), queue = [{ node: root, x: origin.x, top: origin.y + root.height / 2 - spans.get(root.id)! / 2 }]
  for (let index = 0; index < queue.length; index++) {
    const { node, x, top } = queue[index], span = spans.get(node.id)!, list = children.get(node.id)!
    placed.set(node.id, { x, y: top + span / 2 - node.height / 2 })
    const childrenSpan = list.reduce((sum, child) => sum + spans.get(child.id)!, 0) + Math.max(0, list.length - 1) * vGap
    let childTop = top + (span - childrenSpan) / 2
    for (const child of list) { queue.push({ node: child, x: x + node.width + hGap, top: childTop }); childTop += spans.get(child.id)! + vGap }
  }
  if ([...placed.values()].some((point) => !finite(point.x) || !finite(point.y))) return fail('invalid-layout', 'Layout would exceed finite geometry.')
  return success(nodes.map((node) => placed.has(node.id) ? { ...node, ...placed.get(node.id)! } : node))
}

export function createMindMapTemplate(namespace: string, origin: BoardPoint = { x: 0, y: 0 }, existingIds: readonly string[] = []): StructureResult<{ nodes: DiagramNode[]; connectors: DiagramConnector[]; treeId: string }> {
  if (!namespace || typeof namespace !== 'string' || namespace.length > 200) return fail('invalid-namespace', 'Use a fresh nonempty namespace no longer than 200 characters for each template instance.')
  const treeId = `${namespace}:tree`, existing = new Set(existingIds), nodes: DiagramNode[] = [], connectors: DiagramConnector[] = []
  const add = (title: string, parentIndex?: number, order = 0) => {
    const index = nodes.length, id = `${namespace}:node:${index}`
    const parentId = parentIndex === undefined ? undefined : `${namespace}:node:${parentIndex}`
    nodes.push({ id, kind: 'note', title, body: '', x: origin.x, y: origin.y, width: 180, height: 90, color: parentId ? '#405b78' : '#38516d', opacity: 1, mindMap: { version: 1, treeId, ...(parentId ? { parentId } : {}), order } })
    if (parentId) connectors.push({ id: `${namespace}:edge:${index}`, sourceId: parentId, targetId: id, sourcePort: 'right', targetPort: 'left', sourcePortMode: 'adaptive', targetPortMode: 'adaptive', style: 'elbow', color: '#60a5fa', width: 2, dashed: false, startArrow: false, endArrow: false, animated: false, mindMap: { version: 1, treeId, childId: id } })
    return index
  }
  add('Project')
  const branches = ['Research', 'Design', 'Build', 'Review'].map((title, index) => add(title, 0, index))
  const leaves: number[] = []
  for (const parentIndex of branches) for (let order = 0; order < 3; order++) leaves.push(add(['Inputs', 'Work', 'Checks'][order], parentIndex, order))
  leaves.slice(0, 3).forEach((parentIndex) => add('Detail', parentIndex))
  for (const item of [...nodes, ...connectors]) if (existing.has(item.id)) return fail('template-id-collision', `Template identity ${item.id} already exists; generate another namespace.`)
  const laidOut = layoutMindMap(nodes, treeId, { origin })
  return laidOut.ok ? success({ nodes: laidOut.value, connectors, treeId }) : laidOut
}

export function createProcessMapTemplate(namespace: string, origin: BoardPoint = { x: 0, y: 0 }, existingIds: readonly string[] = []): StructureResult<{ nodes: DiagramNode[]; connectors: DiagramConnector[] }> {
  if (!namespace || typeof namespace !== 'string' || namespace.length > 200) return fail('invalid-namespace', 'Use a fresh nonempty namespace no longer than 200 characters for each template instance.')
  const existing = new Set(existingIds)
  const titles = ['Start', 'Collect references', 'Explore ideas', 'Choose direction', 'Plan work', 'Build draft', 'Review', 'Refine', 'Document', 'Finish']
  const nodes: DiagramNode[] = []
  for (let index = 0; index < titles.length; index++) {
    const kind: DiagramShapeKind = index === 0 || index === 9 ? 'terminator' : index === 3 || index === 6 ? 'decision' : index === 8 ? 'document' : 'process'
    const id = `${namespace}:node:${index}`
    if (existing.has(id)) return fail('template-id-collision', `Template identity ${id} already exists; generate another namespace.`)
    const shape = createDiagramShape(kind, id, { x: origin.x + (index % 5) * 240, y: origin.y + Math.floor(index / 5) * 200, width: 180, height: 100 }, titles[index])
    if (!shape.ok) return shape
    nodes.push({ ...shape.value, body: titles[index], diagramShape: kind === 'terminator' ? 'start-end' : kind })
  }
  const connectors: DiagramConnector[] = []
  for (let index = 0; index < nodes.length - 1; index++) {
    const edgeId = `${namespace}:edge:${index}`
    if (existing.has(edgeId)) return fail('template-id-collision', `Template identity ${edgeId} already exists; generate another namespace.`)
    connectors.push({
      id: edgeId,
      sourceId: nodes[index].id,
      targetId: nodes[index + 1].id,
      sourcePort: 'right',
      targetPort: 'left',
      sourcePortMode: 'adaptive',
      targetPortMode: 'adaptive',
      style: 'elbow',
      color: '#60a5fa',
      width: 2,
      dashed: false,
      startArrow: false,
      endArrow: true,
      animated: false,
      ...(index === 3 || index === 6 ? { label: 'Continue' } : {})
    })
  }
  return success({ nodes, connectors })
}

export function createSwimlaneTemplate(namespace: string, origin: BoardPoint = { x: 0, y: 0 }, title = 'Workflow', laneTitles: readonly string[] = ['Research', 'Production', 'Review'], existingIds: readonly string[] = []): StructureResult<{ nodes: DiagramNode[]; connectors: DiagramConnector[] }> {
  if (!namespace || typeof namespace !== 'string' || namespace.length > 200) return fail('invalid-namespace', 'Use a fresh nonempty namespace no longer than 200 characters for each template instance.')
  const existing = new Set(existingIds)
  const trimmedTitle = (title || '').trim()
  const titles = laneTitles && laneTitles.length ? laneTitles : ['Research', 'Production', 'Review']
  if (!trimmedTitle || trimmedTitle.length > 160 || titles.length < 2 || titles.length > 8 || titles.some(t => !t.trim() || t.trim().length > 160)) {
    return fail('invalid-swimlane-spec', 'Name the swimlane and between 2 and 8 lanes, with labels up to 160 characters.')
  }
  const rootId = `${namespace}:frame`
  if (existing.has(rootId)) return fail('template-id-collision', `Template identity ${rootId} already exists; generate another namespace.`)
  const root: DiagramNode = {
    id: rootId,
    kind: 'group',
    containerRole: 'frame',
    diagramRole: 'swimlane',
    title: trimmedTitle,
    x: origin.x,
    y: origin.y,
    width: 960,
    height: 36 + titles.length * 152,
    color: '#405b78'
  }
  const lanes: DiagramNode[] = []
  for (let index = 0; index < titles.length; index++) {
    const laneId = `${namespace}:lane:${index}`
    if (existing.has(laneId)) return fail('template-id-collision', `Template identity ${laneId} already exists; generate another namespace.`)
    lanes.push({
      id: laneId,
      kind: 'group',
      containerRole: 'frame',
      diagramRole: 'lane',
      title: titles[index].trim(),
      groupId: rootId,
      x: origin.x + 18,
      y: origin.y + 48 + index * 152,
      width: 924,
      height: 120,
      color: '#405b78'
    })
  }
  return success({ nodes: [root, ...lanes], connectors: [] })
}

export type DiagramShapeKind = 'process' | 'decision' | 'terminator' | 'document'
/** Original portable geometry; no SVG strings, external libraries or new shape
 * enum values. All four forms remain editable with the current Pen/node tools. */
export function createDiagramShape(kind: DiagramShapeKind, id: string, frame: { x: number; y: number; width: number; height: number }, title?: string): StructureResult<DiagramNode> {
  const { x, y, width: w, height: h } = frame
  if (!id || ![x, y, w, h].every(finite) || w <= 0 || h <= 0) return fail('invalid-shape-frame', 'Diagram shapes require an identity and a finite positive frame.')
  let points: VectorPathPoint[]
  if (kind === 'process') points = [{ x: 0, y: 0 }, { x: w, y: 0 }, { x: w, y: h }, { x: 0, y: h }]
  else if (kind === 'decision') points = [{ x: w / 2, y: 0 }, { x: w, y: h / 2 }, { x: w / 2, y: h }, { x: 0, y: h / 2 }]
  else if (kind === 'terminator') {
    const r = Math.min(w / 2, h / 2), k = .5522847498307936 * r
    points = [{ x: r, y: 0, handleIn: { x: -k, y: 0 } }, { x: w - r, y: 0, handleOut: { x: k, y: 0 } }, { x: w, y: r, handleIn: { x: 0, y: -k } }, { x: w, y: h - r, handleOut: { x: 0, y: k } }, { x: w - r, y: h, handleIn: { x: k, y: 0 } }, { x: r, y: h, handleOut: { x: -k, y: 0 } }, { x: 0, y: h - r, handleIn: { x: 0, y: k } }, { x: 0, y: r, handleOut: { x: 0, y: -k } }]
  } else if (kind === 'document') {
    const r = h * .12
    points = [{ x: 0, y: 0 }, { x: w, y: 0 }, { x: w, y: h - r, handleOut: { x: -w / 6, y: r } }, { x: w / 2, y: h - r, handleIn: { x: w / 6, y: r }, handleOut: { x: -w / 6, y: -r }, handleMode: 'smooth' }, { x: 0, y: h - r, handleIn: { x: w / 6, y: -r } }]
  } else return fail('unsupported-shape', 'Only process, decision, terminator and document shapes are supported.')
  return success({ id, kind: 'shape', ...frame, title: title ?? ({ process: 'Process', decision: 'Decision', terminator: 'Start / End', document: 'Document' })[kind], shapeType: 'path', vectorPath: { version: 1, closed: true, points }, color: '#405b78', strokeColor: '#afc8dc', strokeWidth: 2, opacity: 1, vectorFillRule: 'nonzero', vectorStrokeJoin: 'round', vectorStrokeCap: 'round' })
}

/** A snapshot is plain JSON/structuredClone data. Undo and native persistence
 * belong to the caller; this function does not write a workspace or migrate it. */
export function cloneDiagramSnapshot<T extends DiagramNode, E extends DiagramConnector>(nodes: readonly T[], connectors: readonly E[]): { nodes: T[]; connectors: E[] } { return clone({ nodes: [...nodes], connectors: [...connectors] }) }

export type ContainerPaintOrder = { orderedIds: string[]; zIndexById: Map<string, number> }
const containerPaintLayer = (node: BoardNode) => node.zIndex ?? (node.graphColumn ? 2 : node.kind === 'group' ? 0 : node.kind === 'column' ? 1 : 2)

/** Layers order sibling subtrees, never a child behind its owning container.
 * Ordinals are a render projection; saved zIndex/model order are preserved.
 * Iterative traversal tolerates deeply nested imported ownership trees. */
export function containerPaintOrder(nodes: readonly BoardNode[]): StructureResult<ContainerPaintOrder> {
  const valid = validateContainerOwnership(nodes)
  if (!valid.ok) return valid
  const children = new Map<string | undefined, BoardNode[]>(), index = new Map(nodes.map((node, ordinal) => [node.id, ordinal]))
  for (const node of nodes) {
    if (node.zIndex !== undefined && !Number.isFinite(node.zIndex)) return fail('invalid-layer', 'Object layer values must be finite; paint ordering was cancelled.', node.id)
    const owner = ownerId(node)
    const siblings = children.get(owner) || []
    siblings.push(node); children.set(owner, siblings)
  }
  for (const siblings of children.values()) siblings.sort((a, b) => containerPaintLayer(a) - containerPaintLayer(b) || index.get(a.id)! - index.get(b.id)!)
  const orderedIds: string[] = [], stack = [...(children.get(undefined) || [])].reverse()
  while (stack.length) {
    const node = stack.pop()!
    orderedIds.push(node.id)
    const descendants = children.get(node.id) || []
    for (let cursor = descendants.length - 1; cursor >= 0; cursor--) stack.push(descendants[cursor])
  }
  return success({ orderedIds, zIndexById: new Map(orderedIds.map((id, ordinal) => [id, ordinal])) })
}

import { VirtualList } from '../ui/VirtualList'
import { useEffect, useId, useMemo, useRef, useState } from 'react'
import type { BoardModel, BoardPoint, DiagramTemplate } from '../model/project'
import { mindMapBranchIds } from './diagramStructureCore'
import { captureDiagramTemplate, diagramObjectRows, instantiateDiagramTemplate, runDiagramWorkflow, type DiagramWorkflowCommand, type DiagramWorkflowResult } from './diagramWorkflow'

export type DiagramStructurePanelProps = {
  board: BoardModel
  selectedIds: readonly string[]
  templates: readonly DiagramTemplate[]
  origin: BoardPoint
  readOnly?: boolean
  onPublish: (board: BoardModel, selectedIds: string[]) => boolean
  onSaveTemplate: (template: DiagramTemplate) => boolean
  onSelect: (ids: string[]) => void
  onClose: () => void
}

/** A controlled nonmodal editing surface. Content and template persistence go
 * through the caller's existing publication/history; there is no local journal.
 */
export function DiagramStructurePanel({ board, selectedIds, templates, origin, readOnly = false, onPublish, onSaveTemplate, onSelect, onClose }: DiagramStructurePanelProps) {
  const labelId = useId(), helperId = useId(), createLabelRef = useRef<HTMLInputElement>(null)
  const [newTitle, setNewTitle] = useState('New idea')
  const [nodeLabel, setNodeLabel] = useState('')
  const [parentId, setParentId] = useState('')
  const [templateTitle, setTemplateTitle] = useState('My diagram')
  const [status, setStatus] = useState('')
  const selectedNode = board.nodes.find(node => node.id === selectedIds.at(-1))
  const rows = useMemo(() => diagramObjectRows(board.nodes), [board.nodes])
  const selectedRow = rows.ok ? rows.value.find(row => row.node.id === selectedNode?.id) : undefined
  const editable = !readOnly && selectedRow && !selectedRow.locked && !selectedRow.hidden
  const branch = selectedNode?.mindMap ? mindMapBranchIds(board.nodes, selectedNode.id) : undefined
  const descendants = new Set(branch?.ok ? branch.value : [])
  useEffect(() => { createLabelRef.current?.focus() }, [])
  useEffect(() => { setNodeLabel(selectedNode?.title || ''); setParentId('') }, [selectedNode?.id, selectedNode?.title])

  const namespace = () => `diagram-${crypto.randomUUID()}`
  function publish(result: ReturnType<typeof runDiagramWorkflow> | ReturnType<typeof instantiateDiagramTemplate>, successText: string) {
    if (!result.ok) { setStatus(result.issues[0]?.detail || 'The diagram command was cancelled.'); return false }
    if (!onPublish(result.value.board, result.value.selectedIds)) { setStatus('The board changed or an edit was refused. Your selection and diagram were kept.'); return false }
    setStatus(successText)
    return true
  }
  const run = (command: DiagramWorkflowCommand, text: string) => publish(runDiagramWorkflow(board, command, readOnly), text)
  const createBranch = (kind: 'add-child' | 'add-sibling') => {
    if (!selectedNode) return
    run({ kind, id: selectedNode.id, namespace: namespace(), title: newTitle }, kind === 'add-child' ? 'Child branch added.' : 'Sibling branch added.')
  }
  function saveTemplate() {
    if (readOnly) { setStatus('This workspace is read-only.'); return }
    const result = captureDiagramTemplate(board, selectedIds, `template-${crypto.randomUUID()}`, templateTitle)
    if (!result.ok) { setStatus(result.issues[0]?.detail || 'The template could not be captured.'); return }
    if (!onSaveTemplate(result.value)) { setStatus('The template was not saved; your diagram was kept.'); return }
    setStatus(`Saved ${result.value.title}: ${result.value.nodes.length} objects and ${result.value.connectors.length} internal connections. External links remain on the original board.`)
  }
  function enterBranch(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Enter') return
    event.preventDefault(); event.stopPropagation()
    if (selectedNode?.mindMap) {
      if (!editable) { setStatus('Show and unlock the selected branch before editing it.'); return }
      createBranch(event.shiftKey ? 'add-sibling' : 'add-child')
    } else if (!event.shiftKey) run({ kind: 'new-root', title: newTitle, namespace: namespace(), origin }, 'Mind-map root added.')
  }

  return <aside className="diagram-structure-panel" aria-label="Diagram structure" onKeyDown={event => { if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); onClose() } }}>
    <header>
      <h2 id={labelId}>Diagram structure</h2>
      <button type="button" aria-label="Close diagram structure" onClick={onClose}>Close</button>
    </header>
    <p id={helperId}>Diagram relationships stay on this board. They do not create folders or subboards.</p>
    {readOnly && <p role="status">This workspace is read-only. You can inspect visible objects.</p>}
    <section aria-label="Create diagram">
      <h3>Create</h3>
      <label>New diagram label<input ref={createLabelRef} aria-describedby={helperId} value={newTitle} maxLength={160} disabled={readOnly} onChange={event => setNewTitle(event.target.value)} onKeyDown={enterBranch} /></label>
      <p className="diagram-keyboard-help">In this label field: Enter adds a child to the selected branch; Shift+Enter adds its sibling. With no branch selected, Enter creates a root. Tab moves focus normally.</p>
      <div className="diagram-actions">
        <button type="button" disabled={readOnly} onClick={() => run({ kind: 'new-root', title: newTitle, namespace: namespace(), origin }, 'Mind-map root added.')}>New mind-map root</button>
        <button type="button" disabled={readOnly} onClick={() => run({ kind: 'starter-map', namespace: namespace(), origin }, '20-node mind map added.')}>Add 20-node mind map</button>
        <button type="button" disabled={readOnly} onClick={() => run({ kind: 'process-map', namespace: namespace(), origin }, '10-node process map added.')}>Add process map</button>
        <button type="button" disabled={readOnly} onClick={() => run({ kind: 'swimlane', namespace: namespace(), origin, title: newTitle || 'Workflow' }, 'Swimlane with Research, Production and Review frames added.')}>Add named swimlane</button>
      </div>
      <p>Swimlanes use frame membership. Frames do not clip artwork or automatically rearrange members. Moving a frame carries its members; resizing changes its boundary.</p>
    </section>
    {selectedNode && <section aria-label="Selected diagram object">
      <h3>{selectedNode.title || 'Selected object'}</h3>
      <label>Object label<input value={nodeLabel} maxLength={160} disabled={!editable} onChange={event => setNodeLabel(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') { event.preventDefault(); event.stopPropagation(); run({ kind: 'rename', id: selectedNode.id, title: nodeLabel }, 'Object label updated.') } }} /></label>
      <button type="button" disabled={!editable} onClick={() => run({ kind: 'rename', id: selectedNode.id, title: nodeLabel }, 'Object label updated.')}>Rename object</button>
      {selectedNode.mindMap && <>
        <div className="diagram-actions">
          <button type="button" disabled={!editable || selectedNode.mindMap.collapsed === true} onClick={() => createBranch('add-child')}>Add child branch</button>
          <button type="button" disabled={!editable || !selectedNode.mindMap.parentId} onClick={() => createBranch('add-sibling')}>Add sibling branch</button>
          <button type="button" disabled={!editable} onClick={() => run({ kind: 'layout', id: selectedNode.id }, 'Visible mind-map branches arranged.')}>Arrange mind map</button>
          <button type="button" disabled={!editable} onClick={() => run({ kind: 'collapse', id: selectedNode.id, collapsed: !selectedNode.mindMap?.collapsed }, selectedNode.mindMap?.collapsed ? 'Branch expanded.' : 'Branch collapsed.')}>{selectedNode.mindMap.collapsed ? 'Expand branch' : 'Collapse branch'}</button>
        </div>
        <label>Branch parent<select aria-label="Branch parent" value={parentId} disabled={!editable || !selectedNode.mindMap.parentId} onChange={event => setParentId(event.target.value)}>
          <option value="">Choose a parent</option>
          {board.nodes.filter(node => node.mindMap?.treeId === selectedNode.mindMap?.treeId && !descendants.has(node.id)).map(node => <option key={node.id} value={node.id}>{node.title || node.id}</option>)}
        </select></label>
        <button type="button" disabled={!editable || !selectedNode.mindMap.parentId || !parentId} onClick={() => run({ kind: 'reparent', id: selectedNode.id, parentId }, 'Branch reparented; labels and connection identities retained.')}>Reparent branch</button>
        <div className="diagram-actions" aria-label="Move whole branch">
          {([['Left', -40, 0], ['Right', 40, 0], ['Up', 0, -40], ['Down', 0, 40]] as const).map(([label, x, y]) => <button type="button" key={label} disabled={!editable} aria-label={`Move whole branch ${label.toLowerCase()}`} onClick={() => run({ kind: 'move-branch', id: selectedNode.id, delta: { x, y } }, `Branch moved ${label.toLowerCase()}.`)}>{label}</button>)}
        </div>
      </>}
      {!selectedNode.mindMap && (selectedNode.kind === 'group' || selectedNode.kind === 'column') && <button type="button" disabled={!editable} onClick={() => run({ kind: 'collapse', id: selectedNode.id, collapsed: !selectedNode.collapsed }, selectedNode.collapsed ? 'Container expanded.' : 'Container collapsed.')}>{selectedNode.collapsed ? 'Expand container' : 'Collapse container'}</button>}
      <div className="diagram-actions">
        <button type="button" disabled={!editable} onClick={() => run({ kind: 'layer', id: selectedNode.id, direction: 'front' }, 'Object moved ahead of its siblings.')}>Bring ahead of siblings</button>
        <button type="button" disabled={!editable} onClick={() => run({ kind: 'layer', id: selectedNode.id, direction: 'back' }, 'Object moved behind its siblings.')}>Send behind siblings</button>
      </div>
    </section>}
    <section aria-label="Diagram objects and layers">
      <h3>Objects and layers</h3>
      <p>Layers order siblings. Owned members stay above their container. Hide and lock are saved states; collapse keeps the owner visible.</p>
      {!rows.ok ? <p role="alert">{rows.issues[0]?.detail}</p> : <div className="diagram-object-list">
        <VirtualList items={rows.value} itemKey={row => row.node.id} label="Diagram objects and layers" renderItem={row => <div className="diagram-object-row" key={row.node.id} style={{ paddingInlineStart: row.depth * 12 }}>
          <button type="button" disabled={row.hidden} aria-pressed={selectedIds.includes(row.node.id)} aria-label={`Select diagram object ${row.node.title || row.node.id}`} onClick={() => onSelect([row.node.id])}>{row.node.title || row.node.id}</button>
          <span className="diagram-object-state">{row.node.diagramRole || (row.node.mindMap ? 'branch' : row.node.containerRole || row.node.kind)}{row.hidden ? ' · hidden' : ''}{row.locked ? ' · locked' : ''}</span>
          <label><input type="checkbox" aria-label={`Show diagram object ${row.node.title || row.node.id}`} checked={!row.node.hidden} disabled={readOnly || row.inheritedHidden || row.locked} onChange={event => run({ kind: 'visibility', id: row.node.id, hidden: !event.target.checked }, event.target.checked ? 'Object shown.' : 'Object hidden.')} />Show</label>
          <label><input type="checkbox" aria-label={`Lock diagram object ${row.node.title || row.node.id}`} checked={Boolean(row.node.locked)} disabled={readOnly || row.inheritedLock || row.hidden} onChange={event => run({ kind: 'lock', id: row.node.id, locked: event.target.checked }, event.target.checked ? 'Object locked.' : 'Object unlocked.')} />Lock</label>
          {(row.inheritedLock || row.inheritedHidden) && <span>Owner state applies</span>}
        </div>} />
      </div>}
    </section>
    <section aria-label="Saved diagram templates">
      <h3>Saved local templates</h3>
      <label>Template name<input value={templateTitle} maxLength={160} disabled={readOnly} onChange={event => setTemplateTitle(event.target.value)} /></label>
      <button type="button" disabled={readOnly || selectedIds.length === 0} onClick={saveTemplate}>Save selected diagram as template</button>
      <p>Complete owned regions and branches are captured with internal connections. Board portals and interchange imports are unsupported. Referenced assets stay in this project.</p>
      {templates.length === 0 ? <p>No saved diagrams yet.</p> : <ul>{templates.map(template => <li key={template.id}><span>{template.title}</span><button type="button" aria-label={`Insert diagram template ${template.title}`} disabled={readOnly} onClick={() => publish(instantiateDiagramTemplate(board, template, namespace(), origin, readOnly), `Inserted ${template.title} with fresh object and connection identities.`)}>Insert</button></li>)}</ul>}
    </section>
    <p className="diagram-structure-status" role="status" aria-live="polite">{status}</p>
  </aside>
}

export type { DiagramWorkflowResult }

import type { BoardModel, BoardPoint, DiagramTemplate } from '../model/project'
import { validateBoardMutation } from './boardMutationSafety'
import { containerDescendantIds, containerPaintOrder, createMindMapTemplate, createProcessMapTemplate, createSwimlaneTemplate, diagramState, layoutMindMap, mindMapBranchIds, moveContainerWithDescendants, reparentMindMapBranch, validateContainerOwnership, validateMindMap, validateMindMapConnectors, type DiagramConnector, type DiagramNode, type StructureResult } from './diagramStructureCore'

export type { DiagramTemplate } from '../model/project'
export type DiagramWorkflowResult = { board: BoardModel; selectedIds: string[] }
export type DiagramWorkflowCommand =
  | { kind: 'new-root' | 'starter-map' | 'process-map'; namespace: string; origin: BoardPoint; title?: string }
  | { kind: 'swimlane'; namespace: string; origin: BoardPoint; title: string; laneTitles?: string[] }
  | { kind: 'add-child' | 'add-sibling'; id: string; namespace: string; title: string }
  | { kind: 'rename'; id: string; title: string }
  | { kind: 'collapse'; id: string; collapsed: boolean }
  | { kind: 'reparent'; id: string; parentId: string; order?: number }
  | { kind: 'layout'; id: string }
  | { kind: 'move-branch'; id: string; delta: BoardPoint }
  | { kind: 'visibility'; id: string; hidden: boolean }
  | { kind: 'lock'; id: string; locked: boolean }
  | { kind: 'layer'; id: string; direction: 'front' | 'back' }

const failure = <T = never>(detail: string, code = 'diagram-workflow'): StructureResult<T> => ({ ok: false, issues: [{ code, detail }] })
const success = <T>(value: T): StructureResult<T> => ({ ok: true, value })
const owner = (node: DiagramNode) => node.groupId || node.parentColumnId
const validTitle = (value: string) => typeof value === 'string' && value.trim().length > 0 && value.trim().length <= 160
const existingIds = (board: BoardModel) => [...board.nodes.map(node => node.id), ...board.connectors.map(edge => edge.id)]
const finitePoint = (point: BoardPoint) => Number.isFinite(point.x) && Number.isFinite(point.y)

/** Complete source-graph validation. The caller still owns the one existing
 * board/history publication; this module never writes disk or maintains Undo. */
export function validateDiagramWorkflowGraph(nodes: readonly DiagramNode[], connectors: readonly DiagramConnector[]): StructureResult<true> {
  const ownership = validateContainerOwnership(nodes), trees = validateMindMap(nodes)
  if (!ownership.ok) return ownership
  if (!trees.ok) return trees
  const ids = new Set(nodes.map(node => node.id)), edges = new Set<string>()
  for (const node of nodes) {
    if (!['column', 'group', 'image', 'video', 'model', 'document', 'note', 'text', 'clip', 'shape', 'board-link'].includes(node.kind) || ![node.x, node.y, node.width, node.height, node.rotation ?? 0].every(Number.isFinite) || node.width <= 0 || node.height <= 0) return failure('Every diagram object needs a supported kind, finite geometry and positive dimensions.')
    const paths = [node.vectorPath, ...(node.vectorBoolean?.operands || []), ...(node.vectorBoolean?.resolvedPaths || [])].filter(path => Boolean(path))
    const invalidPaths = paths.some(path => !path || path.version !== 1 || !Array.isArray(path.points) || path.points.length < (path.closed ? 3 : 2) || path.points.some(point => !finitePoint(point) || point.handleIn && !finitePoint(point.handleIn) || point.handleOut && !finitePoint(point.handleOut)))
    const invalidTransform = node.vectorTransform && Object.values(node.vectorTransform).some(value => !Number.isFinite(value))
    if (invalidPaths || invalidTransform) return failure('A diagram path contains invalid editable geometry.')
  }
  for (const edge of connectors) {
    if (!edge.id || ids.has(edge.id) || edges.has(edge.id) || (edge.sourceId && !ids.has(edge.sourceId)) || (edge.targetId && !ids.has(edge.targetId))) return failure('The diagram has a duplicate identity or a missing connector endpoint.')
    edges.add(edge.id)
    if (!edge.sourceId && !edge.sourcePoint || !edge.targetId && !edge.targetPoint) return failure('Every connection needs two attached or detached endpoints.')
    if ([...(edge.bendPoints || []), ...(edge.sourcePoint ? [edge.sourcePoint] : []), ...(edge.targetPoint ? [edge.targetPoint] : [])].some(point => !finitePoint(point))) return failure('Connection coordinates must be finite.')
    if (edge.mindMap && !nodes.some(node => node.mindMap?.treeId === edge.mindMap?.treeId)) return failure('A mind-map connection references a missing tree.')
  }
  for (const treeId of new Set(nodes.flatMap(node => node.mindMap ? [node.mindMap.treeId] : []))) {
    const valid = validateMindMapConnectors(nodes, connectors, treeId)
    if (!valid.ok) return valid
  }
  return success(true)
}

function publishCandidate(board: BoardModel, nodes: DiagramNode[], connectors: DiagramConnector[], selectedIds: string[], readOnly: boolean): StructureResult<DiagramWorkflowResult> {
  const graph = validateDiagramWorkflowGraph(nodes, connectors)
  if (!graph.ok) return graph
  const checked = validateBoardMutation(board, { ...board, nodes, connectors }, readOnly)
  if (!checked.ok) return checked
  const visibleSelection = [...new Set(selectedIds)].filter(id => { const state = diagramState(nodes, id); return state.ok && !state.value.hidden })
  return success({ board: checked.value, selectedIds: visibleSelection })
}

const edgeBetween = (id: string, sourceId: string, targetId: string): DiagramConnector => ({ id, sourceId, targetId, sourcePort: 'right', targetPort: 'left', sourcePortMode: 'adaptive', targetPortMode: 'adaptive', style: 'elbow', color: '#60a5fa', width: 2, dashed: false, startArrow: false, endArrow: true, animated: false })
function validNamespace(board: BoardModel, namespace: string, origin?: BoardPoint): StructureResult<true> {
  if (typeof namespace !== 'string' || !namespace || namespace.length > 200 || origin && !finitePoint(origin)) return failure('Use a fresh nonempty identity and finite placement coordinates.')
  if (existingIds(board).some(id => id.startsWith(`${namespace}:`))) return failure('This instance identity already exists; insert again with a fresh identity.')
  return success(true)
}

/** All returned object/edge changes are one candidate board. Rejection leaves
 * every input reference/record intact, including unknown metadata. */
export function runDiagramWorkflow(board: BoardModel, command: DiagramWorkflowCommand, readOnly = false): StructureResult<DiagramWorkflowResult> {
  if (readOnly) return failure('This workspace is read-only.')
  const graph = validateDiagramWorkflowGraph(board.nodes, board.connectors)
  if (!graph.ok) return graph
  if ('namespace' in command) { const fresh = validNamespace(board, command.namespace, 'origin' in command ? command.origin : undefined); if (!fresh.ok) return fresh }
  const nodes: DiagramNode[] = [...board.nodes], connectors: DiagramConnector[] = [...board.connectors]
  if (command.kind === 'starter-map') {
    const created = createMindMapTemplate(command.namespace, command.origin, existingIds(board))
    if (!created.ok) return created
    return publishCandidate(board, [...nodes, ...created.value.nodes], [...connectors, ...created.value.connectors], [created.value.nodes[0].id], readOnly)
  }
  if (command.kind === 'new-root') {
    const title = command.title?.trim() || 'Root idea'
    if (!validTitle(title)) return failure('Use a nonempty label of at most 160 characters.')
    const id = `${command.namespace}:node:0`, treeId = `${command.namespace}:tree`
    nodes.push({ id, kind: 'note', title, body: '', ...command.origin, width: 180, height: 90, color: '#405b78', mindMap: { version: 1, treeId, order: 0 } })
    return publishCandidate(board, nodes, connectors, [id], readOnly)
  }
  if (command.kind === 'process-map') {
    const created = createProcessMapTemplate(command.namespace, command.origin, existingIds(board))
    if (!created.ok) return created
    return publishCandidate(board, [...nodes, ...created.value.nodes], [...connectors, ...created.value.connectors], created.value.nodes.map(node => node.id), readOnly)
  }
  if (command.kind === 'swimlane') {
    const created = createSwimlaneTemplate(command.namespace, command.origin, command.title, command.laneTitles, existingIds(board))
    if (!created.ok) return created
    return publishCandidate(board, [...nodes, ...created.value.nodes], connectors, [created.value.nodes[0].id], readOnly)
  }
  if (!('id' in command)) return failure('Unsupported diagram creation command.')
  const node = board.nodes.find(node => node.id === command.id) as DiagramNode | undefined
  if (!node) return failure('The selected diagram object is no longer on this board.')
  if (command.kind === 'add-child' || command.kind === 'add-sibling') {
    if (!node.mindMap || !validTitle(command.title)) return failure('Select a mind-map branch and enter a nonempty label of at most 160 characters.')
    const parent = command.kind === 'add-child' ? node : nodes.find(entry => entry.id === node.mindMap!.parentId)
    if (!parent?.mindMap) return failure('The tree root has no sibling. Add a child or create another root.')
    const state = diagramState(nodes, parent.id)
    if (!state.ok) return state
    if (state.value.locked || state.value.hidden || parent.mindMap.collapsed || parent.collapsed) return failure('Expand and unlock the destination branch before adding content.')
    const siblings = nodes.filter(entry => entry.mindMap?.parentId === parent.id)
    const id = `${command.namespace}:node:0`, order = siblings.length ? Math.max(...siblings.map(entry => entry.mindMap!.order)) + 1 : 0
    nodes.push({ id, kind: 'note', title: command.title.trim(), body: '', x: parent.x + parent.width + 80, y: siblings.length ? Math.max(...siblings.map(entry => entry.y + entry.height)) + 24 : parent.y, width: 180, height: 90, color: '#405b78', ...(parent.groupId ? { groupId: parent.groupId } : {}), ...(parent.parentColumnId ? { parentColumnId: parent.parentColumnId, columnOrder: Math.max(-1, ...nodes.filter(entry => entry.parentColumnId === parent.parentColumnId).map(entry => entry.columnOrder ?? 0)) + 1 } : {}), mindMap: { version: 1, treeId: parent.mindMap.treeId, parentId: parent.id, order } })
    connectors.push({ ...edgeBetween(`${command.namespace}:edge:0`, parent.id, id), endArrow: false, mindMap: { version: 1, treeId: parent.mindMap.treeId, childId: id } })
    return publishCandidate(board, nodes, connectors, [id], readOnly)
  }
  if (command.kind === 'reparent') {
    const result = reparentMindMapBranch(nodes, connectors, node.id, command.parentId, command.order)
    return result.ok ? publishCandidate(board, result.value.nodes, result.value.connectors, [node.id], readOnly) : result
  }
  if (command.kind === 'move-branch') {
    const branch = mindMapBranchIds(nodes, node.id)
    if (!branch.ok) return branch
    const moved = moveContainerWithDescendants(nodes, connectors, branch.value, command.delta)
    return moved.ok ? publishCandidate(board, moved.value.nodes, moved.value.connectors, [node.id], readOnly) : moved
  }
  if (command.kind === 'layout') {
    if (!node.mindMap) return failure('Select a mind-map branch to arrange its tree.')
    const laidOut = layoutMindMap(nodes, node.mindMap.treeId)
    return laidOut.ok ? publishCandidate(board, laidOut.value, connectors, [node.id], readOnly) : laidOut
  }
  let updated: DiagramNode
  if (command.kind === 'rename') {
    if (!validTitle(command.title)) return failure('Use a nonempty label of at most 160 characters.')
    updated = { ...node, title: command.title.trim(), ...(node.diagramShape ? { body: command.title.trim() } : {}) }
  } else if (command.kind === 'collapse') {
    if (node.mindMap) updated = { ...node, mindMap: { ...node.mindMap, collapsed: command.collapsed } }
    else if (node.kind === 'group' || node.kind === 'column') updated = { ...node, collapsed: command.collapsed }
    else return failure('Only mind-map branches and containers can collapse.')
  } else if (command.kind === 'visibility') updated = { ...node, hidden: command.hidden }
  else if (command.kind === 'lock') updated = { ...node, locked: command.locked }
  else if (command.kind === 'layer') {
    const state = diagramState(nodes, node.id)
    if (!state.ok) return state
    if (state.value.locked || state.value.hidden) return failure('Show and unlock the object before changing its layer.')
    const siblings = nodes.filter(entry => owner(entry) === owner(node)), layers = siblings.map(entry => entry.zIndex ?? (entry.kind === 'group' ? 0 : entry.kind === 'column' ? 1 : 2))
    const zIndex = command.direction === 'front' ? Math.max(...layers) + 1 : Math.min(...layers) - 1
    if (!Number.isFinite(zIndex) || layers.includes(zIndex)) return failure('The current layer values cannot be reordered safely.')
    updated = { ...node, zIndex }
  } else return failure('Unsupported diagram command.')
  return publishCandidate(board, nodes.map(entry => entry.id === node.id ? updated : entry), connectors, [node.id], readOnly)
}

export function captureDiagramTemplate(board: BoardModel, selectedIds: readonly string[], id: string, title: string): StructureResult<DiagramTemplate> {
  if (!id || !validTitle(title) || !selectedIds.length) return failure('Select diagram objects and give the template a name of at most 160 characters.')
  const valid = validateDiagramWorkflowGraph(board.nodes, board.connectors)
  if (!valid.ok) return valid
  const selected = new Set(selectedIds)
  for (const selectedId of selected) if (!board.nodes.some(node => node.id === selectedId)) return failure('A selected template object is no longer on this board.')
  // Capture complete owned regions and branches, repeatedly until both graphs
  // reach a fixed point. Board portals stay outside diagram reuse.
  let size = -1
  while (size !== selected.size) {
    size = selected.size
    const descendants = containerDescendantIds(board.nodes, [...selected])
    if (!descendants.ok) return descendants
    descendants.value.forEach(value => selected.add(value))
    for (const node of board.nodes) if (selected.has(node.id) && node.mindMap) {
      const branch = mindMapBranchIds(board.nodes, node.id)
      if (!branch.ok) return branch
      branch.value.forEach(value => selected.add(value))
    }
  }
  const picked = board.nodes.filter(node => selected.has(node.id)) as DiagramNode[]
  if (picked.some(node => node.kind === 'board-link')) return failure('Board portals are not diagram templates. Select diagram content without board links.')
  const left = Math.min(...picked.map(node => node.x)), top = Math.min(...picked.map(node => node.y))
  const nodes = structuredClone(picked).map(node => {
    const next = { ...node, x: node.x - left, y: node.y - top }
    if (next.groupId && !selected.has(next.groupId)) delete next.groupId
    if (next.parentColumnId && !selected.has(next.parentColumnId)) { delete next.parentColumnId; delete next.columnOrder }
    if (next.mindMap?.parentId && !selected.has(next.mindMap.parentId)) next.mindMap = { ...next.mindMap, parentId: undefined, order: 0 }
    return next
  })
  // Separate disconnected captured branches into independent valid trees.
  const treeOf = new Map<string, string>()
  let treeIndex = 0
  for (const root of nodes.filter(node => node.mindMap && !node.mindMap.parentId)) {
    const treeId = `${id}:captured-tree:${treeIndex++}`, queue = [root.id]
    for (let index = 0; index < queue.length; index++) { treeOf.set(queue[index], treeId); queue.push(...nodes.filter(node => node.mindMap?.parentId === queue[index]).map(node => node.id)) }
  }
  nodes.forEach(node => { if (node.mindMap) node.mindMap = { ...node.mindMap, treeId: treeOf.get(node.id)! } })
  const translate = (point: BoardPoint) => ({ ...point, x: point.x - left, y: point.y - top })
  const connectors = structuredClone(board.connectors.filter(edge => (edge.sourceId ? selected.has(edge.sourceId) : true) && (edge.targetId ? selected.has(edge.targetId) : true) && Boolean(edge.sourceId && selected.has(edge.sourceId) || edge.targetId && selected.has(edge.targetId)))) as DiagramConnector[]
  for (const edge of connectors) {
    if (edge.sourcePoint) edge.sourcePoint = translate(edge.sourcePoint)
    if (edge.targetPoint) edge.targetPoint = translate(edge.targetPoint)
    if (edge.bendPoints) edge.bendPoints = edge.bendPoints.map(translate)
    if (edge.mindMap) edge.mindMap = { ...edge.mindMap, treeId: treeOf.get(edge.mindMap.childId)! }
  }
  const checked = validateDiagramWorkflowGraph(nodes, connectors)
  return checked.ok ? success({ version: 1, id, title: title.trim(), nodes, connectors }) : checked
}

export function validateDiagramTemplate(value: unknown): value is DiagramTemplate {
  if (!value || typeof value !== 'object') return false
  const template = value as DiagramTemplate
  if (template.version !== 1 || typeof template.id !== 'string' || !template.id || !validTitle(template.title) || !Array.isArray(template.nodes) || !template.nodes.length || template.nodes.length > 5000 || !Array.isArray(template.connectors) || template.nodes.some(node => !node || node.kind === 'board-link') || template.connectors.some(edge => !edge)) return false
  try { return validateDiagramWorkflowGraph(template.nodes, template.connectors).ok } catch { return false }
}

export function instantiateDiagramTemplate(board: BoardModel, template: DiagramTemplate, namespace: string, origin: BoardPoint, readOnly = false): StructureResult<DiagramWorkflowResult> {
  if (!validateDiagramTemplate(template)) return failure('The saved template is invalid or unsupported; the board was left unchanged.')
  const fresh = validNamespace(board, namespace, origin)
  if (!fresh.ok) return fresh
  const ids = new Map(template.nodes.map((node, index) => [node.id, `${namespace}:node:${index}`])), trees = new Map([...new Set(template.nodes.flatMap(node => node.mindMap ? [node.mindMap.treeId] : []))].map((treeId, index) => [treeId, `${namespace}:tree:${index}`]))
  const translate = (point: BoardPoint) => ({ ...point, x: point.x + origin.x, y: point.y + origin.y })
  const nodes = structuredClone(template.nodes).map(node => ({ ...node, ...translate(node), id: ids.get(node.id)!, ...(node.groupId ? { groupId: ids.get(node.groupId)! } : {}), ...(node.parentColumnId ? { parentColumnId: ids.get(node.parentColumnId)! } : {}), ...(node.mindMap ? { mindMap: { ...node.mindMap, treeId: trees.get(node.mindMap.treeId)!, ...(node.mindMap.parentId ? { parentId: ids.get(node.mindMap.parentId)! } : {}) } } : {}) }))
  const connectors = structuredClone(template.connectors).map((edge, index) => ({ ...edge, id: `${namespace}:edge:${index}`, ...(edge.sourceId ? { sourceId: ids.get(edge.sourceId)! } : {}), ...(edge.targetId ? { targetId: ids.get(edge.targetId)! } : {}), ...(edge.sourcePoint ? { sourcePoint: translate(edge.sourcePoint) } : {}), ...(edge.targetPoint ? { targetPoint: translate(edge.targetPoint) } : {}), ...(edge.bendPoints ? { bendPoints: edge.bendPoints.map(translate) } : {}), ...(edge.mindMap ? { mindMap: { ...edge.mindMap, treeId: trees.get(edge.mindMap.treeId)!, childId: ids.get(edge.mindMap.childId)! } } : {}) }))
  return publishCandidate(board, [...board.nodes, ...nodes], [...board.connectors, ...connectors], nodes.filter(node => !owner(node) && !node.mindMap?.parentId).map(node => node.id), readOnly)
}

export function diagramObjectRows(nodes: readonly DiagramNode[]): StructureResult<{ node: DiagramNode; depth: number; locked: boolean; hidden: boolean; inheritedLock: boolean; inheritedHidden: boolean }[]> {
  const order = containerPaintOrder(nodes)
  if (!order.ok) return order
  const byId = new Map(nodes.map(node => [node.id, node])), rows = []
  for (const id of order.value.orderedIds) {
    const node = byId.get(id)!, state = diagramState(nodes, id)
    if (!state.ok) return state
    const withoutOwn = diagramState(nodes.map(entry => entry.id === id ? { ...entry, locked: false, hidden: false } : entry), id)
    if (!withoutOwn.ok) return withoutOwn
    rows.push({ node, depth: state.value.containerAncestors.length + state.value.mindMapAncestors.length, locked: state.value.locked, hidden: state.value.hidden, inheritedLock: withoutOwn.value.locked, inheritedHidden: withoutOwn.value.hidden })
  }
  return success(rows)
}

import type { BoardNode } from '../model/project'
import { containerDescendantIds, containerPaintOrder, diagramProjectionStates, type StructureResult } from './diagramStructureCore'

const ownerOf = (node: BoardNode) => node.groupId || node.parentColumnId
const rankOf = (node: BoardNode) => node.zIndex ?? (node.kind === 'group' ? 0 : node.kind === 'column' ? 1 : 2)
const refuse = (code: string, detail: string, nodeId?: string): StructureResult<never> => ({ ok: false, issues: [{ code, detail, ...(nodeId ? { nodeId } : {}) }] })

export type DrawingLayerRow = { node: BoardNode; depth: number; paintOrder: number; locked: boolean; hidden: boolean }

/** A derived view of existing node identities, never a second saved layer model.
 * Topmost siblings appear first; an owner precedes its children. */
export function projectDrawingLayers(nodes: readonly BoardNode[]): StructureResult<DrawingLayerRow[]> {
  const paint = containerPaintOrder(nodes), states = diagramProjectionStates(nodes)
  if (!paint.ok) return paint
  if (!states.ok) return states
  const byId = new Map(nodes.map(node => [node.id, node])), siblings = new Map<string | undefined, BoardNode[]>()
  for (const id of paint.value.orderedIds) {
    const node = byId.get(id)!, owner = ownerOf(node), family = siblings.get(owner) || []
    family.push(node); siblings.set(owner, family)
  }
  const rows: DrawingLayerRow[] = [], stack = (siblings.get(undefined) || []).map(node => ({ node, depth: 0 }))
  while (stack.length) {
    const { node, depth } = stack.pop()!
    rows.push({ node, depth, paintOrder: paint.value.zIndexById.get(node.id)!, ...states.value.get(node.id)! })
    for (const child of siblings.get(node.id) || []) stack.push({ node: child, depth: depth + 1 })
  }
  return { ok: true, value: rows }
}

/** Move selected sibling subtrees together, keeping their existing relative
 * paint order. Ownership, geometry, array order and untouched records survive.
 * Refuse exhausted numeric ranks rather than rewriting unrelated saved data. */
export function changeDrawingLayerOrder<T extends BoardNode>(nodes: T[], ids: readonly string[], direction: 'front' | 'back'): StructureResult<T[]> {
  const paint = containerPaintOrder(nodes), states = diagramProjectionStates(nodes)
  if (!paint.ok) return paint
  if (!states.ok) return states
  const expanded = containerDescendantIds(nodes, ids)
  if (!expanded.ok) return expanded
  for (const id of expanded.value) {
    const state = states.value.get(id)!
    if (state.locked || state.hidden) return refuse('blocked-layer', 'The object or a container member is locked, hidden or collapsed; the whole layer command was cancelled.', id)
  }
  const byId = new Map(nodes.map(node => [node.id, node])), selected = new Set(ids), covered = new Set<string>(), roots = new Set<string>()
  const siblings = new Map<string | undefined, T[]>()
  // Parent-first canonical order also removes redundant selected descendants.
  for (const id of paint.value.orderedIds) {
    const node = byId.get(id)!, owner = ownerOf(node), family = siblings.get(owner) || []
    family.push(node); siblings.set(owner, family)
    if (owner && covered.has(owner)) covered.add(id)
    else if (selected.has(id)) { roots.add(id); covered.add(id) }
  }
  const replacements = new Map<string, T>()
  for (const family of siblings.values()) {
    const moved = family.filter(node => roots.has(node.id)), kept = family.filter(node => !roots.has(node.id))
    if (!moved.length || !kept.length) continue
    const desired = direction === 'front' ? [...kept, ...moved] : [...moved, ...kept]
    if (desired.every((node, index) => node === family[index])) continue
    let edge = rankOf(family[0])
    for (const node of family) edge = direction === 'front' ? Math.max(edge, rankOf(node)) : Math.min(edge, rankOf(node))
    let previous = direction === 'front' ? edge : -Infinity
    for (let index = 0; index < moved.length; index++) {
      const rank = direction === 'front' ? edge + index + 1 : edge - moved.length + index
      if (!Number.isFinite(rank) || rank <= previous || (direction === 'back' && rank >= edge)) {
        return refuse('layer-rank-capacity', 'Saved layer ranks have no safe numeric space for this command; ordering was left unchanged.', moved[index].id)
      }
      replacements.set(moved[index].id, { ...moved[index], zIndex: rank }); previous = rank
    }
  }
  return { ok: true, value: replacements.size ? nodes.map(node => replacements.get(node.id) || node) : nodes }
}

