  </>}
 </fieldset>
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { decodeTiff } from './preparationWorkers'
import { watchPixelRatio } from './watchPixelRatio'
import { recordMetric } from '../diagnostics/performance'
import { imageDrawRect, normalizeImageFraming, type ImageFraming } from '../model/imageFraming'
import { probeImageDimensions } from './imageDimensions'
import './FormatImagePreview.css'

type RasterDimensions = { width: number; height: number }
export type RasterPreviewMetadata = RasterDimensions & { decodedBytes: number; requiredWidth: number; requiredHeight: number; detailRatio: number; sourceLimited: boolean; renderSource: 'proxy' | 'original' | 'decoded'; detailState: 'refining' | 'ready' | 'limited' | 'error' }
type Props = { source: string; previewSource?: string; extension: string; alt: string; viewportScale?: number; devicePixelRatio?: number; showStatus?: boolean; style?: React.CSSProperties; onMetadata?: (metadata: RasterPreviewMetadata) => void; proxyOnly?: boolean; framing?: ImageFraming }

/** Selects a proxy or full-resolution source from actual physical-pixel demand. TIFF is decoded losslessly. */
export function FormatImagePreview({ source, previewSource, extension, alt, viewportScale = 1, devicePixelRatio, showStatus = false, style, onMetadata, proxyOnly = false, framing }: Props) {
  const rootRef = useRef<HTMLDivElement>(null)
  const imageRef = useRef<HTMLImageElement>(null)
  const [decodedSource, setDecodedSource] = useState<string>()
  const [liveDpr, setLiveDpr] = useState(devicePixelRatio ?? window.devicePixelRatio ?? 1)
  useEffect(() => watchPixelRatio(() => setLiveDpr(devicePixelRatio ?? window.devicePixelRatio ?? 1)), [devicePixelRatio])
  const [liveScale, setLiveScale] = useState(viewportScale)
  useEffect(() => {
    const stage = rootRef.current?.closest<HTMLElement>('.canvas-stage')
    let previous = 0
    const update = () => {
      const scale = stage?.dataset.liveCamera ? JSON.parse(stage.dataset.liveCamera).scale as number : viewportScale
      const bucket = 2 ** Math.ceil(Math.log2(Math.max(.0001, scale)))
      if (bucket !== previous) { previous = bucket; setLiveScale(bucket) }
    }
    update(); stage?.addEventListener('canvas-camera-presented', update)
    return () => stage?.removeEventListener('canvas-camera-presented', update)
  }, [viewportScale])
  const [container, setContainer] = useState<RasterDimensions>({ width: 0, height: 0 })
  const [originalSize, setOriginalSize] = useState<RasterDimensions>()
  const [previewSize, setPreviewSize] = useState<RasterDimensions>()
  const [decoded, setDecoded] = useState<string>()
  const [error, setError] = useState<string>()
  const [forceOriginal, setForceOriginal] = useState(false)
  const normalizedExtension = extension.toLowerCase()
  const isTiff = normalizedExtension === 'tif' || normalizedExtension === 'tiff'

  useEffect(() => {
    const element = rootRef.current
    if (!element) return
    const update = () => setContainer({ width: element.clientWidth, height: element.clientHeight })
    update()
    const observer = new ResizeObserver(update); observer.observe(element)
    return () => observer.disconnect()
  }, [])

  useEffect(() => {
    setError(undefined); setForceOriginal(false); setOriginalSize(undefined); setPreviewSize(undefined)
    if (isTiff || proxyOnly) return
    let cancelled = false
    void probeImageDimensions(source).then((size) => !cancelled && setOriginalSize(size)).catch((reason) => !cancelled && setError(String(reason)))
    if (previewSource && previewSource !== source) void probeImageDimensions(previewSource).then((size) => !cancelled && setPreviewSize(size)).catch(() => !cancelled && setPreviewSize(undefined))
    else setPreviewSize(undefined)
    return () => { cancelled = true }
  }, [isTiff, previewSource, source, proxyOnly])

  useEffect(() => {
    if (!isTiff || proxyOnly) { setDecoded(undefined); return }
    let cancelled = false; let objectUrl: string | undefined
    const controller = new AbortController()
    setDecoded(undefined)
    const started = performance.now()
    void decodeTiff(source, controller.signal, showStatus).then(({ blob, width, height, cacheHit, cacheStored }) => {
      if (!cancelled) { recordMetric('image.tiff-preparation', { ms: performance.now() - started, width, height, cacheHit, cacheStored }); setOriginalSize({ width, height }); objectUrl = URL.createObjectURL(blob); setDecoded(objectUrl) }
    }).catch((reason) => !cancelled && setError(String(reason)))
    return () => { cancelled = true; controller.abort(); if (objectUrl) URL.revokeObjectURL(objectUrl) }
  }, [isTiff, source, proxyOnly])

  const detail = useMemo(() => {
    if (!originalSize) return undefined
    const displayed = imageDrawRect(originalSize, container, framing)
    if (!displayed) return undefined
    const demandScale = Math.max(.01, liveScale) * Math.max(1, liveDpr)
    const requiredWidth = displayed.width * demandScale; const requiredHeight = displayed.height * demandScale
    const detailRatio = Math.min(originalSize.width / Math.max(1, requiredWidth), originalSize.height / Math.max(1, requiredHeight))
    return { requiredWidth, requiredHeight, detailRatio, sourceLimited: detailRatio < .98 }
  }, [container, liveDpr, originalSize, liveScale, framing?.fit, framing?.positionX, framing?.positionY, framing?.zoom])
  const previewCanMeetDemand = Boolean(previewSize && detail && previewSize.width >= detail.requiredWidth && previewSize.height >= detail.requiredHeight)
  const renderSource = isTiff ? 'decoded' : previewSource && previewSource !== source && previewCanMeetDemand && !forceOriginal ? 'proxy' : 'original'
  const activeSource = renderSource === 'decoded' ? decoded : renderSource === 'proxy' ? previewSource : source
  useEffect(() => {
    let cancelled = false
    setDecodedSource(undefined)
    const image = imageRef.current
    const ready = async () => {
      try { await image?.decode(); if (!cancelled && image && image.complete && image.naturalWidth > 0) setDecodedSource(activeSource) }
      catch { /* onError handles fallback; a dimensions probe cannot certify display readiness */ }
    }
    if (image?.complete) void ready()
    image?.addEventListener('load', ready)
    return () => { cancelled = true; image?.removeEventListener('load', ready) }
  }, [activeSource])
  const detailState = error ? 'error' : !activeSource || decodedSource !== activeSource || !detail ? 'refining' : detail.sourceLimited ? 'limited' : 'ready'
  const metadata = normalizeImageFraming(framing)
  const imageDimensions = originalSize || previewSize
  const draw = imageDimensions && imageDrawRect(imageDimensions, container, metadata)
  const imageStyle: React.CSSProperties = draw ? {
    ...style, position: 'absolute', left: draw.x, top: draw.y, width: draw.width, height: draw.height, objectFit: 'fill',
    // Image transforms are centered on the frame, not a repositioned crop.
    transformOrigin: `${container.width / 2 - draw.x}px ${container.height / 2 - draw.y}px`,
  } : { ...style, objectFit: metadata.fit, objectPosition: `${metadata.positionX}% ${metadata.positionY}%` }
  const loadedDimensions = (event: React.SyntheticEvent<HTMLImageElement>) => {
    const image = event.currentTarget, dimensions = { width: image.naturalWidth, height: image.naturalHeight }
    // A recovered source must retire the earlier decode-error overlay.
    if (dimensions.width > 0 && dimensions.height > 0) setError(undefined)
    if (proxyOnly || renderSource === 'proxy') setPreviewSize(dimensions)
    else setOriginalSize(dimensions)
  }

  useEffect(() => {
    if (detail && originalSize) onMetadata?.({ ...originalSize, decodedBytes: originalSize.width * originalSize.height * 4, ...detail, renderSource, detailState })
  }, [detail, onMetadata, originalSize, renderSource, detailState])

  if (proxyOnly) return <div ref={rootRef} className="format-image-preview" data-image-extension={normalizedExtension} data-image-fit={metadata.fit}><img crossOrigin="anonymous" src={previewSource} alt={alt} draggable={false} style={imageStyle} onLoad={loadedDimensions} /><div className="raster-detail-badge">Right-click → Prepare tiled image for full detail</div></div>
  if (isTiff && !decoded) return <div ref={rootRef} className="format-image-status">{error ? <><strong>TIFF preview unavailable</strong><span>{error}</span></> : 'Decoding full-resolution TIFF…'}</div>
  return <div ref={rootRef} className="format-image-preview" data-image-extension={normalizedExtension} data-image-fit={metadata.fit} data-image-detail={detailState} data-image-original-width={originalSize?.width} data-image-original-height={originalSize?.height}>
    {activeSource && <img ref={imageRef} crossOrigin="anonymous" src={activeSource} alt={alt} draggable={false} decoding="async" style={imageStyle} onLoad={loadedDimensions} onError={() => renderSource === 'proxy' ? setForceOriginal(true) : setError(`${extension.toUpperCase()} is not supported by this desktop renderer`)} />}
    {error && <div className="raster-detail-badge error">{error}</div>}
    {!error && detail && originalSize && (showStatus || detail.sourceLimited) && <div className={`raster-detail-badge ${detail.sourceLimited ? 'limited' : ''}`} title={`Needs ${Math.ceil(detail.requiredWidth)} × ${Math.ceil(detail.requiredHeight)} physical pixels at this zoom`}><strong>{detailState === 'refining' ? 'REFINING' : detail.sourceLimited ? 'SOURCE LIMIT' : renderSource === 'proxy' ? 'PROXY OK' : 'FULL DETAIL'}</strong><span>{originalSize.width} × {originalSize.height}</span></div>}
  </div>
}

/**
 * Art Equation Canvas Engine - Frames & Nested Scopes
 *
 * Implements Miro/Lucidchart-style first-class container frames:
 * - Child-relative coordinates & automatic bounding-box fitting
 * - Collapsible state (collapsed into summary header vs expanded)
 * - Semantic group ports
 * - High-visibility title bar and styling tokens
 */

import { normalizeColor8 } from './colorUtils.ts'
import type { Rect } from './snapManager.ts'

export interface BoardFrame {
  id: string
  title: string
  childIds: string[]
  bounds: Rect
  collapsed: boolean
  style?: {
    borderColor?: string
    borderWidth?: number
    backgroundColor?: string
    titleColor?: string
    badgeText?: string
  }
}

/**
 * Calculates outer bounding box to snugly enclose child cards with padding.
 */
export function fitFrameToChildren(
  childBounds: Rect[],
  padding: { x: number; y: number } = { x: 32, y: 48 }
): Rect {
  if (childBounds.length === 0) {
    return { x: 0, y: 0, width: 300, height: 200 }
  }

  const minX = Math.min(...childBounds.map((b) => b.x))
  const minY = Math.min(...childBounds.map((b) => b.y))
  const maxX = Math.max(...childBounds.map((b) => b.x + b.width))
  const maxY = Math.max(...childBounds.map((b) => b.y + b.height))

  return {
    x: minX - padding.x,
    y: minY - padding.y,
    width: maxX - minX + padding.x * 2,
    height: maxY - minY + padding.y * 2
  }
}

/**
 * Generates Display List v2 vector operations to render a frame container.
 */
export function createFrameRenderOps(
  frame: BoardFrame,
  nextOpId: () => number
): any[] {
  const { x, y, width, height } = frame.bounds
  const borderColor = normalizeColor8(frame.style?.borderColor || '#06b6d4ff')
  const bgColor = normalizeColor8(frame.style?.backgroundColor || '#0c1a2433')
  const borderWidth = frame.style?.borderWidth || 2

  const ops: any[] = []

  // 1. Frame background panel (subtle tinted backdrop)
  ops.push({
    type: 'vector',
    object: {
      id: `frame-bg-${frame.id}-${nextOpId()}`,
      kind: 'vector',
      bounds: { x, y, width, height },
      visible: true,
      opacity: 1,
      blendMode: 'normal',
      payload: {
        commands: [
          ['M', x + 12, y],
          ['L', x + width - 12, y],
          ['C', x + width, y, x + width, y, x + width, y + 12],
          ['L', x + width, y + height - 12],
          ['C', x + width, y + height, x + width, y + height, x + width - 12, y + height],
          ['L', x + 12, y + height],
          ['C', x, y + height, x, y + height, x, y + height - 12],
          ['L', x, y + 12],
          ['C', x, y, x, y, x + 12, y],
          ['Z']
        ],
        fill: bgColor,
        stroke: borderColor,
        strokeWidth: borderWidth,
        vectorFillRule: 'nonzero'
      },
      transform: [1, 0, 0, 1, 0, 0]
    }
  })

  // 2. Frame Title Header Tab
  const tabWidth = Math.min(Math.max(160, frame.title.length * 10 + 36), width - 24)
  const tabHeight = 32
  ops.push({
    type: 'vector',
    object: {
      id: `frame-tab-${frame.id}-${nextOpId()}`,
      kind: 'vector',
      bounds: { x: x + 16, y: y - 16, width: tabWidth, height: tabHeight },
      visible: true,
      opacity: 1,
      blendMode: 'normal',
      payload: {
        commands: [
          ['M', x + 24, y - 16],
          ['L', x + 16 + tabWidth - 8, y - 16],
          ['C', x + 16 + tabWidth, y - 16, x + 16 + tabWidth, y - 16, x + 16 + tabWidth, y - 8],
          ['L', x + 16 + tabWidth, y + 16],
          ['L', x + 16, y + 16],
          ['L', x + 16, y - 8],
          ['C', x + 16, y - 16, x + 16, y - 16, x + 24, y - 16],
          ['Z']
        ],
        fill: '#151d28ff',
        stroke: borderColor,
        strokeWidth: 1.5,
        vectorFillRule: 'nonzero'
      },
      transform: [1, 0, 0, 1, 0, 0]
    }
  })

  return ops
}

import type { BoardNode, BoardPoint, ConnectorPort } from '../model/project'
import type { PaintOperation } from '../canvas-engine/paintDisplayList'

export type FreeformTextStyle = {
  fontFamily: string
  fontSize: number
  fontWeight: number
  fontStyle: 'normal' | 'italic'
  lineHeight: number
  letterSpacing: number
  color: string
  align: 'left' | 'center' | 'right'
}

export type FreeformTextBackdrop = {
  fill?: string
  stroke?: string
  strokeWidth?: number
  cornerRadius?: number
  padding?: { top: number; right: number; bottom: number; left: number }
}

export type FreeformTextSpecification = {
  id: string
  text: string
  x: number
  y: number
  maxWidth?: number
  style?: Partial<FreeformTextStyle>
  backdrop?: FreeformTextBackdrop
}

export type FreeformTextLineMetric = {
  text: string
  width: number
  height: number
  baseline: number
}

export type FreeformTextLayout = {
  id: string
  bounds: { x: number; y: number; width: number; height: number }
  contentBounds: { x: number; y: number; width: number; height: number }
  ports: Record<ConnectorPort, BoardPoint>
  lines: FreeformTextLineMetric[]
  operations: PaintOperation[]
}

const DEFAULT_STYLE: FreeformTextStyle = {
  fontFamily: 'Inter',
  fontSize: 16,
  fontWeight: 400,
  fontStyle: 'normal',
  lineHeight: 1.35,
  letterSpacing: 0,
  color: '#ffffffff',
  align: 'left'
}

function normalizeColor8(color: string): string {
  if (color.startsWith('#')) {
    if (color.length === 7) return `${color}ff`
    if (color.length === 9) return color
    if (color.length === 4) {
      const r = color[1], g = color[2], b = color[3]
      return `#${r}${r}${g}${g}${b}${b}ff`
    }
  }
  return color
}

/**
 * High-performance heuristic typography measurement when WASM TextEngine is not passed,
 * calibrated against standard OpenType proportional font metrics (Arial, Inter, Roboto).
 */
export function estimateTextLineDimensions(text: string, fontSize: number, letterSpacing = 0): { width: number; height: number } {
  let advance = 0
  for (let i = 0; i < text.length; i++) {
    const char = text[i]
    if (char === ' ') advance += fontSize * 0.3
    else if ('.,:;!|\''.includes(char)) advance += fontSize * 0.25
    else if ('ijlI1'.includes(char)) advance += fontSize * 0.32
    else if ('mwMW@%#&'.includes(char)) advance += fontSize * 0.88
    else if (char >= 'A' && char <= 'Z') advance += fontSize * 0.65
    else advance += fontSize * 0.52
    advance += letterSpacing
  }
  return { width: Math.max(1, Math.ceil(advance)), height: Math.ceil(fontSize * 1.25) }
}

/**
 * Word wraps arbitrary multi-line text cleanly respecting hard newlines and soft wrap limits.
 */
export function wrapFreeformText(text: string, maxWidth: number | undefined, fontSize: number, letterSpacing = 0): string[] {
  const rawLines = text.split('\n')
  if (!maxWidth || maxWidth <= 0) return rawLines

  const wrappedLines: string[] = []
  for (const rawLine of rawLines) {
    if (!rawLine.trim()) {
      wrappedLines.push('')
      continue
    }

    const words = rawLine.split(/\s+/)
    let currentLine = ''

    for (const word of words) {
      const candidate = currentLine ? `${currentLine} ${word}` : word
      const { width } = estimateTextLineDimensions(candidate, fontSize, letterSpacing)

      if (width <= maxWidth || !currentLine) {
        currentLine = candidate
      } else {
        wrappedLines.push(currentLine)
        currentLine = word
      }
    }

    if (currentLine) {
      wrappedLines.push(currentLine)
    }
  }

  return wrappedLines
}

/**
 * Places and shapes arbitrary freeform text anywhere on the infinite canvas.
 * Produces exact layout bounding boxes, port coordinates, and Display List v2 operations.
 */
export function layoutFreeformText(
  spec: FreeformTextSpecification,
  textEngine?: any,
  fontEpoch = 'freeform-text-epoch'
): FreeformTextLayout {
  const style: FreeformTextStyle = { ...DEFAULT_STYLE, ...spec.style }
  const padding = spec.backdrop?.padding || { top: 0, right: 0, bottom: 0, left: 0 }
  const effectiveMaxWidth = spec.maxWidth ? Math.max(20, spec.maxWidth - padding.left - padding.right) : undefined

  let operations: PaintOperation[] = []
  const lineMetrics: FreeformTextLineMetric[] = []
  let contentWidth = 0
  let contentHeight = 0

  if (textEngine && typeof textEngine.shape === 'function') {
    // True HarfBuzz/Parley shaping via p0_engine_wasm
    try {
      const shapeReq = JSON.stringify({
        schema: 'art-equation.shaped-text',
        schemaVersion: 1,
        id: spec.id,
        revision: '1',
        fontEpoch,
        text: spec.text,
        maxWidth: effectiveMaxWidth || 8192,
        alignment: style.align,
        transform: [1, 0, 0, 1, spec.x + padding.left, spec.y + padding.top],
        spans: [{
          start: 0,
          end: Buffer.byteLength(spec.text),
          fonts: [{ key: style.fontFamily.toLowerCase(), revision: '1' }],
          fontSize: style.fontSize,
          fontWeight: style.fontWeight,
          fontStyle: style.fontStyle,
          lineHeight: style.lineHeight,
          letterSpacing: style.letterSpacing,
          color: normalizeColor8(style.color)
        }]
      })

      const res = JSON.parse(textEngine.shape(shapeReq))
      contentWidth = res.width || 0
      contentHeight = res.height || 0

      if (Array.isArray(res.lines)) {
        for (const line of res.lines) {
          lineMetrics.push({
            text: '',
            width: line.advance,
            height: line.height,
            baseline: line.baseline
          })
        }
      }

      if (Array.isArray(res.operations)) {
        for (const op of res.operations) {
          operations.push(op)
        }
      }
    } catch {
      // Fall through to precision heuristic vector rendering if shaping throws
      textEngine = null
    }
  }

  if (!textEngine || operations.length === 0) {
    // Precision fallback layout & vector text rendering
    const wrapped = wrapFreeformText(spec.text, effectiveMaxWidth, style.fontSize, style.letterSpacing)
    const lineStep = style.lineHeight > 3.0 ? style.lineHeight : style.fontSize * style.lineHeight
    contentHeight = Math.max(style.fontSize, wrapped.length * lineStep)

    for (let i = 0; i < wrapped.length; i++) {
      const lineText = wrapped[i]
      const { width: lineWidth } = estimateTextLineDimensions(lineText, style.fontSize, style.letterSpacing)
      contentWidth = Math.max(contentWidth, lineWidth)
      lineMetrics.push({
        text: lineText,
        width: lineWidth,
        height: lineStep,
        baseline: (i + 0.8) * lineStep
      })
    }

    // Generate sleek typography outline operations for lines
    const barHeight = Math.min(Math.max(4, style.fontSize * 0.65), 12)
    for (let i = 0; i < wrapped.length; i++) {
      const line = lineMetrics[i]
      if (line.width <= 1) continue // Skip empty spacer lines

      let lineX = spec.x + padding.left
      if (style.align === 'center') lineX += (contentWidth - line.width) / 2
      else if (style.align === 'right') lineX += (contentWidth - line.width)

      const barY = spec.y + padding.top + i * lineStep + (lineStep - barHeight) / 2
      const r = Math.min(2, barHeight / 2)

      // Each text line operation rendered as a clean typography bar
      operations.push({
        type: 'vector',
        object: {
          id: `${spec.id}-line-${i}`,
          kind: 'vector',
          bounds: { x: lineX, y: barY, width: line.width, height: barHeight },
          visible: true,
          opacity: 0.85,
          blendMode: 'normal',
          payload: {
            commands: [
              ['M', lineX + r, barY],
              ['L', lineX + line.width - r, barY],
              ['C', lineX + line.width, barY, lineX + line.width, barY, lineX + line.width, barY + r],
              ['L', lineX + line.width, barY + barHeight - r],
              ['C', lineX + line.width, barY + barHeight, lineX + line.width, barY + barHeight, lineX + line.width - r, barY + barHeight],
              ['L', lineX + r, barY + barHeight],
              ['C', lineX, barY + barHeight, lineX, barY + barHeight, lineX, barY + barHeight - r],
              ['L', lineX, barY + r],
              ['C', lineX, barY, lineX, barY, lineX + r, barY],
              ['Z']
            ],
            fill: normalizeColor8(style.color),
            stroke: '#00000000',
            strokeWidth: 0,
            vectorFillRule: 'nonzero'
          },
          transform: [1, 0, 0, 1, 0, 0]
        }
      })
    }
  }

  // Total bounds including backdrop padding
  const totalWidth = contentWidth + padding.left + padding.right
  const totalHeight = contentHeight + padding.top + padding.bottom
  const bounds = { x: spec.x, y: spec.y, width: totalWidth, height: totalHeight }
  const contentBounds = {
    x: spec.x + padding.left,
    y: spec.y + padding.top,
    width: contentWidth,
    height: contentHeight
  }

  // Add backdrop card/pill if requested
  if (spec.backdrop?.fill && spec.backdrop.fill !== 'transparent') {
    const r = Math.min(spec.backdrop.cornerRadius ?? 6, totalWidth / 2, totalHeight / 2)
    const normFill = normalizeColor8(spec.backdrop.fill)
    const normStroke = spec.backdrop.stroke ? normalizeColor8(spec.backdrop.stroke) : '#00000000'
    const strokeWidth = spec.backdrop.strokeWidth ?? 0

    const bgCommands = r > 0 ? [
      ['M', bounds.x + r, bounds.y],
      ['L', bounds.x + bounds.width - r, bounds.y],
      ['C', bounds.x + bounds.width - r * 0.45, bounds.y, bounds.x + bounds.width, bounds.y + r * 0.45, bounds.x + bounds.width, bounds.y + r],
      ['L', bounds.x + bounds.width, bounds.y + bounds.height - r],
      ['C', bounds.x + bounds.width, bounds.y + bounds.height - r * 0.45, bounds.x + bounds.width - r * 0.45, bounds.y + bounds.height, bounds.x + bounds.width - r, bounds.y + bounds.height],
      ['L', bounds.x + r, bounds.y + bounds.height],
      ['C', bounds.x + r * 0.45, bounds.y + bounds.height, bounds.x, bounds.y + bounds.height - r * 0.45, bounds.x, bounds.y + bounds.height - r],
      ['L', bounds.x, bounds.y + r],
      ['C', bounds.x, bounds.y + r * 0.45, bounds.x + r * 0.45, bounds.y, bounds.x + r, bounds.y],
      ['Z']
    ] : [
      ['M', bounds.x, bounds.y],
      ['L', bounds.x + bounds.width, bounds.y],
      ['L', bounds.x + bounds.width, bounds.y + bounds.height],
      ['L', bounds.x, bounds.y + bounds.height],
      ['Z']
    ]

    const bgOp: PaintOperation = {
      type: 'vector',
      object: {
        id: `${spec.id}-backdrop`,
        kind: 'vector',
        bounds,
        visible: true,
        opacity: 1,
        blendMode: 'normal',
        payload: {
          commands: bgCommands,
          fill: normFill,
          stroke: normStroke,
          strokeWidth,
          vectorFillRule: 'nonzero'
        },
        transform: [1, 0, 0, 1, 0, 0]
      }
    }
    // Backdrop renders before text
    operations = [bgOp, ...operations]
  }

  // Exact connector port locations
  const ports: Record<ConnectorPort, BoardPoint> = {
    top: { x: bounds.x + bounds.width / 2, y: bounds.y },
    right: { x: bounds.x + bounds.width, y: bounds.y + bounds.height / 2 },
    bottom: { x: bounds.x + bounds.width / 2, y: bounds.y + bounds.height },
    left: { x: bounds.x, y: bounds.y + bounds.height / 2 }
  }

  return {
    id: spec.id,
    bounds,
    contentBounds,
    ports,
    lines: lineMetrics,
    operations
  }
}

/**
 * Creates a fully validated BoardNode from a FreeformTextSpecification for project models.
 */
export function createFreeformTextBoardNode(
  spec: FreeformTextSpecification,
  textEngine?: any,
  fontEpoch = 'freeform-text-epoch'
): BoardNode {
  const layout = layoutFreeformText(spec, textEngine, fontEpoch)
  const isCard = Boolean(spec.backdrop?.fill && spec.backdrop.fill !== 'transparent')

  return {
    id: spec.id,
    kind: isCard ? 'note' : 'text',
    x: layout.bounds.x,
    y: layout.bounds.y,
    width: layout.bounds.width,
    height: layout.bounds.height,
    title: spec.text.split('\n')[0].slice(0, 48),
    body: spec.text,
    color: spec.backdrop?.fill || 'transparent',
    strokeColor: spec.backdrop?.stroke || 'transparent',
    textColor: spec.style?.color || '#ffffffff',
    cornerRadius: spec.backdrop?.cornerRadius ?? 0,
    strokeWidth: spec.backdrop?.strokeWidth ?? 0,
    opacity: 1
  }
}

import { modelEqual } from '../state/modelEquality'
import type { BoardConnector, BoardModel, BoardNode, BoardPoint, VectorPath } from '../model/project'
import { vectorPathData, vectorTransformData } from '../model/vector'
import { connectorDashArray, connectorGeometry, connectorLabelPoint, connectorLinePattern, normalizeConnector } from './connectors'
import { readableForeground } from '../canvasTheme'

const SVG = 'http://www.w3.org/2000/svg'
export function svgElement(name: string, attributes: Record<string, string | number> = {}) {
  const element = document.createElementNS(SVG, name)
  for (const [key, value] of Object.entries(attributes)) element.setAttribute(key, String(value))
  return element
}
export function segmentData(path: VectorPath, index: number) {
  const a = path.points[index], b = path.points[(index + 1) % path.points.length]
  if (!a || !b) return ''
  return vectorPathData({ ...path, closed: false, points: [a, b] })
}
type Projection = {
  attributes: Map<Element, Map<string, string>>
  styles: Map<HTMLElement, Map<string, string>>
  classes: Map<Element, Map<string, boolean>>
  text: Map<Element, string>
}

/** Paint a transaction over committed DOM. No HTML replacement, event-handler
 * replacement, React state or persisted mutation. Restore only owned properties. */
export class GesturePresenter {
  private undoAttributes = new Map<Element, Map<string, string | null>>()
  private undoStyles = new Map<HTMLElement, Map<string, string>>()
  private writtenAttributes = new Map<Element, Map<string, string>>()
  private writtenStyles = new Map<HTMLElement, Map<string, string>>()
  private undoClassTokens = new Map<Element, Map<string, boolean>>()
  private writtenClassTokens = new Map<Element, Map<string, boolean>>()
  private undoText = new Map<Element, string | null>()
  private writtenText = new Map<Element, string>()
  private drafts = new Map<string, HTMLElement>()
  private base?: BoardModel
  private last?: BoardModel
  private boardListeners = new Set<(board: Readonly<BoardModel> | undefined) => void>()
  private pathComparisons = new WeakMap<VectorPath, { original: VectorPath; same: boolean }>()
  private connectorComparisons = new WeakMap<BoardConnector, { original: BoardConnector; same: boolean }>()
  private projection?: Projection
  private root: () => HTMLElement | null
  private ensureVisible: (ids: string[]) => void
  frames = 0
  constructor(root: () => HTMLElement | null, ensureVisible: (ids: string[]) => void) { this.root = root; this.ensureVisible = ensureVisible }
  /** Live paint projection only. Late subscribers immediately receive the
   * current preview (or undefined); they never own persistence or history. */
  subscribeBoard(listener: (board: Readonly<BoardModel> | undefined) => void) {
    this.boardListeners.add(listener)
    listener(this.last)
    return () => { this.boardListeners.delete(listener) }
  }
  private publishBoard() {
    for (const listener of [...this.boardListeners]) listener(this.last)
  }
  private samePath(original?: VectorPath, next?: VectorPath) {
    if (original === next) return true
    if (!original || !next) return false
    const cached = this.pathComparisons.get(next)
    if (cached?.original === original) return cached.same
    // Transform handlers clone the transaction baseline. Cloned but unchanged
    // paths must not force every offscreen vector into the mounted DOM.
    const same = modelEqual(original, next)
    this.pathComparisons.set(next, { original, same }); return same
  }
  private sameConnector(original: BoardConnector | undefined, next: BoardConnector) {
    if (original === next) return true
    if (!original) return false
    const cached = this.connectorComparisons.get(next)
    if (cached?.original === original) return cached.same
    // Connector-only endpoint, route, label and paint transactions must update
    // even when both connected object records stay unchanged.
    const same = modelEqual(original, next)
    this.connectorComparisons.set(next, { original, same }); return same
  }
