files.source:
/**
 * Art Equation Canvas Engine - Structured Graph Edge & Routing System
 *
 * Implements first-class edge data structures with semantic kinds,
 * typed port bindings, confidence, provenance, and routing modes:
 * - Straight lines
 * - Smooth cubic Béziers with tension
 * - Orthogonal stepped routing (authored waypoints control obstacle clearance)
 * - Waypoint-guided paths
 * - Directional arrows & optional mid-line semantic labels
 */

import { normalizeColor8 } from './colorUtils.ts'

export type EdgeKind = 'continuity' | 'reference' | 'identity' | 'branch' | 'evidence' | 'transform'
export type EdgeDirection = 'forward' | 'backward' | 'bidirectional'
export type RouteMode = 'straight' | 'bezier' | 'orthogonal' | 'manual'

export interface GraphEdge {
  id: string
  source: { cardId: string; portId: string }
  target: { cardId: string; portId: string }
  kind: EdgeKind
  direction: EdgeDirection
  label?: string
  confidence?: number
  provenance?: {
    createdBy: 'user' | 'AI' | 'import'
    sourceIds?: string[]
  }
  route: {
    mode: RouteMode
    waypoints?: { x: number; y: number }[]
    /** Optional authored Bézier controls; endpoints remain resolved card ports. */
    controls?: [{ x: number; y: number }, { x: number; y: number }]
  }
  style?: {
    stroke?: string
    strokeWidth?: number
    dash?: number[]
    showArrow?: boolean
  }
}

export interface ComputedRoute {
  pathCommands: any[]
  bounds: { x: number; y: number; width: number; height: number }
  midpoint: { x: number; y: number }
  tipPoint: { x: number; y: number }
  tipAngle: number
}

export const EDGE_KIND_COLORS: Record<EdgeKind, string> = {
  continuity: '#f59e0b', // Amber/gold
  branch: '#ef4444',     // Crimson/red
  reference: '#3b82f6',  // Blue
  identity: '#a855f7',   // Purple
  evidence: '#10b981',   // Emerald
  transform: '#ec4899'   // Magenta
}

/**
 * Computes exact route geometry from source coordinates to target coordinates.
 */
export function computeEdgeRoute(
  sx: number,
  sy: number,
  tx: number,
  ty: number,
  mode: RouteMode = 'bezier',
  waypoints: { x: number; y: number }[] = [],
  controls?: [{ x: number; y: number }, { x: number; y: number }]
): ComputedRoute {
  if (!['straight', 'bezier', 'orthogonal', 'manual'].includes(mode)) throw new Error(`Unsupported edge route mode: ${mode}`)
  if (![sx, sy, tx, ty].every(Number.isFinite)) throw new Error('Edge endpoints must be finite.')
  if (!Array.isArray(waypoints) || waypoints.length > 4096) throw new Error('Edge waypoints must be a bounded array.')
  for (const point of waypoints) {
    if (!point || ![point.x, point.y].every(Number.isFinite)) throw new Error('Edge waypoints must be finite.')
  }
  if (controls !== undefined) {
    if (mode !== 'bezier' || waypoints.length || !Array.isArray(controls) || controls.length !== 2
      || controls.some(point => !point || ![point.x, point.y].every(Number.isFinite))) {
      throw new Error('Authored controls require a Bézier route with two finite controls and no waypoints.')
    }
  }
  const dx = tx - sx
  const dy = ty - sy
  let commands: any[] = []
  let midpoint = { x: (sx + tx) / 2, y: (sy + ty) / 2 }
  let tipAngle = Math.atan2(dy, dx)

  if (waypoints && waypoints.length > 0) {
    commands = [['M', sx, sy]]
    for (const pt of waypoints) {
      commands.push(['L', pt.x, pt.y])
    }
    commands.push(['L', tx, ty])
    const lastPt = waypoints[waypoints.length - 1]
    tipAngle = Math.atan2(ty - lastPt.y, tx - lastPt.x)
  } else if (mode === 'straight' || mode === 'manual') {
    commands = [['M', sx, sy], ['L', tx, ty]]
    midpoint = { x: (sx + tx) / 2, y: (sy + ty) / 2 }
  } else if (mode === 'orthogonal') {
    const midX = sx + dx * 0.5
    commands = [
      ['M', sx, sy],
      ['L', midX, sy],
      ['L', midX, ty],
      ['L', tx, ty]
    ]
    midpoint = { x: midX, y: (sy + ty) / 2 }
    tipAngle = Math.atan2(0, tx - midX)
  } else if (mode === 'bezier') {
    // Smooth Bézier curve with tension
    const dist = Math.hypot(dx, dy)
    const tension = Math.min(Math.max(dist * 0.45, 40), 320)
    
    // Choose control offsets based on relative positions
    const cp1x = controls?.[0].x ?? sx + (Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? tension : -tension * 0.3) : 0)
    const cp1y = controls?.[0].y ?? sy + (Math.abs(dy) >= Math.abs(dx) ? (dy > 0 ? tension : -tension * 0.3) : 0)
    const cp2x = controls?.[1].x ?? tx - (Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? tension : -tension * 0.3) : 0)
    const cp2y = controls?.[1].y ?? ty - (Math.abs(dy) >= Math.abs(dx) ? (dy > 0 ? tension : -tension * 0.3) : 0)

    commands = [['M', sx, sy], ['C', cp1x, cp1y, cp2x, cp2y, tx, ty]]
    
    // Midpoint along cubic Bézier at t=0.5
    const t = 0.5
    const mt = 1 - t
    const mx = mt * mt * mt * sx + 3 * mt * mt * t * cp1x + 3 * mt * t * t * cp2x + t * t * t * tx
    const my = mt * mt * mt * sy + 3 * mt * mt * t * cp1y + 3 * mt * t * t * cp2y + t * t * t * ty
    midpoint = { x: mx, y: my }

    // Derivative at t=1.0 for tip angle
    const dtx = 3 * (tx - cp2x)
    const dty = 3 * (ty - cp2y)
    tipAngle = Math.atan2(dty, dtx)
  }

  // The control-point hull conservatively contains cubic curves as well as
  // authored routes. Reuse these coordinates for the terminal tangent so
  // zero-length final segments/control derivatives cannot turn arrows sideways.
  const points: Array<{ x: number; y: number }> = []
  for (const command of commands) {
    for (let i = 1; i < command.length; i += 2) {
      const point = { x: command[i], y: command[i + 1] }
      if (![point.x, point.y].every(Number.isFinite)) throw new Error('Edge route exceeds finite geometry.')
      points.push(point)
    }
  }
  for (let i = points.length - 2; i >= 0; i--) {
    const terminalDx = tx - points[i].x
    const terminalDy = ty - points[i].y
    if (Math.hypot(terminalDx, terminalDy) > 1e-9) {
      tipAngle = Math.atan2(terminalDy, terminalDx)
      break
    }
  }
  const minX = Math.min(...points.map(point => point.x)) - 10
  const minY = Math.min(...points.map(point => point.y)) - 10
  const maxX = Math.max(...points.map(point => point.x)) + 10
  const maxY = Math.max(...points.map(point => point.y)) + 10
  if (![minX, minY, maxX, maxY, maxX - minX, maxY - minY, midpoint.x, midpoint.y, tipAngle].every(Number.isFinite)) {
    throw new Error('Edge route exceeds finite geometry.')
  }

  return {
    pathCommands: commands,
    bounds: { x: minX, y: minY, width: Math.max(20, maxX - minX), height: Math.max(20, maxY - minY) },
    midpoint,
    tipPoint: { x: tx, y: ty },
    tipAngle
  }
}

/**
 * Generates Display List v2 operations representing a rendered edge.
 */
export function createEdgeRenderOps(
  edge: GraphEdge,
  sourcePos: { x: number; y: number },
  targetPos: { x: number; y: number },
  nextOpId: () => number
): any[] {
  const color = edge.style?.stroke || EDGE_KIND_COLORS[edge.kind] || '#3b82f6'
  const strokeColor = normalizeColor8(color)
  const strokeWidth = edge.style?.strokeWidth ?? 2.5
  if (!Number.isFinite(strokeWidth) || strokeWidth < 0) throw new Error('Edge stroke width must be finite and nonnegative.')
  const showArrow = edge.style?.showArrow !== false

  const route = computeEdgeRoute(
    sourcePos.x,
    sourcePos.y,
    targetPos.x,
    targetPos.y,
    edge.route.mode,
    edge.route.waypoints,
    edge.route.controls
  )

  const extraStrokeOutset = Math.max(0, strokeWidth / 2 - 10)
  const paintBounds = { x: route.bounds.x - extraStrokeOutset, y: route.bounds.y - extraStrokeOutset,
    width: route.bounds.width + extraStrokeOutset * 2, height: route.bounds.height + extraStrokeOutset * 2 }
  if (!Object.values(paintBounds).every(Number.isFinite)) throw new Error('Edge stroke exceeds finite geometry.')

  const ops: any[] = [
    {
      type: 'vector',
      object: {
        id: `edge-${edge.id}-${nextOpId()}`,
        kind: 'vector',
        bounds: paintBounds,
        visible: true,
        opacity: 1,
        blendMode: 'normal',
        payload: {
          commands: route.pathCommands,
          fill: '#00000000',
          stroke: strokeColor,
          strokeWidth,
          vectorFillRule: 'nonzero'
        },
        transform: [1, 0, 0, 1, 0, 0]
      }
    }
  ]

  // Render arrowhead if requested
  if (showArrow) {
    const headLen = 10
    const arrowAngle = Math.PI / 6
    const { x: tx, y: ty } = route.tipPoint
    const angle = route.tipAngle

    const p1x = tx - headLen * Math.cos(angle - arrowAngle)
    const p1y = ty - headLen * Math.sin(angle - arrowAngle)
    const p2x = tx - headLen * Math.cos(angle + arrowAngle)
    const p2y = ty - headLen * Math.sin(angle + arrowAngle)

    ops.push({
      type: 'vector',
      object: {
        id: `edge-head-${edge.id}-${nextOpId()}`,
        kind: 'vector',
        bounds: {
          x: Math.min(tx, p1x, p2x) - 0.5,
          y: Math.min(ty, p1y, p2y) - 0.5,
          width: Math.max(tx, p1x, p2x) - Math.min(tx, p1x, p2x) + 1,
          height: Math.max(ty, p1y, p2y) - Math.min(ty, p1y, p2y) + 1
        },
        visible: true,
        opacity: 1,
        blendMode: 'normal',
        payload: {
          commands: [
            ['M', tx, ty],
            ['L', p1x, p1y],
            ['L', p2x, p2y],
            ['Z']
          ],
          fill: strokeColor,
          stroke: strokeColor,
          strokeWidth: 1,
          vectorFillRule: 'nonzero'
        },
        transform: [1, 0, 0, 1, 0, 0]
      }
    })
  }

  // Render socket anchor dots at endpoints
  const dotR = 3.5
  ops.push(
    {
      type: 'vector',
      object: {
        id: `edge-src-dot-${edge.id}-${nextOpId()}`,
        kind: 'vector',
        bounds: { x: sourcePos.x - dotR - 0.5, y: sourcePos.y - dotR - 0.5, width: dotR * 2 + 1, height: dotR * 2 + 1 },
        visible: true,
        opacity: 0.9,
        blendMode: 'normal',
        payload: {
          commands: [
            ['M', sourcePos.x - dotR, sourcePos.y],
            ['C', sourcePos.x - dotR, sourcePos.y - dotR * 0.55, sourcePos.x - dotR * 0.55, sourcePos.y - dotR, sourcePos.x, sourcePos.y - dotR],
            ['C', sourcePos.x + dotR * 0.55, sourcePos.y - dotR, sourcePos.x + dotR, sourcePos.y - dotR * 0.55, sourcePos.x + dotR, sourcePos.y],
            ['C', sourcePos.x + dotR, sourcePos.y + dotR * 0.55, sourcePos.x + dotR * 0.55, sourcePos.y + dotR, sourcePos.x, sourcePos.y + dotR],
            ['C', sourcePos.x - dotR * 0.55, sourcePos.y + dotR, sourcePos.x - dotR, sourcePos.y + dotR * 0.55, sourcePos.x - dotR, sourcePos.y],
            ['Z']
          ],
          fill: strokeColor,
          stroke: '#ffffffff',
          strokeWidth: 1,
          vectorFillRule: 'nonzero'
        },
        transform: [1, 0, 0, 1, 0, 0]
      }
    }
  )

  return ops
}

import type { BoardModel, BoardNode } from '../model/project'
import { GraphColumnRuntime } from './graphColumnV2'
import { diagramState } from './diagramStructureCore'
import { patchBoardNode } from './boardMutationSafety'

export type GraphWritableAttribute = 'title' | 'body' | 'color' | 'textColor' | 'opacity'

/** An explicit authored command, never an evaluation side effect. The caller
 * publishes this immutable board through the ordinary undo/history boundary. */
export function writeGraphObjectAttribute(board: BoardModel, graphId: string, objectId: string, field: GraphWritableAttribute, value: string, readOnly = false): BoardModel {
  if (!board.nodes.some(n => n.id === graphId && n.graphColumn)) throw Error('Choose a Graph Column before sending changes.')
  const state = diagramState(board.nodes, graphId)
  if (readOnly || !state.ok || state.value.locked || state.value.hidden) throw Error('Unlock and show the graph before sending changes.')
  const records = new GraphColumnRuntime().evaluate(board, graphId)
  if (records.type !== 'records' || !records.value.some(r => r.objectId === objectId)) throw Error('Choose an object in this graph’s collected records.')
  if (!['title','body','color','textColor','opacity'].includes(field)) throw Error('Unsupported object attribute.')
  if (value.length > 200000) throw Error('Attribute text exceeds the edit limit.')
  let patch: Partial<BoardNode>
  if (field === 'opacity') {
    const opacity = Number(value)
    if (!value.trim() || !Number.isFinite(opacity) || opacity < 0 || opacity > 1) throw Error('Opacity must be between 0 and 1.')
    patch = {opacity}
  } else {
    if ((field === 'color' || field === 'textColor') && !/^(?:#[\da-f]{3}|#[\da-f]{4}|#[\da-f]{6}|#[\da-f]{8}|transparent)$/i.test(value.trim())) throw Error('Use a hexadecimal colour or transparent.')
    patch = {[field]:value}
  }
  const changed = patchBoardNode(board, objectId, patch, readOnly)
  if (!changed.ok) throw Error(changed.issues[0]?.detail || 'Object edit refused.')
  return changed.value
}

import { useMemo, useRef, useState } from 'react'
import type { BoardModel, BoardPoint, BoardNode } from '../model/project'
import { bindGraphColumnInputs, editGraphColumn } from './graphColumnV2'
import { diagramProjectionStates } from './diagramStructureCore'

const anchor=(node:BoardNode,x:number,y:number):BoardPoint=>{const a=(node.rotation||0)*Math.PI/180,dx=x-node.width/2,dy=y-node.height/2;return{x:node.x+node.width/2+dx*Math.cos(a)-dy*Math.sin(a),y:node.y+node.height/2+dx*Math.sin(a)+dy*Math.cos(a)}}
/** UI-only hit regions. Graph data retains object/port IDs; the renderer owns
 * the graph's visible pins. Magnetic hit distance is constant in screen pixels. */
export function GraphPortInteraction({board,readOnly,onChange,onError,onEdit}:{board:BoardModel;readOnly:boolean;onChange(board:BoardModel):void;onError(message:string):void;onEdit(id:string):void}) {
  const svg=useRef<SVGSVGElement>(null), [drag,setDrag]=useState<{source:string;from:BoardPoint;at:BoardPoint}|null>(null)
  const states=useMemo(()=>diagramProjectionStates(board.nodes),[board.nodes])
  const visible=useMemo(()=>states.ok?board.nodes.filter(n=>!states.value.get(n.id)?.hidden):[],[board.nodes,states])
  const targets=visible.flatMap(n=>n.graphColumn?[{id:n.id,point:anchor(n,0,n.height/2),input:undefined as string|undefined},...n.graphColumn.inputs.map((p,i)=>({id:n.id,point:anchor(n,0,n.height*(i+1)/(n.graphColumn!.inputs.length+1)),input:p.id}))]:[])
  const point=(event:React.PointerEvent)=>{const matrix=svg.current?.getScreenCTM();if(!matrix)return null;const p=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse());return{x:p.x,y:p.y}}
  const nearest=(p:BoardPoint,source:string)=>targets.filter(t=>t.id!==source).sort((a,b)=>Math.hypot(a.point.x-p.x,a.point.y-p.y)-Math.hypot(b.point.x-p.x,b.point.y-p.y) || Number(Boolean(b.input))-Number(Boolean(a.input))).find(t=>Math.hypot(t.point.x-p.x,t.point.y-p.y)<=14/board.viewport.scale)
  const hot=drag?nearest(drag.at,drag.source):undefined
  return <svg ref={svg} className="graph-v2-port-overlay graph-port-interaction" aria-label="Graph connection ports" onPointerMove={e=>{if(!drag)return;e.stopPropagation();const p=point(e);if(p)setDrag({...drag,at:p})}} onPointerCancel={()=>setDrag(null)} onPointerUp={e=>{if(!drag)return;e.stopPropagation();const p=point(e),target=p&&nearest(p,drag.source);setDrag(null);if(!target)return;try{const graph=board.nodes.find(n=>n.id===target.id)!;onChange(target.input?editGraphColumn(board,target.id,{inputs:graph.graphColumn!.inputs.map(i=>i.id===target.input?{...i,sourceId:drag.source}:i)}):bindGraphColumnInputs(board,target.id,[...graph.graphColumn!.inputs.map(i=>i.sourceId),drag.source]))}catch(error){onError(String(error))}}}>
    {visible.map(n=>{const p=anchor(n,n.width,n.height/2),s=states.ok?states.value.get(n.id):undefined;return <circle key={n.id} cx={p.x} cy={p.y} r={8/board.viewport.scale} className="graph-port-hit" role="button" tabIndex={readOnly?-1:0} aria-label={`Connect from ${n.title||n.kind}`} onKeyDown={e=>{if(e.key==='Enter'&&n.graphColumn){e.stopPropagation();onEdit(n.id)}}} onPointerDown={e=>{e.stopPropagation();e.preventDefault();if(readOnly||!s||s.locked)return;e.currentTarget.setPointerCapture(e.pointerId);setDrag({source:n.id,from:p,at:p})}}/>})}
    {targets.map(t=><circle key={t.id+':'+(t.input||'new')} cx={t.point.x} cy={t.point.y} r={8/board.viewport.scale} className={'graph-port-target'+(hot===t?' magnetic':'')} onPointerDown={e=>{e.stopPropagation();e.preventDefault();onEdit(t.id)}}><title>{t.input?'Reconnect input':'Connect to graph'}</title></circle>)}
    {drag&&<path className="graph-port-draft" d={`M${drag.from.x} ${drag.from.y} L${hot?.point.x??drag.at.x} ${hot?.point.y??drag.at.y}`} fill="none" stroke="#67d5cd" strokeWidth={1.5/board.viewport.scale}/>}
  </svg>
}

import { assetIntrinsicSize } from '../model/naturalImageBounds.ts'
import type { ImageDimensions } from '../model/imageFraming.ts'
import type { ProjectAsset } from '../model/project'

const dimensionCache = new Map<string, Promise<ImageDimensions>>()
const MAX_DIMENSION_CACHE_ENTRIES = 192
const DIMENSION_TIMEOUT_MS = 12_000
const MAX_PROBE_ORIGINAL_BYTES = 32 * 1024 * 1024

/** Shared placement/preview probe. Each source has one pending or successful
 * dimension promise; failed requests can retry. Settled probes release handlers,
 * their timer and their image source rather than retaining a decoder element. */
export function probeImageDimensions(source: string): Promise<ImageDimensions> {
  if (!source.trim()) return Promise.reject(new Error('Image source is unavailable'))
  const cached = dimensionCache.get(source)
  if (cached) return cached
  const pending = new Promise<ImageDimensions>((resolve, reject) => {
    const image = new Image()
    let settled = false
    const finish = (dimensions?: ImageDimensions, error?: Error) => {
      if (settled) return
      settled = true
      clearTimeout(timeout)
      image.onload = null
      image.onerror = null
      image.removeAttribute('src')
      if (dimensions) resolve(dimensions)
      else reject(error || new Error('Image dimensions are unavailable'))
    }
    image.onload = () => {
      const dimensions = { width: image.naturalWidth, height: image.naturalHeight }
      if (Number.isSafeInteger(dimensions.width) && Number.isSafeInteger(dimensions.height) && dimensions.width > 0 && dimensions.height > 0) finish(dimensions)
      else finish(undefined, new Error('Image dimensions are invalid'))
    }
    image.onerror = () => finish(undefined, new Error('Image dimensions are unavailable'))
    const timeout = setTimeout(() => finish(undefined, new Error('Image dimensions timed out after 12 seconds')), DIMENSION_TIMEOUT_MS)
    try { image.src = source } catch (error) {
      finish(undefined, error instanceof Error ? error : new Error(String(error)))
    }
  })
  dimensionCache.set(source, pending)
  if (dimensionCache.size > MAX_DIMENSION_CACHE_ENTRIES) dimensionCache.delete(dimensionCache.keys().next().value!)
  void pending.catch(() => {
    // An evicted older request must not remove a newer request for this source.
    if (dimensionCache.get(source) === pending) dimensionCache.delete(source)
  })
  return pending
}

/** Original dimensions only. Proxy rounding must never become saved image
 * geometry. Missing metadata on huge/tiled assets refuses a whole-image probe;
 * the caller can request native header metadata or prepare its pyramid. */
export async function readImageDimensions(asset: ProjectAsset | undefined, originalSource?: string): Promise<ImageDimensions | undefined> {
  const metadata = assetIntrinsicSize(asset)
  if (metadata) return metadata
  if (asset?.requiresTiledPreview || (asset?.byteLength ?? 0) > MAX_PROBE_ORIGINAL_BYTES) return undefined
  if (!originalSource) return undefined
  return probeImageDimensions(originalSource)
}

import type { BoardModel, BoardNode, ProjectAsset } from '../model/project'
import { diagramState, moveContainerWithDescendants } from './diagramStructureCore'
import { layoutBoardColumnsResult } from './columns'
import { boardNodeVisualBounds } from './arrangement'
import { assetIntrinsicSize, fitNaturalImageBounds } from '../model/naturalImageBounds'

export type PersistentLayoutGuide = {
  id: string; title: string; axis: 'x' | 'y'; anchor: 'start' | 'center' | 'end'
  mode?: 'manual' | 'relationship'
  position: number; members: Array<{ id: string; offset: number }>
}
export function createManualGuide(axis: 'x' | 'y', position: number): PersistentLayoutGuide {
  if (!Number.isFinite(position)) throw new Error('Guide position must be finite')
  return { id: crypto.randomUUID(), title: axis === 'x' ? 'Vertical ruler guide' : 'Horizontal ruler guide', axis, anchor: 'start', position, mode: 'manual', members: [] }
}
export type LayoutProposal = { source: string; board: BoardModel; warnings: string[]; moved: number }
export const layoutFingerprint = (board: BoardModel) => JSON.stringify([board.id, board.nodes, board.connectors, board.layoutGuides])
const parent = (node: BoardNode) => node.parentColumnId || node.groupId
const size = (node: BoardNode, axis: 'x' | 'y') => axis === 'x' ? node.width : node.height
const anchorOffset = (node: BoardNode, guide: Pick<PersistentLayoutGuide, 'axis' | 'anchor'>) => guide.anchor === 'start' ? 0 : size(node, guide.axis) * (guide.anchor === 'center' ? .5 : 1)

/** Ownership stays in the established column/group/portal model. */
export function layoutFamily(nodes: BoardNode[], id: string): Set<string> {
  const ids = new Set([id]); let changed = true
  while (changed) { changed = false; for (const node of nodes) if (parent(node) && ids.has(parent(node)!) && !ids.has(node.id)) { ids.add(node.id); changed = true } }
  return ids
}
function movableRoot(nodes: BoardNode[], node: BoardNode) {
  const family = layoutFamily(nodes, node.id)
  return !parent(node) && !node.rotation && !nodes.some((child) => {
    if (!family.has(child.id)) return false
    const state = diagramState(nodes, child.id)
    return !state.ok || state.value.locked || state.value.hidden || child.collapsed
  })
}
function shiftFamily(board: BoardModel, id: string, dx: number, dy: number) {
  const moved = moveContainerWithDescendants(board.nodes, board.connectors, [id], { x: dx, y: dy })
  return moved.ok ? { ...board, nodes: moved.value.nodes, connectors: moved.value.connectors } : board
}
export function createLayoutGuide(board: BoardModel, ids: string[], axis: 'x' | 'y', anchor: PersistentLayoutGuide['anchor']): PersistentLayoutGuide | null {
  const members = board.nodes.filter((node) => ids.includes(node.id) && movableRoot(board.nodes, node))
  if (members.length < 2) return null
  const position = members[0][axis] + anchorOffset(members[0], { axis, anchor })
  return { id: crypto.randomUUID(), title: `${axis === 'x' ? 'Vertical' : 'Horizontal'} ${anchor} guide`, axis, anchor, position,
    members: members.map((node) => ({ id: node.id, offset: node[axis] + anchorOffset(node, { axis, anchor }) - position })) }
}
export function moveLayoutGuide(board: BoardModel, id: string, position: number): BoardModel {
  const guide = board.layoutGuides?.find((entry) => entry.id === id)
  if (!guide || !Number.isFinite(position)) return board
  const members = guide.members.map((member) => board.nodes.find((node) => node.id === member.id))
  if (members.some((node) => !node || !movableRoot(board.nodes, node))) return board
  let next = board
  guide.members.forEach((member) => { const node = next.nodes.find((entry) => entry.id === member.id)!; const delta = position + member.offset - node[guide.axis] - anchorOffset(node, guide); next = shiftFamily(next, node.id, guide.axis === 'x' ? delta : 0, guide.axis === 'y' ? delta : 0) })
  return { ...next, layoutGuides: board.layoutGuides!.map((entry) => entry.id === id ? { ...entry, position } : entry) }
}
/** A manual member move becomes a retained optical tweak, never a snap-back. */
export function reconcileLayoutGuides(before: BoardModel, after: BoardModel): BoardModel {
  if (!after.layoutGuides?.length) return after
  const layoutGuides = after.layoutGuides.map((guide) => ({ ...guide, members: guide.members.filter((member) => after.nodes.some((node) => node.id === member.id && !parent(node))).map((member) => {
    const old = before.nodes.find((node) => node.id === member.id), next = after.nodes.find((node) => node.id === member.id)!
    return old && (old[guide.axis] !== next[guide.axis] || size(old, guide.axis) !== size(next, guide.axis)) && before.layoutGuides?.find((entry) => entry.id === guide.id)?.position === guide.position
      ? { ...member, offset: next[guide.axis] + anchorOffset(next, guide) - guide.position } : member
  }) })).filter((guide) => guide.mode === 'manual' || guide.members.length >= 2)
  return { ...after, layoutGuides }
}
const intersects = (a: BoardNode, b: BoardNode, gap: number) => a.x < b.x + b.width + gap && a.x + a.width + gap > b.x && a.y < b.y + b.height + gap && a.y + a.height + gap > b.y
function familyFootprint(board: BoardModel, root: BoardNode): BoardNode {
  const family = layoutFamily(board.nodes, root.id), boxes = board.nodes.filter((node) => family.has(node.id)).map(boardNodeVisualBounds)
  const x = Math.min(...boxes.map((box) => box.left)), y = Math.min(...boxes.map((box) => box.top))
  return { ...root, x, y, width: Math.max(...boxes.map((box) => box.right)) - x, height: Math.max(...boxes.map((box) => box.bottom)) - y }
}

export function proposeLayout(board: BoardModel, ids: string[], mode: 'rows' | 'columns', gap = 24): LayoutProposal {
  gap = Math.max(0, Number.isFinite(gap) ? gap : 24)
  const selected = new Set(ids.length ? ids : board.nodes.filter((node) => !parent(node)).map((node) => node.id))
  const roots = board.nodes.filter((node) => selected.has(node.id) && movableRoot(board.nodes, node))
  const warnings = board.nodes.filter((node) => selected.has(node.id) && !movableRoot(board.nodes, node)).map((node) => `${node.title || node.id}: retained because it is locked, contains a lock, or belongs to a container.`)
  if (!roots.length) return { source: layoutFingerprint(board), board, warnings, moved: 0 }
  const families = new Set(roots.flatMap((node) => [...layoutFamily(board.nodes, node.id)]))
  const obstacles = board.nodes.filter((node) => !families.has(node.id) && !parent(node)).map((node) => familyFootprint(board, node))
  const limit = Math.max(1, Math.ceil(Math.sqrt(roots.length)))
  let x = Math.min(...roots.map((node) => node.x)), y = Math.min(...roots.map((node) => node.y)), cross = 0, draft = board
  const startX = x, startY = y, placed: BoardNode[] = []
  roots.forEach((node, index) => {
    if (index && index % limit === 0) { if (mode === 'rows') { x = startX; y += cross + gap } else { y = startY; x += cross + gap }; cross = 0 }
    const footprint = familyFootprint(board, node)
    let candidate = { ...footprint, x, y }
    // A finite monotone sweep past each intersecting obstacle; never resize content.
    for (let pass = 0; pass <= obstacles.length + placed.length; pass++) {
      const hits = [...obstacles, ...placed].filter((obstacle) => intersects(candidate, obstacle, gap))
      if (!hits.length) break
      candidate = { ...candidate, y: Math.max(...hits.map((hit) => hit.y + hit.height + gap)) }
    }
    draft = shiftFamily(draft, node.id, candidate.x - footprint.x, candidate.y - footprint.y); placed.push(candidate)
    if (mode === 'rows') { x = candidate.x + footprint.width + gap; cross = Math.max(cross, candidate.y - y + footprint.height) }
    else { y = candidate.y + footprint.height + gap; cross = Math.max(cross, footprint.width) }
  })
  const next = reconcileLayoutGuides(board, draft)
  return { source: layoutFingerprint(board), board: next, warnings, moved: roots.filter((root) => { const node = draft.nodes.find((node) => node.id === root.id)!; return root.x !== node.x || root.y !== node.y }).length }
}
export function acceptLayoutProposal(board: BoardModel, proposal: LayoutProposal): BoardModel | null {
  return layoutFingerprint(board) === proposal.source ? proposal.board : null
}

export type HierarchySuggestion = { parentId: string; childId: string; reason: string; confidence: 'spatial' }
export function suggestLayoutHierarchy(board: BoardModel): HierarchySuggestion[] {
  const result: HierarchySuggestion[] = []
  const images = board.nodes.filter((node) => ['image', 'video', 'document'].includes(node.kind))
  for (const text of board.nodes.filter((node) => ['note', 'text'].includes(node.kind) && !parent(node))) {
    const candidates = images.filter((image) => !parent(image) && image.y + image.height <= text.y && text.y - image.y - image.height <= 48 && Math.min(image.x + image.width, text.x + text.width) - Math.max(image.x, text.x) >= Math.min(image.width, text.width) * .65)
      .sort((a, b) => text.y - a.y - a.height - (text.y - b.y - b.height))
    if (candidates.length && (candidates.length === 1 || candidates[0].y + candidates[0].height !== candidates[1].y + candidates[1].height)) result.push({ parentId: candidates[0].id, childId: text.id, reason: 'Text immediately below overlapping media; review as a possible caption.', confidence: 'spatial' })
    else {
      const below = images.filter((image) => !parent(image) && image.y >= text.y + text.height && image.y - text.y - text.height <= 48 && Math.min(image.x + image.width, text.x + text.width) - Math.max(image.x, text.x) >= Math.min(image.width, text.width) * .65)
      if (below.length === 1) result.push({ parentId: below[0].id, childId: text.id, reason: 'Text immediately above overlapping media; review as a possible heading.', confidence: 'spatial' })
    }
  }
  return result
}

export function groupHierarchySuggestion(board: BoardModel, suggestion: HierarchySuggestion): BoardModel {
  if (!suggestLayoutHierarchy(board).some((entry) => entry.parentId === suggestion.parentId && entry.childId === suggestion.childId)) return board
  const members = board.nodes.filter((node) => [suggestion.parentId, suggestion.childId].includes(node.id))
  if (members.length !== 2 || members.some((node) => !movableRoot(board.nodes, node))) return board
  const id = `research-group-${crypto.randomUUID()}`, x = Math.min(...members.map((node) => node.x)) - 12, y = Math.min(...members.map((node) => node.y)) - 32
  const group: BoardNode = { id, kind: 'group', title: members.find((node) => node.id === suggestion.childId)?.title || 'Media and text', x, y, width: Math.max(...members.map((node) => node.x + node.width)) - x + 12, height: Math.max(...members.map((node) => node.y + node.height)) - y + 12, color: '#38516d' }
  return reconcileLayoutGuides(board, { ...board, nodes: [...board.nodes.map((node) => members.includes(node) ? { ...node, groupId: id } : node), group] })
}

export function semanticClusterLabel(assetIds: string[], assets: ProjectAsset[], index: number) {
  const counts = new Map<string, number>()
  for (const id of assetIds) for (const tag of new Set(assets.find((asset) => asset.id === id)?.tags || [])) counts.set(tag, (counts.get(tag) || 0) + 1)
  const shared = [...counts].filter(([, count]) => count >= Math.max(2, assetIds.length * .5)).sort((a, b) => b[1] - a[1])[0]?.[0]
  return shared || `Visual references ${index + 1}`
}

export function organizeSemanticClusters(board: BoardModel, clusters: Array<{ title: string; assetIds: string[] }>, target: 'groups' | 'columns', assets: ProjectAsset[]): LayoutProposal {
  const source = layoutFingerprint(board), warnings: string[] = [], claimed = new Set<string>(), moved = new Set<string>()
  let nodes = [...board.nodes], x = Math.max(0, ...nodes.map((node) => node.x + node.width)) + 90
  clusters.forEach((cluster, clusterIndex) => {
    const id = `semantic-${board.id}-${clusterIndex}-${target}-${board.nodes.length}`, cards: BoardNode[] = []
    if (nodes.some((node) => node.id === id)) { warnings.push('A generated group identity already exists; retry the review.'); return }
    cluster.assetIds.forEach((assetId) => {
      if (claimed.has(assetId)) return; claimed.add(assetId)
      const existing = nodes.filter((node) => node.assetId === assetId)
      if (existing.some((node) => !movableRoot(nodes, node) || node.kind === 'group' || node.kind === 'column')) { warnings.push(`${assets.find((asset) => asset.id === assetId)?.displayName || assetId}: kept in its existing container or lock.`); return }
      const asset = assets.find((entry) => entry.id === assetId)
      if (!existing.length && !asset) return
      const fitted = fitNaturalImageBounds(assetIntrinsicSize(asset), { width: 250, height: 180 })
      if (!existing.length && !fitted) { warnings.push(`${asset!.displayName}: original dimensions unavailable; retained in Mini Bridge.`); return }
      const base = existing.length ? existing : [{ id: `${id}-asset-${cards.length}`, kind: 'image' as const, imagePresentation: 'artwork' as const, title: asset!.displayName, assetId, x: 0, y: 0, ...fitted! }]
      for (const node of base) { cards.push({ ...node, groupId: target === 'groups' ? id : undefined, parentColumnId: target === 'columns' ? id : undefined, columnOrder: target === 'columns' ? cards.length : undefined }); moved.add(node.id) }
    })
    if (!cards.length) return
    const width = Math.max(...cards.map((card) => card.width)) + 32
    let y = 142
    const positioned = cards.map((card) => { const next = { ...card, x: x + 16, y }; y += card.height + 24; return next })
    nodes = nodes.filter((node) => !positioned.some((card) => card.id === node.id))
    nodes.push({ id, kind: target === 'groups' ? 'group' : 'column', x, y: 90, width, height: y - 90, title: cluster.title, color: '#765a40', columnPreserveCardSizes: target === 'columns' }, ...positioned)
    x += width + 40
  })
  let next = { ...board, nodes }
  if (target === 'columns') {
    const newColumns = nodes.filter((node) => node.kind === 'column' && !board.nodes.some((old) => old.id === node.id)).map((node) => node.id)
    const result = layoutBoardColumnsResult(next, newColumns)
    if (!result.ok) return { source, board, warnings: [...warnings, result.issues[0]?.detail || 'Column arrangement refused.'], moved: 0 }
    next = result.value
  }
  return { source, board: reconcileLayoutGuides(board, next), warnings, moved: moved.size }
}

