/** Recover translation from the transformed AABB AND the known untransformed
 * size/linear map. Inverting the AABB alone loses rotation/skew/flip geometry. */
export function reconstructWorldMatrix(rect: CanvasRect, size: Size, linear: readonly [number, number, number, number], camera: CanvasViewport, stageOrigin: { x: number; y: number }): PaintMatrix | null {
  const [a, b, c, d] = linear
  if (!finite(...linear, rect.x, rect.y, rect.width, rect.height, size.width, size.height, camera.x, camera.y, camera.scale, stageOrigin.x, stageOrigin.y)
    || camera.scale <= 0 || size.width <= 0 || size.height <= 0 || rect.width <= 0 || rect.height <= 0 || Math.abs(a*d-b*c) < 1e-12) return null
  const xs = [0, a*size.width, c*size.height, a*size.width+c*size.height]
  const ys = [0, b*size.width, d*size.height, b*size.width+d*size.height]
  const expectedWidth = (Math.max(...xs)-Math.min(...xs))*camera.scale
  const expectedHeight = (Math.max(...ys)-Math.min(...ys))*camera.scale
  // Subpixel layout rounding, not permission to accept unrelated/stale boxes.
  if (Math.abs(expectedWidth-rect.width) > .1 || Math.abs(expectedHeight-rect.height) > .1) return null
  const e = (rect.x-stageOrigin.x-camera.x)/camera.scale-Math.min(...xs)
  const f = (rect.y-stageOrigin.y-camera.y)/camera.scale-Math.min(...ys)
  return finite(e, f) ? [a,b,c,d,e,f] : null
}

export function normalizeCornerRadii(css: readonly [string,string,string,string], size: Size): Radii | null {
  if (!finite(size.width,size.height) || size.width <= 0 || size.height <= 0) return null
  const result: [number,number][] = []
  for (const corner of css) {
    const values = corner.trim().split(/\s+/)
    if (values.length < 1 || values.length > 2) return null
    const pair = [values[0], values[1] ?? values[0]].map((v,i) => v.endsWith('%') && /^\d+(?:\.\d+)?%$/.test(v)
      ? Number.parseFloat(v)/100*(i===0 ? size.width : size.height) : px(v))
    if (pair.some(v => v === null || v < 0 || !finite(v))) return null
    result.push(pair as [number,number])
  }
  const [tl,tr,br,bl]=result
  const factor = Math.min(1, ...[[size.width,tl[0]+tr[0]],[size.width,bl[0]+br[0]],
    [size.height,tl[1]+bl[1]],[size.height,tr[1]+br[1]]].map(([edge,total])=>total ? edge/total : 1))
  return result.map(([x,y])=>[x*factor,y*factor] as const)
}

/** Standard cubic derivative for measured CSS elliptical corners. This is not
 * the independently certified ordinary ellipse drawing contour. */
export function roundedRectCommands(size: Size, radii: Radii): readonly CanvasVectorCommand[] {
  if (radii.length!==4 || !finite(size.width,size.height,...radii.flat()) || size.width<=0 || size.height<=0 || radii.some(p=>p[0]<0||p[1]<0)) throw new Error('CARD_LAYOUT_INVALID: rounded rectangle')
  const [tl,tr,br,bl]=radii, k=.5522847498307936, w=size.width,h=size.height
  return [['M',tl[0],0],['L',w-tr[0],0],['C',w-tr[0]*(1-k),0,w,tr[1]*(1-k),w,tr[1]],
    ['L',w,h-br[1]],['C',w,h-br[1]*(1-k),w-br[0]*(1-k),h,w-br[0],h],
    ['L',bl[0],h],['C',bl[0]*(1-k),h,0,h-bl[1]*(1-k),0,h-bl[1]],
    ['L',0,tl[1]],['C',0,tl[1]*(1-k),tl[0]*(1-k),0,tl[0],0],['Z']]
}

export type MeasuredCardPart = Readonly<{
  role: 'article'|'header'|'body'|'badge'|'surface'
  size: Size; worldMatrix: PaintMatrix; layoutBounds: CanvasRect; radii: Radii
  background: string | null; backgroundImage: string; opacity: number
  borderWidths: readonly number[]; borderColors: readonly (string|null)[]; borderStyles: readonly string[]
  overflowX: string; overflowY: string; isolation: string; blendMode: string
  boxShadow: string; filter: string; backdropFilter: string
  blockers: readonly string[]
}>
export type MeasuredCardPaint = Readonly<{
  objectId: string; objectRevision: number; order: number; mountEpoch: number
  status: 'measured-partial'|'invalid'; completePaint: false
  layoutBounds: CanvasRect | null; parts: readonly MeasuredCardPart[]; blockers: readonly string[]
}>
export type MeasuredCardPaintSnapshot = Readonly<{
  schema: 'art-equation.measured-card-paint'; sceneId: string; sceneRevision: number
  layoutRevision: number; camera: CanvasViewport; objects: readonly MeasuredCardPaint[]
  unmeasuredObjects: number
}>
const mountEpochs = new WeakMap<HTMLElement, number>()
let mountEpoch = 0
function union(a: CanvasRect|null,b: CanvasRect): CanvasRect {
  if (!a) return b
  const x=Math.min(a.x,b.x), y=Math.min(a.y,b.y)
  return {x,y,width:Math.max(a.x+a.width,b.x+b.width)-x,height:Math.max(a.y+a.height,b.y+b.height)-y}
}
export function measuredLinearWorld(element: Element, world: HTMLElement): readonly [number,number,number,number] | null {
  let result = new DOMMatrixReadOnly()
  const parents: Element[]=[]
  for (let current: Element|null=element;current && current!==world;current=current.parentElement) {
    if (parents.length>=32) return null
    parents.push(current)
  }
  for (const current of parents.reverse()) {
    const style=getComputedStyle(current)
    if (style.perspective !== 'none') return null
    const matrix=new DOMMatrixReadOnly(style.transform==='none' ? undefined : style.transform)
    if (!matrix.is2D) return null
    result=result.multiply(matrix)
  }
  return [result.a,result.b,result.c,result.d]
}
function partRole(element: HTMLElement, article: HTMLElement): MeasuredCardPart['role'] {
  if (element===article) return 'article'
  if (element.matches('.node-drag-handle')) return 'header'
  if (element.matches('.column-header-copy>small')) return 'badge'
  if (element.matches('.node-copy,.board-rich-text,.node-document,.transformed-image,.board-link-card')) return 'body'
  return 'surface'
}

/** Actual mounted layout only. No inferred card skin, saved layout registry,
 * text contents, resource pixels or permission to claim complete object paint. */
export function captureMeasuredCardPaint(stage: HTMLElement, scene: CanvasSceneSnapshot, camera: CanvasViewport, layoutRevision=0): MeasuredCardPaintSnapshot {
  const world=stage.querySelector<HTMLElement>(':scope > .board-world')
  const origin=stage.getBoundingClientRect(), stageOrigin={x:origin.left+stage.clientLeft,y:origin.top+stage.clientTop}
  const articles=world ? [...world.querySelectorAll<HTMLElement>(':scope > .board-object-layer > article.board-node[data-node-id]')] : []
  const byId=new Map<string,HTMLElement>(), duplicates=new Set<string>()
  for (const article of articles) { const id=article.dataset.nodeId!;if(byId.has(id))duplicates.add(id);byId.set(id,article) }
  const snapshot: MeasuredCardPaint[]=[]
  let totalParts=0
  const worldStyle=world && getComputedStyle(world)
  const worldMatrix=worldStyle && new DOMMatrixReadOnly(worldStyle.transform==='none' ? undefined : worldStyle.transform)
  const cameraCurrent=Boolean(worldMatrix && worldStyle?.transformOrigin==='0px 0px'
    && measuredCameraMatrixCurrent(worldMatrix,camera,{width:stage.clientWidth,height:stage.clientHeight}))
  for (const object of scene.objects.filter(o=>o.kind!=='vector' && !o.hidden)) {
    if (snapshot.length>=512) break
    const article=byId.get(object.id), blockers:string[]=[], parts:MeasuredCardPart[]=[]
    let envelope:CanvasRect|null=null
    const invalid=(reason:string)=>snapshot.push({objectId:object.id,objectRevision:object.revision,order:object.order,
      mountEpoch:article ? mountEpochs.get(article) ?? 0 : 0,status:'invalid',completePaint:false,layoutBounds:null,parts:[],blockers:[reason]})
    if (!world || !cameraCurrent || !finite(camera.x,camera.y,camera.scale) || camera.scale<=0) { invalid('CAMERA_LAYOUT_NOT_CURRENT');continue }
    if (!article || duplicates.has(object.id)) { invalid(article?'DUPLICATE_MOUNT_ID':'LAYOUT_NOT_MOUNTED');continue }
    if (article.dataset.velloPaint) { invalid('LAYOUT_PAINT_ALREADY_SUPPRESSED');continue }
    if (!mountEpochs.has(article)) mountEpochs.set(article,++mountEpoch)
    const elements=[article,...article.querySelectorAll<HTMLElement>('*')]
    if (elements.length>128 || totalParts+elements.length>4096 || snapshot.length>=512) { invalid('LAYOUT_MEASUREMENT_LIMIT');continue }
    totalParts+=elements.length
    if (article.textContent?.trim()) blockers.push('TEXT_SHAPING_PENDING')
    if (article.querySelector('img,video,canvas,iframe,svg,object,embed')) blockers.push('RESOURCE_OR_PROVIDER_PAINT_PENDING')
    for (const element of elements) {
      if (!(element instanceof HTMLElement)) continue
      const style=getComputedStyle(element)
      if (style.display==='none' || style.visibility==='hidden' || style.visibility==='collapse') continue
      if (style.display==='contents') { blockers.push('DISPLAY_CONTENTS_PENDING');continue }
      const rect=element.getBoundingClientRect()
      if (!rect.width || !rect.height) continue
      const bounds={x:(rect.left-stageOrigin.x-camera.x)/camera.scale,y:(rect.top-stageOrigin.y-camera.y)/camera.scale,width:rect.width/camera.scale,height:rect.height/camera.scale}
      if (!finite(bounds.x,bounds.y,bounds.width,bounds.height,bounds.x+bounds.width,bounds.y+bounds.height)) { blockers.push('NONFINITE_OR_UNBOUNDED_LAYOUT');continue }
      envelope=union(envelope,bounds)
      const size=borderBoxSize(style), linear=measuredLinearWorld(element,world)
      const matrix=size && linear && reconstructWorldMatrix({x:rect.left,y:rect.top,width:rect.width,height:rect.height},size,linear,camera,stageOrigin)
      if (!size || !matrix) { blockers.push('FRAGMENTED_OR_UNSUPPORTED_BOX');continue }
      const radii=normalizeCornerRadii([style.borderTopLeftRadius,style.borderTopRightRadius,style.borderBottomRightRadius,style.borderBottomLeftRadius],size)
      if (!radii) { blockers.push('UNRESOLVED_CORNER_RADII');continue }
      const partBlockers:string[]=[]
      const background=normalizeMeasuredColor(style.backgroundColor)
      const borderColors=[style.borderTopColor,style.borderRightColor,style.borderBottomColor,style.borderLeftColor].map(normalizeMeasuredColor)
      const borderWidths=[style.borderTopWidth,style.borderRightWidth,style.borderBottomWidth,style.borderLeftWidth].map(v=>px(v) ?? NaN)
      const borderStyles=[style.borderTopStyle,style.borderRightStyle,style.borderBottomStyle,style.borderLeftStyle]
      if (!background || borderColors.some(c=>!c)) partBlockers.push('UNRESOLVED_CSS_COLOR')
      if (!borderWidths.every(v=>finite(v)&&v>=0)) partBlockers.push('UNRESOLVED_BORDER_WIDTH')
      if (borderStyles.some(s=>s!=='solid'&&s!=='none')) partBlockers.push('BORDER_STYLE_PENDING')
      if (style.backgroundImage!=='none') partBlockers.push('BACKGROUND_IMAGE_OR_GRADIENT_PENDING')
      if (style.boxShadow!=='none' || style.textShadow!=='none') partBlockers.push('SHADOW_PAINT_PENDING')
      if (style.filter!=='none' || style.backdropFilter!=='none') partBlockers.push('FILTER_PAINT_PENDING')
      if (style.mixBlendMode!=='normal') partBlockers.push('CSS_BLEND_PENDING')
      if (style.clipPath!=='none' || style.maskImage!=='none' || style.borderImageSource!=='none') partBlockers.push('MASK_OR_BORDER_IMAGE_PENDING')
      if (style.animationName!=='none' || style.transitionDuration.split(',').some(t=>Number.parseFloat(t)>0)) partBlockers.push('DYNAMIC_STYLE_PENDING')
      for (const pseudo of ['::before','::after']) {
        const p=getComputedStyle(element,pseudo)
        if (p.content!=='none' && p.content!=='normal' && p.display!=='none') partBlockers.push('PSEUDO_ELEMENT_PAINT_PENDING')
      }
      const opacity=Number(style.opacity)
      if (!Number.isFinite(opacity)||opacity<0||opacity>1) partBlockers.push('INVALID_OPACITY')
      parts.push({role:partRole(element,article),size,worldMatrix:matrix,layoutBounds:bounds,radii,background,
        backgroundImage:style.backgroundImage,opacity,borderWidths,borderColors,borderStyles,overflowX:style.overflowX,
        overflowY:style.overflowY,isolation:style.isolation,blendMode:style.mixBlendMode,boxShadow:style.boxShadow,
        filter:style.filter,backdropFilter:style.backdropFilter,blockers:partBlockers})
      blockers.push(...partBlockers)
    }
    // Root geometry must match the CURRENT live scene, not a prior DOM commit.
    const root=parts.find(p=>p.role==='article'), local=object.localBounds
    const angle=object.appearance.rotation*Math.PI/180, cos=Math.cos(angle),sin=Math.sin(angle)
    const rootCurrent=root && local && Math.abs(root.size.width-local.width)<=.1 && Math.abs(root.size.height-local.height)<=.1
      && Math.abs(root.worldMatrix[0]-cos)<1e-6 && Math.abs(root.worldMatrix[1]-sin)<1e-6
      && Math.abs(root.worldMatrix[2]+sin)<1e-6 && Math.abs(root.worldMatrix[3]-cos)<1e-6
      && Math.abs(root.worldMatrix[0]*root.size.width/2+root.worldMatrix[2]*root.size.height/2+root.worldMatrix[4]-local.x-local.width/2)<=.1
      && Math.abs(root.worldMatrix[1]*root.size.width/2+root.worldMatrix[3]*root.size.height/2+root.worldMatrix[5]-local.y-local.height/2)<=.1
    if (!rootCurrent) blockers.push('OBJECT_LAYOUT_NOT_CURRENT')
    blockers.push('COMPLETE_CARD_OWNERSHIP_PENDING')
    snapshot.push({objectId:object.id,objectRevision:object.revision,order:object.order,mountEpoch:mountEpochs.get(article)!,
      status:root && !blockers.includes('OBJECT_LAYOUT_NOT_CURRENT')?'measured-partial':'invalid',completePaint:false,
      layoutBounds:envelope,parts,blockers:[...new Set(blockers)]})
  }
  return {schema:'art-equation.measured-card-paint',sceneId:scene.id,sceneRevision:scene.revision,layoutRevision,camera:{...camera},objects:snapshot,
    unmeasuredObjects:scene.objects.reduce((count,o)=>count+(o.kind!=='vector'&&!o.hidden?1:0),0)-snapshot.length}
}

/** A qualified primitive contribution for isolated diagnostics/future compiler.
 * It is NOT a card list and must never authorize production ownership. */
export function compileMeasuredSurface(part: MeasuredCardPart, id: string): { operations: readonly PaintOperation[]; completePaint: false; blockers: readonly string[] } {
  const blockers=[...part.blockers]
  if (!finite(part.size.width,part.size.height) || part.size.width<=0 || part.size.height<=0
    || part.radii.length!==4 || part.radii.some(pair=>pair.length!==2||!finite(...pair)||pair.some(n=>n<0))
    || part.borderWidths.length!==4 || part.borderWidths.some(n=>!finite(n)||n<0)
    || part.borderColors.length!==4 || part.borderStyles.length!==4) blockers.push('SURFACE_GEOMETRY_INVALID')
  if (part.opacity!==1) blockers.push('SURFACE_SUBTREE_OPACITY_PENDING')
  if (part.borderWidths.some(w=>w!==part.borderWidths[0]) || part.borderColors.some(c=>c!==part.borderColors[0])) blockers.push('ASYMMETRIC_BORDER_PAINT_PENDING')
  if (!part.background || !/^#[a-f0-9]{8}$/i.test(part.background) || part.borderColors.some(c=>!c||!/^#[a-f0-9]{8}$/i.test(c))) blockers.push('UNRESOLVED_CSS_COLOR')
  if (part.borderStyles.some(s=>s!==part.borderStyles[0]) || part.borderStyles.some(s=>s!=='solid'&&s!=='none')) blockers.push('BORDER_STYLE_PENDING')
  if (part.backgroundImage!=='none' || part.boxShadow!=='none' || part.filter!=='none' || part.backdropFilter!=='none' || part.blendMode!=='normal') blockers.push('SURFACE_EFFECT_PAINT_PENDING')
  // An inset border can require another CSS corner-overlap reduction even
  // when the measured outer radii fit. Refuse that case until its CSS inner
  // contour is independently qualified; never emit a self-crossing ring.
  if (part.radii.length===4 && part.borderWidths.length===4) {
    const inset=part.borderWidths[0], iw=part.size.width-2*inset, ih=part.size.height-2*inset
    if (iw>0 && ih>0) {
      const [tl,tr,br,bl]=part.radii.map(([x,y])=>[Math.max(0,x-inset),Math.max(0,y-inset)])
      if (tl[0]+tr[0]>iw || bl[0]+br[0]>iw || tl[1]+bl[1]>ih || tr[1]+br[1]>ih) blockers.push('INSET_RADIUS_OVERLAP_PENDING')
    }
  }
  if (!id || !finite(...part.worldMatrix)) blockers.push('SURFACE_ID_OR_MATRIX_INVALID')
  if (blockers.length) return {operations:[],completePaint:false,blockers:[...new Set(blockers)]}
  const operations:PaintOperation[]=[]
  operations.push({type:'vector',object:{id:id+':background',kind:'vector',transform:part.worldMatrix,
    payload:{commands:roundedRectCommands(part.size,part.radii),fill:part.background,strokeWidth:0}}})
  const width=part.borderStyles[0]==='solid'?part.borderWidths[0]:0
  if (width>0) {
    const outer=roundedRectCommands(part.size,part.radii), innerSize={width:part.size.width-2*width,height:part.size.height-2*width}
    const inner=innerSize.width>0&&innerSize.height>0 ? roundedRectCommands(innerSize,part.radii.map(([x,y])=>[Math.max(0,x-width),Math.max(0,y-width)]))
      .map(command=>command.map((n,index)=>index===0?n:typeof n==='number'?n+width:n) as unknown as CanvasVectorCommand) : []
    operations.push({type:'vector',object:{id:id+':border',kind:'vector',transform:part.worldMatrix,
      payload:{commands:[...outer,...inner],fill:part.borderColors[0],vectorFillRule:'evenodd',strokeWidth:0}}})
  }
  return {operations,completePaint:false,blockers:['COMPLETE_CARD_OWNERSHIP_PENDING']}
}

/**
 * Art Equation Canvas Engine - Media Fidelity Engine
 *
 * Implements strict separation of MediaAsset from MediaPlacement:
 * - Natural width/height, orientation, originalUri, and proxies preserved.
 * - Uniform scaling: contain | cover | crop | native.
 * - Strict prohibition of independent X/Y scaling (zero distortion).
 * - Video asset metadata: duration, poster frame, filmstrip keyframes, and time-range annotations.
 */

export type MediaFitMode = 'contain' | 'cover' | 'crop' | 'native'

export interface VideoMetadata {
  durationSec: number
  codec?: string
  width: number
  height: number
  fps?: number
  posterKey?: string
  filmstripKey?: string
  keyframeTimestamps?: number[]
}

export interface MediaAsset {
  assetId: string
  originalUri: string
  intrinsicWidth: number
  intrinsicHeight: number
  orientation?: number
  colorProfile?: string
  checksum?: string
  proxyUris?: {
    thumb?: string
    medium?: string
    high?: string
  }
  video?: VideoMetadata
}

export interface NormalizedRect {
  x: number // 0.0 - 1.0
  y: number // 0.0 - 1.0
  width: number // 0.0 - 1.0
  height: number // 0.0 - 1.0
}

export interface MediaPlacement {
  cardId: string
  assetId: string
  frameRect: {
    x: number
    y: number
    width: number
    height: number
  }
  fitMode: MediaFitMode
  cropRectNormalized?: NormalizedRect
  rotation?: number // in degrees
}

export interface ComputedMediaFit {
  // Destination position and size on canvas
  destX: number
  destY: number
  destWidth: number
  destHeight: number
  // Source crop rectangle inside the original asset
  srcX: number
  srcY: number
  srcWidth: number
  srcHeight: number
  // Transform scale factors (uniform!)
  scale: number
  uniformScaleX: number
  uniformScaleY: number
}

/**
 * Calculates uniform, aspect-ratio-preserving media placement.
 * Ensures zero image distortion under all standard fit modes.
 */
export function calculateMediaFit(
  asset: { intrinsicWidth: number; intrinsicHeight: number },
  placement: {
    frameRect: { x: number; y: number; width: number; height: number }
    fitMode: MediaFitMode
    cropRectNormalized?: NormalizedRect
  }
): ComputedMediaFit {
  const { intrinsicWidth: iw, intrinsicHeight: ih } = asset
  const { frameRect, fitMode, cropRectNormalized } = placement
  const { x: fx, y: fy, width: fw, height: fh } = frameRect

  if (iw <= 0 || ih <= 0 || fw <= 0 || fh <= 0) {
    return {
      destX: fx,
      destY: fy,
      destWidth: fw,
      destHeight: fh,
      srcX: 0,
      srcY: 0,
      srcWidth: Math.max(1, iw),
      srcHeight: Math.max(1, ih),
      scale: 1,
      uniformScaleX: 1,
      uniformScaleY: 1
    }
  }

  // Calculate effective source area if a normalized crop rectangle is provided
  let sx = 0
  let sy = 0
  let sw = iw
  let sh = ih

  if (cropRectNormalized) {
    const cx = Math.max(0, Math.min(1, cropRectNormalized.x))
    const cy = Math.max(0, Math.min(1, cropRectNormalized.y))
    const cw = Math.max(0.01, Math.min(1 - cx, cropRectNormalized.width))
    const ch = Math.max(0.01, Math.min(1 - cy, cropRectNormalized.height))
    sx = cx * iw
    sy = cy * ih
    sw = cw * iw
    sh = ch * ih
  }

  const assetAspect = sw / sh
  const frameAspect = fw / fh

  let destX = fx
  let destY = fy
  let destWidth = fw
  let destHeight = fh
  let scale = 1

  switch (fitMode) {
    case 'contain': {
      // Scale uniformly until either width or height touches the frame boundary
      if (assetAspect > frameAspect) {
        // Limited by frame width
        scale = fw / sw
        destWidth = fw
        destHeight = sh * scale
        destX = fx
        destY = fy + (fh - destHeight) / 2 // Center vertically
      } else {
        // Limited by frame height
        scale = fh / sh
        destHeight = fh
        destWidth = sw * scale
        destX = fx + (fw - destWidth) / 2 // Center horizontally
        destY = fy
      }
      break
    }

    case 'cover': {
      // Scale uniformly until the entire frame is filled, clipping excess
      if (assetAspect > frameAspect) {
        // Fill frame height, clip horizontal sides
        scale = fh / sh
        const visibleSrcWidth = fw / scale
        sx += (sw - visibleSrcWidth) / 2
        sw = visibleSrcWidth
        destWidth = fw
        destHeight = fh
      } else {
        // Fill frame width, clip vertical top/bottom
        scale = fw / sw
        const visibleSrcHeight = fh / scale
        sy += (sh - visibleSrcHeight) / 2
        sh = visibleSrcHeight
        destWidth = fw
        destHeight = fh
      }
      break
    }

    case 'native': {
      // 1:1 pixel mapping, centered
      scale = 1
      destWidth = sw
      destHeight = sh
      destX = fx + (fw - destWidth) / 2
      destY = fy + (fh - destHeight) / 2
      break
    }

    case 'crop':
    default: {
      // Uses cropRectNormalized directly, fitted to the frame bounds with aspect preservation
      scale = Math.min(fw / sw, fh / sh)
      destWidth = sw * scale
      destHeight = sh * scale
      destX = fx + (fw - destWidth) / 2
      destY = fy + (fh - destHeight) / 2
      break
    }
  }

  return {
    destX,
    destY,
    destWidth,
    destHeight,
    srcX: sx,
    srcY: sy,
    srcWidth: sw,
    srcHeight: sh,
    scale,
    uniformScaleX: scale,
    uniformScaleY: scale
  }
}

/**
 * Creates Display List v2 operations for rendering an image asset with uniform fit mode.
 */
export function createMediaRenderOp(
  opId: string,
  resourceRef: { key: string; width: number; height: number; revision: number; epoch: number },
  computedFit: ComputedMediaFit,
  opacity: number = 1.0
): any {
  // Transform places image at destX, destY scaled uniformly by computedFit.scale
  // Note: if covered or cropped, sourceRect selects the visible region of the texture
  const sx = computedFit.scale
  const sy = computedFit.scale
  const tx = computedFit.destX - sx * computedFit.srcX
  const ty = computedFit.destY - sy * computedFit.srcY

  return {
    type: 'image',
    id: opId,
    resource: {
      key: resourceRef.key,
      revision: resourceRef.revision || 1,
      epoch: resourceRef.epoch || 1,
      width: resourceRef.width,
      height: resourceRef.height
    },
    sourceRect: {
      x: computedFit.srcX,
      y: computedFit.srcY,
      width: computedFit.srcWidth,
      height: computedFit.srcHeight
    },
    transform: [sx, 0, 0, sy, tx, ty],
    opacity,
    sampling: 'bilinear'
  }
}

import type { CanvasSceneObject, CanvasSceneSnapshot } from '../canvas-engine/contracts'
import type { BoardNode } from '../model/project'
import { boardNodeVisualBounds } from './arrangement'
import { connectorSvgMarkup } from './connectors'
import { escapeSvg, vectorNodeSvgMarkup } from './vectorSvg'
import { imageDrawRect } from '../model/imageFraming'

export type MinimapBounds = { minX: number; minY: number; maxX: number; maxY: number }
export type MinimapImage = { source: string; width: number; height: number }

export function minimapBounds(objects: readonly CanvasSceneObject[], stageWidth: number, stageHeight: number, nodes?: readonly BoardNode[]): MinimapBounds {
  const visible = objects.filter((object) => !object.hidden)
  if (!visible.length) return { minX: -40, minY: -40, maxX: stageWidth + 40, maxY: stageHeight + 40 }
  const byId = new Map(nodes?.map((node) => [node.id, node]))
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
  for (const object of visible) {
    const node = byId.get(object.id)
    const box = node ? boardNodeVisualBounds(node) : { left: object.bounds.x, top: object.bounds.y, right: object.bounds.x + object.bounds.width, bottom: object.bounds.y + object.bounds.height }
    minX = Math.min(minX, box.left); minY = Math.min(minY, box.top)
    maxX = Math.max(maxX, box.right); maxY = Math.max(maxY, box.bottom)
  }
  return { minX: minX - 40, minY: minY - 40, maxX: maxX + 40, maxY: maxY + 40 }
}

export function mapToMinimap(bounds: MinimapBounds, width: number, height: number) {
  const padding = 7
  const scale = Math.max(.00001, Math.min(Math.max(1, width - padding * 2) / Math.max(1, bounds.maxX - bounds.minX), Math.max(1, height - padding * 2) / Math.max(1, bounds.maxY - bounds.minY)))
  const offsetX = (width - (bounds.maxX - bounds.minX) * scale) / 2
  const offsetY = (height - (bounds.maxY - bounds.minY) * scale) / 2
  return { scale, offsetX, offsetY, x: (value: number) => offsetX + (value - bounds.minX) * scale, y: (value: number) => offsetY + (value - bounds.minY) * scale }
}

function fallbackNode(object: CanvasSceneObject): BoardNode {
  const box = object.localBounds || object.bounds
  return {
    id: object.id, kind: object.kind === 'vector' ? 'shape' : object.kind === 'container' ? 'group' : 'note', title: '',
    x: box.x, y: box.y, width: box.width, height: box.height,
    color: object.appearance.fill, strokeColor: object.appearance.stroke, opacity: object.appearance.opacity,
    strokeWidth: object.appearance.strokeWidth, cornerRadius: object.appearance.cornerRadius, rotation: object.appearance.rotation,
    vectorFillRule: object.appearance.vectorFillRule, vectorStrokeJoin: object.appearance.vectorStrokeJoin, vectorStrokeCap: object.appearance.vectorStrokeCap,
    ...(object.vectorPath ? { shapeType: 'path' as const, vectorPath: { ...object.vectorPath, points: object.vectorPath.points.map((point) => ({ ...point })) } } : {}),
  }
}

function nodeMarkup(node: BoardNode, image?: MinimapImage, headerHeight = 0): string {
  if (node.kind === 'shape' && node.shapeType === 'path' && node.vectorPath) return vectorNodeSvgMarkup(node, node.x, node.y, 'minimap')
  const safe = escapeSvg, cx = node.x + node.width / 2, cy = node.y + node.height / 2
  const opacity = Math.max(0, Math.min(1, node.opacity ?? 1))
  const stroke = safe(node.strokeColor || '#a8b1bd'), fill = safe(node.color || '#6e7785')
  const attrs = `fill="${fill}" stroke="${stroke}" stroke-width="${safe(node.strokeWidth ?? 1)}"`
  const transform = node.rotation ? ` transform="rotate(${safe(node.rotation)} ${safe(cx)} ${safe(cy)})"` : ''
  let shape: string
  if (node.shapeType === 'ellipse') shape = `<ellipse cx="${safe(cx)}" cy="${safe(cy)}" rx="${safe(node.width / 2)}" ry="${safe(node.height / 2)}" ${attrs}/>`
  else if (node.shapeType === 'line' || node.shapeType === 'arrow') shape = `<line x1="${safe(node.x)}" y1="${safe(node.y)}" x2="${safe(node.x + node.width)}" y2="${safe(node.y + node.height)}" stroke="${stroke}" stroke-width="${safe(node.strokeWidth ?? 2)}"/>`
  else shape = `<rect x="${safe(node.x)}" y="${safe(node.y)}" width="${safe(node.width)}" height="${safe(node.height)}" rx="${safe(node.cornerRadius || 0)}" ${attrs}/>`
  if (image) {
    const body = { width: node.width, height: Math.max(1, node.height - headerHeight) }
    const fit = imageDrawRect(image, body, node.imageTransform)
    if (fit) {
      const id = `minimap-image-${[...node.id].map(c=>c.codePointAt(0)!.toString(16)).join('-')}`
      const framing = node.imageTransform
      const centerY = node.y + headerHeight + body.height / 2
      const imageTransform = `translate(${safe(cx)} ${safe(centerY)}) rotate(${safe(framing?.rotation || 0)}) scale(${framing?.flipX ? -1 : 1} ${framing?.flipY ? -1 : 1}) translate(${safe(-cx)} ${safe(-centerY)})`
      const markup = `<defs><clipPath id="${id}"><rect x="${safe(node.x)}" y="${safe(node.y + headerHeight)}" width="${safe(body.width)}" height="${safe(body.height)}" rx="${safe(node.cornerRadius || 0)}"/></clipPath></defs><g clip-path="url(#${id})"><image href="${safe(image.source)}" x="${safe(node.x+fit.x)}" y="${safe(node.y+headerHeight+fit.y)}" width="${safe(fit.width)}" height="${safe(fit.height)}" preserveAspectRatio="none" transform="${imageTransform}" opacity="${safe(framing?.opacity ?? 1)}"${framing?.grayscale ? ' filter="url(#minimap-grayscale)"' : ''}/></g>`
      return `<g${transform} opacity="${safe(opacity)}">${shape}${markup}</g>`
    }
  }
  return `<g${transform} opacity="${safe(node.kind === 'column' || node.kind === 'group' ? opacity * .45 : opacity)}">${shape}</g>`
}

/** Use the canonical path instead of the broad-phase rectangular hit envelope.
 * The scene stays retained; camera updates redraw only its viewport outline. */
export function minimapSceneSvg(scene: CanvasSceneSnapshot, nodes: readonly BoardNode[] | undefined, bounds: MinimapBounds, width: number, height: number, images?: ReadonlyMap<string, MinimapImage>): string {
  const byId = new Map(nodes?.map((node) => [node.id, node]))
  const visible = scene.objects.filter((object) => !object.hidden).sort((a, b) => a.order - b.order)
  const canonical = visible.map((object) => byId.get(object.id) || fallbackNode(object))
  const map = mapToMinimap(bounds, width, height)
  const safe = escapeSvg
  const ids = new Set(canonical.map(node => node.id))
  const connections = scene.connections.filter(connection => (!connection.sourceId || ids.has(connection.sourceId)) && (!connection.targetId || ids.has(connection.targetId))).map((connection) => connectorSvgMarkup(connection, canonical, 'minimap')).join('')
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${safe(width)}" height="${safe(height)}" viewBox="0 0 ${safe(width)} ${safe(height)}"><defs><filter id="minimap-grayscale"><feColorMatrix type="saturate" values="0"/></filter></defs><rect width="100%" height="100%" fill="${safe(scene.environment.background)}"/><g transform="translate(${safe(map.offsetX)} ${safe(map.offsetY)}) scale(${safe(map.scale)}) translate(${safe(-bounds.minX)} ${safe(-bounds.minY)})">${connections}${canonical.map((node,index)=>nodeMarkup(node,images?.get(node.id),visible[index].modelArtwork?.kind==='image' ? visible[index].modelArtwork.header?.height || 0 : 0)).join('')}</g></svg>`
}

import {parseFragment,html,type DefaultTreeAdapterTypes} from 'parse5'
import {validPyramid} from '../canvas-engine/imagePyramid'
import parseInlineStyle from 'inline-style-parser'
import type { BoardNode, ProjectAsset } from '../model/project'
import type { CanvasSceneObject } from '../canvas-engine/contracts'

// Pure saved-source parsing: no browser DOM, editor access or CSSOM layout.
// Unsupported source constructs remain explicit rather than being flattened.
export function projectModelArtwork(node: BoardNode, asset: ProjectAsset | undefined, source?: string, tilesSource?:string): CanvasSceneObject['modelArtwork'] {
  if(node.kind==='image' && asset?.status!=='missing' && asset?.status!=='modified' && validPyramid(asset?.imagePyramid) && tilesSource && source && !node.imageTransform?.overlay && (!node.imageTransform?.blendMode||['source-over','multiply','screen'].includes(node.imageTransform.blendMode)))return {kind:'image',source,sourceRevision:1,pyramid:asset.imagePyramid,tilesSource,framing:node.imageTransform,header:node.imagePresentation==='artwork'?undefined:{title:node.title,fill:'#22252c',color:node.textColor||'#dfe1e6',height:37}}
  if (node.kind === 'image' && (!node.imageTransform?.blendMode || ['source-over','multiply','screen'].includes(node.imageTransform.blendMode)) &&
      !asset?.imagePyramid && !asset?.requiresTiledPreview && asset?.status !== 'missing' &&
      (!asset || asset.imageDimensions && asset.imageDimensions.width <= 4096 && asset.imageDimensions.height <= 4096) &&
      source && /^(png|jpe?g|bmp|ico|webp|tiff?)$/i.test(asset?.extension || (source.startsWith('data:image/png') ? 'png' : ''))) {
    return { kind: 'image', source, sourceRevision: 1, sourceDimensions:asset?.imageDimensions, extension: asset?.extension, framing: node.imageTransform, header: node.imagePresentation==='artwork' ? undefined : {title:node.title,fill:'#22252c',color:node.textColor || '#dfe1e6',height:37} }
  }
  if (!['text','note','column','group','document','board-link','clip'].includes(node.kind) || node.graphColumn) return undefined
  if (node.coverAssetId) return undefined
  if ((node.kind === 'document' && node.assetId) || node.kind === 'board-link' || (node.kind === 'clip' && node.assetId) || (node.kind === 'group' && (node.containerRole === 'frame' || /\bframe\b/i.test(node.title)))) return undefined
  const plain = node.kind !== 'text' && node.kind !== 'clip'
  type SourceNode=DefaultTreeAdapterTypes.ChildNode
  const sourceHtml=plain ? '<p></p>' : node.kind === 'clip' ? node.captured?.articleHtml || node.captured?.transcriptHtml || '<p></p>' : node.body || '<p>New text</p>'
  if(new TextEncoder().encode(sourceHtml).length>2_000_000)return undefined
  const sourceTree=parseFragment(sourceHtml)
  const pending=sourceTree.childNodes.map(node=>({node,depth:0}));let sourceNodes=0
  while(pending.length){const {node,depth}=pending.pop()!;if(++sourceNodes>16384||depth>128)return undefined;if('childNodes' in node)for(const child of node.childNodes)pending.push({node:child,depth:depth+1})}
  const tag=(node:SourceNode)=>'tagName' in node?node.tagName.toUpperCase():''
  const children=(node:SourceNode)=>'childNodes' in node?node.childNodes:[]
  const attr=(node:SourceNode,name:string)=>'attrs' in node?node.attrs.find(attr=>attr.name===name)?.value:''
  const styles=new WeakMap<object,Record<string,string>>()
  let qualified=true
  const styleOf=(node:SourceNode)=>{let result=styles.get(node);if(!result){result={};try{for(const value of parseInlineStyle(attr(node,'style') || ''))if(value.type==='declaration')result[value.property.toLowerCase()]=value.value}catch{qualified=false};styles.set(node,result)}return result}
  const styledRun=(nodes:SourceNode[]):SourceNode|undefined=>{for(const node of nodes){if(tag(node)==='SPAN'&&attr(node,'style'))return node;const found=styledRun(children(node));if(found)return found}}
  const first=styledRun(sourceTree.childNodes),firstStyle=first?styleOf(first):{}
  const textNode=(value:string):SourceNode=>({nodeName:'#text',value,parentNode:null})
  if(plain)sourceTree.childNodes=[{nodeName:'p',tagName:'p',attrs:[],namespaceURI:html.NS.HTML,parentNode:sourceTree,childNodes:[textNode(['column','group'].includes(node.kind)?'':node.body || '')]}]
  const family = (value: string) => value.trim().replace(/^(['"])(.*)\1$/, '$2')
  const number = (value: string, fallback: number) => value ? Number.parseFloat(value) : fallback
  const base = { family: family(firstStyle['font-family'] || 'Segoe UI'), size: number(firstStyle['font-size'] || '', node.textMode ? 32 : node.kind === 'note' ? 10 : 11),
    weight: number(firstStyle['font-weight'] || '', 400), italic: false, lineHeight: number(firstStyle['line-height'] || '', 1.2),
    spacing: 0, color: node.textColor || (node.kind === 'note' ? '#29231e' : '#dfe1e6'), underline: false, strike: false, highlight: undefined as string | undefined }
  type Style = typeof base
  const spans: NonNullable<Extract<CanvasSceneObject['modelArtwork'], {kind:'type'}>>['spans'][number][] = []
  const blocks: NonNullable<Extract<CanvasSceneObject['modelArtwork'], {kind:'type'}>>['blocks'] extends readonly (infer B)[] | undefined ? B[] : never = []
  let text = '', bytes = 0
  function visit(element: SourceNode, inherited: Style, explicitWeight = false) {
    if (element.nodeName === '#text') {
      const run = 'value' in element ? element.value : '', end = bytes + new TextEncoder().encode(run).length
