type Vertex = { x: number; y: number; u: number; v: number }
export type ImageGeometryInput = { left: number; top: number; width: number; height: number; imageWidth: number; imageHeight: number; radius: number; density: number; transform: { a: number; b: number; c: number; d: number } }

/** Clip a transformed contain-image against its rounded-bottom body. UVs are
 * interpolated at intersections, so the original image remains one texture.
 * Convex triangles batch with sprites without per-card stencil passes. */
export function retainedImageGeometry(input: ImageGeometryInput) {
  const { left, top, width, height, imageWidth, imageHeight, transform: m } = input
  const fit = Math.min(width / imageWidth, height / imageHeight)
  const cx = left + width / 2, cy = top + height / 2
  let polygon: Vertex[] = [[0, 0], [1, 0], [1, 1], [0, 1]].map(([u, v]) => {
    const x = (u - .5) * imageWidth * fit, y = (v - .5) * imageHeight * fit
    return { x: cx + m.a * x + m.c * y, y: cy + m.b * x + m.d * y, u, v }
  })
  const radius = Math.max(0, Math.min(input.radius, width / 2, height / 2))
  const physicalRadius = radius * input.density
  const segments = Math.max(1, Math.ceil(Math.PI / 2 / (2 * Math.acos(Math.max(-1, 1 - .2 / Math.max(.2, physicalRadius))))))
  const edge: { x: number; y: number }[] = [{ x: left, y: top }, { x: left + width, y: top }]
  for (const [x, angle] of [[left + width - radius, 0], [left + radius, Math.PI / 2]]) {
    for (let i = 0; i <= segments; i++) {
      const theta = angle + Math.PI / 2 * i / segments
      edge.push({ x: x + radius * Math.cos(theta), y: top + height - radius + radius * Math.sin(theta) })
    }
  }
  for (let i = 0; i < edge.length && polygon.length; i++) {
    const a = edge[i], b = edge[(i + 1) % edge.length]
    const distance = (p: Vertex) => (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x)
    const output: Vertex[] = []
    for (let j = 0; j < polygon.length; j++) {
      const current = polygon[j], previous = polygon[(j + polygon.length - 1) % polygon.length]
      const d0 = distance(previous), d1 = distance(current)
      if ((d0 >= 0) !== (d1 >= 0)) {
        const t = d0 / (d0 - d1)
        output.push({ x: previous.x + t * (current.x - previous.x), y: previous.y + t * (current.y - previous.y), u: previous.u + t * (current.u - previous.u), v: previous.v + t * (current.v - previous.v) })
      }
      if (d1 >= 0) output.push(current)
    }
    polygon = output
  }
  const indices = []
  for (let i = 1; i + 1 < polygon.length; i++) indices.push(0, i, i + 1)
  return { positions: new Float32Array(polygon.flatMap(p => [p.x, p.y])), uvs: new Float32Array(polygon.flatMap(p => [p.u, p.v])), indices: new Uint32Array(indices) }
}

export type RetainedMode = 'dom' | 'raster' | 'retained' | 'vello'

/** Explicit rollout flags; the existing compositor remains the release default
 * until the retained paths pass their visual and performance gates. A GPU
 * build can flip the default via VITE_DEFAULT_CANVAS_RENDERER=retained; an
 * explicit ?canvas-renderer= parameter always wins. */
export function retainedMode(search = window.location.search): RetainedMode {
  const mode = new URLSearchParams(search).get('canvas-renderer')
  if (mode === 'raster' || mode === 'retained' || mode === 'vello' || mode === 'dom') return mode
  if (import.meta.env.VITE_DEFAULT_CANVAS_RENDERER === 'vello') return 'vello'
  return import.meta.env.VITE_DEFAULT_CANVAS_RENDERER === 'retained' ? 'retained' : 'dom'
}

import { FrameScheduler, SampleRing } from '../canvas-engine/frameScheduler'

export type PointerSample = Pick<PointerEvent, 'pointerId' | 'clientX' | 'clientY' | 'pressure' | 'timeStamp' | 'shiftKey' | 'altKey' | 'ctrlKey' | 'metaKey'>
export type InputMetrics = { received: number; coalesced: number; merged: number; dropped: number; applied: number; maxPending: number; cancelled: number; completed: number }
export function createInputMetrics(): InputMetrics {
  return { received: 0, coalesced: 0, merged: 0, dropped: 0, applied: 0, maxPending: 0, cancelled: 0, completed: 0 }
}

/** Absolute-position tools consume the newest sample once per frame. Stroke
 * consumers can preserve every ordered/coalesced sample retained by the ring.
 * Stroke overload cancels rather than committing a silently truncated trace;
 * latest-position tools can still merge/drop older samples safely. */
export function scheduledPointerGesture(options: {
  initial: { clientX: number; clientY: number; pointerId?: number }
  captureTarget: EventTarget
  scheduler: FrameScheduler
  metrics: InputMetrics
  move: (sample: PointerSample) => void
  finish: (sample: PointerSample) => void
  cancel: () => void
  changed: () => void
  preserveSamples?: boolean
}) {
  const { scheduler, metrics } = options
  const ring = new SampleRing<PointerSample>(64)
  let closed = false
  let pointerId = options.initial.pointerId
  let latest = options.initial
  let receivedPosition = options.initial
  const matches = (event: PointerEvent) => pointerId === undefined || event.pointerId === pointerId
  const copy = (event: PointerEvent): PointerSample => ({ pointerId: event.pointerId, clientX: event.clientX, clientY: event.clientY, pressure: event.pressure, timeStamp: event.timeStamp, shiftKey: event.shiftKey, altKey: event.altKey, ctrlKey: event.ctrlKey, metaKey: event.metaKey })
  const apply = () => {
    const samples = ring.drain()
    if (!samples.length || closed) return
    if (options.preserveSamples) {
      for (const sample of samples) {
        if (closed) break
        latest = sample; metrics.applied++
        options.move(sample)
      }
    } else {
      metrics.merged += samples.length - 1
      latest = samples[samples.length - 1]
      metrics.applied++
      options.move(latest as PointerSample)
    }
    options.changed()
  }
  const queue = (event: PointerEvent) => {
    if (closed) return
    const droppedBefore = ring.dropped
    ring.push(copy(event))
    metrics.received++
    metrics.dropped += ring.dropped - droppedBefore
    metrics.maxPending = Math.max(metrics.maxPending, ring.size)
    if (options.preserveSamples && ring.dropped > droppedBefore) cancel()
  }
  const move = (event: PointerEvent) => {
    if (!matches(event) || closed) return
    pointerId ??= event.pointerId
    receivedPosition = event
    const samples = event.getCoalescedEvents?.() || []
    metrics.coalesced += samples.length
    if (samples.length) for (const sample of samples) queue(sample)
    // Always retain the dispatch position, including final modifiers.
    queue(event)
    if (!closed) scheduler.schedule('pointer', apply)
  }
  const finish = (event: PointerEvent) => {
    if (!matches(event) || closed) return
    if (event.clientX !== receivedPosition.clientX || event.clientY !== receivedPosition.clientY) {
      queue(event)
      if (closed) return
      scheduler.schedule('pointer', apply)
    }
    // Releasing a modifier immediately before pointer-up must not undo the
    // last snapped preview when the pointer itself has not moved.
    scheduler.flush('pointer')
    metrics.completed++
    dispose()
    options.finish(copy(event))
  }
  const cancel = () => {
    if (closed) return
    metrics.cancelled++
    dispose()
    options.cancel()
  }
  const pointerCancel = (event: Event) => { if (matches(event as PointerEvent)) cancel() }
  const visibility = () => { if (document.hidden) cancel() }
  function dispose() {
    if (closed) return
    closed = true
    scheduler.cancel('pointer')
    ring.drain()
    window.removeEventListener('pointermove', move)
    window.removeEventListener('pointerup', finish)
    window.removeEventListener('pointercancel', pointerCancel)
    window.removeEventListener('blur', cancel)
    document.removeEventListener('visibilitychange', visibility)
    options.captureTarget.removeEventListener('lostpointercapture', pointerCancel)
    scheduler.settle(options.changed)
  }
  scheduler.beginInteraction()
  window.addEventListener('pointermove', move)
  window.addEventListener('pointerup', finish)
  window.addEventListener('pointercancel', pointerCancel)
  window.addEventListener('blur', cancel)
  document.addEventListener('visibilitychange', visibility)
  options.captureTarget.addEventListener('lostpointercapture', pointerCancel)
  return dispose
}

/**
 * Art Equation Canvas Engine - Screen-Space Snapping & Guides Manager
 *
 * Implements tldraw-grade magnetic snapping:
 * - Edge alignment (left, center, right, top, middle, bottom)
 * - Grid snapping with configurable cell dimensions
 * - Equal-gap snapping between consecutive cards
 * - Dynamic guide line generation with measurement readouts
 * - Constant screen-space snap threshold across any canvas zoom level
 */

export interface Rect {
  x: number
  y: number
  width: number
  height: number
}

export interface SnapGuide {
  axis: 'x' | 'y'
  position: number
  start: number
  end: number
  kind: 'edge' | 'center' | 'gap' | 'grid'
}

export interface SnapResult {
  x: number
  y: number
  guides: SnapGuide[]
}

export class ScreenSpaceSnapManager {
  private thresholdScreenPx: number
  private gridSize: number

  constructor(thresholdScreenPx: number = 6, gridSize: number = 24) {
    this.thresholdScreenPx = thresholdScreenPx
    this.gridSize = gridSize
  }

  /**
   * Snaps a moving/resizing box against existing boxes and grid.
   *
   * @param target Current proposed position/bounds of target
   * @param others Other stationary boxes on canvas
   * @param zoom Current canvas zoom factor (e.g. 1.0, 0.5, 2.0)
   * @param snapToGrid Whether grid snapping is enabled
   */
  public snap(
    target: Rect,
    others: Rect[],
    zoom: number = 1.0,
    snapToGrid: boolean = true
  ): SnapResult {
    const thresholdWorld = this.thresholdScreenPx / Math.max(0.01, zoom)
    let bestX = target.x
    let bestY = target.y
    let minDeltaX = thresholdWorld
    let minDeltaY = thresholdWorld
    const guides: SnapGuide[] = []

    const targetRight = target.x + target.width
    const targetBottom = target.y + target.height
    // 1. Grid Snapping (Baseline)
    if (snapToGrid) {
      const gridSnapX = Math.round(target.x / this.gridSize) * this.gridSize
      const dx = Math.abs(gridSnapX - target.x)
      if (dx < minDeltaX) {
        minDeltaX = dx
        bestX = gridSnapX
      }

      const gridSnapY = Math.round(target.y / this.gridSize) * this.gridSize
      const dy = Math.abs(gridSnapY - target.y)
      if (dy < minDeltaY) {
        minDeltaY = dy
        bestY = gridSnapY
      }
    }

    // 2. Object-to-Object Edge and Center Snapping
    for (const other of others) {
      const otherRight = other.x + other.width
      const otherBottom = other.y + other.height
      const otherCenterX = other.x + other.width / 2
      const otherCenterY = other.y + other.height / 2

      // Horizontal alignments (Snap X)
      const xChecks = [
        { val: other.x, shift: 0, kind: 'edge' as const }, // Left-to-left
        { val: otherRight, shift: -target.width, kind: 'edge' as const }, // Right-to-right
        { val: otherRight, shift: 0, kind: 'edge' as const }, // Left-to-right
        { val: other.x, shift: -target.width, kind: 'edge' as const }, // Right-to-left
        { val: otherCenterX, shift: -target.width / 2, kind: 'center' as const } // Center-to-center
      ]

      for (const check of xChecks) {
        const candidateX = check.val + check.shift
        const dx = Math.abs(candidateX - target.x)
        if (dx < minDeltaX) {
          minDeltaX = dx
          bestX = candidateX
          guides.push({
            axis: 'x',
            position: check.val,
            start: Math.min(target.y, other.y),
            end: Math.max(targetBottom, otherBottom),
            kind: check.kind
          })
        }
      }

      // Vertical alignments (Snap Y)
      const yChecks = [
        { val: other.y, shift: 0, kind: 'edge' as const }, // Top-to-top
        { val: otherBottom, shift: -target.height, kind: 'edge' as const }, // Bottom-to-bottom
        { val: otherBottom, shift: 0, kind: 'edge' as const }, // Top-to-bottom
        { val: other.y, shift: -target.height, kind: 'edge' as const }, // Bottom-to-top
        { val: otherCenterY, shift: -target.height / 2, kind: 'center' as const } // Center-to-center
      ]

      for (const check of yChecks) {
        const candidateY = check.val + check.shift
        const dy = Math.abs(candidateY - target.y)
        if (dy < minDeltaY) {
          minDeltaY = dy
          bestY = candidateY
          guides.push({
            axis: 'y',
            position: check.val,
            start: Math.min(target.x, other.x),
            end: Math.max(targetRight, otherRight),
            kind: check.kind
          })
        }
      }
    }

    return {
      x: bestX,
      y: bestY,
      guides
    }
  }

  /**
   * Distributes boxes evenly along an axis with equal spacing.
   */
  public distribute(
    boxes: Rect[],
    axis: 'x' | 'y',
    specifiedGap?: number
  ): Rect[] {
    if (boxes.length <= 1) return [...boxes]

    const sorted = [...boxes].sort((a, b) => (axis === 'x' ? a.x - b.x : a.y - b.y))
    const first = sorted[0]
    const last = sorted[sorted.length - 1]

    if (specifiedGap !== undefined) {
      let currentPos = axis === 'x' ? first.x : first.y
      return sorted.map((box) => {
        const updated = {
          ...box,
          x: axis === 'x' ? currentPos : box.x,
          y: axis === 'y' ? currentPos : box.y
        }
        currentPos += (axis === 'x' ? box.width : box.height) + specifiedGap
        return updated
      })
    }

    // Auto-calculate equal gap across total span
    const totalSpan = axis === 'x' ? last.x + last.width - first.x : last.y + last.height - first.y
    const totalBoxSizes = sorted.reduce((sum, b) => sum + (axis === 'x' ? b.width : b.height), 0)
    const gap = Math.max(0, (totalSpan - totalBoxSizes) / (sorted.length - 1))

    let currentPos = axis === 'x' ? first.x : first.y
    return sorted.map((box) => {
      const updated = {
        ...box,
        x: axis === 'x' ? currentPos : box.x,
        y: axis === 'y' ? currentPos : box.y
      }
      currentPos += (axis === 'x' ? box.width : box.height) + gap
      return updated
    })
  }

  /**
   * Aligns boxes along a specified mode (start, center, end).
   */
  public align(
    boxes: Rect[],
    axis: 'x' | 'y',
    mode: 'start' | 'center' | 'end'
  ): Rect[] {
    if (boxes.length <= 1) return [...boxes]

    let targetCoord = 0
    if (axis === 'x') {
      if (mode === 'start') {
        targetCoord = Math.min(...boxes.map((b) => b.x))
        return boxes.map((b) => ({ ...b, x: targetCoord }))
      } else if (mode === 'end') {
        targetCoord = Math.max(...boxes.map((b) => b.x + b.width))
        return boxes.map((b) => ({ ...b, x: targetCoord - b.width }))
      } else {
        const centers = boxes.map((b) => b.x + b.width / 2)
        const avgCenter = centers.reduce((a, b) => a + b, 0) / centers.length
        return boxes.map((b) => ({ ...b, x: avgCenter - b.width / 2 }))
      }
    } else {
      if (mode === 'start') {
        targetCoord = Math.min(...boxes.map((b) => b.y))
        return boxes.map((b) => ({ ...b, y: targetCoord }))
      } else if (mode === 'end') {
        targetCoord = Math.max(...boxes.map((b) => b.y + b.height))
        return boxes.map((b) => ({ ...b, y: targetCoord - b.height }))
      } else {
        const centers = boxes.map((b) => b.y + b.height / 2)
        const avgCenter = centers.reduce((a, b) => a + b, 0) / centers.length
        return boxes.map((b) => ({ ...b, y: avgCenter - b.height / 2 }))
      }
    }
  }
}

import type { BoardPoint } from '../model/project'
import type { FrameClock } from '../canvas-engine/frameScheduler'

export type StrokeBounds = { minX: number; minY: number; maxX: number; maxY: number }

/** Disposable gesture paint, never document state. Commands are encoded once
 * per accepted point; a coalesced input batch publishes only once per frame.
 * The canonical ordered samples stay with the gesture for fitting/erasure. */
export class StrokePreview {
  private commands: string[] = []
  private rawPoints: BoardPoint[] = []
  private pending: number | null = null
  private generation = 0
  private dirtyBounds: StrokeBounds | null = null
  readonly metrics = { samples: 0, frames: 0, cleared: 0 }
  private clock: FrameClock
  private paint: (path: string) => void

  constructor(clock: FrameClock, paint: (path: string) => void) {
    this.clock = clock
    this.paint = paint
  }

  get bounds(): StrokeBounds | null {
    return this.dirtyBounds ? { ...this.dirtyBounds } : null
  }

  get points(): readonly BoardPoint[] {
    return this.rawPoints
  }

  begin(point: BoardPoint) {
    this.clear()
    this.rawPoints.push({ x: point.x, y: point.y })
    this.commands.push(`M ${point.x} ${point.y}`)
    this.dirtyBounds = { minX: point.x, minY: point.y, maxX: point.x, maxY: point.y }
    this.metrics.samples++
    this.schedule()
  }

  append(point: BoardPoint) {
    if (!this.commands.length) return
    this.rawPoints.push({ x: point.x, y: point.y })
    this.commands.push(`L ${point.x} ${point.y}`)
    if (this.dirtyBounds) {
