  toSmoothPath(): string {
    const pts = this.rawPoints
    if (pts.length <= 2) return this.commands.join(' ')
    const parts = [`M ${pts[0].x} ${pts[0].y}`]
    for (let i = 1; i < pts.length - 1; i++) {
