    const movement = new MutationObserver(wake)
    if (world) movement.observe(world, { attributes: true, attributeFilter: ['style'] })
    poster.addEventListener('load', wake); poster.addEventListener('error', posterFailed); root.querySelector('button')!.addEventListener('click', retry)
    window.addEventListener('resize', wake); stage.addEventListener('scroll', wake); stage.addEventListener('canvas-camera-presented', wake); stage.addEventListener('canvas-gesture-presented', wake); wake()
    return () => { stopped = true; stopDpr(); cancelAppFrame(raf); resize.disconnect(); movement.disconnect(); poster.removeEventListener('load', wake); poster.removeEventListener('error', posterFailed); root.querySelector('button')!.removeEventListener('click', retry); window.removeEventListener('resize', wake); stage.removeEventListener('scroll', wake); stage.removeEventListener('canvas-camera-presented', wake); stage.removeEventListener('canvas-gesture-presented', wake); release(); wakeRef.current = () => {} }
  }, [props.pyramid, props.posterUrl, props.tilesUrl])
  return <div className="tiled-image-frame" style={props.nativeSize ? { width: props.pyramid.width, height: props.pyramid.height, flexShrink: 0 } : undefined}><div className="tiled-image-preview" ref={rootRef} data-tile-state="poster" style={props.style}>
    <img crossOrigin="anonymous" className="tile-poster" src={props.posterUrl} alt={props.alt} draggable={false} />
    <span className="tile-message" hidden />
    <button type="button" className="tile-retry" title="Retry missing tiles or restart graphics" onClick={event => event.stopPropagation()}>Retry tiles</button>
  </div></div>
}

import { useCallback, useLayoutEffect, useRef } from 'react'
import type { BoardModel } from '../model/project'

/** Gesture previews are presented outside React. Only final commands reach persistence. */
export function useGestureBoard(persisted: BoardModel, commit: (board: BoardModel, historyBase?: BoardModel | null, mergeKey?: string) => void, presenter: { present(base: BoardModel, next: BoardModel): void; clear(committed?: BoardModel): void; repaint(): void }) {
  const active = useRef(false)
  const currentBoard = useRef(persisted)
  useLayoutEffect(() => {
    const previous = currentBoard.current
    currentBoard.current = persisted
    if (previous !== persisted) { active.current = false; presenter.clear(persisted) }
  }, [persisted, presenter])
  useLayoutEffect(() => { presenter.repaint() })
  useLayoutEffect(() => () => presenter.clear(), [presenter])
  const beginPreview = useCallback(() => { active.current = true }, [])
  const endPreview = useCallback(() => { active.current = false; presenter.clear() }, [presenter])
  const change = useCallback((board: BoardModel, historyBase?: BoardModel | null, mergeKey?: string) => {
    // An undo or external command can replace the board during a drag. Old
    // gesture callbacks must never overwrite that newer committed snapshot.
    if (currentBoard.current !== persisted) return
    if (active.current && historyBase === null) {
      presenter.present(persisted, board)
    } else {
      presenter.clear()
      if (board !== persisted || historyBase !== null) commit(board, historyBase, mergeKey)
    }
  }, [persisted, commit, presenter])
  return { board: persisted, change, beginPreview, endPreview }
}

import { useEffect, useRef, useState, type Dispatch, type SetStateAction } from 'react'
import type { ProjectAsset, ProjectModel } from '../model/project'
import { cancelImagePyramid, imagePyramidStatus, startImagePyramid, type PyramidJob } from '../storage/workspace'
import { validPyramid } from '../canvas-engine/imagePyramid'

export function useImagePreparation(projectId: string, setProject: Dispatch<SetStateAction<ProjectModel>>) {
  const [task, setTask] = useState<{ job: PyramidJob; source: string; name: string } | null>(null)
  const [error, setError] = useState(''), busy = useRef(false)
  const prepare = async (asset: ProjectAsset) => {
    if (busy.current) { setError('Finish or cancel the current image preparation first.'); return }
    busy.current = true; setError('')
    const source = asset.status === 'moved' ? asset.managedRelativePath || asset.relativePath : asset.relativePath
    try { setTask({ job: await startImagePyramid(projectId, asset.id, source), source, name: asset.displayName }) }
    catch (error) { setError(String(error)); busy.current = false }
  }
  const jobId = task?.job.id
  useEffect(() => {
    if (!jobId || !task) return
    const source = task.source
    let stopped = false, timer: ReturnType<typeof setTimeout>
    const poll = async () => {
      try {
        const job = await imagePyramidStatus(jobId)
        if (stopped) return
        setTask(current => current?.job.id === jobId ? { ...current, job } : current)
        if (job.phase === 'complete' && validPyramid(job.pyramid)) {
          setProject(current => current.id !== job.projectId ? current : { ...current, assets: current.assets.map(asset => asset.id === job.assetId && (asset.status === 'moved' ? asset.managedRelativePath || asset.relativePath : asset.relativePath) === source ? { ...asset, imagePyramid: job.pyramid, thumbnailRelativePath: job.pyramid!.posterRelativePath, status: 'available' } : asset) })
        }
        if (['complete', 'failed', 'cancelled'].includes(job.phase)) { busy.current = false; return }
        timer = setTimeout(poll, 500)
      } catch (error) { if (!stopped) { setError(String(error)); timer = setTimeout(poll, 1500) } }
    }
    void poll()
    return () => { stopped = true; clearTimeout(timer) }
    // Poll lifetime is the native job, not progress updates or board selection.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [jobId, setProject])
  const done = task && ['complete', 'failed', 'cancelled'].includes(task.job.phase)
  const notice = (task || error) && <aside className="pyramid-preparation" aria-label="Tiled image preparation">
    <span role="status">{error || (task?.job.phase === 'complete' ? `${task.name}: tiled image ready` : `${task?.name}: ${task?.job.phase}`)}{task?.job.error && ` · ${task.job.error}`}</span>
    {task && !done && <button type="button" onClick={() => void cancelImagePyramid(task.job.id).catch(error => setError(String(error)))}>Cancel</button>}
    {(!task || done) && <button type="button" onClick={() => { setTask(null); setError('') }}>Dismiss</button>}
  </aside>
  return { prepare, notice }
}

import { appUpdateClock, cancelAppFrame } from '../canvas-engine/appFrameClock'
import { captureMeasuredCardPaint, type MeasuredCardPaintSnapshot } from './measuredCardPaint'
import { withCanonicalStageCardPaint } from './completeMeasuredCardPaint'
import type { CanvasSceneSnapshot, CanvasViewport } from '../canvas-engine/contracts'

/** Independent disposable layout invalidation. Measurements never change
 * documents, history, DOM paint ownership or the accepted renderer frame. */
export function observeMeasuredCardPaint(stage: HTMLElement, current: () => { scene: CanvasSceneSnapshot; viewport: CanvasViewport }, publish: (snapshot: MeasuredCardPaintSnapshot) => void) {
  let disposed=false, pending:number|undefined, timer:number|undefined, revision=0, fingerprint=''
  const observed=new Set<Element>()
  const schedule=()=> {
    if (disposed || pending!==undefined || timer!==undefined || document.hidden) return
    // This observational derivative is not on the drawing/presentation path.
    // Coalesce hot gesture/camera mutations instead of measuring every frame.
    timer=window.setTimeout(()=>{timer=undefined;if(!disposed)pending=appUpdateClock.request(measure)},100)
  }
  const resize=new ResizeObserver(schedule)
  function measure() {
    pending=undefined
    if (disposed || document.hidden) return
    const input=current()
    const measured=withCanonicalStageCardPaint(stage,()=>captureMeasuredCardPaint(stage,input.scene,input.viewport,revision+1))
    const next=JSON.stringify({...measured,layoutRevision:0})
    // Bounds/layout/style/fonts/resources can change independently of the
    // board revision. Equal measurements do not trigger a publication loop.
    if (next!==fingerprint) { fingerprint=next;revision++;publish({...measured,layoutRevision:revision}) }
    const mounted=new Set<Element>(stage.querySelectorAll<HTMLElement>('.board-world>.board-object-layer>article.board-node'))
    for (const article of [...mounted]) for (const element of article.querySelectorAll<HTMLElement>('.node-drag-handle,.column-header-copy>small,.node-copy,.board-rich-text,.node-document,.transformed-image,.board-link-card')) {
      if (mounted.size<4096) mounted.add(element)
    }
    for (const element of observed) if (!mounted.has(element)) { resize.unobserve(element);observed.delete(element) }
    for (const element of mounted) if (!observed.has(element)) { resize.observe(element);observed.add(element) }
  }
  const mutation=new MutationObserver(schedule)
  mutation.observe(stage,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['class','style','src','hidden','data-node-id']})
  const theme=new MutationObserver(schedule)
  for (let parent=stage.parentElement,count=0;parent && count<16;parent=parent.parentElement,count++) theme.observe(parent,{attributes:true,attributeFilter:['class','style','data-theme']})
  stage.addEventListener('load',schedule,true)
  stage.addEventListener('scroll',schedule,true)
  stage.addEventListener('canvas-camera-presented',schedule)
  for (const event of ['pointerover','pointerout','focusin','focusout','transitionend','animationend']) stage.addEventListener(event,schedule,true)
  document.addEventListener('visibilitychange',schedule)
  document.fonts?.addEventListener('loadingdone',schedule)
  document.fonts?.addEventListener('loadingerror',schedule)
  void document.fonts?.ready.then(schedule)
  schedule()
  return { invalidate:schedule, dispose(){
    disposed=true
    if (pending!==undefined) cancelAppFrame(pending)
    if (timer!==undefined) window.clearTimeout(timer)
    mutation.disconnect();theme.disconnect();resize.disconnect();observed.clear()
    stage.removeEventListener('load',schedule,true)
    stage.removeEventListener('scroll',schedule,true)
    stage.removeEventListener('canvas-camera-presented',schedule)
    for (const event of ['pointerover','pointerout','focusin','focusout','transitionend','animationend']) stage.removeEventListener(event,schedule,true)
    document.removeEventListener('visibilitychange',schedule)
    document.fonts?.removeEventListener('loadingdone',schedule)
    document.fonts?.removeEventListener('loadingerror',schedule)
  } }
}

import type { BoardNode, VectorGradient, VectorTexture } from '../model/project'

export const paintAlpha = (value: number | undefined) => Number.isFinite(value) ? Math.max(0, Math.min(1, value!)) : 1
const escape = (value: string | number) => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')
export const paintId = (id: string, channel: string) => `paint-${channel}-${[...id].map(c=>c.codePointAt(0)!.toString(16)).join('-')}`
export function validGradient(g: VectorGradient): boolean {
  return g.version===1 && ['linear','radial'].includes(g.kind) && g.transform.length===6 && g.transform.every(Number.isFinite) && Math.abs(g.transform[0]*g.transform[3]-g.transform[1]*g.transform[2])>1e-12 && [g.start.x,g.start.y,g.end.x,g.end.y].every(Number.isFinite) && ['pad','reflect','repeat'].includes(g.spread) && (g.kind!=='radial' || Number.isFinite(g.radius) && g.radius!>0 && (g.focalRadius===undefined || Number.isFinite(g.focalRadius) && g.focalRadius>=0 && g.focalRadius<=g.radius!)) && g.stops.length>=2 && g.stops.length<=256 && g.stops.every((s,i)=>Number.isFinite(s.offset)&&s.offset>=0&&s.offset<=1&&(!i||s.offset>=g.stops[i-1].offset)&&Number.isFinite(s.opacity)&&s.opacity>=0&&s.opacity<=1&&/^(#[0-9a-f]{3,8}|rgba?\([\d\s.,%]+\)|[a-z]+)$/i.test(s.color))
}
export function validTexture(t: VectorTexture): boolean { return t.version===1 && /^data:image\/(png|jpeg);base64,[a-z\d+/=\s]+$/i.test(t.href) && t.href.length<=40_000_000 && t.width>0 && t.height>0 && [t.width,t.height,...t.transform].every(Number.isFinite) && t.transform.length===6 }
export function gradientMarkup(g: VectorGradient, id: string): string {
  if(!validGradient(g)) return ''
  const tag=g.kind==='linear'?'linearGradient':'radialGradient'
  const coordinates=g.kind==='linear'?`x1="${g.start.x}" y1="${g.start.y}" x2="${g.end.x}" y2="${g.end.y}"`:`cx="${g.start.x}" cy="${g.start.y}" fx="${g.end.x}" fy="${g.end.y}" r="${g.radius}" fr="${g.focalRadius??0}"`
  return `<${tag} id="${escape(id)}" gradientUnits="userSpaceOnUse" gradientTransform="matrix(${g.transform.join(' ')})" spreadMethod="${g.spread}" ${coordinates}>${g.stops.map(s=>`<stop offset="${s.offset}" stop-color="${escape(s.color)}" stop-opacity="${paintAlpha(s.opacity)}"/>`).join('')}</${tag}>`
}
export function vectorPaintDefinitions(node: BoardNode, prefix: string): string {
  return (node.vectorFillGradient?gradientMarkup(node.vectorFillGradient,paintId(prefix,'fill')):'')+(node.vectorStrokeGradient?gradientMarkup(node.vectorStrokeGradient,paintId(prefix,'stroke')):'')
}
export function transformVectorPaint(node: BoardNode, m: VectorGradient['transform']): Partial<BoardNode> {
  const matrix=(n: VectorGradient['transform'])=>[m[0]*n[0]+m[2]*n[1],m[1]*n[0]+m[3]*n[1],m[0]*n[2]+m[2]*n[3],m[1]*n[2]+m[3]*n[3],m[0]*n[4]+m[2]*n[5]+m[4],m[1]*n[4]+m[3]*n[5]+m[5]] as VectorGradient['transform']
  const point=(p:{x:number;y:number},translate=true)=>({x:m[0]*p.x+m[2]*p.y+(translate?m[4]:0),y:m[1]*p.x+m[3]*p.y+(translate?m[5]:0)})
