  background: #24201a;
  pointer-events: auto;
}
.vello-render-notice[hidden] { display: none !important; }
.vello-render-notice button { font: inherit; padding: 6px 10px; cursor: pointer; }

/* Base artwork belongs to the engine; cached hit paths and transient segment
   highlights remain synchronous, including while a path is selected. */
.board-node[data-vello-paint] .node-vector-shape > g { opacity: 1 !important; }
.board-node[data-vello-paint] .node-vector-shape .vector-segment-selected { opacity: 1 !important; }

import {subsetPaintScene} from '../canvas-engine/visiblePaintScene'
import { requestAppFrame, cancelAppFrame } from '../canvas-engine/appFrameClock'
