}

/**
 * Binary packed card buffer for high-throughput zero-copy serialization of 10,000+ cards.
 * Layout per card (32 bytes / 8 x 32-bit words):
 * [0..3]: bounds [minX, minY, maxX, maxY] (f32)
 * [4]: opacity (f32)
 * [5]: lod (u8), flags (u8), resident (u8), _pad (u8)
 * [6]: scale (f32)
 * [7]: assetId numeric hash (u32)
 */
export class PackedCardBuffer {
  static readonly BYTES_PER_CARD = 32
  readonly buffer: ArrayBuffer
  readonly f32: Float32Array
  readonly u32: Uint32Array
  readonly u8: Uint8Array
  private count = 0

  constructor(capacity = 10000) {
    this.buffer = new ArrayBuffer(capacity * PackedCardBuffer.BYTES_PER_CARD)
    this.f32 = new Float32Array(this.buffer)
    this.u32 = new Uint32Array(this.buffer)
    this.u8 = new Uint8Array(this.buffer)
  }

  get cardCount(): number {
    return this.count
  }

  writeCard(
    minX: number,
    minY: number,
    maxX: number,
    maxY: number,
    opacity = 1.0,
    lod = 0,
    assetIdHash = 0
  ): void {
    const offset = this.count * 8
    this.f32[offset + 0] = minX
    this.f32[offset + 1] = minY
    this.f32[offset + 2] = maxX
    this.f32[offset + 3] = maxY
    this.f32[offset + 4] = opacity
    this.u8[(offset + 5) * 4 + 0] = lod & 0xff
    this.u8[(offset + 5) * 4 + 1] = 1 // resident flag
    this.f32[offset + 6] = 1.0 // scale
    this.u32[offset + 7] = assetIdHash
    this.count++
  }

  reset(): void {
    this.count = 0
  }

  getByteView(): Uint8Array {
    return new Uint8Array(this.buffer, 0, this.count * PackedCardBuffer.BYTES_PER_CARD)
  }
}

export type AtlasBatch = Readonly<{
  atlasId: string | number
  count: number
  images: readonly RasterImageDescriptor[]
}>

/**
 * Groups raster image primitives by texture atlas to collapse draw calls.
 */
export function batchRasterImagesByAtlas(
  images: readonly RasterImageDescriptor[]
): AtlasBatch[] {
  const map = new Map<string | number, RasterImageDescriptor[]>()
  for (let i = 0; i < images.length; i++) {
    const img = images[i]
    const key = img.assetId
    let group = map.get(key)
    if (!group) {
      group = []
      map.set(key, group)
    }
    group.push(img)
  }
  const batches: AtlasBatch[] = []
  for (const [atlasId, list] of map.entries()) {
    batches.push({ atlasId, count: list.length, images: list })
  }
  return batches
}

import type { CanvasSceneChangeSet, CanvasSceneConnection, CanvasSceneObject, CanvasSceneSnapshot } from './contracts'

function changed<T extends { id: string; revision: number }>(previous: readonly T[], next: readonly T[]) {
  const previousById = new Map(previous.map((entry) => [entry.id, entry]))
  const nextIds = new Set(next.map((entry) => entry.id))
  return {
    upsert: next.filter((entry) => previousById.get(entry.id)?.revision !== entry.revision),
    remove: previous.filter((entry) => !nextIds.has(entry.id)).map((entry) => entry.id),
  }
}

/** Creates the renderer-facing delta while keeping application history out of the engine. */
export function diffCanvasScenes(previous: CanvasSceneSnapshot, next: CanvasSceneSnapshot): CanvasSceneChangeSet {
  if (previous.id !== next.id) throw new Error('Canvas scenes must have the same id to produce a change set')
  const objects = changed<CanvasSceneObject>(previous.objects, next.objects)
  const connections = changed<CanvasSceneConnection>(previous.connections, next.connections)
  return {
    sceneId: next.id,
    fromRevision: previous.revision,
    toRevision: next.revision,
    upsertObjects: objects.upsert,
    removeObjectIds: objects.remove,
    upsertConnections: connections.upsert,
    removeConnectionIds: connections.remove,
    ...(previous.environment === next.environment ? {} : { environment: next.environment }),
  }
}

