    || typeof r.key !== 'string' || !r.key || new TextEncoder().encode(r.key).length > 1024
    || !Number.isSafeInteger(r.revision) || r.revision <= 0 || !Number.isInteger(r.epoch) || r.epoch <= 0 || r.epoch > 0xffffffff
