import type {CanvasSceneObject, CanvasSceneSnapshot} from './contracts'

/** Browser hit/editor overlays are not paint authority for these providers. */
export function ownsModelPaint(object:CanvasSceneObject) {
  return Boolean(object.modelArtwork || object.structuredCard)
}

/** Retain a pending frame only while every visible member has an engine
 * provider. Mixed browser overlays and editors still present in the accepted
 * frame require their
 * explicit handoff. This is last-frame presentation, never acceptance of a
 * newer revision, and must not advance input/quality completion telemetry. */
export function canRetainModelFrame(previous:CanvasSceneSnapshot, current:CanvasSceneSnapshot, accepted:ReadonlySet<string>, editing:boolean) {
  if(editing || previous.id!==current.id || !accepted.size)return false
  const native=(object:CanvasSceneObject)=>ownsModelPaint(object) || object.kind==='vector' && !object.hasDiagramCaption && !object.hasShapeCaption && object.preparedVectorGeometry?.status==='ready'
  const visible=current.objects.filter(object=>!object.hidden)
  if(visible.some(object=>!native(object)))return false
  const ids=new Set(visible.map(object=>object.id))
  return [...accepted].every(id=>ids.has(id))
}

export type FrameClock = {
  request: (callback: (timestamp: number) => void) => number
  cancel: (id: number) => void
}

export type FramePhase = 'idle' | 'interaction' | 'settle'

/** Host-neutral keyed work queue. Repeated invalidations share one animation frame. */
export class FrameScheduler {
  private readonly clock: FrameClock
  private readonly tasks = new Map<string, () => void>()
  private frame: number | null = null
  private running = false
  private interacting = false
  private disposed = false
  phase: FramePhase = 'idle'
  readonly metrics = { frames: 0, mergedTasks: 0, executedTasks: 0, settleFrames: 0 }

  constructor(clock: FrameClock) { this.clock = clock }

  get processingFrame() { return this.running }

  clear() {
    if (this.frame !== null) this.clock.cancel(this.frame)
    this.frame = null
    this.tasks.clear()
    this.interacting = false
    this.phase = 'idle'
  }

  schedule(key: string, task: () => void) {
    if (this.disposed) return
    if (this.tasks.has(key)) this.metrics.mergedTasks++
    this.tasks.set(key, task)
    this.request()
  }

  beginInteraction() { this.tasks.delete('settle'); this.interacting = true; this.phase = 'interaction' }

  settle(task?: () => void) {
    if (this.disposed) return
    this.interacting = false
    this.phase = 'settle'
    if (task) this.tasks.set('settle', task)
    this.request()
  }

  flush(key: string) {
    const task = this.tasks.get(key)
    if (!task) return
    this.tasks.delete(key)
    this.metrics.executedTasks++
    task()
  }

  cancel(key: string) {
    this.tasks.delete(key)
    if (!this.tasks.size && this.phase !== 'settle' && this.frame !== null) {
      this.clock.cancel(this.frame)
      this.frame = null
    }
  }

  dispose() {
    this.disposed = true
    this.clear()
  }

  private request() {
    if (this.frame !== null || this.running) return
    this.frame = this.clock.request(() => {
      this.frame = null
      this.running = true
      this.metrics.frames++
      const settling = this.phase === 'settle'
      if (settling) this.metrics.settleFrames++
      // Snapshot keys, then delete before executing: tasks can safely cancel or
      // enqueue other work. A key runs at most once in an animation frame.
      try {
        for (const key of [...this.tasks.keys()]) this.flush(key)
      } finally {
        this.running = false
        this.phase = this.interacting ? 'interaction' : this.tasks.size ? 'settle' : 'idle'
        if (this.tasks.size) this.request()
      }
    })
  }
}

/** Keeps ordered samples with fixed memory; overload drops the oldest samples. */
export class SampleRing<T> {
  readonly capacity: number
  private readonly values: Array<T | undefined>
  private head = 0
  size = 0
  dropped = 0

  constructor(capacity = 64) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new Error('Sample capacity must be a positive integer')
    this.capacity = capacity
    this.values = new Array(capacity)
  }

  push(value: T) {
    if (this.size === this.capacity) {
      this.values[this.head] = value
      this.head = (this.head + 1) % this.capacity
      this.dropped++
    } else {
      this.values[(this.head + this.size++) % this.capacity] = value
    }
  }

  drain(): T[] {
    const values: T[] = []
    while (this.size) {
      values.push(this.values[this.head]!)
      this.values[this.head] = undefined
      this.head = (this.head + 1) % this.capacity
      this.size--
    }
    return values
  }
}

import type { PaintMatrix } from './paintDisplayList'
/** Conservative largest singular value includes rotated and sheared images.
 * A mip must supply at least one source pixel per physical display pixel. */
export function imageDemand(width:number,height:number,matrix:PaintMatrix,physicalScale:number) {
  if(![width,height,physicalScale,...matrix].every(Number.isFinite)||width<=0||height<=0||physicalScale<=0)
    throw new Error('IMAGE_INVALID: physical image demand invalid')
  const density=physicalScale*maximumTransformScale(matrix)
  let divisor=1
  while(divisor<Math.max(width,height)&&1/(divisor*2)>=density)divisor*=2
  return {width:Math.max(1,Math.ceil(width/divisor)),height:Math.max(1,Math.ceil(height/divisor)),divisor}
}

export function maximumTransformScale(matrix: readonly number[]) {
  const [a,b,c,d]=matrix
  if (![a,b,c,d].every(Number.isFinite)) throw new Error('IMAGE_INVALID: transform invalid')
  const trace=a*a+b*b+c*c+d*d,det=a*d-b*c
  return Math.sqrt((trace+Math.sqrt(Math.max(0,trace*trace-4*det*det)))/2)
}

/** Portable derived-image contract. No browser, renderer or native handles. */
export type ImagePyramid = {
  schemaVersion: number; generator: string; sourceSha256: string
  width: number; height: number; tileSize: number; overlap: number; maxLevel: number
  format: string; tilesRelativePath: string; posterRelativePath: string; manifestRelativePath: string
  tileCount: number; generatedBytes: number; displayColorSpace: string
}
export type TileRect = { x: number; y: number; width: number; height: number }
export type PyramidTile = TileRect & { key: string; level: number; col: number; row: number; pixelWidth: number; pixelHeight: number; left: number; top: number; coreWidth: number; coreHeight: number }
export const TILE_ATLAS_EDGE = 4096
export const TILE_SLOT_EDGE = 514
export const TILE_CAPACITY = 49

export function requiredPyramidLevel(p: ImagePyramid, density: number) {
  return Math.max(0, Math.min(p.maxLevel, p.maxLevel + Math.ceil(Math.log2(Math.max(1e-9, density)))))
}

/** Sharpness must reflect visible residency, mip and actual backing allocation. */
export function pyramidDetailState(wanted: number, ready: number, failed: number, level: number, requiredLevel: number, actualDensity: number, requiredDensity: number) {
  if (failed > 0) return 'error'
  if (wanted < 1 || ready < wanted) return 'refining'
  if (level < requiredLevel || actualDensity + 1e-6 < requiredDensity) return 'budget-limited'
  return 'ready'
}

/** Visible tiles stay pinned and ahead of this bounded directional lookahead. */
export function planDirectionalPrefetch(p: ImagePyramid, visible: readonly PyramidTile[], view: TileRect, previous?: TileRect, limit = 2) {
  if (!visible.length || visible.length >= TILE_CAPACITY || limit < 1) return []
  const factor = 2 ** (p.maxLevel - visible[0].level), margin = factor * 512
  const candidates = planPyramid(p, { x: view.x - margin, y: view.y - margin, width: view.width + margin * 2, height: view.height + margin * 2 }, 1 / factor, 10000)
    .filter(tile => !visible.some(item => item.key === tile.key))
  const cx = view.x + view.width / 2, cy = view.y + view.height / 2
  const dx = previous ? cx - previous.x - previous.width / 2 : 0, dy = previous ? cy - previous.y - previous.height / 2 : 0, length = Math.hypot(dx,dy)
  const score = (tile: PyramidTile) => {
    const x = tile.x + tile.width / 2 - cx, y = tile.y + tile.height / 2 - cy
    return (length > 1e-6 ? (x * dx + y * dy) / length : 0) - Math.hypot(x,y)
  }
  return candidates.sort((a,b)=>score(b)-score(a)||a.key.localeCompare(b.key)).slice(0,Math.min(limit,TILE_CAPACITY-visible.length))
}

export function validPyramid(p: ImagePyramid | undefined): p is ImagePyramid {
  if (!p || p.schemaVersion !== 1 || p.tileSize !== 512 || p.overlap !== 1 || p.format !== 'png') return false
  if (![p.width, p.height, p.maxLevel].every(Number.isSafeInteger) || p.width < 1 || p.height < 1 || Math.max(p.width, p.height) > 262144 || p.width * p.height > 1e9 || p.maxLevel !== Math.ceil(Math.log2(Math.max(p.width, p.height)))) return false
  return [p.tilesRelativePath, p.posterRelativePath, p.manifestRelativePath].every(path => typeof path === 'string' && /^projects\/[^/]+\/assets\/pyramids\//.test(path) && path.split('/').every(part => part !== '..' && part !== '.' && !part.includes('\\') && !part.includes(':')))
}

/** Visible source rectangle -> physical-pixel mip, coarsened to fit pinned slots.
 * Half-open edges avoid requesting a spurious tile at exact boundaries. */
export function planPyramid(p: ImagePyramid, view: TileRect, pixelsPerSourcePixel: number, capacity = TILE_CAPACITY): PyramidTile[] {
  const x0 = Math.max(0, view.x), y0 = Math.max(0, view.y)
  const x1 = Math.min(p.width, view.x + view.width), y1 = Math.min(p.height, view.y + view.height)
  if (x1 <= x0 || y1 <= y0 || !Number.isFinite(pixelsPerSourcePixel) || capacity < 1) return []
  let level = requiredPyramidLevel(p, pixelsPerSourcePixel)
  for (;;) {
    const factor = 2 ** (p.maxLevel - level), w = Math.ceil(p.width / factor), h = Math.ceil(p.height / factor)
    const firstCol = Math.floor(x0 / factor / 512), firstRow = Math.floor(y0 / factor / 512)
    const lastCol = Math.min(Math.ceil(w / 512) - 1, Math.ceil(x1 / factor / 512) - 1)
    const lastRow = Math.min(Math.ceil(h / 512) - 1, Math.ceil(y1 / factor / 512) - 1)
    if ((lastCol - firstCol + 1) * (lastRow - firstRow + 1) > capacity && level > 0) { level--; continue }
    const tiles: PyramidTile[] = []
    for (let row = firstRow; row <= lastRow; row++) for (let col = firstCol; col <= lastCol; col++) {
      const coreWidth = Math.min(512, w - col * 512), coreHeight = Math.min(512, h - row * 512)
      const left = col > 0 ? 1 : 0, top = row > 0 ? 1 : 0
      tiles.push({ key: `${level}/${col}_${row}.png`, level, col, row, x: col * 512 * factor, y: row * 512 * factor, width: Math.min(coreWidth * factor, p.width - col * 512 * factor), height: Math.min(coreHeight * factor, p.height - row * 512 * factor), pixelWidth: coreWidth + left + Number((col + 1) * 512 < w), pixelHeight: coreHeight + top + Number((row + 1) * 512 < h), left, top, coreWidth, coreHeight })
    }
    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2
    return tiles.sort((a, b) => Math.hypot(a.x + a.width / 2 - cx, a.y + a.height / 2 - cy) - Math.hypot(b.x + b.width / 2 - cx, b.y + b.height / 2 - cy))
  }
}

/**
 * Isolated Inking Scratchpad (VectorCraft Dual-Buffer Model)
 *
 * Separates active inking strokes under stylus/pointer from the persistent committed scene.
 * Guarantees sub-4ms input-to-photon latency by avoiding whole-scene invalidations or
 * persistent curve re-tessellations during active drawing.
 */

import type { CanvasPoint, CanvasVectorCommand } from './contracts'

export type InkingStrokeStyle = Readonly<{
  width: number
  color: string
  cap?: 'butt' | 'round' | 'square'
  join?: 'miter' | 'round' | 'bevel'
}>

export type CommittedStroke = Readonly<{
  id: string
  points: readonly CanvasPoint[]
  commands: readonly CanvasVectorCommand[]
  style: InkingStrokeStyle
  timestamp: number
}>

export class InkingScratchpad {
  /** Persistent vector strokes committed to the board (rebuilt only on commit) */
  private persistentStrokes: CommittedStroke[] = []
  /** Pre-allocated flat Float32Array buffer for active inking (8192 floats = 4096 points) */
  private pointBuffer: Float32Array = new Float32Array(8192)
  private pointCount = 0
  private activeStyle: InkingStrokeStyle = { width: 2, color: '#000000', cap: 'round', join: 'round' }
  /** Monotonic revision tracking persistent scene changes */
  private persistentRevision = 0
  /** Scratchpad revision incremented on every pointer movement */
  private scratchpadRevision = 0

  get isDrawing(): boolean {
    return this.pointCount > 0
  }

  get strokeCount(): number {
    return this.persistentStrokes.length
  }

  get currentRevision(): { persistent: number; scratchpad: number } {
    return {
      persistent: this.persistentRevision,
      scratchpad: this.scratchpadRevision,
    }
  }

  /**
   * Called on pointer_down: initializes an isolated scratchpad buffer.
   * Zero memory allocation: reuses pre-allocated typed memory.
   */
  beginStroke(startPoint: CanvasPoint, style?: Partial<InkingStrokeStyle>): void {
    this.pointCount = 1
    this.pointBuffer[0] = startPoint.x
    this.pointBuffer[1] = startPoint.y

    if (style) {
      this.activeStyle = {
        width: style.width ?? 2,
        color: style.color ?? '#000000',
        cap: style.cap ?? 'round',
        join: style.join ?? 'round',
      }
    }
    this.scratchpadRevision++
  }

  /**
   * Called on pointer_move: updates ONLY the scratchpad buffer via flat typed memory.
   * Zero cost to the persistent scene (no re-allocations, zero GC churn).
   * Runs in < 0.001ms, satisfying the sub-4ms input-to-photon budget without cold-start spikes.
   */
  updateActiveStroke(point: CanvasPoint): void {
    if (this.pointCount === 0) return

    // Double buffer if capacity exceeded
    if (this.pointCount * 2 + 2 >= this.pointBuffer.length) {
      const expanded = new Float32Array(this.pointBuffer.length * 2)
      expanded.set(this.pointBuffer)
      this.pointBuffer = expanded
    }

    const idx = this.pointCount * 2
    this.pointBuffer[idx] = point.x
    this.pointBuffer[idx + 1] = point.y
    this.pointCount++
    this.scratchpadRevision++
  }

  /**
   * Returns active stroke points array (cached and synced from the typed ring buffer).
   */
  getActivePoints(): CanvasPoint[] {
    if (this.pointCount === 0) return []
    const pts: CanvasPoint[] = new Array(this.pointCount)
    for (let i = 0; i < this.pointCount; i++) {
      pts[i] = { x: this.pointBuffer[i * 2], y: this.pointBuffer[i * 2 + 1] }
    }
    return pts
  }

  /**
   * Generates smooth quadratic Bézier midpoint commands directly from the flat typed buffer.
   * Evaluates in tight loops with zero intermediate point object allocation.
   */
  getActiveCommands(): readonly CanvasVectorCommand[] {
    const count = this.pointCount
    if (count === 0) return []
    const buf = this.pointBuffer

    if (count === 1) {
      return [['M', buf[0], buf[1]], ['L', buf[0], buf[1]]]
    }
    if (count === 2) {
      return [['M', buf[0], buf[1]], ['L', buf[2], buf[3]]]
    }

    const commands: CanvasVectorCommand[] = [['M', buf[0], buf[1]]]
    for (let i = 1; i < count - 1; i++) {
      const p1x = buf[i * 2]
      const p1y = buf[i * 2 + 1]
      const p2x = buf[(i + 1) * 2]
      const p2y = buf[(i + 1) * 2 + 1]
      const midX = (p1x + p2x) / 2
      const midY = (p1y + p2y) / 2

      const prevX = i === 1 ? buf[0] : (buf[(i - 1) * 2] + p1x) / 2
      const prevY = i === 1 ? buf[1] : (buf[(i - 1) * 2 + 1] + p1y) / 2
      const cp1x = prevX + (2 / 3) * (p1x - prevX)
      const cp1y = prevY + (2 / 3) * (p1y - prevY)
      const cp2x = midX + (2 / 3) * (p1x - midX)
      const cp2y = midY + (2 / 3) * (p1y - midY)
      commands.push(['C', cp1x, cp1y, cp2x, cp2y, midX, midY])
    }
    const lastX = buf[(count - 1) * 2]
    const lastY = buf[(count - 1) * 2 + 1]
    commands.push(['L', lastX, lastY])
    return commands
  }

  /**
   * Called on pointer_up: commits the scratchpad stroke into the persistent scene.
   */
  commitStroke(id?: string): CommittedStroke | null {
    if (this.pointCount === 0) {
      this.pointCount = 0
      return null
    }

    const commands = this.getActiveCommands()
    const points = this.getActivePoints()
    const committed: CommittedStroke = {
      id: id ?? `stroke-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      points,
      commands,
      style: { ...this.activeStyle },
      timestamp: Date.now(),
    }

    this.persistentStrokes.push(committed)
    this.persistentRevision++
    this.pointCount = 0
    this.scratchpadRevision++
    return committed
  }

  /**
   * Assembles a frame scene by overlaying the active scratchpad stroke
   * on top of the persistent scene without re-allocating persistent vectors.
   */
  assembleFrameScene(): {
    persistent: readonly CommittedStroke[]
    active: {
      points: readonly CanvasPoint[]
      commands: readonly CanvasVectorCommand[]
      style: InkingStrokeStyle
    } | null
  } {
    return {
      persistent: this.persistentStrokes,
      active: this.pointCount > 0
        ? {
            points: this.getActivePoints(),
            commands: this.getActiveCommands(),
            style: this.activeStyle,
          }
        : null,
    }
  }

  /**
   * Performance harness: verifies that processing active stroke events
   * achieves sub-4ms input-to-photon latency.
   */
  benchmarkInputLatency(sampleCount = 1000): {
    totalMs: number
    avgMicrosPerPoint: number
    maxMicrosPerPoint: number
    passedSub4ms: boolean
  } {
    // Warmup JIT compiler
    this.beginStroke({ x: 0, y: 0 })
    for (let w = 0; w < 20; w++) {
      this.updateActiveStroke({ x: w, y: w })
    }
    this.commitStroke('warmup')

    // Measure steady-state active inking
    this.beginStroke({ x: 0, y: 0 })
    let maxMicros = 0
    const start = performance.now()

    for (let i = 1; i <= sampleCount; i++) {
      const t0 = performance.now()
      this.updateActiveStroke({ x: i * 0.5, y: Math.sin(i * 0.05) * 50 })
      const elapsedMicros = (performance.now() - t0) * 1000
      if (elapsedMicros > maxMicros) maxMicros = elapsedMicros
    }

    const totalMs = performance.now() - start
    const avgMicros = (totalMs / sampleCount) * 1000
    this.commitStroke('benchmark-stroke')

    return {
      totalMs,
      avgMicrosPerPoint: avgMicros,
      maxMicrosPerPoint: maxMicros,
      // Target: each point update must take well under 4ms (4000 microseconds)
      passedSub4ms: maxMicros < 4000 && avgMicros < 4000,
    }
  }
}

import type { CanvasViewport } from './contracts'

/** Live presentation state, independent of React and persisted documents.
 * Hosts present this snapshot directly; document/history updates happen at commit. */
export class LiveCamera {
  private value: CanvasViewport
  private listeners = new Set<(viewport: CanvasViewport) => void>()
  revision = 0
  constructor(initial: CanvasViewport) { this.value = { ...initial } }
  get current(): CanvasViewport { return this.value }
  present(viewport: CanvasViewport) {
    if (![viewport.x, viewport.y, viewport.scale].every(Number.isFinite) || viewport.scale <= 0) throw new Error('Invalid camera transform')
    if (viewport.x === this.value.x && viewport.y === this.value.y && viewport.scale === this.value.scale) return false
    this.value = { ...viewport }; this.revision++
    for (const listener of [...this.listeners]) listener(this.value)
    return true
  }
  subscribe(listener: (viewport: CanvasViewport) => void) {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }
}

import type { CanvasSceneSnapshot } from './contracts'

/** Disposable live paint state. Canonical documents and history belong to the
 * host; this stream only delivers immutable scene projections to presenters. */
export class LiveCanvasScene {
  private value: CanvasSceneSnapshot
  private listeners = new Set<(scene: CanvasSceneSnapshot) => void>()
  revision = 0
  constructor(initial: CanvasSceneSnapshot) { this.value = initial }
  get current(): CanvasSceneSnapshot { return this.value }
  present(scene: CanvasSceneSnapshot) {
    if (scene === this.value) return false
    this.value = scene; this.revision++
    for (const listener of [...this.listeners]) listener(this.value)
    return true
  }
  subscribe(listener: (scene: CanvasSceneSnapshot) => void) {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }
}

/** Computed colour, not model colour. Unknown colour spaces remain refused. */
export function normalizeMeasuredColor(css: string): string | null {
  if (css === 'transparent') return '#00000000'
  const match = /^(rgba?|color)\((.*)\)$/.exec(css.trim())
  if (!match) return null
  let value = match[2].trim(), normalized = false
  if (match[1] === 'color') {
    if (!value.startsWith('srgb ')) return null
    value = value.slice(5); normalized = true
  }
  const tokens = value.replace(/,/g, ' ').replace(/\//g, ' ').trim().split(/\s+/)
  if (tokens.length !== 3 && tokens.length !== 4) return null
  const numbers = tokens.map((token, index) => {
    if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?%?$/i.test(token)) return NaN
    const n = Number.parseFloat(token)
    return token.endsWith('%') ? n / 100 : index === 3 || normalized ? n : n / 255
  })
  if (!numbers.every(Number.isFinite)) return null
  if (numbers.length === 3) numbers.push(1)
  return '#' + numbers.map(n => Math.round(Math.max(0, Math.min(1, n)) * 255).toString(16).padStart(2, '0')).join('')
}

import {canvasResourceBudget,type CanvasResourceBudget,type CanvasResourceLease} from './resourceBudget'
export type ResolvedTextFont = Readonly<{
  key: string; revision: string; faceIndex: number; contentHash: string; bytes: Uint8Array
  requestedFamily: string; resolvedFamily: string; resolvedWeight: number; resolvedStyle: string
  synthesisRequired: boolean; axes: readonly unknown[]
}>
export type TextFontDescriptor = Readonly<{ family: string; weight: number; italic: boolean }>
export type TextFallbackDescriptor = Readonly<{ families: readonly string[]; text: string; weight: number; italic: boolean; locale?: string }>
export type TextFontResolver = ((request: TextFontDescriptor) => Promise<ResolvedTextFont>) & { fallbacks?: (request: TextFallbackDescriptor) => Promise<readonly ResolvedTextFont[]> }
export type ManagedTextFontResolver = TextFontResolver & { dispose(): void; stats(): Readonly<{ entries: number; bytes: number; disposed: boolean }> }

/** The native command resolves only installed families, not caller file paths. */
export function createNativeTextFontResolver(invoke: (command: string, args: unknown) => Promise<unknown>, budget: CanvasResourceBudget = canvasResourceBudget): ManagedTextFontResolver {
  const pending = new Map<string, Promise<ResolvedTextFont>>()
  const fallbackPending = new Map<string, Promise<readonly ResolvedTextFont[]>>()
  const owner = {}, leases = new Map<string, CanvasResourceLease>(), payloads = new Map<string, Uint8Array>()
  let retainedBytes = 0, disposed = false
  const resolve: TextFontResolver = async request => {
    if (disposed) throw new Error('FONT_RESOLVER_DISPOSED')
    const identity = JSON.stringify(request)
    const existing = pending.get(identity); if (existing) return existing
    if (pending.size >= 128) throw new Error('FONT_RESOURCE_LIMIT: native resolver cache entries')
    const result = invoke('resolve_system_font', { request }).then(raw => {
      if (disposed) throw new Error('FONT_RESOLVER_DISPOSED')
      const face = raw as { bytesBase64?: string; contentHash?: string; faceIndex?: number; requestedFamily?: string; resolvedFamily?: string; resolvedWeight?: number; resolvedStyle?: string; synthesisRequired?: boolean; axes?: unknown[] }
      const encoded = face.bytesBase64
      if (typeof encoded !== 'string' || encoded.length === 0 || encoded.length > Math.ceil(32 * 1024 * 1024 / 3) * 4 || encoded.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(encoded) || !/^[a-f0-9]{64}$/.test(face.contentHash ?? '') || !Number.isInteger(face.faceIndex) || face.faceIndex! < 0 || face.faceIndex! > 4096 || face.requestedFamily !== request.family || !face.resolvedFamily || face.resolvedFamily.length > 256 || !Number.isFinite(face.resolvedWeight) || face.resolvedWeight! < 1 || face.resolvedWeight! > 1000 || typeof face.resolvedStyle !== 'string' || face.resolvedStyle.length > 64 || !Array.isArray(face.axes) || typeof face.synthesisRequired !== 'boolean') {
        throw new Error('FONT_INVALID: native face receipt')
      }
      const key = `${face.contentHash}:${face.faceIndex}`, length = encoded.length / 4 * 3 - (encoded.endsWith('==') ? 2 : encoded.endsWith('=') ? 1 : 0)
      if (length <= 0 || length > 32 * 1024 * 1024) throw new Error('FONT_RESOURCE_LIMIT: native payload bytes')
      let bytes = payloads.get(key)
      if (!bytes) {
        if (retainedBytes + length > 128 * 1024 * 1024) throw new Error('FONT_RESOURCE_LIMIT: native resolver cache bytes')
        // Account the bounded IPC string and decode copies separately from the
        // retained binary. Native/Chromium transport allocations remain estimates.
        const transient = budget.acquire({ owner, key: `font-decode:${key}`, pool: 'tile-surface', bytes: encoded.length * 2 + length * 2, pinned: true })
        if (!transient) throw new Error('FONT_RESOURCE_LIMIT: native transport budget')
        try {
          const binary = atob(encoded); if (binary.length !== length) throw new Error('FONT_INVALID: base64 byte count')
          const lease = budget.acquire({ owner, key: `font-bytes:${key}`, pool: 'retained', bytes: length, pinned: true })
          if (!lease) throw new Error('FONT_RESOURCE_LIMIT: native retained budget')
          try { bytes = Uint8Array.from(binary, char => char.charCodeAt(0)); payloads.set(key, bytes); leases.set(key, lease); retainedBytes += length }
          catch (error) { lease.release(); throw error }
        } finally { transient.release() }
      }
      return {
        key, revision: face.contentHash!, faceIndex: face.faceIndex!,
        contentHash: face.contentHash!, bytes, requestedFamily: face.requestedFamily!,
        resolvedFamily: face.resolvedFamily, resolvedWeight: face.resolvedWeight!, resolvedStyle: face.resolvedStyle!,
        synthesisRequired: face.synthesisRequired === true, axes: face.axes ?? [],
      }
    }).catch(error => { pending.delete(identity); throw error })
    pending.set(identity, result); return result
  }
  const fallbacks = async (request: TextFallbackDescriptor): Promise<readonly ResolvedTextFont[]> => {
    if (disposed) throw new Error('FONT_RESOLVER_DISPOSED')
    const key = JSON.stringify(request), existing = fallbackPending.get(key); if (existing) return existing
    if (fallbackPending.size >= 128) throw new Error('FONT_RESOURCE_LIMIT: fallback cache entries')
    const result = invoke('resolve_system_font_fallbacks', { request }).then(async raw => {
      const receipt = raw as { families?: string[]; uncoveredCodePoints?: number[]; method?: string }
      if (!Array.isArray(receipt.families) || receipt.families.length > 16 || receipt.families.some(family => typeof family !== 'string' || !family || family.length > 256) || !Array.isArray(receipt.uncoveredCodePoints) || receipt.uncoveredCodePoints.some(point => !Number.isInteger(point) || point < 0 || point > 0x10ffff) || receipt.method !== 'fontique-native-script-locale-fallback-with-actual-face-coverage') throw new Error('FONT_INVALID: native fallback receipt')
      if (receipt.uncoveredCodePoints.length) throw new Error(`FONT_GLYPH_MISSING: native fallback ${receipt.uncoveredCodePoints.map(point => point.toString(16)).join(',')}`)
      const faces: ResolvedTextFont[] = []
      for (const family of receipt.families) faces.push(await resolve({ family, weight: request.weight, italic: request.italic }))
      return faces
    }).catch(error => { fallbackPending.delete(key); throw error })
    fallbackPending.set(key, result); return result
  }
  return Object.assign(resolve, { fallbacks, dispose() { disposed = true; pending.clear(); fallbackPending.clear(); payloads.clear(); leases.clear(); retainedBytes = 0; budget.releaseOwner(owner) }, stats: () => ({ entries: pending.size + fallbackPending.size, bytes: retainedBytes, disposed }) })
}

import type { CanvasVectorCommand } from './contracts'

export type PaintMatrix = readonly [number, number, number, number, number, number]
export type DecodedImageReference = Readonly<{ key: string; revision: number; epoch: number; width: number; height: number }>
export type DecodedImageUpload = Readonly<{ reference: DecodedImageReference; pixels: Uint8Array<ArrayBuffer> }>
export type GradientPaint = Readonly<{
  stops:readonly Readonly<{offset:number;color:string}>[];interpolation:'srgb';alphaInterpolation:'premultiplied'
}> & (Readonly<{kind:'linear';start:readonly [number,number];end:readonly [number,number]}>
  | Readonly<{kind:'radial';center:readonly [number,number];radius:number}>)
export type VectorPaintRecord = Readonly<Record<string, unknown>> & { readonly id: string; readonly kind: 'vector'; readonly order?: number }
export type IsolatedPaintScope = {
  readonly scopeId: string
  readonly commands: readonly CanvasVectorCommand[]
  readonly transform: PaintMatrix
  readonly fillRule: 'nonzero' | 'evenodd'
  /** Explicit isolation: blends inside see this scope's local backdrop. */
  readonly isolation: 'isolated'
}
export type PaintOperation =
  | Readonly<{ type: 'vector'; object: VectorPaintRecord }>
  | Readonly<{ type: 'image'; id: string; resource: DecodedImageReference;
      sourceRect: Readonly<{ x: number; y: number; width: number; height: number }>;
      transform: PaintMatrix; opacity: number; sampling: 'nearest' | 'bilinear' }>
  | Readonly<{type:'gradient';id:string;commands:readonly CanvasVectorCommand[];transform:PaintMatrix;brushTransform:PaintMatrix;fillRule:'nonzero'|'evenodd';gradient:GradientPaint}>
  | Readonly<{type:'blurredRoundedRect';id:string;rect:Readonly<{x:number;y:number;width:number;height:number}>;radius:number;stdDeviation:number;color:string;transform:PaintMatrix}>
  | Readonly<IsolatedPaintScope & { type: 'pushClip' }>
  | Readonly<IsolatedPaintScope & { type: 'pushComposite'; opacity: number; blendMode: 'normal' | 'multiply' | 'screen' | 'destination-out' }>
  | Readonly<{ type: 'pop'; scopeId: string }>
export type PreparedPaintDisplayList = Readonly<{
  schema: 'art-equation.display-list'
  schemaVersion: 2
  sceneId: string
  revision: string
  environment: Readonly<{ background: string; colorSpace: 'srgb' }>
  operations: readonly PaintOperation[]
  resources: readonly DecodedImageReference[]
}>

/** Compile the existing fully guarded vector batch into explicit paint order.
 * Existing identities/project/history remain authoritative. Shared Rust
 * preparation validates every scope, matrix and paint before either backend.
 * Parent ownership is never interpreted as a clip, opacity or extra transform. */
export function compileVectorPaintList(scene: {
  sceneId: string; revision: string; objects: readonly VectorPaintRecord[]
}): PreparedPaintDisplayList {
  const ids = new Set<string>()
  for (const object of scene.objects) {
    if (!object.id || ids.has(object.id) || object.kind !== 'vector' || !Number.isFinite(object.order ?? 0)) {
      throw new Error('DISPLAY_LIST_INVALID: vector identities/order must be valid before compilation')
    }
    ids.add(object.id)
  }
  const ordered = scene.objects.map((object, index) => ({ object, index }))
    .sort((a, b) => (a.object.order ?? 0) - (b.object.order ?? 0) || a.index - b.index)
  return {
    schema: 'art-equation.display-list', schemaVersion: 2, sceneId: scene.sceneId, revision: scene.revision,
    environment: { background: '#00000000', colorSpace: 'srgb' }, resources: [],
    operations: ordered.map(({ object }) => ({ type: 'vector', object })),
  }
}

/** Reserve UI/input capacity. This is admission policy, not a speed claim. */
export function preparationPolicy(logicalCores: number, memoryMiB = 4096) {
  const cores = Number.isFinite(logicalCores) ? Math.max(1, Math.floor(logicalCores)) : 1
  const reserved = cores >= 4 ? 2 : 1
  const memoryWorkers = Math.max(1, Math.floor(Math.max(128, Number.isFinite(memoryMiB) ? memoryMiB : 512) / 512))
  return { workers: Math.max(1, Math.min(4, cores - reserved, memoryWorkers)), reservedCores: reserved,
    queued: 16, workingBytes: 256 * 1024 * 1024, taskBytes: 128 * 1024 * 1024 }
}

import type { CanvasSceneSnapshot, CanvasViewport } from './contracts'

/** Tracks only fields consumed by the backdrop. Selection, media and connector
 * changes do not invalidate grid or column geometry. */
export class BackdropInvalidation {
  private gridKey = ''
  private structureKey = ''
  private sceneId: string | undefined
  private objects: CanvasSceneSnapshot['objects'] | undefined
  private viewportKey = ''
  private force = true

  reset() { this.force = true }

  consume(scene: CanvasSceneSnapshot, viewport: CanvasViewport) {
    const force = this.force || this.sceneId !== scene.id
    const grid = scene.environment.grid
    const gridKey = `${grid.visible}/${grid.color}/${grid.opacity}/${grid.spacing}`
    let structureKey = this.structureKey
    if (force || scene.objects !== this.objects) {
      structureKey = JSON.stringify(scene.objects.filter((object) => object.role === 'column').map((object) => [object.id, object.bounds]))
    }
    const viewportKey = `${viewport.x}/${viewport.y}/${viewport.scale}`
    const dirty = { grid: force || gridKey !== this.gridKey, structure: force || structureKey !== this.structureKey, viewport: force || viewportKey !== this.viewportKey }
    this.force = false
    this.sceneId = scene.id
    this.objects = scene.objects
    this.gridKey = gridKey
    this.structureKey = structureKey
    this.viewportKey = viewportKey
    return dirty
  }
}

export type CanvasResourcePool = 'tile-atlas' | 'tile-surface' | 'retained'
export type CanvasResourceLimits = Readonly<{ total: number; pools: Readonly<Record<CanvasResourcePool, number>> }>
export type CanvasResourceSnapshot = Readonly<{
  version: number
  bytes: number
  limit: number
  allocations: number
  evictions: number
  denied: number
  callbackErrors: number
  pools: Readonly<Record<CanvasResourcePool, Readonly<{ bytes: number; limit: number; allocations: number }>>>
}>

export type CanvasResourceRequest = {
  owner: object
  key: string
  pool: CanvasResourcePool
  bytes: number
  /** Active/visible resources are pinned. Only idle rebuildable entries may be evicted. */
  pinned?: boolean
  /** Larger values survive before smaller values. */
  priority?: number
  evict?: () => void
}

type RecordEntry = CanvasResourceRequest & { id: number; used: number; released: boolean }

export type CanvasResourceLease = {
  readonly key: string
  readonly pool: CanvasResourcePool
  readonly bytes: number
  touch(): void
  setPinned(pinned: boolean): void
  resize(bytes: number): boolean
  release(): void
}

export const DEFAULT_CANVAS_RESOURCE_LIMITS: CanvasResourceLimits = {
  // Estimated renderer-owned bytes. Browser compositor/driver allocations remain unavailable.
  total: 512 * 1024 * 1024,
  pools: { 'tile-atlas': 256 * 1024 * 1024, 'tile-surface': 128 * 1024 * 1024, retained: 128 * 1024 * 1024 },
}

/** Shared accounting and deterministic LRU eviction for rebuildable canvas resources. */
export class CanvasResourceBudget {
  readonly limits: CanvasResourceLimits
  private records = new Map<number, RecordEntry>()
  private listeners = new Set<() => void>()
  private serial = 0
  private nextId = 1
  private version = 0
  private evictions = 0
  private denied = 0
  private callbackErrors = 0
  private callbacks: (() => void)[] = []
  private notifying = false
  private notificationPending = false
  constructor(limits: CanvasResourceLimits = DEFAULT_CANVAS_RESOURCE_LIMITS) {
    const total = normalizedBytes(limits.total)
    const pools = Object.fromEntries(RESOURCE_POOLS.map(pool => [pool, normalizedBytes(limits.pools[pool])])) as Record<CanvasResourcePool, number>
    this.limits = Object.freeze({ total, pools: Object.freeze(pools) })
  }

  acquire(request: CanvasResourceRequest): CanvasResourceLease | undefined {
    const bytes = normalizedBytes(request.bytes)
    if (!RESOURCE_POOLS.includes(request.pool)) throw new Error('Unknown canvas resource pool')
    if (request.priority !== undefined && !Number.isFinite(request.priority)) throw new Error('Canvas resource priority must be finite')
    const victims = this.planRoom(request.pool, bytes)
    if (!victims) { this.denied++; this.changed(); return }
    const entry: RecordEntry = { ...request, bytes, id: this.nextId++, used: ++this.serial, released: false }
    // Commit the replacement before invoking disposal or subscription callbacks.
    // Those callbacks may re-enter the budget, so no half-reserved state leaks.
    for (const victim of victims) this.detach(victim, true)
    this.records.set(entry.id, entry)
    const lease: CanvasResourceLease = {
      key: entry.key,
      pool: entry.pool,
      get bytes() { return entry.bytes },
      touch: () => { if (!entry.released) entry.used = ++this.serial },
      setPinned: pinned => { if (!entry.released) { entry.pinned = pinned; entry.used = ++this.serial; this.changed() } },
      resize: value => {
        if (entry.released) return false
        const next = normalizedBytes(value), growth = Math.max(0, next - entry.bytes)
        const victims = growth ? this.planRoom(entry.pool, growth, entry.id) : []
        if (!victims) { this.denied++; this.changed(); return false }
        for (const victim of victims) this.detach(victim, true)
        entry.bytes = next; entry.used = ++this.serial; this.changed(); return true
      },
      release: () => this.release(entry, false),
    }
    this.changed()
    return lease
  }

  releaseOwner(owner: object) {
    const entries = [...this.records.values()].filter(entry => entry.owner === owner)
    for (const entry of entries) this.detach(entry, false)
    if (entries.length) this.changed()
  }

  subscribe(listener: () => void) { this.listeners.add(listener); return () => this.listeners.delete(listener) }

  snapshot(): CanvasResourceSnapshot {
    const pools = Object.fromEntries((Object.keys(this.limits.pools) as CanvasResourcePool[]).map(pool => {
      const entries = [...this.records.values()].filter(entry => entry.pool === pool)
      return [pool, { bytes: entries.reduce((sum, entry) => sum + entry.bytes, 0), limit: this.limits.pools[pool], allocations: entries.length }]
    })) as CanvasResourceSnapshot['pools']
    return { version: this.version, bytes: Object.values(pools).reduce((sum, pool) => sum + pool.bytes, 0), limit: this.limits.total, allocations: this.records.size, evictions: this.evictions, denied: this.denied, callbackErrors: this.callbackErrors, pools }
  }

  private planRoom(pool: CanvasResourcePool, bytes: number, excludedId?: number): RecordEntry[] | undefined {
    if (bytes > this.limits.total || bytes > this.limits.pools[pool]) return
    let total = 0, pooled = 0
    for (const entry of this.records.values()) { total += entry.bytes; if (entry.pool === pool) pooled += entry.bytes }
    const victims: RecordEntry[] = []
    const candidates = [...this.records.values()]
      .filter(entry => entry.id !== excludedId && !entry.pinned)
      .sort((a, b) => (a.priority || 0) - (b.priority || 0) || a.used - b.used || a.id - b.id)
    // Pool-only pressure cannot be relieved by destroying another pool. Satisfy
    // this constraint first, then apply global LRU only if total pressure remains.
    for (const victim of candidates) {
      if (pooled + bytes <= this.limits.pools[pool]) break
      if (victim.pool !== pool || victim.bytes === 0) continue
      victims.push(victim); total -= victim.bytes; pooled -= victim.bytes
    }
    if (pooled + bytes > this.limits.pools[pool]) return
    const selected = new Set(victims)
    for (const victim of candidates) {
      if (total + bytes <= this.limits.total) break
      if (selected.has(victim) || victim.bytes === 0) continue
      victims.push(victim); total -= victim.bytes
    }
    if (total + bytes > this.limits.total) return
    return victims
  }

  private release(entry: RecordEntry, evicted: boolean) {
    if (entry.released) return
    this.detach(entry, evicted)
    this.changed()
  }

  private detach(entry: RecordEntry, evicted: boolean) {
    entry.released = true; this.records.delete(entry.id)
    if (evicted) { this.evictions++; if (entry.evict) this.callbacks.push(entry.evict) }
  }

  private changed() {
    this.version++; this.notificationPending = true
    if (this.notifying) return
    this.notifying = true
    const invoke = (callback: () => void) => {
      try { callback() }
      catch (error) {
        // A disposal/listener failure cannot lose an already committed lease or
        // prevent the remaining resources from being retired. Keep it observable.
        this.callbackErrors++
        console.error('Canvas resource callback failed', error)
      }
    }
    try {
      while (this.callbacks.length || this.notificationPending) {
        const callbacks = this.callbacks; this.callbacks = []
        for (const callback of callbacks) invoke(callback)
        if (this.notificationPending) {
          this.notificationPending = false
          for (const listener of [...this.listeners]) invoke(listener)
        }
      }
    } finally { this.notifying = false }
  }
}

const RESOURCE_POOLS: CanvasResourcePool[] = ['tile-atlas', 'tile-surface', 'retained']

function normalizedBytes(value: number) {
  if (!Number.isSafeInteger(value) || value < 0) throw new Error('Canvas resource bytes must be a non-negative safe integer')
  return value
}

export const canvasResourceBudget = new CanvasResourceBudget()

import { canvasResourceBudget, type CanvasResourceLease, type CanvasResourceBudget } from './resourceBudget'
import type { CanvasRect } from './contracts'
import type { VectorPaintRecord,PaintOperation,PreparedPaintDisplayList } from './paintDisplayList'

type Source = { id: string; order: number; bounds: CanvasRect }
type Fragment<T> = { source: T; variant: number; json: string; operation:PaintOperation; token: number; lease: CanvasResourceLease }

/** Rebuildable display derivatives, never document state or GPU handles. Object
 * projections are immutable: replacement identity invalidates even if revision
 * bookkeeping was missed. Camera translation is deliberately absent. */
export class RetainedPaintCompiler<T extends Source> {
  private fragments = new Map<string, Fragment<T>>()
  private sceneId = ''
  private frame?: { key: string; json: string; lease: CanvasResourceLease }
  private previous = new Map<string, CanvasRect>()
  private builds = 0
  private hits = 0
  private budget: CanvasResourceBudget
  constructor(budget: CanvasResourceBudget = canvasResourceBudget) { this.budget = budget }
  compile(sceneId: string, revision: string, sources: readonly T[], variant: (source: T) => number,
    build: (source: T) => VectorPaintRecord) {
    const sceneChanged = this.sceneId !== sceneId
    if (sceneChanged) { this.clear(); this.sceneId = sceneId }
    const ids = new Set<string>(), changed: CanvasRect[] = [], parts: string[] = [], operations:PaintOperation[]=[], tokens: number[] = []
    const ordered = sources.map((source, index) => ({ source, index }))
      .sort((a, b) => a.source.order - b.source.order || a.index - b.index)
    for (const { source } of ordered) {
      if (!source.id || ids.has(source.id) || !Number.isFinite(source.order)) throw new Error('DISPLAY_LIST_INVALID: duplicate identity or invalid order')
      ids.add(source.id)
      const scale = variant(source)
      if (!Number.isFinite(scale) || scale <= 0) throw new Error('DISPLAY_LIST_INVALID: invalid physical scale variant')
      let entry = this.fragments.get(source.id)
      if (entry?.source === source && entry.variant === scale) { entry.lease.touch(); this.hits++ }
      else {
        const old = this.previous.get(source.id)
        if (old) changed.push({ ...old })
        changed.push({ ...source.bounds })
        entry?.lease.release(); this.fragments.delete(source.id)
        const operation:PaintOperation={type:'vector',object:build(source)}
        const json = JSON.stringify(operation)
        const token = ++this.builds
        const lease = this.budget.acquire({ owner: this, key: source.id, pool: 'retained', bytes: json.length * 2,
          priority: 2, evict: () => { this.fragments.delete(source.id); this.releaseFrame() } })
        entry = lease ? { source, variant: scale, json, operation, token, lease } : undefined
        if (entry) this.fragments.set(source.id, entry)
        if (!entry) { parts.push(json); operations.push(operation);tokens.push(token) }
      }
      if (entry) { parts.push(entry.json);operations.push(entry.operation); tokens.push(entry.token) }
    }
    for (const [id, entry] of this.fragments) if (!ids.has(id)) { entry.lease.release(); this.fragments.delete(id) }
    for (const [id, bounds] of this.previous) if (!ids.has(id)) changed.push({ ...bounds })
    this.previous = new Map(sources.map(source => [source.id, { ...source.bounds }]))
    // Full target rendering remains the pixel oracle. Damage records authorize
    // preparation reuse only; effects/clips are not silently scissored here.
    // Frame identity is derived paint, not the enclosing camera/document generation.
    // Immutable source/variant tokens change whenever paint changes.
    const key = JSON.stringify([sceneId, tokens])
    let json: string
    if (this.frame?.key === key) { this.frame.lease.touch(); json = this.frame.json }
    else {
      this.releaseFrame()
      json = `{"schema":"art-equation.display-list","schemaVersion":2,"sceneId":${JSON.stringify(sceneId)},"revision":${JSON.stringify(revision)},"environment":{"background":"#00000000","colorSpace":"srgb"},"resources":[],"operations":[${parts.join(',')}]}`
      const lease = this.budget.acquire({ owner: this, key: 'frame', pool: 'retained', bytes: (key.length + json.length) * 2,
        priority: 1, evict: () => { this.frame = undefined } })
      if (lease) this.frame = { key, json, lease }
    }
    const displayList:PreparedPaintDisplayList={schema:'art-equation.display-list',schemaVersion:2,sceneId,revision,environment:{background:'#00000000',colorSpace:'srgb'},resources:[],operations}
    return { ids, json, displayList, damage: { sceneChanged, gpuFullRedraw: true, world: changed }, stats: { builds: this.builds, hits: this.hits, retained: this.fragments.size } }
  }
  private releaseFrame() { this.frame?.lease.release(); this.frame = undefined }
  clear() {
    this.releaseFrame()
    for (const entry of this.fragments.values()) entry.lease.release()
    this.fragments.clear(); this.previous.clear(); this.sceneId = ''
  }
}

import type {
  CanvasHostCommand,
  CanvasSceneChangeSet,
  CanvasSceneSnapshot,
  CanvasTelemetryEvent,
  CanvasViewport,
} from './contracts'

/** Host-neutral identifier. Consumers map it to their own project/document IDs. */
export type CanvasDocumentAddress = Readonly<{
  projectId: string
  documentId: string
  sceneId: string
}>

/** The bridge reserves spatial placement without requiring a 3D renderer now. */
export type CanvasPlacement =
  | Readonly<{ kind: 'plane-2d'; x: number; y: number; rotation: number }>
  | Readonly<{ kind: 'plane-3d'; matrix: readonly [number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number] }>

export type CanvasBridgeCapabilities = Readonly<{
  renderer: 'vello-gpu' | 'vello-cpu'
  dimensions: readonly ('2d' | '3d')[]
  transientCamera: boolean
  nestedScenes: boolean
  incrementalChanges: boolean
}>

export type CanvasBridgeState = Readonly<{
  address: CanvasDocumentAddress
  viewport: CanvasViewport
  placement: CanvasPlacement
  selection: readonly string[]
}>

/** Implemented by Art Equation, Eclipse Documentation Hub, or Nana Banana.
 * The reusable canvas never imports a consumer's React stores or persistence. */
export interface CanvasBridgeHost {
  loadScene(address: CanvasDocumentAddress, signal: AbortSignal): Promise<CanvasSceneSnapshot>
  commit(command: CanvasHostCommand): void
  resolveAsset(assetId: string, revision: number, signal: AbortSignal): Promise<string>
  saveNavigation(state: CanvasBridgeState): void
  recordTelemetry(event: CanvasTelemetryEvent): void
}

/** Implemented by a canvas runtime. Vello GPU and Vello CPU share this contract without changing consumer adapters. */
export interface ReusableCanvasRuntime {
  readonly capabilities: CanvasBridgeCapabilities
  open(host: CanvasBridgeHost, initial: CanvasBridgeState, signal: AbortSignal): Promise<CanvasSceneSnapshot>
  applyChanges(changes: CanvasSceneChangeSet): void
  setViewport(viewport: CanvasViewport, transient: boolean): void
  setPlacement(placement: CanvasPlacement): void
  setSelection(objectIds: readonly string[]): void
  close(): void
}

/** Small stateful coordinator shared by host adapters. It contains no rendering,
 * storage, board, document, or application-specific policy. */
export class ReusableCanvasBridge {
  #runtime: ReusableCanvasRuntime
  #host: CanvasBridgeHost
  #state: CanvasBridgeState | null = null

  constructor(runtime: ReusableCanvasRuntime, host: CanvasBridgeHost) {
    this.#runtime = runtime
    this.#host = host
  }

  get capabilities() { return this.#runtime.capabilities }
  get state() { return this.#state }

  async open(initial: CanvasBridgeState, signal: AbortSignal) {
    const scene = await this.#runtime.open(this.#host, initial, signal)
    this.#state = initial
    return scene
  }

  updateNavigation(update: Partial<Pick<CanvasBridgeState, 'viewport' | 'placement' | 'selection'>>, transient = false) {
    if (!this.#state) return
    this.#state = { ...this.#state, ...update }
    if (update.viewport) this.#runtime.setViewport(update.viewport, transient)
    if (update.placement) this.#runtime.setPlacement(update.placement)
    if (update.selection) this.#runtime.setSelection(update.selection)
    if (!transient) this.#host.saveNavigation(this.#state)
  }

  applyChanges(changes: CanvasSceneChangeSet) {
