        if (disposed || !read(() => element.isConnected && element.innerHTML === fingerprint)) return disposedResult(options, 'TEXT_LAYOUT_CHANGED_DURING_PREPARATION', fingerprint)
        const estimatedBytes = JSON.stringify(operations).length * 4
        const resultLease = budget.acquire({ owner, key: `text-paint:${options.id}:${options.revision}`, pool: 'retained', bytes: estimatedBytes, pinned: true })
        if (!resultLease) return disposedResult(options, 'FONT_RESOURCE_LIMIT: positioned outline budget', fingerprint)
        const completePaint = [...usedFaces].every(face => PIXEL_QUALIFIED_FONT_FACES.has(face))
        return { id: options.id, revision: options.revision, fontEpoch, sourceFingerprint: fingerprint, completePaint, operations,
          blockers: completePaint ? [] : ['TEXT_FONT_PIXEL_ACCEPTANCE_PENDING'], qualification: { policy: 'actual-font-measured-lines-shared-outline-v2', fontHashes: [...usedFonts], widthDifferences: differences, lines, scaleDependent }, release: () => resultLease.release() }
      } catch (error) { const blocker = String(error); return disposedResult(options, blocker.includes('TEXT_BASELINE_') ? `${blocker}; provider ${JSON.stringify(options.id)}` : blocker, fingerprint) }
    },
    stats: () => ({ fontEpoch, disposed, registeredFonts: registered.size, engine: JSON.parse(engine.resource_stats()), budgetBytes: lease?.bytes ?? 0 }),
    dispose() { if (disposed) return; disposed = true; registered.clear(); engine.free?.(); budget.releaseOwner(owner) },
  }
}

export const prepareSemanticParagraphPaint = (session: ReturnType<typeof createTextPaintSession>, element: HTMLElement, options: Parameters<typeof session.prepare>[1]) => session.prepare(element, options)
export const prepareSemanticSvgTextPaint = (session: ReturnType<typeof createTextPaintSession>, element: SVGTextElement, options: SvgTextPaintOptions) => session.prepareSvg(element, options)

/** Fixed shards preserve immutable render snapshots while copying only changed
 * buckets. Forking cost is independent of board membership; no overlay chains. */
class ShardedMap<V> {
 private buckets:Map<string,V>[] = Array.from({length:128},()=>new Map())
 private owned=new Set<number>(Array.from({length:128},(_,i)=>i))
 private count=0
 copiedEntries=0
 private bucket(key:string){let hash=2166136261;for(let i=0;i<key.length;i++)hash=Math.imul(hash^key.charCodeAt(i),16777619);return (hash>>>0)%128}
 private write(i:number){if(!this.owned.has(i)){this.copiedEntries+=this.buckets[i].size;this.buckets[i]=new Map(this.buckets[i]);this.owned.add(i)}return this.buckets[i]}
 fork(){const next=new ShardedMap<V>();next.buckets=this.buckets.slice();next.owned.clear();this.owned.clear();next.count=this.count;return next}
 get size(){return this.count}
 get(key:string){return this.buckets[this.bucket(key)].get(key)}
 set(key:string,value:V){const b=this.write(this.bucket(key));if(!b.has(key))this.count++;b.set(key,value);return this}
 delete(key:string){const i=this.bucket(key);if(!this.buckets[i].has(key))return false;this.write(i).delete(key);this.count--;return true}
 *keys(){for(const b of this.buckets)yield* b.keys()}
 *values(){for(const b of this.buckets)yield* b.values()}
}

import type { CanvasRect } from './contracts'

export type SpatialRecord = Readonly<{ id: string; bounds: CanvasRect }>

function intersects(a: CanvasRect, b: CanvasRect) {
  return a.x <= b.x + b.width && a.x + a.width >= b.x && a.y <= b.y + b.height && a.y + a.height >= b.y
}

function sameBounds(a: CanvasRect, b: CanvasRect) {
  return a.x === b.x && a.y === b.y && a.width === b.width && a.height === b.height
}

function validBounds(bounds: CanvasRect) {
  return [bounds.x, bounds.y, bounds.width, bounds.height, bounds.x + bounds.width, bounds.y + bounds.height].every(Number.isFinite)
    && bounds.width >= 0 && bounds.height >= 0
}

/** A predictable, incrementally maintained broad-phase index for sparse, unbounded 2D boards. */
export class UniformGridSpatialIndex<T extends SpatialRecord> {
  readonly cellSize: number
  private records = new ShardedMap<T>()
  private recordCells = new ShardedMap<string[]>()
  private cells = new ShardedMap<Set<string>>()
  private overflow = new Set<string>()

  constructor(records: readonly T[] = [], cellSize = 512) {
    if (!Number.isFinite(cellSize) || cellSize <= 0) throw new Error('Spatial-index cell size must be positive')
    this.cellSize = cellSize
    this.reconcile(records)
  }

  get size() {
    return this.records.size
  }

  get cellCount() {
    return this.cells.size
  }

  get(id: string) {
    return this.records.get(id)
  }

  /** Isolated render snapshot. Unchanged cell sets are shared; edits copy only
   * touched sets so abandoned React renders cannot mutate the committed index. */
  fork(records: readonly T[]) {
    const next = new UniformGridSpatialIndex<T>([], this.cellSize)
    next.records = this.records.fork()
    next.recordCells = this.recordCells.fork()
    next.cells = this.cells.fork()
    next.overflow = new Set(this.overflow)
    next.reconcile(records)
    return next
  }

  /** Explicit edit batches bypass full reconcile and preserve the old snapshot. */
  forkChanges(changed:readonly T[],removed:readonly string[]=[]) {
    const next=new UniformGridSpatialIndex<T>([],this.cellSize)
    next.records=this.records.fork();next.recordCells=this.recordCells.fork();next.cells=this.cells.fork();next.overflow=new Set(this.overflow)
    for(const id of removed)next.remove(id)
    for(const record of changed)next.upsert(record)
    return next
  }
  get copiedEntries(){return this.records.copiedEntries+this.recordCells.copiedEntries+this.cells.copiedEntries}

  query(bounds: CanvasRect): T[] {
    if (!validBounds(bounds)) return []
    const found = new Map<string, T>()
    const range = this.cellRange(bounds, 16_384)
    // An enormous viewport or coordinate must not enumerate unbounded cells.
    // Scan the finite record membership without clamping the user's geometry.
    if (!range) return [...this.records.values()].filter(entry => !validBounds(entry.bounds) || intersects(entry.bounds, bounds))
    this.visitCellKeys(range, (key) => {
      for (const id of this.cells.get(key) || []) {
        const entry = this.records.get(id)
        if (entry && !found.has(id) && intersects(entry.bounds, bounds)) found.set(id, entry)
      }
    })
    for (const id of this.overflow) {
      const entry = this.records.get(id)
      if (entry && (!validBounds(entry.bounds) || intersects(entry.bounds, bounds))) found.set(id, entry)
    }
    return [...found.values()]
  }

  upsert(record: T) {
    const existing = this.records.get(record.id)
    this.records.set(record.id, record)
    if (existing && sameBounds(existing.bounds, record.bounds)) return
    if (existing) this.removeFromCells(record.id)
    const range = this.cellRange(record.bounds, 4_096)
    if (!range) { this.overflow.add(record.id); return }
    const keys: string[] = []
    this.visitCellKeys(range, (key) => {
      keys.push(key)
      const ids = this.cells.get(key)
      this.cells.set(key, new Set(ids).add(record.id))
    })
    this.recordCells.set(record.id, keys)
  }

  remove(id: string) {
    if (!this.records.delete(id)) return false
    this.removeFromCells(id)
    return true
  }

  reconcile(records: readonly T[]) {
    const retained = new Set<string>()
    for (const record of records) {
      retained.add(record.id)
      if(this.records.get(record.id)!==record)this.upsert(record)
    }
    for (const id of this.records.keys()) if (!retained.has(id)) this.remove(id)
  }

  private removeFromCells(id: string) {
    this.overflow.delete(id)
    for (const key of this.recordCells.get(id) || []) {
      const ids = new Set(this.cells.get(key))
      ids.delete(id)
      if (ids.size) this.cells.set(key, ids)
      else this.cells.delete(key)
    }
    this.recordCells.delete(id)
  }

  private cellRange(bounds: CanvasRect, limit: number) {
    if (!validBounds(bounds)) return undefined
    const left = Math.floor(bounds.x / this.cellSize)
    const top = Math.floor(bounds.y / this.cellSize)
    const right = Math.floor((bounds.x + Math.max(0, bounds.width)) / this.cellSize)
    const bottom = Math.floor((bounds.y + Math.max(0, bounds.height)) / this.cellSize)
    if (![left, top, right, bottom].every(Number.isSafeInteger)) return undefined
    const columns = right - left + 1, rows = bottom - top + 1
    if (columns > limit || rows > limit || columns * rows > limit) return undefined
    return { left, top, right, bottom }
  }

  private visitCellKeys({ left, top, right, bottom }: { left: number; top: number; right: number; bottom: number }, visit: (key: string) => void) {
    for (let y = top; y <= bottom; y += 1) {
      for (let x = left; x <= right; x += 1) visit(`${x}:${y}`)
    }
  }
}

export type VectorPoint = {
  x: number
  y: number
  handleIn?: { x: number; y: number }
  handleOut?: { x: number; y: number }
}

export type VectorPathLike = { closed: boolean; points: VectorPoint[] }
export type VectorLodBand = 'exact' | 'near' | 'medium' | 'far'
export type VectorGeometry = Readonly<{
  canonicalData: string
  renderData: string
  hitData: string
  segmentData: readonly string[]
  segmentHitData: readonly string[]
  band: VectorLodBand
  estimatedBytes: number
}>

type BaseGeometry = { id: number; canonicalData: string; segmentData: string[] }
type CacheEntry = VectorGeometry & { key: string; used: number }

const round = (value: number) => Math.round(value * 1e4) / 1e4
const pointText = (point: { x: number; y: number }) => `${round(point.x)} ${round(point.y)}`
const add = (point: { x: number; y: number }, offset?: { x: number; y: number }) => ({ x: point.x + (offset?.x || 0), y: point.y + (offset?.y || 0) })

function segmentData(path: VectorPathLike, index: number) {
  const from = path.points[index]
  const nextIndex = index + 1 < path.points.length ? index + 1 : path.closed ? 0 : -1
  const to = path.points[nextIndex]
  if (!from || !to) return ''
  return from.handleOut || to.handleIn
    ? `M ${pointText(from)} C ${pointText(add(from, from.handleOut))} ${pointText(add(to, to.handleIn))} ${pointText(to)}`
    : `M ${pointText(from)} L ${pointText(to)}`
}

function exactPathData(path: VectorPathLike) {
  if (!path.points.length) return ''
  const segments = Array.from({ length: path.closed ? path.points.length : Math.max(0, path.points.length - 1) }, (_, index) => segmentData(path, index).replace(/^M [^CL]+ (?=[CL])/, ''))
  return `M ${pointText(path.points[0])}${segments.length ? ` ${segments.join(' ')}` : ''}${path.closed && path.points.length > 2 ? ' Z' : ''}`
}

function distanceToLine(point: VectorPoint, start: VectorPoint, end: VectorPoint) {
  const dx = end.x - start.x, dy = end.y - start.y
  const length = Math.hypot(dx, dy)
  return length < 1e-8 ? Math.hypot(point.x - start.x, point.y - start.y) : Math.abs(dy * point.x - dx * point.y + end.x * start.y - end.y * start.x) / length
}

function flattenCubic(p0: VectorPoint, p1: VectorPoint, p2: VectorPoint, p3: VectorPoint, tolerance: number, output: VectorPoint[], depth = 0) {
  if (depth >= 10 || Math.max(distanceToLine(p1, p0, p3), distanceToLine(p2, p0, p3)) <= tolerance) { output.push({ x: p3.x, y: p3.y }); return }
  const midpoint = (a: VectorPoint, b: VectorPoint): VectorPoint => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 })
  const a = midpoint(p0, p1), b = midpoint(p1, p2), c = midpoint(p2, p3), d = midpoint(a, b), e = midpoint(b, c), m = midpoint(d, e)
  flattenCubic(p0, a, d, m, tolerance, output, depth + 1)
  flattenCubic(m, e, c, p3, tolerance, output, depth + 1)
}

function flattenedSegments(path: VectorPathLike, tolerance: number) {
  const count = path.closed ? path.points.length : Math.max(0, path.points.length - 1)
  return Array.from({ length: count }, (_, index) => {
    const from = path.points[index], to = path.points[index + 1 < path.points.length ? index + 1 : 0]
    const points: VectorPoint[] = [{ x: from.x, y: from.y }]
    if (from.handleOut || to.handleIn) flattenCubic(from, add(from, from.handleOut), add(to, to.handleIn), to, tolerance, points)
    else points.push({ x: to.x, y: to.y })
    return points
  })
}

function polylineData(points: VectorPoint[]) {
  if (!points.length) return ''
  return `M ${pointText(points[0])}${points.slice(1).map((point) => ` L ${pointText(point)}`).join('')}`
}

function combinedPolylineData(segments: VectorPoint[][], closed: boolean) {
  if (!segments.length) return ''
  return `${polylineData([segments[0][0], ...segments.flatMap((points) => points.slice(1))])}${closed ? ' Z' : ''}`
}

export function vectorLodBand(scale: number): VectorLodBand {
  if (scale >= 1) return 'exact'
  if (scale >= .5) return 'near'
  if (scale >= .25) return 'medium'
  return 'far'
}

const screenError: Record<VectorLodBand, number> = { exact: 0, near: .35, medium: .6, far: .85 }
// Use each band's upper zoom edge so projected error never exceeds its cap.
const bandScale: Record<VectorLodBand, number> = { exact: 1, near: 1, medium: .5, far: .25 }

/** Bounded, renderer-owned geometry. Canonical document points never depend on it. */
export class VectorGeometryCache {
  readonly byteLimit: number
  private identities = new WeakMap<object, BaseGeometry>()
  private entries = new Map<string, CacheEntry>()
  private nextId = 1
  private serial = 0
  private bytes = 0
  private builds = 0
  private hits = 0
  private evictions = 0
  constructor(byteLimit = 32 * 1024 * 1024) { this.byteLimit = byteLimit }

  get(path: VectorPathLike, scale: number, exact = false): VectorGeometry {
    let base = this.identities.get(path)
    if (!base) {
      const segmentCount = path.closed ? path.points.length : Math.max(0, path.points.length - 1)
      base = { id: this.nextId++, canonicalData: exactPathData(path), segmentData: Array.from({ length: segmentCount }, (_, index) => segmentData(path, index)) }
      this.identities.set(path, base)
    }
    const band = exact ? 'exact' : vectorLodBand(scale)
    const key = `${base.id}/${band}`
    const cached = this.entries.get(key)
    if (cached) { cached.used = ++this.serial; this.hits++; return cached }
    const renderTolerance = screenError[band] / bandScale[band]
    const renderSegments = band === 'exact' ? [] : flattenedSegments(path, renderTolerance)
    const hitSegments = flattenedSegments(path, Math.max(.25, .75 / Math.max(.18, scale)))
    const renderData = band === 'exact' ? base.canonicalData : combinedPolylineData(renderSegments, path.closed)
    const segmentHitData = hitSegments.map(polylineData)
    const hitData = combinedPolylineData(hitSegments, path.closed)
    const strings = [base.canonicalData, renderData, hitData, ...base.segmentData, ...segmentHitData]
    const estimatedBytes = strings.reduce((total, value) => total + value.length * 2, 0) + path.points.length * 64
    const entry: CacheEntry = { key, canonicalData: base.canonicalData, renderData, hitData, segmentData: base.segmentData, segmentHitData, band, estimatedBytes, used: ++this.serial }
    this.entries.set(key, entry); this.bytes += estimatedBytes; this.builds++; this.trim()
    return entry
  }

  clear() { this.identities = new WeakMap(); this.entries.clear(); this.bytes = 0 }
  snapshot() { return { bytes: this.bytes, limit: this.byteLimit, entries: this.entries.size, builds: this.builds, hits: this.hits, evictions: this.evictions } }
  private trim() {
    while (this.bytes > this.byteLimit && this.entries.size > 1) {
      let oldest: CacheEntry | undefined
      for (const entry of this.entries.values()) if (!oldest || entry.used < oldest.used) oldest = entry
      if (!oldest) break
      this.entries.delete(oldest.key); this.bytes -= oldest.estimatedBytes; this.evictions++
    }
  }
}

/** Appends an authored Pen segment in O(1); edits fall back to an exact rebuild. */
export class IncrementalPenPath {
  private points: readonly VectorPoint[] = []
  private data = ''
  private appends = 0
  private rebuilds = 0
  sync(points: readonly VectorPoint[]) {
    if (!points.length) { this.points = points; this.data = ''; return this.data }
    const appended = points.length === this.points.length + 1 && this.points.every((point, index) => point === points[index])
    if (appended) {
      this.data = this.points.length ? `${this.data} ${segmentData({ closed: false, points: points as VectorPoint[] }, points.length - 2).replace(/^M [^CL]+ (?=[CL])/, '')}` : `M ${pointText(points[0])}`
      this.appends++
    } else { this.data = exactPathData({ closed: false, points: points as VectorPoint[] }); this.rebuilds++ }
    this.points = points
    return this.data
  }
  snapshot() { return { appends: this.appends, rebuilds: this.rebuilds, points: this.points.length } }
}

export const vectorGeometryCache = new VectorGeometryCache()

/**
 * ViewportCamera Mathematical Model (Standardized Canvas Camera)
 *
 * Provides sub-pixel accurate world-to-screen transforms, screen-to-world unprojection,
 * and zero-cost frustum / AABB culling shared across Vello and Bevy engines.
 */

import type { CanvasRect, CanvasViewport } from './contracts'

export type BoundingBoxAABB = readonly [number, number, number, number] // [minX, minY, maxX, maxY]

export class ViewportCamera {
  /** Canvas center in world coordinates [cx, cy] */
  readonly position: readonly [number, number]
  /** Camera zoom scale (1.0 = 100%, 0.5 = Zoomed in, 2.0 = Zoomed out) */
  readonly zoom: number
  /** Screen / viewport dimension in physical pixels [width, height] */
  readonly viewportSize: readonly [number, number]

  constructor(
    position: readonly [number, number] = [0, 0],
    zoom = 1.0,
    viewportSize: readonly [number, number] = [1920, 1080]
  ) {
    if (!Number.isFinite(zoom) || zoom <= 0) {
      throw new Error(`ViewportCamera zoom must be a positive finite number, got: ${zoom}`)
    }
    if (!Number.isFinite(position[0]) || !Number.isFinite(position[1])) {
      throw new Error(`ViewportCamera position coordinates must be finite: [${position[0]}, ${position[1]}]`)
    }
    if (viewportSize[0] < 0 || viewportSize[1] < 0) {
      throw new Error(`ViewportCamera viewport size must be non-negative: [${viewportSize[0]}, ${viewportSize[1]}]`)
    }
    this.position = [position[0], position[1]]
    this.zoom = zoom
    this.viewportSize = [viewportSize[0], viewportSize[1]]
  }

  /**
   * Generates world-space AABB [minX, minY, maxX, maxY] for zero-cost frustum culling.
   */
  visibleWorldBounds(): BoundingBoxAABB {
    const halfW = (this.viewportSize[0] * this.zoom) / 2.0
    const halfH = (this.viewportSize[1] * this.zoom) / 2.0
    return [
      this.position[0] - halfW,
      this.position[1] - halfH,
      this.position[0] + halfW,
      this.position[1] + halfH,
    ]
  }

  /**
   * Converts world coordinates to Vello 2D affine matrix [sx, kx, ky, sy, tx, ty].
   * Translates world center to viewport center and scales by (1.0 / zoom).
   */
  toVelloAffine(): readonly [number, number, number, number, number, number] {
    const invZoom = 1.0 / this.zoom
    const tx = -this.position[0] * invZoom + this.viewportSize[0] / 2.0
    const ty = -this.position[1] * invZoom + this.viewportSize[1] / 2.0
    return [invZoom, 0, 0, invZoom, tx, ty]
  }

  /**
   * Evaluates if an entity's world bounding box [minX, minY, maxX, maxY]
   * intersects the camera's visible frustum.
   */
  intersectsFrustum(aabb: BoundingBoxAABB): boolean {
    const cam = this.visibleWorldBounds()
    return !(
      aabb[2] < cam[0] || // right < left
      aabb[0] > cam[2] || // left > right
      aabb[3] < cam[1] || // bottom < top
      aabb[1] > cam[3]    // top > bottom
    )
  }

  /**
   * Evaluates if a CanvasRect intersects the camera's visible frustum.
   */
  intersectsRect(rect: CanvasRect): boolean {
    const aabb: BoundingBoxAABB = [
      rect.x,
      rect.y,
      rect.x + rect.width,
      rect.y + rect.height,
    ]
    return this.intersectsFrustum(aabb)
  }

  /**
   * Unprojects a screen-space point to canvas world-space coordinates.
   */
  screenToWorld(screenPt: readonly [number, number]): readonly [number, number] {
    return [
      this.position[0] + (screenPt[0] - this.viewportSize[0] / 2.0) * this.zoom,
      this.position[1] + (screenPt[1] - this.viewportSize[1] / 2.0) * this.zoom,
    ]
  }

  /**
   * Projects a canvas world-space point to screen-space pixel coordinates.
   */
  worldToScreen(worldPt: readonly [number, number]): readonly [number, number] {
    const invZoom = 1.0 / this.zoom
    return [
      (worldPt[0] - this.position[0]) * invZoom + this.viewportSize[0] / 2.0,
      (worldPt[1] - this.position[1]) * invZoom + this.viewportSize[1] / 2.0,
    ]
  }

  /**
   * Constructs a ViewportCamera from legacy CanvasViewport {x, y, scale}.
   * Note: in legacy CanvasViewport, x, y represent pan offset and scale is 1/zoom.
   */
  static fromViewport(
    viewport: CanvasViewport,
    viewportSize: readonly [number, number] = [1920, 1080]
  ): ViewportCamera {
    const zoom = viewport.scale > 0 ? 1.0 / viewport.scale : 1.0
    // World position from pan offset:
    const position: [number, number] = [
      (viewportSize[0] / 2.0 - viewport.x) * zoom,
      (viewportSize[1] / 2.0 - viewport.y) * zoom,
    ]
    return new ViewportCamera(position, zoom, viewportSize)
  }

  /**
   * Converts to legacy CanvasViewport representation.
   */
  toViewport(): CanvasViewport {
    const scale = 1.0 / this.zoom
    const x = this.viewportSize[0] / 2.0 - this.position[0] * scale
    const y = this.viewportSize[1] / 2.0 - this.position[1] * scale
    return { x, y, scale }
  }

  /**
   * Computes Sparse Virtual Texturing (SVT) Mip/LOD level based on camera zoom.
   * Zoom = 1.0 -> LOD 0 (full resolution)
   * Zoom = 2.0 (zoomed out 0.5x) -> LOD 1 (half resolution)
   * Zoom = 4.0 (zoomed out 0.25x) -> LOD 2 (quarter resolution)
   */
  computeTileLOD(maxLod = 5): number {
    if (this.zoom <= 1.0 || !Number.isFinite(this.zoom)) return 0
    const lod = Math.floor(Math.log2(this.zoom))
    return Math.min(Math.max(0, lod), maxLod)
  }

  /**
   * Fast hierarchical spatial culling against a SpatialQuadtree.
   * Discards entire off-screen spatial branches in O(log N) time, bypassing flat O(N) linear scans.
   */
  cullQuadtree(quadtree: SpatialQuadtree): SpatialQuadtreeItem[] {
    return quadtree.queryFrustum(this)
  }
}

export interface SpatialQuadtreeItem {
  readonly id: string | number
  readonly bounds: BoundingBoxAABB
}

/**
 * 2D Loose Quadtree Spatial Index for high-density infinite canvas boards (10,000+ entities).
 * Eliminates linear O(N) frustum culling overhead by pruning off-screen quadrants in O(log N) time.
 */
export class SpatialQuadtree {
  readonly bounds: BoundingBoxAABB
  readonly maxItems: number
  readonly maxDepth: number
  readonly depth: number
  private items: SpatialQuadtreeItem[] = []
  private children: [SpatialQuadtree, SpatialQuadtree, SpatialQuadtree, SpatialQuadtree] | null = null

  constructor(
    bounds: BoundingBoxAABB = [-100000, -100000, 100000, 100000],
    maxItems = 32,
    maxDepth = 8,
    depth = 0
  ) {
    this.bounds = bounds
    this.maxItems = maxItems
    this.maxDepth = maxDepth
    this.depth = depth
  }

  insert(item: SpatialQuadtreeItem): boolean {
    const [minX, minY, maxX, maxY] = this.bounds
    const [iMinX, iMinY, iMaxX, iMaxY] = item.bounds

    // Check if item intersects node bounds
    if (iMaxX < minX || iMinX > maxX || iMaxY < minY || iMinY > maxY) {
      return false
    }

    if (this.children) {
      let inserted = false
      for (let i = 0; i < 4; i++) {
        if (this.children[i].insert(item)) {
          inserted = true
        }
      }
      return inserted
    }

    this.items.push(item)

    if (this.items.length > this.maxItems && this.depth < this.maxDepth) {
      this.subdivide()
    }
    return true
  }

  private subdivide(): void {
    const [minX, minY, maxX, maxY] = this.bounds
    const midX = (minX + maxX) / 2
    const midY = (minY + maxY) / 2
    const nextDepth = this.depth + 1

    this.children = [
      new SpatialQuadtree([minX, minY, midX, midY], this.maxItems, this.maxDepth, nextDepth),
      new SpatialQuadtree([midX, minY, maxX, midY], this.maxItems, this.maxDepth, nextDepth),
      new SpatialQuadtree([minX, midY, midX, maxY], this.maxItems, this.maxDepth, nextDepth),
      new SpatialQuadtree([midX, midY, maxX, maxY], this.maxItems, this.maxDepth, nextDepth),
    ]

    const existing = this.items
    this.items = []
    for (const item of existing) {
      for (let i = 0; i < 4; i++) {
        this.children[i].insert(item)
      }
    }
  }

  /**
   * Queries visible items intersecting the camera view frustum in O(log N) time.
   */
  queryFrustum(
    camera: ViewportCamera,
    visitedSet = new Set<string | number>(),
    out: SpatialQuadtreeItem[] = []
  ): SpatialQuadtreeItem[] {
    if (!camera.intersectsFrustum(this.bounds)) {
      return out
    }

    for (let i = 0; i < this.items.length; i++) {
      const item = this.items[i]
      if (!visitedSet.has(item.id)) {
        visitedSet.add(item.id)
        if (camera.intersectsFrustum(item.bounds)) {
          out.push(item)
        }
      }
    }

    if (this.children) {
      for (let i = 0; i < 4; i++) {
        this.children[i].queryFrustum(camera, visitedSet, out)
      }
    }

    return out
  }

  clear(): void {
    this.items.length = 0
    this.children = null
  }
}

import type {CanvasSceneObject,CanvasSceneSnapshot} from './contracts'
type Index={objects:Map<string,{object:CanvasSceneObject;index:number}>;edges:Map<string,CanvasSceneSnapshot['connections'][number][]>}
const objectIndexes=new WeakMap<CanvasSceneSnapshot['objects'],Index['objects']>(),edgeIndexes=new WeakMap<CanvasSceneSnapshot['connections'],Index['edges']>()
/** Membership is supplied by the spatial index. Camera work visits only those
 * IDs and incident graph edges; immutable source arrays are indexed once. */
export function subsetPaintScene(scene:CanvasSceneSnapshot,ids?:ReadonlySet<string>):CanvasSceneSnapshot {
 if(!ids)return scene
 let byId=objectIndexes.get(scene.objects)
 if(!byId){byId=new Map(scene.objects.map((object,index)=>[object.id,{object,index}]));objectIndexes.set(scene.objects,byId)}
 let edges=edgeIndexes.get(scene.connections)
 if(!edges){edges=new Map();for(const edge of scene.connections)if(edge.relationshipStyle==='graph-v2'&&edge.sourceId&&edge.targetId){const list=edges.get(edge.sourceId)||[];list.push(edge);edges.set(edge.sourceId,list)}edgeIndexes.set(scene.connections,edges)}
 const found=new Map<string,{object:CanvasSceneObject;index:number}>()
 for(const id of ids){const entry=byId.get(id);if(entry)found.set(id,entry);for(const edge of edges.get(id)||[])if(ids.has(edge.targetId!)){const record=byId.get(edge.id);if(record)found.set(edge.id,record)}}
 return {...scene,objects:[...found.values()].sort((a,b)=>a.index-b.index).map(e=>e.object)}
}

