import { converter, formatHex } from 'culori'
import { useRef, useState } from 'react'
import type { CSSProperties, PointerEvent as ReactPointerEvent, ReactNode } from 'react'
import './ColorPanel.css'

export type ColorTarget = 'fill' | 'stroke' | 'text' | 'columnBody' | 'background' | 'grid'

type ColorPanelProps = {
  contextIdentity: string
  value: string
  opacity: number
  swatches: string[]
  title?: string
  target: ColorTarget
  targets?: ColorTarget[]
  targetLabels?: Partial<Record<ColorTarget, string>>
  contrastBackground?: string
  className?: string
  embedded?: boolean
  controls?: ReactNode
  onTargetChange: (target: ColorTarget) => void
  onChange: (value: string, opacity: number) => void
  onSwatchesChange: (swatches: string[]) => void
  onClose: () => void
}

const toRgb = converter('rgb')
const toHsl = converter('hsl')
const toOklch = converter('oklch')
const FULL_PALETTE = [
  '#17191f', '#3a3f48', '#6f7884', '#dfe3e8', '#fffaf3', '#f4d7c6',
  '#e7a08e', '#c95755', '#8f2f3b', '#f0bb72', '#d68b3d', '#a66e36',
  '#f2df7d', '#c5b44c', '#78985d', '#3f7659', '#65bcb0', '#277b77',
  '#6ca5c5', '#35658c', '#5867a5', '#8d72b0', '#b35f95', '#6e4569',
]

function HexColorInput({ value, opacity, onChange }: Pick<ColorPanelProps, 'value' | 'opacity' | 'onChange'>) {
  const [draft, setDraft] = useState(() => value.toUpperCase())
  const cancelBlur = useRef(false)
  return <input aria-label="Hex color" spellCheck={false} value={draft}
    onChange={(event) => { cancelBlur.current = false; setDraft(event.target.value) }}
    onBlur={() => {
      const next = draft.trim()
      if (!cancelBlur.current && /^#[0-9a-f]{6}$/i.test(next) && next.toLowerCase() !== value.toLowerCase()) onChange(next.toLowerCase(), opacity)
      cancelBlur.current = false
      setDraft(value.toUpperCase())
    }}
    onKeyDown={(event) => {
      if (event.key === 'Enter') { event.preventDefault(); event.stopPropagation(); event.currentTarget.blur() }
      else if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); cancelBlur.current = true; setDraft(value.toUpperCase()) }
    }}
  />
}

export function ColorPanel({ contextIdentity, value, opacity, swatches, title, target, targets = ['fill', 'stroke', 'text'], targetLabels, contrastBackground = '#15171b', className, embedded = false, controls, onTargetChange, onChange, onSwatchesChange, onClose }: ColorPanelProps) {
  const [recentSwatches, setRecentSwatches] = useState<string[]>(() => swatches.slice(0, 8))
  const rgb = toRgb(value) || { mode: 'rgb' as const, r: 0.84, g: 0.64, b: 0.42 }
  const hsl = toHsl(value) || { mode: 'hsl' as const, h: 32, s: 0.52, l: 0.63 }
  const oklch = toOklch(value) || { mode: 'oklch' as const, l: 0.74, c: 0.1, h: 60 }
  const hsv = rgbToHsv(rgb.r, rgb.g, rgb.b)
  const contrast = contrastRatio(value, contrastBackground)

  function setColor(color: Parameters<typeof formatHex>[0]) {
    const formatted = formatHex(color)
    if (formatted) {
      onChange(formatted, opacity)
      setRecentSwatches((current) => [formatted, ...current.filter((entry) => entry !== formatted)].slice(0, 8))
    }
  }

  function setHue(event: ReactPointerEvent<HTMLDivElement>) {
    const bounds = event.currentTarget.getBoundingClientRect()
    const angle = Math.atan2(event.clientY - (bounds.top + bounds.height / 2), event.clientX - (bounds.left + bounds.width / 2)) * 180 / Math.PI
    const hue = (angle + 90 + 360) % 360
    setColor(hsvToRgb(hue, hsv.s, hsv.v))
  }

  function setSaturationValue(event: ReactPointerEvent<HTMLDivElement>) {
    const bounds = event.currentTarget.getBoundingClientRect()
    const saturation = clamp((event.clientX - bounds.left) / bounds.width)
    const brightness = clamp(1 - (event.clientY - bounds.top) / bounds.height)
    setColor(hsvToRgb(hsv.h, saturation, brightness))
  }

  return (
    <aside className={`professional-color ${className || ''}`} aria-label="Color controls">
      {!embedded && <header><div><strong>Color</strong>{title && <small>{title}</small>}</div><button type="button" aria-label="Close color controls" onClick={onClose}>×</button></header>}
      {targets.length ? <div className="color-targets" style={{ gridTemplateColumns: `repeat(${targets.length},1fr)` }} role="group" aria-label="Color target">{targets.map((entry) => <button className={target === entry ? 'active' : ''} type="button" key={entry} onClick={() => onTargetChange(entry)}>{targetLabels?.[entry] || entry[0].toUpperCase() + entry.slice(1)}</button>)}</div> : <div className="color-empty-state">Select an object to edit its colors.</div>}
      <fieldset className="color-editor-fields" disabled={!targets.length}>
      {controls}
      <div className="hue-ring" onPointerDown={(event) => { event.currentTarget.setPointerCapture(event.pointerId); setHue(event) }} onPointerMove={(event) => event.buttons === 1 && setHue(event)} style={{ '--hue': hsv.h } as CSSProperties}>
        <div className="sv-field" onPointerDown={(event) => { event.stopPropagation(); event.currentTarget.setPointerCapture(event.pointerId); setSaturationValue(event) }} onPointerMove={(event) => { if (event.buttons === 1) { event.stopPropagation(); setSaturationValue(event) } }}>
          <i style={{ left: `${hsv.s * 100}%`, top: `${(1 - hsv.v) * 100}%` }} />
        </div>
      </div>
      <div className="color-hex-row"><span style={{ background: value }} /><HexColorInput key={JSON.stringify([contextIdentity, target, value, opacity])} value={value} opacity={opacity} onChange={onChange} /><strong>{Math.round(opacity * 100)}%</strong></div>
      <div className="color-values"><label>R<input type="number" min="0" max="255" value={Math.round(rgb.r * 255)} onChange={(event) => setColor({ ...rgb, r: Number(event.target.value) / 255 })} /></label><label>G<input type="number" min="0" max="255" value={Math.round(rgb.g * 255)} onChange={(event) => setColor({ ...rgb, g: Number(event.target.value) / 255 })} /></label><label>B<input type="number" min="0" max="255" value={Math.round(rgb.b * 255)} onChange={(event) => setColor({ ...rgb, b: Number(event.target.value) / 255 })} /></label></div>
      <div className="color-values"><label>H<input type="number" value={Math.round(hsl.h || 0)} onChange={(event) => setColor({ ...hsl, h: Number(event.target.value) })} /></label><label>S<input type="number" value={Math.round((hsl.s || 0) * 100)} onChange={(event) => setColor({ ...hsl, s: Number(event.target.value) / 100 })} /></label><label>L<input type="number" value={Math.round((hsl.l || 0) * 100)} onChange={(event) => setColor({ ...hsl, l: Number(event.target.value) / 100 })} /></label></div>
      <div className="color-values oklch-values"><label>L<input type="number" step=".01" value={(oklch.l || 0).toFixed(2)} onChange={(event) => setColor({ ...oklch, l: Number(event.target.value) })} /></label><label>C<input type="number" step=".01" value={(oklch.c || 0).toFixed(2)} onChange={(event) => setColor({ ...oklch, c: Number(event.target.value) })} /></label><label>H<input type="number" value={Math.round(oklch.h || 0)} onChange={(event) => setColor({ ...oklch, h: Number(event.target.value) })} /></label></div>
      <label className="opacity-control"><span>Opacity</span><input aria-label="Color opacity" type="range" min="0" max="100" value={Math.round(opacity * 100)} onChange={(event) => onChange(value, Number(event.target.value) / 100)} /></label>
      <div className="contrast-readout"><span>Contrast on canvas</span><strong>{contrast.toFixed(2)}:1</strong><em>{contrast >= 4.5 ? 'AA text' : contrast >= 3 ? 'AA large' : 'Decorative only'}</em></div>
      <section className="color-palette" aria-label="Full color palette"><header><strong>Palette</strong><label className="custom-color"><input type="color" aria-label="Custom color" value={value} onChange={(event) => setColor(event.target.value)} /><span>Custom</span></label></header><div className="palette-grid">{FULL_PALETTE.map((color) => <button key={color} type="button" style={{ background: color }} title={color} aria-label={`Use palette color ${color}`} onClick={() => setColor(color)} />)}</div></section>
      {recentSwatches.length > 0 && <section className="swatch-section" aria-label="Recent colors"><header><strong>Recent</strong><small>{recentSwatches.length}</small></header><div className="managed-swatches">{recentSwatches.map((color) => <button key={color} type="button" style={{ background: color }} title={color} aria-label={`Use recent swatch ${color}`} onClick={() => setColor(color)} />)}</div></section>}
      <section className="swatch-section" aria-label="Project swatches"><header><strong>Project</strong><small>{swatches.length}</small></header><div className="managed-swatches">{swatches.map((color) => <button key={color} type="button" style={{ background: color }} title={color} aria-label={`Use project swatch ${color}`} onClick={() => setColor(color)} />)}<button className="add-swatch" type="button" aria-label="Save current swatch" onClick={() => !swatches.includes(value) && onSwatchesChange([...swatches, value])}>＋</button></div></section>
      </fieldset>
    </aside>
  )
}

function clamp(value: number) { return Math.min(1, Math.max(0, value)) }

function rgbToHsv(r: number, g: number, b: number) {
  const max = Math.max(r, g, b), min = Math.min(r, g, b), delta = max - min
  let h = 0
  if (delta) {
    if (max === r) h = 60 * (((g - b) / delta) % 6)
    else if (max === g) h = 60 * ((b - r) / delta + 2)
    else h = 60 * ((r - g) / delta + 4)
  }
  return { h: (h + 360) % 360, s: max ? delta / max : 0, v: max }
}

function hsvToRgb(h: number, s: number, v: number) {
  const c = v * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = v - c
  const [r, g, b] = h < 60 ? [c, x, 0] : h < 120 ? [x, c, 0] : h < 180 ? [0, c, x] : h < 240 ? [0, x, c] : h < 300 ? [x, 0, c] : [c, 0, x]
  return { mode: 'rgb' as const, r: r + m, g: g + m, b: b + m }
}

function contrastRatio(foreground: string, background: string) {
  const luminance = (hex: string) => {
    const color = toRgb(hex) || { r: 0, g: 0, b: 0 }
    const channel = (value: number) => value <= .03928 ? value / 12.92 : ((value + .055) / 1.055) ** 2.4
    return .2126 * channel(color.r) + .7152 * channel(color.g) + .0722 * channel(color.b)
  }
  const a = luminance(foreground), b = luminance(background)
  return (Math.max(a, b) + .05) / (Math.min(a, b) + .05)
}

type Kind = 'pan' | 'zoom'
type Input = { seq: number; at: number; kind: Kind }
export type PaintInput = { seq: number; requestedAt: number }
let nextInputScope = 0
/** Correlates input with the generation actually committed. A smooth rAF loop
 * or an old accepted frame cannot satisfy this measurement. */
export class CanvasInputTracker {
  private readonly inputScope = ++nextInputScope
  private inputs: Input[] = []
  private seq = 0
  private now: () => number
  dropped = 0
  constructor(now = () => performance.now()) { this.now = now }
  mark(kind: Kind) {
    const input = { seq: ++this.seq, at: this.now(), kind }
    this.inputs.push(input)
    if (this.inputs.length > 512) { this.inputs.shift(); this.dropped++ }
    return input.seq
  }
  begin(): PaintInput { return { seq: this.seq, requestedAt: this.now() } }
  commit(request: PaintInput) {
    const end = this.now(), pending = this.inputs.filter(input => input.seq <= request.seq)
    this.inputs = this.inputs.filter(input => input.seq > request.seq)
    if (!pending.length) return undefined
    return { kind: pending.at(-1)!.kind, inputSeq: request.seq, coalesced: pending.length,
      oldestInputMs: end - pending[0].at, latestInputMs: end - pending.at(-1)!.at,
      requestToCommitMs: end - request.requestedAt, pendingInputs: this.inputs.length, dropped: this.dropped,
      // Keep every credited event's kind and age. A mixed pan/zoom batch must
      // not turn all earlier zoom events into the final pan event's latency.
      sampleSchema: 1, inputScope: this.inputScope, inputSamplesJson: JSON.stringify(pending.map(input => ({ seq: input.seq, kind: input.kind, ms: end - input.at }))) }
  }
}

export type DiagnosticRow={t:number;kind:string;data:Record<string,number|string|boolean>;sequence?:number}
type Entry={row:DiagnosticRow;json:string;bytes:number}
type Options={session:string;native:()=>boolean;send:(batch:string)=>Promise<unknown>;now?:()=>number;historyCapacity?:number;transportCapacity?:number;maxBufferedBytes?:number;maxBatchBytes?:number}

/** Local history and native transport are separate bounded owners. In-flight
 * rows cannot be evicted or overtaken by a second drain. Failed rows return to
 * the front, and every actual eviction has a persistent explicit counter. */
export class DiagnosticBuffer{
 private readonly options:Required<Options>
 private readonly encoder=new TextEncoder()
 private history:Entry[]=[]
 private pending:Entry[]=[]
 private active:Entry[]=[]
 private historyBytes=0
 private pendingBytes=0
 private activeBytes=0
 private drain:Promise<boolean>|undefined
 private retryAt=0
 private rowSequence=0
 private batchSequence=0
 private reportedDropped=0
 private reportedHistoryDropped=0
 dropped=0
 historyDropped=0
 transportFailures=0
 constructor(options:Options){
  this.options={now:Date.now,historyCapacity:2000,transportCapacity:2000,maxBufferedBytes:2*1024*1024,maxBatchBytes:256_000,...options}
  if(!Number.isInteger(this.options.maxBatchBytes)||this.options.maxBatchBytes<1024||this.options.maxBatchBytes>256_000||!Number.isInteger(this.options.historyCapacity)||this.options.historyCapacity<1||!Number.isInteger(this.options.transportCapacity)||this.options.transportCapacity<1||!Number.isInteger(this.options.maxBufferedBytes)||this.options.maxBufferedBytes<1024||this.encoder.encode(JSON.stringify(options.session)).length>256)throw new Error('DIAGNOSTIC_BUFFER_INVALID_LIMITS')
 }
 get pendingRows(){return this.pending.length+this.active.length}
 snapshot(){return {rows:this.history.map(entry=>entry.row),dropped:this.dropped,historyDropped:this.historyDropped,pendingRows:this.pendingRows,inFlightRows:this.active.length,transportFailures:this.transportFailures}}
 record(source:DiagnosticRow){
  const row={...source,data:{...source.data},sequence:++this.rowSequence},json=JSON.stringify(row),bytes=this.encoder.encode(json).length
  // App metrics have bounded names/values. Refuse a hostile/accidental giant
  // row explicitly instead of retaining an entry that can never fit a batch.
  if(bytes>Math.min(24_000,this.options.maxBatchBytes-512,this.options.maxBufferedBytes)){
   this.historyDropped++;if(this.options.native())this.dropped++;return
  }
  const entry={row,json,bytes}
  while(this.history.length>=this.options.historyCapacity||this.historyBytes+bytes>this.options.maxBufferedBytes){const old=this.history.shift()!;this.historyBytes-=old.bytes;this.historyDropped++}
  this.history.push(entry);this.historyBytes+=bytes
  if(!this.options.native())return
  while(this.pending.length&&(this.pendingRows>=this.options.transportCapacity||this.pendingBytes+this.activeBytes+bytes>this.options.maxBufferedBytes)){const old=this.pending.shift()!;this.pendingBytes-=old.bytes;this.dropped++}
  if(this.pendingRows>=this.options.transportCapacity||this.pendingBytes+this.activeBytes+bytes>this.options.maxBufferedBytes){this.dropped++;return}
  this.pending.push(entry);this.pendingBytes+=bytes
 }
 flush(force=false):Promise<boolean>{
  if(this.drain)return this.drain
  if(!this.options.native())return Promise.resolve(true)
  if(!force&&this.options.now()<this.retryAt)return Promise.resolve(false)
  // Publish drain ownership before entering user/native transport callbacks.
  const running=Promise.resolve().then(()=>this.flushSerially())
  this.drain=running
  void running.finally(()=>{if(this.drain===running)this.drain=undefined})
  return running
 }
 private async flushSerially():Promise<boolean>{
  drain:while(this.pending.length||this.dropped!==this.reportedDropped||this.historyDropped!==this.reportedHistoryDropped){
   const dropped=this.dropped,historyDropped=this.historyDropped
   const prefix=`{"session":${JSON.stringify(this.options.session)},"batchSequence":${this.batchSequence+1},"dropped":${dropped},"historyDropped":${historyDropped},"rows":[`
   let bytes=this.encoder.encode(prefix).length+2
   const active:Entry[]=[]
   while(this.pending.length){
    const entry=this.pending[0],extra=entry.bytes+(active.length?1:0)
    if(bytes+extra>this.options.maxBatchBytes){
     if(active.length)break
     // Defensive refusal if a future envelope grows beyond the reservation.
     // Do not loop sending empty batches forever around an impossible head row.
     this.pending.shift();this.pendingBytes-=entry.bytes;this.dropped++;continue drain
    }
    this.pending.shift();this.pendingBytes-=entry.bytes;active.push(entry);bytes+=extra
   }
   this.active=active;this.activeBytes=active.reduce((sum,entry)=>sum+entry.bytes,0)
   const batch=prefix+active.map(entry=>entry.json).join(',')+']}'
   try{
    await this.options.send(batch)
    this.batchSequence++;this.reportedDropped=dropped;this.reportedHistoryDropped=historyDropped;this.retryAt=0
    this.active=[];this.activeBytes=0
   }catch{
    // Capacity already includes active rows, so restoring this prefix cannot
    // overflow. New records are never allowed to evict an in-flight authority.
    this.pending=[...active,...this.pending];this.pendingBytes+=this.activeBytes
    this.active=[];this.activeBytes=0;this.transportFailures++;this.retryAt=this.options.now()+1000
    return false
   }
  }
  return true
 }
}

import { requestAppFrame } from '../canvas-engine/appFrameClock'
import { invoke, isTauri } from '@tauri-apps/api/core'
import { CanvasInputTracker } from './canvasInput'
import {DiagnosticBuffer,type DiagnosticRow} from './diagnosticBuffer'
import { preparationWorkerSnapshot } from '../board/preparationWorkers'
const inputTrackers = new WeakMap<Element, CanvasInputTracker>()
export function canvasInputsFor(stage: Element) {
  let tracker = inputTrackers.get(stage)
  if (!tracker) { tracker = new CanvasInputTracker(); inputTrackers.set(stage, tracker) }
  return tracker
}
type Row=DiagnosticRow
const session = crypto.randomUUID()
const environment=()=>({userAgent:navigator.userAgent,dpr:devicePixelRatio,viewport:[innerWidth,innerHeight],visibility:document.visibilityState})
const buffer=new DiagnosticBuffer({session,native:isTauri,maxBatchBytes:252_000,send:batch=>{
  const payload=JSON.stringify({...JSON.parse(batch),schema:1,version:'2.1.0-alpha',at:new Date().toISOString(),environment:environment()})
  if(new TextEncoder().encode(payload).length>256_000)return Promise.reject(new Error('DIAGNOSTIC_BATCH_TOO_LARGE'))
  return invoke('record_performance_batch',{batch:payload})
}})
let installed=false,flushScheduled=false
const allowed = /^[a-z0-9_.:-]{1,80}$/i
const boundedData = (data: Row['data']) => Object.fromEntries(Object.entries(data).filter(([key,value]) => allowed.test(key) && (typeof value==='boolean'||typeof value==='number'&&Number.isFinite(value)||typeof value==='string'&&value.length<=160)).slice(0,32))
type CommittedInputSample = { seq: number; kind: 'pan' | 'zoom'; ms: number }
const inputSampleKeys = new Set(['kind','inputSeq','coalesced','oldestInputMs','latestInputMs','dropped','sampleSchema','inputScope','inputSamplesJson','inputChunkIndex','inputChunks','inputBatchEvents'])

/** Only canonical numeric input evidence receives a longer string allowance.
 * Split at 128 events so the tracker's full 512-event queue fits in at most
 * four bounded rows without changing any credited event, age or identity. */
function inputCommitChunks(data: Row['data']): Row['data'][] | undefined {
  if (data.sampleSchema!==1 || typeof data.inputSamplesJson!=='string' || data.inputSamplesJson.length>64_000 ||
    typeof data.inputScope!=='number' || !Number.isSafeInteger(data.inputScope) || data.inputScope<=0 ||
    typeof data.inputSeq!=='number' || !Number.isSafeInteger(data.inputSeq) || data.inputSeq<=0 ||
    typeof data.coalesced!=='number' || !Number.isInteger(data.coalesced) || data.coalesced<1 || data.coalesced>512 ||
    typeof data.dropped!=='number' || !Number.isSafeInteger(data.dropped) || data.dropped<0) return
  let decoded: unknown
  try { decoded=JSON.parse(data.inputSamplesJson) } catch { return }
  if (!Array.isArray(decoded) || decoded.length!==data.coalesced) return
  const samples: CommittedInputSample[]=[]
  let previous=0
  for (const raw of decoded) {
    if (!raw || typeof raw!=='object' || Array.isArray(raw) || Object.keys(raw).length!==3) return
    const event=raw as Record<string,unknown>
    if (typeof event.seq!=='number' || !Number.isSafeInteger(event.seq) || event.seq<=previous || event.seq>data.inputSeq ||
      (event.kind!=='pan' && event.kind!=='zoom') || typeof event.ms!=='number' || !Number.isFinite(event.ms) || event.ms<0) return
    previous=event.seq
    samples.push({seq:event.seq,kind:event.kind,ms:event.ms})
  }
  // Reject disagreement rather than repairing or lowering recorded latency.
  if (data.kind!==samples.at(-1)!.kind || data.oldestInputMs!==Math.max(...samples.map(event=>event.ms)) || data.latestInputMs!==Math.min(...samples.map(event=>event.ms))) return
  const extras=Object.fromEntries(Object.entries(boundedData(data)).filter(([key])=>!inputSampleKeys.has(key)).slice(0,20))
  const rows: Row['data'][]=[]
  const chunks=Math.ceil(samples.length/128)
  for (let offset=0;offset<samples.length;offset+=128) {
    const chunk=samples.slice(offset,offset+128)
    rows.push({...extras,kind:chunk.at(-1)!.kind,inputSeq:data.inputSeq,coalesced:chunk.length,
      oldestInputMs:Math.max(...chunk.map(event=>event.ms)),latestInputMs:Math.min(...chunk.map(event=>event.ms)),
      dropped:data.dropped,sampleSchema:1,inputScope:data.inputScope,inputSamplesJson:JSON.stringify(chunk),
      inputChunkIndex:rows.length,inputChunks:chunks,inputBatchEvents:samples.length})
  }
  return rows
}

export function recordMetric(kind: string, data: Row['data'] = {}) {
  if (!allowed.test(kind)) return
  const chunks=kind==='input.commit' ? inputCommitChunks(data) : undefined
  const rows=chunks ?? [boundedData(data)]
  // Malformed schema-1 JSON must stay visibly invalid at the evidence parser,
  // even if its string happens to fit the generic 160-character allowance.
  if (kind==='input.commit' && data.sampleSchema===1 && !chunks) delete rows[0].inputSamplesJson
  const t=Math.round(performance.now())
  for (const safe of rows) buffer.record({t,kind,data:safe})
  if(isTauri()&&buffer.pendingRows>=100&&!flushScheduled){flushScheduled=true;queueMicrotask(()=>{flushScheduled=false;void flush()})}
}
export function metricSpan(kind: string, data: Row['data'] = {}) {
  const start = performance.now()
  return () => recordMetric(kind, { ...data, ms: Math.round((performance.now() - start) * 100) / 100 })
}
export function diagnosticsSnapshot() {
  return { schema: 1, version: '2.1.0-alpha', session, at: new Date().toISOString(), ...buffer.snapshot(),
    environment: environment(), preparation: preparationWorkerSnapshot(),
  }
}
async function flush() {
  return buffer.flush()
}
export async function exportDiagnostics() {
  recordMetric('issue.marker')
  const snapshot = diagnosticsSnapshot()
  const text = JSON.stringify(snapshot, null, 2)
  if (isTauri()) {
    // The native JSONL already receives the same rows in bounded batches.
    // Sending the whole snapshot again can exceed its 256000-byte command cap.
    if(!await buffer.flush(true))throw new Error('Diagnostics could not be written; buffered rows are retained for retry')
    window.dispatchEvent(new CustomEvent('ae-diagnostics-saved'))
  } else {
    const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }))
    const link = document.createElement('a'); link.href = url; link.download = 'art-equation-diagnostics.json'; link.click()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }
}
export function installDiagnostics() {
  if (installed) return; installed = true
  recordMetric('session.start')
  // Capture before the App wheel handler schedules its camera generation.
  window.addEventListener('wheel', event => {
    if (!(event.target instanceof Element)) return
    const stage = event.target.closest('.canvas-stage')
    if (stage) canvasInputsFor(stage).mark(event.ctrlKey || event.metaKey ? 'zoom' : 'pan')
  }, { capture: true, passive: true })
  for (const type of ['longtask','event','long-animation-frame'] as const) {
    try {
      const observer = new PerformanceObserver(list => {
        for (const entry of list.getEntries()) {
          if (type === 'event' && entry.duration < 40) continue
          const frame = entry as PerformanceEntry & { blockingDuration?: number; scripts?: { duration: number; forcedStyleAndLayoutDuration: number }[] }
          recordMetric(type, { name: entry.name, ms: Math.round(entry.duration), start: Math.round(entry.startTime),
            blockingMs: Math.round(frame.blockingDuration || 0), forcedLayoutMs: Math.round(frame.scripts?.reduce((total,script) => total + script.forcedStyleAndLayoutDuration,0) || 0) })
        }
      })
      observer.observe(type === 'event' ? { type, buffered: true, durationThreshold: 40 } as PerformanceObserverInit : { type, buffered: true })
    } catch { recordMetric('observer.unavailable', { type }) }
  }
  let lastSample = 0
  const sample = () => {
    if (document.hidden || performance.now() - lastSample < 4000) return
    lastSample = performance.now()
    const gaps: number[] = []; let before = performance.now(), start = before
    const frame = (now: number) => {
      gaps.push(now - before); before = now
      if (document.hidden) return
      if (now - start < 800 && gaps.length < 120) requestAppFrame(frame)
      else {
        gaps.sort((a,b) => a-b)
        const stage = document.querySelector<HTMLElement>('.canvas-stage')
        const host = document.querySelector<HTMLElement>('.vello-board')
        recordMetric('frame.sample', { p95: Math.round(gaps[Math.floor(gaps.length*.95)] || 0), max: Math.round(gaps.at(-1)||0),
          samples: gaps.length, dom: document.getElementsByTagName('*').length, total: Number(stage?.dataset.totalNodes||0),
          visible: Number(stage?.dataset.visibleNodes||0), backend: host?.dataset.renderer||'unavailable',
          pending: host?.dataset.pending==='true', commits: Number(stage?.dataset.reactCommits||0) })
      }
    }; requestAppFrame(frame)
  }
  setInterval(sample, 5000); setInterval(() => { void flush() }, 1000)
  document.addEventListener('visibilitychange', () => { recordMetric('visibility', { hidden: document.hidden }); void flush() })
  window.addEventListener('error', () => recordMetric('error.window'))
  window.addEventListener('unhandledrejection', () => recordMetric('error.promise'))
  window.addEventListener('keydown', event => { if (event.ctrlKey && event.shiftKey && event.code==='KeyD') { event.preventDefault(); void exportDiagnostics() } })
  Object.assign(window, { __AE_DIAGNOSTICS__: { snapshot: diagnosticsSnapshot, mark: () => recordMetric('issue.marker'), export: exportDiagnostics } })
}

/* Retained document ownership wrappers keep the existing pane layout. */
.workbench > .retained-document-session { display: contents; }
.workbench > .retained-document-session[hidden] { display: none !important; }
.studio-shell .compact-split > .retained-document-session > .document-pane {
  grid-column: 1;
  grid-row: 2;
  width: 100%;
  height: 100%;
}

/* Explicit, temporary Focus writing composition. Preferences and Canvas stay retained. */
@media screen {
  .studio-shell.document-focus-shell { grid-template-rows: 44px minmax(0, 1fr); }
  .document-focus-shell > .app-bar,
  .document-focus-shell > .status-bar,
  .document-focus-shell > .app-body > .navigator,
  .document-focus-shell > .app-body > .project-inspector,
  .document-focus-shell > .app-body > .panel-edge,
  .document-focus-shell > .app-body > .panel-edge-tab,
  .document-focus-shell .project-center > .board-navigation,
  .document-focus-shell .project-center > .project-board-strip,
  .document-focus-shell .project-center > .project-board-strip-restore,
  .document-focus-shell .workbench > .canvas-pane,
  .document-focus-shell .workbench > .split-divider,
  .document-focus-shell .workbench > .compact-split-tabs { display: none !important; }
  .studio-shell.document-focus-shell > .app-body { grid-template-columns: minmax(0, 1fr) !important; grid-row: 2; }
  .studio-shell.document-focus-shell > .app-body > .project-center {
    grid-column: 1 !important; grid-template-rows: minmax(0, 1fr) !important;
  }
  .document-focus-shell .workbench { display: flex !important; }
  .document-focus-shell .workbench > .retained-document-session:not([hidden]) > .document-pane {
    width: 100% !important; flex: 1; min-width: 0; min-height: 0;
  }
}
.document-focus-bar {
  grid-row: 1; display: flex; align-items: center; gap: 12px; min-width: 0;
  padding: 4px 12px; background: var(--surface-appbar); border-bottom: 1px solid var(--line);
}
.document-focus-title { min-width: 0; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text); font-size: 13px; }
.document-focus-readonly { color: var(--muted); font-size: 11px; }
.document-focus-bar > button { flex: none; white-space: nowrap; min-height: 34px; }
.document-focus-bar > button:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 1px; }
@media (max-width: 480px) { .document-focus-bar { gap: 8px; padding-inline: 8px; } .document-focus-bar > button { padding-inline: 8px; } }
@media print { .document-focus-bar { display: none !important; } }

/**
 * Advance Document Continuous Semantic Tree Pagination & Layout Solver
 * Implements ART_EQUATION_DOCUMENT_ADVANCE_SCOPE (§§2-5) & ARGON_INSTRUCTION_DIRECTIVE.md (§2.2-2.3)
 *
 * Core Architectural Law:
 * - Pages and Flow are dynamic projections of a single continuous authored ProseMirror/Tiptap tree.
 * - Never persist `document.pages[]` in document schemas.
 * - Overflow pagination is derived via constraint solving; explicit breaks (PageBreak, BlankPage,
 *   SectionBreakContinuous, SectionBreakNextPage) represent authored user intent.
 */

import type { JSONContent } from '@tiptap/react'
import type { DocumentLayout } from '../model/project'

export type AuthoredBreakKind =
  | 'pageBreak'
  | 'blankPage'
  | 'sectionBreakContinuous'
  | 'sectionBreakNextPage'

export type MediaPlacementMode = 'inline' | 'block' | 'anchored' | 'left' | 'right'

export interface DocPosition {
  blockIndex: number
  lineOffset: number
  utf8Offset: number
}

export interface FragmentRef {
  blockIndex: number
  nodeType: string
  nodeId: string
  startLine: number
  endLine: number
  heightPx: number
  isAuthoredBreak?: boolean
  breakKind?: AuthoredBreakKind
  intrinsicReserved?: boolean
}

export interface PageSlice {
  pageIndex: number
  pageNumber: number
  sectionId: string
  sectionIndex: number
  sourceStart: DocPosition
  sourceEnd: DocPosition
  fragments: FragmentRef[]
  contentHeightPx: number
  availableHeightPx: number
  utilization: number
  isBlankPage: boolean
  hasExplicitBreak: boolean
  explicitBreakKind?: AuthoredBreakKind
  columns: 1 | 2
}

export interface PaginationCheckpoint {
  pageIndex: number
  sectionIndex: number
  blockIndex: number
  accumulatedWords: number
  contentHash: string
}

export interface OverflowDiagnostic {
  pageIndex: number
  blockIndex: number
  nodeType: string
  severity: 'warning' | 'info'
  message: string
}

export interface DocumentBlockCounts {
  paragraphs: number
  headings: number
  lists: number
  images: number
  videos: number
  models3d: number
  pdfEmbeds: number
  tables: number
  footnotes: number
  pageBreaks: number
  blankPages: number
  sectionBreaks: number
}

export interface PaginationResult {
  revision: number
  pageWidthPx: number
  pageHeightPx: number
  marginPx: number
  contentWidthPx: number
  contentHeightPx: number
  columns: 1 | 2
  pages: PageSlice[]
  checkpoints: PaginationCheckpoint[]
  overflow: OverflowDiagnostic[]
  counts: DocumentBlockCounts
  wordCount: number
  characterCount: number
  estimatedReadMinutes: number
}

/**
 * Explicit Unicode & UTF-8/UTF-16/Grapheme Index Map per paragraph (Advance Document Scope §3).
 * Prevents caret/selection bugs across emoji sequences, CJK, RTL, and combining marks.
 */
export interface TextIndexMap {
  text: string
  utf8ByteLength: number
  utf16CodeUnitLength: number
  scalarCount: number
  graphemeBoundariesUtf16: number[]
  wordCount: number
  containsRtl: boolean
  containsCjk: boolean
}

const RTL_REGEX = /[\u0591-\u07FF\uFB1D-\uFDFD\uFE70-\uFEFC]/
const CJK_REGEX = /[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff\uff66-\uff9f\uac00-\ud7af]/

export function createTextIndexMap(text: string): TextIndexMap {
  const encoder = new TextEncoder()
  const utf8ByteLength = encoder.encode(text).byteLength
  const utf16CodeUnitLength = text.length
  let scalarCount = 0
  for (const _ of text) scalarCount += 1

  const graphemeBoundariesUtf16: number[] = [0]
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' })
    for (const seg of segmenter.segment(text)) {
      if (seg.index > 0) graphemeBoundariesUtf16.push(seg.index)
    }
  } else {
    let idx = 0
    for (const ch of text) {
      idx += ch.length
      if (idx < text.length) graphemeBoundariesUtf16.push(idx)
    }
  }
  if (graphemeBoundariesUtf16[graphemeBoundariesUtf16.length - 1] !== text.length && text.length > 0) {
    graphemeBoundariesUtf16.push(text.length)
  }

  const trimmed = text.trim()
  const cjkMatches = trimmed.match(new RegExp(CJK_REGEX.source, 'g'))
  const nonCjkText = trimmed.replace(new RegExp(CJK_REGEX.source, 'g'), ' ').trim()
  const latinWords = nonCjkText ? nonCjkText.split(/\s+/).length : 0
  const wordCount = latinWords + (cjkMatches ? cjkMatches.length : 0)

  return {
    text,
    utf8ByteLength,
    utf16CodeUnitLength,
    scalarCount,
    graphemeBoundariesUtf16,
    wordCount,
    containsRtl: RTL_REGEX.test(text),
    containsCjk: CJK_REGEX.test(text),
  }
}

export function resolvePageGeometry(layout: DocumentLayout) {
  const baseDimensions =
    layout.pageSize === 'a4'
      ? [794, 1123]
      : layout.pageSize === 'screen'
        ? [920, 1080]
        : [816, 1056] // US Letter default
  const [portraitWidth, portraitHeight] = baseDimensions
  const pageWidthPx = layout.orientation === 'landscape' ? portraitHeight : portraitWidth
  const pageHeightPx = layout.orientation === 'landscape' ? portraitWidth : portraitHeight
  const marginPx = layout.margins === 'compact' ? 42 : layout.margins === 'wide' ? 92 : 68
  // Running header (52px top band) and running footer (38px bottom band)
  const headerFooterReservePx = 166
  const contentHeightPx = Math.max(240, pageHeightPx - headerFooterReservePx)
  const contentWidthPx = Math.max(200, pageWidthPx - 2 * marginPx)
  const columns: 1 | 2 = layout.columns === 2 ? 2 : 1
  const columnGutterPx = columns === 2 ? 42 : 0
  const columnWidthPx = columns === 2 ? Math.max(120, (contentWidthPx - columnGutterPx) / 2) : contentWidthPx

  return {
    pageWidthPx,
    pageHeightPx,
    marginPx,
    contentWidthPx,
    contentHeightPx,
    columns,
    columnWidthPx,
    columnGutterPx,
  }
}

function extractNodeText(node: JSONContent): string {
  if (typeof node.text === 'string') return node.text
  if (!Array.isArray(node.content)) return ''
  return node.content.map(extractNodeText).join('')
}

function hashBlock(node: JSONContent, index: number): string {
  const type = node.type || 'unknown'
  const text = extractNodeText(node)
  const attrs = node.attrs ? JSON.stringify(node.attrs) : ''
  return `${index}:${type}:${text.length}:${attrs}`
}

interface MeasuredBlock {
  blockIndex: number
  nodeType: string
  nodeId: string
  heightPx: number
  lineCount: number
  lineHeightPx: number
  keepWithNext: boolean
  keepTogether: boolean
  isAuthoredBreak: boolean
  breakKind?: AuthoredBreakKind
  intrinsicReserved: boolean
  wordCount: number
  charCount: number
  utf8Bytes: number
  hash: string
}

function measureBlock(
  node: JSONContent,
  blockIndex: number,
  columnWidthPx: number
): MeasuredBlock {
  const type = node.type || 'paragraph'
  const nodeId = String(node.attrs?.id || `block-${blockIndex}`)
  const text = extractNodeText(node)
  const textMap = createTextIndexMap(text)
  const hash = hashBlock(node, blockIndex)

  // Authored Break Intent
  if (
    type === 'pageBreak' ||
    type === 'blankPage' ||
    type === 'sectionBreakContinuous' ||
    type === 'sectionBreakNextPage'
  ) {
    return {
      blockIndex,
      nodeType: type,
      nodeId,
      heightPx: 0,
      lineCount: 0,
      lineHeightPx: 0,
      keepWithNext: false,
      keepTogether: true,
      isAuthoredBreak: true,
      breakKind: type as AuthoredBreakKind,
      intrinsicReserved: false,
      wordCount: 0,
      charCount: 0,
      utf8Bytes: 0,
      hash,
    }
  }

  // Multimodal Media Blocks with Intrinsic Box Reservation (Advance Document Scope §4 "Media stability rule")
  if (type === 'image' || type === 'videoBlock' || type === 'model3DBlock' || type === 'pdfEmbedBlock') {
    const placement = String(node.attrs?.placement || 'block') as MediaPlacementMode
    const intrinsicW = Number(node.attrs?.width) || (type === 'model3DBlock' ? 640 : type === 'pdfEmbedBlock' ? 612 : 640)
    const intrinsicH = Number(node.attrs?.height) || (type === 'model3DBlock' ? 380 : type === 'pdfEmbedBlock' ? 792 : 360)
    const ratio = intrinsicH / Math.max(1, intrinsicW)
    const effectiveWidth =
      placement === 'inline'
        ? Math.min(180, columnWidthPx * 0.45)
        : placement === 'left' || placement === 'right'
          ? columnWidthPx * 0.48
          : Math.min(columnWidthPx, intrinsicW)
    const mediaBoxHeight = Math.round(
      Math.max(110, Math.min(520, effectiveWidth * ratio)) + (node.attrs?.caption ? 28 : 12)
    )
    return {
      blockIndex,
      nodeType: type,
      nodeId,
      heightPx: mediaBoxHeight,
      lineCount: 1,
      lineHeightPx: mediaBoxHeight,
      keepWithNext: false,
      keepTogether: true,
      isAuthoredBreak: false,
      intrinsicReserved: true,
      wordCount: textMap.wordCount,
      charCount: textMap.scalarCount,
      utf8Bytes: textMap.utf8ByteLength,
      hash,
    }
  }

  // Table block with row-level split policy (Advance Document Scope §22)
  if (type === 'table') {
    const rows = Array.isArray(node.content) ? node.content.length : 3
    const rowHeightPx = 38
    const totalHeight = rows * rowHeightPx + 20
    return {
      blockIndex,
      nodeType: type,
      nodeId,
      heightPx: totalHeight,
      lineCount: Math.max(1, rows),
      lineHeightPx: rowHeightPx,
      keepWithNext: false,
      keepTogether: rows <= 4,
      isAuthoredBreak: false,
      intrinsicReserved: false,
      wordCount: textMap.wordCount,
      charCount: textMap.scalarCount,
      utf8Bytes: textMap.utf8ByteLength,
      hash,
    }
  }

  // Footnote block
  if (type === 'footnote') {
    const footnoteText = String(node.attrs?.text || text)
    const fnMap = createTextIndexMap(footnoteText)
    const charsPerLine = Math.max(24, Math.floor(columnWidthPx / 7.2))
    const lines = Math.max(1, Math.ceil(Math.max(1, fnMap.scalarCount) / charsPerLine))
    const lineHeightPx = 19
    return {
      blockIndex,
      nodeType: type,
      nodeId,
      heightPx: lines * lineHeightPx + 10,
      lineCount: lines,
      lineHeightPx,
      keepWithNext: false,
      keepTogether: true,
      isAuthoredBreak: false,
      intrinsicReserved: false,
      wordCount: fnMap.wordCount,
      charCount: fnMap.scalarCount,
      utf8Bytes: fnMap.utf8ByteLength,
      hash,
    }
  }

  // Headings (keepWithNext = true, keepTogether = true)
  if (type === 'heading') {
    const level = Number(node.attrs?.level) || 2
    const fontSizePx = level === 1 ? 34 : level === 2 ? 24 : 18
    const lineHeightPx = Math.round(fontSizePx * 1.22)
    const avgCharWidth = fontSizePx * 0.54
    const charsPerLine = Math.max(12, Math.floor(columnWidthPx / avgCharWidth))
    const lines = Math.max(1, Math.ceil(Math.max(1, textMap.scalarCount) / charsPerLine))
    const marginVertical = level === 1 ? 28 : level === 2 ? 22 : 16
    return {
      blockIndex,
      nodeType: type,
      nodeId,
      heightPx: lines * lineHeightPx + marginVertical,
      lineCount: lines,
      lineHeightPx,
      keepWithNext: true,
      keepTogether: true,
      isAuthoredBreak: false,
      intrinsicReserved: false,
      wordCount: textMap.wordCount,
      charCount: textMap.scalarCount,
      utf8Bytes: textMap.utf8ByteLength,
      hash,
    }
  }

  // Lists & Blockquotes & Paragraphs
  const fontSizePx = 15
  const lineHeightPx = 25
  const avgCharWidth = textMap.containsCjk ? fontSizePx * 0.95 : fontSizePx * 0.52
  const effectiveColumnWidth = type === 'blockquote' || type === 'bulletList' || type === 'orderedList'
    ? Math.max(120, columnWidthPx - 32)
    : columnWidthPx
  const charsPerLine = Math.max(18, Math.floor(effectiveColumnWidth / avgCharWidth))

  let lines = 1
  if (type === 'bulletList' || type === 'orderedList') {
    const items = Array.isArray(node.content) ? node.content : []
    lines = items.reduce((acc, item) => {
      const itemLen = extractNodeText(item).length
      return acc + Math.max(1, Math.ceil(Math.max(1, itemLen) / charsPerLine))
    }, 0)
    lines = Math.max(1, lines)
  } else {
    lines = Math.max(1, Math.ceil(Math.max(1, textMap.scalarCount) / charsPerLine))
  }

  const blockMargin = type === 'blockquote' ? 24 : 12
  return {
    blockIndex,
    nodeType: type,
    nodeId,
    heightPx: lines * lineHeightPx + blockMargin,
    lineCount: lines,
    lineHeightPx,
    keepWithNext: false,
    keepTogether: type === 'blockquote' && lines <= 4,
    isAuthoredBreak: false,
    intrinsicReserved: false,
    wordCount: textMap.wordCount,
    charCount: textMap.scalarCount,
    utf8Bytes: textMap.utf8ByteLength,
    hash,
  }
}

/**
 * Constraint-solving pagination pass with widow/orphan control, keep-with-next,
 * intrinsic media reservation, and explicit break intent.
 */
export function solveDocumentPagination(
  content: JSONContent,
  layout: DocumentLayout,
  revision = 1
): PaginationResult {
  const geom = resolvePageGeometry(layout)
  const blocks = Array.isArray(content?.content) ? content.content : []

  const counts: DocumentBlockCounts = {
    paragraphs: 0,
    headings: 0,
    lists: 0,
    images: 0,
    videos: 0,
    models3d: 0,
    pdfEmbeds: 0,
    tables: 0,
    footnotes: 0,
    pageBreaks: 0,
    blankPages: 0,
    sectionBreaks: 0,
  }

  const measured: MeasuredBlock[] = blocks.map((node, index) => {
    const t = node.type || 'paragraph'
    if (t === 'paragraph') counts.paragraphs += 1
    else if (t === 'heading') counts.headings += 1
    else if (t === 'bulletList' || t === 'orderedList') counts.lists += 1
    else if (t === 'image') counts.images += 1
    else if (t === 'videoBlock') counts.videos += 1
    else if (t === 'model3DBlock') counts.models3d += 1
    else if (t === 'pdfEmbedBlock') counts.pdfEmbeds += 1
    else if (t === 'table') counts.tables += 1
    else if (t === 'footnote') counts.footnotes += 1
    else if (t === 'pageBreak') counts.pageBreaks += 1
    else if (t === 'blankPage') counts.blankPages += 1
    else if (t === 'sectionBreakContinuous' || t === 'sectionBreakNextPage') counts.sectionBreaks += 1

    return measureBlock(node, index, geom.columnWidthPx)
  })

  // Total available vertical column height per page sheet
  const pageCapacityPx = geom.contentHeightPx * geom.columns
  const pages: PageSlice[] = []
  const checkpoints: PaginationCheckpoint[] = []
  const overflow: OverflowDiagnostic[] = []

  let sectionIndex = 0
  let currentFragments: FragmentRef[] = []
  let currentHeightPx = 0
  let currentStart: DocPosition = { blockIndex: 0, lineOffset: 0, utf8Offset: 0 }
  let runningUtf8 = 0
  let totalWords = 0
  let totalChars = 0

  const flushPage = (
    endPos: DocPosition,
    opts?: { isBlankPage?: boolean; hasExplicitBreak?: boolean; explicitBreakKind?: AuthoredBreakKind }
  ) => {
    const pageIndex = pages.length
    const slice: PageSlice = {
      pageIndex,
      pageNumber: pageIndex + 1,
      sectionId: `sec-${sectionIndex + 1}`,
      sectionIndex,
      sourceStart: { ...currentStart },
      sourceEnd: { ...endPos },
      fragments: currentFragments,
      contentHeightPx: Math.round(currentHeightPx),
      availableHeightPx: pageCapacityPx,
      utilization: Math.min(1, Number((currentHeightPx / Math.max(1, pageCapacityPx)).toFixed(3))),
      isBlankPage: Boolean(opts?.isBlankPage),
      hasExplicitBreak: Boolean(opts?.hasExplicitBreak),
      explicitBreakKind: opts?.explicitBreakKind,
      columns: geom.columns,
    }
    pages.push(slice)
    checkpoints.push({
      pageIndex,
      sectionIndex,
      blockIndex: currentStart.blockIndex,
      accumulatedWords: totalWords,
      contentHash: currentFragments.map((f) => `${f.blockIndex}:${f.startLine}-${f.endLine}`).join('|'),
    })
    currentFragments = []
    currentHeightPx = 0
    currentStart = { ...endPos }
  }

  for (let i = 0; i < measured.length; i += 1) {
    const blk = measured[i]
    totalWords += blk.wordCount
    totalChars += blk.charCount

    // Handle explicit authored breaks
    if (blk.isAuthoredBreak && blk.breakKind) {
      currentFragments.push({
        blockIndex: blk.blockIndex,
        nodeType: blk.nodeType,
        nodeId: blk.nodeId,
        startLine: 0,
        endLine: 0,
        heightPx: 0,
        isAuthoredBreak: true,
        breakKind: blk.breakKind,
      })
      const nextPos: DocPosition = {
        blockIndex: i + 1,
        lineOffset: 0,
        utf8Offset: runningUtf8,
      }
      if (blk.breakKind === 'sectionBreakContinuous') {
        sectionIndex += 1
        continue
      }
      if (blk.breakKind === 'sectionBreakNextPage') {
        flushPage(nextPos, { hasExplicitBreak: true, explicitBreakKind: 'sectionBreakNextPage' })
        sectionIndex += 1
        continue
      }
      if (blk.breakKind === 'pageBreak') {
        flushPage(nextPos, { hasExplicitBreak: true, explicitBreakKind: 'pageBreak' })
        continue
      }
      if (blk.breakKind === 'blankPage') {
        if (currentFragments.length > 1 || currentHeightPx > 0) {
          flushPage(nextPos, { hasExplicitBreak: true, explicitBreakKind: 'pageBreak' })
        }
        flushPage(nextPos, {
          isBlankPage: true,
          hasExplicitBreak: true,
          explicitBreakKind: 'blankPage',
        })
        continue
      }
    }

    // Check oversized indivisible block diagnostic (Advance Document Scope §22)
    if (blk.keepTogether && blk.heightPx > pageCapacityPx) {
      overflow.push({
        pageIndex: pages.length,
        blockIndex: blk.blockIndex,
        nodeType: blk.nodeType,
        severity: 'warning',
        message: `Block #${blk.blockIndex + 1} (${blk.nodeType}, ${blk.heightPx}px) exceeds single-page capacity (${pageCapacityPx}px).`,
      })
    }

    // Keep-with-next constraint: if this is a heading and the next block's first 2 lines won't fit
    const nextBlk = measured[i + 1]
    const keepWithNextReserve =
      blk.keepWithNext && nextBlk && !nextBlk.isAuthoredBreak
        ? Math.min(nextBlk.heightPx, Math.max(nextBlk.lineHeightPx * 2, 44))
        : 0

    if (
      currentHeightPx > 0 &&
      currentHeightPx + blk.heightPx + keepWithNextReserve > pageCapacityPx
    ) {
      // Can we split lines across pages (with widow/orphan >= 2 lines)?
      const remainingPx = pageCapacityPx - currentHeightPx
      const fitLines =
        !blk.keepTogether && blk.lineHeightPx > 0
          ? Math.floor(remainingPx / blk.lineHeightPx)
          : 0

      if (!blk.keepTogether && blk.lineCount >= 4 && fitLines >= 2 && blk.lineCount - fitLines >= 2) {
        const firstPartPx = fitLines * blk.lineHeightPx
        currentFragments.push({
          blockIndex: blk.blockIndex,
          nodeType: blk.nodeType,
          nodeId: blk.nodeId,
          startLine: 0,
          endLine: fitLines,
          heightPx: firstPartPx,
          intrinsicReserved: blk.intrinsicReserved,
        })
        currentHeightPx += firstPartPx
        const midPos: DocPosition = {
          blockIndex: blk.blockIndex,
          lineOffset: fitLines,
          utf8Offset: runningUtf8 + Math.round((blk.utf8Bytes * fitLines) / blk.lineCount),
        }
        flushPage(midPos)
        const restPx = blk.heightPx - firstPartPx
        currentFragments.push({
          blockIndex: blk.blockIndex,
          nodeType: blk.nodeType,
          nodeId: blk.nodeId,
          startLine: fitLines,
          endLine: blk.lineCount,
          heightPx: restPx,
          intrinsicReserved: blk.intrinsicReserved,
        })
        currentHeightPx += restPx
      } else {
        // Move entire block to the next page
        flushPage({ blockIndex: blk.blockIndex, lineOffset: 0, utf8Offset: runningUtf8 })
        currentFragments.push({
          blockIndex: blk.blockIndex,
          nodeType: blk.nodeType,
          nodeId: blk.nodeId,
          startLine: 0,
          endLine: blk.lineCount,
          heightPx: blk.heightPx,
          intrinsicReserved: blk.intrinsicReserved,
        })
        currentHeightPx += blk.heightPx
      }
    } else {
      currentFragments.push({
        blockIndex: blk.blockIndex,
        nodeType: blk.nodeType,
        nodeId: blk.nodeId,
        startLine: 0,
        endLine: blk.lineCount,
        heightPx: blk.heightPx,
        intrinsicReserved: blk.intrinsicReserved,
      })
      currentHeightPx += blk.heightPx
    }

    runningUtf8 += blk.utf8Bytes
  }

  if (currentFragments.length > 0 || pages.length === 0) {
    flushPage({
      blockIndex: measured.length,
      lineOffset: 0,
      utf8Offset: runningUtf8,
    })
  }

  return {
    revision,
    pageWidthPx: geom.pageWidthPx,
    pageHeightPx: geom.pageHeightPx,
    marginPx: geom.marginPx,
    contentWidthPx: geom.contentWidthPx,
    contentHeightPx: geom.contentHeightPx,
    columns: geom.columns,
    pages,
    checkpoints,
    overflow,
    counts,
    wordCount: totalWords,
    characterCount: totalChars,
    estimatedReadMinutes: Math.max(1, Math.ceil(totalWords / 220)),
  }
}

/* ==========================================================================
   Art Equation Studio - Rich Process Document Styling
   Workstream F / PRC-01 to PRC-11
   ========================================================================== */

.process-document-container {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at 50% 0%, #0d1527 0%, #090d16 100%);
  color: #f1f5f9;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
