}

.gemini-bug-desc {
  font-size: 0.8rem;
  color: var(--text-muted);
  line-height: 1.4;
  white-space: pre-wrap;
}

.gemini-bug-fix {
  font-size: 0.78rem;
  color: var(--teal, #38bdf8);
  background: rgba(56, 189, 248, 0.08);
  padding: 4px 6px;
  border-radius: 4px;
}

.gemini-bug-actions {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}

.gemini-bug-actions button {
  font-size: 0.72rem;
  padding: 2px 8px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
}

/* Feedback Stream */
.gemini-feedback-feed {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 180px;
  overflow-y: auto;
  padding-right: 4px;
}

.gemini-feedback-item {
  padding: 6px 8px;
  border-radius: 5px;
  border-left: 3px solid var(--teal, #38bdf8);
  background: var(--surface-control);
  font-size: 0.8rem;
  line-height: 1.35;
  color: var(--text);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.gemini-feedback-item.warning {
  border-left-color: #f59e0b;
}

.gemini-feedback-item.error {
  border-left-color: #ef4444;
}

.gemini-feedback-item.success {
  border-left-color: #10b981;
}

.gemini-feedback-meta {
  display: flex;
  justify-content: space-between;
  font-size: 0.68rem;
  color: var(--text-muted);
}

.gemini-empty-hint {
  padding: 12px;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.82rem;
  background: var(--surface-control);
  border: 1px dashed var(--line);
  border-radius: 6px;
}

import React, { useState, useEffect } from 'react'
import { geminiStore } from './geminiStore.ts'
import './geminiBridge.css'

export function useGeminiStore() {
  const [, setTick] = useState(0)

  useEffect(() => {
    return geminiStore.subscribe(() => {
      setTick(t => t + 1)
    })
  }, [])

  return {
    bugs: geminiStore.getBugs(),
    feedback: geminiStore.getFeedbackLog(),
    status: geminiStore.getStatus(),
    trackBug: geminiStore.trackBug.bind(geminiStore),
    updateBugStatus: geminiStore.updateBugStatus.bind(geminiStore),
    clearResolvedBugs: geminiStore.clearResolvedBugs.bind(geminiStore),
    addFeedback: geminiStore.addFeedback.bind(geminiStore),
    clearFeedback: geminiStore.clearFeedback.bind(geminiStore),
  }
}

interface GeminiBridgePanelProps {
  activeBoardId?: string
  onInjectNote?: (boardId: string, title: string, content: string) => void
  onExportProjectSnapshot?: () => void
}

export const GeminiBridgePanel: React.FC<GeminiBridgePanelProps> = ({
  activeBoardId,
  onInjectNote,
  onExportProjectSnapshot,
}) => {
  const store = useGeminiStore()
  const [newTitle, setNewTitle] = useState('')
  const [newDesc, setNewDesc] = useState('')
  const [newSeverity, setNewSeverity] = useState<'low' | 'medium' | 'high' | 'critical'>('medium')
  const [newComponent, setNewComponent] = useState('canvas')
  const [showAddForm, setShowAddForm] = useState(false)
  const [copiedStatus, setCopiedStatus] = useState(false)

  const openBugs = store.bugs.filter(b => b.status === 'open')
  const investigatingBugs = store.bugs.filter(b => b.status === 'investigating')
  const resolvedBugs = store.bugs.filter(b => b.status === 'resolved')

  const handleAddBug = (e: React.FormEvent) => {
    e.preventDefault()
    if (!newTitle.trim()) return

    store.trackBug({
      title: newTitle.trim(),
      description: newDesc.trim(),
      component: newComponent,
      severity: newSeverity,
      reproductionSteps: [],
      status: 'open'
    })

    setNewTitle('')
    setNewDesc('')
    setShowAddForm(false)
  }

  const handleExportMarkdown = () => {
    const lines = [
      '# Art Equation - Tracked Bugs Report',
      `Generated: ${new Date().toISOString()}`,
      `Total Issues: ${store.bugs.length} (Open: ${openBugs.length}, Investigating: ${investigatingBugs.length}, Resolved: ${resolvedBugs.length})`,
      '',
      ...store.bugs.map(b => {
        return `### [${b.severity.toUpperCase()}] ${b.title} (${b.component})\n- **Status:** ${b.status}\n- **ID:** ${b.id}\n- **Description:** ${b.description || 'None'}\n${b.suggestedFix ? `- **Suggested Fix:** ${b.suggestedFix}\n` : ''}`
      })
    ]
    const text = lines.join('\n')
    navigator.clipboard.writeText(text).then(() => {
      setCopiedStatus(true)
      setTimeout(() => setCopiedStatus(false), 2000)
    }).catch(() => {})
  }

  const handleQuickInject = () => {
    if (onInjectNote && activeBoardId) {
      onInjectNote(
        activeBoardId,
        'Gemini Live Note',
        `Generated at ${new Date().toLocaleTimeString()}\nConnected via MCP Live Bridge.`
      )
      store.addFeedback({
        message: `Injected sample card onto active board [${activeBoardId}]`,
        level: 'success'
      })
    } else {
      store.addFeedback({
        message: 'No active board selected to inject data.',
        level: 'warning'
      })
    }
  }

  return (
    <div className="gemini-bridge-panel" aria-label="Gemini Live MCP Bridge">
      <header>
        <h2>Gemini Live MCP & Issue Tracker</h2>
        <small>
          Bidirectional integration bridge connecting Google Gemini and MCP tools directly to the Art Equation engine.
          Supports live model inspection, real-time feedback logging, and issue tracking across all levels.
        </small>
      </header>

      {/* Stats Summary */}
      <div className="gemini-stats-grid">
        <div className="gemini-stat-box">
          <span>Bridge Status</span>
          <strong style={{ color: '#86efac' }}>Active</strong>
        </div>
        <div className="gemini-stat-box">
          <span>Open Bugs</span>
          <strong style={{ color: openBugs.length ? '#fca5a5' : 'inherit' }}>{openBugs.length}</strong>
        </div>
        <div className="gemini-stat-box">
          <span>Investigating</span>
          <strong style={{ color: '#fde047' }}>{investigatingBugs.length}</strong>
        </div>
        <div className="gemini-stat-box">
          <span>Resolved</span>
          <strong style={{ color: '#86efac' }}>{resolvedBugs.length}</strong>
        </div>
      </div>

      {/* Control Actions */}
      <div className="gemini-actions-row">
        <button type="button" onClick={() => setShowAddForm(!showAddForm)}>
          {showAddForm ? 'Cancel Add' : '+ Log Issue'}
        </button>
        <button type="button" onClick={handleQuickInject}>
          Inject Live Canvas Card
        </button>
        <button type="button" onClick={handleExportMarkdown}>
          {copiedStatus ? 'Copied Report!' : 'Export Bug Report'}
        </button>
        {resolvedBugs.length > 0 && (
          <button type="button" onClick={() => store.clearResolvedBugs()}>
            Clear Resolved
          </button>
        )}
        {onExportProjectSnapshot && (
          <button type="button" onClick={onExportProjectSnapshot}>
            Capture Diagnostics Snapshot
          </button>
        )}
      </div>

      {/* Quick Add Form */}
      {showAddForm && (
        <form className="gemini-bug-card" onSubmit={handleAddBug} style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          <strong style={{ fontSize: '0.85rem' }}>Track New Issue</strong>
          <input
            type="text"
            placeholder="Issue summary / title"
            value={newTitle}
            onChange={e => setNewTitle(e.target.value)}
            style={{ padding: '6px 8px', borderRadius: 4, border: '1px solid var(--line)', background: 'var(--surface)', color: 'var(--text)' }}
            required
          />
          <textarea
            placeholder="Detailed description & symptoms"
            value={newDesc}
            onChange={e => setNewDesc(e.target.value)}
            style={{ minHeight: 60, padding: '6px 8px', borderRadius: 4, border: '1px solid var(--line)', background: 'var(--surface)', color: 'var(--text)' }}
          />
          <div style={{ display: 'flex', gap: 8 }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: '0.8rem', color: 'var(--text-muted)' }}>
              Component:
              <select
                value={newComponent}
                onChange={e => setNewComponent(e.target.value)}
                style={{ borderRadius: 4, border: '1px solid var(--line)', background: 'var(--surface)', color: 'var(--text)', padding: '2px 4px' }}
              >
                <option value="canvas">Canvas / Engine</option>
                <option value="vello">Vello GPU / CPU</option>
                <option value="ui">UI Shell / Controls</option>
                <option value="navigation">Navigation</option>
                <option value="export">Export / Media</option>
                <option value="persistence">Storage / Persistence</option>
              </select>
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: '0.8rem', color: 'var(--text-muted)' }}>
              Severity:
              <select
                value={newSeverity}
                onChange={e => setNewSeverity(e.target.value as 'low' | 'medium' | 'high' | 'critical')}
                style={{ borderRadius: 4, border: '1px solid var(--line)', background: 'var(--surface)', color: 'var(--text)', padding: '2px 4px' }}
              >
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
                <option value="critical">Critical</option>
              </select>
            </label>
          </div>
          <button type="submit" style={{ alignSelf: 'flex-start', padding: '4px 12px', background: 'var(--teal, #0ea5e9)', color: '#fff', border: 'none', borderRadius: 4, cursor: 'pointer' }}>
            Save Issue
          </button>
        </form>
      )}

      {/* Subsections: Tracked Bugs & Feedback Feed */}
      <div className="gemini-subsections">
        {/* Tracked Bugs Section */}
        <div>
          <div className="gemini-section-header">
            <h3>Live Tracked Issues</h3>
            <span>{store.bugs.length} total</span>
          </div>
          {store.bugs.length === 0 ? (
            <div className="gemini-empty-hint">No active bugs tracked. Gemini or users can file issues in real time.</div>
          ) : (
            <div className="gemini-bug-list">
              {store.bugs.map(bug => (
                <div key={bug.id} className="gemini-bug-card">
                  <div className="gemini-bug-card-top">
                    <div className="gemini-bug-title-wrap">
                      <span className={`gemini-badge gemini-badge-${bug.severity}`}>{bug.severity}</span>
                      <span className="gemini-bug-title">{bug.title}</span>
                      <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>[{bug.component}]</span>
                    </div>
                    <span className={`gemini-status-tag ${bug.status}`}>{bug.status}</span>
                  </div>

                  {bug.description && <div className="gemini-bug-desc">{bug.description}</div>}
                  {bug.suggestedFix && <div className="gemini-bug-fix">💡 Fix: {bug.suggestedFix}</div>}

                  <div className="gemini-bug-actions">
                    {bug.status !== 'investigating' && bug.status !== 'resolved' && (
                      <button type="button" onClick={() => store.updateBugStatus(bug.id, 'investigating')}>
                        Investigate
                      </button>
                    )}
                    {bug.status !== 'resolved' ? (
                      <button type="button" onClick={() => store.updateBugStatus(bug.id, 'resolved')}>
                        ✓ Mark Resolved
                      </button>
                    ) : (
                      <button type="button" onClick={() => store.updateBugStatus(bug.id, 'open')}>
                        Reopen
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Live Feedback Feed */}
        <div>
          <div className="gemini-section-header">
            <h3>Real-Time Live Feedback Stream</h3>
            <button
              type="button"
              onClick={() => store.clearFeedback()}
              style={{ fontSize: '0.72rem', background: 'transparent', border: 'none', color: 'var(--text-muted)', cursor: 'pointer' }}
            >
              Clear Feed
            </button>
          </div>
          {store.feedback.length === 0 ? (
            <div className="gemini-empty-hint">No feedback events recorded yet.</div>
          ) : (
            <div className="gemini-feedback-feed">
              {store.feedback.map(item => (
                <div key={item.id} className={`gemini-feedback-item ${item.level}`}>
                  <div>{item.message}</div>
                  {item.suggestedAction && (
                    <div style={{ color: 'var(--teal, #38bdf8)', fontSize: '0.75rem' }}>
                      👉 {item.suggestedAction}
                    </div>
                  )}
                  <div className="gemini-feedback-meta">
                    <span>{item.level.toUpperCase()}</span>
                    <span>{new Date(item.timestamp).toLocaleTimeString()}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

/**
 * Gemini Live Bridge & Issue Tracker Store
 *
 * Provides real-time bidirectional state, issue tracking, and feedback logging
 * for deep Gemini MCP integration into Art Equation.
 */

export interface TrackedBug {
  id: string
  title: string
  description: string
  component: string
  severity: 'low' | 'medium' | 'high' | 'critical'
  reproductionSteps: string[]
  suggestedFix?: string
  status: 'open' | 'investigating' | 'resolved'
  createdAt: string
  updatedAt: string
}

export interface GeminiFeedbackItem {
  id: string
  message: string
  level: 'info' | 'warning' | 'error' | 'success'
  suggestedAction?: string
  timestamp: string
}

class GeminiBridgeStore {
  private bugs: Map<string, TrackedBug> = new Map()
  private feedbackLog: GeminiFeedbackItem[] = []
  private listeners: Set<() => void> = new Set()
  private connectionStatus: {
    active: boolean
    port?: number
    pid?: number
    lastPing?: string
  } = { active: false }

  constructor() {
    // Seed initial system monitor
    this.addFeedback({
      message: 'Gemini Embedded Engine Bridge initialized. MCP inspection and mutation active.',
      level: 'info'
    })
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  private notify() {
    for (const listener of this.listeners) {
      try { listener() } catch {}
    }
  }

  // --- Bug & Issue Tracking ---

  trackBug(bug: Omit<TrackedBug, 'id' | 'createdAt' | 'updatedAt'> & { id?: string }): TrackedBug {
    const id = bug.id || `bug-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
    const now = new Date().toISOString()
    const record: TrackedBug = {
      id,
      title: bug.title,
      description: bug.description,
      component: bug.component || 'general',
      severity: bug.severity || 'medium',
      reproductionSteps: bug.reproductionSteps || [],
      suggestedFix: bug.suggestedFix,
      status: bug.status || 'open',
      createdAt: now,
      updatedAt: now,
    }
    this.bugs.set(id, record)
    this.addFeedback({
      message: `[Tracked Bug] (${record.severity.toUpperCase()}) ${record.title} [${record.component}]`,
      level: record.severity === 'critical' || record.severity === 'high' ? 'error' : 'warning'
    })
    this.notify()
    return record
  }

  updateBugStatus(id: string, status: TrackedBug['status']): TrackedBug | undefined {
    const bug = this.bugs.get(id)
    if (!bug) return undefined
    bug.status = status
    bug.updatedAt = new Date().toISOString()
    this.addFeedback({
      message: `[Bug Updated] ${bug.title} -> ${status.toUpperCase()}`,
      level: status === 'resolved' ? 'success' : 'info'
    })
    this.notify()
    return bug
  }

  getBugs(): TrackedBug[] {
    return Array.from(this.bugs.values()).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))
  }

  clearResolvedBugs(): void {
    for (const [id, bug] of this.bugs.entries()) {
      if (bug.status === 'resolved') {
        this.bugs.delete(id)
      }
    }
    this.notify()
  }

  // --- Feedback Log ---

  addFeedback(item: { message: string; level?: 'info' | 'warning' | 'error' | 'success'; suggestedAction?: string }): GeminiFeedbackItem {
    const record: GeminiFeedbackItem = {
      id: `fb-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      message: item.message,
      level: item.level || 'info',
      suggestedAction: item.suggestedAction,
      timestamp: new Date().toISOString()
    }
    this.feedbackLog.push(record)
    if (this.feedbackLog.length > 200) {
      this.feedbackLog.shift()
    }
    this.notify()
    return record
  }

  getFeedbackLog(): GeminiFeedbackItem[] {
    return [...this.feedbackLog].reverse()
  }

  clearFeedback(): void {
    this.feedbackLog = []
    this.notify()
  }

  // --- Connection Status ---

  setConnection(status: { active: boolean; port?: number; pid?: number }) {
    this.connectionStatus = {
      ...status,
      lastPing: new Date().toISOString()
    }
    this.notify()
  }

  getConnection() {
    return { ...this.connectionStatus }
  }

  getStatus() {
    return this.getConnection()
  }
}

export const geminiStore = new GeminiBridgeStore()

/*
 * Art Equation's glass material is deliberately limited to the functional
 * chrome (navigation, controls, and transient panels). Canvas objects and
 * document content keep their own opaque, user-authored colors.
 */
.studio-shell {
  --glass-surface: #0f1318;
  --glass-overlay-surface: #13171d;
  --glass-opacity: 92%;
  --glass-overlay-opacity: 97%;
  --glass-control-opacity: 85%;
  --glass-border: #d7e4f021;
  --glass-highlight: #ffffff14;
  --glass-reflection: #a9d8e009;
  --glass-shadow: 0 18px 52px #05070bb0, inset 0 1px #ffffff0e;
  --glass-overlay-shadow: 0 22px 68px #05070bc2, inset 0 1px #ffffff12;
  --glass-blur: 20px;
}

.studio-shell.workspace-light {
  --glass-surface: #f2eee8;
  --glass-overlay-surface: #faf7f1;
  --glass-opacity: 88%;
  --glass-overlay-opacity: 97%;
  --glass-control-opacity: 84%;
  --glass-border: #66543b35;
  --glass-highlight: #ffffffbf;
  --glass-reflection: #d5b98c30;
  --glass-shadow: 0 16px 44px #57463029, inset 0 1px #ffffffd9;
  --glass-overlay-shadow: 0 22px 58px #57463038, inset 0 1px #ffffffed;
}

/* The functional layer: restrained, more opaque glass over workspace content. */
.studio-shell :is(
  .app-bar,
  .navigator,
  .project-inspector,
  .pane-toolbar,
  .board-navigation,
  .project-board-strip,
  .status-bar
) {
  border-color: var(--glass-border);
  background-color: var(--glass-surface);
  background-image: linear-gradient(148deg, var(--glass-highlight), transparent 39%, transparent 72%, var(--glass-reflection));
  box-shadow: inset 0 1px var(--glass-highlight);
}

.studio-shell .app-bar {
  position: relative;
  z-index: 100;
  box-shadow: inset 0 -1px var(--glass-border), inset 0 1px var(--glass-highlight);
}

.studio-shell .navigator,
.studio-shell .project-inspector {
  background-image: linear-gradient(165deg, var(--glass-highlight), transparent 34%, var(--glass-reflection));
}

/* Floating controls use the regular/high-legibility material, not clear glass. */
.studio-shell :is(
  .canvas-toolbar,
  .canvas-tool-rail,
  .canvas-subtools,
  .canvas-zoom-control,
  .canvas-zoom-menu,
  .canvas-minimap,
  .board-minimap,
