  box-shadow: inset 0 1px var(--glass-highlight), 0 8px 26px #05070b38;
}

.studio-shell :is(
  .settings-panel,
  .trash-viewer,
  .text-entry-dialog,
  .project-tools-menu,
  .new-item-menu,
  .navigator-item-menu,
