) {
  border-color: var(--glass-border);
  background-color: var(--glass-overlay-surface);
  background-image: linear-gradient(145deg, var(--glass-highlight), transparent 44%, var(--glass-reflection));
  box-shadow: var(--glass-overlay-shadow);
}

.studio-shell .trash-viewer,
.studio-shell .settings-panel {
  border-radius: 14px;
}

.studio-shell .canvas-tool-rail,
.studio-shell .canvas-toolbar {
