}

.studio-shell :is(.canvas-tool-rail, .canvas-toolbar, .canvas-subtools, .canvas-zoom-control, .panel-edge-tab) {
  -webkit-backdrop-filter: saturate(145%) blur(var(--glass-blur));
  backdrop-filter: saturate(145%) blur(var(--glass-blur));
}

@supports (backdrop-filter: blur(1px)) {
  .studio-shell :is(
    .app-bar,
    .navigator,
    .project-inspector,
    .pane-toolbar,
    .board-navigation,
    .project-board-strip,
