    -webkit-backdrop-filter: saturate(155%) blur(22px);
    backdrop-filter: saturate(155%) blur(22px);
  }
}

/* OS transparency preferences can disable translucency without changing theme. */
@media (prefers-reduced-transparency: reduce) {
  .studio-shell {
    --glass-opacity: 99%;
    --glass-overlay-opacity: 99%;
    --glass-blur: 0px;
  }

  .studio-shell :is(
    .app-bar,
    .navigator,
    .project-inspector,
    .pane-toolbar,
    .board-navigation,
    .project-board-strip,
    .status-bar,
    .canvas-toolbar,
    .canvas-tool-rail,
    .canvas-subtools,
    .canvas-zoom-control,
    .canvas-zoom-menu,
    .board-minimap,
    .canvas-minimap,
    .settings-panel,
    .trash-viewer,
    .text-entry-dialog,
    .project-tools-menu,
    .new-item-menu,
    .navigator-item-menu,
    .board-cover-picker,
    .project-cover-picker,
    .canvas-context-menu,
    .board-export-popover,
    .canvas-diagnostics,
    .unsorted-panel,
    .project-search-results,
    .document-more-menu,
    .asset-context-menu,
    .inspector-drawer,
    .color-popover,
    .professional-color,
    .panel-edge-tab
  ) {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .studio-shell :is(.app-bar, .navigator, .project-inspector, .canvas-toolbar, .canvas-tool-rail, .settings-panel, .trash-viewer) {
    scroll-behavior: auto;
