@media (max-width: 740px) { .artwork-framing-review__layout { grid-template-columns: minmax(0, 1fr); gap: 18px; } .artwork-framing-review__stage { min-height: 220px; padding: 12px; } .artwork-framing-review__footer { align-items: flex-start; flex-direction: column; } .artwork-framing-review__footer > div { align-self: flex-end; } }
@container (max-width: 700px) { .artwork-framing-review__layout { grid-template-columns: minmax(0, 1fr); gap: 18px; } .artwork-framing-review__stage { min-height: 220px; padding: 12px; } .artwork-framing-review__footer { align-items: flex-start; flex-direction: column; } .artwork-framing-review__footer > div { align-self: flex-end; } }
@media (max-width: 420px) { .artwork-framing-review__identities { grid-template-columns: repeat(2, minmax(0, 1fr)); } .artwork-framing-review h2 { font-size: 22px; } }
