  | { action: 'generate_collision_hull'; method: 'convex_hull' | 'box' }
  | { action: 'assign_collection'; collectionName: string }

export interface DccCommandStack {
  id: string
  name: string
  targetDcc: TargetDccApp
  steps: DccCommandAction[]
}

