  return first ? { left: first.x, top: first.y, right: first.x, bottom: first.y } : { left: 0, top: 0, right: 0, bottom: 0 }
}

export function vectorNodeBounds(node: BoardNode): VectorBounds {
  const operands = node.vectorBoolean?.operands
  // Subtraction cutters may extend beyond the original artwork. Their hidden
  // geometry must not enlarge the visible selection frame or minimap.
  const paths = operands?.length ? node.vectorBoolean?.operation === 'subtract' ? operands.slice(0, 1) : operands : node.vectorPath ? [node.vectorPath] : []
  if (!paths.length) return { left: node.x, top: node.y, right: node.x + node.width, bottom: node.y + node.height }
  const mapPoint = (point: BoardPoint) => vectorLocalToBoard(node, point)
  let bounds: VectorBounds | undefined
  for (const path of paths) for (let index = 0; index < path.points.length; index += 1) {
    const curve = segment(path, index)
    if (!curve) continue
    const current = cubicBounds({ p0: mapPoint(curve.p0), p1: mapPoint(curve.p1), p2: mapPoint(curve.p2), p3: mapPoint(curve.p3) })
    bounds = bounds ? { left: Math.min(bounds.left, current.left), top: Math.min(bounds.top, current.top), right: Math.max(bounds.right, current.right), bottom: Math.max(bounds.bottom, current.bottom) } : current
  }
  const padding = Math.max(0, node.strokeWidth ?? 2) / 2
  return bounds ? { left: bounds.left - padding, top: bounds.top - padding, right: bounds.right + padding, bottom: bounds.bottom + padding } : { left: node.x, top: node.y, right: node.x + node.width, bottom: node.y + node.height }
}

export type VectorAffine = { a: number; b: number; c: number; d: number; e: number; f: number }
const finite = (value: number | undefined, fallback: number) => Number.isFinite(value) ? value! : fallback

/** Exact SVG order: T(board centre) R T(local offset) skewX skewY S T(-centre). */
export function vectorNodeMatrix(node: BoardNode): VectorAffine {
  const transform = node.vectorTransform || {}, cx = node.width / 2, cy = node.height / 2
  const sx = finite(transform.scaleX, 1), sy = finite(transform.scaleY, 1)
  const kx = Math.tan(finite(transform.skewX, 0) * Math.PI / 180), ky = Math.tan(finite(transform.skewY, 0) * Math.PI / 180)
  const theta = finite(node.rotation, 0) * Math.PI / 180, cos = Math.cos(theta), sin = Math.sin(theta)
  const aa = sx * (1 + kx * ky), bb = sx * ky, cc = sy * kx, dd = sy
  const a = cos * aa - sin * bb, b = sin * aa + cos * bb, c = cos * cc - sin * dd, d = sin * cc + cos * dd
  const tx = finite(transform.translateX, 0), ty = finite(transform.translateY, 0)
  return { a, b, c, d, e: node.x + cx + cos * tx - sin * ty - a * cx - c * cy, f: node.y + cy + sin * tx + cos * ty - b * cx - d * cy }
}

export function vectorLocalToBoard(node: BoardNode, point: BoardPoint): BoardPoint {
  const m = vectorNodeMatrix(node)
  return { x: m.a * point.x + m.c * point.y + m.e, y: m.b * point.x + m.d * point.y + m.f }
}

/** Undefined for collapsed/singular transforms: never manufacture a pointer delta. */
export function vectorBoardDeltaToLocal(node: BoardNode, delta: BoardPoint): BoardPoint | undefined {
  const m = vectorNodeMatrix(node), determinant = m.a * m.d - m.b * m.c
  if (!Number.isFinite(determinant) || Math.abs(determinant) < 1e-10) return undefined
  return { x: (m.d * delta.x - m.c * delta.y) / determinant, y: (-m.b * delta.x + m.a * delta.y) / determinant }
}

export function vectorBoardToLocal(node: BoardNode, point: BoardPoint): BoardPoint | undefined {
  const m = vectorNodeMatrix(node)
  return vectorBoardDeltaToLocal(node, { x: point.x - m.e, y: point.y - m.f })
}

export function transformVectorPath(path: VectorPath, matrix: VectorAffine): VectorPath {
  const handle = (value: BoardPoint | undefined) => value && { x: matrix.a * value.x + matrix.c * value.y, y: matrix.b * value.x + matrix.d * value.y }
  return { ...path, points: path.points.map((point) => ({ ...point, x: matrix.a * point.x + matrix.c * point.y + matrix.e, y: matrix.b * point.x + matrix.d * point.y + matrix.f, ...(point.handleIn ? { handleIn: handle(point.handleIn) } : {}), ...(point.handleOut ? { handleOut: handle(point.handleOut) } : {}) })) }
}

/** Bake only the inner transform, then resize its editable geometry with the frame.
 * Rotation stays editable. This prevents stale skew/translation centres after resize. */
export function resizeVectorNodeFrame(node: BoardNode, frame: { x: number; y: number; width: number; height: number }): BoardNode {
  if (!node.vectorPath || node.width <= 0 || node.height <= 0 || frame.width <= 0 || frame.height <= 0 || ![frame.x, frame.y, frame.width, frame.height].every(Number.isFinite)) return node
  const matrix = vectorNodeMatrix({ ...node, x: 0, y: 0, rotation: 0 })
  const resize = (path: VectorPath) => scaleVectorPath(transformVectorPath(path, matrix), frame.width / node.width, frame.height / node.height)
  return { ...node, ...transformVectorPaint(node, [matrix.a*frame.width/node.width,matrix.b*frame.height/node.height,matrix.c*frame.width/node.width,matrix.d*frame.height/node.height,matrix.e*frame.width/node.width,matrix.f*frame.height/node.height]), x: frame.x, y: frame.y, width: frame.width, height: frame.height, vectorTransform: undefined, vectorPath: resize(node.vectorPath), ...(node.vectorBoolean ? { vectorBoolean: { ...node.vectorBoolean, operands: node.vectorBoolean.operands.map(resize), ...(node.vectorBoolean.resolvedPaths ? { resolvedPaths: node.vectorBoolean.resolvedPaths.map(resize) } : {}) } } : {}) }
}

export function vectorSegmentPoint(path: VectorPath, index: number, t: number): BoardPoint | undefined {
  const curve = segment(path, index)
  if (!curve) return undefined
  const bounded = Math.max(0, Math.min(1, t))
  return { x: cubicValue(curve.p0.x, curve.p1.x, curve.p2.x, curve.p3.x, bounded), y: cubicValue(curve.p0.y, curve.p1.y, curve.p2.y, curve.p3.y, bounded) }
}

/** Move the grabbed cubic point exactly while endpoints and other segments remain fixed. */
export function reshapeVectorSegment(path: VectorPath, index: number, t: number, delta: BoardPoint): VectorPath {
  const curve = segment(path, index)
  if (!curve || ![t, delta.x, delta.y].every(Number.isFinite)) return path
  const bounded = Math.max(.02, Math.min(.98, t)), u = 1 - bounded
  const weightOut = 3 * u * u * bounded, weightIn = 3 * u * bounded * bounded, denominator = weightOut ** 2 + weightIn ** 2
  const nextIndex = (index + 1) % path.points.length, points = path.points.slice()
  points[index] = { ...points[index], handleOut: add(subtract(curve.p1, curve.p0), scale(delta, weightOut / denominator)), handleMode: 'corner' }
  points[nextIndex] = { ...points[nextIndex], handleIn: add(subtract(curve.p2, curve.p3), scale(delta, weightIn / denominator)), handleMode: 'corner' }
  return { ...path, points }
}

/** Coarse bracketing plus local refinement avoids choosing a distant curve lobe. */
export function nearestVectorSegment(path: VectorPath, point: BoardPoint): { index: number; t: number; point: BoardPoint; distance: number } | undefined {
  let best: { index: number; t: number; point: BoardPoint; distance: number } | undefined
  const count = path.closed ? path.points.length : path.points.length - 1
  for (let index = 0; index < count; index++) {
    let sampleT = 0, sampleDistance = Infinity
    for (let sample = 0; sample <= 32; sample++) {
      const t = sample / 32, p = vectorSegmentPoint(path, index, t)!, d = distance(p, point)
      if (d < sampleDistance) { sampleDistance = d; sampleT = t }
    }
    let low = Math.max(0, sampleT - 1 / 32), high = Math.min(1, sampleT + 1 / 32)
    for (let iteration = 0; iteration < 24; iteration++) {
      const left = low + (high - low) / 3, right = high - (high - low) / 3
      if (distance(vectorSegmentPoint(path, index, left)!, point) < distance(vectorSegmentPoint(path, index, right)!, point)) high = right
      else low = left
    }
    const t = (low + high) / 2, p = vectorSegmentPoint(path, index, t)!, d = distance(p, point)
    if (!best || d < best.distance) best = { index, t, point: p, distance: d }
  }
  return best
}

/** Retract in/out/both Bézier handles at anchor index without leaving stale {0, 0} objects. */
export function retractVectorHandle(path: VectorPath, index: number, which: 'in' | 'out' | 'both'): VectorPath {
  if (index < 0 || index >= path.points.length) return path
  const points = path.points.slice()
  const current = points[index]
  const updated: VectorPathPoint = { ...current }
  if (which === 'in' || which === 'both') delete updated.handleIn
  if (which === 'out' || which === 'both') delete updated.handleOut
  updated.handleMode = 'corner'
  points[index] = updated
  return { ...path, points }
}

/** Extend a handle from an anchor with optional collinear symmetric counterpart. */
export function extendVectorHandle(path: VectorPath, index: number, which: 'in' | 'out', delta: BoardPoint, symmetric = false): VectorPath {
  if (index < 0 || index >= path.points.length || !Number.isFinite(delta.x) || !Number.isFinite(delta.y)) return path
  const points = path.points.slice()
  const current = points[index]
  const updated: VectorPathPoint = { ...current }
  const len = Math.hypot(delta.x, delta.y)
  if (len < 1e-4) {
    if (which === 'in') delete updated.handleIn
    else delete updated.handleOut
    if (!updated.handleIn && !updated.handleOut) updated.handleMode = 'corner'
    points[index] = updated
    return { ...path, points }
  }
  if (which === 'in') {
    updated.handleIn = { x: round(delta.x), y: round(delta.y) }
    if (symmetric) {
      updated.handleOut = { x: round(-delta.x), y: round(-delta.y) }
      updated.handleMode = 'smooth'
    } else {
      updated.handleMode = 'corner'
    }
  } else {
    updated.handleOut = { x: round(delta.x), y: round(delta.y) }
    if (symmetric) {
      updated.handleIn = { x: round(-delta.x), y: round(-delta.y) }
      updated.handleMode = 'smooth'
    } else {
      updated.handleMode = 'corner'
    }
  }
  points[index] = updated
  return { ...path, points }
}

export type VectorSnapResult = {
  point: BoardPoint
  snapped: boolean
  snapType?: 'anchor' | 'axis-x' | 'axis-y'
  reference?: BoardPoint
}

/** Snap a pointer coordinate to nearby path anchors or orthogonal axes. */
export function snapPointToVectorGuides(
  point: BoardPoint,
  anchors: readonly BoardPoint[],
  options: { tolerance?: number; snapAxes?: boolean; axisReference?: BoardPoint } = {},
): VectorSnapResult {
  const tolerance = Math.max(1, options.tolerance ?? 8)
  let bestDistance = Infinity
  let snappedPoint = { ...point }
  let snapType: VectorSnapResult['snapType'] = undefined
  let reference: BoardPoint | undefined = undefined

  for (const anchor of anchors) {
    const d = distance(point, anchor)
    if (d <= tolerance && d < bestDistance) {
      bestDistance = d
      snappedPoint = { x: anchor.x, y: anchor.y }
      snapType = 'anchor'
      reference = anchor
    }
  }
  if (snapType === 'anchor') {
    return { point: snappedPoint, snapped: true, snapType, reference }
  }

  if (options.snapAxes && options.axisReference) {
    const ref = options.axisReference
    const dx = Math.abs(point.x - ref.x)
    const dy = Math.abs(point.y - ref.y)
    if (dx <= tolerance && dx <= dy) {
      return { point: { x: ref.x, y: point.y }, snapped: true, snapType: 'axis-x', reference: ref }
    }
    if (dy <= tolerance) {
      return { point: { x: point.x, y: ref.y }, snapped: true, snapType: 'axis-y', reference: ref }
    }
  }

  return { point, snapped: false }
}

/** Keep an imported affine stroke editable when its baked fill path changes. */
export function synchronizeVectorStroke(node: BoardNode): BoardNode {
  const g=node.vectorStrokeGeometry
  if(!g || !node.vectorPath || g.paths.length!==1 || node.vectorBoolean)return node
  const [a,b,c,d,e,f]=g.transform,det=a*d-b*c
  if(Math.abs(det)<1e-12)return node
  const path=transformVectorPath(node.vectorPath,{a:d/det,b:-b/det,c:-c/det,d:a/det,e:(c*f-d*e)/det,f:(b*e-a*f)/det})
  return {...node,vectorStrokeGeometry:{...g,paths:[{...path,closed:g.paths[0].closed}]}}
}

import paper from 'paper'
import type { VectorBooleanOperation, VectorPath, VectorPathPoint } from './project'

type FillRule = 'nonzero' | 'evenodd'
type Cached = { operands: readonly VectorPath[]; signature: string; value: VectorPath[] | undefined }
// Bound retained immutable source references/results; old document revisions
// must not grow an unbounded renderer cache. No Paper canvas/view is created.
const cache: Cached[] = []
const MAX_CACHE_ENTRIES = 128
const scope = new paper.PaperScope()
new scope.Project(undefined!) // Geometry-only project, without a canvas/view element.

function validPath(path: VectorPath): boolean {
  return path?.closed === true && Array.isArray(path.points) && path.points.length >= 3 && path.points.every(point =>
    Number.isFinite(point.x) && Number.isFinite(point.y) &&
    (!point.handleIn || (Number.isFinite(point.handleIn.x) && Number.isFinite(point.handleIn.y))) &&
    (!point.handleOut || (Number.isFinite(point.handleOut.x) && Number.isFinite(point.handleOut.y))))
}

/** Derived exact Bézier boundary contours. Source operands/rules remain the
 * editable document truth; the returned paths use nonzero outer/hole winding.
 * undefined means unsupported/invalid; [] is a valid empty set result. */
export function resolveVectorBooleanGeometry(
  operation: VectorBooleanOperation,
  operands: readonly VectorPath[],
  fillRules?: readonly FillRule[],
): VectorPath[] | undefined {
  const signature = `${operation}:${operands.map((_, index) => fillRules?.[index] ?? 'nonzero').join(',')}`
  const index = cache.findIndex(entry => entry.operands === operands && entry.signature === signature)
  if (index >= 0) { const [entry] = cache.splice(index, 1); cache.push(entry); return entry.value }
  let value: VectorPath[] | undefined
  if (['union', 'subtract', 'intersect', 'exclude'].includes(operation) && operands.length >= 2 && operands.every(validPath)) {
    const items: paper.PathItem[] = []
    try {
      scope.activate()
      const paths = operands.map((path, index) => {
        const item = new scope.Path({ insert: false, closed: true, fillRule: fillRules?.[index] ?? 'nonzero' })
        for (const point of path.points) item.add(new scope.Segment(
          new scope.Point(point.x, point.y),
          new scope.Point(point.handleIn?.x ?? 0, point.handleIn?.y ?? 0),
          new scope.Point(point.handleOut?.x ?? 0, point.handleOut?.y ?? 0),
        ))
        items.push(item)
        return item
      })
      let result: paper.PathItem = paths[0]
      for (const path of paths.slice(1)) {
        const options = { insert: false, trace: true }
        result = operation === 'union' ? result.unite(path, options)
          : operation === 'subtract' ? result.subtract(path, options)
            : operation === 'intersect' ? result.intersect(path, options) : result.exclude(path, options)
        result.fillRule = 'nonzero'
        items.push(result)
      }
      result.reorient(true, true)
      const contours = result instanceof scope.CompoundPath ? result.children as paper.Path[] : [result as paper.Path]
      value = contours.filter(path => path.segments.length > 0).map(path => ({
        version: 1, closed: true,
        points: path.segments.map(segment => {
          const point: VectorPathPoint = { x: segment.point.x, y: segment.point.y }
          if (!segment.handleIn.isZero()) point.handleIn = { x: segment.handleIn.x, y: segment.handleIn.y }
          if (!segment.handleOut.isZero()) point.handleOut = { x: segment.handleOut.x, y: segment.handleOut.y }
          return point
        }),
      }))
      if (!value.every(path => path.points.every(point => Number.isFinite(point.x) && Number.isFinite(point.y) &&
        (!point.handleIn || (Number.isFinite(point.handleIn.x) && Number.isFinite(point.handleIn.y))) &&
        (!point.handleOut || (Number.isFinite(point.handleOut.x) && Number.isFinite(point.handleOut.y)))))) value = undefined
    } catch { value = undefined } finally { for (const item of items) item.remove() }
  }
  cache.push({ operands, signature, value })
  if (cache.length > MAX_CACHE_ENTRIES) cache.shift()
  return value
}

import type { BoardNode, VectorBooleanOperation, VectorPath } from './project'
import { joinVectorPaths, transformVectorPath, vectorNodeMatrix, vectorPathBounds } from './vector'

export type VectorCompositionResult =
  | { ok: true; node: BoardNode; sourceIds: string[] }
  | { ok: false; reason: string }

/** Compose editable paths in board space, then give the result a fresh local frame.
 * Ownership/connector mutation remains the caller's atomic board operation.
 * Boolean operands stay exact source geometry; resolving their paint is separate.
 */
export function composeVectorPaths(
  nodes: readonly BoardNode[],
  operation: 'join' | VectorBooleanOperation,
  resultId = nodes[0]?.id,
  options: { joinTolerance?: number } = {},
): VectorCompositionResult {
  const refuse = (reason: string): VectorCompositionResult => ({ ok: false, reason })
  if (nodes.length !== 2 || !resultId || nodes[0].id === nodes[1].id) return refuse('Select exactly two different paths.')
  if (!['join', 'union', 'subtract', 'intersect', 'exclude'].includes(operation)) return refuse('Unknown path operation.')
  const [first, second] = nodes
  if (first.groupId !== second.groupId || first.parentColumnId !== second.parentColumnId) return refuse('Both paths must have the same direct group and column owner.')
  if (nodes.some((node) => node.locked)) return refuse('Unlock both paths before combining them.')
  if (nodes.some((node) => node.kind !== 'shape' || node.shapeType !== 'path' || !node.vectorPath)) return refuse('Both objects must be editable paths.')
  if (nodes.some((node) => node.vectorBoolean)) return refuse('Resolve existing Boolean paths before combining them again.')
  const paths = nodes.map((node) => node.vectorPath!)
  if (paths.some((path) => path.version !== 1 || path.points.length < (path.closed ? 3 : 2))) return refuse('A path has too few anchors or an unsupported version.')
  if (operation === 'join' ? paths.some((path) => path.closed) : paths.some((path) => !path.closed)) return refuse(operation === 'join' ? 'Join requires two open paths.' : 'Boolean operations require two closed paths.')
  if (paths.some((path) => path.points.some((point) => [point.x, point.y, point.handleIn?.x ?? 0, point.handleIn?.y ?? 0, point.handleOut?.x ?? 0, point.handleOut?.y ?? 0].some((value) => !Number.isFinite(value))))) return refuse('A path contains invalid anchor or control coordinates.')
  if (nodes.some((node) => [node.x, node.y, node.width, node.height, node.rotation ?? 0, ...Object.values(node.vectorTransform || {})].some((value) => !Number.isFinite(value)) || node.width <= 0 || node.height <= 0)) return refuse('A path contains invalid frame or transform values.')
  const matrices = nodes.map(vectorNodeMatrix)
  if (matrices.some((matrix) => Object.values(matrix).some((value) => !Number.isFinite(value)) || Math.abs(matrix.a * matrix.d - matrix.b * matrix.c) < 1e-10)) return refuse('A collapsed or singular path transform cannot be combined.')
  const tolerance = options.joinTolerance ?? 12
  if (!Number.isFinite(tolerance) || tolerance < 0) return refuse('Join tolerance must be a finite non-negative distance.')
  const worldPaths = paths.map((path, index) => transformVectorPath(path, matrices[index]))
  const joined = operation === 'join' ? joinVectorPaths(worldPaths[0], worldPaths[1], tolerance) : undefined
  if (operation === 'join' && !joined) return refuse('The selected paths could not be joined.')
  const boundsPaths = joined ? [joined] : operation === 'subtract' ? worldPaths.slice(0, 1) : worldPaths
  const bounds = boundsPaths.map(vectorPathBounds)
  const x = Math.min(...bounds.map((bound) => bound.left)), y = Math.min(...bounds.map((bound) => bound.top))
  const width = Math.max(1, Math.max(...bounds.map((bound) => bound.right)) - x)
  const height = Math.max(1, Math.max(...bounds.map((bound) => bound.bottom)) - y)
  if (![x, y, width, height].every(Number.isFinite)) return refuse('The composed path exceeds finite coordinate bounds.')
  const local = (path: VectorPath) => transformVectorPath(path, { a: 1, b: 0, c: 0, d: 1, e: -x, f: -y })
  const operands = worldPaths.map(local)
  const node: BoardNode = {
    ...first,
    id: resultId,
    title: operation === 'join' ? 'Joined path' : `${operation[0].toUpperCase()}${operation.slice(1)} path`,
    x, y, width, height,
    rotation: 0,
    vectorTransform: undefined,
    strokeWidth: first.strokeWidth ?? 2,
    opacity: first.opacity ?? 1,
    vectorFillRule: operation === 'exclude' ? 'evenodd' : first.vectorFillRule ?? 'nonzero',
    vectorStrokeJoin: first.vectorStrokeJoin ?? 'miter',
    vectorStrokeCap: first.vectorStrokeCap ?? 'butt',
    vectorPath: joined ? local(joined) : operands[0],
    vectorBoolean: joined ? undefined : { operation: operation as VectorBooleanOperation, operands, fillRules: nodes.map((source) => source.vectorFillRule ?? 'nonzero') },
  }
  return { ok: true, node, sourceIds: nodes.map((source) => source.id) }
}

import type { BoardNode, BoardPoint, VectorPath, VectorPathPoint } from './project'
import { transformVectorPath, vectorNodeMatrix, vectorPathBounds } from './vector.ts'

type Cubic = { p0: BoardPoint; p1: BoardPoint; p2: BoardPoint; p3: BoardPoint }
const add = (a: BoardPoint, b: BoardPoint): BoardPoint => ({ x: a.x + b.x, y: a.y + b.y })
const sub = (a: BoardPoint, b: BoardPoint): BoardPoint => ({ x: a.x - b.x, y: a.y - b.y })
const mul = (a: BoardPoint, value: number): BoardPoint => ({ x: a.x * value, y: a.y * value })
const mix = (a: BoardPoint, b: BoardPoint, t: number) => add(a, mul(sub(b, a), t))
const dist = (a: BoardPoint, b: BoardPoint) => Math.hypot(a.x - b.x, a.y - b.y)
const valid = (point: BoardPoint) => Boolean(point && typeof point === 'object' && Number.isFinite(point.x) && Number.isFinite(point.y))
const boundedPoint = (point: unknown): point is BoardPoint => Boolean(point && typeof point === 'object'
  && valid(point as BoardPoint) && Math.abs((point as BoardPoint).x) <= 1e9 && Math.abs((point as BoardPoint).y) <= 1e9)
const validEditablePath = (path: VectorPath | undefined): path is VectorPath => Boolean(path && path.version === 1
  && typeof path.closed === 'boolean' && Array.isArray(path.points) && path.points.length >= (path.closed ? 3 : 2)
  && path.points.length <= 65_536 && path.points.every(point => boundedPoint(point)
    && (point.handleIn === undefined || boundedPoint(point.handleIn)) && (point.handleOut === undefined || boundedPoint(point.handleOut))))

function distanceToSegment(point: BoardPoint, from: BoardPoint, to: BoardPoint) {
  const delta = sub(to, from), length = delta.x ** 2 + delta.y ** 2
  const t = length ? Math.max(0, Math.min(1, ((point.x - from.x) * delta.x + (point.y - from.y) * delta.y) / length)) : 0
  return dist(point, mix(from, to, t))
}

function segmentDistance(a: BoardPoint, b: BoardPoint, c: BoardPoint, d: BoardPoint) {
  const cross = (from: BoardPoint, to: BoardPoint, point: BoardPoint) => (to.x - from.x) * (point.y - from.y) - (to.y - from.y) * (point.x - from.x)
  const overlaps = Math.max(Math.min(a.x, b.x), Math.min(c.x, d.x)) <= Math.min(Math.max(a.x, b.x), Math.max(c.x, d.x)) && Math.max(Math.min(a.y, b.y), Math.min(c.y, d.y)) <= Math.min(Math.max(a.y, b.y), Math.max(c.y, d.y))
  if (overlaps && cross(a, b, c) * cross(a, b, d) <= 0 && cross(c, d, a) * cross(c, d, b) <= 0) return 0
  return Math.min(distanceToSegment(a, c, d), distanceToSegment(b, c, d), distanceToSegment(c, a, b), distanceToSegment(d, a, b))
}

function simplify(points: BoardPoint[], tolerance: number): BoardPoint[] {
  if (points.length <= 2 || tolerance <= 0) return points
  const keep = new Set([0, points.length - 1]), work = [[0, points.length - 1]]
  while (work.length) {
    const [first, last] = work.pop()!
    let furthest = -1, maximum = tolerance
    for (let index = first + 1; index < last; index++) {
      const d = distanceToSegment(points[index], points[first], points[last])
      if (d > maximum) { maximum = d; furthest = index }
    }
    if (furthest >= 0) { keep.add(furthest); work.push([first, furthest], [furthest, last]) }
  }
  return [...keep].sort((a, b) => a - b).map((index) => points[index])
}

export type PencilOptions = { tolerance?: number; minDistance?: number; smoothing?: number; closed?: boolean; maxPoints?: number }

/** Freehand samples become editable cubic anchors; no SVG string or raster is stored.
 * Tolerances are board units, so callers convert desired screen pixels by zoom. */
export function createPencilPath(samples: BoardPoint[], options: PencilOptions = {}): VectorPath {
  const minimum = Math.max(0, options.minDistance ?? .5), limit = Math.max(2, Math.floor(options.maxPoints ?? 2048))
  const filtered: BoardPoint[] = []
  for (const sample of samples) if (valid(sample) && (!filtered.length || dist(filtered.at(-1)!, sample) >= minimum)) filtered.push({ x: sample.x, y: sample.y })
  const last = samples.findLast(valid)
  if (last && filtered.length && dist(last, filtered.at(-1)!) > 1e-8) filtered.push({ ...last })
  const closed = Boolean(options.closed && filtered.length > 2)
  if (closed && dist(filtered[0], filtered.at(-1)!) <= minimum) filtered.pop()
  let anchors = simplify(filtered, Math.max(0, options.tolerance ?? 1.5))
  if (anchors.length > limit) anchors = Array.from({ length: limit }, (_, index) => anchors[Math.round(index * (anchors.length - 1) / (limit - 1))])
  const smoothing = Math.max(0, Math.min(1, options.smoothing ?? .7))
  const points: VectorPathPoint[] = anchors.map((point, index) => {
    if (!smoothing || anchors.length < 3) return { ...point }
    const previous = anchors[index - 1] || (closed ? anchors.at(-1)! : point), next = anchors[index + 1] || (closed ? anchors[0] : point)
    const direction = sub(next, previous), length = Math.hypot(direction.x, direction.y)
    if (length < 1e-9) return { ...point }
    const incoming = dist(previous, point) * smoothing / 3, outgoing = dist(point, next) * smoothing / 3, axis = mul(direction, 1 / length)
    return { ...point, ...(closed || index > 0 ? { handleIn: mul(axis, -incoming) } : {}), ...(closed || index < anchors.length - 1 ? { handleOut: mul(axis, outgoing) } : {}), handleMode: 'smooth' }
  })
  return { version: 1, closed: closed && points.length > 2, points }
}

function curveFor(path: VectorPath, index: number): Cubic {
  const from = path.points[index], to = path.points[(index + 1) % path.points.length]
  return { p0: from, p1: add(from, from.handleOut || { x: 0, y: 0 }), p2: add(to, to.handleIn || { x: 0, y: 0 }), p3: to }
}

function split(curve: Cubic, t: number): [Cubic, Cubic] {
  const a = mix(curve.p0, curve.p1, t), b = mix(curve.p1, curve.p2, t), c = mix(curve.p2, curve.p3, t)
  const d = mix(a, b, t), e = mix(b, c, t), point = mix(d, e, t)
  return [{ p0: curve.p0, p1: a, p2: d, p3: point }, { p0: point, p1: e, p2: c, p3: curve.p3 }]
}

function curveSlice(curve: Cubic, low: number, high: number): Cubic {
  const left = high < 1 ? split(curve, high)[0] : curve
  return low > 0 ? split(left, low / high)[1] : left
}

function sweepDistance(point: BoardPoint, sweep: BoardPoint[]) {
  if (sweep.length === 1) return dist(point, sweep[0])
  let minimum = Infinity
  for (let index = 1; index < sweep.length; index++) minimum = Math.min(minimum, distanceToSegment(point, sweep[index - 1], sweep[index]))
  return minimum
}

/** Erase intervals are located with a bounded geometric tolerance. Every surviving
 * section is the original cubic's exact De Casteljau slice, not a flattened redraw. */
export function eraseVectorPath(path: VectorPath, sweep: BoardPoint[], radius: number, tolerance = .1): { changed: boolean; paths: VectorPath[] } {
  const samples = sweep.filter(valid)
  if (!validEditablePath(path) || path.closed || !samples.length || !Number.isFinite(radius) || radius <= 0) return { changed: false, paths: [path] }
  const epsilon = Math.max(.001, Math.min(radius / 8, Number.isFinite(tolerance) ? tolerance : .1))
  const survivors: VectorPath[] = []
  let current: VectorPathPoint[] = [], changed = false
  const flush = () => { if (current.length > 1) survivors.push({ version: 1, closed: false, points: current }); current = [] }
  const appendCurve = (curve: Cubic) => {
    const outgoing = sub(curve.p1, curve.p0), incoming = sub(curve.p2, curve.p3)
    if (!current.length) current.push({ x: curve.p0.x, y: curve.p0.y, handleOut: outgoing, handleMode: 'corner' })
    else current[current.length - 1] = { ...current.at(-1)!, handleOut: outgoing, handleMode: 'corner' }
    current.push({ x: curve.p3.x, y: curve.p3.y, handleIn: incoming, handleMode: 'corner' })
  }
  for (let index = 0; index < path.points.length - 1; index++) {
    const original = curveFor(path, index), intervals: { low: number; high: number; keep: boolean }[] = []
    const locate = (curve: Cubic, low: number, high: number, depth: number) => {
      const halves = split(curve, .5), center = halves[0].p3
      const reach = Math.max(...[curve.p0, curve.p1, curve.p2, curve.p3].map((point) => dist(point, center))), d = sweepDistance(center, samples)
      // Distance to the swept centreline is 1-Lipschitz. These decisions are
      // certain for the whole control hull, including looping cubics.
      if (d - reach > radius) { intervals.push({ low, high, keep: true }); return }
      if (d + reach < radius) { intervals.push({ low, high, keep: false }); return }
      if (reach <= epsilon || depth >= 20) { intervals.push({ low, high, keep: d >= radius }); return }
      const middle = (low + high) / 2
      locate(halves[0], low, middle, depth + 1); locate(halves[1], middle, high, depth + 1)
    }
    locate(original, 0, 1, 0)
    const merged: typeof intervals = []
    for (const interval of intervals) {
      const previous = merged.at(-1)
      if (previous?.keep === interval.keep) previous.high = interval.high
      else merged.push({ ...interval })
    }
    for (const interval of merged) {
      if (interval.keep) appendCurve(curveSlice(original, interval.low, interval.high))
      else { changed = true; flush() }
    }
  }
  flush()
  return changed ? { changed: true, paths: survivors } : { changed: false, paths: [path] }
}

const CIRCLE_K = .5522847498307936
export function vectorCircle(center: BoardPoint, radius: number): VectorPath {
  const h = radius * CIRCLE_K
  return { version: 1, closed: true, points: [
    { x: center.x + radius, y: center.y, handleIn: { x: 0, y: -h }, handleOut: { x: 0, y: h } },
    { x: center.x, y: center.y + radius, handleIn: { x: h, y: 0 }, handleOut: { x: -h, y: 0 } },
    { x: center.x - radius, y: center.y, handleIn: { x: 0, y: h }, handleOut: { x: 0, y: -h } },
    { x: center.x, y: center.y - radius, handleIn: { x: -h, y: 0 }, handleOut: { x: h, y: 0 } },
  ] }
}

/** Capsule cutters keep a filled vector Eraser independent of canvas color. */
export function vectorEraserCutters(sweep: BoardPoint[], radius: number): VectorPath[] {
  const samples = sweep.filter(valid)
  if (!samples.length || !Number.isFinite(radius) || radius <= 0) return []
  if (samples.length === 1) return [vectorCircle(samples[0], radius)]
  const cutters: VectorPath[] = []
  for (let index = 1; index < samples.length; index++) {
    const a = samples[index - 1], b = samples[index], delta = sub(b, a), length = Math.hypot(delta.x, delta.y)
    if (length < 1e-8) continue
    const axis = mul(delta, 1 / length), normal = { x: -axis.y, y: axis.x }, cap = radius * CIRCLE_K
    const ar = add(a, mul(normal, radius)), br = add(b, mul(normal, radius)), end = add(b, mul(axis, radius))
    const bl = sub(b, mul(normal, radius)), al = sub(a, mul(normal, radius)), start = sub(a, mul(axis, radius))
    cutters.push({ version: 1, closed: true, points: [
      { ...ar, handleIn: mul(axis, -cap) },
      { ...br, handleOut: mul(axis, cap) },
      { ...end, handleIn: mul(normal, cap), handleOut: mul(normal, -cap) },
      { ...bl, handleIn: mul(axis, cap) },
      { ...al, handleOut: mul(axis, -cap) },
      { ...start, handleIn: mul(normal, -cap), handleOut: mul(normal, cap) },
    ] })
  }
  return cutters.length ? cutters : [vectorCircle(samples[0], radius)]
}

/** Converts live shapes to editable path geometry when a partial edit requires it. */
export function editableShapePath(node: BoardNode): VectorPath | undefined {
  if (node.kind !== 'shape') return undefined
  const w = node.width, h = node.height
  if (![node.x, node.y, w, h, node.rotation ?? 0].every(Number.isFinite) || w <= 0 || h <= 0
    || [node.x, node.y, w, h].some(value => Math.abs(value) > 1e9)) return undefined
  if (node.shapeType === 'line' || node.shapeType === 'arrow') {
    if (node.vectorTransform !== undefined || node.vectorBoolean !== undefined) return undefined
    // App paints only first/last anchors as a straight line. Intermediate
    // anchors and cubic controls are editable metadata, not visible line paint.
    // The CSS reverse transform is applied inside the article before rotation.
    if (node.vectorPath && (!Array.isArray(node.vectorPath.points) || node.vectorPath.points.length < 2)) return undefined
    const first = node.vectorPath ? node.vectorPath.points[0] : { x: 0, y: 0 }
    const last = node.vectorPath ? node.vectorPath.points.at(-1) : { x: w, y: h }
    if (!boundedPoint(first) || !boundedPoint(last)) return undefined
    return { version: 1, closed: false, points: [first, last].map((point) => ({ x: point.x, y: node.body === 'reverse' ? h - point.y : point.y })) }
  }
  // These ordinary CSS/SVG shapes do not consume stored inner path transforms
  // or Boolean metadata. Never erase an invisible derivative instead of paint.
  if ((node.shapeType === 'rectangle' || node.shapeType === 'ellipse')
    && (node.vectorPath !== undefined || node.vectorTransform !== undefined || node.vectorBoolean !== undefined)) return undefined
  if (node.vectorTransform !== undefined && (!node.vectorTransform || typeof node.vectorTransform !== 'object' || Array.isArray(node.vectorTransform)
    || Object.values(node.vectorTransform).some(value => value !== undefined && !Number.isFinite(value)))) return undefined
  if (node.vectorPath) return validEditablePath(node.vectorPath) ? node.vectorPath : undefined
  if (node.shapeType === 'ellipse') {
    const ellipse = vectorCircle({ x: 0, y: 0 }, 1)
    // The actual SVG uses rx/ry=49 in its normalized100 viewport. Converting
    // at50 grows untouched artwork as soon as a partial erasure is committed.
    return transformVectorPath(ellipse, { a: w * .49, b: 0, c: 0, d: h * .49, e: w / 2, f: h / 2 })
  }
  if (node.shapeType !== 'rectangle') return undefined
  const r = Math.max(0, Math.min(node.cornerRadius ?? 14, w / 2, h / 2)), k = r * CIRCLE_K
  if (!r) return { version: 1, closed: true, points: [{ x: 0, y: 0 }, { x: w, y: 0 }, { x: w, y: h }, { x: 0, y: h }] }
  return { version: 1, closed: true, points: [
    { x: r, y: 0, handleIn: { x: -k, y: 0 } }, { x: w - r, y: 0, handleOut: { x: k, y: 0 } },
    { x: w, y: r, handleIn: { x: 0, y: -k } }, { x: w, y: h - r, handleOut: { x: 0, y: k } },
    { x: w - r, y: h, handleIn: { x: k, y: 0 } }, { x: r, y: h, handleOut: { x: -k, y: 0 } },
    { x: 0, y: h - r, handleIn: { x: 0, y: k } }, { x: 0, y: r, handleOut: { x: 0, y: -k } },
  ] }
}

function flatten(path: VectorPath, tolerance = .25): BoardPoint[] {
  const points: BoardPoint[] = path.points.length ? [path.points[0]] : []
  const visit = (curve: Cubic, depth: number) => {
    if (depth >= 15 || Math.max(distanceToSegment(curve.p1, curve.p0, curve.p3), distanceToSegment(curve.p2, curve.p0, curve.p3)) <= tolerance) { points.push(curve.p3); return }
    const [left, right] = split(curve, .5); visit(left, depth + 1); visit(right, depth + 1)
  }
  for (let index = 0; index < (path.closed ? path.points.length : path.points.length - 1); index++) visit(curveFor(path, index), 0)
  return points
}

function inside(point: BoardPoint, polygon: BoardPoint[], evenOdd = false) {
  let winding = 0
  for (let index = 1; index < polygon.length; index++) {
    const a = polygon[index - 1], b = polygon[index], cross = (b.x - a.x) * (point.y - a.y) - (point.x - a.x) * (b.y - a.y)
    if (a.y <= point.y && b.y > point.y && cross > 0) winding++
    if (a.y > point.y && b.y <= point.y && cross < 0) winding--
  }
  return evenOdd ? Math.abs(winding) % 2 === 1 : winding !== 0
}

function localizeNode(node: BoardNode, path: VectorPath, operands?: VectorPath[]): BoardNode {
  const bounds = vectorPathBounds(path), x = bounds.left, y = bounds.top
  const translate = (value: VectorPath) => transformVectorPath(value, { a: 1, b: 0, c: 0, d: 1, e: -x, f: -y })
  return { ...node, shapeType: 'path', x, y, width: Math.max(1, bounds.right - x), height: Math.max(1, bounds.bottom - y), rotation: 0, vectorTransform: undefined, vectorPath: translate(path), vectorBoolean: operands ? { operation: 'subtract', operands: operands.map(translate) } : undefined }
}

export type VectorEraseResult = { changed: boolean; nodes: BoardNode[]; unsupported?: string }

/** Erasure runs in board space, giving a circular brush even on flipped/skewed paths.
 * Filled paths retain editable subtraction operands; open paths become exact cubic fragments.
 * Imported media and non-subtract Boolean expressions are intentionally unsupported. */
export function eraseVectorNode(node: BoardNode, sweep: BoardPoint[], radius: number, options: { tolerance?: number; idFactory?: () => string } = {}): VectorEraseResult {
  const path = editableShapePath(node), samples = sweep.filter(valid)
  if (node.locked || !samples.length || !Number.isFinite(radius) || radius <= 0) return { changed: false, nodes: [node] }
  if (!path) return { changed: false, nodes: [node], unsupported: 'Eraser edits vector shapes only; source media is preserved.' }
  // Rebasing a surviving contour currently has no corresponding caption
  // layout transform. Refuse instead of deleting ordinary shape labels or
  // moving a diagram caption when rotation/inner affine is baked into paths.
  if (node.diagramShape || ((node.shapeType === 'rectangle' || node.shapeType === 'ellipse') && Boolean(node.body))) return { changed: false, nodes: [node], unsupported: 'Captioned shapes retain their text; partial erasure needs shared caption geometry.' }
  // The CSS rectangle paints a background, inset border and drop shadow.
  // Rebasing it into one SVG path would move that border to a centered stroke
  // and discard the shadow. Preserve it until the whole prepared appearance
  // can be clipped by canonical erasure operands without changing its skin.
  if (node.shapeType === 'rectangle') return { changed: false, nodes: [node], unsupported: 'Rectangle appearance is preserved; erasure needs shared inset-border and shadow paint.' }
  if (node.vectorBoolean && node.vectorBoolean.operation !== 'subtract') return { changed: false, nodes: [node], unsupported: 'Resolve Union/Intersect/Exclude before partial erasure.' }
  if (node.vectorBoolean && (!Array.isArray(node.vectorBoolean.operands) || node.vectorBoolean.operands.length < 2
    || node.vectorBoolean.operands.some(operand => !validEditablePath(operand) || !operand.closed))) return { changed: false, nodes: [node], unsupported: 'Invalid subtraction geometry; the original artwork is preserved.' }
  if (node.shapeType === 'arrow') return { changed: false, nodes: [node], unsupported: 'Arrow semantics are preserved; convert the arrow to an ordinary path before erasing.' }
  const matrix = vectorNodeMatrix(node)
  if (![matrix.a, matrix.b, matrix.c, matrix.d, matrix.e, matrix.f].every(Number.isFinite)
    || Math.abs(matrix.a * matrix.d - matrix.b * matrix.c) < 1e-10) return { changed: false, nodes: [node], unsupported: 'Singular vector transform; the original artwork is preserved.' }
  const worldPath = transformVectorPath(path, matrix)
  if (!validEditablePath(worldPath)) return { changed: false, nodes: [node], unsupported: 'Invalid world geometry; the original artwork is preserved.' }
  if (!path.closed) {
    const erased = eraseVectorPath(worldPath, samples, radius, options.tolerance)
    if (!erased.changed) return { changed: false, nodes: [node] }
    const idFactory = options.idFactory || (() => `path-${crypto.randomUUID()}`)
    // A plain line's displayed width is65% of its saved width and its SVG
    // ignores authored path cap/join fields. Preserve that actual stroke when
    // surviving straight sections become ordinary editable paths.
    const source = node.shapeType === 'line' ? { ...node, body: '', strokeWidth: (node.strokeWidth ?? 2) * .65,
      vectorStrokeCap: 'butt' as const, vectorStrokeJoin: 'miter' as const } : node
    return { changed: true, nodes: erased.paths.map((part, index) => localizeNode({ ...source, id: index ? idFactory() : node.id }, part)) }
  }
  const operands = node.vectorBoolean ? node.vectorBoolean.operands.map((value) => transformVectorPath(value, matrix)) : [worldPath]
  const contours = operands.map((value) => flatten(value, options.tolerance ?? .25))
  const filled = (point: BoardPoint) => inside(point, contours[0], node.vectorFillRule === 'evenodd') && !contours.slice(1).some((contour) => inside(point, contour))
  let hit = samples.some(filled)
  // Crossing a thin object may have no sample inside it. Exact segment distance
  // on the flattened boundary avoids work proportional to artwork size / brush
  // radius (a tiny brush on a million-unit line must not freeze the UI).
  if (!hit) for (const contour of contours) for (let index = 1; index < contour.length && !hit; index++) {
    const a = contour[index - 1], b = contour[index]
    if (samples.length === 1) hit = distanceToSegment(samples[0], a, b) <= radius
    else for (let sample = 1; sample < samples.length && !hit; sample++) hit = segmentDistance(a, b, samples[sample - 1], samples[sample]) <= radius
  }
  if (!hit) return { changed: false, nodes: [node] }
  // Simplify noisy pointer samples before storing portable capsule contours.
  const cutters = vectorEraserCutters(simplify(samples, Math.max(.1, radius / 12)), radius)
  return { changed: true, nodes: [localizeNode(node, operands[0], [...operands, ...cutters])] }
}

export type StrokeProfile = 'uniform' | 'calligraphic-ribbon' | 'taper-both' | 'taper-start' | 'taper-end'

/** Converts an open centerline into an exact closed contour with variable width / calligraphic profile.
 * Preserves smooth Bézier tangents for Vello antialiasing and GPU acceleration. */
export function createTaperedStrokeContour(
  path: VectorPath,
  baseWidth: number,
  profile: StrokeProfile = 'calligraphic-ribbon',
  options: { stepsPerSegment?: number; smoothing?: number } = {},
): VectorPath {
  if (!validEditablePath(path) || path.closed || baseWidth <= 0) return path
  const steps = Math.max(8, options.stepsPerSegment ?? 16)
  const segmentCount = path.points.length - 1
  const totalSamples = segmentCount * steps

  const widthFactor = (u: number): number => {
    switch (profile) {
      case 'calligraphic-ribbon':
        return Math.sin(u * Math.PI) * 1.35 + 0.15
      case 'taper-both':
        return Math.sin(u * Math.PI)
      case 'taper-start':
        return Math.sin((u * Math.PI) / 2)
      case 'taper-end':
        return Math.cos((u * Math.PI) / 2)
      case 'uniform':
      default:
        return 1.0
    }
  }

  const leftPoints: BoardPoint[] = []
  const rightPoints: BoardPoint[] = []

  for (let seg = 0; seg < segmentCount; seg++) {
    const curve = curveFor(path, seg)
    const startStep = seg === 0 ? 0 : 1
    for (let s = startStep; s <= steps; s++) {
      const t = s / steps
      const u = (seg * steps + s) / totalSamples
      const pt = mix(
        mix(mix(curve.p0, curve.p1, t), mix(curve.p1, curve.p2, t), t),
        mix(mix(curve.p1, curve.p2, t), mix(curve.p2, curve.p3, t), t),
        t,
      )
      const dt = 1e-4
      const tA = Math.max(0, t - dt), tB = Math.min(1, t + dt)
      const ptA = mix(
        mix(mix(curve.p0, curve.p1, tA), mix(curve.p1, curve.p2, tA), tA),
        mix(mix(curve.p1, curve.p2, tA), mix(curve.p2, curve.p3, tA), tA),
        tA,
      )
      const ptB = mix(
        mix(mix(curve.p0, curve.p1, tB), mix(curve.p1, curve.p2, tB), tB),
        mix(mix(curve.p1, curve.p2, tB), mix(curve.p2, curve.p3, tB), tB),
        tB,
      )
      const delta = sub(ptB, ptA)
      const len = Math.hypot(delta.x, delta.y) || 1
      const normal = { x: -delta.y / len, y: delta.x / len }
      const halfW = (baseWidth * widthFactor(u)) / 2

      leftPoints.push(add(pt, mul(normal, halfW)))
      rightPoints.push(sub(pt, mul(normal, halfW)))
    }
  }

  const contour = [...leftPoints, ...rightPoints.reverse()]
  return createPencilPath(contour, { closed: true, tolerance: 0.3, smoothing: options.smoothing ?? 0.65 })
}

/** Generates a stylized almond-shaped eye contour with sharp corners and smooth arcs.
 * Used for character illustration and repeat pattern motifs. */
export function createStylizedEyeContour(
  center: BoardPoint,
  width: number,
  height: number,
  pupilRadiusRatio = 0.32,
): { outer: VectorPath; pupil: VectorPath } {
  const hw = width / 2, hh = height / 2
  const kx = hw * 0.55, ky = hh * 0.95
  const outer: VectorPath = {
    version: 1,
    closed: true,
    points: [
      { x: center.x - hw, y: center.y, handleOut: { x: kx, y: -ky }, handleMode: 'corner' },
      { x: center.x, y: center.y - hh, handleIn: { x: -kx * 0.6, y: 0 }, handleOut: { x: kx * 0.6, y: 0 }, handleMode: 'smooth' },
      { x: center.x + hw, y: center.y, handleIn: { x: -kx, y: -ky }, handleOut: { x: -kx, y: ky }, handleMode: 'corner' },
      { x: center.x, y: center.y + hh, handleIn: { x: kx * 0.6, y: 0 }, handleOut: { x: -kx * 0.6, y: 0 }, handleMode: 'smooth' },
    ],
  }
  const pr = Math.min(hw, hh) * pupilRadiusRatio
  const pupil = vectorCircle(center, pr)
  return { outer, pupil }
}

/** Computes zoom-adaptive tolerance in board coordinates so drawing simplification
 * maintains consistent screen-pixel fidelity across any canvas zoom level. */
export function adaptivePencilTolerance(zoom: number, screenTolerancePixels = 1.5): number {
  const safeZoom = Math.max(0.001, Math.min(100, Number.isFinite(zoom) ? zoom : 1))
  return Math.max(0.05, screenTolerancePixels / safeZoom)
}

/** Evaluates the exact cubic Bézier first derivative (velocity vector) B'(t). */
export function cubicDerivative(curve: Cubic, t: number): BoardPoint {
  const u = 1 - t
  // B'(t) = 3(1-t)^2 (p1 - p0) + 6(1-t)t (p2 - p1) + 3t^2 (p3 - p2)
  const d0 = sub(curve.p1, curve.p0)
  const d1 = sub(curve.p2, curve.p1)
  const d2 = sub(curve.p3, curve.p2)
  return {
    x: 3 * u * u * d0.x + 6 * u * t * d1.x + 3 * t * t * d2.x,
    y: 3 * u * u * d0.y + 6 * u * t * d1.y + 3 * t * t * d2.y,
  }
}

/** Computes the arc length of a cubic Bézier curve using 5-point Gauss-Legendre quadrature. */
export function cubicArcLength(curve: Cubic): number {
  // 5-point Gauss-Legendre nodes and weights on [-1, 1] mapped to [0, 1]
  const nodes = [
    0.5,
    0.5 - 0.5 * 0.538469310105683,
    0.5 + 0.5 * 0.538469310105683,
    0.5 - 0.5 * 0.906179845938664,
    0.5 + 0.5 * 0.906179845938664,
  ]
  const weights = [
    0.5 * 0.568888888888889,
    0.5 * 0.478628670499366,
    0.5 * 0.478628670499366,
    0.5 * 0.236926885056189,
    0.5 * 0.236926885056189,
  ]

  let length = 0
  for (let i = 0; i < 5; i++) {
    const vel = cubicDerivative(curve, nodes[i])
    const speed = Math.hypot(vel.x, vel.y)
    length += weights[i] * speed
  }
  return length
}

/** Computes the total arc length of a vector path across all segments. */
export function pathArcLength(path: VectorPath): number {
  if (!path || !path.points || path.points.length < 2) return 0
  const count = path.closed ? path.points.length : path.points.length - 1
  let total = 0
  for (let i = 0; i < count; i++) {
    const c = curveFor(path, i)
    total += cubicArcLength(c)
  }
  return total
}

import type { BoardNode, BoardPoint } from './project'
import { vectorBoardDeltaToLocal, vectorLocalToBoard } from './vector.ts'

type NodeIndex = { byId: Map<string, BoardNode>; duplicates: Set<string> }
function indexNodes(nodes: BoardNode[]): NodeIndex {
  const byId = new Map<string, BoardNode>(), duplicates = new Set<string>()
  for (const node of nodes) { if (byId.has(node.id)) duplicates.add(node.id); byId.set(node.id, node) }
  return { byId, duplicates }
}
const owners = (node: BoardNode) => [
  ...(node.groupId ? [{ id: node.groupId, kind: 'group' }] : []),
  ...(node.parentColumnId ? [{ id: node.parentColumnId, kind: 'column' }] : []),
]

/** Editing inherits both freeform-group and column locks. Corrupt ownership
 * fails closed; no geometry helper may edit through a missing/ambiguous owner. */
function editBlockReason(index: NodeIndex, nodeId: string): string | undefined {
  const stack: { id: string; exit?: boolean; expectedKind?: string }[] = [{ id: nodeId }]
  const active = new Set<string>(), visited = new Set<string>()
  while (stack.length) {
    const item = stack.pop()!
    if (item.exit) { active.delete(item.id); visited.add(item.id); continue }
    if (index.duplicates.has(item.id)) return `Ambiguous duplicate object ID: ${item.id}.`
    const node = index.byId.get(item.id)
    if (!node) return `Missing owner or object: ${item.id}.`
    if (item.expectedKind && node.kind !== item.expectedKind) return `Invalid ${item.expectedKind} owner: ${item.id}.`
    if (active.has(item.id)) return 'Cyclic object ownership; repair the hierarchy before editing.'
    if (visited.has(item.id)) continue
    if (node.locked) return item.id === nodeId ? 'This object is locked.' : `Locked ancestor: ${node.title || node.id}.`
    active.add(item.id); stack.push({ id: item.id, exit: true })
    for (const owner of owners(node)) stack.push({ id: owner.id, expectedKind: owner.kind })
  }
  return undefined
}

export function vectorEditBlockReason(nodes: BoardNode[], nodeId: string): string | undefined {
  return editBlockReason(indexNodes(nodes), nodeId)
}

export type VectorDirectSelectionPolicy = {
  state: 'single' | 'none' | 'multiple' | 'locked' | 'unsupported'
  nodeId?: string
  message: string
}

/** Explicit first-pass policy: anchor indices belong to one editable path only.
 * Simultaneous multi-path anchor editing requires per-node identities and is not
 * silently approximated by applying the first path's indices to other paths. */
export function vectorDirectSelectionPolicy(nodes: BoardNode[], selectedIds: string[]): VectorDirectSelectionPolicy {
  const ids = [...new Set(selectedIds)]
  if (!ids.length) return { state: 'none', message: 'Select one editable path to edit its anchors and segments.' }
  if (ids.length > 1) return { state: 'multiple', message: 'Direct Selection edits one path at a time. Select a single path; simultaneous multi-path anchor editing is not supported yet.' }
  const index = indexNodes(nodes), node = index.byId.get(ids[0]), blocked = editBlockReason(index, ids[0])
  if (blocked) return { state: 'locked', message: blocked }
  if (node?.kind === 'shape' && node.shapeType === 'rectangle' && node.vectorBoolean) return { state: 'unsupported', message: 'This rectangle retains its inset border, shadow and caption with editable erasure cuts. Anchor conversion is unavailable until the complete appearance can be preserved; resize and radius controls remain available.' }
  if (node?.kind !== 'shape' || !node.vectorPath || node.vectorBoolean) return { state: 'unsupported', message: 'Select a single editable path. Live shapes and Boolean results must be converted before anchor editing.' }
  if (!vectorBoardDeltaToLocal(node, { x: 1, y: 0 })) return { state: 'unsupported', message: 'This path has a singular transform. Reset its transform before editing anchors.' }
  return { state: 'single', nodeId: node.id, message: '' }
}

export type VectorEditorControl = { index: number; anchor: BoardPoint; handleIn?: BoardPoint; handleOut?: BoardPoint }

/** HTML controls live inside the outer node container, which already supplies
 * board translation and rotation. Apply ONLY the inner SVG transform here;
 * applying vectorLocalToBoard(node, ...) directly would double that rotation. */
export function vectorEditorControls(node: BoardNode): VectorEditorControl[] {
  if (!node.vectorPath) return []
  const innerNode = { ...node, x: 0, y: 0, rotation: 0 }
  const project = (point: BoardPoint) => vectorLocalToBoard(innerNode, point)
  return node.vectorPath.points.map((point, index) => ({
    index, anchor: project(point),
    ...(point.handleIn ? { handleIn: project({ x: point.x + point.handleIn.x, y: point.y + point.handleIn.y }) } : {}),
    ...(point.handleOut ? { handleOut: project({ x: point.x + point.handleOut.x, y: point.y + point.handleOut.y }) } : {}),
  }))
}

export type VectorEraserScope = { nodeIds: string[]; blocked: { nodeId: string; reason: string }[] }

/** A selected group/frame/column scopes the Eraser to its descendant vectors.
 * Empty selection targets board vectors, never media. Any selection (even an
 * unsupported item) disables the board-wide fallback. Locks remain inherited. */
export function vectorEraserScope(nodes: BoardNode[], selectedIds: string[]): VectorEraserScope {
  const index = indexNodes(nodes), candidates = new Set(selectedIds.length ? selectedIds : nodes.map((node) => node.id))
  const children = new Map<string, string[]>()
  for (const node of nodes) for (const owner of owners(node)) {
    const members = children.get(owner.id)
    if (members) members.push(node.id)
    else children.set(owner.id, [node.id])
  }
  const queue = [...candidates]
  for (let position = 0; position < queue.length; position++) {
    const parent = index.byId.get(queue[position])
    if (!parent || (parent.kind !== 'group' && parent.kind !== 'column')) continue
    for (const child of children.get(parent.id) || []) if (!candidates.has(child)) { candidates.add(child); queue.push(child) }
  }
  const nodeIds: string[] = [], blocked: VectorEraserScope['blocked'] = []
  for (const id of candidates) {
    const node = index.byId.get(id), reason = editBlockReason(index, id)
    if (reason) { blocked.push({ nodeId: id, reason }); continue }
    if (node?.kind === 'shape') nodeIds.push(id)
    else if (selectedIds.includes(id) && node?.kind !== 'group' && node?.kind !== 'column') blocked.push({ nodeId: id, reason: 'Eraser edits vector shapes only; source media is preserved.' })
  }
  return { nodeIds, blocked }
}

