          {!preview && <div className="notebook-add-area"><button type="button" aria-expanded={Boolean(insert && insert.pageId === page.id && !insert.afterId)} aria-haspopup="menu" onClick={(event) => { const origin = event.currentTarget; setInsert((current) => current?.pageId === page.id && !current.afterId ? undefined : { pageId: page.id, origin }) }}>＋ Add module</button>{insert?.pageId === page.id && !insert.afterId && <InsertMenu choose={chooseModule} close={() => setInsert(undefined)} origin={insert.origin} />}</div>}
        </section>)}
      </section>
    </div>
    <footer className="notebook-status"><p role="status" aria-live="polite">{message}</p>{loaded.blocked && <button type="button" onClick={() => { try { const key = `${storageKey}.recovery.${Date.now()}`; localStorage.setItem(key, exportNotebookJson(book)); setMessage(`Saved separate recovery copy: ${key}`) } catch (error) { setSaveError(String(error)) } }}>Save separate recovery copy</button>}{saveError && <p role="alert">{saveError}</p>}</footer>
    {showImport && <ImportDialog current={book} accept={(next) => { commit(next); setPageId(next.pages[0].id); setMessage('Imported validated proof data. Undo restores the previous notebook.') }} close={() => setShowImport(false)} />}
  </main>
}

