import { useMemo, useState } from 'react'
import type { DailyTask, DailyWorksheet, ProjectModel, WorksheetLink } from '../model/project'
import './DailyWorksheets.css'

type Props = { project: ProjectModel; onChange: (worksheets: DailyWorksheet[]) => void; onClose: () => void }

const isoToday = () => new Date().toISOString().slice(0, 10)
const title = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })

export function DailyWorksheets({ project, onChange, onClose }: Props) {
  const [date, setDate] = useState(isoToday)
  const [query, setQuery] = useState('')
  const worksheet = project.worksheets?.find((entry) => entry.date === date) || { date, tasks: [], notesHtml: '<p></p>', updatedAt: new Date().toISOString() }
  const links = useMemo<WorksheetLink[]>(() => [
    ...project.boards.map((entry) => ({ kind: 'board' as const, id: entry.id, label: `Board: ${entry.title}` })),
    ...project.documents.map((entry) => ({ kind: 'document' as const, id: entry.id, label: `Document: ${entry.title}` })),
    ...project.assets.map((entry) => ({ kind: 'asset' as const, id: entry.id, label: `File: ${entry.displayName}` })),
  ], [project])
  const matching = (project.worksheets || []).filter((entry) => !query || `${entry.date} ${entry.notesHtml} ${entry.tasks.map((task) => task.title).join(' ')}`.toLowerCase().includes(query.toLowerCase()))
  const progress = worksheet.tasks.length ? Math.round(worksheet.tasks.filter((task) => task.completed).length / worksheet.tasks.length * 100) : 0
  const commit = (next: DailyWorksheet) => onChange([...(project.worksheets || []).filter((entry) => entry.date !== date), { ...next, updatedAt: new Date().toISOString() }].sort((a, b) => a.date.localeCompare(b.date)))
  const addTask = () => commit({ ...worksheet, tasks: [...worksheet.tasks, { id: crypto.randomUUID(), title: 'New task', completed: false, links: [] }] })
  const previous = [...(project.worksheets || [])].filter((entry) => entry.date < date).sort((a, b) => b.date.localeCompare(a.date))[0]
  const carry = () => previous && commit({ ...worksheet, tasks: [...worksheet.tasks, ...previous.tasks.filter((task) => !task.completed && !worksheet.tasks.some((current) => current.carriedFrom === task.id)).map((task) => ({ ...task, id: crypto.randomUUID(), completed: false, carriedFrom: task.id }))] })
  const exportRange = (print = false) => {
    const contents = matching.map((entry) => `<article><h2>${title(entry.date)}</h2><ul>${entry.tasks.map((task) => `<li>${task.completed ? '✓' : '○'} ${task.title}</li>`).join('')}</ul>${entry.notesHtml}</article>`).join('')
    const html = `<!doctype html><title>${project.title} worksheets</title><style>body{max-width:760px;margin:40px auto;font:16px system-ui}article{break-inside:avoid;border-bottom:1px solid #ccc;padding:16px 0}</style><h1>${project.title} — Daily worksheets</h1>${contents}`
    const blob = new Blob([html], { type: 'text/html' }); const url = URL.createObjectURL(blob)
    if (print) { const win = window.open(url, '_blank'); win?.addEventListener('load', () => win.print()) } else { const a = document.createElement('a'); a.href = url; a.download = `${project.title.replace(/[^a-z0-9]+/gi, '-')}-worksheets.html`; a.click() }
    window.setTimeout(() => URL.revokeObjectURL(url), 1000)
  }
  const month = new Date(`${date}T12:00:00`); const days = Array.from({ length: new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate() }, (_, i) => `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, '0')}-${String(i + 1).padStart(2, '0')}`)
  return <div className="planner-backdrop"><section className="planner-dialog" aria-label="Daily worksheets"><header><div><span>PROJECT CALENDAR</span><h2>Daily worksheets</h2></div><button onClick={onClose}>×</button></header><div className="planner-toolbar"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search worksheets…" /><button onClick={() => exportRange()}>Export HTML</button><button onClick={() => exportRange(true)}>Print / PDF</button></div><div className="planner-layout"><aside><h3>{month.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</h3><div className="calendar-grid">{days.map((day) => { const entry = project.worksheets?.find((item) => item.date === day); const done = entry?.tasks.filter((task) => task.completed).length || 0; return <button className={day === date ? 'active' : ''} onClick={() => setDate(day)} key={day}>{Number(day.slice(-2))}{entry && <i style={{ '--progress': `${entry.tasks.length ? done / entry.tasks.length * 100 : 0}%` } as React.CSSProperties} />}</button> })}</div><h3>Search results</h3><div className="worksheet-search-results">{matching.slice(-12).reverse().map((entry) => <button key={entry.date} onClick={() => setDate(entry.date)}>{entry.date}<small>{entry.tasks.filter((task) => task.completed).length}/{entry.tasks.length} done</small></button>)}</div></aside><main><div className="worksheet-heading"><div><span>{title(date)}</span><strong>{progress}% complete</strong></div><div><button onClick={addTask}>＋ Task</button><button disabled={!previous || !previous.tasks.some((task) => !task.completed)} onClick={carry}>Carry unfinished</button></div></div><div className="task-list">{worksheet.tasks.map((task) => <TaskRow key={task.id} task={task} links={links} onChange={(next) => commit({ ...worksheet, tasks: worksheet.tasks.map((item) => item.id === task.id ? next : item) })} onDelete={() => commit({ ...worksheet, tasks: worksheet.tasks.filter((item) => item.id !== task.id) })} />)}</div><label className="daily-notes"><span>Rich daily notes</span><div contentEditable suppressContentEditableWarning dangerouslySetInnerHTML={{ __html: worksheet.notesHtml }} onBlur={(event) => commit({ ...worksheet, notesHtml: event.currentTarget.innerHTML })} /></label></main></div></section></div>
}

function TaskRow({ task, links, onChange, onDelete }: { task: DailyTask; links: WorksheetLink[]; onChange: (task: DailyTask) => void; onDelete: () => void }) {
  return <div className={`daily-task ${task.completed ? 'done' : ''}`}><input aria-label={`Complete ${task.title}`} type="checkbox" checked={task.completed} onChange={(event) => onChange({ ...task, completed: event.target.checked })} /><input value={task.title} onChange={(event) => onChange({ ...task, title: event.target.value })} /><select value="" aria-label="Link task" onChange={(event) => { const link = links.find((entry) => `${entry.kind}:${entry.id}` === event.target.value); if (link) onChange({ ...task, links: [...task.links, link] }); event.currentTarget.value = '' }}><option value="">Link…</option>{links.map((link) => <option key={`${link.kind}:${link.id}`} value={`${link.kind}:${link.id}`}>{link.label}</option>)}</select>{task.links.map((link) => <button className="task-link" title="Remove link" key={`${link.kind}:${link.id}`} onClick={() => onChange({ ...task, links: task.links.filter((entry) => entry !== link) })}>{link.label}</button>)}<button className="delete-task" onClick={onDelete}>×</button></div>
}

/// <reference lib="webworker" />

type WasmModule = {
  default: (input?: RequestInfo | URL | Response | BufferSource | WebAssembly.Module) => Promise<unknown>
  render_b1_fixture: (width: number, height: number, pathCount: number) => Uint8Array
  render_b1_workload: (
    width: number,
    height: number,
    pathCount: number,
    scale: number,
    panX: number,
    panY: number,
    editIndex: number,
    editDelta: number,
  ) => Uint8Array
}

type Workload = {
  name: string
  width: number
  height: number
  pathCount: number
  scale: number
  panX: number
  panY: number
  editIndex: number
  editDelta: number
}

const sampleCount = 7

function percentile(samples: number[], fraction: number) {
  const sorted = [...samples].sort((a, b) => a - b)
  return sorted[Math.min(sorted.length - 1, Math.ceil(sorted.length * fraction) - 1)]
}

function summary(samples: number[]) {
  return {
    minMs: Math.min(...samples),
    p50Ms: percentile(samples, 0.5),
    p95Ms: percentile(samples, 0.95),
    maxMs: Math.max(...samples),
  }
}

function measurePresentation(pixels: Uint8Array, width: number, height: number) {
  const imageCanvas = new OffscreenCanvas(width, height)
  const imageContext = imageCanvas.getContext('2d')
  if (!imageContext) throw new Error('OffscreenCanvas 2D context is unavailable')
  const imageStartedAt = performance.now()
  imageContext.putImageData(new ImageData(new Uint8ClampedArray(pixels), width, height), 0, 0)
  const putImageDataMs = performance.now() - imageStartedAt

  const textureCanvas = new OffscreenCanvas(width, height)
  const gl = textureCanvas.getContext('webgl2')
  if (!gl) throw new Error('OffscreenCanvas WebGL2 context is unavailable')
  const texture = gl.createTexture()
  if (!texture) throw new Error('Unable to allocate benchmark texture')
  gl.bindTexture(gl.TEXTURE_2D, texture)
  const textureStartedAt = performance.now()
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, width, height, 0, gl.RGBA, gl.UNSIGNED_BYTE, pixels)
  gl.finish()
  const textureUploadMs = performance.now() - textureStartedAt
  gl.deleteTexture(texture)
  return { putImageDataMs, textureUploadMs }
}

self.onmessage = async () => {
  const coldStartedAt = performance.now()
  try {
    const module = await import('./generated/project_b_wasm.js') as WasmModule
    await module.default()
    const wasmStartupMs = performance.now() - coldStartedAt
    const workloads: Workload[] = [
      { name: 'beziers-1k', width: 1024, height: 768, pathCount: 1_000, scale: 1, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'beziers-5k', width: 1024, height: 768, pathCount: 5_000, scale: 1, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'beziers-20k', width: 1024, height: 768, pathCount: 20_000, scale: 1, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'zoom-20k', width: 1024, height: 768, pathCount: 20_000, scale: 1.75, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'pan-20k', width: 1024, height: 768, pathCount: 20_000, scale: 1, panX: 180, panY: -120, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'resize-20k', width: 1440, height: 900, pathCount: 20_000, scale: 1, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'edit-preview-5k', width: 1024, height: 768, pathCount: 5_000, scale: 1, panX: 0, panY: 0, editIndex: 2_499, editDelta: 6 },
    ]
    const cases = []
    let preview: Uint8Array | undefined
    for (const workload of workloads) {
      const firstStartedAt = performance.now()
      module.render_b1_workload(
        workload.width, workload.height, workload.pathCount, workload.scale,
        workload.panX, workload.panY, workload.editIndex, workload.editDelta,
      )
      const firstRenderMs = performance.now() - firstStartedAt
      const renderSamples = []
      const putImageDataSamples = []
      const textureUploadSamples = []
      let pixels: Uint8Array<ArrayBufferLike> = new Uint8Array()
      for (let sample = 0; sample < sampleCount; sample += 1) {
        const renderStartedAt = performance.now()
        pixels = module.render_b1_workload(
          workload.width, workload.height, workload.pathCount, workload.scale,
          workload.panX, workload.panY, workload.editIndex,
          workload.name === 'edit-preview-5k' ? workload.editDelta + sample : workload.editDelta,
        )
        renderSamples.push(performance.now() - renderStartedAt)
        const presentation = measurePresentation(pixels, workload.width, workload.height)
        putImageDataSamples.push(presentation.putImageDataMs)
        textureUploadSamples.push(presentation.textureUploadMs)
      }
      cases.push({
        ...workload,
        samples: sampleCount,
        firstRenderMs,
        render: summary(renderSamples),
        putImageData: summary(putImageDataSamples),
        textureUpload: summary(textureUploadSamples),
        rgbaBufferMiB: pixels.byteLength / (1024 * 1024),
      })
      if (workload.name === 'beziers-5k') preview = new Uint8Array(pixels)
    }
    self.postMessage({ ok: true, wasmStartupMs, width: 1024, height: 768, cases, preview }, preview ? [preview.buffer] : [])
  } catch (error) {
    self.postMessage({ ok: false, error: String(error) })
  }
}

/// <reference lib="webworker" />

type B3Renderer = {
  initialize: () => Promise<string>
  render: (width: number, height: number, pathCount: number) => Promise<void>
  render_workload: (
    width: number,
    height: number,
    pathCount: number,
    scale: number,
    panX: number,
    panY: number,
    editIndex: number,
    editDelta: number,
  ) => Promise<void>
  render_replay: (width: number, height: number) => Promise<string>
  render_real_board: (width: number, height: number) => Promise<string>
  render_overlap_fixture: (width: number, height: number) => Promise<string>
  render_real_board_pixels: (width: number, height: number) => Promise<Uint8Array>
  destroy_device_for_recovery_test: () => void
  free: () => void
}

type WasmModule = {
  default: (input?: RequestInfo | URL | Response | BufferSource | WebAssembly.Module) => Promise<unknown>
  B3Renderer: new () => B3Renderer
}

const sampleCount = 7
let renderer: B3Renderer | undefined
let adapter: Record<string, string> | undefined
let initializationCount = 0
let workerRunCount = 0
let wasmStartupMs = 0
let gpuInitializeMs = 0

async function ensureRenderer() {
  if (renderer) return { reused: true }
  const workerStartedAt = performance.now()
  const module = await import('./generated/project_b_wasm.js') as WasmModule
  await module.default()
  wasmStartupMs = performance.now() - workerStartedAt
  renderer = new module.B3Renderer()
  const initializeStartedAt = performance.now()
  adapter = JSON.parse(await renderer.initialize()) as Record<string, string>
  gpuInitializeMs = performance.now() - initializeStartedAt
  initializationCount += 1
  return { reused: false }
}

function percentile(samples: number[], fraction: number) {
  const sorted = [...samples].sort((a, b) => a - b)
  return sorted[Math.min(sorted.length - 1, Math.ceil(sorted.length * fraction) - 1)]
}

self.onmessage = async (event: MessageEvent<{ type?: string }>) => {
  try {
    if (event.data?.type === 'recover') {
      await ensureRenderer()
      const oldRenderer = renderer
      if (!oldRenderer) throw new Error('Recovery test could not initialize renderer')
      await oldRenderer.render_real_board(1024, 768)
      oldRenderer.destroy_device_for_recovery_test()
      oldRenderer.free()
      renderer = undefined
      const recoveryStartedAt = performance.now()
      await ensureRenderer()
      const recoveredRenderer = renderer as B3Renderer | undefined
      if (!recoveredRenderer) throw new Error('Recovery test could not recreate renderer')
      const report = JSON.parse(await recoveredRenderer.render_real_board(1024, 768)) as Record<string, unknown>
      self.postMessage({
        ok: true,
        recovery: {
          recovered: true,
          elapsedMs: performance.now() - recoveryStartedAt,
          initializationCount,
          report,
        },
      })
      return
    }
    const lifecycle = await ensureRenderer()
    const activeRenderer = renderer
    if (!activeRenderer) throw new Error('Persistent WebGPU renderer failed to initialize')
    workerRunCount += 1
    const cases = []
    const workloads = [
      { name: 'beziers-1k', width: 1024, height: 768, pathCount: 1_000, scale: 1, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'beziers-5k', width: 1024, height: 768, pathCount: 5_000, scale: 1, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'beziers-20k', width: 1024, height: 768, pathCount: 20_000, scale: 1, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'zoom-20k', width: 1024, height: 768, pathCount: 20_000, scale: 1.75, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'pan-20k', width: 1024, height: 768, pathCount: 20_000, scale: 1, panX: 180, panY: -120, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'resize-20k', width: 1440, height: 900, pathCount: 20_000, scale: 1, panX: 0, panY: 0, editIndex: 0xffffffff, editDelta: 0 },
      { name: 'edit-preview-5k', width: 1024, height: 768, pathCount: 5_000, scale: 1, panX: 0, panY: 0, editIndex: 2_499, editDelta: 6 },
    ]
    for (const workload of workloads) {
      const firstStartedAt = performance.now()
      await activeRenderer.render_workload(
        workload.width, workload.height, workload.pathCount, workload.scale,
        workload.panX, workload.panY, workload.editIndex, workload.editDelta,
      )
      const firstRenderMs = performance.now() - firstStartedAt
      const samples = []
      for (let sample = 0; sample < sampleCount; sample += 1) {
        const startedAt = performance.now()
        await activeRenderer.render_workload(
          workload.width, workload.height, workload.pathCount, workload.scale,
          workload.panX, workload.panY, workload.editIndex,
          workload.name === 'edit-preview-5k' ? workload.editDelta + sample : workload.editDelta,
        )
        samples.push(performance.now() - startedAt)
      }
      cases.push({
        ...workload,
        samples: sampleCount,
        firstRenderMs,
        minMs: Math.min(...samples),
        p50Ms: percentile(samples, 0.5),
        p95Ms: percentile(samples, 0.95),
        maxMs: Math.max(...samples),
      })
    }
    const sceneFixtures = []
    for (const fixture of [
      { name: 'frozen-replay-v1', render: () => activeRenderer.render_replay(1600, 1000) },
      { name: 'real-board-sacrificial', render: () => activeRenderer.render_real_board(1024, 768) },
      { name: 'mixed-z-overlap', render: () => activeRenderer.render_overlap_fixture(640, 480) },
    ]) {
      const startedAt = performance.now()
      const report = JSON.parse(await fixture.render()) as Record<string, unknown>
      sceneFixtures.push({ name: fixture.name, elapsedMs: performance.now() - startedAt, ...report })
    }
    const previewWidth = 1024
    const previewHeight = 768
    const presentationStartedAt = performance.now()
    const preview = await activeRenderer.render_real_board_pixels(previewWidth, previewHeight)
    const presentationMs = performance.now() - presentationStartedAt
    const rowBytes = previewWidth * 4
    const paddedRowBytes = Math.ceil(rowBytes / 256) * 256
    const rgbaBytes = rowBytes * previewHeight
    const viewSwitches = []
    for (const mode of ['canvas', 'document', 'split', 'canvas']) {
      const startedAt = performance.now()
      if (mode !== 'document') {
        await activeRenderer.render(1024, 768, 5_000)
      }
      viewSwitches.push({ mode, elapsedMs: performance.now() - startedAt })
    }
    self.postMessage({
      ok: true,
      wasmStartupMs,
      gpuInitializeMs,
      adapter,
      cases,
      sceneFixtures,
      presentation: { width: previewWidth, height: previewHeight, elapsedMs: presentationMs },
      memory: {
        targetTextureBytes: rgbaBytes,
        readbackBufferBytes: paddedRowBytes * previewHeight,
        transferredPreviewBytes: preview.byteLength,
        measuredTransientFloorBytes: rgbaBytes + paddedRowBytes * previewHeight + preview.byteLength,
        scope: 'Known presentation allocations only; excludes driver, pipeline cache and WASM heap.',
      },
      preview,
      lifecycle: {
        reusedExistingRenderer: lifecycle.reused,
        initializationCount,
        workerRunCount,
        viewSwitches,
      },
    }, [preview.buffer])
  } catch (error) {
    self.postMessage({ ok: false, error: String(error) })
  }
}

