let nextWatcherId = 0
const sourceSignature = (video: HTMLVideoElement) => JSON.stringify([
  video.getAttribute('src') ?? '', video.src,
  [...video.querySelectorAll('source')].map(source => [source.getAttribute('src') ?? '', source.getAttribute('type') ?? '']),
])
