import type {CanvasSceneObject,CanvasViewport} from '../../canvas-engine/contracts'
import {imageDrawRect} from '../../model/imageFraming'
import {imageDemand} from '../../canvas-engine/imageDemand'

/** Required physical density, rounded UP to a stable mip bucket. Sources remain
 * unchanged. Rotation/flip are orthogonal; explicit fill uses its largest axis. */
export function modelImageDemand(object:CanvasSceneObject,source:{width:number;height:number},view?:CanvasViewport,dpr=1){
 const frame=object.localBounds!,model=object.modelArtwork
 if(model?.kind!=='image')throw Error('MODEL_IMAGE_DESCRIPTOR_INVALID')
 const fit=imageDrawRect(source,{width:frame.width,height:frame.height-(model.header?.height||0)},model.framing)
 if(!fit)throw Error('MODEL_IMAGE_FRAMING_INVALID')
 const demand=view?imageDemand(source.width,source.height,[fit.scaleX,0,0,fit.scaleY,0,0],view.scale*dpr):{...source,divisor:1}
 return {...demand,sourceWidth:source.width,sourceHeight:source.height}
}

import type {CanvasSceneObject,CanvasViewport,CanvasSize} from '../../canvas-engine/contracts'
import {imageDrawRect} from '../../model/imageFraming'
import {planPyramid,requiredPyramidLevel,validPyramid} from '../../canvas-engine/imagePyramid'
import type {PaintMatrix} from '../../canvas-engine/paintDisplayList'

/** Camera and authored transforms are the only tile-demand geometry inputs. */
export function planModelImageTiles(object:CanvasSceneObject,view:CanvasViewport,size:CanvasSize,dpr:number) {
 const model=object.modelArtwork,frame=object.localBounds
 if(model?.kind!=='image'||!validPyramid(model.pyramid)||!frame||!size.width||!size.height)throw Error('MODEL_TILE_DESCRIPTOR_INVALID')
 const p=model.pyramid,top=model.header?.height||0,height=frame.height-top
 const fit=imageDrawRect(p,{width:frame.width,height},model.framing)
 if(!fit||!Number.isFinite(dpr)||dpr<=0||!Number.isFinite(view.scale)||view.scale<=0)throw Error('MODEL_TILE_VIEW_INVALID')
 const angle=object.appearance.rotation*Math.PI/180,c=Math.cos(angle),s=Math.sin(angle)
 const imageAngle=(model.framing?.rotation||0)*Math.PI/180,rc=Math.cos(imageAngle),rs=Math.sin(imageAngle),fx=model.framing?.flipX?-1:1,fy=model.framing?.flipY?-1:1
 const ia=rc*fx,ib=rs*fx,ic=-rs*fy,id=rc*fy
 const tx=frame.x+frame.width/2-c*frame.width/2+s*frame.height/2,ty=frame.y+frame.height/2-s*frame.width/2-c*frame.height/2
 const x=frame.width/2+ia*(fit.x-frame.width/2)+ic*(fit.y-height/2),y=top+height/2+ib*(fit.x-frame.width/2)+id*(fit.y-height/2)
 const matrix:PaintMatrix=[(c*ia-s*ib)*fit.scaleX,(s*ia+c*ib)*fit.scaleX,(c*ic-s*id)*fit.scaleY,(s*ic+c*id)*fit.scaleY,tx+c*x-s*y,ty+s*x+c*y]
 const [a,b,cc,d,e,f]=matrix,det=a*d-b*cc
 if(Math.abs(det)<1e-12)throw Error('MODEL_TILE_TRANSFORM_INVALID')
 const points=[[0,0],[size.width,0],[size.width,size.height],[0,size.height]].map(([sx,sy])=>{const wx=(sx-view.x)/view.scale-e,wy=(sy-view.y)/view.scale-f;return {x:(d*wx-cc*wy)/det,y:(a*wy-b*wx)/det}})
 const left=Math.max(0,Math.min(...points.map(p=>p.x))),upper=Math.max(0,Math.min(...points.map(p=>p.y)))
 const crop={x:left,y:upper,width:Math.max(0,Math.min(p.width,Math.max(...points.map(p=>p.x)))-left),height:Math.max(0,Math.min(p.height,Math.max(...points.map(p=>p.y)))-upper)}
 const density=Math.max(fit.scaleX,fit.scaleY)*view.scale*dpr,tiles=planPyramid(p,crop,density)
 return {matrix,fit,tiles,requiredLevel:requiredPyramidLevel(p,density),density,top,height,crop}
}

import type { CanvasSceneObject } from '../../canvas-engine/contracts'
import type { CompleteCardPaintResult } from '../../canvas-engine/completePaint'

// Scene objects are immutable. Camera requests reuse their identities and must
// not serialize every rich-text/media descriptor again on each pointer sample.
const paintKeys=new WeakMap<CanvasSceneObject,Map<string,string>>()

/** Position/order/selection are not glyph or decoded-image inputs. Saved
 * geometry dimensions, all paint styles and source descriptors remain inputs.
 * Rotations deliberately require recompilation until affine parity is tested. */
export function modelPaintKey(sceneId: string, object: CanvasSceneObject): string {
  let keys=paintKeys.get(object)
  const existing=keys?.get(sceneId);if(existing!==undefined)return existing
  const key=JSON.stringify([sceneId,object.id,object.localBounds?.width,object.localBounds?.height,
    object.appearance,object.structuredCard,object.modelArtwork,object.modelPorts])
  if(!keys){keys=new Map();paintKeys.set(object,keys)}
  if(keys.size>=8)keys.delete(keys.keys().next().value!)
  keys.set(sceneId,key);return key
}

export function moveModelPaint(card: CompleteCardPaintResult, previous: CanvasSceneObject, next: CanvasSceneObject): CompleteCardPaintResult {
  if(previous===next)return card
  const dx=next.localBounds!.x-previous.localBounds!.x,dy=next.localBounds!.y-previous.localBounds!.y
  if(!dx&&!dy)return {...card,objectRevision:next.revision,order:next.order}
  const operations=card.operations.map(operation=>{
    if(operation.type==='pop')return operation
    if(operation.type==='vector'){
      const matrix=operation.object.transform as readonly number[]|undefined
      if(!matrix||matrix.length!==6)throw Error('MODEL_RETAINED_TRANSFORM_MISSING')
      return {...operation,object:{...operation.object,transform:[...matrix.slice(0,4),matrix[4]+dx,matrix[5]+dy]}}
    }
    return {...operation,transform:[...operation.transform.slice(0,4),operation.transform[4]+dx,operation.transform[5]+dy] as [number,number,number,number,number,number]}
  })
  return {...card,objectRevision:next.revision,order:next.order,operations,visualBounds:card.visualBounds?{...card.visualBounds,x:card.visualBounds.x+dx,y:card.visualBounds.y+dy}:null}
}

import {appendAssetPathUrl} from '../../canvas-engine/assetPathUrl'
import type {CanvasSceneObject,CanvasViewport,CanvasSize} from '../../canvas-engine/contracts'
import type {PaintOperation,DecodedImageUpload,PaintMatrix} from '../../canvas-engine/paintDisplayList'
import type {DecodedImageRegistry} from '../../canvas-engine/decodedImageRegistry'
import {canvasResourceBudget} from '../../canvas-engine/resourceBudget'
import {metricSpan,recordMetric} from '../../diagnostics/performance'
import {planModelImageTiles} from './modelImageTiles'
import {planPyramid,planDirectionalPrefetch,type PyramidTile} from '../../canvas-engine/imagePyramid'
import type {ModelTileStream} from './modelTileStream'
