export type VelloBackend = 'gpu' | 'cpu'
export type VelloFrame = {
  generation: number
  snapshot: string
  displayList?: import('../../canvas-engine/paintDisplayList').PreparedPaintDisplayList
  width: number
  height: number
  scale: number
  panX: number
  panY: number
  /** Immutable canonical premultiplied sRGB pixels; never GPU readback. */
  images?: readonly DecodedImageUpload[]
}
export type FrameMetadata = Record<string, unknown> & { width: number; height: number }
export type GpuSession = {
  canvas: HTMLCanvasElement
  prepare(frame: VelloFrame): Promise<FrameMetadata>
  present(): FrameMetadata
  discard(): void
  dispose(): void
  destroyForTest?(): void
  checkHealth?(): void
}
export type CpuSession = {
  render(frame: VelloFrame): Promise<{ pixels: Uint8Array<ArrayBuffer>; metadata: FrameMetadata; release?():void }>
  dispose(): void
  reusableSurfaceBytes?(): number
}
export type PresenterCallbacks = {
  accepted(result: { generation: number; backend: VelloBackend; canvas: HTMLCanvasElement; metadata: FrameMetadata; frame: VelloFrame }): void
  error(result: { generation: number; backend: VelloBackend; error: string }): void
  state?(result: { backend: VelloBackend; state: 'loading' | 'ready' | 'fallback' | 'paused' | 'error'; reason?: string }): void
  /** Includes recovery/health retries of a previously accepted frame. */
  preparing?(generation:number):void
  /** Snapshot/image pins may retire only when neither an active transport nor
   * queued fallback/recovery attempt still owns this generation. */
  settled?(generation:number):void
}
export type PresenterDependencies = {
  createCanvas(): HTMLCanvasElement
  createGpu(canvas: HTMLCanvasElement): Promise<GpuSession>
  createCpu(): CpuSession
  hidden(): boolean
  watchHealth(check: () => void): () => void
}
import type { DecodedImageUpload } from '../../canvas-engine/paintDisplayList'

/** Actual viewport-session preparation, independent of native helper devices. */
let snapshot: Readonly<{ pending: number; ready: number; failed: number }> = Object.freeze({ pending: 0, ready: 0, failed: 0 })
const listeners = new Set<() => void>()
export const viewportWarmup = {
  getSnapshot: () => snapshot,
  subscribe(listener: () => void) { listeners.add(listener); return () => { listeners.delete(listener) } },
  begin() {
    snapshot = Object.freeze({ ...snapshot, pending: snapshot.pending + 1 })
    for (const listener of listeners) listener()
    let finished = false
    return (success: boolean) => {
      if (finished) return
      finished = true
      snapshot = Object.freeze({ pending: snapshot.pending - 1, ready: snapshot.ready + Number(success), failed: snapshot.failed + Number(!success) })
      for (const listener of listeners) listener()
    }
  },
}

export type ProjectBPreflightReport = {
  measuredAt: string
  userAgent: string
  webView2Runtime?: string
  webGpu: {
    available: boolean
    adapterAvailable: boolean
    requestAdapterMs?: number
    info?: Record<string, unknown>
    error?: string
  }
  wasmWorker: Record<string, unknown>
  gpuRenderer?: Record<string, unknown>
}

declare global {
  interface Window {
    __projectBPreflight?: Promise<ProjectBPreflightReport>
  }
}

async function probeWebGpu(): Promise<ProjectBPreflightReport['webGpu']> {
  const gpu = (navigator as Navigator & { gpu?: { requestAdapter: () => Promise<unknown> } }).gpu
  if (!gpu) return { available: false, adapterAvailable: false }
  const startedAt = performance.now()
  try {
    const adapter = await gpu.requestAdapter() as {
      info?: { vendor?: string; architecture?: string; device?: string; description?: string }
    } | null
    const adapterInfo = adapter?.info
    return {
      available: true,
      adapterAvailable: Boolean(adapter),
      requestAdapterMs: performance.now() - startedAt,
      info: adapterInfo ? {
        vendor: adapterInfo.vendor || '',
        architecture: adapterInfo.architecture || '',
        device: adapterInfo.device || '',
        description: adapterInfo.description || '',
      } : undefined,
    }
  } catch (error) {
    return { available: true, adapterAvailable: false, requestAdapterMs: performance.now() - startedAt, error: String(error) }
  }
}

function probeWasmWorker(): Promise<Record<string, unknown>> {
  return new Promise((resolve) => {
    const worker = new Worker(new URL('./preflightWorker.ts', import.meta.url), { type: 'module' })
    const timeout = window.setTimeout(() => {
      worker.terminate()
      resolve({ ok: false, error: 'worker timed out after 15 seconds' })
    }, 15_000)
    worker.onmessage = ({ data }) => {
      window.clearTimeout(timeout)
      worker.terminate()
      resolve(data as Record<string, unknown>)
    }
    worker.onerror = (event) => {
      window.clearTimeout(timeout)
      worker.terminate()
      resolve({ ok: false, error: event.message })
    }
    worker.postMessage('run')
  })
}

function probeGpuRendererWorker(): Promise<Record<string, unknown>> {
  return new Promise((resolve) => {
    const worker = new Worker(new URL('./b3Worker.ts', import.meta.url), { type: 'module' })
    const runs: Array<Record<string, unknown>> = []
    const timeout = window.setTimeout(() => {
      worker.terminate()
      resolve({ ok: false, error: 'persistent GPU renderer timed out after 45 seconds', runs })
    }, 45_000)
    worker.onmessage = ({ data }: MessageEvent<Record<string, unknown> & { preview?: Uint8Array }>) => {
      const { preview: _preview, cases, ...compact } = data
      runs.push({ ...compact, cases })
      if (data.ok === false || runs.length === 2) {
        window.clearTimeout(timeout)
        worker.terminate()
        resolve({ ok: data.ok !== false, runs })
      } else {
        worker.postMessage({ type: 'run' })
      }
    }
    worker.onerror = (event) => {
      window.clearTimeout(timeout)
      worker.terminate()
      resolve({ ok: false, error: event.message, runs })
    }
    worker.postMessage({ type: 'run' })
  })
}

export function startProjectBPreflight() {
  const queryEnabled = new URLSearchParams(window.location.search).get('project-b-preflight') === '1'
  const run = async (webview2Runtime?: string) => {
    const [webGpu, wasmWorker, gpuRenderer] = await Promise.all([
      probeWebGpu(),
      probeWasmWorker(),
      probeGpuRendererWorker(),
    ])
    const report = { measuredAt: new Date().toISOString(), userAgent: navigator.userAgent, webView2Runtime: webview2Runtime, webGpu, wasmWorker, gpuRenderer }
    console.info('[Project B pre-flight]', report)
    void invoke('record_project_b_preflight', { report }).catch(() => undefined)
    return report
  }
  if (queryEnabled) {
    window.__projectBPreflight = run()
    return
  }
  void invoke<{ enabled: boolean; webview2Runtime?: string }>('project_b_preflight_context')
    .then(({ enabled, webview2Runtime }) => {
      if (enabled) window.__projectBPreflight = run(webview2Runtime)
    })
    .catch(() => undefined)
}
import { invoke } from '@tauri-apps/api/core'

/// <reference lib="webworker" />

type WasmModule = {
  default: (input?: RequestInfo | URL | Response | BufferSource | WebAssembly.Module) => Promise<unknown>
  project_b_preflight: () => string
}

self.onmessage = async () => {
  const startedAt = performance.now()
  try {
    const module = await import('./generated/project_b_wasm.js') as WasmModule
    await module.default()
    const result = JSON.parse(module.project_b_preflight())
    self.postMessage({ ok: true, elapsedMs: performance.now() - startedAt, result })
  } catch (error) {
    self.postMessage({ ok: false, elapsedMs: performance.now() - startedAt, error: String(error) })
  }
}

let worker: Worker | undefined
let nextId = 1
const requests = new Map<number, { resolve: (value: ImageData) => void; reject: (reason: unknown) => void }>()

function persistentWorker() {
  if (worker) return worker
  worker = new Worker(new URL('./productionWorker.ts', import.meta.url), { type: 'module' })
  worker.onmessage = (event: MessageEvent<{ id: number; ok: boolean; width: number; height: number; pixels?: Uint8Array; error?: string }>) => {
    const request = requests.get(event.data.id)
    if (!request) return
    requests.delete(event.data.id)
    if (!event.data.ok || !event.data.pixels) request.reject(new Error(event.data.error || 'Vello render failed'))
    else request.resolve(new ImageData(new Uint8ClampedArray(event.data.pixels), event.data.width, event.data.height))
  }
  worker.onerror = (event) => {
    for (const request of requests.values()) request.reject(new Error(event.message))
    requests.clear(); worker?.terminate(); worker = undefined
  }
  return worker
}

export function renderVelloScene(input: { width: number; height: number; snapshot: string; scale: number; panX: number; panY: number }) {
  const id = nextId++
  return new Promise<ImageData>((resolve, reject) => {
    requests.set(id, { resolve, reject })
    persistentWorker().postMessage({ id, ...input })
  })
}

/// <reference lib="webworker" />

type Renderer = {
  initialize: () => Promise<string>
  render_snapshot_pixels: (width: number, height: number, snapshot: string, scale: number, panX: number, panY: number) => Promise<Uint8Array>
}

let rendererPromise: Promise<Renderer> | undefined

function renderer() {
  if (!rendererPromise) rendererPromise = (async () => {
    const wasm = await import('./generated/project_b_wasm.js')
    await wasm.default()
    const next = new wasm.B3Renderer() as Renderer
    await next.initialize()
    return next
  })()
  return rendererPromise
}

let work = Promise.resolve()
let latestId = 0
self.onmessage = (event: MessageEvent<{ id: number; width: number; height: number; snapshot: string; scale: number; panX: number; panY: number }>) => {
  latestId = event.data.id
  work = work.then(async () => {
    const request = event.data
    if (request.id < latestId) {
      self.postMessage({ id: request.id, ok: false, error: 'superseded' })
      return
    }
    try {
      const active = await renderer()
      if (request.id < latestId) {
        self.postMessage({ id: request.id, ok: false, error: 'superseded' })
        return
      }
      const pixels = await active.render_snapshot_pixels(request.width, request.height, request.snapshot, request.scale, request.panX, request.panY)
      if (request.id < latestId) {
        self.postMessage({ id: request.id, ok: false, error: 'superseded' })
        return
      }
      self.postMessage({ id: request.id, ok: true, width: request.width, height: request.height, pixels }, [pixels.buffer])
    } catch (error) {
      rendererPromise = undefined
      self.postMessage({ id: request.id, ok: false, error: String(error) })
    }
  })
}

