import { useEffect, useRef, useState, type CSSProperties } from 'react'
import './projectIdentity.css'

type Phase = 'ready' | 'loading' | 'playing' | 'paused' | 'away' | 'finished' | 'error'
type Clip = 'retreat' | 'pass'
export type ProjectIdentityProps = { reduceMotion?: boolean; active?: boolean; onStatus?: (message: string) => void }
const media = (name: string) => `${import.meta.env.BASE_URL}aquarium-header/${name}`

/** Decorative aquarium only. Project title and commands remain owned by App. */
export function ProjectIdentity({ reduceMotion = false, active = true, onStatus }: ProjectIdentityProps = {}) {
  const video = useRef<HTMLVideoElement>(null)
  const waterVideo = useRef<HTMLVideoElement>(null)
  const request = useRef(0)
  const waterRequest = useRef(0)
  const statusRef = useRef(onStatus)
  statusRef.current = onStatus
  const [clip, setClip] = useState<Clip>('retreat')
  const [attempt, setAttempt] = useState(0)
  const [phase, setPhase] = useState<Phase>('ready')
  const [systemReduced, setSystemReduced] = useState(() => typeof window !== 'undefined' && typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches)
  const [visible, setVisible] = useState(() => typeof document === 'undefined' || !document.hidden)
  const [motionPaused, setMotionPaused] = useState(false)
  const [hasVideoFrame, setHasVideoFrame] = useState(false)
  const [waterPlaying, setWaterPlaying] = useState(false)
  const reduced = reduceMotion || systemReduced
  const suspended = !active || !visible
  const still = reduced || motionPaused || suspended
  const announce = (message: string) => statusRef.current?.(message)

  useEffect(() => {
    if (typeof window.matchMedia !== 'function') return
    const query = window.matchMedia('(prefers-reduced-motion: reduce)')
    const change = () => setSystemReduced(query.matches)
    query.addEventListener('change', change)
    return () => query.removeEventListener('change', change)
  }, [])
  useEffect(() => {
    const change = () => setVisible(!document.hidden)
    document.addEventListener('visibilitychange', change)
    return () => document.removeEventListener('visibilitychange', change)
  }, [])
  useEffect(() => {
    const current = waterVideo.current, token = ++waterRequest.current
    if (!current) return
    if (still) { current.pause(); setWaterPlaying(false); return }
    current.muted = true
    void current.play().then(() => { if (waterRequest.current === token) setWaterPlaying(true) }).catch(() => { if (waterRequest.current === token) setWaterPlaying(false) })
    return () => { waterRequest.current++; current.pause() }
  }, [still])
  useEffect(() => {
    if (still && (phase === 'playing' || phase === 'loading')) { request.current++; video.current?.pause(); setPhase('paused') }
    if (reduced) setHasVideoFrame(false)
  }, [still, reduced, phase])
  useEffect(() => {
    if (phase !== 'loading' || still) return
    const current = video.current, token = ++request.current
    if (!current) return
    current.muted = true
    void current.play().then(() => {
      if (request.current === token) { setHasVideoFrame(true); setPhase('playing') }
    }).catch(() => {
      if (request.current === token) { setHasVideoFrame(false); setPhase('error'); announce('Aquarium playback unavailable. A still image is shown.') }
    })
    return () => { request.current++ }
  }, [clip, phase, still, attempt])
  useEffect(() => () => { request.current++; waterRequest.current++; video.current?.pause(); waterVideo.current?.pause() }, [])

  const reset = () => {
    request.current++; video.current?.pause(); setHasVideoFrame(false); setAttempt(value => value + 1); setClip('retreat'); setPhase('ready')
    announce('Fish returned to the foreground')
  }
  const begin = (next: Clip) => {
    if (reduced || suspended || motionPaused) return
    request.current++; video.current?.pause(); setHasVideoFrame(false); setClip(next); setAttempt(value => value + 1); setPhase('loading')
    announce(next === 'retreat' ? 'Fish swimming into the distance' : 'Fish swimming across the tank')
  }
  const toggleMotion = () => {
    if (reduced || suspended) return
    request.current++
    if (motionPaused) { setMotionPaused(false); if (phase === 'paused') setPhase('loading') }
    else { setMotionPaused(true); video.current?.pause(); if (phase === 'playing' || phase === 'loading') setPhase('paused') }
  }
  const fishAction = () => {
    if (suspended) return
    if (reduced) { setHasVideoFrame(false); setClip('retreat'); setPhase(phase === 'away' ? 'ready' : 'away'); announce(phase === 'away' ? 'Fish returned to the foreground' : 'Fish in the distance · still image'); return }
    if (motionPaused) { setMotionPaused(false); if (phase === 'paused') setPhase('loading'); else if (phase === 'away' || phase === 'finished') reset(); else { request.current++; setAttempt(value => value + 1); setClip('retreat'); setHasVideoFrame(false); setPhase('loading') } return }
    if (phase === 'away' || phase === 'finished') { reset(); return }
    if (phase === 'playing' || phase === 'loading') { toggleMotion(); return }
    if (phase === 'paused') { setMotionPaused(false); setPhase('loading'); return }
    begin('retreat')
  }
  const actionLabel = reduced ? (phase === 'away' ? 'Show fish in foreground' : 'Show fish in distance') : phase === 'away' || phase === 'finished' ? 'Bring fish back' : phase === 'playing' || phase === 'loading' ? 'Pause fish motion' : phase === 'paused' ? 'Resume fish motion' : 'Send fish swimming away'
  const status = reduced ? 'Still images' : suspended ? 'Motion suspended' : phase === 'loading' ? 'Loading…' : phase === 'playing' ? (clip === 'retreat' ? 'Swimming away' : 'Swimming pass') : phase === 'paused' ? 'Paused' : phase === 'away' ? 'In the distance' : phase === 'finished' ? 'Pass finished' : phase === 'error' ? 'Playback unavailable' : 'Click the fish'
  const showVideo = hasVideoFrame && !reduced && ['playing', 'loading', 'paused', 'away', 'finished'].includes(phase)
  const poster = media(phase === 'away' ? 'away-poster.jpg' : 'near-poster.jpg')
  return <>
    <div className="project-identity aquarium-scene" data-aquarium-state={phase} data-motion={reduced ? 'reduced' : suspended ? 'suspended' : motionPaused ? 'paused' : 'active'}>
      <img className="aquarium-poster" src={poster} alt="" draggable={false} aria-hidden="true" />
      <video ref={video} key={`${clip}-${attempt}`} src={media(clip === 'retreat' ? 'fish-retreat.mp4' : 'fish-swimming-pass.mp4')} poster={poster} preload="none" playsInline muted disablePictureInPicture aria-hidden="true" className={showVideo ? 'aquarium-video visible' : 'aquarium-video'} onEnded={event => {
        if (still || event.currentTarget !== video.current || !event.currentTarget.ended || !['loading', 'playing'].includes(phase)) return
        setPhase(clip === 'retreat' ? 'away' : 'finished'); announce(clip === 'retreat' ? 'Fish in the distance. Bring it back when ready.' : 'Swimming pass finished. Bring the fish back when ready.')
      }} onError={event => {
        if (still || event.currentTarget !== video.current || !event.currentTarget.error || !['loading', 'playing', 'paused'].includes(phase)) return
        request.current++; setHasVideoFrame(false); setPhase('error'); announce('Aquarium playback unavailable. A still image is shown.')
      }} />
      <button type="button" className="aquarium-fish-action" aria-label={actionLabel} title={actionLabel} onClick={fishAction} />
      <span className="identity-wordmark" aria-hidden="true">Art Equation</span>
      <div className="aquarium-controls">
        <span className="aquarium-status" role="status" aria-live="polite" aria-atomic="true">{status}</span>
        <button type="button" aria-label={phase === 'error' ? 'Retry aquarium playback' : 'Play swimming pass'} title={phase === 'error' ? 'Retry aquarium playback' : 'Play swimming pass'} disabled={still} onClick={() => begin(phase === 'error' ? clip : 'pass')}>{phase === 'error' ? 'Retry' : '▷'}</button>
        <button type="button" aria-label={motionPaused ? 'Resume aquarium motion' : 'Pause aquarium motion'} aria-pressed={motionPaused || reduced} disabled={reduced || suspended} title={reduced ? 'Reduced motion uses still images' : motionPaused ? 'Resume aquarium motion' : 'Pause aquarium motion'} onClick={toggleMotion}>{motionPaused || reduced ? '▷' : 'Ⅱ'}</button>
        {phase !== 'ready' && <button type="button" aria-label="Reset aquarium" title="Reset aquarium" onClick={reset}>↺</button>}
      </div>
    </div>
    <div className="aquarium-water-band" style={{ '--aquarium-water': `url("${media('water-texture.png')}")` } as CSSProperties} aria-hidden="true">
      <div className="aquarium-water-poster" />
      <video ref={waterVideo} src={media('water-loop.mp4')} preload="none" playsInline muted loop disablePictureInPicture aria-hidden="true" className={waterPlaying ? 'aquarium-water-video visible' : 'aquarium-water-video'} onError={event => {
        if (event.currentTarget !== waterVideo.current || !event.currentTarget.error) return
        waterRequest.current++; setWaterPlaying(false)
      }} />
    </div>
  </>
}

import { useMemo, useState } from 'react'
import type { ProjectModel, PromptDraft, PromptMode, VisualRecipe } from '../model/project'
import './PromptGenerator.css'

type Props = { project: ProjectModel; recipes: VisualRecipe[]; onHistoryChange: (history: PromptDraft[]) => void; onRecipesChange: (recipes: VisualRecipe[]) => void; onClose: () => void }
const blank = (): PromptDraft => ({ id: crypto.randomUUID(), createdAt: new Date().toISOString(), mode: 'generate', targetModel: 'Generic image model', subject: '', composition: '', camera: '', materials: '', lighting: '', consistency: '', negative: '', prompt: '' })
const models = ['Generic image model', 'GPT Image', 'Midjourney', 'Stable Diffusion', 'FLUX', 'Adobe Firefly']
export function PromptGenerator({ project, recipes, onHistoryChange, onRecipesChange, onClose }: Props) {
  const [draft, setDraft] = useState<PromptDraft>(blank); const [historyQuery, setHistoryQuery] = useState('')
  const references = useMemo(() => project.assets.filter((asset) => asset.kind === 'image').map((asset) => ({ id: asset.id, label: asset.displayName })), [project.assets])
  const generate = () => { const sections = [[draft.mode === 'generate' ? 'Create' : draft.mode === 'edit' ? 'Edit the reference image to show' : draft.mode === 'restyle' ? 'Restyle the reference image as' : 'Unify the reference images into', draft.subject], ['Composition', draft.composition], ['Camera', draft.camera], ['Materials', draft.materials], ['Lighting', draft.lighting], ['Consistency requirements', draft.consistency], ['Avoid', draft.negative]].filter(([, value]) => value).map(([label, value]) => `${label}: ${value}`).join('. '); setDraft((current) => ({ ...current, prompt: sections })) }
  const save = () => onHistoryChange([{ ...draft, createdAt: new Date().toISOString() }, ...(project.promptHistory || []).filter((entry) => entry.id !== draft.id)].slice(0, 100))
  const copy = async () => { await navigator.clipboard?.writeText(draft.prompt); save() }
  const saveRecipe = () => { const recipe: VisualRecipe = { id: crypto.randomUUID(), title: `${draft.subject || 'Prompt'} variation`, category: 'Prompt', problem: draft.negative, procedure: draft.prompt, applications: [draft.targetModel], tools: [], aiModels: [draft.targetModel], variationOf: undefined, updatedAt: new Date().toISOString() }; onRecipesChange([...recipes, recipe]); save() }
  const history = (project.promptHistory || []).filter((entry) => !historyQuery || `${entry.prompt} ${entry.subject}`.toLowerCase().includes(historyQuery.toLowerCase()))
  return <div className="prompt-backdrop"><section className="prompt-dialog"><header><div><span>LOCAL TEMPLATE WORKSPACE</span><h2>Prompt generator</h2></div><button onClick={onClose}>×</button></header><div className="prompt-layout"><main><div className="prompt-top"><select value={draft.mode} onChange={(event) => setDraft({ ...draft, mode: event.target.value as PromptMode })}><option value="generate">Generate</option><option value="edit">Edit</option><option value="restyle">Restyle</option><option value="unify">Unify</option></select><select value={draft.targetModel} onChange={(event) => setDraft({ ...draft, targetModel: event.target.value })}>{models.map((model) => <option key={model}>{model}</option>)}</select><select value={draft.referenceAssetId || ''} onChange={(event) => setDraft({ ...draft, referenceAssetId: event.target.value || undefined })}><option value="">Reference image…</option>{references.map((reference) => <option key={reference.id} value={reference.id}>{reference.label}</option>)}</select></div><div className="prompt-fields">{([['subject', 'Subject'], ['composition', 'Composition'], ['camera', 'Camera'], ['materials', 'Materials'], ['lighting', 'Lighting'], ['consistency', 'Consistency requirements'], ['negative', 'Negative constraints']] as const).map(([key, label]) => <label key={key}>{label}<textarea value={draft[key]} onChange={(event) => setDraft({ ...draft, [key]: event.target.value })}/></label>)}</div><div className="prompt-output"><div><strong>Generated prompt</strong><button onClick={generate}>Generate locally</button><button onClick={copy}>Copy</button><button onClick={saveRecipe}>Save as recipe variation</button></div><textarea value={draft.prompt} placeholder="Your generated prompt will appear here." onChange={(event) => setDraft({ ...draft, prompt: event.target.value })}/></div></main><aside><input type="search" value={historyQuery} onChange={(event) => setHistoryQuery(event.target.value)} placeholder="Search prompt history…"/><button className="history-new" onClick={() => setDraft(blank())}>＋ New prompt</button><h3>History</h3>{history.map((entry) => <button className="prompt-history" key={entry.id} onClick={() => setDraft(entry)}><strong>{entry.subject || 'Untitled prompt'}</strong><small>{entry.mode} · {new Date(entry.createdAt).toLocaleDateString()}</small><span>{entry.prompt}</span></button>)}</aside></div></section></div>
}

import { useMemo, useRef, useState } from 'react'
import type { ProjectModel, VisualRecipe } from '../model/project'
import './RecipeLibrary.css'

type Props = { project: ProjectModel; recipes: VisualRecipe[]; onRecipesChange: (recipes: VisualRecipe[]) => void; onProjectSnapshotsChange: (recipes: VisualRecipe[]) => void; onClose: () => void }
const blank = (): VisualRecipe => ({ id: crypto.randomUUID(), title: 'Untitled recipe', category: 'General', problem: '', procedure: '', applications: [], tools: [], aiModels: [], updatedAt: new Date().toISOString() })
const words = (value: string) => value.split(',').map((word) => word.trim()).filter(Boolean)

export function RecipeLibrary({ project, recipes, onRecipesChange, onProjectSnapshotsChange, onClose }: Props) {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('all'); const [favorites, setFavorites] = useState(false); const [selectedId, setSelectedId] = useState<string | null>(recipes[0]?.id || null); const fileRef = useRef<HTMLInputElement>(null)
  const selected = recipes.find((recipe) => recipe.id === selectedId)
  const visible = useMemo(() => recipes.filter((recipe) => (!query || `${recipe.title} ${recipe.category} ${recipe.problem} ${recipe.procedure}`.toLowerCase().includes(query.toLowerCase())) && (category === 'all' || recipe.category === category) && (!favorites || recipe.favorite)), [recipes, query, category, favorites])
  const update = (next: VisualRecipe) => onRecipesChange(recipes.map((recipe) => recipe.id === next.id ? { ...next, updatedAt: new Date().toISOString() } : recipe))
  const attach = () => { if (!selected) return; const attached = { ...selected, usedByProjectIds: [...new Set([...(selected.usedByProjectIds || []), project.id])] }; update(attached); onProjectSnapshotsChange([...(project.recipeSnapshots || []).filter((recipe) => recipe.id !== selected.id), attached]) }
  const exportPack = () => { const url = URL.createObjectURL(new Blob([JSON.stringify(recipes, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = 'art-equation-recipes.json'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
  const importPack = async (file?: File) => { if (!file) return; try { const incoming = JSON.parse(await file.text()) as VisualRecipe[]; if (!Array.isArray(incoming)) throw new Error(); const byId = new Map(recipes.map((recipe) => [recipe.id, recipe])); incoming.forEach((recipe) => byId.set(recipe.id || crypto.randomUUID(), { ...blank(), ...recipe, id: recipe.id || crypto.randomUUID() })); onRecipesChange([...byId.values()]) } catch { window.alert('That file is not a valid recipe pack.') } }
  return <div className="recipe-backdrop"><section className="recipe-dialog" aria-label="Visual recipes"><header><div><span>GLOBAL MASTER LIBRARY</span><h2>Visual recipes</h2><small>Attach a frozen project snapshot when a workflow is used.</small></div><button onClick={onClose}>×</button></header><div className="recipe-tools"><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search recipes…"/><select value={category} onChange={(event) => setCategory(event.target.value)}><option value="all">All categories</option>{[...new Set(recipes.map((recipe) => recipe.category))].map((entry) => <option key={entry}>{entry}</option>)}</select><button className={favorites ? 'active' : ''} onClick={() => setFavorites(!favorites)}>Favorites</button><button onClick={() => { const recipe = blank(); onRecipesChange([...recipes, recipe]); setSelectedId(recipe.id) }}>＋ Recipe</button><button onClick={exportPack}>Export pack</button><button onClick={() => fileRef.current?.click()}>Import pack</button><input ref={fileRef} hidden type="file" accept="application/json" onChange={(event) => void importPack(event.target.files?.[0])}/></div><div className="recipe-layout"><aside>{visible.map((recipe) => <button className={recipe.id === selectedId ? 'selected' : ''} key={recipe.id} onClick={() => setSelectedId(recipe.id)}>{recipe.thumbnail ? <img src={recipe.thumbnail} alt=""/> : <i>✦</i>}<span><strong>{recipe.title}</strong><small>{recipe.category} · {(recipe.usedByProjectIds || []).length} projects</small></span>{recipe.favorite && <b>★</b>}</button>)}{!visible.length && <p>No recipes found.</p>}</aside>{selected ? <main><div className="recipe-title"><input value={selected.title} onChange={(event) => update({ ...selected, title: event.target.value })}/><button className={selected.favorite ? 'active' : ''} onClick={() => update({ ...selected, favorite: !selected.favorite })}>★</button><button onClick={attach}>{project.recipeSnapshots?.some((recipe) => recipe.id === selected.id) ? 'Snapshot attached' : 'Attach to project'}</button><button onClick={() => { const variation = { ...selected, id: crypto.randomUUID(), title: `${selected.title} variation`, variationOf: selected.id, updatedAt: new Date().toISOString() }; onRecipesChange([...recipes, variation]); setSelectedId(variation.id) }}>Variation</button></div><div className="recipe-fields"><label>Category<input value={selected.category} onChange={(event) => update({ ...selected, category: event.target.value })}/></label><label>Thumbnail URL<input value={selected.thumbnail || ''} onChange={(event) => update({ ...selected, thumbnail: event.target.value || undefined })}/></label><label>Recommended apps<input value={selected.applications.join(', ')} onChange={(event) => update({ ...selected, applications: words(event.target.value) })}/></label><label>Tools<input value={selected.tools.join(', ')} onChange={(event) => update({ ...selected, tools: words(event.target.value) })}/></label><label>AI models<input value={selected.aiModels.join(', ')} onChange={(event) => update({ ...selected, aiModels: words(event.target.value) })}/></label></div><label>Problem<textarea value={selected.problem} onChange={(event) => update({ ...selected, problem: event.target.value })}/></label><label>Procedure<textarea value={selected.procedure} onChange={(event) => update({ ...selected, procedure: event.target.value })}/></label><footer>Used by: {selected.usedByProjectIds?.length ? selected.usedByProjectIds.join(', ') : 'No project snapshots yet'}<button className="danger" onClick={() => { onRecipesChange(recipes.filter((recipe) => recipe.id !== selected.id)); setSelectedId(null) }}>Delete</button></footer></main> : <main className="recipe-empty">Select or create a recipe.</main>}</div></section></div>
}

import { useEffect, useMemo, useRef } from 'react'
import type { ProjectModel } from '../model/project'
import { searchProject, type ProjectSearchKind } from './projectSearchModel'
export type { ProjectSearchKind } from './projectSearchModel'

type SearchProps = {
  project: ProjectModel
  query: string
  onQueryChange: (query: string) => void
  onNavigate: (kind: ProjectSearchKind, id: string, nodeId?: string) => void
  searchOriginTitle?: string
  onReturn?: () => void
}

export function ProjectSearch({ project, query, onQueryChange, onNavigate, searchOriginTitle, onReturn }: SearchProps) {
  const results = useMemo(() => searchProject(project, query), [project, query])
  const container = useRef<HTMLDivElement>(null), input = useRef<HTMLInputElement>(null)
  useEffect(() => {
    if (!query.trim()) return
    const outside = (event: PointerEvent) => { if (event.target instanceof Node && !container.current?.contains(event.target)) onQueryChange('') }
    window.addEventListener('pointerdown', outside, true)
    return () => window.removeEventListener('pointerdown', outside, true)
  }, [query, onQueryChange])
  const keys = (event: React.KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.preventDefault()
      event.stopPropagation()
      if (query.trim()) {
        onQueryChange('')
        input.current?.focus()
      } else if (onReturn) {
        onReturn()
      }
      return
    }
    const buttons = [...(container.current?.querySelectorAll<HTMLButtonElement>('.project-search-results button') || [])]
    if (!buttons.length) return
    const index = buttons.indexOf(document.activeElement as HTMLButtonElement)
    let next: number | undefined
    if (event.key === 'ArrowDown') next = Math.min(buttons.length - 1, index + 1)
    if (event.key === 'ArrowUp') { if (index <= 0) { event.preventDefault(); input.current?.focus(); return }; next = index - 1 }
    if (index >= 0 && event.key === 'Home') next = 0
    if (index >= 0 && event.key === 'End') next = buttons.length - 1
    if (next !== undefined) { event.preventDefault(); buttons[next].focus() }
  }
  return <div className={`project-search ${searchOriginTitle ? 'has-return' : ''}`} ref={container} onKeyDown={keys}>
    {searchOriginTitle && onReturn && (
      <button
        className="project-search-return"
        type="button"
        onClick={onReturn}
        title={`Return to ${searchOriginTitle} (Esc)`}
        aria-label={`Return to ${searchOriginTitle}`}
      >
        <span className="return-arrow" aria-hidden="true">↩</span>
        <span className="return-label">Return to <strong>{searchOriginTitle}</strong></span>
      </button>
    )}
    <input ref={input} value={query} onChange={(event) => onQueryChange(event.target.value)} placeholder="Search project…" aria-label="Search project" aria-describedby="project-search-scope" aria-controls={query.trim() ? 'project-search-results' : undefined} />
    <span className="project-search-scope" id="project-search-scope">This project</span>
    {query.trim() && <div className="project-search-results" id="project-search-results" role="region" aria-label="Project search results">
      <span className="sr-only" role="status">{results.length ? results.length + ' project matches' : 'No project matches'}</span>
      {results.length ? <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>{results.map((result) => <li key={result.key}><button type="button" onClick={() => onNavigate(result.kind, result.id, result.nodeId)}><strong>{result.title}</strong><small>{result.context}</small></button></li>)}</ul> : <p>No project matches.</p>}
    </div>}
  </div>
}

import type { ProjectModel } from '../model/project'
import { boardAncestors } from '../board/boardHierarchy'

export type ProjectSearchKind = 'board' | 'document' | 'worksheets' | 'recipes' | 'prompts' | 'references' | 'assets'
export type ProjectSearchResult = { key: string; kind: ProjectSearchKind; id: string; nodeId?: string; title: string; context: string }
export function searchProject(project: ProjectModel, query: string, limit = 30): ProjectSearchResult[] {
  const needle = query.trim().toLocaleLowerCase()
  if (!needle) return []
  const matches: ProjectSearchResult[] = [], includes = (value: unknown) => JSON.stringify(value ?? '').toLocaleLowerCase().includes(needle)
  const assets = new Map(project.assets.map((asset) => [asset.id, asset]))
  for (const board of project.boards) {
    const path = [...boardAncestors(project.boards, board.id), board].map((entry) => entry.title).join(' / ')
    if (includes(board.title)) matches.push({ key: 'board-' + board.id, kind: 'board', id: board.id, title: board.title, context: path })
    for (const node of board.nodes) {
      const asset = node.assetId ? assets.get(node.assetId) : undefined
      if (includes({ title: node.title, body: node.body, captured: node.captured, annotations: node.videoAnnotations, asset: asset && { name: asset.displayName, aliases: asset.aliases, tags: asset.tags } })) matches.push({ key: board.id + '-' + node.id, kind: 'board', id: board.id, nodeId: node.id, title: node.title || asset?.displayName || node.kind, context: path + ' · ' + node.kind })
    }
  }
  for (const document of project.documents) if (includes({ title: document.title, content: document.content })) matches.push({ key: 'document-' + document.id, kind: 'document', id: document.id, title: document.title, context: 'Document text' })
  for (const asset of project.assets) if (includes(asset)) matches.push({ key: 'asset-' + asset.id, kind: 'assets', id: asset.id, title: asset.displayName, context: asset.extension.toUpperCase() + ' · asset catalog' })
  for (const worksheet of project.worksheets || []) if (includes({ date: worksheet.date, notes: worksheet.notesHtml, tasks: worksheet.tasks })) matches.push({ key: 'worksheet-' + worksheet.date, kind: 'worksheets', id: worksheet.date, title: worksheet.date, context: 'Daily worksheet' })
  for (const recipe of project.recipeSnapshots || []) if (includes(recipe)) matches.push({ key: 'recipe-' + recipe.id, kind: 'recipes', id: recipe.id, title: recipe.title, context: 'Attached recipe' })
  for (const prompt of project.promptHistory || []) if (includes(prompt)) matches.push({ key: 'prompt-' + prompt.id, kind: 'prompts', id: prompt.id, title: prompt.subject || prompt.prompt.slice(0, 60) || 'Prompt draft', context: prompt.mode + ' · ' + prompt.targetModel })
  for (const library of project.referenceLibraries || []) if (includes(library)) matches.push({ key: 'library-' + library.id, kind: 'references', id: library.id, title: library.name, context: 'Reference library' })
  for (const crop of project.referenceCrops || []) if (includes(crop)) matches.push({ key: 'crop-' + crop.id, kind: 'references', id: crop.id, title: crop.title, context: 'Saved reference crop' })
  return matches.slice(0, Math.max(0, limit))
}

/// <reference lib="webworker" />
import { AutoProcessor, AutoTokenizer, CLIPTextModelWithProjection, CLIPVisionModelWithProjection, RawImage, env } from '@huggingface/transformers'

const MODEL_ID = 'Xenova/clip-vit-base-patch16'
const MODEL_REVISION = '342fdf2f67aded64d138ff074745fb4a5d2bba5f'

type Request =
  | { type: 'initialize'; preferGpu: boolean }
  | { type: 'embed-images'; items: Array<{ recordId: string; url: string }> }
  | { type: 'embed-text'; query: string }
  | { type: 'cancel' }

let processor: Awaited<ReturnType<typeof AutoProcessor.from_pretrained>> | null = null
let visionModel: Awaited<ReturnType<typeof CLIPVisionModelWithProjection.from_pretrained>> | null = null
let tokenizer: Awaited<ReturnType<typeof AutoTokenizer.from_pretrained>> | null = null
let textModel: Awaited<ReturnType<typeof CLIPTextModelWithProjection.from_pretrained>> | null = null
let cancelled = false
let device: 'webgpu' | 'wasm' = 'wasm'

env.allowRemoteModels = true
env.allowLocalModels = true

function emit(message: unknown) { self.postMessage(message) }

function normalize(input: Float32Array | number[]) {
  let magnitude = 0
  for (const value of input) magnitude += value * value
  magnitude = Math.sqrt(magnitude) || 1
  return Array.from(input, (value) => value / magnitude)
}

async function load(preferGpu: boolean) {
  if (processor && visionModel) return
  const requestedDevice: 'webgpu' | 'wasm' = preferGpu && 'gpu' in navigator ? 'webgpu' : 'wasm'
  const progress_callback = (progress: unknown) => emit({ type: 'model-progress', progress })
  processor = await AutoProcessor.from_pretrained(MODEL_ID, { revision: MODEL_REVISION, progress_callback })
  try {
    visionModel = await CLIPVisionModelWithProjection.from_pretrained(MODEL_ID, { revision: MODEL_REVISION, device: requestedDevice, dtype: 'q8', progress_callback })
    device = requestedDevice
  } catch (error) {
    if (requestedDevice === 'wasm') throw error
    emit({ type: 'fallback', reason: String(error) })
    visionModel = await CLIPVisionModelWithProjection.from_pretrained(MODEL_ID, { revision: MODEL_REVISION, device: 'wasm', dtype: 'q8', progress_callback })
    device = 'wasm'
  }
  emit({ type: 'ready', modelId: MODEL_ID, modelRevision: MODEL_REVISION, device })
}

async function loadText(preferGpu: boolean) {
  if (tokenizer && textModel) return
  const requestedDevice: 'webgpu' | 'wasm' = preferGpu && 'gpu' in navigator ? 'webgpu' : 'wasm'
  const progress_callback = (progress: unknown) => emit({ type: 'model-progress', progress })
  tokenizer = await AutoTokenizer.from_pretrained(MODEL_ID, { revision: MODEL_REVISION, progress_callback })
  try {
    textModel = await CLIPTextModelWithProjection.from_pretrained(MODEL_ID, { revision: MODEL_REVISION, device: requestedDevice, dtype: 'q8', progress_callback })
    device = requestedDevice
  } catch (error) {
    if (requestedDevice === 'wasm') throw error
    emit({ type: 'fallback', reason: String(error) })
    textModel = await CLIPTextModelWithProjection.from_pretrained(MODEL_ID, { revision: MODEL_REVISION, device: 'wasm', dtype: 'q8', progress_callback })
    device = 'wasm'
  }
}

self.onmessage = async (event: MessageEvent<Request>) => {
  const request = event.data
  if (request.type === 'cancel') { cancelled = true; return }
  try {
    if (request.type === 'initialize') { await load(request.preferGpu); return }
    if (request.type === 'embed-text') {
      await loadText(true)
      const inputs = tokenizer!([request.query], { padding: true, truncation: true })
      const output = await textModel!(inputs)
      emit({ type: 'text-complete', vector: normalize(output.text_embeds.data as Float32Array), modelId: MODEL_ID, modelRevision: MODEL_REVISION, device })
      return
    }
    if (request.type === 'embed-images') {
      cancelled = false
      await load(true)
      const embeddings: Array<{ recordId: string; vector: number[] }> = []
      for (let index = 0; index < request.items.length; index += 1) {
        if (cancelled) { emit({ type: 'cancelled', completed: embeddings.length }); return }
        const item = request.items[index]
        try {
          const image = await RawImage.read(item.url)
          const inputs = await processor!(image)
          const output = await visionModel!(inputs)
          embeddings.push({ recordId: item.recordId, vector: normalize(output.image_embeds.data as Float32Array) })
          emit({ type: 'item-progress', completed: index + 1, total: request.items.length, recordId: item.recordId })
        } catch (error) {
          emit({ type: 'item-error', recordId: item.recordId, error: String(error) })
        }
      }
      emit({ type: 'complete', embeddings, modelId: MODEL_ID, modelRevision: MODEL_REVISION, device })
    }
  } catch (error) {
    emit({ type: 'error', error: String(error) })
  }
}

