import { useState } from 'react'
import { useMemo } from 'react'
import { LayoutPlanPreview } from '../board/LayoutResearchPanel'
import { organizeSemanticClusters, semanticClusterLabel } from '../board/layoutResearch'
import type { BoardModel, ProjectAsset } from '../model/project'
import type { SemanticAnalysis } from '../storage/workspace'
import './SemanticClusterReview.css'

type Props = {
  board?: BoardModel
  analysis: SemanticAnalysis
  assets: ProjectAsset[]
  onApply: (clusters: Array<{ title: string; assetIds: string[] }>, target: 'groups' | 'columns') => void
  onClose: () => void
}

const assetId = (recordId: string) => recordId.startsWith('asset:') ? recordId.slice(6) : undefined

export function SemanticClusterReview({ board, analysis, assets, onApply, onClose }: Props) {
  const [target, setTarget] = useState<'groups' | 'columns'>('groups')
  const [clusters, setClusters] = useState(() => analysis.clusters.map((cluster, index) => ({ ...cluster, title: semanticClusterLabel(cluster.recordIds.map(assetId).filter((id): id is string => Boolean(id)), assets, index), selected: true })))
  const assetName = (recordId: string) => assets.find((asset) => asset.id === assetId(recordId))?.displayName || recordId.replace(/^asset:/, '')
  const selected = clusters.filter((cluster) => cluster.selected)
  const chosen = selected.map((cluster) => ({ title: cluster.title.trim() || 'Visual references', assetIds: cluster.recordIds.map(assetId).filter((id): id is string => Boolean(id)) }))
  const proposal = useMemo(() => board ? organizeSemanticClusters(board, chosen, target, assets) : null, [board, clusters, target, assets])
  return <div className="semantic-review-backdrop">
    <section className="semantic-review" aria-label="Semantic cluster review">
      <header><div><span>REVIEW BEFORE ORGANIZING</span><h2>Visual clusters</h2><p>{analysis.analyzedCount} images analyzed · {analysis.clusters.length} clusters · {analysis.nearDuplicates.length} near-duplicate candidates</p></div><button type="button" onClick={onClose}>×</button></header>
      <div className="semantic-review-body">
        <main>
          {!clusters.length && <div className="semantic-review-empty"><strong>No stable clusters found</strong><p>The current images may be intentionally diverse. Nothing has been changed.</p></div>}
          {clusters.map((cluster) => <article className={cluster.selected ? 'selected' : ''} key={cluster.id}>
            <label><input type="checkbox" checked={cluster.selected} onChange={(event) => setClusters((current) => current.map((entry) => entry.id === cluster.id ? { ...entry, selected: event.target.checked } : entry))}/><input value={cluster.title} aria-label="Cluster title" onChange={(event) => setClusters((current) => current.map((entry) => entry.id === cluster.id ? { ...entry, title: event.target.value } : entry))}/></label>
            <div><strong>{assetName(cluster.representativeRecordId)}</strong><small>{cluster.recordIds.length} members · average similarity {cluster.averageScore.toFixed(3)}</small></div>
            <ul>{cluster.recordIds.map((recordId) => <li key={recordId}>{assetName(recordId)}</li>)}</ul>
          </article>)}
        </main>
        <aside>{proposal && board && <section><h3>Layout preview</h3><LayoutPlanPreview before={board} after={proposal.board} /><p>{proposal.moved} references eligible. Existing dimensions are retained.</p>{proposal.warnings.map((warning) => <p key={warning}>{warning}</p>)}{selected.some((cluster) => cluster.recordIds.length > 12) && <p>Large cluster: consider smaller themed subgroups or an existing subboard before applying.</p>}</section>}<h3>Near-duplicate candidates</h3><p>These require both close pixels and close embeddings. Review only—no files will be removed.</p>{analysis.nearDuplicates.map((pair) => <div key={`${pair.leftRecordId}:${pair.rightRecordId}`}><strong>{assetName(pair.leftRecordId)}</strong><span>↔</span><strong>{assetName(pair.rightRecordId)}</strong><small>pixel distance {pair.perceptualDistance} · semantic {pair.embeddingScore.toFixed(3)}</small></div>)}{!analysis.nearDuplicates.length && <em>No near duplicates detected.</em>}</aside>
      </div>
      <footer><label>Organize selected clusters as <select value={target} onChange={(event) => setTarget(event.target.value as typeof target)}><option value="groups">Freeform groups</option><option value="columns">Columns</option></select></label><span>{selected.length} clusters selected</span><button type="button" onClick={onClose}>Cancel</button><button type="button" className="primary-button" disabled={!selected.length || Boolean(proposal && !proposal.moved)} onClick={() => onApply(selected.map((cluster) => ({ title: cluster.title.trim() || 'Visual cluster', assetIds: cluster.recordIds.map(assetId).filter((id): id is string => Boolean(id)) })), target)}>Apply to active board</button></footer>
    </section>
  </div>
}

import { convertFileSrc } from '@tauri-apps/api/core'
import { commitSemanticEmbeddings, listSemanticSources, prepareSemanticIndex, type SemanticIndexStatus } from '../storage/workspace'

export type SemanticIndexProgress = {
  phase: 'preparing' | 'loading-model' | 'embedding' | 'saving' | 'complete' | 'cancelled' | 'failed'
  completed: number
  total: number
  detail?: string
}

export class SemanticIndexer {
  private worker: Worker | null = null

  cancel() { this.worker?.postMessage({ type: 'cancel' }) }

  async run(projectId: string, workspaceRoot: string, onProgress: (progress: SemanticIndexProgress) => void): Promise<SemanticIndexStatus> {
    onProgress({ phase: 'preparing', completed: 0, total: 0 })
    const prepared = await prepareSemanticIndex(projectId)
    const sources = (await listSemanticSources(projectId)).filter((source) => source.active && source.embeddingState !== 'ready')
    if (!sources.length) { onProgress({ phase: 'complete', completed: prepared.indexedCount, total: prepared.sourceCount, detail: 'All current images already have local embeddings' }); return prepared }
    const items = sources.map((source) => ({
      recordId: source.recordId,
      url: /^[a-zA-Z]:[\\/]/.test(source.relativePath) ? convertFileSrc(source.relativePath) : convertFileSrc(`${workspaceRoot.replace(/[\\/]$/, '')}/${source.relativePath.replace(/^[\\/]/, '')}`),
    }))
    this.worker = new Worker(new URL('./semantic.worker.ts', import.meta.url), { type: 'module' })
    return new Promise<SemanticIndexStatus>((resolve, reject) => {
      const fail = (error: unknown) => {
        onProgress({ phase: 'failed', completed: 0, total: items.length, detail: String(error) })
        this.worker?.terminate(); this.worker = null; reject(error)
      }
      this.worker!.onerror = (event) => fail(event.message)
      this.worker!.onmessage = (event: MessageEvent<Record<string, unknown>>) => {
        const message = event.data
        if (message.type === 'model-progress') onProgress({ phase: 'loading-model', completed: 0, total: items.length })
        else if (message.type === 'fallback') onProgress({ phase: 'loading-model', completed: 0, total: items.length, detail: 'GPU unavailable; using CPU' })
        else if (message.type === 'item-progress') onProgress({ phase: 'embedding', completed: Number(message.completed), total: Number(message.total) })
        else if (message.type === 'item-error') onProgress({ phase: 'embedding', completed: 0, total: items.length, detail: `Skipped ${String(message.recordId)}` })
        else if (message.type === 'cancelled') {
          onProgress({ phase: 'cancelled', completed: Number(message.completed), total: items.length })
          this.worker?.terminate(); this.worker = null; reject(new Error('Semantic indexing cancelled'))
        }
        else if (message.type === 'error') fail(message.error)
        else if (message.type === 'complete') {
          const embeddings = message.embeddings as Array<{ recordId: string; vector: number[] }>
          const dimension = embeddings[0]?.vector.length || 512
          onProgress({ phase: 'saving', completed: embeddings.length, total: items.length })
          void commitSemanticEmbeddings(projectId, String(message.modelId), String(message.modelRevision), dimension, embeddings)
            .then((status) => { onProgress({ phase: 'complete', completed: embeddings.length, total: items.length }); this.worker?.terminate(); this.worker = null; resolve(status) })
            .catch(fail)
        }
      }
      this.worker!.postMessage({ type: 'embed-images', items })
    })
  }
}

import { findSimilarSemantic, searchSemanticIndex, type SemanticSearchResult } from '../storage/workspace'

export class SemanticSearchClient {
  private worker: Worker | null = null
  private pending: { resolve: (vector: number[]) => void; reject: (error: Error) => void; onStatus: (status: string) => void } | null = null

  private ensureWorker() {
    if (this.worker) return this.worker
    this.worker = new Worker(new URL('./semantic.worker.ts', import.meta.url), { type: 'module' })
    this.worker.onmessage = (event: MessageEvent<Record<string, unknown>>) => {
      if (!this.pending) return
      if (event.data.type === 'model-progress') this.pending.onStatus('Loading local text model…')
      else if (event.data.type === 'fallback') this.pending.onStatus('GPU unavailable; searching on CPU…')
      else if (event.data.type === 'text-complete') {
        const pending = this.pending; this.pending = null
        pending.resolve(event.data.vector as number[])
      } else if (event.data.type === 'error') {
        const pending = this.pending; this.pending = null
        pending.reject(new Error(String(event.data.error)))
      }
    }
    this.worker.onerror = (event) => {
      const pending = this.pending; this.pending = null
      pending?.reject(new Error(event.message))
    }
    return this.worker
  }

  async search(projectId: string, query: string, onStatus: (status: string) => void): Promise<SemanticSearchResult[]> {
    if (this.pending) throw new Error('A semantic search is already running')
    const vector = await new Promise<number[]>((resolve, reject) => {
      this.pending = { resolve, reject, onStatus }
      this.ensureWorker().postMessage({ type: 'embed-text', query })
    })
    onStatus('Comparing project references…')
    return searchSemanticIndex(projectId, vector)
  }

  findSimilar(projectId: string, assetId: string) {
    return findSimilarSemantic(projectId, `asset:${assetId}`)
  }

  dispose() { this.worker?.terminate(); this.worker = null; this.pending = null }
}

import { useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react'
import type { BoardModel, ProjectModel, ShapeType } from '../model/project'
import { createSelectorStore, type SelectorStore, type StateUpdate } from './selectorStore'

export type ToolState = {
  interactionTool: 'select' | 'connect' | 'draw' | 'pen' | 'node' | 'type' | 'pencil' | 'erase'
  viewportTool: 'select' | 'hand' | 'zoom'
  shapeKind: ShapeType
  eraserSize: number
}
export type SelectionState = {
  selectedIds: string[]
  selectedConnectorId: string | null
  selectedVectorPoint: { nodeId: string; index: number } | null
  selectedVectorAnchorIndexes: number[]
  selectedVectorSegmentIndexes: number[]
}
export const createToolStore = () => createSelectorStore<ToolState>({ interactionTool: 'select', viewportTool: 'select', shapeKind: 'rectangle', eraserSize: 24 })
export const createSelectionStore = (ids: string[]) => createSelectorStore<SelectionState>({ selectedIds: ids, selectedConnectorId: null, selectedVectorPoint: null, selectedVectorAnchorIndexes: [], selectedVectorSegmentIndexes: [] })
export const createDocumentStore = (project: ProjectModel) => createSelectorStore({ project, activeDocumentId: 'project-brief', activeBoardId: 'master-reference-board' })

export function useStoreField<T, K extends keyof T>(store: SelectorStore<T>, key: K): [T[K], (update: StateUpdate<T[K]>) => void] {
  const slice = useMemo(() => store.select(state => state[key], (a, b) => Object.is(a, b) || Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((value, index) => Object.is(value, b[index]))), [store, key])
  const value = useSyncExternalStore(slice.subscribe, slice.getSnapshot, slice.getSnapshot)
  const set = useMemo(() => (update: StateUpdate<T[K]>) => store.field(key, update), [store, key])
  return [value, set]
}
/** A new selection owner on each board; no previous-board publication window.
 * Remembered IDs are validated against the destination's current model. */
export function useBoardSelectionStore(session: string, board: BoardModel, remembered: readonly string[]) {
  return useMemo(() => createSelectionStore(remembered.filter(id => board.nodes.some(node => node.id === id))), [session])
}
export function useDocumentController(initial: () => ProjectModel) {
  const [store] = useState(() => createDocumentStore(initial()))
  return store
}

/** A mounted input listener stays stable, but always reads the committed
 * controller revision. Capturing the initial board/index causes repeated
 * membership publications after a board edit or switch. */
export function useControllerEvent<Args extends unknown[]>(callback: (...args: Args) => void) {
  const latest = useRef(callback)
  useLayoutEffect(() => { latest.current = callback })
  return useMemo(() => (...args: Args) => latest.current(...args), [])
}

/** No serialization or temporary strings. Immutable shared branches stop the
 * comparison immediately. Models here are acyclic JSON records, not DOM/media. */
export function modelEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true
  if (!a || !b || typeof a !== 'object' || typeof b !== 'object') return false
  if (Array.isArray(a) !== Array.isArray(b)) return false
  const left = a as Record<string, unknown>, right = b as Record<string, unknown>
  const keys = Object.keys(left)
  return keys.length === Object.keys(right).length && keys.every(key => Object.hasOwn(right, key) && modelEqual(left[key], right[key]))
}

export type StateUpdate<T> = T | ((previous: T) => T)

/** Instance-scoped, synchronous immutable state. Selectors notify only on a
 * changed slice; unchanged content retains identity for paint/history caches. */
export function createSelectorStore<T>(initial: T) {
  let state = initial, revision = 0
  const listeners = new Set<() => void>()
  const getSnapshot = () => state
  const subscribe = (listener: () => void) => { listeners.add(listener); return () => { listeners.delete(listener) } }
  const set = (update: StateUpdate<T>) => {
    const next = typeof update === 'function' ? (update as (previous: T) => T)(state) : update
    if (Object.is(next, state)) return
    state = next; revision++
    for (const listener of [...listeners]) listener()
  }
  const field = <K extends keyof T>(key: K, update: StateUpdate<T[K]>) => set(previous => {
    const next = typeof update === 'function' ? (update as (value: T[K]) => T[K])(previous[key]) : update
    return Object.is(next, previous[key]) ? previous : { ...previous, [key]: next }
  })
  const select = <S>(selector: (value: T) => S, equal: (a: S, b: S) => boolean = Object.is) => {
    let selected = selector(state)
    return {
      getSnapshot: () => { const next = selector(state); if (!equal(next, selected)) selected = next; return selected },
      subscribe: (listener: () => void) => subscribe(() => {
        const next = selector(state)
        if (!equal(next, selected)) { selected = next; listener() }
      }),
    }
  }
  return { getSnapshot, subscribe, set, field, select, get revision() { return revision } }
}
