const CURATED_FONT_FAMILIES = [
  'Inter', 'Source Serif 4', 'Iowan Old Style', 'Georgia', 'Garamond',
  'Palatino Linotype', 'Arial', 'Calibri', 'Cambria', 'Courier New',
]

export type FontCatalog = {
  families: readonly string[]
  source: 'system-catalog' | 'unverified'
}

export type FontFamilyOption = {
  value: string
  label: string
  description: string
  status: 'default' | 'listed' | 'unlisted' | 'unverified' | 'stack' | 'generic'
}

export const UNVERIFIED_FONT_CATALOG: FontCatalog = {
  families: CURATED_FONT_FAMILIES,
  source: 'unverified',
}

let cachedCatalog: FontCatalog | null = null
let pending: Promise<FontCatalog> | null = null

/** The native command currently enumerates catalog names, not resolved faces. */
export function normalizeFontCatalog(families: readonly string[]): FontCatalog {
  const unique = new Map<string, string>()
  for (const family of families) {
    const trimmed = family.trim()
    if (trimmed && !unique.has(trimmed.toLowerCase())) unique.set(trimmed.toLowerCase(), trimmed)
  }
  const normalized = [...unique.values()].sort((a, b) => a.localeCompare(b))
  // An empty response can also mean catalog discovery failed. Do not assert that
  // every font is unavailable, or promote the curated list to installed fonts.
  return normalized.length ? { families: normalized, source: 'system-catalog' } : UNVERIFIED_FONT_CATALOG
}

/** Preserve the exact authored value; menu labels never rewrite document marks. */
export function fontFamilyOptions(catalog: FontCatalog, authoredFamily = ''): FontFamilyOption[] {
  const listedFamilies = new Set(catalog.families.map(family => family.toLowerCase()))
  const defaults: FontFamilyOption = {
    value: '', label: 'Default (paragraph style)', status: 'default',
    description: 'Uses the paragraph font styling. No font family override is saved.',
  }
  const describe = (value: string): FontFamilyOption => {
    if (value.includes(',')) return {
      value, label: `${value} (Font stack)`, status: 'stack',
      description: 'Uses this ordered font stack. An available family or browser fallback is used.',
    }
    const canonical = value.trim().replace(/^(['"])(.*)\1$/, '$2').toLowerCase()
    if (['serif', 'sans-serif', 'monospace', 'cursive', 'fantasy', 'system-ui', 'ui-serif', 'ui-sans-serif', 'ui-monospace', 'ui-rounded', 'math', 'emoji', 'fangsong'].includes(canonical)) return {
      value, label: `${value} (Generic family)`, status: 'generic',
      description: 'Uses a font chosen by the browser for this generic family.',
    }
    const listed = catalog.source === 'system-catalog' && listedFamilies.has(canonical)
    if (listed) return {
      value, label: value, status: 'listed',
      description: 'Listed in this device’s font catalog. The rendered face can vary with weight, style and character coverage.',
    }
    if (catalog.source === 'system-catalog') return {
      value, label: `${value} (Not listed)`, status: 'unlisted',
      description: 'Not listed in this device’s font catalog. Another font may be used; the saved font choice is preserved.',
    }
    return {
      value, label: `${value} (Unverified)`, status: 'unverified',
      description: 'Font availability has not been checked on this device.',
    }
  }
  const options = [defaults]
  if (authoredFamily) options.push(describe(authoredFamily))
  const activeCanonical = authoredFamily.trim().replace(/^(['"])(.*)\1$/, '$2').toLowerCase()
  for (const family of catalog.families) {
    if (family.toLowerCase() !== activeCanonical) options.push(describe(family))
  }
  return options
}

/** Discover catalog choices without asserting that a family or face was rendered. */
export async function discoverFontCatalog() {
  if (cachedCatalog) return cachedCatalog
  if (!pending) {
    pending = invoke<string[]>('list_system_fonts')
      .then((families) => {
        cachedCatalog = normalizeFontCatalog(families)
        return cachedCatalog
      })
      .catch(() => {
        cachedCatalog = UNVERIFIED_FONT_CATALOG
        return cachedCatalog
      })
      .finally(() => { pending = null })
  }
  return pending
}

import { useEffect, useRef, useSyncExternalStore } from 'react'
import { useModalFocus } from './useModalFocus'

type Request = { id: number; title: string; message: string; confirmLabel: string; cancelLabel?: string; resolve: (accepted: boolean) => void }
const queue: Request[] = []
const listeners = new Set<() => void>()
let nextId = 1
const notify = () => listeners.forEach((listener) => listener())
const subscribe = (listener: () => void) => { listeners.add(listener); return () => { listeners.delete(listener) } }
const snapshot = () => queue[0] || null

/** Bounded, serial requests: a second error never replaces a pending safety decision. */
export function appConfirm(message: string, options: { title?: string; confirmLabel?: string } = {}): Promise<boolean> {
  if (queue.length >= 16) return Promise.resolve(false)
  return new Promise((resolve) => { queue.push({ id: nextId++, title: options.title || 'Confirm action', message, confirmLabel: options.confirmLabel || 'Continue', cancelLabel: 'Cancel', resolve }); notify() })
}
export function appAlert(message: string, title = 'Action could not finish'): void {
  if (queue.length >= 16) return
  queue.push({ id: nextId++, title, message, confirmLabel: 'Close', resolve: () => undefined }); notify()
}
function finish(id: number, accepted: boolean) {
  if (queue[0]?.id !== id) return
  const request = queue.shift()!
  notify(); request.resolve(accepted)
}

export function AppDialogHost({ onActiveChange }: { onActiveChange: (active: boolean) => void }) {
  const request = useSyncExternalStore(subscribe, snapshot, () => null)
  useEffect(() => { onActiveChange(Boolean(request)) }, [request, onActiveChange])
  return request ? <DecisionDialog key={request.id} request={request} /> : null
}
function DecisionDialog({ request }: { request: Request }) {
  const dialog = useRef<HTMLDivElement>(null), cancel = useRef<HTMLButtonElement>(null)
  useModalFocus(dialog, cancel)
  return <div className="text-entry-backdrop app-decision-backdrop" onPointerDown={(event) => { event.stopPropagation() }}>
    <div ref={dialog} className="text-entry-dialog app-decision-dialog" role={request.cancelLabel ? 'alertdialog' : 'dialog'} aria-modal="true" aria-labelledby={`decision-title-${request.id}`} aria-describedby={`decision-message-${request.id}`} tabIndex={-1} onKeyDown={(event) => { event.stopPropagation(); if (event.key === 'Escape') { event.preventDefault(); finish(request.id, false) } }}>
      <header><span>ART EQUATION</span><button type="button" aria-label="Close dialog" onClick={() => finish(request.id, false)}>×</button></header>
      <h2 id={`decision-title-${request.id}`}>{request.title}</h2>
      <p id={`decision-message-${request.id}`} className="app-decision-message">{request.message}</p>
      <footer>{request.cancelLabel && <button ref={cancel} type="button" className="quiet-button" onClick={() => finish(request.id, false)}>{request.cancelLabel}</button>}<button ref={request.cancelLabel ? undefined : cancel} type="button" className="primary-button" onClick={() => finish(request.id, true)}>{request.confirmLabel}</button></footer>
    </div>
  </div>
}

import { useEffect, useRef, type ReactNode } from 'react'

/** Board actions share one compact trigger in both wide and Split layouts. */
export function BoardActionsMenu({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLDetailsElement>(null)
  const close = (focus = false) => {
    if (!ref.current?.open) return
    ref.current.open = false
    if (focus) ref.current.querySelector('summary')?.focus()
  }
  useEffect(() => {
    const outside = (event: PointerEvent) => { if (!ref.current?.contains(event.target as Node)) close() }
    const escape = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && ref.current?.open) { event.preventDefault(); event.stopPropagation(); close(true) }
    }
    document.addEventListener('pointerdown', outside)
    document.addEventListener('keydown', escape, true)
    return () => { document.removeEventListener('pointerdown', outside); document.removeEventListener('keydown', escape, true) }
  }, [])
  return <details ref={ref} className="filmstrip-actions">
    <summary onKeyDown={event => {
      if (event.key !== 'ArrowDown' || !ref.current) return
      event.preventDefault(); ref.current.open = true
      ref.current.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus()
    }}>Board actions ▾</summary>
    <div role="group" aria-label="Board actions" onClick={event => { if ((event.target as Element).closest('button:not(:disabled)')) close() }} onKeyDown={event => {
      if (!['ArrowDown','ArrowUp','Home','End'].includes(event.key)) return
      const buttons = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')]
      if (!buttons.length) return
      event.preventDefault(); event.stopPropagation()
      const index = buttons.indexOf(document.activeElement as HTMLButtonElement)
      buttons[event.key === 'Home' ? 0 : event.key === 'End' ? buttons.length - 1 : (index + (event.key === 'ArrowDown' ? 1 : buttons.length - 1)) % buttons.length]?.focus()
    }}>{children}</div>
  </details>
}

