import { useEffect, useState } from 'react'
import { invoke, isTauri } from '@tauri-apps/api/core'
import { recordMetric } from '../diagnostics/performance'
type Result = { requested: string; used: string; width: number; height: number; rgbaBase64: string; exactPixels: boolean; backendSucceeded: boolean; fallbackReason?: string; details: { device?: string; workers?: number; setupMs?: number; transferComputeReadbackMs?: number; adapterBackend?: string; backendFallbacks?: string[]; buffersCreated?: boolean; retainedBufferBytes?: number; luidMatched?: boolean; maxChannelDelta?: number; hardwareBackendAvailable?: boolean }; backendEndToEndMs: number; isolatedRoundTripMs: number }
export function ExperimentalPreparationSettings() {
  const [session, setSession] = useState<{ phase: string; ready: boolean; warmup?: { warmupMs: number } }>()
  useEffect(() => {
    if (!isTauri()) return
    let stopped = false, timer: ReturnType<typeof setTimeout> | undefined
    const refresh = async () => {
      try { const result = await invoke<NonNullable<typeof session>>('inspect_preparation_session'); if (stopped) return; setSession(result); if (result.phase === 'warming') timer = setTimeout(() => void refresh(), 500); else recordMetric('engine.compute-session', { phase: result.phase, warmupMs: result.warmup?.warmupMs || 0 }) }
      catch { if (!stopped) setSession({ phase: 'unavailable', ready: false }) }
    }
    void refresh()
    return () => { stopped = true; clearTimeout(timer) }
  }, [])
  const [busy, setBusy] = useState(false), [rows, setRows] = useState<Array<{ label: string; result?: Omit<Result, 'rgbaBase64'>; error?: string }>>([])
  const [message, setMessage] = useState('')
  const compare = async () => {
    if (busy) return
    setBusy(true); setRows([]); setMessage('Comparing a small image preparation job…')
    const width = 512, height = 513, bytes = new Uint8Array(width * height * 4)
    for (let index = 0; index < bytes.length; index++) bytes[index] = index % 251
    let binary = ''
    for (let offset = 0; offset < bytes.length; offset += 16384) binary += String.fromCharCode(...bytes.subarray(offset, offset + 16384))
    const rgbaBase64 = btoa(binary)
    let baseline: string | undefined
    try {
      for (const [backend, workers] of [['cpu', 1], ['cpu', 2], ['cpu', 4], ['wgpu', undefined], ['dx12', undefined], ['vulkan', undefined], ['opencl', undefined], ['cuda-dx12', undefined], ['cuda-dx12-upload', undefined]] as const) {
        const label = backend === 'cpu' ? `CPU · ${workers} workers requested` : backend === 'wgpu' ? 'Automatic native compute' : `${backend.toUpperCase()} compute`
        try {
          const result = await invoke<Result>('prepare_image_experimental', { request: { width, height, rgbaBase64, backend, workers } })
          baseline ??= result.rgbaBase64
          if (!result.exactPixels || result.rgbaBase64 !== baseline || result.width !== 256 || result.height !== 257) throw new Error('Prepared pixels differ from the CPU reference')
          const { rgbaBase64: _pixels, ...summary } = result
          setRows(previous => [...previous, { label, result: summary }])
          recordMetric('engine.experimental-preparation', { requested: backend, used: result.used, workers: result.details.workers || 0, backendSucceeded: result.backendSucceeded, backendMs: result.backendEndToEndMs, roundTripMs: result.isolatedRoundTripMs, setupMs: result.details.setupMs || 0, transferComputeReadbackMs: result.details.transferComputeReadbackMs || 0 })
        } catch (error) { setRows(previous => [...previous, { label, error: String(error).slice(0, 500) }]); recordMetric('engine.experimental-preparation-error', { requested: backend }) }
      }
      setMessage('Comparison finished. Canvas rendering and project files are unchanged.')
    } finally { setBusy(false) }
  }
  const compareJpeg = async () => {
    if (busy) return
    setBusy(true); setMessage('Comparing bounded JPEG decoding…')
    try {
      const canvas = document.createElement('canvas'); canvas.width = 513; canvas.height = 257
      const context = canvas.getContext('2d'); if (!context) throw new Error('JPEG fixture creation unavailable')
      const image = context.createImageData(513, 257)
      for (let p = 0; p < image.data.length; p += 4) { const v = (p / 4) % 251; image.data[p] = v; image.data[p + 1] = v; image.data[p + 2] = v; image.data[p + 3] = 255 }
      context.putImageData(image, 0, 0)
      const jpegBase64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1]
      const result = await invoke<Result>('prepare_jpeg_experimental', { request: { jpegBase64 } })
      const { rgbaBase64: _pixels, ...summary } = result
      setRows(previous => [...previous.filter(row => row.label !== 'nvJPEG decode'), { label: 'nvJPEG decode', result: summary }])
      recordMetric('engine.experimental-jpeg', { used: result.used, backendMs: result.backendEndToEndMs, maxChannelDelta: result.details.maxChannelDelta || 0, hardwareBackendAvailable: result.details.hardwareBackendAvailable || false })
      setMessage('JPEG comparison finished. Decoder rounding and fallback are reported separately.')
    } catch (error) { setMessage(String(error).slice(0, 500)) } finally { setBusy(false) }
  }
  return <section><h3>Experimental image preparation</h3><p>Compare CPU workers, automatic native compute, DX12, Vulkan, OpenCL and CUDA/DX12 sharing on the same small, alpha-aware image reduction. Each accelerator must match the CPU pixels.</p>
    <small>Compute session: {session?.phase || 'unavailable'}{session?.warmup ? ` · startup preparation ${session.warmup.warmupMs.toFixed(1)} ms` : ''}</small>
    <button type="button" disabled={!isTauri() || busy || !session?.ready} onClick={() => void compare()}>{busy ? 'Comparing…' : 'Compare image preparation'}</button>
    <button type="button" disabled={!isTauri() || busy || !session?.ready} onClick={() => void compareJpeg()}>Compare JPEG decoding</button>
    <small>Devices and shaders prepare in the background at launch and stay ready in an isolated helper. Startup cost is shown separately; each job includes transfers and helper communication. This does not qualify canvas or 4K performance.</small>
    {rows.map(row => <div key={row.label}><strong>{row.label}</strong>{row.result ? <><p>{row.result.used} · {row.result.details.device || 'CPU fallback'}{row.result.details.workers ? ` · ${row.result.details.workers} active workers` : ''} · {row.result.isolatedRoundTripMs.toFixed(1)} ms total</p><small>Backend preparation {row.result.backendEndToEndMs.toFixed(1)} ms{row.result.details.setupMs !== undefined ? ` · setup ${row.result.details.setupMs.toFixed(1)} ms · copy/compute/readback ${row.result.details.transferComputeReadbackMs?.toFixed(1)} ms` : ''} · {row.result.exactPixels ? 'exact pixels' : `JPEG rounding delta ${row.result.details.maxChannelDelta}/255`}{row.result.details.buffersCreated !== undefined ? ` · ${row.result.details.buffersCreated ? 'buffers allocated' : 'buffers reused'}` : ''}</small>{row.result.details.backendFallbacks?.map(reason => <p key={reason}>{reason}</p>)}{row.result.fallbackReason && <p>{row.result.fallbackReason}</p>}</> : <p>{row.error}</p>}</div>)}
    <small role="status">{message}</small></section>
}

import { useEffect, useState, useRef } from 'react'
import { invoke, isTauri } from '@tauri-apps/api/core'
import { hydrateLaunchPreferences, launchLanguages, saveLaunchPreferences, useLaunchPreferences } from './launchPreferences'
import { launchText, accelerationText } from './launchTranslations'
import { recordMetric } from '../diagnostics/performance'
type Adapter = { name: string; vendor: string; backend: string; deviceType: string; software: boolean; driver: string; gpuUploadHeap?: { supported?: boolean } }
type Capabilities = { hardware: { adapters: Adapter[]; recommendedNativeBackend: string; discoveryMs: number; nvidiaLibraries?: { runtimePackaged: boolean; nvjpegPackaged: boolean } } }
let inspection: Promise<Capabilities> | undefined
export function LaunchHardwareSettings({ onInteract, compact, onHardwareStatus }: { onInteract?: () => void; compact?: boolean; onHardwareStatus?: (status: 'checking'|'ready'|'failed'|'preview') => void }) {
  const preferences = useLaunchPreferences(), t = launchText[preferences.language], a = accelerationText[preferences.language]
  const [capabilities, setCapabilities] = useState<Capabilities>()
  const warmRevision = useRef(0)
  const warmTasks = useRef<Promise<void>>(Promise.resolve())
  const [warm, setWarm] = useState<'warming' | 'ready' | 'failed'>()
  const [failed, setFailed] = useState(false), [saveFailed, setSaveFailed] = useState(false)
  useEffect(()=>{onHardwareStatus?.(!isTauri()?'preview':failed?'failed':capabilities?'ready':'checking')},[capabilities,failed,onHardwareStatus])
  useEffect(() => {
    let live = true
    void hydrateLaunchPreferences().catch(() => { if (live) setSaveFailed(true) })
    if (isTauri()) {
      inspection ||= invoke<Capabilities>('inspect_engine_capabilities')
      void inspection.then(result => {
        if (!live) return
        setCapabilities(result)
        recordMetric('engine.launch-hardware', { adapters: result.hardware.adapters.length, recommended: result.hardware.recommendedNativeBackend, discoveryMs: result.hardware.discoveryMs })
      }).catch(() => { if (live) setFailed(true) })
    }
    return () => { live = false }
  }, [])
  const update = (p: typeof preferences) => {
    onInteract?.(); setSaveFailed(false)
    const changed = p.nativeBackend !== preferences.nativeBackend || p.preparationAcceleration !== preferences.preparationAcceleration
    const revision = changed ? ++warmRevision.current : warmRevision.current
    if (changed && isTauri()) setWarm('warming')
    void saveLaunchPreferences(p).then(async () => {
      if (!changed || !isTauri()) return
      warmTasks.current = warmTasks.current.catch(() => undefined).then(async () => {
      if (revision !== warmRevision.current) return
      try {
        const result = await invoke<{ used: string; fallbackReason?: string; totalMs: number }>('prepare_image_experimental', { request: { width: 2, height: 2, rgbaBase64: '/////////////////////w==', backend: 'wgpu' } })
        const fallback = !!result.fallbackReason || (p.preparationAcceleration !== 'standard' && result.used !== p.preparationAcceleration)
        recordMetric('engine.launch-acceleration-warmup', { used: result.used, totalMs: result.totalMs, fallback })
        if (revision === warmRevision.current) setWarm(fallback ? 'failed' : 'ready')
      } catch { if (revision === warmRevision.current) setWarm('failed') }
      })
    }).catch(() => { setSaveFailed(true); if (revision === warmRevision.current) setWarm('failed') })
  }
  const adapters = capabilities?.hardware.adapters || []
  const available = (backend: string) => !isTauri() || adapters.some(a => a.backend.toLowerCase() === backend && !a.software)
  const cudaAvailable = isTauri() && capabilities?.hardware.nvidiaLibraries?.runtimePackaged && adapters.some(a => a.vendor === 'NVIDIA' && a.backend === 'Dx12' && !a.software)
  const uploadAvailable = cudaAvailable && adapters.some(a => a.vendor === 'NVIDIA' && a.backend === 'Dx12' && !a.software && a.gpuUploadHeap?.supported)
  return <section className="launch-hardware-settings" lang={preferences.language} aria-label={t.hardware}>
    {!compact && <label>{t.language}<select aria-label={t.language} value={preferences.language} onChange={e => update({ ...preferences, language: e.target.value as typeof preferences.language })}>
      {launchLanguages.map(l => <option key={l.id} value={l.id} lang={l.id}>{l.label}</option>)}
    </select></label>}
    <h2>{t.hardware}</h2>
    <div className="launch-hardware-status" role="status">
      {!isTauri() ? t.browser : failed ? t.failed : !capabilities ? t.checking : <>
        <ul aria-label={t.adapters}>{adapters.map((a, i) => <li key={`${a.backend}-${i}`}><strong>{a.name}</strong> · {a.vendor} · {a.backend} · {a.deviceType}</li>)}</ul>
        <p>{t.recommended}: <strong>{capabilities.hardware.recommendedNativeBackend.toUpperCase()}</strong></p>
      </>}
    </div>
    <label>{t.backend}<select aria-label={t.backend} value={preferences.nativeBackend} onChange={e => update({ ...preferences, nativeBackend: e.target.value as typeof preferences.nativeBackend, preparationAcceleration: e.target.value === 'vulkan' ? 'standard' : preferences.preparationAcceleration })}>
      <option value="auto">{t.auto}</option>
      <option value="dx12" disabled={!available('dx12')}>DirectX 12</option>
      <option value="vulkan" disabled={!available('vulkan')}>Vulkan</option>
    </select></label>
    <p>{t.scope}</p><p>{t.fallback}</p>
    <details><summary>{t.advanced}</summary>
      <label>{a.label}<select aria-label={a.label} value={preferences.preparationAcceleration} onChange={e => update({ ...preferences, preparationAcceleration: e.target.value as typeof preferences.preparationAcceleration, nativeBackend: e.target.value === 'standard' ? preferences.nativeBackend : 'dx12' })}>
        <option value="standard">{a.standard}</option>
        <option value="cuda-dx12" disabled={!cudaAvailable}>{a.cuda}</option>
        <option value="cuda-dx12-upload" disabled={!uploadAvailable}>{a.upload}</option>
      </select></label>
      <p>{a.retained}</p>{warm && <p role="status">{warm === 'warming' ? a.warming : warm === 'ready' ? a.ready : a.unavailable}</p>}
      <p>{capabilities?.hardware.nvidiaLibraries?.nvjpegPackaged ? a.jpeg : a.missing}</p>
      <p>{t.amd}</p>
    </details>
    <small>{t.translation}</small>
    {saveFailed && <p role="alert">{t.saveError}</p>}
  </section>
}

import { useSyncExternalStore } from 'react'
import { invoke, isTauri } from '@tauri-apps/api/core'
export function readLaunchTheme(): 'navy'|'dark'|'light'|undefined {try{const value=localStorage.getItem('art-equation:ui-theme:v1');return value==='navy'||value==='dark'||value==='light'?value:undefined}catch{return undefined}}
export function saveLaunchTheme(value:'navy'|'dark'|'light'){try{localStorage.setItem('art-equation:ui-theme:v1',value)}catch{/* Workspace disk settings remain the native persistence path. */}}
export type LaunchLanguage = 'en' | 'zh-CN' | 'ja' | 'pt-BR' | 'pt-PT' | 'es'
export type LaunchPreferences = { language: LaunchLanguage; nativeBackend: 'auto' | 'dx12' | 'vulkan'; preparationAcceleration: 'standard' | 'cuda-dx12' | 'cuda-dx12-upload' }
export const launchLanguages: { id: LaunchLanguage; label: string }[] = [
  { id: 'en', label: 'English' }, { id: 'zh-CN', label: '简体中文（普通话）' },
  { id: 'ja', label: '日本語' }, { id: 'pt-BR', label: 'Português (Brasil)' },
  { id: 'pt-PT', label: 'Português (Portugal)' }, { id: 'es', label: 'Español' },
]
const key = 'art-equation:launch-preferences:v1'
const valid = (p: unknown): p is LaunchPreferences => !!p && typeof p === 'object'
  && launchLanguages.some(l => l.id === (p as LaunchPreferences).language)
  && ['auto', 'dx12', 'vulkan'].includes((p as LaunchPreferences).nativeBackend)
  && ['standard', 'cuda-dx12', 'cuda-dx12-upload'].includes((p as LaunchPreferences).preparationAcceleration || 'standard')
let current: LaunchPreferences = { language: 'en', nativeBackend: 'auto', preparationAcceleration: 'standard' }
try { const saved: unknown = JSON.parse(localStorage.getItem(key) || 'null'); if (valid(saved)) current = { ...saved, preparationAcceleration: saved.preparationAcceleration || 'standard' } } catch { /* defaults */ }
const listeners = new Set<() => void>()
let revision = 0
let loaded: Promise<void> | undefined
let writes: Promise<unknown> = Promise.resolve()
function publish(p: LaunchPreferences) { current = { ...p, preparationAcceleration: p.preparationAcceleration || 'standard' }; localStorage.setItem(key, JSON.stringify(p)); for (const listener of listeners) listener() }
export function hydrateLaunchPreferences() {
  return loaded ||= (isTauri() ? (() => {
    const started = revision
    return invoke<LaunchPreferences>('get_launch_preferences').then(p => { if (valid(p) && started === revision) publish(p) })
  })() : Promise.resolve())
}
export function saveLaunchPreferences(p: LaunchPreferences) {
  if (!valid(p)) return Promise.reject(new Error('Invalid launch preferences'))
  revision++; publish(p)
  // Serialize writes so rapid language/backend changes cannot save out of order.
  const result = writes.catch(() => undefined).then(() => isTauri() ? invoke('set_launch_preferences', { preferences: p }) : undefined)
  writes = result
  return result
}
export function useLaunchPreferences() {
  return useSyncExternalStore(listener => { listeners.add(listener); return () => { listeners.delete(listener) } }, () => current)
}

export type LaunchLayout = 'milinotes'|'graphing'|'advanced-split'
export function readLaunchLayout():LaunchLayout {try{const value=localStorage.getItem('art-equation:launch-layout:v1');if(value==='graphing'||value==='advanced-split')return value}catch{}return 'milinotes'}
export function saveLaunchLayout(value:LaunchLayout){try{localStorage.setItem('art-equation:launch-layout:v1',value)}catch{}}

export type CanvasUiPersonality = 'classical' | 'milanote'
export function readCanvasUiPersonality(): CanvasUiPersonality {
  try {
    const value = localStorage.getItem('art-equation:canvas-ui-personality:v1')
    if (value === 'classical' || value === 'milanote') return value
  } catch {}
  return 'classical'
}
export function saveCanvasUiPersonality(value: CanvasUiPersonality) {
  try {
    localStorage.setItem('art-equation:canvas-ui-personality:v1', value)
  } catch {}
}

