      const backward = event.shiftKey || event.key === 'ArrowUp'
      if (event.key === 'Tab' && event.target !== controls[backward ? 0 : controls.length - 1]) return
      const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : index + (backward ? -1 : 1)
